void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

int initialize_data(long num_offsets, int num_keys, long alignment_boundary,
                    long **offsets, int **keys, record **records) {

    // Allocate memory for offsets and keys with the specified alignment
