#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

#define CHUNK_SIZE 4096
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2

typedef struct {
    char *filename;
    int is_stdin;
} FileDescriptor;

typedef struct {
    pthread_mutex_t lock;
    FILE *log_file;
    time_t start_time;
} LogContext;

void log_message(LogContext *log_ctx, const char *message, int level) {
    pthread_mutex_lock(&log_ctx->lock);
    if (level == LOG_LEVEL_INFO || level == LOG_LEVEL_ERROR) {
        fprintf(log_ctx->log_file, "[%s] %s\n", level == LOG_LEVEL_INFO ? "INFO" : "ERROR", message);
        fflush(log_ctx->log_file);
    }
    pthread_mutex_unlock(&log_ctx->lock);
}

void usage(const char *prog_name) {
    printf("Usage: %s [-l log_file] [-r regex_pattern] <file1> [<file2> ...]\n", prog_name);
}

int process_line(const char *line, const char *pattern) {
    if (!pattern) return 1; // No pattern to filter
    regex_t regex;
    int reti = regcomp(&regex, pattern, REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        return 0;
    }
    reti = regexec(&regex, line, 0, NULL, 0);
    regfree(&regex);
    return !reti; // Return true if pattern matches
}

void process_file(FileDescriptor *file_desc, const char *pattern, LogContext *log_ctx) {
    FILE *fp = file_desc->is_stdin ? stdin : fopen(file_desc->filename, "r");
    if (!fp) {
        log_message(log_ctx, strerror(errno), LOG_LEVEL_ERROR);
        return;
    }

    char buffer[CHUNK_SIZE];
    size_t bytes_read;
    long lines_processed = 0;

    while ((bytes_read = fread(buffer, 1, CHUNK_SIZE, fp)) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                buffer[i] = '\0';
                if (process_line(buffer, pattern)) {
                    lines_processed++;
                }
                i = -1; // Start from the beginning of the next line
            }
        }
    }

    fclose(fp);
    log_message(log_ctx, "File processed successfully", LOG_LEVEL_INFO);
}

void *file_worker(void *arg) {
    FileDescriptor *file_desc = (FileDescriptor *)arg;
    LogContext *log_ctx = (LogContext *)malloc(sizeof(LogContext));
    pthread_mutex_init(&log_ctx->lock, NULL);

    log_message(log_ctx, "Processing file", LOG_LEVEL_INFO);
    process_file(file_desc, "pattern", log_ctx); // Replace "pattern" with actual pattern if needed

    pthread_mutex_destroy(&log_ctx->lock);
    free(log_ctx);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    LogContext log_ctx;
    pthread_mutex_init(&log_ctx.lock, NULL);
    log_ctx.log_file = fopen("program.log", "a");
    time(&(log_ctx.start_time));

    FILE *fp_in;
    char buffer[BUFSIZ];
    int opt;

    while ((opt = getopt(argc, argv, "l:r:")) != -1) {
        switch (opt) {
            case 'l':
                log_ctx.log_file = fopen(optarg, "a");
                break;
            case 'r':
                // Handle regex pattern
                break;
            default:
                usage(argv[0]);
                return EXIT_FAILURE;
        }
    }

    pthread_t threads[MAX_FILES];
    FileDescriptor files[MAX_FILES];
    int file_count = 0;

    if (optind == argc) {
        files[file_count++] = (FileDescriptor){.filename = NULL, .is_stdin = 1};
    } else {
        for (; optind < argc; ++optind) {
            files[file_count++] = (FileDescriptor){.filename = argv[optind], .is_stdin = 0};
        }
    }

    for (int i = 0; i < file_count; ++i) {
        pthread_create(&threads[i], NULL, file_worker, &files[i]);
    }

    for (int i = 0; i < file_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(log_ctx.log_file);
    pthread_mutex_destroy(&log_ctx.lock);

    return EXIT_SUCCESS;
}
```

This program includes handling of command line arguments, logging, regex filtering, and multi-threaded processing. Adjust the `MAX_FILES` definition as needed for your environment.']

