    char *rules;
    int timeout;
    char *log_file;
} Config;

void log_message(const Config *config, const char *message) {
    FILE *logfile = fopen(config->log_file, "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", message);
        fclose(logfile);
    }
}

void signal_handler(int signum) {
    exit(EXIT_FAILURE);
}

int parse_and_transform(const char *input, const char *rules, char **output, size_t *size) {
    // Implement rule-based parsing and transformation logic here.
    // This is a stub. You need to replace it with actual logic.

    // For demonstration purposes, simply copy the input to output
    *size = strlen(input);
    *output = malloc(*size + 1);
    if (*output == NULL) {
        return -1;
    }
    memcpy(*output, input, *size);
    (*output)[*size] = '\0';

    return 0; // Return 0 on success
}

void process_file(const Config *config) {
    FILE *input_file = fopen(config->input_file, "rb");
    if (!input_file) {
        log_message(config, "Error opening input file.");
        exit(EXIT_FAILURE);
    }

    pthread_t timer_thread;
    int timer_active = 0;

    void start_timer() {
        timer_active = 1;
        alarm(config->timeout);
    }

    void stop_timer() {
        if (timer_active) {
            alarm(0); // Cancel the timeout
            timer_active = 0;
        }
    }

    void *timeout_handler(void *arg) {
        Config *cfg = (Config *)arg;
        log_message(cfg, "Processing timeout.");
        exit(EXIT_FAILURE);
    }

    pthread_create(&timer_thread, NULL, timeout_handler, (void *)config);

    fseek(input_file, 0L, SEEK_END);
    long file_size = ftell(input_file);
    rewind(input_file);

    char buffer[BUFFER_SIZE];
    char *output_data = NULL;
    size_t output_size = 0;

    start_timer();

    while (!feof(input_file)) {
        size_t bytes_read = fread(buffer, 1, BUFFER_SIZE, input_file);
        if (ferror(input_file) || bytes_read == 0) break;

        int result = parse_and_transform(buffer, config->rules, &output_data, &output_size);
        if (result != 0) {
            log_message(config, "Error during parsing and transformation.");
            exit(EXIT_FAILURE);
        }

        // Append the transformed data to output_file here.
    }

    stop_timer();
    pthread_cancel(timer_thread);

    FILE *output_file = fopen(config->output_file, "wb");
    if (!output_file || fwrite(output_data, 1, output_size, output_file) != output_size) {
        log_message(config, "Error writing to output file.");
        free(output_data);
        exit(EXIT_FAILURE);
    }

    fclose(input_file);
    fclose(output_file);

    free(output_data);
}

int main(int argc, char *argv[]) {
    if (argc < 5 || argc > 6) {
        fprintf(stderr, "Usage: %s <input file> <output file> <rules> [<timeout>] <log file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config config = {
        .input_file = argv[1],
        .output_file = argv[2],
        .rules = argv[3],
        .timeout = (argc == 6) ? atoi(argv[4]) : 10, // Default timeout of 10 seconds
        .log_file = argc == 6 ? argv[5] : "process.log"
    };

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    process_file(&config);

    return EXIT_SUCCESS;
}
