#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dns_sd.h>
#include <arpa/inet.h>

#define MAX_THREADS 4
#define BUFFER_SIZE 1024

typedef struct {
    char **fileNames;
    int numFiles;
    pthread_mutex_t mutex;
} Args;

typedef struct {
    u_char *ip_address;
    size_t ip_length;
    int error_code;
} DnsResult;

void resolve_dns(const char *hostname, DnsResult *result) {
    DNSServiceRef sdref = NULL;
    DnsServiceError err = DNSServiceResolve(0, 0, 0, hostname, "_http", "_tcp", NULL, &sdref, NULL);

    if (err == kDNSServiceErr_NoError) {
        struct sockaddr_in addr;
        size_t addr_len = sizeof(addr);
        int status = DNSServiceGetAddrInfo(sdref, 0, NULL, AF_INET, SOCK_STREAM, IPPROTO_TCP,
                                           (void *)&addr, &addr_len, NULL, NULL);

        if (status == kDNSServiceErr_NoError) {
            result->ip_address = malloc(addr_len);
            memcpy(result->ip_address, &addr.sin_addr, addr_len);
            result->ip_length = addr_len;
            result->error_code = 0;
        } else {
            free(result->ip_address);
            result->error_code = -1;
        }
    } else {
        result->error_code = err;
    }

    DNSServiceRefDeallocate(sdref);
}

void *process_file(void *arg) {
    Args *args = (Args *)arg;
    for (int i = 0; i < args->numFiles; ++i) {
        FILE *file = fopen(args->fileNames[i], "r");
        if (!file) continue;

        char *line = NULL;
        size_t len = 0;
        while (getline(&line, &len, file) != -1) {
            char *fields[MAX_THREADS];
            int field_count = 0;
            char *token = strtok(line, " ");
            while (token) {
                fields[field_count++] = token;
                token = strtok(NULL, " ");
            }

            if (field_count > 2 && isdigit(fields[field_count - 1][0]) &&
                isdigit(fields[field_count - 2][0])) {
                double num1 = atof(fields[field_count - 1]);
                double num2 = atof(fields[field_count - 2]);
                double average = (num1 + num2) / 2.0;

                for (int j = 0; j < field_count - 2; ++j) {
                    printf("%s,", fields[j]);
                }
                printf("%.2f\n", average);
            } else {
                for (int j = 0; j < field_count - 1; ++j) {
                    printf("%s,", fields[j]);
                }
                printf("\n");
            }
        }

        free(line);
        fclose(file);
    }

    pthread_mutex_lock(&args->mutex);
    --args->numFiles;
    pthread_mutex_unlock(&args->mutex);

    return NULL;
}

void log_message(const char *message) {
    // Simulated logging function
    printf("Log: %s\n", message);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> <file2> ... <fileN>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Args args;
    args.fileNames = &argv[1];
    args.numFiles = argc - 1;
    pthread_mutex_init(&args.mutex, NULL);

    pthread_t threads[MAX_THREADS];
    int active_threads = 0;

    while (args.numFiles > 0) {
        if (active_threads < MAX_THREADS && args.numFiles > 0) {
            Args *arg_copy = malloc(sizeof(Args));
            memcpy(arg_copy, &args, sizeof(Args));

            pthread_create(&threads[active_threads], NULL, process_file, arg_copy);
            active_threads++;
        }

        for (int i = 0; i < active_threads; ++i) {
            if (pthread_tryjoin_np(threads[i], NULL) == 0) {
                free((Args *)pthread_getspecific(pthread_getspecific));
                threads[i] = threads[active_threads - 1];
                --active_threads;
            }
        }
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&args.mutex);

    DnsResult dns_result;
    resolve_dns("example.com", &dns_result);
    if (dns_result.error_code == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr *)dns_result.ip_address));
        free(dns_result.ip_address);
    } else {
        log_message("DNS resolution failed");
    }

    return EXIT_SUCCESS;
}
