#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_ENTRY_SIZE 1024
#define BATCH_SIZE 100

typedef struct {
    char *message;
    time_t timestamp;
    char correlation_id[36];
    char user_id[64];
    char request_type[64];
} LogEntry;

typedef struct {
    LogEntry *entries[BATCH_SIZE];
    int count;
    pthread_mutex_t lock;
} LogBatch;

void get_timestamp(time_t *timestamp) {
    time(timestamp);
}

void generate_correlation_id(char *id, size_t len) {
    // Simple example of generating a correlation ID
    snprintf(id, len, "%ld", (long)time(NULL));  // Replace with a proper unique ID generator in production
}

LogBatch log_batch = {{0}, 0, PTHREAD_MUTEX_INITIALIZER};

void add_log_entry(const char *user_id, const char *request_type, const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&log_batch.lock);

    if (log_batch.count >= BATCH_SIZE) {
        // Submit batch and clear it
        submit_and_clear_log_batch();
    }

    LogEntry *entry = malloc(sizeof(LogEntry));
    char message[MAX_LOG_ENTRY_SIZE];

    entry->timestamp = time(NULL);
    get_timestamp(&(entry->timestamp));

    generate_correlation_id(entry->correlation_id, sizeof(entry->correlation_id));
    strncpy(entry->user_id, user_id, sizeof(entry->user_id) - 1);
    strncpy(entry->request_type, request_type, sizeof(entry->request_type) - 1);

    vsnprintf(message, MAX_LOG_ENTRY_SIZE, format, args);
    entry->message = strdup(message);

    log_batch.entries[log_batch.count++] = entry;

    va_end(args);
    pthread_mutex_unlock(&log_batch.lock);
}

void submit_and_clear_log_batch() {
    // Simulate submission to external logging service
    for (int i = 0; i < log_batch.count; ++i) {
        LogEntry *entry = log_batch.entries[i];
        printf("[%ld] [%s] [User: %s, Type: %s]: %s\n",
               entry->timestamp, entry->correlation_id,
               entry->user_id, entry->request_type, entry->message);

        free(entry->message);
        free(entry);
    }

    log_batch.count = 0;
}

void flush_log_batch() {
    pthread_mutex_lock(&log_batch.lock);
    submit_and_clear_log_batch();
    pthread_mutex_unlock(&log_batch.lock);
