# Set up logging
logging.basicConfig(filename='deployment.log', level=logging.INFO,
                    format='%(asctime)s %(levelname)s: %(message)s')

def load_config_from_vault(env):
    """Load environment-specific configuration from a secure vault."""
    try:
        # Simulate loading config from a vault service
        command = f"vault read -field=app_config secret/{env}"
        result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        logging.error(f"Failed to load config for {env}: {e}")
        raise

def apply_configuration(env, config):
    """Apply the configuration to the application's config files."""
    try:
        # Simulate applying configuration
        with open(f"{env}_config.txt", "w") as file:
            file.write(config)
        logging.info(f"Configuration applied for {env}")
    except Exception as e:
        logging.error(f"Failed to apply config for {env}: {e}")
        raise

def execute_shell_command(command, retries=3):
    """Execute shell command with retry logic."""
    attempt = 0
    while attempt < retries:
        try:
            result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
            logging.info(f"Command succeeded: {command}")
            return result.stdout.strip()
        except subprocess.CalledProcessError as e:
            attempt += 1
            logging.warning(f"Command failed (attempt {attempt}): {e}. Retrying...")
            if attempt == retries:
                logging.error(f"Command ultimately failed after {retries} attempts: {command}")
                raise

def deploy_to_environment(env):
    """Deploy application to a specific environment."""
    try:
        config = load_config_from_vault(env)
        apply_configuration(env, config)

        # Example deployment command
        execute_shell_command(f"kubectl apply -f {env}/deployment.yaml")

        logging.info(f"Deployment successful for {env}")
    except Exception as e:
        logging.error(f"Deployment failed for {env}: {e}. Initiating rollback.")
        rollback(env)
        raise

def rollback(env):
    """Rollback changes in case of failure."""
    try:
        execute_shell_command(f"kubectl rollout undo deployment/{env}-app")
        logging.info(f"Rollback successful for {env}")
    except Exception as e:
        logging.error(f"Rollback failed for {env}: {e}")

def main():
    environments = ['development', 'staging', 'production']

    for env in environments:
        try:
            deploy_to_environment(env)
        except Exception as e:
            logging.error(f"Deployment process aborted: {e}")
            break

if __name__ == "__main__":
    start_time = datetime.now()
    main()
    end_time = datetime.now()
    elapsed_time = (end_time - start_time).total_seconds()

    if elapsed_time > 300:  # Example latency threshold in seconds
        logging.warning("Deployment exceeded the specified latency threshold.")
```

This script is a comprehensive deployment automation tool that handles configuration loading, application deployment, command execution with retries, and rollback in case of failures. It logs each step for auditing purposes and includes network failure handling logic through retry mechanisms.']

