    if (!ctx) {
        log_operation("Error: Unable to create cipher context.");
        fclose(config_file);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        // Parse operation type and algorithm from the configuration
        char operation_type[10], algorithm_name[50];
        if (sscanf(line, "%s %s", operation_type, algorithm_name) != 2) {
            log_operation("Error: Invalid configuration line.");
            continue;
        }

        const EVP_CIPHER *cipher = NULL;
        if (!strcmp(algorithm_name, "AES-256-CBC")) {
            cipher = EVP_aes_256_cbc();
        } else if (!strcmp(algorithm_name, "DES-EDE3-CBC")) {
            cipher = EVP_des_ede3_cbc();
        } else {
            log_operation("Error: Unsupported algorithm.");
            continue;
        }

        if (cipher == NULL) {
            log_operation("Error: Algorithm initialization failed.");
            continue;
        }

        if (!strcmp(operation_type, "encrypt") || !strcmp(operation_type, "decrypt")) {
            int final_block_len = 0;
            unsigned char iv[EVP_MAX_IV_LENGTH];
            unsigned char *buffer = malloc(EVP_CIPHER_block_size(cipher));
            if (!buffer) {
                log_operation("Error: Memory allocation failed.");
                continue;
            }

            // Initialize cipher context
            if (!strcmp(operation_type, "encrypt")) {
                EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
            } else {
                EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv);
            }

            size_t out_len = 0;
            int success = 1;

            // Simulate reading data for encryption/decryption
            unsigned char *input_data = (unsigned char *)"Sample input data";
            size_t input_len = strlen((char *)input_data);

            if (!strcmp(operation_type, "encrypt")) {
                EVP_EncryptUpdate(ctx, buffer, &out_len, input_data, input_len);
                EVP_EncryptFinal_ex(ctx, buffer + out_len, &final_block_len);
            } else {
                EVP_DecryptUpdate(ctx, buffer, &out_len, input_data, input_len);
                EVP_DecryptFinal_ex(ctx, buffer + out_len, &final_block_len);
            }

            success = (out_len == -1) ? 0 : 1;

            log_operation(success ? "Operation successful." : "Operation failed.");

            free(buffer);
        }
    }

