#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    int value;
    pthread_mutex_t lock;
} Semaphore;

typedef struct {
    Semaphore *semaphores;
    size_t count;
    size_t capacity;
    pthread_mutex_t collection_lock;
} SemaphoreCollection;

SemaphoreCollection* create_semaphore_collection(size_t initial_capacity) {
    SemaphoreCollection *collection = (SemaphoreCollection *)malloc(sizeof(SemaphoreCollection));
    if (!collection) return NULL;

    collection->semaphores = (Semaphore *)calloc(initial_capacity, sizeof(Semaphore));
    if (!collection->semaphores) {
        free(collection);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        pthread_mutex_init(&collection->semaphores[i].lock, NULL);
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->collection_lock, NULL);

    return collection;
}

void log_operation(const char *operation, int semaphore_id) {
    printf("Operation: %s on Semaphore ID: %d\n", operation, semaphore_id);
}

int acquire_semaphore(SemaphoreCollection *collection, int id) {
    pthread_mutex_lock(&collection->semaphores[id].lock);

    if (collection->semaphores[id].value > 0) {
        collection->semaphores[id].value--;
        log_operation("Acquire", id);
        pthread_mutex_unlock(&collection->semaphores[id].lock);
        return 0;
    }

    pthread_mutex_unlock(&collection->semaphores[id].lock);
    log_operation("Wait (Failed)", id);
    return -1; // Semaphore is unavailable
}

int release_semaphore(SemaphoreCollection *collection, int id) {
    pthread_mutex_lock(&collection->semaphores[id].lock);

    collection->semaphores[id].value++;
    log_operation("Release", id);

    pthread_mutex_unlock(&collection->semaphores[id].lock);
    return 0;
}

int delete_semaphore(SemaphoreCollection *collection, int id) {
    pthread_mutex_lock(&collection->collection_lock);

    if (id < 0 || id >= collection->count) {
        pthread_mutex_unlock(&collection->collection_lock);
        log_operation("Delete Failed", id);
        return -1; // Invalid ID
    }

    pthread_mutex_destroy(&collection->semaphores[id].lock);
    memmove(&collection->semaphores[id], &collection->semaphores[id + 1],
            (collection->count - id - 1) * sizeof(Semaphore));
    collection->count--;

    if ((collection->capacity > INITIAL_SIZE && collection->count < collection->capacity / 2)) {
        Semaphore *new_semaphores = (Semaphore *)realloc(collection->semaphores,
                (collection->capacity / 2) * sizeof(Semaphore));
        if (new_semaphores) {
            collection->semaphores = new_semaphores;
            collection->capacity /= 2;
        }
    }

    pthread_mutex_unlock(&collection->collection_lock);
    log_operation("Delete", id);
    return 0;
}

void resize_semaphore_collection(SemaphoreCollection *collection, size_t new_capacity) {
    pthread_mutex_lock(&collection->collection_lock);

    Semaphore *new_semaphores = (Semaphore *)realloc(collection->semaphores,
            new_capacity * sizeof(Semaphore));
    if (!new_semaphores && new_capacity > collection->capacity) {
        pthread_mutex_unlock(&collection->collection_lock);
        log_operation("Resize Failed", -1);
        return;
    }

    for (size_t i = collection->count; i < new_capacity; ++i) {
        pthread_mutex_init(&new_semaphores[i].lock, NULL);
    }

    collection->semaphores = new_semaphores;
    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->collection_lock);
}

void destroy_semaphore_collection(SemaphoreCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        pthread_mutex_destroy(&collection->semaphores[i].lock);
    }
    free(collection->semaphores);
    pthread_mutex_destroy(&collection->collection_lock);
    free(collection);
}

int main() {
    SemaphoreCollection *collection = create_semaphore_collection(INITIAL_SIZE);

    if (!collection) return EXIT_FAILURE;

    for (int i = 0; i < INITIAL_SIZE; ++i) {
        collection->semaphores[i].value = 1;
    }
    collection->count = INITIAL_SIZE;

    acquire_semaphore(collection, 2);
    release_semaphore(collection, 2);
    delete_semaphore(collection, 2);

    destroy_semaphore_collection(collection);
    return EXIT_SUCCESS;
}
```

This C code provides a robust mechanism for managing semaphores within a collection. It includes functions to create, acquire, release, and delete semaphores while ensuring thread safety using mutex locks. The collection dynamically resizes based on load, logs operations for auditing, and handles memory management efficiently.']

