using System;
using System.IO;
using System.Threading;
using System.Xml;
using System.Xml.XPath;

public class XmlDirManager
{
    public static void ParseXmlAndCreateDir(string xmlString, string targetElementName, string baseDirectoryPath, int timeoutMilliseconds)
    {
        if (string.IsNullOrEmpty(xmlString) || string.IsNullOrEmpty(targetElementName) || string.IsNullOrEmpty(baseDirectoryPath))
            throw new ArgumentNullException("Input parameters cannot be null or empty.");

        XmlDocument xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.LoadXml(xmlString);
        }
        catch (Exception ex)
        {
            throw new ArgumentException("Invalid XML format.", ex);
        }

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        bool foundElement = false;

        using (AutoResetEvent autoResetEvent = new AutoResetEvent(false))
        {
            ThreadPool.QueueUserWorkItem(_ =>
            {
                try
                {
                    XPathNodeIterator nodes = navigator.Select(targetElementName);
                    if (nodes.Count == 0)
                        throw new FileNotFoundException($"No elements found with the name '{targetElementName}'.");

                    if (nodes.MoveNext() && nodes.Current.MoveToNext())
                        throw new InvalidOperationException($"Multiple elements found with the name '{targetElementName}'.");

                    foundElement = true;
                    autoResetEvent.Set();
                }
                catch
                {
                    // Ignore exceptions here, they will be re-thrown after the timeout.
                }
            });

            if (!autoResetEvent.WaitOne(timeoutMilliseconds))
                throw new TimeoutException($"Timeout of {timeoutMilliseconds}ms exceeded while searching for element '{targetElementName}'.");

            if (!foundElement)
                throw new FileNotFoundException($"No elements found with the name '{targetElementName}'.");
        }

        XPathNavigator navigatorForText = xmlDoc.CreateNavigator();
        string targetDirName = navigatorForText.SelectSingleNode(targetElementName)?.Value.Trim();

        if (string.IsNullOrEmpty(targetDirName))
            throw new InvalidOperationException("Target element text is empty or null.");

        string fullPath;
        do
        {
            fullPath = Path.Combine(baseDirectoryPath, targetDirName);
            if (Directory.Exists(fullPath))
                targetDirName += "_" + DateTime.Now.Ticks.ToString();
        } while (!CreateUniqueDirectory(fullPath));

        SetEnvironmentVariable("TARGET_DIR", fullPath);
    }

    private static bool CreateUniqueDirectory(string path)
    {
        try
        {
            Directory.CreateDirectory(path);
            return true;
        }
        catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
        {
            Console.WriteLine($"Failed to create directory: {ex.Message}");
            return false;
        }
    }

    private static void SetEnvironmentVariable(string variableName, string value)
    {
        Environment.SetEnvironmentVariable(variableName, value);
    }
}
