<?php

class UserManager {
    private $db;
    private $logger;

    public function __construct($dbConnection) {
        $this->db = $dbConnection;
        $this->logger = new Logger();
    }

    public function handleRequest($_REQUEST) {
        try {
            $subAction = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : 'create';
            $id = isset($_REQUEST['id']) ? (int)$_REQUEST['id'] : null;

            switch ($subAction) {
                case 'delete':
                    return $this->deleteUser($id);
                case 'update':
                    return $this->updateUser($_REQUEST, $id);
                default:
                    return $this->createUser($_REQUEST);
            }
        } catch (Exception $e) {
            $this->logger->logError($e->getMessage());
            return json_encode(['error' => $e->getMessage()]);
        }
    }

    private function validateRequest(array $request, $isUpdate = false) {
        if (!isset($request['name'], $request['email'], $request['password'])) {
            throw new Exception('Name, email, and password are required.');
        }

        if ($isUpdate && (!isset($request['confirm_password']) || $request['password'] !== $request['confirm_password'])) {
            throw new Exception('Passwords do not match for update.');
        }

        if (!filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
            throw new Exception('Invalid email format.');
        }
    }

    private function isEmailUnique($email, $id = null) {
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM users WHERE email = ?" . ($id ? " AND id != ?" : ""));
        $stmt->bind_param('s' . ($id ? 'i' : ''), $email, $id);
        $stmt->execute();
        $stmt->bind_result($count);
        $stmt->fetch();

        return $count === 0;
    }

    private function createUser(array $request) {
        $this->validateRequest($request);

        if (!$this->isEmailUnique($request['email'])) {
            throw new Exception('Email already exists.');
        }

        $stmt = $this->db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
        $hashedPassword = password_hash($request['password'], PASSWORD_BCRYPT);
        $stmt->bind_param('sss', $request['name'], $request['email'], $hashedPassword);

        if (!$stmt->execute()) {
            throw new Exception('Failed to create user.');
        }

        $this->logger->logInfo("User created: {$request['email']}");
        return json_encode(['success' => 'User created successfully.']);
    }

    private function updateUser(array $request, $id) {
        $this->validateRequest($request, true);

        if (!$this->isEmailUnique($request['email'], $id)) {
            throw new Exception('Email already exists.');
        }

        $stmt = $this->db->prepare("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?");
        $hashedPassword = password_hash($request['password'], PASSWORD_BCRYPT);
        $stmt->bind_param('sssi', $request['name'], $request['email'], $hashedPassword, $id);

        if (!$stmt->execute()) {
            throw new Exception('Failed to update user.');
        }

        $this->logger->logInfo("User updated: {$request['email']}");
        return json_encode(['success' => 'User updated successfully.']);
    }

    private function deleteUser($id) {
        if ($id === null) {
            throw new Exception('ID is required for deletion.');
        }

        $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
        $stmt->bind_param('i', $id);

        if (!$stmt->execute()) {
            throw new Exception('Failed to delete user.');
        }

        $this->logger->logInfo("User deleted: ID {$id}");
        return json_encode(['success' => 'User deleted successfully.']);
    }
}

class Logger {
    public function logError($message) {
        error_log("[ERROR] " . date('Y-m-d H:i:s') . ": " . $message);
    }

    public function logInfo($message) {
        error_log("[INFO] " . date('Y-m-d H:i:s') . ": " . message);
    }
}

// Usage example:
// Assuming $db is a valid database connection
$userManager = new UserManager($db);
$response = $userManager->handleRequest($_REQUEST);
echo $response;
