    private async Task<HashSet<string>> GetValidElementIdentifiersAsync(string sectionId)
    {
        string cacheKey = $"ValidElements:{sectionId}";
        var validElements = (HashSet<string>?)await _cache.GetAsync(cacheKey);

        if (!validElements.HasValue)
        {
            validElements = new HashSet<string>(await _database.GetElementIdentifiers(sectionId));
            await _cache.SetAsync(cacheKey, validElements, new DistributedCacheEntryOptions
            {
