public class ThemeManager {

    private static final Logger logger = Logger.getLogger(ThemeManager.class.getName());
    private static final String DEFAULT_THEME_DIR = "/default/theme/dir";
    private static final ConcurrentHashMap<String, Bitmap> themeCache = new ConcurrentHashMap<>();
    private static final Object lock = new Object();

    public ThemeManager() {
        initializeLogger();
    }

    private void initializeLogger() {
        try {
            FileHandler fileHandler = new FileHandler("ThemeManager.log", true);
            fileHandler.setFormatter(new SimpleFormatter());
            logger.addHandler(fileHandler);
        } catch (IOException e) {
            System.err.println("Failed to set up logger: " + e.getMessage());
        }
    }

    public MoSTState loadMoSTStateFromFile(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                logger.info("Successfully loaded MoSTState from " + filePath);
                return (MoSTState) obj;
            }
            logger.warning("File does not contain a valid MoSTState: " + filePath);
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Error loading MoSTState from file: " + e.getMessage());
        }
        return null;
    }

    public boolean cacheThemeBitmap(String themeId, Bitmap bitmap) {
        if (bitmap == null) {
            themeCache.remove(themeId);
            return false;
        }
        themeCache.put(themeId, bitmap);
        logger.info("Cached theme bitmap for ID: " + themeId);
        return true;
    }

    public Bitmap getThemeBitmap(String themeId) {
        return themeCache.getOrDefault(themeId, null);
    }

    public void validateAndSetDefaultThemeDirectory() {
        if (!checkThemeDirectoryExists(DEFAULT_THEME_DIR)) {
            logger.warning("Default theme directory missing. Setting to default: " + DEFAULT_THEME_DIR);
            setDefaultThemeDirectory(DEFAULT_THEME_DIR);
        }
    }

