["```javascript
const fs = require('fs').promises;
const path = require('path');

// Simple cache implementation
const fileCache = new Map();

async function readFilesWithExtension(directory, extensions) {
    try {
        const files = await fs.readdir(directory);

        // Filter files based on the specified extensions
        const filteredFiles = files.filter(file => 
            extensions.some(ext => path.extname(file).toLowerCase() === `.${ext.toLowerCase()}`)
        );

        const tasks = filteredFiles.map(async file => {
            try {
                const filePath = path.join(directory, file);

                // Check cache first
                if (fileCache.has(filePath)) {
                    return { fileName: file, contentLength: String(fileCache.get(filePath).length) };
                }

                // Read the file content asynchronously
                const content = await fs.readFile(filePath);

                // Update cache with new content length
                fileCache.set(filePath, content);

                return { fileName: file, contentLength: String(content.length) };

            } catch (error) {
                console.error(`Error reading file ${file}:`, error.message);
                return null;  // or handle differently if needed
            }
        });

        const results = await Promise.all(tasks);

        // Filter out null results from errors
        return results.filter(result => result !== null);

    } catch (error) {
        console.error(`Error reading directory ${directory}:`, error.message);
        throw new Error('Failed to read files.');
    }
}

module.exports = { readFilesWithExtension };
```

