import requests
import logging

# Define constants for feature names
FEATURES = ["Battery Life", "Camera Quality", "Display Resolution", "Processor Speed"]
CACHE_SIZE = 100

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def get_feature_metadata():
    # Simulate external data source retrieval with retry for handling latency and inconsistencies.
    try:
        response = requests.get("https://api.example.com/feature-metadata")
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        logging.error(f"Error fetching feature metadata: {e}")
        return {}

def process_reviews(reviews):
    # Initialize data structure to store results
    result = {feature.lower(): {'count': 0, 'positive_feedback': 0.0, 'user_mentions': set()} for feature in FEATURES}

    # Compile regex patterns for feature mentions, case-insensitive and ignoring punctuation
    patterns = {re.compile(re.escape(feature), re.IGNORECASE): feature.lower() for feature in FEATURES}

    # Caching frequently accessed features to improve performance
    cache = {}

    def is_positive_feedback(review):
        positive_words = ["good", "great", "excellent"]
        return any(word in review.lower() for word in positive_words)

    # Process each review
    for user_id, content in reviews:
        logging.info(f"Processing review from user {user_id}")

        # Check cache first
        if content in cache:
            matched_features = cache[content]
        else:
            matched_features = set()
            for pattern, feature_key in patterns.items():
                if pattern.search(content):
                    matched_features.add(feature_key)

            # Update cache (simple FIFO policy)
            if len(cache) >= CACHE_SIZE:
                cache.pop(next(iter(cache)))
            cache[content] = matched_features

        # Update results based on matches
        for feature_key in matched_features:
            result[feature_key]['count'] += 1
            result[feature_key]['user_mentions'].add(user_id)
            if is_positive_feedback(content):
                result[feature_key]['positive_feedback'] += 1

    # Calculate percentage of positive feedback and convert sets to lists
    for feature_key, stats in result.items():
        total_mentions = stats['count']
        if total_mentions > 0:
            stats['positive_feedback'] = (stats['positive_feedback'] / total_mentions) * 100
        stats['user_mentions'] = list(stats['user_mentions'])

    # Fetch additional metadata and integrate with the results
    feature_metadata = get_feature_metadata()
    for feature_key, data in result.items():
        if feature_key in feature_metadata:
            data.update(feature_metadata[feature_key])

    logging.info("Finished processing reviews")
    return result

# Example usage
