function renderFooterScripts(scripts) {
    if (!Array.isArray(scripts)) return '';

    const uniqueKeys = new Set();

    function generateUniqueKey(base) {
        let key = base;
        let counter = 1;
        while (uniqueKeys.has(key)) {
            key = `${base}-${counter}`;
            counter += 1;
        }
        uniqueKeys.add(key);
        return key;
    }

    const scriptElements = scripts.map(script => {
        if (!script || typeof script !== 'object') return '';

        let { js, css } = script;
        const dataKey = generateUniqueKey('footer-script');

        const safeJs = js ? `<script type="text/javascript">${js.replace(/</g, '\\u003c')}</script>` : '';
        const safeCss = css ? 
            `<style scoped>${css.replace(/</g, '\\u003c').replace(/>/g, '\\u003e')}</style>` : '';

        return `
            <div data-key="${dataKey}" style="display: contents;">
                ${safeJs}
                ${safeCss}
            </div>
        `;
    }).filter(Boolean);

    return `<footer>${scriptElements.join('')}</footer>`;
}

// Example usage:
const scripts = [
    { js: "console.log('Analytics script');", css: "body { background-color: #f0f0f0; }" },
    { js: "<!-- Inline comment --> alert('Test');" }, // Special characters handled
    null, // Graceful handling of null values
    {} // Graceful handling of empty objects
];

console.log(renderFooterScripts(scripts));
```

