// Function to process dialog fields.
void refreshDialogFields(std::forward_list<std::string>& dialogFields,
                         const std::string& resourceId, const std::string& url) {

    if (resourceId.empty() || url.empty()) {
        logError("Resource ID or URL is empty.");
        return;
    }

    // Predefined array of field names to refresh.
    const std::vector<std::string> fieldsToRefresh = {"field1", "field2", "field3"};

    for (const auto& fieldName : fieldsToRefresh) {
        if (std::find(dialogFields.begin(), dialogFields.end(), fieldName) != dialogFields.end()) {
            // Prepare message.
            std::string message = resourceId + "|" + url + "|" + fieldName;

            try {
                // Send message to parent window.
                if (sendMessageToParent(message)) {
                    // Receive updated field value.
                    std::string updatedValue = receiveResponseFromParent();

                    // Replace the corresponding entry in the forward list.
                    for (auto it = dialogFields.begin(); it != dialogFields.end(); ++it) {
                        if (*it == fieldName) {
                            *it = updatedValue;
                            break;
                        }
                    }
                } else {
                    logError("Failed to send message to parent window.");
                }
            } catch (...) {
                logError("Unexpected error during communication with parent window.");
            }
        }
    }

    // Check if resourceId is in the list; if not, append it.
    if (std::find(dialogFields.begin(), dialogFields.end(), resourceId) == dialogFields.end()) {
        dialogFields.push_back(resourceId);
    }
}
