class DataStreamManager {
    constructor() {
        this.streams = new Map(); // Unique identifier -> { buffers: [], totalLength: 0 }
    }

    appendData(streamId, newData) {
        if (!(newData instanceof Buffer)) {
            throw new Error('New data must be a Buffer');
        }

        const stream = this.streams.get(streamId);

        if (!stream) {
            // Initialize a new stream
            this.streams.set(streamId, { buffers: [newData], totalLength: newData.length });
            return;
        }

        // Verify integrity (simple checksum for demonstration)
        const checksum = this.calculateChecksum(newData);
        console.log(`Appending data with checksum: ${checksum}`);

        stream.buffers.push(newData);
        stream.totalLength += newData.length;

        // Perform a periodic cleanup if necessary
        this.cleanup(streamId);
    }

    retrieveData(streamId, start, end) {
        const stream = this.streams.get(streamId);

        if (!stream || start < 0 || end > stream.totalLength || start >= end) {
            throw new Error('Invalid range or stream not found');
        }

        let currentPos = 0;
        const resultBuffers = [];

        for (const buffer of stream.buffers) {
            if (currentPos + buffer.length <= start) {
                // This whole buffer is before the requested range
                currentPos += buffer.length;
                continue;
            }

            if (currentPos >= end) {
                // We've reached or passed the end of the requested range
                break;
            }

            const effectiveStart = Math.max(0, start - currentPos);
            const effectiveEnd = Math.min(buffer.length, end - currentPos);

            resultBuffers.push(buffer.slice(effectiveStart, effectiveEnd));

            currentPos += buffer.length;
        }

        return Buffer.concat(resultBuffers);
    }

    calculateChecksum(data) {
        // Simple checksum calculation for demonstration
        let sum = 0;
        for (let i = 0; i < data.length; i++) {
            sum += data[i];
        }
        return sum % 256;
    }

    cleanup(streamId) {
        const stream = this.streams.get(streamId);

        if (!stream || stream.buffers.length <= 1) {
            // No need to clean up
            return;
        }

        // If total length is small enough, concatenate buffers to reduce fragmentation
        if (stream.totalLength < 1024 * 1024) { // Example threshold of 1MB for concatenation
            const concatenatedBuffer = Buffer.concat(stream.buffers);
            stream.buffers = [concatenatedBuffer];
        }
    }

    handleFailure() {
        // Implement data persistence or snapshotting if necessary
        console.log('Implementing failure handling logic');
    }
}

// Usage example:
const manager = new DataStreamManager();
manager.appendData('stream1', Buffer.from('Hello, World!'));
manager.appendData('stream1', Buffer.from(' More data.'));

const dataPortion = manager.retrieveData('stream1', 0, 13);
console.log(dataPortion.toString()); // Outputs: Hello, World!
