const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

async function loadJavaScriptFiles(directory, retries = 3) {
    try {
        const files = await fs.readdir(directory);

        for (const file of files) {
            if (path.extname(file) === '.js') {
                let content;
                let attempt = 0;

                while (attempt < retries && !content) {
                    try {
                        content = await loadFileContent(path.join(directory, file));
                        const newFilename = generateNewFilename(file);
                        await renameAndSaveFile(content, path.join(directory, newFilename));

                        console.log(`Successfully loaded and saved: ${newFilename}`);
                    } catch (error) {
                        attempt++;
                        if (attempt === retries) {
                            console.error(`Failed to load file after ${retries} attempts: ${file}`, error);
                        }
                    }
                }
            }
        }
    } catch (error) {
        console.error('Error reading directory:', error);
    }
}

async function loadFileContent(filePath) {
    const response = await axios.get(filePath, { responseType: 'text' });
    return response.data;
}

function generateNewFilename(originalFilename) {
    const digits = Array.from({ length: 3 }).map(() => Math.floor(Math.random() * 10)).join('');
    const baseName = path.basename(originalFilename, '.js');
    const charSum = [...baseName].reduce((sum, char) => sum + char.charCodeAt(0), 0);
    return `${baseName}_${digits}.newext`;
}

async function renameAndSaveFile(content, newFilePath) {
    await fs.writeFile(newFilePath, content);
}

// Usage
loadJavaScriptFiles('./your-directory-path');

