import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class BackgroundServiceManager {

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private volatile boolean running = false;
    private final ServiceConfig config;

    public BackgroundServiceManager(ServiceConfig config) {
        this.config = config;
    }

    public void start() {
        if (!running) {
            running = true;
            scheduler.scheduleAtFixedRate(this::runService, 0, config.getScheduleInterval(), TimeUnit.MILLISECONDS);
        }
    }

    public void stop() {
        if (running) {
            publishStatusUpdate("Stopping service");
            running = false;
            // Additional cleanup logic
        }
    }

    private void runService() {
        try {
            long startTime = System.currentTimeMillis();

            if (!checkResourceLimits()) {
                logWarning("Resource limits exceeded, delaying restart.");
                return;  // Exit and let the scheduler retry after configured interval.
            }

            // Main service logic here

            publishStatusUpdate("Running successfully");

            long endTime = System.currentTimeMillis();
            long duration = endTime - startTime;
            if (duration > config.getMaxAllowedDuration()) {
                logWarning("Service run exceeded max duration, considering restart.");
            }
        } catch (Exception e) {
            logError("Service encountered an error: " + e.getMessage(), e);
            handleFailure();
        }
    }

    private boolean checkResourceLimits() {
        // Logic to check CPU and memory usage
        return true;  // Assume it returns a valid status based on checks
    }

    private void publishStatusUpdate(String message) {
        // Code to send updates to the external monitoring system
        logInfo("Status update: " + message);
    }

    private void handleFailure() {
        try {
            TimeUnit.MILLISECONDS.sleep(config.getRestartDelay());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        start();  // Restart service after delay
    }

    public void fetchAndApplyConfigFromApi() {
        ServiceConfig newConfig = fetchConfigFromApi();
        if (!newConfig.equals(this.config)) {
