<?php

require 'vendor/autoload.php';

use Psr\Log\LoggerInterface;
use Predis\Client as RedisClient;
use Symfony\Component\Finder\Finder;
use Symfony\Component\Config\FileLocator;
use Symfony\Component\DependencyInjection\ContainerBuilder;

// Initialize Logger (Psr-3)
class SimpleLogger implements LoggerInterface {
    private $logFile;

    public function __construct($logFilePath) {
        $this->logFile = fopen($logFilePath, 'a');
    }

    public function log($level, $message, array $context = []) {
        $logEntry = sprintf("[%s] %s: %s\n", date('Y-m-d H:i:s'), strtoupper($level), json_encode(['message' => $message, 'context' => $context]));
        fwrite($this->logFile, $logEntry);
    }

    public function __destruct() {
        fclose($this->logFile);
    }
}

// Configuration Manager
class ConfigurationManager {
    private $envVars = [];
    private $config;
    private $cache;

    public function __construct(LoggerInterface $logger) {
        $this->logger = $logger;
        $this->initCache();
        $this->loadConfiguration();
    }

    private function initCache() {
        $this->cache = new RedisClient(); // Using Redis for distributed caching
    }

    private function loadConfiguration() {
        // Load environment variables and command-line arguments
        foreach ($_SERVER as $key => $value) {
            if (strpos($key, 'ENV_') === 0) {
                putenv("$key=$value");
                $this->envVars[$key] = getenv($key);
            }
        }

        $cliArgs = getopt('', ['config:', 'api-url:']);
        if (!empty($cliArgs['config'])) {
            $this->loadFromFile($cliArgs['config']);
        }

        // Load from environment file, command-line and user input
        $envConfig = $this->parseEnvFile('.env');
        $this->mergeConfig($envConfig);

        // User input during runtime (simulated here)
        if (!empty($_POST)) {
            $this->mergeConfig($_POST);
        }

        // Load from database
        $dbConfig = $this->loadFromDatabase();
        $this->mergeConfig($dbConfig);

        // Load from external API
        $apiUrl = getenv('API_URL') ?: 'https://example.com/api/config';
        try {
            $apiConfig = file_get_contents($apiUrl);
            $apiConfig = json_decode($apiConfig, true) ?? [];
            $this->validateAndMergeApiConfig($apiConfig);
        } catch (\Exception $e) {
            $this->logger->log('error', 'Failed to retrieve API config', ['exception' => $e]);
        }

        // Store in cache
        $cacheKey = 'app_config';
        $this->cache->set($cacheKey, json_encode($this->config));

        $this->logger->log('info', 'Configuration loaded successfully');
    }

    private function loadFromFile($filePath) {
        if (!file_exists($filePath)) return;

        $finder = new Finder();
        $files = $finder->files()->in(dirname($filePath))->name(basename($filePath));

        foreach ($files as $file) {
            $this->mergeConfig(parse_ini_file($file->getRealPath()));
        }
    }

    private function parseEnvFile($filePath) {
        if (!file_exists($filePath)) return [];

        $lines = file($filePath, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
        $config = [];

        foreach ($lines as $line) {
            if (strpos(trim($line), '#') === 0 || trim($line) === '') continue;

            list($name, $value) = explode('=', $line, 2);
            $name = trim($name);
            $value = trim($value);
            $config[$name] = getenv($name) ?: $value;
        }

        return $config;
    }

    private function loadFromDatabase() {
        // Simulate database configuration loading
        return [
            'db_host' => 'localhost',
            'db_name' => 'my_app_db'
        ];
    }

    private function validateAndMergeApiConfig(array $apiConfig) {
        foreach ($apiConfig as $key => $value) {
            if (!isset($this->config[$key]) || $this->config[$key] !== $value) {
                $this->config[$key] = $value;
            }
        }
    }

    private function mergeConfig(array $newConfig) {
        foreach ($newConfig as $key => $value) {
            if (empty($this->config[$key])) {
                $this->config[$key] = $value;
            }
        }
    }

    public function getConfig() {
        return $this->config;
    }

    public function watchForChanges() {
        // Monitor changes in configuration sources
        while (true) {
            sleep(60); // Configurable interval

            if ($this->hasConfigChanged()) {
                $this->loadConfiguration();
                $this->logger->log('info', 'Configuration reloaded due to changes');
            }
        }
    }

    private function hasConfigChanged() {
        // Check file modification times, database timestamps or API last-modified headers
        return false; // Simplified for example purposes
    }
}

// Distributed Locking Mechanism
class SimpleLockManager {
    private $redis;

    public function __construct(RedisClient $client) {
        $this->redis = $client;
    }

    public function acquireLock($lockName, $timeout = 10) {
        $lockKey = "lock:$lockName";

        if ($this->redis->setnx($lockKey, time() + $timeout)) {
            return true; // Acquired the lock
        }

        $currentExpiration = $this->redis->get($lockKey);

        if (time() > $currentExpiration) {
            if ($this->redis->set($lockName, time() + $timeout, ['NX', 'PX' => $timeout * 1000])) {
                return true;
            }
        }

        return false; // Failed to acquire lock
    }

    public function releaseLock($lockName) {
        $this->redis->del("lock:$lockName");
    }
}

// Resource Monitoring
class ResourceMonitor {
    public static function report() {
        $memoryUsage = memory_get_usage();
        $cpuLoad = sys_getloadavg()[0]; // 1-minute load average

        echo sprintf("Memory Usage: %s bytes\n", formatBytes($memoryUsage));
        echo sprintf("CPU Load: %.2f%%\n", $cpuLoad * 100);
    }

    private static function formatBytes($bytes, $precision = 2) {
        $units = ['B', 'KB', 'MB', 'GB', 'TB'];

        $power = intval(floor(log($bytes, 1024)));
        return round($bytes / pow(1024, $power), $precision) . ' ' . $units[$power];
    }
}

// Graceful shutdown handler
register_shutdown_function(function() use ($logger) {
    $logger->log('info', 'Shutting down gracefully');
    // Cleanup operations go here
});

$logger = new SimpleLogger(__DIR__ . '/app.log');

$configManager = new ConfigurationManager($logger);

if (function_exists('pcntl_fork')) {
    $pid = pcntl_fork();
    if ($pid == -1) {
        exit("Error forking...\n");
    } elseif ($pid) {
        // Parent process
        $lockManager = new SimpleLockManager(new RedisClient());

        if (!$lockManager->acquireLock('config_update')) {
            exit("Failed to acquire lock. Exiting.\n");
        }

        try {
            $configManager->watchForChanges();
        } finally {
            $lockManager->releaseLock('config_update');
        }
    } else {
        // Child process
        ResourceMonitor::report(); 
    }
} else {
    ResourceMonitor::report(); 
}

?>
