use Psr\Log\LoggerInterface;
use GuzzleHttp\Client as HttpClient;
use CircuitBreaker\EasyCircuitBreaker;

class SessionUpdater {

    private $httpClient;
    private $logger;
    private $circuitBreaker;
    private $retryLimit = 3;

    public function __construct(HttpClient $httpClient, LoggerInterface $logger) {
        $this->httpClient = $httpClient;
        $this->logger = $logger;
        $this->circuitBreaker = new EasyCircuitBreaker();
    }

    public function updateUserSession($userId, $sessionData) {
        try {
            if (!$this->circuitBreaker->isAvailable()) {
                throw new Exception('Circuit breaker is open');
            }

            $attempt = 0;
            $success = false;

            while ($attempt < $this->retryLimit && !$success) {
                try {
                    $attempt++;
                    $this->updateSessionInDatabases($userId, $sessionData);
                    $this->syncWithExternalServices($userId, $sessionData);

                    $this->logger->info("Successfully updated session for user: {$userId}", ['attempt' => $attempt]);
                    $success = true;
                } catch (Exception $e) {
                    $this->handleTransientError($e, $attempt);
                }
            }

            if (!$success) {
                throw new Exception('Failed to update session after retries');
            }
        } catch (Exception $e) {
            $this->logger->error("Failed to update session for user: {$userId}", ['error' => $e->getMessage()]);
        }
    }

