    }

    private function handleTransientError(Exception $e, $attempt) {
        if ($attempt < $this->retryLimit && $this->isTransientError($e)) {
            sleep(pow(2, $attempt)); // Exponential backoff
            return;
        }

        $this->circuitBreaker->recordFailure();
        throw $e;
    }

    private function isTransientError(Exception $e) {
        // Determine if the error is transient and should be retried
        return in_array($e->getCode(), [500, 502, 503, 504]);
    }
}

