['```php
<?php

function generateConfigurableString($length, $charset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789') {
    $randomString = '';
    $maxIndex = strlen($charset) - 1;

    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charset[random_int(0, $maxIndex)];
    }

    return $randomString;
}

function generateConfigurableHash($password, $salt = '') {
    if (!$salt) {
        $salt = generateConfigurableString(16);
    }

    return hash('sha256', $salt . $password);
}

