<script type="text/javascript">
async function asyncReadFile(filePath) {
    try {
        const response = await fetch(`file://${filePath}`);

        if (!response.ok) {
            throw new Error('Network response was not ok.');
        }

        const data = await response.text();

        // Simple checksum for integrity check: length of file content
        const expectedChecksum = parseInt(response.headers.get("x-file-checksum") || "0");
        const actualChecksum = Buffer.from(data).length;

        if (actualChecksum !== expectedChecksum) {
            throw new Error('Data integrity check failed.');
        }

        return data;
    } catch (error) {
        console.error('Error reading file:', error);
        throw error; // Rethrow for further handling
    }
}
</script>
