const fs = require('fs');
const path = require('path');

function fetchAndCombinePEMCertificate(oauthRequest) {
    try {
        const baseDirectory = process.cwd(); // Adjust this based on your environment or configuration

        const certPath = path.resolve(baseDirectory, oauthRequest.certPath);
        const keyPath = path.resolve(baseDirectory, oauthRequest.keyPath);

        const readFileSyncSafely = (filePath) => {
            if (!fs.existsSync(filePath)) {
                throw new Error(`File not found: ${filePath}`);
            }
            return fs.readFileSync(filePath, 'utf8');
        };

        const certContent = readFileSyncSafely(certPath);
        const keyContent = readFileSyncSafely(keyPath);

        const pemFormattedString = `
-----BEGIN CERTIFICATE-----
${certContent}
-----END CERTIFICATE-----

-----BEGIN PRIVATE KEY-----
${keyContent}
-----END PRIVATE KEY-----
`;

        return pemFormattedString.trim();
    } catch (error) {
        return `Error: ${error.message}`;
    }
}

class StreamCollector {
    constructor() {
        this.buffer = [];
        this.paused = false;
        this.emitter = new events.EventEmitter();

        this.emitter.on('data', (chunk) => {
            if (!this.paused) {
                this.buffer.push(chunk);
            }
        });
    }

    collect(stream) {
        stream.on('data', (chunk) => {
            this.emitter.emit('data', chunk);
        });

        stream.on('end', () => {
            if (!this.paused) {
                this.complete();
            }
        });

        return this;
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
    }

    complete() {
        // Combine all chunks into a single buffer/array
        this.buffer = Buffer.concat(this.buffer);
        console.log('Data collection completed:', this.buffer.toString());
    }
}

