['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_CONCURRENT_REQUESTS 100

typedef struct {
    char ip_address[INET6_ADDRSTRLEN];
    char profile_info[1024]; // Adjust size as needed
} UserAuthInfo;

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static pthread_mutex_t rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
static int current_requests = 0;

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';

    return realsize;
}

int rate_limit() {
    pthread_mutex_lock(&rate_limit_lock);
    if (current_requests >= MAX_CONCURRENT_REQUESTS) {
        pthread_mutex_unlock(&rate_limit_lock);
        return -1; // Rate limit exceeded
    }
    current_requests++;
    pthread_mutex_unlock(&rate_limit_lock);
    return 0;
}

void release_resources(int result, MemoryStruct *mem) {
    if (result != CURLE_OK && mem->data) {
        free(mem->data);
        mem->data = NULL;
    }
    pthread_mutex_lock(&rate_limit_lock);
    current_requests--;
    pthread_mutex_unlock(&rate_limit_lock);
}

UserAuthInfo* resolveAndAuthenticate(const char *hostname, const char *oauth_token) {
    if (rate_limit() != 0) {
        return NULL; // Rate limit exceeded
    }

    UserAuthInfo *auth_info = malloc(sizeof(UserAuthInfo));
    if (!auth_info) {
        release_resources(0, NULL);
        return NULL;
    }
    memset(auth_info, 0, sizeof(UserAuthInfo));

    struct addrinfo hints, *res, *ptr;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        free(auth_info);
        release_resources(0, NULL);
        return NULL;
    }

    for (ptr = res; ptr != NULL; ptr = ptr->ai_next) {
        void *addr;
        if (ptr->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)ptr->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)ptr->ai_addr;
            addr = &(ipv6->sin6_addr);
        }
        inet_ntop(ptr->ai_family, addr, auth_info->ip_address, sizeof(auth_info->ip_address));
        break; // We only need the first address
    }

    freeaddrinfo(res);

    CURL *curl;
    CURLcode res_curl;
    MemoryStruct chunk;

    chunk.data = malloc(1);
    if (!chunk.data) {
        free(auth_info);
        release_resources(0, NULL);
        return NULL;
    }
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        char auth_url[256];
        snprintf(auth_url, sizeof(auth_url), "https://api.example.com/auth?token=%s", oauth_token);

        curl_easy_setopt(curl, CURLOPT_URL, auth_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res_curl = curl_easy_perform(curl);
        if (res_curl != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res_curl));
        } else {
            strcpy(auth_info->profile_info, chunk.data);
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    release_resources(res_curl, &chunk);

    if (res_curl != CURLE_OK) {
        free(auth_info);
        return NULL;
    }

    return auth_info;
}
```']

