<?php

class PasswordUpdater {

    private $db;
    private $emailService;
    private $logger;

    public function __construct($db, $emailService, $logger) {
        $this->db = $db;
        $this->emailService = $emailService;
        $this->logger = $logger;
    }

    public function updateUserPasswords(array $userUpdates): void {
        foreach ($userUpdates as $userId => $newPassword) {
            if (!$this->rateLimitCheck($userId)) {
                continue;
            }

            try {
                $transaction = $this->db->beginTransaction();

                // Ensure atomic update with locking mechanism
                $lockResult = $this->acquireLockForUser($userId);
                if ($lockResult !== true) {
                    throw new Exception('Unable to acquire lock for user.');
                }

                // Check if a password change is already pending or in process (idempotency)
                if (!$this->isIdempotentUpdate($userId)) {
                    $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);

                    $updateResult = $this->db->prepare("UPDATE users SET password = ? WHERE id = ? AND update_in_progress = 0");
                    $updateResult->execute([$hashedPassword, $userId]);

                    if ($updateResult->rowCount() === 1) {
                        // Mark as in progress
                        $markInProgress = $this->db->prepare("UPDATE users SET update_in_progress = 1 WHERE id = ?");
                        $markInProgress->execute([$userId]);

                        // Send email confirmation
                        $this->sendPasswordChangeConfirmation($userId);

                        // Log success
                        $this->logger->log('SUCCESS', ['user_id' => $userId, 'timestamp' => date('Y-m-d H:i:s')]);
                    }
                }

                $transaction->commit();
            } catch (Exception $e) {
                if ($transaction && !$transaction->isRollbackOnly()) {
                    $transaction->rollBack();
                }

                // Log failure
                $this->logger->log('ERROR', ['user_id' => $userId, 'timestamp' => date('Y-m-d H:i:s'), 'error' => $e->getMessage()]);

                // Implement retry logic or other recovery strategies if necessary
            } finally {
                $this->releaseLockForUser($userId);
            }
        }
    }

    private function acquireLockForUser(int $userId): bool {
        // Implement locking mechanism using database row-level locks or a distributed lock manager
        return true; // Placeholder
    }

    private function releaseLockForUser(int $userId): void {
        // Release any acquired locks
    }

    private function isIdempotentUpdate(int $userId): bool {
        $checkPending = $this->db->prepare("SELECT COUNT(*) FROM users WHERE id = ? AND update_in_progress = 1");
        $checkPending->execute([$userId]);
        return (int) $checkPending->fetchColumn() > 0;
    }

    private function sendPasswordChangeConfirmation(int $userId): void {
        try {
            // Call external email service
            $this->emailService->sendConfirmationEmail($userId);
        } catch (Exception $e) {
            // Handle failure gracefully, log error
            $this->logger->log('EMAIL_ERROR', ['user_id' => $userId, 'error' => $e->getMessage()]);
