std::mutex logMutex;

void logAttack(const std::string& characterName, const std::string& attackName) {
    std::lock_guard<std::mutex> guard(logMutex);
    std::ofstream logFile("combat_log.txt", std::ios_base::app);
    if (logFile.is_open()) {
        auto now = std::chrono::system_clock::now();
        auto now_c = std::chrono::system_clock::to_time_t(now);
        logFile << "[" << std::ctime(&now_c) 
                << "Character: " << characterName 
                << ", Attack: " << attackName << "]\n";
    }
}

void manageCombatStrategy(CombatSystem& combatSystem, int experienceLevel, const std::string& characterName, int currentTime) {
    // Get the priority list and find the next available attack
    auto priorityList = combatSystem.getAttackPriorityList();
    for (const auto& attackName : priorityList) {
        try {
            CombatSystem::Attack attack = combatSystem.getAttack(attackName);
            if ((currentTime - attack.lastUsedTime) >= attack.cooldown) {
                // Calculate the attack power
                double scaledPower = std::log1p(experienceLevel);

                // Log the selected attack
                logAttack(characterName, attackName);

                // Update last used time for the attack
                combatSystem.getAttack(attackName).lastUsedTime = currentTime;

                std::cout << "Character: " << characterName 
                          << ", Attack: " << attackName 
                          << ", Power: " << scaledPower 
                          << "\n";

                return;
            }
        } catch (const std::runtime_error& e) {
            // Handle missing attack error if needed
        }
    }

    // If no attacks are available, do nothing or log accordingly.
}

// Example usage within a multithreaded environment:
void characterThread(CombatSystem& combatSystem, int experienceLevel, const std::string& characterName) {
    auto startTime = std::chrono::system_clock::now();
    while (true) {
        auto currentTime = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now() - startTime).count();

        manageCombatStrategy(combatSystem, experienceLevel, characterName, currentTime);
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Adjust as needed
    }
}

int main() {
    CombatSystem combatSystem;

    // Simulate concurrent characters
    std::thread character1(characterThread, std::ref(combatSystem), 10, "Warrior");
    std::thread character2(characterThread, std::ref(combatSystem), 20, "Mage");

    character1.join();
    character2.join();

    return 0;
}
```

This code provides a basic framework for managing combat strategies in a video game setting. It includes thread-safe logging and handles attack cooldowns and priority-based selection efficiently. The power scaling is logarithmic with experience level, and the function updates priorities periodically without compromising performance.']

