#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *name;
    char *value;
} Setting;

typedef struct Node {
    Setting setting;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} SettingsCollection;

SettingsCollection* init_collection() {
    SettingsCollection *collection = (SettingsCollection*)malloc(sizeof(SettingsCollection));
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

int add_setting(SettingsCollection *collection, const char *name, const char *value) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        if (strcmp(current->setting.name, name) == 0) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Duplicate setting
        }
        current = current->next;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->setting.name = strdup(name);
    new_node->setting.value = strdup(value);
    new_node->next = collection->head;
    collection->head = new_node;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Successfully added
}

int load_settings_from_file(SettingsCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    char name[256];
    char value[1024];

    while (fscanf(file, "%255s %1023s", name, value) == 2) {
        add_setting(collection, name, value);
    }

    fclose(file);
    return 0; // Successfully loaded
}

int load_settings_from_network(SettingsCollection *collection, const char *endpoint) {
    // Simulate network loading
    // In real-world scenarios, you'd use networking libraries like libcurl
    if (strcmp(endpoint, "network1") == 0) {
        add_setting(collection, "NetworkSetting1", "Value1");
        add_setting(collection, "NetworkSetting2", "Value2");
    }
    return 0; // Successfully loaded
}

int count_unique_settings(SettingsCollection *collection) {
    int count = 0;
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
    return count;
}

void iterate_settings(SettingsCollection *collection, void (*callback)(const Setting *)) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        callback(&(current->setting));
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_collection(SettingsCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->setting.name);
        free(temp->setting.value);
        free(temp);
    }

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int main() {
    SettingsCollection *collection = init_collection();

    load_settings_from_file(collection, "config1.txt");
    load_settings_from_file(collection, "config2.txt");
    load_settings_from_network(collection, "network1");

    int total_unique_settings = count_unique_settings(collection);
    printf("Total unique settings: %d\n", total_unique_settings);

    iterate_settings(collection, [](const Setting *setting) {
        printf("%s=%s\n", setting->name, setting->value);
    });

    free_collection(collection);
    return 0;
}
```']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure of a DOM node
typedef struct DomNode {
    char *class;
    char *id;
    char *textContent;
    struct DomNode **children;
    int childCount;
} DomNode;

// Callback function type definition
typedef int (*Callback)(const char*, const char*);

// Helper function to traverse the DOM tree and process nodes
int processDomStringHelper(DomNode* node, const char* selector, size_t sizeLimit,
                           Callback callback, char** result, size_t* currentLength) {
    if (!node || *currentLength >= sizeLimit) {
        return 0;
    }

    int match = 0;

    // Check the class or id using the provided callback
    if (callback(node->class, selector)) {
        match = 1;
    } else if (callback(node->id, selector)) {
        match = 1;
    }

    // If the node matches and adding text won't exceed sizeLimit
    if (match) {
        size_t textLength = strlen(node->textContent);
        if (*currentLength + textLength + 1 > sizeLimit) { // +1 for the slash
            return -1; // Exceeds limit
        }

        strncat(*result, node->textContent, textLength); // Append text content
        (*currentLength) += textLength;

        // Add a slash after the text content if not at the end
        if (*currentLength < sizeLimit) {
            strcat(*result, "/");
            (*currentLength)++;
        }
    }

    // Recursively process child nodes
    for (int i = 0; i < node->childCount; ++i) {
        int childResult = processDomStringHelper(node->children[i], selector, sizeLimit,
                                                 callback, result, currentLength);
        if (childResult == -1) {
            return -1; // Propagate the exceed limit signal
        }
    }

    return 0;
}

// Main function to process the DOM string
char* processDomString(DomNode* root, const char* sizeLimitStr, Callback callback) {
    size_t sizeLimit = strtol(sizeLimitStr, NULL, 10);
    char* result = (char*)malloc(sizeLimit + 1); // Allocate memory for the result
    if (!result) return NULL;

    result[0] = '\0'; // Initialize as empty string
    size_t currentLength = 0;

    int status = processDomStringHelper(root, sizeLimitStr, sizeLimit, callback, &result, &currentLength);
    if (status == -1) {
        free(result);
        return NULL;
    }

    return result; // Return the processed string
}
```

This code defines a C function `processDomString` which traverses a DOM tree and processes nodes according to a selector and size limit. It uses recursion with careful memory management to handle large trees efficiently.']

['Below is a C program that addresses the specified tasks:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    float *averages;
    size_t count;
} Cache;

Cache cache = {NULL, 0};
size_t cache_size = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_default_theme_directory(const char *default_path) {
    static const char *theme_dir = NULL;
    if (!theme_dir) {
        theme_dir = default_path;
        // Initialize directory with default path
    }
}

int parse_and_store_average(const char *line, float *average) {
    char *token;
    int field_count = 0;
    float last_two_fields[2] = {0.0f, 0.0f};

    token = strtok(line, " ");
    while (token != NULL) {
        if (field_count >= 2 && isdigit(token[0])) {
            last_two_fields[field_count - 2] = atof(token);
        }
        field_count++;
        token = strtok(NULL, " ");
    }

    if (field_count < 3) return 0; // Not enough fields

    *average = (last_two_fields[0] + last_two_fields[1]) / 2.0f;
    return 1;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    float average;

    while (fgets(line, sizeof(line), file)) {
        if (parse_and_store_average(line, &average)) {
            pthread_mutex_lock(&cache_mutex);
            if (cache.count >= cache_size) {
                cache_size = cache_size ? cache_size * 2 : 4;
                cache.averages = realloc(cache.averages, cache_size * sizeof(float));
            }
            cache.averages[cache.count++] = average;
            pthread_mutex_unlock(&cache_mutex);
        }
    }

    fclose(file);
}

void output_averages() {
    pthread_mutex_lock(&cache_mutex);
    for (size_t i = 0; i < cache.count; ++i) {
        printf("%f", cache.averages[i]);
        if (i < cache.count - 1) {
            printf(",");
        }
    }
    printf("\n");
    pthread_mutex_unlock(&cache_mutex);
}

void free_resources() {
    free(cache.averages);
    pthread_mutex_destroy(&cache_mutex);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_default_theme_directory("/default/theme/path");

    process_file(argv[1]);

    output_averages();

    free_resources();

    return EXIT_SUCCESS;
}
```

### Key Points:
- **File Processing:** Reads a file line-by-line, calculates the average of the last two numerical fields.
- **Dynamic Memory Management:** Uses dynamic allocation for storing averages and resizes as needed.
- **Thread Safety:** Utilizes mutexes to ensure thread-safe access to shared resources.
- **Error Handling:** Includes basic error handling for file operations.
- **Scalability:** Designed to handle large files efficiently with dynamic memory management.

This program should be compiled and run in a C environment, ensuring all necessary libraries are linked. Adjust the `initialize_default_theme_directory` function as needed for specific directory initialization tasks.']

