#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <tiffio.h>  // Include the TIFF library header
#include <openssl/md5.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamplesCount;
    char **extraSamplesMetadata;  // Array of metadata strings for extra samples
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
} TIFFReport;

static pthread_mutex_t tiffMutex = PTHREAD_MUTEX_INITIALIZER;

TIFFReport* parseTIFFAndHash(const char *filePath) {
    TIFF *tiffFile;
    TIFFDirectory *tdir;
    uint32 w, h, samplesPerPixel;
    uint16 bitsPerSample[4];
    int extraSamplesCount = 0;
    char **extraSamplesMetadata = NULL;

    // Initialize the MD5 context
    unsigned char buffer[MD5_DIGEST_LENGTH];
    FILE *fileStream = fopen(filePath, "rb");
    if (!fileStream) {
        fprintf(stderr, "Unable to open file: %s\n", filePath);
        return NULL;
    }

    // Lock for thread safety
    pthread_mutex_lock(&tiffMutex);

    tiffFile = TIFFFdOpen(fileStream, filePath, "r");
    if (tiffFile == NULL) {
        fprintf(stderr, "Error opening TIFF file: %s\n", TIFFFileName(filePath));
        fclose(fileStream);
        pthread_mutex_unlock(&tiffMutex);
        return NULL;
    }

    if (!TIFFSetDirectory(tiffFile, 0)) {
        fprintf(stderr, "Failed to set directory for TIFF file\n");
        TIFFClose(tiffFile);
        fclose(fileStream);
        pthread_mutex_unlock(&tiffMutex);
        return NULL;
    }

    tdir = TIFFCurrentDir(tiffFile);

    if (!TIFFGetField(tdir, TIFFTAG_BITSPERSAMPLE, bitsPerSample, &samplesPerPixel)) {
        fprintf(stderr, "Failed to get bits per sample and samples per pixel\n");
        goto cleanup;
    }

    // Assuming 1 or 2 extra samples are possible
    if (samplesPerPixel > 4) {
        extraSamplesCount = samplesPerPixel - 4;
        extraSamplesMetadata = malloc(extraSamplesCount * sizeof(char*));
        for (int i = 0; i < extraSamplesCount; ++i) {
            size_t len = snprintf(NULL, 0, "Extra Sample %d Metadata", i + 1);
            extraSamplesMetadata[i] = malloc(len + 1);
            snprintf(extraSamplesMetadata[i], len + 1, "Extra Sample %d Metadata", i + 1);
        }
    }

    // Calculate MD5
    fseek(fileStream, 0, SEEK_SET);
    unsigned char data[1024];
    size_t bytesRead;
    while ((bytesRead = fread(data, 1, sizeof(data), fileStream)) > 0) {
        MD5_Update(buffer, data, bytesRead);
    }

    MD5_Final(tiffFile->md5Hash, buffer);

cleanup:
    if (tiffFile) TIFFClose(tiffFile);
    fclose(fileStream);
    pthread_mutex_unlock(&tiffMutex);

    TIFFReport *report = malloc(sizeof(TIFFReport));
    if (!report) {
        fprintf(stderr, "Failed to allocate memory for report\n");
        return NULL;
    }

    report->bitsPerSample = bitsPerSample[0];  // Simplification: assuming uniform samples
    report->samplesPerPixel = samplesPerPixel;
    report->extraSamplesCount = extraSamplesCount;
    report->extraSamplesMetadata = extraSamplesMetadata;

    memcpy(report->md5Hash, buffer, MD5_DIGEST_LENGTH);

    return report;
}
```

### Key Considerations:

- **Thread Safety**: Uses `pthread_mutex_t` to prevent race conditions when multiple threads access the function.

- **Error Handling**: Provides feedback through standard error output for any failures during file operations or TIFF parsing.

- **Memory Management**: Allocates and frees memory as needed, particularly for extra sample metadata. Ensure proper cleanup to avoid leaks in real-world applications.

- **Performance Optimization**: Utilizes cached metadata from the TIFF library and processes large files efficiently by reading them in chunks.

This code assumes that `tiffio.h` is available on your system, which provides access to a standard TIFF library like libtiff. Additionally, ensure OpenSSL is linked during compilation for MD5 hashing.']

