// Error codes
#define SUCCESS 0
#define ERROR_INVALID_CONFIG -1
#define ERROR_ALGORITHM_LOAD_FAIL -2
#define ERROR_VERSION_MISMATCH -3

typedef struct {
    char *config_string;
} CryptoConfig;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    // Implement logging integration with an external framework
    printf("Log: %s\n", message);
}

int load_algorithms(CryptoConfig config) {
    if (config == NULL || config->config_string == NULL) {
        log_message("Invalid configuration");
        return ERROR_INVALID_CONFIG;
    }

    const char *enabled_algos = config->config_string;

    // Dynamically register AES
    if (strstr(enabled_algos, "AES") != NULL) {
        if (!EVP_add_cipher(EVP_aes_128_cbc())) {
            log_message("Failed to load AES");
            return ERROR_ALGORITHM_LOAD_FAIL;
        }
    }

    // Dynamically register Camellia
    if (strstr(enabled_algos, "Camellia") != NULL) {
        if (!EVP_add_cipher(EVP_camellia_128_cbc())) {
            log_message("Failed to load Camellia");
            return ERROR_ALGORITHM_LOAD_FAIL;
        }
    }

    // Dynamically register MD5
    if (strstr(enabled_algos, "MD5") != NULL) {
        if (!EVP_add_digest(EVP_md5())) {
            log_message("Failed to load MD5");
            return ERROR_ALGORITHM_LOAD_FAIL;
        }
    }

    // Dynamically register SHA
    if (strstr(enabled_algos, "SHA") != NULL) {
        if (!EVP_add_digest(EVP_sha1()) || !EVP_add_digest_alias(EVP_sha1(), "sha")) {
            log_message("Failed to load SHA");
            return ERROR_ALGORITHM_LOAD_FAIL;
        }
    }

    // Dynamically register RSA with SHA1
    if (strstr(enabled_algos, "RSA-SHA1") != NULL) {
        const EVP_MD *md = EVP_get_digestbyname("SHA1");
        if (!md) {
            log_message("Failed to get digest for RSA-SHA1");
            return ERROR_ALGORITHM_LOAD_FAIL;
        }
        // Further integration for RSA would be here
    }

    log_message("All algorithms loaded successfully");
    return SUCCESS;
}

void free_resources(CryptoConfig config) {
    if (config && config->config_string) {
        free(config->config_string);
    }
}

int configure_crypto_module(const char *config_str, int *status_code) {
    pthread_mutex_lock(&lock);

    CryptoConfig config = { .config_string = strdup(config_str) };
    int result = load_algorithms(&config);

    if (result != SUCCESS) {
        *status_code = result;
        log_message("Configuration failed");
    } else {
        *status_code = SUCCESS;
        log_message("Configuration successful");
    }

    free_resources(&config);

    pthread_mutex_unlock(&lock);
    return 0;
}

// Example testing framework function
void run_tests() {
    int status_code;

    // Test valid configuration
    configure_crypto_module("AES,Camellia,MD5,SHA,RSA-SHA1", &status_code);
    printf("Test with all algorithms: %d\n", status_code);

    // Add more tests for edge cases and high-load scenarios here

    // Simulate error conditions
    configure_crypto_module("", &status_code);
    printf("Test with empty configuration: %d\n", status_code);
}

int main() {
    run_tests();
    return 0;
}
```

