// Define a function to convert JPEG to PDF using a third-party tool.
int jpeg_to_pdf(const char *jpeg_filename, const char *pdf_filename, unsigned char **output_bytes) {
    char command[1024];
    FILE *pdf_file = NULL;
    long pdf_size = 0;

    // Construct the command for conversion. Replace 'third_party_tool' with actual command name.
    snprintf(command, sizeof(command), "third_party_tool %s -o %s", jpeg_filename, pdf_filename);

    // Execute the third-party tool to convert JPEG to PDF
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Conversion failed: Error code %d\n", result);
        return 1;
    }

    // Open the resulting PDF file for reading in binary mode
    pdf_file = fopen(pdf_filename, "rb");
    if (!pdf_file) {
        perror("Failed to open the generated PDF file");
        remove(pdf_filename); // Cleanup: remove the partially created or empty PDF file
        return 1;
    }

    // Get the size of the PDF file
    fseek(pdf_file, 0L, SEEK_END);
    pdf_size = ftell(pdf_file);
    rewind(pdf_file);

    // Allocate memory for the output byte array
    *output_bytes = (unsigned char *)malloc(pdf_size);
    if (!*output_bytes) {
        perror("Memory allocation failed");
        fclose(pdf_file); 
        remove(pdf_filename); // Cleanup: remove the generated PDF file
        return 1;
    }

    // Read the entire PDF into the output byte array
    size_t read_size = fread(*output_bytes, 1, pdf_size, pdf_file);
    if (read_size != pdf_size) {
        fprintf(stderr, "Failed to read the entire PDF content\n");
        free(*output_bytes);
        *output_bytes = NULL;
        fclose(pdf_file); 
        remove(pdf_filename); // Cleanup: remove the generated PDF file
        return 1;
    }

    // Close the PDF file and clean up temporary files
    fclose(pdf_file);
    if (remove(pdf_filename) != 0) { // Remove the temporary PDF file after reading
        perror("Failed to delete the temporary PDF file");
    }

    return 0; // Success
}

// Example usage of the function
int main() {
    const char *jpeg_name = "input.jpg";
    const char *pdf_name = "output.pdf";
    unsigned char *pdf_data = NULL;

    int status = jpeg_to_pdf(jpeg_name, pdf_name, &pdf_data);
    if (status == 0) {
        printf("PDF conversion successful!\n");
        // Use the PDF data as needed...

        // Free allocated memory after use
        free(pdf_data);
    } else {
        fprintf(stderr, "Failed to convert JPEG to PDF.\n");
    }

    return status;
}
```

