import java.util.logging.Logger;

public class ConfigFetcher {

    private static final Logger logger = Logger.getLogger(ConfigFetcher.class.getName());
    private static final String API_ENDPOINT = "https://api.example.com/config";
    private static final int TIMEOUT_MS = 5000; // Network timeout
    private static final long RATE_LIMIT_WAIT_MS = 1000; // Wait time for rate limiting

    public static void main(String[] args) {
        String environment = "production"; // Example environment

        try {
            if (localConfigExists()) {
                deleteLocalConfig();
            }

            String configData = fetchConfigFromApi(environment);
            validateAndStoreConfig(configData);

        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to update configuration", e);
            fallbackMechanism();
        }
    }

    private static boolean localConfigExists() {
        File configFile = new File("config.json");
        return configFile.exists();
    }

    private static void deleteLocalConfig() throws Exception {
        Files.deleteIfExists(new File("config.json").toPath());
        logger.info("Deleted local configuration file.");
    }

    private static String fetchConfigFromApi(String environment) throws Exception {
        URL url = new URL(API_ENDPOINT + "?env=" + environment);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout(TIMEOUT_MS);
        connection.setReadTimeout(TIMEOUT_MS);

        int responseCode = connection.getResponseCode();
        if (responseCode == 429) { // Rate limit exceeded
            logger.warning("Rate limit hit, waiting...");
            Thread.sleep(RATE_LIMIT_WAIT_MS);
            return fetchConfigFromApi(environment); // Retry after wait
        }

        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("Failed to fetch config: " + responseCode);
        }

        try (java.io.InputStream inputStream = connection.getInputStream()) {
            byte[] buffer = new byte[4096];
            int bytesRead;
            StringBuilder response = new StringBuilder();

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                response.append(new String(buffer, 0, bytesRead));
            }

            return response.toString();
        }
    }

    private static void validateAndStoreConfig(String configData) throws Exception {
        // Dummy validation logic
        if (configData.isEmpty()) {
            throw new RuntimeException("Invalid configuration data");
        }

        storeInCentralizedSystem(configData);
        logger.info("Configuration stored successfully.");
    }

    private static void storeInCentralizedSystem(String configData) {
        // Simulate storing in a centralized system
        logger.info("Storing configuration in the centralized system...");
    }

    private static void fallbackMechanism() {
        logger.warning("Using fallback mechanism for configuration.");
        // Implement fallback logic, e.g., use cached or default settings
    }
}
