    int index = (unsigned long)session_json % sizeof(processed_sessions) / sizeof(int);

    if (processed_sessions[index]) {
        pthread_mutex_unlock(&session_mutex);
        return ERROR_DEPENDENCY_FAILURE;
    }

    processed_sessions[index] = 1;

    pthread_mutex_unlock(&session_mutex);

    // Check required fields
    if (!session_id || !user_id || expiration_time == 0) {
        return ERROR_MISSING_FIELDS;
    }

    // Validate session_id (non-empty string)
    if (strlen(session_id) == 0 || strlen(session_id) > SESSION_ID_MAX_LENGTH) {
        return ERROR_INVALID_FORMAT;
    }

    // Validate user_id as a UUID
    if (!is_valid_uuid(user_id)) {
        return ERROR_INVALID_FORMAT;
    }

    // Check expiration_time is in the future
    time_t current_utc_time = get_utc_time();
    if (expiration_time <= current_utc_time) {
        return ERROR_INVALID_FORMAT;
    }

    // If everything is valid, reset session as processed
    pthread_mutex_lock(&session_mutex);
    processed_sessions[index] = 0;
    pthread_mutex_unlock(&session_mutex);

    return ERROR_NONE;
}

// Helper function to validate UUID format
int is_valid_uuid(const char *uuid_str) {
    uuid_t parsed_uuid;
    return uuid_parse(uuid_str, parsed_uuid) == 0; // Returns 0 on success
}

// Helper function to get current UTC time
time_t get_utc_time() {
    time_t now;
    struct tm tm_utc;
    time(&now);
    gmtime_r(&now, &tm_utc); // Thread-safe version of gmtime
    return mktime(&tm_utc);
}
```

**Note:**
- This code assumes the existence of a JSON parsing mechanism to extract `session_id`, `user_id`, and `expiration_time`. Replace `"extracted_session_id"`, etc., with actual JSON parsing logic.
- The `is_valid_uuid` function uses the libuuid library for UUID validation. Ensure this or an equivalent library is available in your environment.
- The thread-safe mechanism here uses a simple array with mutex locks to simulate session processing. Adjust the size of `processed_sessions` and hashing logic based on actual usage scenarios.
- Error handling should be expanded as needed, especially regarding external dependency checks like UUID validation service availability or time synchronization issues.']

