using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Threading;
using System.Diagnostics;

public class DatabaseRangeManager
{
    private readonly List<Range> _ranges = new();
    private static readonly HttpClient _httpClient = new();
    private readonly SemaphoreSlim _semaphore = new(1, 1);
    private readonly ILogger _logger;

    public DatabaseRangeManager(ILogger logger)
    {
        _logger = logger;
    }

    public void AddRange(float min, float max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var range = new Range(min, max, inclusiveMin, inclusiveMax);
        MergeRanges(range);
        _logger.Log($"Added range: {range}");
    }

    public void RemoveRange(float min, float max)
    {
        lock (_ranges) // Ensuring thread safety
        {
            _ranges.RemoveAll(r => r.Contains(min, max));
            _logger.Log($"Removed range: ({min}, {max})");
        }
    }

    public async Task<DataTableReader> QueryDatabaseAsync(byte[] data)
    {
        try
        {
            var response = await RetryPolicy(() => _httpClient.PostAsync("https://database.server/query", new ByteArrayContent(data)));
            response.EnsureSuccessStatusCode();
            var dataTable = new DataTable(); // Assuming conversion from response content to DataTable is handled here.
            return dataTable.CreateDataReader();
        }
        catch (Exception ex)
        {
            _logger.LogError($"Database query failed: {ex.Message}");
            throw;
        }
    }

    public float GenerateRandomFloat(float min, float max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var random = new Random();
        double value;

        if (inclusiveMin && inclusiveMax)
            value = random.NextDouble() * (max - min) + min;
        else if (!inclusiveMin && inclusiveMax)
            value = random.NextDouble() * (max - min - 1) + min + 1;
        else if (inclusiveMin && !inclusiveMax)
            value = random.NextDouble() * (max - min) + min;
        else
            value = random.NextDouble() * (max - min - 1) + min + 1;

        return (float)value;
    }

    public int GenerateRandomInteger(int min, int max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var range = inclusiveMax ? max - min + 1 : max - min;
        if (range <= 0) throw new ArgumentOutOfRangeException("Invalid range.");

        return new Random().Next(inclusiveMin ? min : min + 1, inclusiveMax ? max + 1 : max);
    }

    private void MergeRanges(Range newRange)
    {
        lock (_ranges)
        {
            _ranges.Add(newRange);

            var merged = _ranges.OrderBy(r => r.Min).ToList();
            for (int i = 0; i < merged.Count - 1; i++)
            {
                if (merged[i].Overlaps(merged[i + 1]))
                {
                    merged[i] = Range.MergeRanges(merged[i], merged[i + 1]);
                    merged.RemoveAt(i + 1);
                    i--;
                }
            }

            _ranges.Clear();
            _ranges.AddRange(merged);

            _logger.Log($"Merged ranges: {_ranges}");
        }
    }

    public void SplitRange(float min, float max, Func<float, bool> criteria)
    {
        lock (_ranges) // Ensuring thread safety
        {
            var range = new Range(min, max);
            foreach (var subRange in range.Split(criteria))
            {
                _logger.Log($"Split into: {subRange}");
                AddRange(subRange.Min, subRange.Max, true, true);
            }
        }
    }

    private async Task<HttpResponseMessage> RetryPolicy(Func<Task<HttpResponseMessage>> action)
    {
        const int maxRetries = 3;
        int retryCount = 0;

        while (retryCount < maxRetries)
        {
            try
            {
                return await action();
            }
            catch (HttpRequestException ex) when (++retryCount <= maxRetries)
            {
                _logger.LogWarning($"Request failed, attempt {retryCount}. Retrying... Error: {ex.Message}");
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount))); // Exponential backoff
            }
        }

        throw new HttpRequestException("Max retries exceeded");
    }

    private class Range
    {
        public float Min { get; }
        public float Max { get; }
        private readonly bool _inclusiveMin;
        private readonly bool _inclusiveMax;

        public Range(float min, float max, bool inclusiveMin = true, bool inclusiveMax = true)
        {
            Min = min;
            Max = max;
            _inclusiveMin = inclusiveMin;
            _inclusiveMax = inclusiveMax;
        }

        public override string ToString()
        {
            return $"[{Min}, {Max}]";
        }

        public bool Contains(float value) => 
            (_inclusiveMin ? Min <= value : Min < value) && (_inclusiveMax ? Max >= value : Max > value);

        public bool Contains(float min, float max)
        {
            return (_inclusiveMin ? Min <= min : Min < min) &&
                   (_inclusiveMax ? Max >= max : Max > max);
        }

        public IEnumerable<Range> Split(Func<float, bool> criteria)
        {
            var points = new List<float>();
            for (var i = Min; i <= Max; i += 0.1f) // Adjust step as necessary
                if (criteria(i))
                    points.Add(i);

            var ranges = new List<Range>();
            float start = Min;

            foreach (var point in points)
            {
                ranges.Add(new Range(start, point));
                start = point;
            }
            ranges.Add(new Range(start, Max));

            return ranges;
        }

        public bool Overlaps(Range other) => 
            (_inclusiveMin ? Min <= other.Max : Min < other.Max) && (other._inclusiveMax ? other.Min <= Max : other.Min < Max);

        public static Range MergeRanges(Range a, Range b)
        {
            float newMin = a.Min < b.Min || (!a._inclusiveMin && a.Min == b.Min) ? a.Min : b.Min;
            float newMax = a.Max > b.Max || (a._inclusiveMax && a.Max == b.Max) ? a.Max : b.Max;

            bool inclusiveMin = (newMin == a.Min && a._inclusiveMin) || (newMin == b.Min && b._inclusiveMin);
            bool inclusiveMax = (newMax == a.Max && a._inclusiveMax) || (newMax == b.Max && b._inclusiveMax);

            return new Range(newMin, newMax, inclusiveMin, inclusiveMax);
        }
    }

    public interface ILogger
    {
        void Log(string message);
        void LogError(string error);
        void LogWarning(string warning);
    }

    // Monitoring feature using basic logging for simplicity.
    private class ConsoleLogger : ILogger
    {
        public void Log(string message)
        {
            Debug.WriteLine($"INFO: {message}");
        }

        public void LogError(string error)
        {
            Debug.WriteLine($"ERROR: {error}");
        }

        public void LogWarning(string warning)
        {
            Debug.WriteLine($"WARNING: {warning}");
        }
    }
}

public static class ByteArrayContent
{
    public static ByteArrayContent FromByteArray(byte[] byteArray) => new(byteArray);
}
