public class EncryptedMessage
{
    public string MessageId { get; set; }
    public string EncodedMessage { get; set; }
}

public class DecryptionService
{
    private static readonly byte[] TripleDESEncodingKey = Encoding.UTF8.GetBytes("YourTripleDESKeyHere123"); // 24 bytes key for Triple DES
    private static readonly byte[] TripleDESIV = Encoding.UTF8.GetBytes("YourInitVector12"); // 8 bytes IV

    public Dictionary<string, string> ProcessMessages(string jsonPayload)
    {
        var decryptedMessages = new Dictionary<string, string>();

        try
        {
            var messages = JsonConvert.DeserializeObject<List<EncryptedMessage>>(jsonPayload);

            if (messages == null || messages.Count == 0) return decryptedMessages;

            foreach (var message in messages)
            {
                try
                {
                    var decryptedText = DecryptBase64EncodedMessage(message.EncodedMessage, TripleDESEncodingKey, TripleDESIV);
                    decryptedMessages[message.MessageId] = decryptedText;
                }
                catch (Exception ex) when (ex is FormatException || ex is CryptographicException)
                {
                    // Log the error message without crashing
                    Console.WriteLine($"Error processing Message ID {message.MessageId}: {ex.Message}");
                }
            }
        }
        catch (JsonException jsonEx)
        {
            // Handle JSON parsing errors gracefully
            Console.WriteLine($"JSON Parsing Error: {jsonEx.Message}");
        }

        return decryptedMessages;
    }

    private string DecryptBase64EncodedMessage(string base64EncodedEncryptedMessage, byte[] key, byte[] iv)
    {
        try
        {
            var encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);

            using (var tdesAlgorithm = TripleDES.Create())
            {
                tdesAlgorithm.Key = key;
                tdesAlgorithm.IV = iv;

                using (var decryptor = tdesAlgorithm.CreateDecryptor(tdesAlgorithm.Key, tdesAlgorithm.IV))
                {
                    using (var msDecrypt = new MemoryStream(encryptedBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            using (var srDecrypt = new StreamReader(csDecrypt))
                            {
                                return srDecrypt.ReadToEnd();
                            }
                        }
                    }
                }
            }
        }
        catch
        {
            throw; // Rethrow the exception to be caught by the outer try-catch block
        }
    }
}
