using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class HashProcessor
{
    private readonly string filePath;
    private readonly ILogger logger; // Assuming ILogger is the logging interface

    public HashProcessor(string filePath, ILogger logger)
    {
        this.filePath = filePath;
        this.logger = logger;
    }

    public async Task ProcessFileAsync()
    {
        using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 4096, useAsync: true);
        using var reader = new StreamReader(fileStream);

        var queue = new ConcurrentQueue<string>();
        var producerTask = ProduceLines(reader, queue);
        var consumerTasks = StartConsumers(queue);

        await Task.WhenAll(producerTask, Task.WhenAny(consumerTasks));
    }

    private async Task ProduceLines(StreamReader reader, ConcurrentQueue<string> queue)
    {
        string line;
        while ((line = await reader.ReadLineAsync()) != null)
        {
            queue.Enqueue(line);
            logger.Log($"Enqueued line for processing: {SanitizeForLogging(line)}");
        }
    }

    private IEnumerable<Task> StartConsumers(ConcurrentQueue<string> queue)
    {
        var tasks = new List<Task>();

        for (int i = 0; i < Environment.ProcessorCount * 2; i++) // Scale based on processor count
        {
            tasks.Add(Task.Run(() => ConsumeLines(queue)));
        }

        return tasks;
    }

    private void ConsumeLines(ConcurrentQueue<string> queue)
    {
        while (queue.TryDequeue(out var line))
        {
            try
            {
                string hash = CalculateSHA256(line);
                logger.Log($"Processed line: {SanitizeForLogging(line)}, Hash: {hash}");
                // Store the result in a memory-efficient manner, e.g., sending to a database or another service
            }
            catch (Exception ex)
            {
                logger.Log($"Error processing line: {ex.Message}", LogLevel.Error);
                // Optionally re-enqueue for retry logic or handle fault tolerance as needed
            }
        }
    }

    private string CalculateSHA256(string input)
    {
        using var sha256 = SHA256.Create();
        byte[] bytes = Encoding.UTF8.GetBytes(input);
        byte[] hashBytes = sha256.ComputeHash(bytes);

        StringBuilder builder = new StringBuilder();
        foreach (byte b in hashBytes)
            builder.Append(b.ToString("x2"));

        return builder.ToString();
    }

    private string SanitizeForLogging(string text)
    {
        // Implement this based on the logger's requirements
        return text.Length > 50 ? $"{text.Substring(0, 47)}..." : text;
    }
}

// Placeholder interface for logging
