```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AesCbcDecryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AesCbcDecryptor(byte[] key, byte[] iv)
    {
        if (key.Length != 16 && key.Length != 24 && key.Length != 32)
            throw new ArgumentException("Invalid AES key size.");
        if (iv.Length != 16)
            throw new ArgumentException("Invalid IV size.");

        _key = key;
        _iv = iv;
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext, CancellationToken cancellationToken = default)
    {
        using var aes = Aes.Create();
        aes.Key = _key;
        aes.IV = _iv;
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        // Validate and handle malformed data
        if (ciphertext.Length < 16) 
            throw new ArgumentException("Ciphertext too short to contain a valid IV.");

        var decryptedData = new byte[ciphertext.Length];

        try
        {
            using var decryptor = aes.CreateDecryptor(_key, _iv);
            using var ms = new MemoryStream(ciphertext);
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

            await cs.ReadAsync(decryptedData, 0, decryptedData.Length, cancellationToken);
            return ValidateAndTrimPadding(decryptedData, aes.BlockSize / 8);
        }
        catch (CryptographicException ex)
        {
            // Log and handle decryption errors
            Console.WriteLine($"Decryption failed: {ex.Message}");
            throw;
        }
    }

    private byte[] ValidateAndTrimPadding(byte[] decryptedBytes, int blockSize)
    {
        var paddingSize = decryptedBytes[decryptedBytes.Length - 1];

        if (paddingSize < 1 || paddingSize > blockSize)
            throw new CryptographicException("Invalid padding size.");

        for (int i = decryptedBytes.Length - paddingSize; 
             i < decryptedBytes.Length; i++)
        {
            if (decryptedBytes[i] != paddingSize)
                throw new CryptographicException("Invalid padding.");
        }

        var trimmedData = new byte[decryptedBytes.Length - paddingSize];
        Array.Copy(decryptedBytes, 0, trimmedData, 0, trimmedData.Length);

        return trimmedData;
    }
}

