        var iv = Encoding.UTF8.GetBytes("1234567890123456");  // Example IV, replace with actual secure IV

        var decryptor = new AesCbcDecryptor(key, iv);

        byte[] ciphertext = ...; // Ciphertext to be decrypted

        try
        {
            var plaintext = await decryptor.DecryptAsync(ciphertext);
            Console.WriteLine("Decryption successful.");
            Console.WriteLine(Encoding.UTF8.GetString(plaintext));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
