['```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;

public class DataCache<T>
{
    private readonly int _maxEntries;
    private readonly object _lock = new object();
    private readonly Dictionary<string, CacheEntry> _cache = new();

    public DataCache(int maxEntries)
    {
        _maxEntries = maxEntries;
    }

    public T Get(string key, Func<Task<byte[]>> fetchFunc)
    {
        if (_cache.TryGetValue(key, out var cacheEntry) && !cacheEntry.IsExpired())
        {
            return cacheEntry.Data;
        }

        lock (_lock)
        {
            // Double-check locking
            if (_cache.TryGetValue(key, out cacheEntry) && !cacheEntry.IsExpired())
            {
                return cacheEntry.Data;
            }

            try
            {
                var data = fetchFunc().Result;
                DeserializeData(data);

                if (_cache.Count >= _maxEntries)
                {
                    Evict();
                }

                _cache[key] = new CacheEntry { Data = DeserializeData<T>(data), LastAccessed = DateTime.UtcNow };
            }
            catch (Exception ex) when (ex is IOException || ex is InvalidDataException)
            {
                Console.WriteLine($"Error loading data: {ex.Message}");
                return default;
            }

            return _cache[key].Data;
        }
    }

    private void Evict()
    {
        var oldestKey = (_cache.OrderBy(e => e.Value.LastAccessed)).First().Key;
        _cache.Remove(oldestKey);
    }

    private T DeserializeData<T>(byte[] data)
    {
        using (var memoryStream = new MemoryStream(data))
        {
            var formatter = new BinaryFormatter();
            try
            {
                return (T)formatter.Deserialize(memoryStream);
            }
            catch (SerializationException ex)
            {
                throw new InvalidDataException("Deserialization failed", ex);
            }
        }
    }

    private class CacheEntry
    {
        public T Data { get; set; }
        public DateTime LastAccessed { get; set; }

        public bool IsExpired() => (DateTime.UtcNow - LastAccessed).TotalMinutes > 5;
    }
}

public static class DataService
{
    private static readonly object SyncLock = new();
    private static DataCache<MyCustomDataType> _dataCache;

    public static async Task InitializeDataCacheAsync(int cacheSize)
    {
        lock (SyncLock)
        {
            _dataCache ??= new DataCache<MyCustomDataType>(cacheSize);
        }
    }

    public static MyCustomDataType LoadAndDeserialize(string filePath)
    {
        if (_dataCache == null) throw new InvalidOperationException("Data cache not initialized.");

        return _dataCache.Get(filePath, async () => await DownloadAndDecompressAsync(filePath));
    }

    private static async Task<byte[]> DownloadAndDecompressAsync(string filePath)
    {
        try
        {
            using (var httpClient = new HttpClient())
            {
                var response = await httpClient.GetAsync(new Uri(filePath));

                if (!response.IsSuccessStatusCode)
                    throw new IOException("Failed to download file.");

                var compressedData = await response.Content.ReadAsByteArrayAsync();

                using (var input = new MemoryStream(compressedData))
                using (var decompressionStream = new GZipStream(input, CompressionMode.Decompress))
                {
                    using (var resultStream = new MemoryStream())
                    {
                        decompressionStream.CopyTo(resultStream);
                        return resultStream.ToArray();
                    }
                }
            }
        }
        catch (Exception ex) when (ex is HttpRequestException || ex is InvalidDataException)
        {
            throw new IOException("Network or data issue occurred.", ex);
        }
    }
}

[Serializable]
public class MyCustomDataType
{
    // Define the structure of your custom data type here.
}
```']

