// Import necessary libraries
import axios from 'axios';
import NodeCache from 'node-cache'; // For caching
import { throttle } from 'lodash';

// Configuration for API requests
const config = {
  apiUrl: 'https://api.example.com/users',
  cacheTTL: 300, // Cache time-to-live in seconds
  maxRetries: 3,
  rateLimitWindowMs: 1000 * 60, // 1 minute window
  requestsPerWindow: 60,
};

// Set up caching mechanism
const userCache = new NodeCache({ stdTTL: config.cacheTTL });

// Throttle API calls to respect rate limits
let requestCount = 0;
const resetRateLimitCounter = throttle(() => {
  requestCount = 0;
}, config.rateLimitWindowMs);

// Function to fetch users with pagination and caching
async function fetchUsers(page, limit) {
  const cacheKey = `users-${page}-${limit}`;

  // Check cache first
  const cachedData = userCache.get(cacheKey);
  if (cachedData) return cachedData;

  try {
    requestCount++;
    resetRateLimitCounter();

    if (requestCount > config.requestsPerWindow) {
      throw new Error('Rate limit exceeded');
    }

    const response = await axios.get(`${config.apiUrl}?page=${page}&limit=${limit}`);

    // Cache the response data
    userCache.set(cacheKey, response.data);

    return response.data;
  } catch (error) {
    if (axios.isAxiosError(error) && error.response?.status === 429) {
      console.error('Rate limit exceeded. Retrying...');
      await new Promise(resolve => setTimeout(resolve, config.rateLimitWindowMs));
      return fetchUsers(page, limit);
    }

    // Log errors
    console.error(`Failed to fetch users: ${error.message}`);

    throw error;
  }
}

// Function to display data on the web page
function displayUserData(users) {
  const container = document.getElementById('user-container');

  users.forEach(user => {
    const userElement = document.createElement('div');
    userElement.className = 'user';
    userElement.textContent = `${user.name} (${user.email})`;
    container.appendChild(userElement);
  });
}

// Fetch and display data with pagination
async function loadUsers(page, limit) {
  try {
    const usersData = await fetchUsers(page, limit);
    displayUserData(usersData.users);

    // Handle pagination logic here if needed (e.g., next/previous buttons)
  } catch (error) {
    console.error(`Error loading users: ${error.message}`);
    alert('Failed to load user data. Please try again later.');
  }
}

// Initial call to load users
loadUsers(1, 10);

// Example of real-time updates using WebSockets or similar technology could be added here

// Implement performance monitoring (e.g., time taken for requests) and logging as needed
```

