use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use log::{info, error};

fn manage_directories(
    config: Vec<String>,
    max_dirs: Option<usize>,
    timeout: u64,
) -> Result<bool, io::Error> {
    // Initialize environment variable prefix
    let mut path_prefix = env::var("PATH_PREFIX")
        .unwrap_or_else(|_| "PATH_PREFIX".into());

    // Ensure the path ends with a separator appropriate for the OS
    if cfg!(target_os = "windows") {
        if !path_prefix.ends_with('\\') && !path_prefix.is_empty() {
            path_prefix.push('\\');
        }
    } else {
        if !path_prefix.ends_with('/') && !path_prefix.is_empty() {
            path_prefix.push('/');
        }
    }

    let path_prefix = Arc::new(Mutex::new(path_prefix));
    let env_var_name = "MY_PATH_ENV_VAR";
    let delimiter = ";";

    // Mutex to handle concurrent access
    let dirs_mutex = Arc::new(Mutex::new(Vec::new()));

    for dir_name in config.into_iter().take(max_dirs.unwrap_or(config.len())) {
        if !is_valid_dir_name(&dir_name) {
            error!("Invalid directory name: {}", dir_name);
            continue;
        }

        let sanitized_dir_name = sanitize_dir_name(dir_name);
        let full_path = format!("{}/{}", path_prefix.lock().unwrap(), sanitized_dir_name);

        // Check if the directory exists and create it if not
        let mut created = false;

        {
            let _lock = dirs_mutex.lock().unwrap();
            if !Path::new(&full_path).exists() {
                if let Err(e) = fs::create_dir_all(&full_path).wait_timeout(timeout)? {
                    error!("Failed to create directory {}: {}", full_path, e);
                    continue;
                }
                created = true;
                info!("Created directory: {}", full_path);
            } else if !is_directory_valid(Path::new(&full_path)) {
                error!("Directory integrity check failed for {}", full_path);
                continue;
            }
        }

        // Update environment variable
        let mut env_paths = env::var(env_var_name).unwrap_or_default();

        {
            let _lock = dirs_mutex.lock().unwrap();
            if !env_paths.contains(&full_path) {
                env_paths.push_str(&format!("{}{}", delimiter, full_path));
            }
        }

        env::set_var(env_var_name, &env_paths);
    }

    Ok(true)
}

fn is_valid_dir_name(dir_name: &str) -> bool {
    // Add logic to validate directory names
    !dir_name.contains("..") && dir_name.chars().all(|c| c.is_alphanumeric() || c == '-' || c == '_')
}

fn sanitize_dir_name(dir_name: String) -> String {
    // Replace invalid characters with underscores
    dir_name.chars()
        .filter(|&c| c.is_alphanumeric() || c == '-' || c == '_' || c.is_whitespace())
        .collect::<String>()
        .replace(" ", "_")
}

fn is_directory_valid(dir_entry: &DirEntry) -> bool {
    // Placeholder for actual integrity check logic
    true
}

// Additional function to clean up directories
pub fn cleanup_directories(config: Vec<String>) -> Result<(), io::Error> {
    let env_var_name = "MY_PATH_ENV_VAR";
    let delimiter = ";";

    let mut env_paths = env::var(env_var_name).unwrap_or_default();
    for dir_name in config.into_iter() {
        if !is_valid_dir_name(&dir_name) {
            continue;
        }
        let sanitized_dir_name = sanitize_dir_name(dir_name);
        let full_path = format!("{}/{}", env::var("PATH_PREFIX").unwrap_or_else(|_| "PATH_PREFIX".into()), sanitized_dir_name);

        if env_paths.contains(&full_path) && Path::new(&full_path).exists() {
            // Remove directory
            fs::remove_dir_all(full_path)?;
            info!("Removed directory: {}", full_path);

            // Update environment variable
            env_paths = env_paths.replace(&format!("{}{}", delimiter, full_path), "");
        }
    }

    env::set_var(env_var_name, &env_paths);

    Ok(())
}
