#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include "third_party_encryption_library.h" // Assume this header provides necessary encryption functions

// Helper function to find the largest integer in a stream of integers efficiently
int* findLargestInteger(int fd, size_t *count) {
    int buffer_size = 1024; // Initial buffer size for reading data
    int *buffer = malloc(buffer_size * sizeof(int));
    if (!buffer) {
        perror("Failed to allocate memory");
        return NULL;
    }

    int largest = INT_MIN;
    size_t total_read = 0;

    while (1) {
        ssize_t bytes_read = read(fd, buffer + total_read, buffer_size - total_read);
        if (bytes_read == 0) { // End of file
            break;
        }
        if (bytes_read < 0) {
            perror("Read error");
            free(buffer);
            return NULL;
        }

        total_read += bytes_read;
        size_t num_ints = total_read / sizeof(int);

        for (size_t i = 0; i < num_ints; ++i) {
            if (*(buffer + i) > largest) {
                largest = *(buffer + i);
            }
        }

        // Process any remaining data in the buffer
        size_t remainder = total_read % sizeof(int);
        if (remainder != 0 && remainder >= sizeof(int)) {
            int last_int;
            memcpy(&last_int, buffer + num_ints * sizeof(int), sizeof(int));
            if (last_int > largest) {
                largest = last_int;
            }
        }

        // If the buffer is full, shift remaining data to the beginning
        if (remainder != 0 && remainder < sizeof(int)) {
            memmove(buffer, buffer + num_ints * sizeof(int), remainder);
            total_read = remainder;
        } else {
            total_read = 0;
        }
    }

    *count = total_read / sizeof(int);
    free(buffer);

    // Allocate memory for the largest integer
    int *largest_int_ptr = malloc(sizeof(int));
    if (!largest_int_ptr) {
        perror("Failed to allocate memory");
        return NULL;
    }
    *largest_int_ptr = largest;

    return largest_int_ptr;
}

// Main function as per the task requirements
