    EncryptionContext *enc_ctx = initialize_encryption_context();
    if (!enc_ctx) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        return NULL;
    }

    CipherObject *cipher_obj = perform_encryption_operation(enc_ctx, input_string, cmd_option);
    if (!cipher_obj) {
        fprintf(stderr, "Encryption operation failed\n");
        free_encryption_context(enc_ctx);
        return NULL;
    }

    // Find the largest integer from the data stream
    size_t count = 0;
    int *largest_integer_ptr = findLargestInteger(fd, &count);
    if (!largest_integer_ptr) {
        fprintf(stderr, "Failed to process data stream\n");
        free_cipher_object(cipher_obj);
        return NULL;
    }

    printf("Largest integer in the data stream: %d\n", *largest_integer_ptr);

    // Clean up
    free(largest_integer_ptr);

    return cipher_obj;
