static void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

static int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

