    static const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    size_t n = sizeof(alphanum) - 1;
    char *str = (char *)aligned_alloc(ALIGNMENT, length + 1);

    if (!str) return NULL;

    for (size_t i = 0; i < length; ++i) {
        str[i] = alphanum[rand() % n];
    }
    str[length] = '\0';

    return str;
}

static Item *create_item(int key, const char *string) {
    Item *item = (Item *)aligned_alloc(ALIGNMENT, sizeof(Item));
    if (!item) return NULL;

    item->key = key;
    strncpy(item->string, string, STRING_LENGTH);
    item->next = NULL;

    return item;
}

static Node *create_node(int id, double value) {
    Node *node = (Node *)aligned_alloc(ALIGNMENT, sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->id = id;
    node->items = NULL;
    node->children = NULL;
    node->next = NULL;

    return node;
}

void initialize_node_system(int num_nodes, int min_range, int max_range, int items_per_node) {
