        int rand_int = generate_random_int(min_range, max_range);
        double value = calculate_value_from_int(rand_int);

        Node *new_node = create_node(i, value);
        if (!new_node) break;

        new_node->items = NULL;
        Item **item_tail_ptr = &new_node->items;
        for (int j = 0; j < items_per_node; ++j) {
