    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[derive(Serialize, Deserialize, Debug)]
struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

type Cache<T> = RwLock<HashMap<String, T>>;

async fn configure_http_client(url: &str, use_proxy: Option<&str>, verify_tls: bool) -> Client {
    let mut builder = Client::builder();

    if let Some(proxy) = use_proxy {
        let proxy = reqwest::Proxy::all(proxy).unwrap();
        builder.proxy(proxy);
    }

    if !verify_tls {
        builder.danger_accept_invalid_certs(true);
    }

    builder
        .build()
        .expect("Failed to build HTTP client")
}

async fn send_pdu_data(client: &Client, url: &str, data: &[NFAPI_CRC_INDICATION_PDU_T]) -> Result<(), reqwest::Error> {
    let serialized = serde_json::to_string(data)?;
    info!("Sending data to {}", url);
    client
        .post(url)
        .body(serialized.clone())
        .send()
        .await?;

    Ok(())
}

