#include <cstdlib>
#include <ctime>
#include <algorithm>

struct record {
    int value;
};

class UnionFind {
public:
    UnionFind(int size) : parent(size), rank(size, 0) {
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int u) {
        if (u != parent[u]) 
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) 
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                ++rank[rootU];
            }
        }
    }

private:
    std::vector<int> parent, rank;
};

bool hasDuplicate(const std::vector<int>& vec) {
    std::sort(vec.begin(), vec.end());
    return !std::unique(vec.begin(), vec.end()) == vec.end();
}

int initializeAndCountDisjointPairs(size_t offsetSize, size_t keySize, int minValue, int maxValue) {
    long* offsets = new long[offsetSize];
    int* keys = new int[keySize];

    std::srand(std::time(nullptr));

    // Initialize offsets
    for (size_t i = 0; i < offsetSize; ++i) {
        offsets[i] = static_cast<long>(std::rand()) % static_cast<int>(offsetSize);
    }

    // Initialize keys without duplicates
    do {
        for (size_t i = 0; i < keySize; ++i) {
            keys[i] = minValue + std::rand() % (maxValue - minValue + 1);
        }
    } while (hasDuplicate(std::vector<int>(keys, keys + keySize)));

    // Initialize records with random values
    record* records = new record[keySize];
    for (size_t i = 0; i < keySize; ++i) {
        records[i].value = minValue + std::rand() % (maxValue - minValue + 1);
    }

    UnionFind uf(keySize);

    // Measure time and count disjoint pairs
    unsigned long long startTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
    for (size_t i = 0; i < keySize; ++i) {
        int offsetKey = keys[i];
        uf.unite(i, offsetKey);
    }
    unsigned long long endTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();

    double timeTakenMs = (endTime - startTime) / 1000.0;
    std::cout << "Time taken for pair checks: " << timeTakenMs << " ms" << std::endl;

    int disjointPairCount = keySize;
    for (size_t i = 0; i < keySize; ++i) {
        if (uf.find(i) == i) --disjointPairCount;
    }

    // Clean up
    delete[] offsets;
    delete[] keys;
    delete[] records;

    return disjointPairCount;
}

int main() {
    size_t offsetSize = 1000;
    size_t keySize = 500;
    int minValue = 1, maxValue = 1000;

    int disjointPairs = initializeAndCountDisjointPairs(offsetSize, keySize, minValue, maxValue);
    std::cout << "Total disjoint pairs: " << disjointPairs << std::endl;

    return 0;
}
