#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 10

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    point *points;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PointManager;

typedef struct {
    double *doubles;
    char **strings;
    PointManager *point_manager;
    size_t num_points;
} GeoDataManager;

unsigned long hash_point(point p) {
    return ((unsigned long)p.x << 32) | (unsigned long)p.y;
}

int point_exists(PointManager *manager, point new_point) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->points[i].x == new_point.x && manager->points[i].y == new_point.y) {
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void add_point(PointManager *manager, point new_point) {
    if (point_exists(manager, new_point)) {
        fprintf(stderr, "Point %d,%d already exists.\n", new_point.x, new_point.y);
        return;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        point *new_points = realloc(manager->points, new_capacity * sizeof(point));
        if (!new_points) {
            perror("Failed to allocate memory for points");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->points = new_points;
        manager->capacity = new_capacity;
    }

    manager->points[manager->count++] = new_point;

    pthread_mutex_unlock(&manager->lock);
}

void init_geo_data_manager(GeoDataManager *gdm, size_t initial_size) {
    gdm->doubles = malloc(initial_size * sizeof(double));
    if (!gdm->doubles) {
        perror("Failed to allocate memory for doubles");
        return;
    }

    gdm->strings = calloc(initial_size, sizeof(char *));
    if (!gdm->strings) {
        perror("Failed to allocate memory for strings");
        free(gdm->doubles);
        return;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        gdm->strings[i] = malloc(MAX_STRING_LENGTH);
        if (!gdm->strings[i]) {
            perror("Failed to allocate memory for strings");
            while (--i >= 0) free(gdm->strings[i]);
            free(gdm->doubles);
            free(gdm->strings);
            return;
        }
    }

    gdm->point_manager = malloc(sizeof(PointManager));
    if (!gdm->point_manager) {
        perror("Failed to allocate memory for point manager");
        for (size_t i = 0; i < initial_size; ++i) free(gdm->strings[i]);
        free(gdm->strings);
        free(gdm->doubles);
        return;
    }

    gdm->point_manager->points = NULL;
    gdm->point_manager->capacity = 0;
    gdm->point_manager->count = 0;
    pthread_mutex_init(&gdm->point_manager->lock, NULL);

    gdm->num_points = 0;
}

void free_geo_data_manager(GeoDataManager *gdm) {
    if (gdm->doubles) free(gdm->doubles);

    for (size_t i = 0; i < gdm->num_points; ++i) {
        free(gdm->strings[i]);
    }
    free(gdm->strings);

    pthread_mutex_destroy(&gdm->point_manager->lock);
    if (gdm->point_manager->points) free(gdm->point_manager->points);
    free(gdm->point_manager);
}

int main() {
    GeoDataManager gdm;
    init_geo_data_manager(&gdm, 10);

    point p1 = {10, 20};
    add_point(gdm.point_manager, p1);

    point p2 = {15, 25};
    add_point(gdm.point_manager, p2);

    // Duplicate point
    add_point(gdm.point_manager, p1);

    free_geo_data_manager(&gdm);
    return 0;
}
