#include <iostream>
#include <vector>
#include <unordered_set>
#include <random>
#include <chrono>
#include <sys/wait.h>
#include <unistd.h>
#include <cstring>
#include <fstream>

class UnionFind {
private:
    std::vector<int> parent, rank;

public:
    UnionFind(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i)
            parent[i] = i;
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV]) {
                parent[rootV] = rootU;
            } else if (rank[rootU] < rank[rootV]) {
                parent[rootU] = rootV;
            } else {
                parent[rootV] = rootU;
                rank[rootU]++;
            }
        }
    }

    int countDisjointSets() const {
        int disjointCount = 0;
        for (int i = 0; i < parent.size(); ++i) {
            if (parent[i] == i)
                disjointCount++;
        }
        return disjointCount;
    }
};

bool executeCommand(const std::string& command, bool& success) {
    pid_t pid = fork();
    if (pid == -1) {
        std::cerr << "Fork failed" << std::endl;
        return false;
    } else if (pid > 0) { // Parent process
        int status;
        wait(&status);
        success = WIFEXITED(status) && WEXITSTATUS(status) == 0;
    } else { // Child process
        execlp(command.c_str(), command.c_str(), nullptr);
        exit(EXIT_FAILURE); // If exec fails
    }
    return true;
}

void logPerformance(const std::string& message, const std::chrono::milliseconds& duration) {
    std::ofstream logFile("performance.log", std::ios_base::app);
    if (logFile.is_open()) {
        logFile << message << ": " << duration.count() << " ms\n";
        logFile.close();
    }
}

void processCommandsAndAnalyzePairs(const std::vector<std::string>& commands, int numKeys, int minValue, int maxValue) {
    // Initialize keys with unique random values
    std::unordered_set<int> uniqueValues;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    std::vector<int> keys(numKeys);
    for (int i = 0; i < numKeys; ++i) {
        int val;
        do {
            val = dis(gen);
        } while (!uniqueValues.insert(val).second);
        keys[i] = val;
    }

    // Union-Find to find disjoint pairs
    UnionFind uf(numKeys);
    for (size_t i = 0; i < keys.size(); ++i) {
        for (size_t j = i + 1; j < keys.size(); ++j) {
            auto start = std::chrono::high_resolution_clock::now();
            uf.unite(keys[i], keys[j]);
            auto end = std::chrono::high_resolution_clock::now();
            logPerformance("Disjoint Pair Check", std::chrono::duration_cast<std::chrono::milliseconds>(end - start));
        }
    }

    int disjointCount = uf.countDisjointSets();

    // Execute commands concurrently
    for (const auto& cmd : commands) {
        bool success;
        executeCommand(cmd, success);
        std::cout << "Command: " << cmd << " executed successfully: " << success << "\n";
    }
}

int main() {
    std::vector<std::string> commands = {"ls", "echo Hello World"};
    processCommandsAndAnalyzePairs(commands, 10, 1, 100);
    return 0;
}
