    for (auto& data : data_batch) {
        if (!encryptOrDecrypt(data)) {
            internal_errors++;
        } else {
            requests_count++;
        }
    }

    // Report number of processed requests, sessions, and errors
    std::cout << "Requests: " << requests_count << "\n";
    std::cout << "Active Sessions: " << active_sessions << "\n";
