bool CryptoApp::encryptOrDecrypt(std::vector<unsigned char>& data) {
    auto ctx = createContext();
    if (!ctx) {
        logAudit("Failed to create cipher context");
        return false;
    }

    // Setup encryption/decryption
    const EVP_CIPHER* cipher = encrypt_mode ? EVP_aes_256_cbc() : EVP_aes_256_cbc();
    unsigned char key[32] = { /* ... */ };
    unsigned char iv[16] = { /* ... */ };

    if (encrypt_mode) {
        EVP_EncryptInit_ex(ctx.get(), cipher, nullptr, key, iv);
    } else {
        EVP_DecryptInit_ex(ctx.get(), cipher, nullptr, key, iv);
    }

    // Encrypt/Decrypt data
    std::vector<unsigned char> output(data.size() + EVP_CIPHER_block_size(cipher));
    int out_len;

    if (encrypt_mode) {
        EVP_EncryptUpdate(ctx.get(), output.data(), &out_len, data.data(), data.size());
    } else {
        EVP_DecryptUpdate(ctx.get(), output.data(), &out_len, data.data(), data.size());
    }

    // Finalize operation
    int final_out_len;
    if (encrypt_mode) {
        EVP_EncryptFinal_ex(ctx.get(), output.data() + out_len, &final_out_len);
    } else {
        EVP_DecryptFinal_ex(ctx.get(), output.data() + out_len, &final_out_len);
    }

    out_len += final_out_len;
    output.resize(out_len);

    data = std::move(output);
    return true;
}

void CryptoApp::logAudit(const std::string& message) {
    // Interface with external logging system
    sandesh_client_.Log(message);
}

