#include <iostream>
#include <vector>
#include <unordered_set>
#include <random>
#include <chrono>
#include <fstream>
#include <algorithm>
#include <numeric>

struct Record {
    int value;
    long offset;
    double weight;
};

class UnionFind {
public:
    explicit UnionFind(int size) : parent(size), rank(size, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unionSets(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);

        if (rootU != rootV) {
            if (rank[rootU] > rank[rootV])
                parent[rootV] = rootU;
            else if (rank[rootU] < rank[rootV])
                parent[rootU] = rootV;
            else {
                parent[rootV] = rootU;
                rank[rootU]++;
            }
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

void logMessage(const std::string &message) {
    std::cout << message << std::endl; // Replace with a robust logging system
}

int initializeAndProcess(std::size_t size, const std::pair<int, int>& keyRange,
                         const std::pair<long, long>& offsetRange,
                         const std::pair<double, double>& weightRange) {
    std::default_random_engine generator;
    std::uniform_int_distribution<int> keyDist(keyRange.first, keyRange.second);
    std::uniform_int_distribution<long> offsetDist(offsetRange.first, offsetRange.second);
    std::uniform_real_distribution<double> weightDist(weightRange.first, weightRange.second);

    Record* records = new Record[size];
    std::unordered_set<int> uniqueKeys;
    auto start = std::chrono::high_resolution_clock::now();

    for (std::size_t i = 0; i < size; ++i) {
        int key = keyDist(generator);
        while (uniqueKeys.count(key)) {
            key = keyDist(generator); // Regenerate key to avoid duplicates
        }
        uniqueKeys.insert(key);

        long offset = offsetDist(generator);
        double weight = weightDist(generator);

        records[i] = { static_cast<int>(i), offset, std::nextafter(weight, std::numeric_limits<double>::max()) };
    }

    auto endInit = std::chrono::high_resolution_clock::now();
    logMessage("Initialization completed in " + 
               std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(endInit - start).count()) + " ms");

    UnionFind uf(size);
    int disjointPairs = 0;

    auto startUnionFind = std::chrono::high_resolution_clock::now();
    for (std::size_t i = 0; i < size; ++i) {
        for (std::size_t j = i + 1; j < size; ++j) {
            if (uf.find(i) != uf.find(j)) {
                uf.unionSets(i, j);
                disjointPairs++;
            }
        }
    }
    auto endUnionFind = std::chrono::high_resolution_clock::now();
    logMessage("Pair checking completed in " + 
               std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(endUnionFind - startUnionFind).count()) + " ms");

    delete[] records;

    // Serialize results to a file
    std::ofstream outFile("results.txt");
    outFile << "Total disjoint pairs: " << disjointPairs << std::endl;
    outFile.close();

    return disjointPairs;
}

int main() {
