// Function to resolve hostname into IP address
int resolve_hostname(const char *hostname, u_char *ip_buffer) {
    struct addrinfo hints, *res, *ressave;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4 addresses only

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    ressave = res;

    while (res != NULL) {
        void *addr;
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);

        inet_ntop(AF_INET, addr, ip_buffer, INET_ADDRSTRLEN);
        freeaddrinfo(ressave); // Free the linked list
        return 0; // Success
    }

    freeaddrinfo(ressave); // Ensure resources are freed if no addresses found
    return -1;
}

