// Function to retrieve a cipher key from the cache or load it
CipherKey get_cipher_key(KeyCache *cache, const unsigned char *key_data, int key_length) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (memcmp(cache->keys[i].key, key_data, key_length) == 0) {
            cache->hit_count++;
            pthread_mutex_unlock(&cache->lock);
            return cache->keys[i];
        }
    }
    cache->miss_count++;
    pthread_mutex_unlock(&cache->lock);

    // Load the key if not found in cache
    CipherKey new_key = { .key = key_data, .key_length = key_length };
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->keys[i].key == NULL) {
            cache->keys[i] = new_key;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return new_key;
}

