    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free resources
    EVP_CIPHER_free(cipher_type);
    free(key_cache);

    log_message("Processing completed.");
    return 0;
}

