#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>
#include <pthread.h>

#define MAX_INTEGER 1000
#define BUFFER_SIZE 256

typedef enum {
    SUCCESS = 0,
    ERROR_DNS_RESOLUTION_FAILED,
    ERROR_INVALID_IP,
    ERROR_INVALID_INPUT,
    ERROR_EMPTY_LIST
} StatusCode;

// Thread-safe logging function
void log_error(const char *message) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    fprintf(stderr, "%s\n", message);

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);
}

// Helper function to find and print the largest integer
void find_and_print_largest(int *numbers, size_t count) {
    if (count == 0) {
        printf("No valid integers were provided.\n");
        return;
    }

    int max = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

// DNS resolution function
StatusCode resolve_dns(const char *hostname) {
    struct hostent *host_info;
    host_info = gethostbyname(hostname);

    if (host_info == NULL) {
        log_error("DNS resolution failed");
        return ERROR_DNS_RESOLUTION_FAILED;
    }

    // Resolve to IP address
    void *addr_list;
    addr_list = &host_info->h_addr_list[0];

    struct in_addr ipv4_address;
    int result = inet_ntop(AF_INET, addr_list, (char *)&ipv4_address.s_addr, INET_ADDRSTRLEN);

    if (result == NULL) {
        log_error("Invalid IP address");
        return ERROR_INVALID_IP;
    }

    printf("Resolved IP: %s\n", ipv4_address.s_addr);
    return SUCCESS;
}

// Main function to resolve DNS and process data
StatusCode resolveAndProcessData(const char *hostname) {
    // Resolve DNS
    StatusCode status = resolve_dns(hostname);
    if (status != SUCCESS) {
        return status;
    }

    int numbers[BUFFER_SIZE];
    size_t count = 0;

    printf("Enter integers separated by space: ");
    char input[BUFFER_SIZE];
    if (!fgets(input, sizeof(input), stdin)) {
        log_error("Failed to read from standard input");
        return ERROR_INVALID_INPUT;
    }

    // Tokenize and validate input
    char *token = strtok(input, " \n");
    while (token != NULL && count < BUFFER_SIZE) {
        int num = atoi(token);

        if (num > MAX_INTEGER) {
            log_error("Integer exceeds maximum value");
        } else {
            numbers[count++] = num;
        }

        token = strtok(NULL, " \n");
    }

    // Find and print the largest integer
    find_and_print_largest(numbers, count);

    return count == 0 ? ERROR_EMPTY_LIST : SUCCESS;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    StatusCode result = resolveAndProcessData(argv[1]);

    switch (result) {
        case SUCCESS:
            printf("All operations completed successfully.\n");
            break;
        case ERROR_DNS_RESOLUTION_FAILED:
            fprintf(stderr, "Failed to resolve DNS.\n");
            break;
        case ERROR_INVALID_IP:
            fprintf(stderr, "Invalid IP address encountered.\n");
            break;
        case ERROR_INVALID_INPUT:
            fprintf(stderr, "Failed to read valid input from standard input.\n");
            break;
        case ERROR_EMPTY_LIST:
            fprintf(stderr, "No valid integers were provided.\n");
            break;
    }

    return result == SUCCESS ? EXIT_SUCCESS : EXIT_FAILURE;
}
```']

