void initializeArrays(long *offsets, int *keys, record **records, size_t count, const char *prefix) {
    if (count == 0) return;

    offsets = malloc(count * sizeof(long));
    keys = malloc(count * sizeof(int));
    records = malloc(count * sizeof(record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

