    size_t total_memory_used = 0;
    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % INT_RANGE_MAX;
        keys[i] = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;

        records[i] = malloc(sizeof(record));
