            exit(EXIT_FAILURE);
        }

        snprintf(records[i]->stringRep, sizeof(records[i]->stringRep), "%s_%ld_%lu", prefix, i, (unsigned long)time(NULL));

        records[i]->itemStruct = malloc(sizeof(item));
        if (!records[i]->itemStruct) {
            fprintf(stderr, "Memory allocation for item failed\n");
            exit(EXIT_FAILURE);
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
