        records[i]->intValue = keys[i];
        records[i]->itemStruct->size = sizeof(double);
        records[i]->itemStruct->data.value = (records[i]->intValue + seconds) / 2.0;

        total_memory_used += sizeof(record) + sizeof(item);

        if (total_memory_used > MAX_MEMORY_USAGE) {
            free(records[i]);
            records[i] = NULL;
            --i; // Retry this index after freeing memory
        }
    }

    callJavaMethod(count); // Call Java method upon completion

    for (size_t i = 0; i < count; ++i) {
        if (records[i]) {
            free(records[i]->itemStruct);
            free(records[i]);
        }
    }
}

