### Java Code:

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class RemoteConnection {

    private static final int CONNECTION_TIMEOUT = 5000; // 5 seconds

    public void connectToRemote(String address, int port) {
        try (SocketChannel channel = SocketChannel.open()) {
            channel.configureBlocking(false);
            if (!channel.connect(new InetSocketAddress(address, port))) {
                if (!waitForConnection(channel)) {
                    System.out.println("Failed to connect within timeout.");
                    return;
                }
            }

            handleConnectionStateChanges(channel);

            // Manage concurrent connections if necessary
        } catch (IOException e) {
            System.err.println("I/O error during connection: " + e.getMessage());
        }
    }

    private boolean waitForConnection(SocketChannel channel) throws InterruptedException, IOException {
        long deadline = System.currentTimeMillis() + CONNECTION_TIMEOUT;
        while (!channel.finishConnect()) {
            if (System.currentTimeMillis() > deadline) return false;

            try {
                Thread.sleep(50); // Small delay to prevent busy waiting
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw e;
            }
        }
        return true;
    }

    private void handleConnectionStateChanges(SocketChannel channel) throws IOException {
        if (channel.finishConnect()) {
            System.out.println("Connected successfully.");
            // Handle data exchange or further processing here
        } else {
            System.err.println("Failed to establish connection.");
        }

        // Additional state change management logic can be implemented here.
    }
}
