#define MAX_MEMORY 1048576 // 1 MB

typedef struct {
    long *offset_ptr;
    int key_ref;
    char *key_string_buffer;
    const char *hex_offset_str;
} record;

void free_resources(long *offsets, int *keys, record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].key_string_buffer != NULL) {
            free(records[i].key_string_buffer);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

int allocate_memory(size_t *array_size, long **offsets, int **keys, record **records) {
    size_t total_memory = 0;

    for (size_t size = 1; size <= MAX_MEMORY / 100; ++size) {
        size_t offsets_memory = sizeof(long) * size;
        size_t keys_memory = sizeof(int) * size;

        // Calculate memory needed for records array
        size_t record_base_memory = sizeof(record) * size;
        size_t key_string_buffers_memory = 0;
        size_t hex_strings_memory = 0;

        char temp_key_str[12]; // Enough space to store any int as a string + null-terminator

        for (size_t i = 0; i < size; ++i) {
            snprintf(temp_key_str, sizeof(temp_key_str), "%d", i);
            key_string_buffers_memory += strlen(temp_key_str) + 1;

            char temp_hex_str[11]; // Enough space to store a long in hex format
            snprintf(temp_hex_str, sizeof(temp_hex_str), "0x%lx", i);
            hex_strings_memory += strlen(temp_hex_str) + 1;
        }

        size_t records_memory = record_base_memory + key_string_buffers_memory + hex_strings_memory;

        total_memory = offsets_memory + keys_memory + records_memory;

        if (total_memory <= MAX_MEMORY) {
            *array_size = size;
            *offsets = malloc(offsets_memory);
            *keys = malloc(keys_memory);
            *records = malloc(records_memory);

            if (!(*offsets) || !(*keys) || !(*records)) {
                free_resources(NULL, NULL, NULL, 0);
                return -1;
            }

            for (size_t i = 0; i < size; ++i) {
                (*offsets)[i] = i;
                (*keys)[i] = i;

                record *rec = &(*records)[i];
                rec->offset_ptr = &((*offsets)[i]);
                rec->key_ref = (*keys)[i];

                size_t key_str_length = snprintf(temp_key_str, sizeof(temp_key_str), "%d", i) + 1;
                char *key_buffer = (char *)malloc(key_str_length);
                if (!key_buffer) {
                    free_resources(*offsets, *keys, *records, size);
                    return -1;
                }
                strncpy(key_buffer, temp_key_str, key_str_length);
                rec->key_string_buffer = key_buffer;

                char hex_str[11];
                snprintf(hex_str, sizeof(hex_str), "0x%lx", i);
                size_t hex_str_length = strlen(hex_str) + 1;
                const char *hex_ptr = (const char *)malloc(hex_str_length);
                if (!hex_ptr) {
                    free_resources(*offsets, *keys, *records, size);
                    return -1;
                }
                memcpy((void *)hex_ptr, hex_str, hex_str_length);
                rec->hex_offset_str = hex_ptr;

            }

            return 0; // Success
        }
    }

    return -2; // Memory budget exceeded without finding a valid size
}

int main() {
    size_t array_size;
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (allocate_memory(&array_size, &offsets, &keys, &records) != 0) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    // Utilize the arrays here...

    free_resources(offsets, keys, records, array_size);

    return EXIT_SUCCESS;
}
