#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 32
#define KEY_RANGE_MIN 0
#define KEY_RANGE_MAX INT_MAX

typedef struct {
    long* offsets;
    int* keys;
    struct record* records;
} Data;

typedef struct {
    long* offset_ptr;
    int key;
    char* key_str;
    char* hex_offset_str;
} record;

char* generate_hex_string(long value) {
    static char buffer[BUFFER_SIZE];
    snprintf(buffer, BUFFER_SIZE, "%lx", (unsigned long)value);
    return buffer;
}

int validate_memory_usage(size_t total_memory, size_t max_memory) {
    return total_memory <= max_memory;
}

void free_resources(Data* data) {
    if (data->offsets) free(data->offsets);
    if (data->keys) free(data->keys);
    if (data->records) {
        for (size_t i = 0; i < sizeof(data->records)/sizeof(record); ++i) {
            free(data->records[i].key_str);
            // Hex string is static, so no need to free
        }
        free(data->records);
    }
}

Data* allocate_data(size_t size, long threshold, size_t max_memory) {
    if (size > MAX_RECORDS || size == 0) return NULL;

    Data* data = malloc(sizeof(Data));
    if (!data) return NULL;

    long sum_offsets = 0;
    for (long i = 0; i < size && sum_offsets + i <= threshold; ++i) {
        sum_offsets += i;
    }
    size_t offset_size = sum_offsets * sizeof(long);
    data->offsets = malloc(offset_size);
    if (!data->offsets) {
        free(data);
        return NULL;
    }

    for (size_t i = 0; i < size && (long)i <= threshold; ++i) {
        data->offsets[i] = i;
    }

    data->keys = malloc(size * sizeof(int));
    if (!data->keys) {
        free(data->offsets);
        free(data);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        data->keys[i] = i;
        if (data->keys[i] < KEY_RANGE_MIN || data->keys[i] > KEY_RANGE_MAX) {
            free_resources(data);
            return NULL;
        }
    }

    size_t record_size = size * sizeof(record);
    data->records = malloc(record_size);
    if (!data->records) {
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        data->records[i].offset_ptr = &data->offsets[i];
        data->records[i].key = data->keys[i];

        data->records[i].key_str = malloc(BUFFER_SIZE * sizeof(char));
        if (!data->records[i].key_str) {
            free_resources(data);
            return NULL;
        }
        snprintf(data->records[i].key_str, BUFFER_SIZE, "%d", data->keys[i]);

        data->records[i].hex_offset_str = generate_hex_string(*data->records[i].offset_ptr);
    }

    size_t total_memory = offset_size + size * sizeof(int) + record_size + size * BUFFER_SIZE;
    if (!validate_memory_usage(total_memory, max_memory)) {
        free_resources(data);
        return NULL;
    }

    return data;
}

void validate_data(Data* data) {
    if (!data || !data->offsets || !data->keys || !data->records) {
        fprintf(stderr, "Error: Data pointers are not properly initialized.\n");
        return;
    }
    for (size_t i = 0; i < sizeof(data->records)/sizeof(record); ++i) {
        if (!data->records[i].key_str) {
            fprintf(stderr, "Error: Key string buffer at index %zu is not initialized.\n", i);
        }
    }
}

int main() {
    size_t max_memory = 1024 * 1024; // Example limit in bytes
    long threshold = 100;
    Data* data = allocate_data(50, threshold, max_memory);

    if (data) {
        validate_data(data);
        free_resources(data);
    } else {
        fprintf(stderr, "Error: Failed to allocate data.\n");
    }

    return 0;
}
