#define MAX_CONTENT_SIZE 1024
#define MEMORY_BUDGET 10240 // Example memory budget

typedef struct file_data {
    char *content;
    int length;
} file_data;

typedef struct inode {
    int inode_id;
    file_data *file_data_ptr;
    struct directory_entry *directory_entry_ptr;
} inode;

typedef struct directory_entry {
    inode *inode_ref;
    char name[256];
} directory_entry;

// Function to allocate memory for an array of inodes
int allocate_inodes(inode **inodes, int num_inodes) {
    size_t total_size = sizeof(inode) * num_inodes + sizeof(file_data) * num_inodes + sizeof(directory_entry) * num_inodes;

    if (total_size > MEMORY_BUDGET) {
        return -1; // Exceeds memory budget
    }

    *inodes = (inode *)malloc(total_size);
    if (!*inodes) return -1;

    char *ptr = (char *)(*inodes + num_inodes);

    for (int i = 0; i < num_inodes; ++i, (*inodes)++) {
        (*inodes)->file_data_ptr = (file_data *)ptr;
        ptr += sizeof(file_data);

        (*inodes)->file_data_ptr->content = (char *)malloc(MAX_CONTENT_SIZE);
        if (!(*inodes)->file_data_ptr->content) return -1;

        memset((*inodes)->file_data_ptr->content, 0, MAX_CONTENT_SIZE);
        (*inodes)->file_data_ptr->length = 0;

        (*inodes)->directory_entry_ptr = (directory_entry *)ptr;
        ptr += sizeof(directory_entry);

        (*inodes)->inode_id = -1; // Initialize with invalid id
    }

    return 0;
}

// Function to free allocated inodes and associated data
void free_inodes(inode *inodes, int num_inodes) {
    for (int i = 0; i < num_inodes; ++i, ++inodes) {
        if (inodes->file_data_ptr) {
            free(inodes->file_data_ptr->content);
            inodes->file_data_ptr->content = NULL;
        }
    }

    free(inodes); // Assuming all allocations are at the beginning
}

// Function to ensure unique inode_id and initialize directory entry name
int add_or_update_inode(inode *inodes, int num_inodes, int new_inode_id, const char *name) {
    for (int i = 0; i < num_inodes; ++i) {
        if (inodes[i].inode_id == -1 || inodes[i].inode_id == new_inode_id) {
            // Check uniqueness
            for (int j = 0; j < num_inodes; ++j) {
                if (i != j && inodes[j].inode_id == new_inode_id) {
                    return -1; // ID conflict found
                }
            }

            inodes[i].inode_id = new_inode_id;
            strncpy(inodes[i].directory_entry_ptr->name, name, sizeof(inodes[i].directory_entry_ptr->name));
            inodes[i].directory_entry_ptr->name[sizeof(inodes[i].directory_entry_ptr->name) - 1] = '\0';

            return i; // Return index of updated or added inode
        }
    }

    return -1; // No space to add new inode
}

// Main function for demonstration purposes
int main() {
    int num_inodes = 5;
    inode *inodes;

    if (allocate_inodes(&inodes, num_inodes) != 0) {
        fprintf(stderr, "Failed to allocate inodes.\n");
        return EXIT_FAILURE;
    }

    // Add or update an inode
    if (add_or_update_inode(inodes, num_inodes, 1, "file.txt") == -1) {
        fprintf(stderr, "Failed to add or update inode.\n");
    }

    free_inodes(inodes, num_inodes);

    return EXIT_SUCCESS;
}
