#define MAX_MEMORY_BUDGET 1048576 // 1 MB

typedef struct {
    long *offset;
    int key_ref;
    char *key_str_buffer;
    const char *hex_offset;
} record;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char* message) {
    time_t now = time(NULL);
    printf("[%s] ERROR: %s\n", ctime(&now), message);
}

long calculate_required_memory(size_t size) {
    // Calculate the total memory required for all allocations
    long int mem_for_long_array = sizeof(long) * size;
    long int mem_for_int_array = sizeof(int) * size;
    long int mem_for_record_array = 0;

    for (size_t i = 0; i < size; ++i) {
        char buffer[12]; // Enough to hold any integer in decimal representation
        snprintf(buffer, sizeof(buffer), "%d", i);
        mem_for_record_array += sizeof(record) + strlen(buffer) + 1 + 17; // 16 digits for hex + null terminator
    }

    return mem_for_long_array + mem_for_int_array + mem_for_record_array;
}

void free_resources(long *offsets, int *keys, record *records, size_t size) {
    if (offsets) free(offsets);
    if (keys) free(keys);

    for (size_t i = 0; i < size; ++i) {
        if (records[i].key_str_buffer) free(records[i].key_str_buffer);
    }
    if (records) free(records);
}

record* allocate_records(size_t size, long *offsets, int *keys) {
    record *records = NULL;
    if (pthread_mutex_lock(&lock) != 0) {
        log_error("Mutex lock failed");
        return NULL;
    }

    records = (record *)malloc(sizeof(record) * size);
    if (!records) {
        log_error("Failed to allocate memory for records array");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char hex_buffer[17]; // 16 digits for a 64-bit number + null terminator

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = &offsets[i];
        records[i].key_ref = keys[i];

        char key_str[12];
        snprintf(key_str, sizeof(key_str), "%d", keys[i]);
        records[i].key_str_buffer = (char *)malloc(strlen(key_str) + 1);
        if (!records[i].key_str_buffer) {
            log_error("Failed to allocate memory for key string buffer");
            free_resources(offsets, keys, records, size);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        strcpy(records[i].key_str_buffer, key_str);

        snprintf(hex_buffer, sizeof(hex_buffer), "%lx", offsets[i]);
        records[i].hex_offset = hex_buffer;
    }

    pthread_mutex_unlock(&lock);
    return records;
}

record* create_structures(size_t size) {
    if (calculate_required_memory(size) > MAX_MEMORY_BUDGET) {
        log_error("Required memory exceeds budget");
        return NULL;
    }

    long *offsets = (long *)malloc(sizeof(long) * size);
    int *keys = (int *)malloc(sizeof(int) * size);

    if (!offsets || !keys) {
        log_error("Failed to allocate initial arrays");
        free_resources(offsets, keys, NULL, size);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    record *records = allocate_records(size, offsets, keys);

    if (!records) {
        free_resources(offsets, keys, NULL, size);
    }

    return records;
}

int main() {
    size_t size = 1000; // Example size
    record *records = create_structures(size);
    if (records) {
        // Use the structures as needed...
        free_resources(NULL, NULL, records, size);
    }
    return 0;
}
```

