// Helper function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__linux__)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    // Fallback for other platforms
    ptr = malloc(size + alignment - 1);
    if (!ptr) return NULL;
    uintptr_t addr = (uintptr_t)ptr + alignment - 1;
    addr -= addr % alignment;
    ptr = (void*)addr;
#endif
    return ptr;
}

// Function to hash an integer key into a string value
char* hash_key_to_value(int key) {
    size_t len = snprintf(NULL, 0, "value_%d", key);
    char *value = malloc(len + 1);
    if (value) {
        snprintf(value, len + 1, "value_%d", key);
    }
    return value;
}

