char* generate_random_type_string(size_t length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    size_t max_index = (sizeof(charset) - 1);
    char *random_str = malloc(length + 1);
    if (!random_str) return NULL;

    for (size_t i = 0; i < length; i++) {
        random_str[i] = charset[rand() % max_index];
    }
    random_str[length] = '\0';
    return random_str;
}

// Function to create and initialize a record
Record* create_record(int key) {
    Record *record = aligned_alloc(64, sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->value = hash_key_to_value(key);
    record->fields = NULL;
    record->next = NULL;

    // Initialize fields with random names and types
    for (int i = 0; i < 3; ++i) {  // Assuming 3 fields per record for demonstration
        Field *field = aligned_alloc(64, sizeof(Field));
        if (!field) return NULL;

        field->name = generate_random_type_string(8); // Fixed length name
        field->type = rand() % (FIELD_TYPE_STRING + 1);
        field->next = record->fields;
        record->fields = field;
    }

    return record;
}

// Function to create and initialize a table with records
Table* create_table(int num_records) {
    Table *table = aligned_alloc(64, sizeof(Table));
    if (!table) return NULL;

    table->head = NULL;

    for (int i = 0; i < num_records; ++i) {
        Record *new_record = create_record(i);
        if (!new_record) {
            // Handle memory allocation failure
            printf("Failed to allocate memory for record %d\n", i);
            continue;
        }

        new_record->next = table->head;
        table->head = new_record;
    }

    return table;
}

// Function to verify the integrity of allocated data
int verify_table_integrity(Table *table) {
    if (!table) return 0;

    Record *current = table->head;
    while (current) {
        if (current->key < 0 || current->value == NULL) {
            printf("Integrity check failed for record with key %d\n", current->key);
