    } else {
        printf("Example test passed: Data integrity verified\n");
    }

    // Clean up allocated memory
    Record *record = table->head;
    while (record) {
        Field *field = record->fields;
        while (field) {
            free(field->name);
            Field *temp_field = field;
            field = field->next;
            free(temp_field);
        }
        char *value = record->value;
        Record *temp_record = record;
        record = record->next;
        free(value);
        free(temp_record);
    }

    free(table);
}

// Main function to demonstrate the testing framework
int main() {
