#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

struct record {
    int value;
};

typedef struct {
    long *offsets;
    int *keys;
    struct record *records;
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
    unsigned int seed;
} MemoryManager;

// Helper function to align a given size up to the next multiple of alignment
size_t align_up(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

int allocate_memory(MemoryManager *manager, size_t num_offsets, size_t num_keys, 
                    size_t num_records, int value_min, int value_max, unsigned int seed) {

    manager->num_offsets = num_offsets;
    manager->num_keys = num_keys;
    manager->num_records = num_records;
    manager->seed = seed;

    // Calculate aligned sizes
    const size_t alignment = 16;
    size_t offsets_size = align_up(num_offsets * sizeof(long), alignment);
    size_t keys_size = align_up(num_keys * sizeof(int), alignment);
    size_t records_size = align_up(num_records * sizeof(struct record), alignment);

    size_t total_size = offsets_size + keys_size + records_size;

    // Attempt allocation
    void *memory = malloc(total_size);
    if (!memory) {
        fprintf(stderr, "Initial memory allocation failed.\n");
        return -1;
    }

    // Align each segment within the allocated block
    manager->offsets = (long *)align_up((uintptr_t)memory + offsets_size, alignment);
    memory = (char *)manager->offsets - offsets_size;

    manager->keys = (int *)align_up((uintptr_t)memory + keys_size, alignment);
    memory = (char *)manager->keys - keys_size;

    manager->records = (struct record *)align_up((uintptr_t)memory + records_size, alignment);

    // Seed random number generator
    srand(seed);

    // Initialize `record` values with deterministic randomness
    for (size_t i = 0; i < num_records; ++i) {
        int value = value_min + rand() % (value_max - value_min + 1);
        manager->records[i].value = value;

        // Verify integrity of allocated data
        if (manager->records[i].value < value_min || manager->records[i].value > value_max) {
            fprintf(stderr, "Data integrity check failed: record %zu has invalid value.\n", i);
            free(memory);
            return -1;
        }
    }

    printf("Memory allocation successful. Number of records: %zu\n", num_records);
    return 0; // Success
}

int main() {
    MemoryManager manager;
    unsigned int seed = 12345; // Custom seed for testing

    if (allocate_memory(&manager, 5, 10, 3, 1, 100, seed) == 0) {
        printf("Allocation succeeded. Records:\n");
        for (size_t i = 0; i < manager.num_records; ++i) {
            printf("Record %zu: value = %d\n", i, manager.records[i].value);
        }
    }

    // Free allocated memory
    free(manager.offsets - align_up(sizeof(long) * 5, 16) / sizeof(long));

    return 0;
}
```

This code defines a `MemoryManager` structure to manage dynamic allocations for offsets, keys, and records. It attempts to allocate memory with specific alignment requirements in a single allocation call using `malloc`, ensuring the entire block is aligned as required by each segment's constraints. The function initializes `record` values deterministically based on a custom seed for reproducibility and verifies data integrity before returning. If initial allocation fails, an error message is printed, and it returns `-1`. After successful allocations, memory can be freed appropriately.']

