```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RANGES 10000

typedef struct {
    long min;
    long max;
    int inclusive_min; // 1 if inclusive, 0 if exclusive
    int inclusive_max;
} Range;

typedef struct {
    Range ranges[MAX_RANGES];
    size_t count;
} RangeSet;

typedef struct {
    int key;
} Record;

// Function to initialize a random number generator
void init_random() {
    srand(time(NULL));
}

// Generate a random long integer within a given range
long generate_random_long(Range r) {
    if (r.inclusive_min && r.inclusive_max) {
        return rand() % (r.max - r.min + 1) + r.min;
    } else if (r.inclusive_min) {
        return rand() % (r.max - r.min) + r.min;
    } else if (r.inclusive_max) {
        return rand() % (r.max - r.min + 2) + r.min - 1;
    } else {
        return rand() % (r.max - r.min + 3) + r.min - 2;
    }
}

// Generate a random float within a given range
float generate_random_float(Range r) {
    double min = r.inclusive_min ? (double)r.min : (double)(r.min + 1);
    double max = r.inclusive_max ? (double)r.max : (double)(r.max - 1);
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Merge overlapping ranges
void merge_ranges(RangeSet* rs) {
    if (rs->count < 2) return;

    qsort(rs->ranges, rs->count, sizeof(Range), [](const void* a, const void* b) {
        Range *ra = (Range *)a;
        Range *rb = (Range *)b;
        if (ra->min != rb->min)
            return ra->min - rb->min;
        return ra->max - rb->max;
    });

    size_t new_count = 0;
    for (size_t i = 0; i < rs->count; ++i) {
        Range current = rs->ranges[i];
        while (new_count > 0 && 
               (current.min <= rs->ranges[new_count - 1].max ||
                (rs->ranges[new_count - 1].inclusive_max && current.inclusive_min))) {
            if (current.max < rs->ranges[new_count - 1].max) {
                rs->ranges[new_count - 1].max = current.max;
                rs->ranges[new_count - 1].inclusive_max = current.inclusive_max;
            }
            current = rs->ranges[++new_count];
        }
        rs->ranges[new_count++] = current;
    }
    rs->count = new_count;
}

// Split a range into non-overlapping sub-ranges
void split_range(Range r, Range* out_ranges, size_t max_splits) {
    // Example logic for splitting; can be customized
    if (r.max - r.min < 2 || max_splits == 0) {
        out_ranges[0] = r;
        return;
    }

    size_t mid = (r.max + r.min) / 2;
    out_ranges[0] = (Range){.min = r.min, .max = mid, .inclusive_min = r.inclusive_min, .inclusive_max = 0};
    out_ranges[1] = (Range){.min = mid + 1, .max = r.max, .inclusive_min = 0, .inclusive_max = r.inclusive_max};
}

// Initialize and manage records
void initialize_records(Record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Range sample_range = {0, 100, 1, 1}; // Example range
        records[i].key = generate_random_long(sample_range);
    }
}

