```java
import java.io.BufferedReader;
import java.io.File;
import java.io.InputStreamReader;

public class CommandExecutor {

    public static void executeCommand(String command, String[] envp, File dir) {
        try {
            File outputFile = new File(dir, "output.txt");
            if (outputFile.exists()) {
                boolean deleted = outputFile.delete();
                if (!deleted) {
                    System.err.println("Failed to delete the output file.");
                    return;
                }
            }

            Process process = Runtime.getRuntime().exec(command, envp, dir);

            // Reading output
            BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = stdOutput.readLine()) != null) {
                System.out.println("Output: " + line);
            }

            // Reading error stream
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            while ((line = stdError.readLine()) != null) {
                System.err.println("Error: " + line);
            }

            process.waitFor();

        } catch (Exception e) {
            System.err.println("Exception occurred: " + e.getMessage());
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        executeCommand("echo Hello World", null, new File("."));
    }
}
