#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    double temperature;
    char *sensor_id;
} SensorData;

typedef struct {
    SensorData **data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SensorCollection;

#define INITIAL_CAPACITY 10

SensorCollection* create_sensor_collection() {
    SensorCollection *collection = (SensorCollection*)malloc(sizeof(SensorCollection));
    if (!collection) return NULL;

    collection->data = (SensorData**)calloc(INITIAL_CAPACITY, sizeof(SensorData*));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

int ensure_capacity(SensorCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    SensorData **new_data = (SensorData**)realloc(collection->data, new_capacity * sizeof(SensorData*));
    if (!new_data) return -1;

    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        new_data[i] = NULL;
    }

    collection->data = new_data;
    collection->capacity = new_capacity;
    return 0;
}

int insert_sensor_data(SensorCollection *collection, long timestamp, double temperature, const char *sensor_id) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity && ensure_capacity(collection)) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    SensorData *new_data = (SensorData*)malloc(sizeof(SensorData));
    if (!new_data) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    new_data->timestamp = timestamp;
    new_data->temperature = temperature;
    new_data->sensor_id = strdup(sensor_id);
    if (!new_data->sensor_id) {
        free(new_data);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->data[collection->count++] = new_data;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_sensor_temperature(SensorCollection *collection, long timestamp, double temperature) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        SensorData *data = collection->data[i];
        if (data->timestamp == timestamp) {
            data->temperature = temperature;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Timestamp not found
}

SensorData* interpolate_temperature(SensorCollection *collection, long timestamp) {
    if (collection->count < 2) return NULL;

    SensorData *prev = NULL, *next = NULL;
    for (size_t i = 0; i < collection->count; ++i) {
        SensorData *data = collection->data[i];
        if (timestamp >= data->timestamp && (!prev || prev->timestamp <= timestamp)) {
            prev = data;
        }
        if (timestamp <= data->timestamp && (!next || next->timestamp > timestamp)) {
            next = data;
        }
    }

    if (!prev || !next) return NULL;

    double time_span = next->timestamp - prev->timestamp;
    double fraction = (double)(timestamp - prev->timestamp) / time_span;
    double interpolated_temp = prev->temperature + fraction * (next->temperature - prev->temperature);

    SensorData *result = malloc(sizeof(SensorData));
    result->timestamp = timestamp;
    result->temperature = interpolated_temp;
    result->sensor_id = strdup(prev->sensor_id);

    return result;
}

void retrieve_data_in_range(SensorCollection *collection, long start_timestamp, long end_timestamp) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        SensorData *data = collection->data[i];
        if (data->timestamp >= start_timestamp && data->timestamp <= end_timestamp) {
            printf("Timestamp: %ld, Temperature: %.2f, Sensor ID: %s\n", data->timestamp, data->temperature, data->sensor_id);
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void destroy_sensor_collection(SensorCollection *collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->data[i]->sensor_id);
        free(collection->data[i]);
    }

    free(collection->data);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// This function can be used to simulate integration with external data source
void update_from_external_source(SensorCollection *collection, long timestamp, double temperature, const char *sensor_id) {
    // Simulate an external data update by inserting or updating the collection
    if (update_sensor_temperature(collection, timestamp, temperature) == -1) {
        insert_sensor_data(collection, timestamp, temperature, sensor_id);
    }
}

int main() {
    SensorCollection *collection = create_sensor_collection();
    if (!collection) return 1;

    insert_sensor_data(collection, 1620000000, 22.5, "sensor_1");
    insert_sensor_data(collection, 1620001000, 23.0, "sensor_1");

    retrieve_data_in_range(collection, 1619999999, 1620002000);

    SensorData *interpolated = interpolate_temperature(collection, 1620000500);
    if (interpolated) {
        printf("Interpolated - Timestamp: %ld, Temperature: %.2f, Sensor ID: %s\n",
               interpolated->timestamp, interpolated->temperature, interpolated->sensor_id);
        free(interpolated->sensor_id);
        free(interpolated);
    }

    update_from_external_source(collection, 1620000500, 22.8, "sensor_1");

    retrieve_data_in_range(collection, 1619999999, 1620002000);

    destroy_sensor_collection(collection);
    return 0;
}
