    srand(seed++); // Simple RNG seed update for demonstration purposes
    int key;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        key = rand() % (max_key - min_key + 1) + min_key;
        if (key >= min_key && key <= max_key) {
            return key;
        }
    }

    fprintf(stderr, "Error: Failed to generate a valid key.\n");
    return -1; // Indicate failure
}

void add_record(Collection *collection, int min_key, int max_key, long offset) {
    if (!collection) return;

    pthread_mutex_lock(&collection->mutex);

    int key = generate_valid_key(min_key, max_key);
    if (key == -1) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;

    // Assuming dynamic array or hash table expansion logic here

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->mutex);
}

void free_collection(Collection *collection) {
    if (!collection) return;

    for (int i = 0; i < collection->size; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);

    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
