['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

#define ALIGNMENT 64
#define MAX_NODES 1000
#define MAX_ITEMS_PER_NODE 50
#define STRING_LENGTH 10

typedef struct item {
    int key;
    char string[STRING_LENGTH + 1];
    union metadata {
        struct item *next_item;
        short value;
    } metadata;
} item_t;

typedef struct node {
    double value;
    item_t *items_head;
    size_t items_count;
} node_t;

// Helper function for aligned memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Helper function to calculate aligned size
size_t aligned_size(size_t size, size_t alignment) {
    return ((size + alignment - 1) / alignment) * alignment;
}

// Function to generate a random alphanumeric string of fixed length
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length > 0) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to initialize nodes and items
node_t* initialize_data_structure(size_t max_nodes, size_t max_items_per_node, const char *log_file) {
    node_t *nodes = aligned_alloc(ALIGNMENT, aligned_size(max_nodes * sizeof(node_t), ALIGNMENT));

    if (!nodes) {
        FILE *log_fp = fopen(log_file, "a");
        fprintf(log_fp, "Memory allocation failed for nodes.\n");
        fclose(log_fp);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_nodes; ++i) {
        double random_int = rand() % 1001; // Random number in range [0, 1000]
        nodes[i].value = sqrt(random_int);

        nodes[i].items_count = 0;
        item_t *current_item = NULL;

        for (size_t j = 0; j < max_items_per_node && nodes[i].items_count < max_items_per_node; ++j) {
            item_t *new_item = aligned_alloc(ALIGNMENT, aligned_size(sizeof(item_t), ALIGNMENT));

            if (!new_item) {
                FILE *log_fp = fopen(log_file, "a");
                fprintf(log_fp, "Memory allocation failed for item at node %zu.\n", i);
                fclose(log_fp);

                // Free previously allocated items in this node
                while (current_item) {
                    item_t *to_free = current_item;
                    current_item = current_item->metadata.next_item;
                    free(to_free);
                }
                break;  // Break out of the inner loop on allocation failure
            }

            new_item->key = rand(); // Unique key generated with full range of int

            generate_random_string(new_item->string, STRING_LENGTH);

            if (rand() % 2) {
                new_item->metadata.value = rand() % 32768;  // Short value from range [0, 32767]
            } else {
                new_item->metadata.next_item = NULL;
            }

            if (!nodes[i].items_head) {
                nodes[i].items_head = new_item;
            } else {
                current_item->metadata.next_item = new_item;
            }

            current_item = new_item;
            nodes[i].items_count++;
        }
    }

    return nodes;
}

// Function to verify integrity of the data structure
int verify_integrity(node_t *nodes, size_t max_nodes) {
    for (size_t i = 0; i < max_nodes; ++i) {
        if (!nodes[i].value || !nodes[i].items_head) {
            return 0;
        }

        item_t *current_item = nodes[i].items_head;

        while (current_item) {
            if (!current_item->key || strlen(current_item->string) != STRING_LENGTH || 
                ((current_item->metadata.next_item && current_item->metadata.next_item->key == 0)) ||
                (!(current_item->metadata.next_item || current_item->metadata.value))) {
                return 0;
            }
            current_item = current_item->metadata.next_item;
        }
    }

    return 1;
}

// Function to free allocated memory for data structure
void free_data_structure(node_t *nodes, size_t max_nodes) {
    if (!nodes) return;

    for (size_t i = 0; i < max_nodes; ++i) {
        item_t *current_item = nodes[i].items_head;

        while (current_item) {
            item_t *to_free = current_item;
            current_item = current_item->metadata.next_item;
            free(to_free);
        }
    }

    free(nodes);
}
