// Define constants for VLAN priority levels
#define VLAN_PRIORITY_DEFAULT 0

typedef struct {
    uint8_t destination[6];
    uint8_t source[6];
} MAC_HEADER;

typedef struct {
    uint16_t tci; // Tag Control Information (contains VLAN ID and Priority)
