// Function to initialize the NICB array
NICB* initialize_nicb_array(int size, uint32_t seed, int vlan_priority, 
                            int ip_checksum_calculation_enabled,
                            pthread_mutex_t *mutex) {
    if (size <= 0 || mutex == NULL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NICB *nicb_array = malloc(size * sizeof(NICB));
    if (!nicb_array) {
        perror("Memory allocation failed for NICB array.");
        return NULL;
    }

    pthread_mutex_lock(mutex);
    for (int i = 0; i < size; ++i) {
        // Initialize MAC addresses with a dummy pattern
        memset(nicb_array[i].mac_header.destination, 0xAA, sizeof(nicb_array[i].mac_header.destination));
        memset(nicb_array[i].mac_header.source, 0xBB, sizeof(nicb_array[i].mac_header.source));

        // Set Ethernet MAC Address with a seed-dependent pattern
        for (int j = 0; j < 6; ++j) {
            nicb_array[i].eth_mac_address[j] = (uint8_t)((seed + i * j) % 256);
        }

        // Generate VLAN tag based on the seed and index
        uint16_t vlan_id = (uint16_t)((seed + i) % 4096); // VLAN IDs range from 0 to 4095
        nicb_array[i].vlan_tag.tci = ((vlan_priority & 0x07) << 13) | (vlan_id);

        // Assign configuration settings
        nicb_array[i].vlan_priority = vlan_priority;
        nicb_array[i].ip_checksum_calculation_enabled = ip_checksum_calculation_enabled;

        printf("Initialized NICB at index %d\n", i);
    }
    pthread_mutex_unlock(mutex);

    return nicb_array;
}

// Example usage
int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int size = 10; // User-defined array size
    uint32_t seed = 12345; // Custom initialization seed

    NICB *nicb_array = initialize_nicb_array(size, seed, VLAN_PRIORITY_DEFAULT, 1, &mutex);
    if (nicb_array) {
        printf("NICB Array initialized successfully.\n");

        // Free allocated memory
        free(nicb_array);
    } else {
        fprintf(stderr, "Failed to initialize NICB array.\n");
    }

    return 0;
}
