        nicbs[i].config.ip_checksum_enabled = rand() % 2; // Enable/disable IP checksum

        // Additional initialization as needed
    }
}

int configure_crypto_policy(CryptoPolicy *policy, const char *algorithm_name, size_t key_size, size_t hash_length, void* algorithm_impl) {
    if (policy == NULL || algorithm_name == NULL || policy->num_algorithms >= MAX_ALGORITHMS) {
        return -1; // Error
    }

    pthread_mutex_lock(&policy->mutex);

    for (int i = 0; i < policy->num_algorithms; ++i) {
        if (strcmp(policy->algorithms[i].name, algorithm_name) == 0) {
            pthread_mutex_unlock(&policy->mutex);
            return -2; // Algorithm already exists
        }
    }

    strcpy(policy->algorithms[policy->num_algorithms].name, algorithm_name);
    policy->algorithms[policy->num_algorithms].key_size = key_size;
    policy->algorithms[policy->num_algorithms].hash_length = hash_length;
    policy->algorithms[policy->num_algorithms].algorithm = algorithm_impl;

    policy->num_algorithms++;
    pthread_mutex_unlock(&policy->mutex);

    return 0; // Success
}

