    size_t record_size = num_records * sizeof(Record);
    if (!can_allocate(record_size, current_usage)) {
        fprintf(stderr, "Insufficient memory for records.\n");
        free(*keys);
        free(*offsets);
        return -1;
    }
    *records = (Record*)malloc(record_size);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(*keys);
        free(*offsets);
        return -1;
    }
    current_usage += record_size;

    // Populate records
    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100 + 1;
        if (num_offsets > 0) {  // Ensure valid offset array size
            int random_offset_index = rand() % num_offsets;
            (*records)[i].offset_ptr = &(*offsets)[random_offset_index];
        } else {
            (*records)[i].offset_ptr = NULL;  // Handle case with zero offsets
        }
    }

    return 0;
}

void validate_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (!records[i].offset_ptr) {
            fprintf(stderr, "Invalid offset pointer at record index %d.\n", i);
        }
    }
}

int main() {
