    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;

    if (initialize_memory(num_offsets, num_keys, num_records, &offsets, &keys, &records) == 0) {
        validate_records(records, num_records);

        // Clean up
        free_resources(offsets, keys, records);
    } else {
        fprintf(stderr, "Memory initialization failed.\n");
    }

    return 0;
}
