uint32_t calculate_checksum_int(int *data, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

uint32_t calculate_checksum_string(char **strings, size_t length) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        for (size_t j = 0; strings[i][j] != '\0'; ++j) {
            checksum += strings[i][j];
        }
    }
    return checksum;
}

void generate_random_data(record *records, size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100; // Example range
        int str_len = rand() % 256;
        for (int j = 0; j < str_len; ++j) {
            records[i].str[j] = 'a' + (rand() % 26);
        }
        records[i].str[str_len] = '\0';
        records[i].timestamp = time(NULL);
    }
}

void resize_record_array(record **records, size_t *capacity) {
    pthread_mutex_lock(&resize_lock);
    size_t new_capacity = *capacity * 2;
    record *new_records = aligned_malloc(new_capacity * sizeof(record));
    if (new_records) {
        memcpy(new_records, *records, (*capacity) * sizeof(record));
        free(*records);
        *records = new_records;
        *capacity = new_capacity;
    }
    pthread_mutex_unlock(&resize_lock);
}

void manage_memory_allocation(size_t num_elements, int **keys, long **offsets, record ***records) {
    size_t record_capacity = INITIAL_CAPACITY;

    keys = aligned_malloc(num_elements * sizeof(int));
    offsets = aligned_malloc(num_elements * sizeof(long));
    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation failed for keys or offsets.\n");
        return;
    }

    *records = aligned_malloc(record_capacity * sizeof(record));
    if (!*records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Initial memory allocation failed for records.\n");
        return;
    }

    generate_random_data(*records, record_capacity);

    // Example of resizing when capacity is exceeded
    if (num_elements > record_capacity) {
        while (num_elements > *record_capacity) {
            resize_record_array(records, &record_capacity);
        }
        generate_random_data(&((*records)[*record_capacity]), num_elements - *record_capacity);
    }

    uint32_t int_checksum = calculate_checksum_int(*keys, num_elements);
    char **strings = malloc(num_elements * sizeof(char *));
    for (size_t i = 0; i < num_elements; ++i) {
        strings[i] = (*records)[i].str;
    }
    uint32_t str_checksum = calculate_checksum_string(strings, num_elements);
    free(strings);

    printf("Int checksum: %u\n", int_checksum);
    printf("String checksum: %u\n", str_checksum);

    // Logging and error handling
    FILE *log_file = fopen("allocation_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "Allocation successful at %ld with %zu records.\n", time(NULL), num_elements);
        fclose(log_file);
    }

    // Handle partial results gracefully
    if (!keys || !offsets || !*records) {
        printf("Partial allocation success. Returning available data.\n");
    }
}

int main() {
    size_t num_elements = 15;
    int *keys = NULL;
    long *offsets = NULL;
