import random
import string
import math
from typing import Optional

class Node:
    def __init__(self, value: float, items_count: int):
        self.value = value
        self.items = []
        for i in range(1, items_count + 1):
            item = {
                'key': i,
                'string': self._generate_random_string()
            }
            self.items.append(item)

    @staticmethod
    def _generate_random_string(length: int = 10) -> str:
        letters_and_digits = string.ascii_letters + string.digits
        return ''.join(random.choice(letters_and_digits) for _ in range(length))


class TestModule:
    def __init__(self, node_count: int, item_count: int):
        self.node_count = node_count
        self.item_count = item_count
        self.nodes = []

    def initialize_node(self, seed: float) -> Optional[Node]:
        try:
            value = math.sqrt(seed)
            return Node(value, self.item_count)
        except MemoryError:
            print("Memory allocation failed during node initialization.")
            self.cleanup()
            raise

    def populate_nodes(self):
        for i in range(1, self.node_count + 1):
            seed = random.uniform(0.0, 100.0) * i
            try:
                node = self.initialize_node(seed)
                if node:
                    self.nodes.append(node)
            except MemoryError:
                print(f"Failed to allocate memory for node with seed {seed}.")
                return

    def verify_node(self, node: Node):
        seen_keys = set()
        for item in node.items:
            if item['key'] in seen_keys or len(item['string']) != 10:
                print(f"Verification failed for key: {item['key']} with string: {item['string']}")
                return False
            seen_keys.add(item['key'])
        print("Node verification passed.")
        return True

    def verify_all_nodes(self):
        for i, node in enumerate(self.nodes):
            if not self.verify_node(node):
                print(f"Verification failed at node index {i}.")
                return False
        print("All nodes verified successfully.")
        return True

    def cleanup(self):
        del self.nodes[:]
        self.nodes = []

# Example usage:
if __name__ == "__main__":
    test_module = TestModule(node_count=10, item_count=5)
    test_module.populate_nodes()

    if test_module.nodes:
        verification_result = test_module.verify_all_nodes()
        if not verification_result:
            print("Some nodes failed verification.")
```

