#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <semaphore.h>
#include <pthread.h>
#include <stdalign.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define ALIGNMENT 16

typedef struct {
    int value;
    int key;
    long offset;
    int ref_count;
} Record;

typedef struct {
    Record *records;
    long *offsets;
    int *keys;
    size_t count;
    sem_t semaphore;
} ResourceManager;

static inline void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__GNUC__) || defined(__clang__)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

static inline void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__GNUC__) || defined(__clang__)
    free(ptr);
#endif
}

ResourceManager* ResourceManagerInit(int initial_semaphore_value, size_t num_elements, int min_random, int max_random) {
    if (num_elements <= 0 || initial_semaphore_value < 0) return NULL;

    ResourceManager *manager = aligned_alloc(ALIGNMENT, sizeof(ResourceManager));
    if (!manager) return NULL;

    manager->count = 0;
    sem_init(&manager->semaphore, 0, initial_semaphore_value);

    size_t current_capacity = MAX_ELEMENTS;
    while (current_capacity < num_elements) {
        current_capacity += CHUNK_SIZE;
    }

    manager->records = aligned_alloc(ALIGNMENT, current_capacity * sizeof(Record));
    manager->offsets = aligned_alloc(ALIGNMENT, current_capacity * sizeof(long));
    manager->keys = aligned_alloc(ALIGNMENT, current_capacity * sizeof(int));

    if (!manager->records || !manager->offsets || !manager->keys) {
        free(manager);
        sem_destroy(&manager->semaphore);
        return NULL;
    }

    int used_keys[MAX_ELEMENTS] = {0};
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_elements && manager->count < current_capacity; ++i) {
        int key = rand() % ((max_random - min_random + 1) * MAX_ELEMENTS) + min_random;

        pthread_mutex_lock(&lock);
        while (used_keys[key % MAX_ELEMENTS]) {
            key++;
        }
        used_keys[key % MAX_ELEMENTS] = 1;
        pthread_mutex_unlock(&lock);

        manager->records[manager->count].value = rand() % (max_random - min_random + 1) + min_random;
        manager->records[manager->count].key = key;
        manager->records[manager->count].offset = i; // Example offset
        manager->records[manager->count].ref_count = 0;

        manager->offsets[i] = i * sizeof(Record);
        manager->keys[i] = key;

        manager->count++;
    }

    sem_destroy(&manager->semaphore);

    return (void *)manager;
}

// Free function should be implemented to free the ResourceManager resources properly
