namespace EnterpriseAuthFramework
{
    public class UserAccount
    {
        public string Username { get; set; }
        public byte[] PasswordHash { get; set; }
        public int FailedLoginAttempts { get; set; }
        public DateTime? LockoutTime { get; set; }
    }

    public interface IAuthPolicyProvider
    {
        bool ValidatePassword(string password);
        bool IsLockedOut(UserAccount user, out TimeSpan lockoutDuration);
    }

    public class AuthPolicyProvider : IAuthPolicyProvider
    {
        private readonly int minPasswordLength;
        private readonly int maxFailedAttempts;
        private readonly TimeSpan lockoutWindow;

        public AuthPolicyProvider(int minPasswordLength, int maxFailedAttempts, TimeSpan lockoutWindow)
        {
            this.minPasswordLength = minPasswordLength;
            this.maxFailedAttempts = maxFailedAttempts;
            this.lockoutWindow = lockoutWindow;
        }

        public bool ValidatePassword(string password)
        {
            return password.Length >= minPasswordLength && password.Any(char.IsUpper) 
                   && password.Any(char.IsDigit) && password.Any(ch => !char.IsLetterOrDigit(ch));
        }

        public bool IsLockedOut(UserAccount user, out TimeSpan lockoutDuration)
        {
            if (user.FailedLoginAttempts >= maxFailedAttempts
                && DateTime.UtcNow - user.LockoutTime.Value < lockoutWindow)
            {
                lockoutDuration = lockoutWindow - (DateTime.UtcNow - user.LockoutTime.Value);
                return true;
            }
            lockoutDuration = TimeSpan.Zero;
            return false;
        }
    }

    public class AuthenticationService
    {
        private readonly IAuthPolicyProvider policyProvider;
        private readonly Dictionary<string, UserAccount> users = new();

        public AuthenticationService(IAuthPolicyProvider policyProvider)
        {
            this.policyProvider = policyProvider;
        }

        public bool RegisterUser(string username, string password)
        {
            if (users.ContainsKey(username)) return false;

            var user = new UserAccount { Username = username };
            using (var sha256 = SHA256.Create())
            {
                user.PasswordHash = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            }
            users.Add(username, user);
            return true;
        }

        public bool LoginUser(string username, string password)
        {
            if (!users.TryGetValue(username, out var user)) return false;

            using (var sha256 = SHA256.Create())
            {
                byte[] hash = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
                if (!hash.SequenceEqual(user.PasswordHash))
                {
                    user.FailedLoginAttempts++;
                    if (policyProvider.IsLockedOut(user, out _))
                    {
                        user.LockoutTime = DateTime.UtcNow;
                    }
                    return false;
                }
            }

            // Reset failed attempts on successful login
            user.FailedLoginAttempts = 0;
            user.LockoutTime = null;

            // Log authentication event here

            return true;
        }

        public void AdjustAccountPolicy(int minPasswordLength, int maxFailedAttempts, TimeSpan lockoutWindow)
        {
            policyProvider = new AuthPolicyProvider(minPasswordLength, maxFailedAttempts, lockoutWindow);
        }
    }

