char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* randomString = (char*)malloc(length + 1);
    if (!randomString) return NULL;

    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        randomString[i] = charset[key];
    }
    randomString[length] = '\0';
    return randomString;
}

Node* allocate_and_initialize_nodes(int node_count, int item_count_per_node, int min_val, int max_val)
{
    Node** nodes = (Node**)aligned_alloc(32, sizeof(Node*) * node_count);
    if (!nodes) return NULL;

    for (int i = 0; i < node_count; ++i) {
        double value = sqrt(generate_random_int(min_val, max_val));

        Node* node = (Node*)aligned_alloc(32, sizeof(Node));
        if (!node) {
            // Clean up previously allocated nodes
            while (--i >= 0) free(nodes[i]);
            free(nodes);
            return NULL;
        }

        node->value = value;
        node->head = (Item*)aligned_alloc(32, sizeof(Item) * item_count_per_node);
        if (!node->head) {
            free(node);
            while (--i >= 0) free(nodes[i]);
            free(nodes);
            return NULL;
        }

        for (int j = 0; j < item_count_per_node; ++j) {
            Item* item = &node->head[j];
            item->key = generate_random_int(1, 10000); // Unique key generation logic might be needed
            char* str = generate_random_string(10);
            if (!str) {
                free(node->head);
                free(node);
                while (--i >= 0) free(nodes[i]);
                free(nodes);
                return NULL;
            }
            strcpy(item->str, str);
            free(str); // Free the temporary string
        }

        nodes[i] = node; // Assign pointer to array
    }

    return nodes;
}

int verify_data_integrity(Node* nodes[], int count) {
    for (int i = 0; i < count; ++i) {
        if (!nodes[i]) continue;

        Node* node = nodes[i];
        double expected_value = sqrt(node->value * node->value);

        if (fabs(expected_value - node->value) > 1e-6) return 0;

        for (Item* item = node->head; item != NULL; item = item->next) {
            if (!item || strlen(item->str) != 10) return 0;
        }
    }

    return 1;
}

void free_allocated_nodes(Node* nodes[], int count) {
    for (int i = 0; i < count; ++i) {
        if (nodes[i]) {
            free(nodes[i]->head);
            free(nodes[i]);
        }
    }
    free(nodes);
}
