### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 10485760 // Example limit: 10 MB
#define STRING_CONSTANT "CONSTANT"
#define UINT_RANGE_MAX 1000
#define NUM_RECORDS 100

typedef struct {
    size_t size;
    union {
        double dValue;
        char *cString;
    };
} Item;

typedef struct {
    int value;
    char identifier[50];
    Item *itemPtr;
} Record;

typedef struct {
    pthread_mutex_t lock;
    long **longArray;
    double *doubleArray;
    struct {
        char string[100];
        unsigned int num;
    } *structArray;
    int *intKeys;
    Record *records;
} DataHolder;

DataHolder* initDataHolder(size_t longArraySize, size_t doubleArraySize,
                           size_t structArraySize, size_t intKeySize) {
    DataHolder *data = (DataHolder *)malloc(sizeof(DataHolder));
    if (!data) return NULL;

    pthread_mutex_init(&data->lock, NULL);

    data->longArray = (long **)malloc(longArraySize * sizeof(long *));
    data->doubleArray = (double *)malloc(doubleArraySize * sizeof(double));
    data->structArray = (typeof(data->structArray))malloc(structArraySize * sizeof(*data->structArray));
    data->intKeys = (int *)malloc(intKeySize * sizeof(int));
    data->records = (Record *)calloc(NUM_RECORDS, sizeof(Record));

    if (!data->longArray || !data->doubleArray || !data->structArray || !data->intKeys || !data->records) {
        freeResources(data);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < longArraySize; ++i) {
        data->longArray[i] = (long *)malloc(sizeof(long));
        *data->longArray[i] = rand();
    }

    for (size_t i = 0; i < doubleArraySize; ++i) {
        data->doubleArray[i] = rand() / (double)RAND_MAX;
    }

    for (size_t i = 0; i < structArraySize; ++i) {
        strcpy(data->structArray[i].string, STRING_CONSTANT);
        data->structArray[i].num = rand() % UINT_RANGE_MAX;
    }

    for (int i = 0; i < NUM_RECORDS; ++i) {
        snprintf(data->records[i].identifier, sizeof(data->records[i].identifier), "ID_%d_%ld", i, time(NULL));
        data->records[i].value = rand();
        data->records[i].itemPtr = (Item *)malloc(sizeof(Item));
        if (!data->records[i].itemPtr) {
            freeResources(data);
            return NULL;
        }
    }

    // Memory usage check
    size_t totalMemoryUsage = sizeof(DataHolder) + 
                              longArraySize * sizeof(long *) +
                              doubleArraySize * sizeof(double) +
                              structArraySize * sizeof(*data->structArray) +
                              intKeySize * sizeof(int) +
                              NUM_RECORDS * sizeof(Record);

    for (size_t i = 0; i < longArraySize; ++i) {
        totalMemoryUsage += sizeof(long);
    }

    for (int i = 0; i < NUM_RECORDS; ++i) {
        totalMemoryUsage += sizeof(Item);
    }

    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        releaseExcessMemory(data, totalMemoryUsage - MAX_MEMORY_USAGE);
    }

    return data;
}

void releaseExcessMemory(DataHolder *data, size_t excess) {
    // Implement logic to free less frequently accessed records
    pthread_mutex_lock(&data->lock);

    while (excess > 0 && NUM_RECORDS > 0) {
        Record *record = &data->records[NUM_RECORDS - 1];
        if (record->itemPtr) {
            free(record->itemPtr);
            record->itemPtr = NULL;
            excess -= sizeof(Item);
        }
        --NUM_RECORDS;
    }

    pthread_mutex_unlock(&data->lock);
}

void freeResources(DataHolder *data) {
    pthread_mutex_lock(&data->lock);

    for (size_t i = 0; i < NUM_RECORDS && data->records[i].itemPtr; ++i) {
        free(data->records[i].itemPtr);
    }

    if (data->longArray) {
        for (size_t i = 0; i < sizeof(data->longArray) / sizeof(long *); ++i) {
            free(data->longArray[i]);
        }
        free(data->longArray);
    }

    pthread_mutex_unlock(&data->lock);

    pthread_mutex_destroy(&data->lock);
    free(data->doubleArray);
    free(data->structArray);
    free(data->intKeys);
    free(data->records);
    free(data);
}

