import java.io.IOException;
import java.nio.channels.SocketChannel;
import java.net.InetSocketAddress;

public class MyJavaClass {

    public void connectToRemote(String host, int port) {
        try (SocketChannel socketChannel = SocketChannel.open()) {
            socketChannel.configureBlocking(false);
            boolean connected = socketChannel.connect(new InetSocketAddress(host, port)).awaitUninterruptibly(5000).isDone();

            if (!connected) {
                System.out.println("Connection attempt timed out.");
                return;
            }

            while (!socketChannel.finishConnect()) {
                // Handle connection state changes
            }
            System.out.println("Connected to remote address: " + host + ":" + port);
        } catch (IOException e) {
            System.err.println("Failed to connect due to IOException: " + e.getMessage());
        }
    }
}
```

