    MD5((unsigned char*) data, strlen(data), outputBuffer);
}

// Convert MD5 digest to hex string
char* md5_to_hex_string(unsigned char digest[MD5_DIGEST_LENGTH]) {
    static char hexString[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hexString[i * 2], "%02x", digest[i]);
    }
    return hexString;
}

