struct offset_key {
    long offset;
    int key;
};

struct record {
    int value;
};

typedef struct {
    struct offset_key *offset_keys;
    size_t n_offset_keys;
    pthread_mutex_t mutex;
} OffsetKeyArray;

typedef struct {
    struct record *records;
    size_t n_records;
    pthread_rwlock_t rwlock;
} RecordArray;

// Error logging function
void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

// Function to check for integer overflow in allocation
size_t safe_multiply(size_t a, size_t b) {
    if (a == 0 || b <= SIZE_MAX / a)
        return a * b;
    else {
        log_error("Integer overflow detected during memory calculation.");
        return 0; // Indicate error
    }
}

int manage_resources(int n, int max_val) {
    if (n < 0) {
        log_error("Negative size for offset_key array.");
        return -1;
    }

    OffsetKeyArray ok_array = { .n_offset_keys = n };
    RecordArray rec_array;

    // Allocate memory for the offset_key array
    size_t size_ok = safe_multiply(n, sizeof(struct offset_key));
    if (!size_ok) {
        log_error("Failed to calculate size for offset_key array.");
        return -1;
    }

    ok_array.offset_keys = (struct offset_key*)malloc(size_ok);
    if (!ok_array.offset_keys) {
        log_error("Failed to allocate memory for offset_key array.");
        return -2;
    }

    // Initialize mutex
    pthread_mutex_init(&ok_array.mutex, NULL);

    // Allocate memory for the record array (twice the size)
    size_t size_rec = safe_multiply(2 * n, sizeof(struct record));
    if (!size_rec) {
        log_error("Failed to calculate size for record array.");
        free(ok_array.offset_keys);
        return -1;
    }

    rec_array.records = (struct record*)malloc(size_rec);
    if (!rec_array.records) {
        log_error("Failed to allocate memory for record array.");
        pthread_mutex_destroy(&ok_array.mutex);
        free(ok_array.offset_keys);
        return -3;
    }

    // Initialize reader-writer lock
    pthread_rwlock_init(&rec_array.rwlock, NULL);

    rec_array.n_records = 2 * n;

    // Populate records with random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < rec_array.n_records; ++i) {
        int value;
        do {
            value = rand() % max_val;
        } while ((i > 0 && rec_array.records[i - 1].value == value) &&
                 (i < rec_array.n_records - 1 || rand() % 2));

        pthread_rwlock_wrlock(&rec_array.rwlock);
        rec_array.records[i].value = value;
        pthread_rwlock_unlock(&rec_array.rwlock);
    }

    // Function to free all resources
    void cleanup() {
        pthread_mutex_destroy(&ok_array.mutex);
        pthread_rwlock_destroy(&rec_array.rwlock);
        free(ok_array.offset_keys);
        free(rec_array.records);
    }

    // Return success indicator; in a real program, more logic would follow here

    return 0;
}

// Example test function
void* thread_function(void *arg) {
    manage_resources(1000, 10);
    return NULL;
}

int main() {
    int n = 1000;
    int max_val = 10;

    if (manage_resources(n, max_val) != 0) {
        log_error("Resource management failed.");
        return EXIT_FAILURE;
    }

    // Example: Run test under multithreading
    const int num_threads = 4;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL) != 0) {
            log_error("Failed to create thread.");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Resources managed successfully under test conditions.\n");
    return EXIT_SUCCESS;
}
