#define ALIGNMENT 16
#define PAGE_SIZE 4096
#define KEY_RANGE 1000
#define RECORD_COUNT 1024

// Record structure
typedef struct {
    int value;
} record_t;

// Utility function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, alignment, size) != 0) {
        return NULL; // Allocation failed
    }
#else
#error "Platform not supported."
#endif
    return ptr;
}

// Fallback to page-aligned allocation if standard fails
void* fallback_aligned_alloc(size_t alignment, size_t size) {
    void *ptr = aligned_alloc(alignment ? alignment : PAGE_SIZE, size);
    if (!ptr) {
        ptr = mmap(NULL, size + (alignment - 1), PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr == MAP_FAILED) {
            return NULL;
        }
    }
    uintptr_t mask = alignment - 1;
    uintptr_t addr = (uintptr_t)ptr & mask;
    ptr = (void*)((addr ? (alignment - addr) : 0) + (char*)ptr);
    return ptr;
}

// Logger function
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message); // Simple logging to stderr
}

// Initialize random number generator
unsigned int seed_from_key(int key) {
