// Enumeration for task status
typedef enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
} TaskStatus;

// Struct to represent dependencies
typedef struct Dependency {
    int task_id;
    float weight;
    struct Dependency* next;
} Dependency;

// Align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL; // Allocation failed
    }
    return ptr;
}

// Struct to represent tasks
typedef struct Task {
    int id;
    int priority;
    TaskStatus status;
    Dependency* dependencies;
    struct Task* next;
} Task;

// Struct to represent the project management system
typedef struct Project {
    Task* tasks;
} Project;

// Function prototypes
Project* create_project();
void init_task(Task* task, int id, int priority);
void add_dependency(Task* task, int dep_id, float weight);
int allocate_aligned(size_t size, size_t alignment);

// Thread-safe mutex for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Create and initialize a project management system
Project* create_project() {
    Project* project = (Project*)aligned_alloc(256, sizeof(Project));
    if (!project) {
        fprintf(stderr, "Memory allocation failed for project\n");
        return NULL;
    }
    project->tasks = NULL;
    return project;
}

// Initialize a task with given id and priority
void init_task(Task* task, int id, int priority) {
    task->id = id;
    task->priority = priority;
    task->status = PENDING;
    task->dependencies = NULL;
    task->next = NULL;
}

// Add a dependency to a task
void add_dependency(Task* task, int dep_id, float weight) {
    pthread_mutex_lock(&lock);
    Dependency* new_dep = (Dependency*)aligned_alloc(256, sizeof(Dependency));
    if (!new_dep) {
        fprintf(stderr, "Memory allocation failed for dependency\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    new_dep->task_id = dep_id;
    new_dep->weight = weight;
    new_dep->next = task->dependencies;
    task->dependencies = new_dep;
    pthread_mutex_unlock(&lock);
}

// Allocate aligned memory
int allocate_aligned(size_t size, size_t alignment) {
    return posix_memalign(NULL, alignment, size) == 0;
}

