#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define ALIGNMENT 32
#define ITEM_STRING_LENGTH 10

typedef struct Item {
    int key;
    char string[ITEM_STRING_LENGTH + 1];
} Item;

typedef struct Node {
    double value;
    int id;
    struct Item *items_head;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} NodeList;

// Utility function to align memory
void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

// Function to generate random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (length) {
        --length; // Leave room for null terminator
        for (size_t n = 0; n < length; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to initialize an item
Item* init_item(int key) {
    Item *item = aligned_alloc(sizeof(Item), ALIGNMENT);
    if (!item) return NULL;
    item->key = key;
    generate_random_string(item->string, ITEM_STRING_LENGTH);
    item->next = NULL;
    return item;
}

// Function to initialize a node
Node* init_node(int id) {
    Node *node = aligned_alloc(sizeof(Node), ALIGNMENT);
    if (!node) return NULL;

    node->value = rand() % 100; // Example: random value within range
    node->id = id;
    node->items_head = NULL;
    node->next = NULL;
    return node;
}

// Function to add an item to a node
void add_item_to_node(Node *node, Item *item) {
    if (!node || !item) return;

    item->next = node->items_head;
    node->items_head = item;
}

// Function to create and initialize the node list
NodeList* init_node_list() {
    NodeList *list = aligned_alloc(sizeof(NodeList), ALIGNMENT);
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a node to the list
void add_node_to_list(NodeList *list, Node *node) {
    if (!list || !node) return;

    pthread_mutex_lock(&list->lock);

    node->next = list->head;
    list->head = node;

    pthread_mutex_unlock(&list->lock);
}

// Function to query nodes by value range
Node* query_nodes_by_value(NodeList *list, double min_value, double max_value) {
    if (!list) return NULL;

    Node *result = NULL;
    Node **tail = &result;

    pthread_mutex_lock(&list->lock);

    for (Node *current = list->head; current != NULL; current = current->next) {
        if (current->value >= min_value && current->value <= max_value) {
            Node *new_node = init_node(current->id);
            if (!new_node) continue;

            new_node->items_head = current->items_head;
            *tail = new_node;
            tail = &new_node->next;
        }
    }

    pthread_mutex_unlock(&list->lock);

    return result;
}

// Function to query nodes by item key
Node* query_nodes_by_item_key(NodeList *list, int key) {
    if (!list) return NULL;

    Node *result = NULL;
    Node **tail = &result;

    pthread_mutex_lock(&list->lock);

    for (Node *current = list->head; current != NULL; current = current->next) {
        for (Item *item = current->items_head; item != NULL; item = item->next) {
            if (item->key == key) {
                Node *new_node = init_node(current->id);
                if (!new_node) continue;

                new_node->items_head = current->items_head;
                *tail = new_node;
                tail = &new_node->next;
                break;
            }
        }
    }

    pthread_mutex_unlock(&list->lock);

    return result;
}

// Function to free node list
void free_node_list(NodeList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Item *item = current->items_head;
        while (item != NULL) {
            Item *next_item = item->next;
            free(item);
            item = next_item;
        }
        Node *next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    srand(time(NULL));

    NodeList *node_list = init_node_list();
    if (!node_list) return 1;

    for (int i = 0; i < 10; ++i) {
        Node *node = init_node(i);
        if (!node) continue;

        for (int j = 0; j < 5; ++j) {
            Item *item = init_item(j);
            if (!item) continue;
            add_item_to_node(node, item);
        }

        add_node_to_list(node_list, node);
    }

    Node *queried_nodes = query_nodes_by_value(node_list, 10.0, 50.0);
    // Process queried nodes...

    free_node_list(node_list);

    return 0;
}
