#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
    pthread_mutex_t lock;
} memory_pool;

void initialize_memory_pool(memory_pool *pool, size_t count, int range_min, int range_max, unsigned int seed) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->count = count;

    // Calculate total required memory
    size_t offset_size = count * sizeof(long);
    size_t key_size = count * sizeof(int);
    size_t record_size = count * sizeof(record);

    // Ensure alignment to 16-byte boundary
    void* aligned_memory;
    if (posix_memalign(&aligned_memory, 16, offset_size + key_size + record_size) != 0) {
        fprintf(stderr, "Failed to allocate memory with required alignment.\n");
        exit(EXIT_FAILURE);
    }

    pool->offsets = (long*)aligned_memory;
    aligned_memory = (char*)aligned_memory + offset_size;

    pool->keys = (int*)aligned_memory;
    aligned_memory = (char*)aligned_memory + key_size;

    pool->records = (record*)aligned_memory;

    // Seed random number generator
    srand(seed);

    // Initialize records with random values within the specified range
    for (size_t i = 0; i < count; ++i) {
        int value = rand() % (range_max - range_min + 1) + range_min;
        pool->records[i].value = value;

        // Verify data consistency
        if (value < range_min || value > range_max) {
            fprintf(stderr, "Data integrity check failed for record at index %zu.\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Log allocation success
    printf("Memory pool initialized successfully with %zu records.\n", count);
}

void* allocate_memory_with_fallback(size_t size, size_t fallback_size) {
    void* memory = malloc(size);
    if (!memory) {
        fprintf(stderr, "Initial allocation failed. Attempting fallback...\n");
        memory = malloc(fallback_size);
        if (!memory) {
            fprintf(stderr, "Fallback allocation also failed.\n");
            exit(EXIT_FAILURE);
        }
    }
    return memory;
}

void* thread_safe_allocate(memory_pool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    void* memory = allocate_memory_with_fallback(size, size / 2);
    if (!memory) {
        fprintf(stderr, "Thread-safe allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&pool->lock);
    return memory;
}

void free_memory_pool(memory_pool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->offsets);  // Freeing the base pointer also frees the rest
}

int main() {
    size_t record_count = 1000;
    int range_min = 1, range_max = 100;
    unsigned int seed = 42;

    memory_pool pool;
    initialize_memory_pool(&pool, record_count, range_min, range_max, seed);

    // Example of concurrent access
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, (void*(*)(void*))thread_safe_allocate, &pool)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

