['Here's an implementation in C that addresses your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>

#define ALIGNMENT 8
#define STR_PAD_LENGTH 128

struct data_packet {
    int id;
    char message[STR_PAD_LENGTH];
};

typedef struct {
    double *doubles;
    char **strings;
    struct data_packet *packets;
    size_t num_doubles;
    size_t num_strings;
    size_t num_packets;
} MemoryConfig;

static atomic_int failed_allocations = 0;

void align_address(void **ptr, size_t alignment) {
    void *original = *ptr;
    if (alignment > sizeof(void*)) {
        uintptr_t address = (uintptr_t)original;
        if (address & (alignment - 1)) {
            address += alignment - (address & (alignment - 1));
            *ptr = (void*)address;
        }
    }
}

MemoryConfig* allocate_memory_config(size_t num_doubles, size_t num_strings, size_t num_packets, int base_id) {
    MemoryConfig *config = NULL;
    size_t total_size = 0;

    // Calculate sizes
    total_size += num_doubles * sizeof(double);
    align_address((void**)&total_size, ALIGNMENT);

    total_size += num_strings * (STR_PAD_LENGTH + (ALIGNMENT - 1));
    align_address((void**)&total_size, ALIGNMENT);

    size_t packet_struct_size = sizeof(struct data_packet) + STR_PAD_LENGTH;
    total_size += num_packets * packet_struct_size;
    align_address((void**)&total_size, ALIGNMENT);

    // Allocate memory
    void *memory_block = malloc(total_size);
    if (!memory_block) {
        atomic_fetch_add(&failed_allocations, 1);
        return NULL;
    }

    config = (MemoryConfig*)malloc(sizeof(MemoryConfig));
    if (!config) {
        free(memory_block);
        atomic_fetch_add(&failed_allocations, 1);
        return NULL;
    }

    // Initialize pointers
    void *current_ptr = memory_block;

    // Allocate and align doubles array
    align_address((void**)&current_ptr, ALIGNMENT);
    config->doubles = (double*)current_ptr;
    current_ptr = (char*)current_ptr + num_doubles * sizeof(double);

    // Allocate and align strings array
    for (size_t i = 0; i < num_strings; ++i) {
        align_address((void**)&current_ptr, ALIGNMENT);
        config->strings[i] = (char*)current_ptr;
        current_ptr += STR_PAD_LENGTH + (ALIGNMENT - 1);
    }

    // Allocate and align data_packet array
    for (size_t i = 0; i < num_packets; ++i) {
        align_address((void**)&current_ptr, ALIGNMENT);
        config->packets[i].id = base_id++;
        strncpy(config->packets[i].message, "", STR_PAD_LENGTH);
        current_ptr += sizeof(struct data_packet) + STR_PAD_LENGTH;
    }

    // Verify integrity
    for (size_t i = 0; i < num_packets; ++i) {
        if (config->packets[i].id != base_id - num_packets + i || strlen(config->packets[i].message) >= STR_PAD_LENGTH) {
            free(memory_block);
            free(config);
            atomic_fetch_add(&failed_allocations, 1);
            return NULL;
        }
    }

    config->num_doubles = num_doubles;
    config->num_strings = num_strings;
    config->num_packets = num_packets;

    return config;
}

void reset_failed_allocations() {
    atomic_store(&failed_allocations, 0);
}

int get_failed_allocations() {
    return atomic_load(&failed_allocations);
}

void free_memory_config(MemoryConfig *config) {
    if (config) {
        free(config);
    }
}
```

