    return ptr;
}

// Calculate checksum for data integrity verification
uint32_t calculate_checksum(void *data, size_t len) {
    uint32_t checksum = 0;
    unsigned char *bytes = (unsigned char*)data;

    while (len--) {
        checksum += *bytes++;
    }

    return checksum;
}

// Function to allocate and initialize array of Record1
