    if (!rand_seed) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        srand(tv.tv_sec ^ tv.tv_usec | 1);
    }
    return rand() % (max - min + 1) + min;
}

void init_random_string(char *str, size_t len) {
