    time_t timestamp;
    Item *itemRef;
} LogEntry;

// Define the dynamic collection of items
typedef struct {
    Item **items; // Pointer to an array of pointers to items
    size_t count; // Current number of items
    size_t capacity; // Maximum number of items before resizing is needed
} ItemCollection;

// Define the log management system
typedef struct {
    LogEntry *entries; // Array of log entries
    size_t count; // Number of log entries
    size_t capacity; // Capacity of the log array
} LogManager;

// Function prototypes
void initItemCollection(ItemCollection *collection);
void addItem(ItemCollection *collection, const char *name, int index, double value);
void initLogManager(LogManager *logManager);
void addLogEntry(LogManager *logManager, Item *itemRef);
void resizeIfNeeded(ItemCollection *collection);
void resizeIfNeeded(LogManager *logManager);
void freeItemCollection(ItemCollection *collection);
void freeLogManager(LogManager *logManager);

// Initialize an item collection
void initItemCollection(ItemCollection *collection) {
    collection->count = 0;
    collection->capacity = 10; // Initial capacity
    collection->items = malloc(collection->capacity * sizeof(Item*));
}

// Add a new item to the collection
void addItem(ItemCollection *collection, const char *name, int index, double value) {
    resizeIfNeeded(collection);

    Item *newItem = malloc(sizeof(Item));
    newItem->name = strdup(name); // Allocate memory and copy string
    newItem->index = index;
    newItem->value = value;

    collection->items[collection->count++] = newItem; // Add item to the array
}

// Initialize a log manager
void initLogManager(LogManager *logManager) {
    logManager->count = 0;
    logManager->capacity = 10; // Initial capacity
    logManager->entries = malloc(logManager->capacity * sizeof(LogEntry));
}

// Add a new log entry
void addLogEntry(LogManager *logManager, Item *itemRef) {
    resizeIfNeeded(logManager);

    LogEntry newEntry;
    time(&newEntry.timestamp);
    newEntry.itemRef = itemRef;

    logManager->entries[logManager->count++] = newEntry; // Add log entry to the array
}

// Resize the item collection if necessary
void resizeIfNeeded(ItemCollection *collection) {
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Item **newItems = realloc(collection->items, newCapacity * sizeof(Item*));

        if (newItems != NULL) {
            collection->items = newItems;
            collection->capacity = newCapacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to allocate memory for item collection.\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Resize the log manager if necessary
void resizeIfNeeded(LogManager *logManager) {
    if (logManager->count >= logManager->capacity) {
        size_t newCapacity = logManager->capacity * 2;
        LogEntry *newEntries = realloc(logManager->entries, newCapacity * sizeof(LogEntry));

        if (newEntries != NULL) {
            logManager->entries = newEntries;
            logManager->capacity = newCapacity;
        } else {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to allocate memory for log manager.\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Free the resources allocated for the item collection
void freeItemCollection(ItemCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i] != NULL) {
            free(collection->items[i]->name); // Free string memory
            free(collection->items[i]); // Free item structure
        }
    }
    free(collection->items); // Free the array of pointers
}

// Free the resources allocated for the log manager
void freeLogManager(LogManager *logManager) {
    free(logManager->entries); // Free the array of log entries
}

// Example usage
int main() {
    ItemCollection items;
    LogManager logs;

    initItemCollection(&items);
    initLogManager(&logs);

    addItem(&items, "item1", 0, 10.5);
    addLogEntry(&logs, items.items[0]);

    // Clean up resources
    freeItemCollection(&items);
    freeLogManager(&logs);

    return 0;
}
