['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    int insertions, deletions, sorts;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

int is_unique(LinkedList* list, unsigned long rx_ue_info_tag, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if ((current->data.RX_UE_INFORMATION_TAG == rx_ue_info_tag) ||
            (current->data.RNTI == rnti)) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ELEMENTS || !is_unique(list, data.RX_UE_INFORMATION_TAG, data.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    list->insertions++;
    pthread_mutex_unlock(&list->lock);
    return 1;
}

void sort_list(LinkedList* list) {
    if (list->count < 2) return;

    pthread_mutex_lock(&list->lock);
    int sorted = 0;
    while (!sorted) {
        Node *current, *prev, *next_next;
        sorted = 1;
        current = list->head;
        prev = NULL;
        while (current && current->next) {
            if (current->data.RNTI > current->next->data.RNTI) {
                sorted = 0;
                next_next = current->next->next;
                current->next->next = current;
                if (prev) {
                    prev->next = current->next;
                } else {
                    list->head = current->next;
                }
                current->next = next_next;
                prev = current->next;
                current = next_next;
            } else {
                prev = current;
                current = current->next;
            }
        }
    }
    list->sorts++;
    pthread_mutex_unlock(&list->lock);
}

int serialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return 0;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);

    pthread_mutex_unlock(&list->lock);
    return 1;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->insertions = 0;
    list->deletions = 0;
    list->sorts = 0;
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % (1 << 16); // Example range
    pdu.RNTI = rand() % (1 << 12);                  // Example range
    pdu.tag.CRCFLAG = rand() & 0x01;                // Random CRC flag
    return pdu;
}

void populate_linked_list(LinkedList* list, int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        while (!insert_node(list, pdu)) {
            pdu = generate_random_pdu(); // Retry with a new random PDU
        }
    }
}

void example_usage() {
    LinkedList* list = create_linked_list();
    if (list) {
        populate_linked_list(list, 10000);
        sort_list(list);
        serialize_list(list, "nfa_data.bin");
        free_linked_list(list);
    }
}
