#include <pthread.h>
#include <time.h>

#define MAX_NODES 100
#define ITEMS_PER_NODE 10
#define DOUBLE_ARRAY_SIZE 50
#define ITEM_STRING_LENGTH 20
#define MEMORY_ALIGNMENT 64

typedef struct {
    double value;
} NodeData;

typedef union {
    struct Item *nextItem;
    short intValue;
} MetadataUnion;

typedef struct Item {
    int key;
    char string[ITEM_STRING_LENGTH];
    MetadataUnion metadata;
} Item;

typedef struct Node {
    NodeData *dataArray;
    Item *items;
    size_t itemCount;
} Node;

typedef struct {
    Node *nodes;
    size_t nodeCount;
} StructureContainer;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Utility functions
void *aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_POSIX_C_SOURCE) || defined(_XOPEN_SOURCE)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    ptr = _aligned_malloc(size, alignment);
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_POSIX_C_SOURCE) || defined(_XOPEN_SOURCE)
    free(ptr);
#else
    _aligned_free(ptr);
#endif
}

// Function to generate a random alphanumeric string of fixed length
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = (char *)malloc(length + 1);

    if (!randomString) return NULL;

    for (size_t i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        randomString[i] = charset[key];
    }
    randomString[length] = '\0';
    return randomString;
}

// Function to initialize the structures
StructureContainer* init_structures(size_t maxNodes, size_t itemsPerNode) {
    StructureContainer *container = (StructureContainer *)aligned_malloc(
        sizeof(StructureContainer), MEMORY_ALIGNMENT);

    if (!container) {
        fprintf(stderr, "Failed to allocate memory for container\n");
        return NULL;
    }

    container->nodes = (Node *)aligned_malloc(maxNodes * sizeof(Node), MEMORY_ALIGNMENT);
    if (!container->nodes) {
        aligned_free(container);
        fprintf(stderr, "Failed to allocate memory for nodes\n");
        return NULL;
    }
    container->nodeCount = 0;

    pthread_mutex_lock(&lock);

    srand(time(NULL));
    for (size_t i = 0; i < maxNodes && i < MAX_NODES; i++) {
        Node *node = &container->nodes[i];

        node->dataArray = (NodeData *)aligned_malloc(DOUBLE_ARRAY_SIZE * sizeof(NodeData), MEMORY_ALIGNMENT);
        if (!node->dataArray) {
            fprintf(stderr, "Failed to allocate memory for dataArray\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        node->items = (Item *)aligned_malloc(itemsPerNode * sizeof(Item), MEMORY_ALIGNMENT);
        if (!node->items) {
            aligned_free(node->dataArray);
            fprintf(stderr, "Failed to allocate memory for items\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        node->itemCount = 0;

        // Populate data array with square roots of random numbers
        for (size_t j = 0; j < DOUBLE_ARRAY_SIZE; j++) {
            int randInt = rand() % 100 + 1;
            node->dataArray[j].value = round(pow(randInt, 0.5) * 1000.0) / 1000.0;
        }

        // Populate items with random keys and strings
        for (size_t j = 0; j < itemsPerNode && j < ITEMS_PER_NODE; j++) {
            Item *item = &node->items[j];

            do {
                item->key = rand() % 10000 + 1;
            } while (j > 0 && node->items[j - 1].key == item->key);

            char *randomStr = generate_random_string(ITEM_STRING_LENGTH);
            if (!randomStr) {
                fprintf(stderr, "Failed to generate random string\n");
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            strncpy(item->string, randomStr, ITEM_STRING_LENGTH - 1);
            free(randomStr);

            // Initialize metadata
            if ((rand() % 100) < 50) {
                item->metadata.intValue = rand() % 1000;
            } else {
                item->metadata.nextItem = NULL; // or some logic to link to another item
            }

            node->itemCount++;
        }
    }

    pthread_mutex_unlock(&lock);
    return container;
}

void free_structures(StructureContainer *container) {
    if (!container) return;

    for (size_t i = 0; i < container->nodeCount && i < MAX_NODES; i++) {
        Node *node = &container->nodes[i];

        aligned_free(node->dataArray);
        aligned_free(node->items);
    }

    aligned_free(container->nodes);
    aligned_free(container);
}

// Example usage
int main() {
    StructureContainer *structures = init_structures(MAX_NODES, ITEMS_PER_NODE);

    if (structures) {
        printf("Structures initialized successfully.\n");

        // Do something with the structures

        free_structures(structures);
    } else {
        fprintf(stderr, "Failed to initialize structures\n");
    }

    return 0;
}
