#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define MEMORY_ALIGNMENT 16

typedef struct {
    int value;
    int key;
    int ref_count;
} record;

typedef struct {
    record *records;
    long *offsets;
    int *keys;
    size_t num_elements;
    sem_t semaphore;
    pthread_mutex_t mutex;
} ResourceManager;

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_POSIX_MEMALIGN)
    if (posix_memalign(&ptr, alignment, size) != 0) return NULL;
#elif defined(_ALIGNED_MALLOC)
    ptr = _aligned_malloc(size, alignment);
#else
    size_t offset = alignment - 1 + sizeof(void*);
    void *raw = malloc(size + offset);
    if (!raw) return NULL;
    ptr = (void*)(((size_t)raw + offset) & ~(alignment - 1));
#endif
    return ptr;
}

void free_aligned(void *ptr) {
#if defined(_POSIX_MEMALIGN)
    free(ptr);
#elif defined(_ALIGNED_MALLOC)
    _aligned_free(ptr);
#else
    // Handle general case or error if necessary
#endif
}

ResourceManager* ResourceManagerInit(size_t num_elements, int key_range_min, int key_range_max) {
    ResourceManager *manager = aligned_alloc(MEMORY_ALIGNMENT, sizeof(ResourceManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    sem_init(&manager->semaphore, 0, 1);

    size_t allocation_size = num_elements;
    manager->records = malloc(sizeof(record) * allocation_size);
    manager->offsets = malloc(sizeof(long) * allocation_size);
    manager->keys = malloc(sizeof(int) * allocation_size);

    if (!manager->records || !manager->offsets || !manager->keys) {
        free_aligned(manager);
        return NULL;
    }

    int used_keys[MAX_ELEMENTS] = {0};
    srand(time(NULL));

    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&manager->mutex);

        // Ensure unique keys
        while (1) {
            manager->keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
            if (!used_keys[manager->keys[i]]) break;
        }
        used_keys[manager->keys[i]] = 1;

        manager->records[i].value = rand();
        manager->records[i].key = manager->keys[i];
        manager->records[i].ref_count = 0;

        // Simulate offset
        manager->offsets[i] = i * sizeof(record);

        pthread_mutex_unlock(&manager->mutex);
    }

    manager->num_elements = num_elements;

    return manager;
}

void ResourceManagerFree(ResourceManager *manager) {
    if (!manager) return;

    sem_destroy(&manager->semaphore);
    pthread_mutex_destroy(&manager->mutex);

    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free_aligned(manager);
}
