typedef struct {
    short value;
    char identifier;
    float* data_ptr;
} Record;

Record* allocate_records(size_t num_records, float min_value, float max_value) {
    if (num_records <= 0) {
        fprintf(stderr, "Number of records must be positive.\n");
        return NULL;
    }

    // Allocate memory for the array of records
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand((unsigned int)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = 0;           // Initialize short value
        records[i].identifier = ' ';    // Default identifier
        records[i].data_ptr = (float*)malloc(sizeof(float));

        if (!records[i].data_ptr) {
            perror("Failed to allocate memory for float pointer");
            // Free previously allocated records and their data pointers
            for (size_t j = 0; j < i; ++j) {
                free(records[j].data_ptr);
            }
            free(records);
            return NULL;
        }

        // Initialize the float with a random value in specified range
        *records[i].data_ptr = min_value + ((float)rand() / RAND_MAX) * (max_value - min_value);
    }

    return records;
}

void free_records(Record* records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].data_ptr);  // Free each float pointer
    }
    free(records);  // Finally, free the array of records itself
}

// Usage example:
// int main() {
