#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define Page Table Entry (PTE) structure
typedef struct {
    unsigned int valid : 1;
    unsigned int rw : 1;       // Read/Write permission
    unsigned int user : 1;     // User/Supervisor mode
    unsigned long page_frame_number; // Frame number in physical memory
} PTE;

// Define MMU structure
typedef struct {
    PTE* page_table;
    size_t num_entries;
    void* virtual_memory;
    void* physical_memory;
    size_t physical_memory_size;
    size_t page_size;
    unsigned int protection_flags;
} MMU;

// Configuration settings for dynamic memory allocation policies
typedef struct {
    size_t alignment;
    unsigned int enable_protection_features;
} MemoryConfig;

// Function prototypes
MMU* initialize_mmu(size_t num_entries, size_t physical_memory_size, size_t page_size,
                    unsigned int protection_flags, MemoryConfig config);
void free_mmu(MMU* mmu);
int add_entry_to_mmu(MMU* mmu, size_t index, unsigned long frame_number, int valid, int rw, int user);

// Mutex for thread-safe operations
pthread_mutex_t lock;

// Logging function
void log_event(const char *event) {
    // Simple logging mechanism
    printf("LOG: %s\n", event);
}

// Function to initialize MMU structures
MMU* initialize_mmu(size_t num_entries, size_t physical_memory_size, size_t page_size,
                    unsigned int protection_flags, MemoryConfig config) {

    if (num_entries == 0 || physical_memory_size == 0 || page_size == 0) {
        log_event("Invalid input parameters.");
        return NULL;
    }

    MMU* mmu = (MMU*)malloc(sizeof(MMU));
    if (!mmu) {
        log_event("Failed to allocate memory for MMU structure.");
        return NULL;
    }

    pthread_mutex_init(&lock, NULL);

    mmu->num_entries = num_entries;
    mmu->page_size = page_size;
    mmu->protection_flags = protection_flags;
    mmu->physical_memory_size = physical_memory_size;

    // Align memory allocation as per configuration
    size_t alignment = config.alignment ? config.alignment : 4096; // Default to 4KB if not specified

    mmu->page_table = (PTE*)aligned_alloc(alignment, num_entries * sizeof(PTE));
    if (!mmu->page_table) {
        free(mmu);
        log_event("Failed to allocate memory for page table.");
        return NULL;
    }

    // Allocate physical memory block
    mmu->physical_memory = malloc(physical_memory_size);
    if (!mmu->physical_memory) {
        free(mmu->page_table);
        free(mmu);
        log_event("Failed to allocate physical memory block.");
        return NULL;
    }

    mmu->virtual_memory = mmap(NULL, num_entries * page_size, PROT_READ | PROT_WRITE,
                               MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mmu->virtual_memory == MAP_FAILED) {
        free(mmu->physical_memory);
        free(mmu->page_table);
        free(mmu);
        log_event("Failed to map virtual memory.");
        return NULL;
    }

    // Initialize page table entries
    for (size_t i = 0; i < num_entries; ++i) {
        mmu->page_table[i].valid = 0;
        mmu->page_table[i].rw = protection_flags & 1;
        mmu->page_table[i].user = (protection_flags >> 1) & 1;
    }

    log_event("MMU initialized successfully.");
    return mmu;
}

// Function to free MMU structures
void free_mmu(MMU* mmu) {
    if (!mmu) return;

    munmap(mmu->virtual_memory, mmu->num_entries * mmu->page_size);
    free(mmu->physical_memory);
    free(mmu->page_table);
    pthread_mutex_destroy(&lock);
    free(mmu);

    log_event("MMU freed successfully.");
}

// Thread-safe function to add an entry to the MMU
int add_entry_to_mmu(MMU* mmu, size_t index, unsigned long frame_number, int valid, int rw, int user) {
    if (!mmu || index >= mmu->num_entries) {
        log_event("Invalid input parameters for adding page table entry.");
        return -1;
    }

    pthread_mutex_lock(&lock);

    mmu->page_table[index].valid = valid ? 1 : 0;
    mmu->page_table[index].rw = rw ? 1 : 0;
    mmu->page_table[index].user = user ? 1 : 0;
    mmu->page_table[index].page_frame_number = frame_number;

    pthread_mutex_unlock(&lock);

    log_event("Page table entry added successfully.");
    return 0;
}

// Main function for testing
int main() {
    MemoryConfig config = { .alignment = 4096, .enable_protection_features = 1 };
    MMU* mmu = initialize_mmu(1024, 1048576, 4096, 3, config);

    if (mmu) {
        add_entry_to_mmu(mmu, 0, 42, 1, 1, 1);
        free_mmu(mmu);
    }

    return 0;
}
