typedef enum { PENDING, IN_PROGRESS, COMPLETED } TaskStatus;

typedef struct Dependency {
    int task_id;
    float weight;
    time_t due_date;
    struct Dependency* next;
} Dependency;

typedef struct Task {
    int priority;
    TaskStatus status;
    Dependency* dependencies;
    int resource_allocation;
    _Bool milestone;
    struct Task* next;
} Task;

typedef struct Project {
    Task* tasks;
} Project;

void initialize_project(Project** project) {
    *project = (_aligned_malloc(sizeof(Project), 256));
    if (*project == NULL) {
        fprintf(stderr, "Memory allocation failed for project\n");
        exit(EXIT_FAILURE);
    }
    (*project)->tasks = NULL;
}

TaskStatus determine_status(int priority, int completion_time, int resource_allocation) {
    // Simplified state machine logic
    if (priority > 5 && completion_time < 10 && resource_allocation < 50)
        return COMPLETED;
    else if (completion_time >= 10 && completion_time < 20)
        return IN_PROGRESS;
    else
        return PENDING;
}

void initialize_task(Task** task, int priority) {
    *task = (_aligned_malloc(sizeof(Task), 256));
    if (*task == NULL) {
        fprintf(stderr, "Memory allocation failed for task\n");
        exit(EXIT_FAILURE);
    }

    (*task)->priority = priority;
    time_t current_time = time(NULL);
    srand((unsigned int)current_time); // Seed random number generator

    (*task)->status = determine_status(priority, rand() % 30, rand() % 100);
    (*task)->dependencies = NULL;
