#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define ALIGNMENT 64
#define MAX_TYPE_LENGTH 10

typedef enum {
    INT,
    FLOAT,
    STRING
} FieldType;

typedef struct Field {
    char *Name;
    char Type[MAX_TYPE_LENGTH];
    struct Field *next;
} Field;

typedef struct Record {
    int Key;
    char *Value;
    Field *Fields;
    struct Record *next;
} Record;

typedef struct Table {
    Record *Head;
} Table;

void align_allocation(void **ptr, size_t size) {
    uintptr_t mask = ALIGNMENT - 1;
    void *raw_ptr = malloc(size + sizeof(uintptr_t));
    if (!raw_ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    uintptr_t aligned_address = ((uintptr_t(raw_ptr) + mask) & ~mask);
    *ptr = (void *)aligned_address;
}

Table* create_table() {
    Table *table = malloc(sizeof(Table));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->Head = NULL;
    return table;
}

Record* create_record(int key) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    align_allocation((void **)&record->Value, 64);
    snprintf(record->Value, 64, "%d", key ^ (key >> 16)); // Simple hash function

    record->Key = key;
    record->Fields = NULL;
    record->next = NULL;

    return record;
}

Field* create_field(const char *name) {
    Field *field = malloc(sizeof(Field));
    if (!field) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    field->Name = strdup(name);
    if (!field->Name) {
        free(field);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    char *types[] = {"INT", "FLOAT", "STRING"};
    int type_index = rand() % 3;
    strcpy(field->Type, types[type_index]);

    field->next = NULL;

    return field;
}

void add_field_to_record(Record *record, const char *name) {
    Field *field = create_field(name);
    if (!record->Fields) {
        record->Fields = field;
    } else {
        Field *current = record->Fields;
        while (current->next) {
            current = current->next;
        }
        current->next = field;
    }
}

void add_record_to_table(Table *table, Record *record) {
    if (!table->Head) {
        table->Head = record;
    } else {
        Record *current = table->Head;
        while (current->next) {
            current = current->next;
        }
        current->next = record;
    }
}

void free_table(Table *table) {
    Record *record = table->Head;
    while (record) {
        Field *field = record->Fields;
        while (field) {
            Field *next_field = field->next;
            free(field->Name);
            free(field);
            field = next_field;
        }
        Record *next_record = record->next;
        free(record->Value);
        free(record);
        record = next_record;
    }
    free(table);
}

