#define ALIGNED_BOUNDARY 32
#define MAX_STRING_LENGTH 100

typedef struct Item {
    int key;
    char string[MAX_STRING_LENGTH];
    bool important;
} Item;

typedef struct Node {
    double value;
    struct Item *items;
    size_t item_count;
