double get_value_range_min();
double get_value_range_max();
void log_event(const char *message);
bool is_allocation_safe(size_t size);

// Helper function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Helper function to free aligned memory
void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

Node* create_linked_list() {
    size_t population_size = get_initial_population_size();
    double value_min = get_value_range_min();
    double value_max = get_value_range_max();

    Node *head = NULL;
    Node **current_node_ptr = &head;

    for (size_t i = 0; i < population_size; ++i) {
        Node *new_node = aligned_alloc(ALIGNED_BOUNDARY, sizeof(Node));
        if (!new_node || !is_allocation_safe(sizeof(Node))) {
            log_event("Allocation failed or unsafe due to fragmentation.");
            while (head) {
                Node *temp = head;
                head = head->next;
                aligned_free(temp);
            }
            return NULL;
        }

        new_node->value = value_min + ((double)rand() / RAND_MAX) * (value_max - value_min);

        size_t item_count = rand() % 10 + 1; // Random number of items
        new_node->items = aligned_alloc(ALIGNED_BOUNDARY, item_count * sizeof(Item));
        if (!new_node->items || !is_allocation_safe(item_count * sizeof(Item))) {
            log_event("Item allocation failed or unsafe due to fragmentation.");
            aligned_free(new_node);
            while (head) {
                Node *temp = head;
                head = head->next;
                aligned_free(temp);
            }
            return NULL;
        }

        new_node->item_count = item_count;
        for (size_t j = 0; j < item_count; ++j) {
            Item *new_item = &new_node->items[j];
            new_item->key = rand() % 100;
            snprintf(new_item->string, MAX_STRING_LENGTH, "Item_%zu", j);
            new_item->important = (rand() % 10) < 3; // 30% chance of being important
        }

        *current_node_ptr = new_node;
        current_node_ptr = &new_node->next;

        log_event("Node and items allocated successfully.");
    }

    return head;
}

