const int MAX_NODES = 10000;
const int COOLDOWN_PERIOD_SECONDS = 3;

struct ResourceItem {
    // Placeholder for resource item data
};

class Node {
public:
    Node(int id) : nodeId(id), primaryCooldown(0), secondaryCooldown(0) {}

    ~Node() {
        delete[] resources;
    }

    void addResourceItems(int itemCount) {
        items.reserve(itemCount);
        ResourceItem* newResources = new ResourceItem[itemCount];
        for (int i = 0; i < itemCount; ++i) {
            newResources[i] = ResourceItem(); // Initialize each item
            items.push_back(newResources[i]);
        }
        resources = newResources;
    }

    void updateCooldowns(int primaryAction, int secondaryAction) {
        if (primaryCooldown <= 0) {
            selectedPrimaryAction = primaryAction;
            primaryCooldown = COOLDOWN_PERIOD_SECONDS;
        } else {
            selectedPrimaryAction = -1; // Indicate cooldown
        }

        if (secondaryCooldown <= 0) {
            selectedSecondaryAction = secondaryAction;
            secondaryCooldown = COOLDOWN_PERIOD_SECONDS;
        } else {
            selectedSecondaryAction = -1; // Indicate cooldown
        }

        std::cout << "Primary Action: " << selectedPrimaryAction 
                  << ", Secondary Action: " << selectedSecondaryAction << std::endl;

        --primaryCooldown;
        --secondaryCooldown;
    }

private:
    int nodeId;
    ResourceItem* resources = nullptr;
    std::vector<ResourceItem> items;
    int primaryCooldown;
    int secondaryCooldown;
    int selectedPrimaryAction = -1;
    int selectedSecondaryAction = -1;

    // Cache to store recently used resource types
    std::unordered_map<int, bool> resourceCache; // Limited to 50 entries

    void cacheResourceType(int type) {
        if (resourceCache.size() >= 50) {
            auto it = resourceCache.begin();
            resourceCache.erase(it);
        }
        resourceCache[type] = true;
    }
};

class SimulationModule {
public:
    SimulationModule() : nodes(new Node[MAX_NODES]) {}

    ~SimulationModule() {
        delete[] nodes;
    }

    void initializeNodes(int nodeCount) {
        for (int i = 0; i < nodeCount; ++i) {
            int itemCount = i + 1; // Example logic to determine item count
            nodes[i] = Node(i);
            nodes[i].addResourceItems(itemCount);
        }
    }

    void startActionCooldowns(int primaryActions, int secondaryActions) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> disPrimary(0, primaryActions - 1);
        std::uniform_int_distribution<> disSecondary(0, secondaryActions - 1);

        while (true) {
            for (int i = 0; i < MAX_NODES; ++i) {
                nodes[i].updateCooldowns(disPrimary(gen), disSecondary(gen));
            }
            std::this_thread::sleep_for(std::chrono::seconds(COOLDOWN_PERIOD_SECONDS));
        }
    }

private:
    Node* nodes;
};

int main() {
    SimulationModule simulation;
    simulation.initializeNodes(10000); // Example initialization
    int primaryActions = 5; // Example number of primary actions
    int secondaryActions = 3; // Example number of secondary actions

    std::thread actionThread(&SimulationModule::startActionCooldowns, &simulation, primaryActions, secondaryActions);
    actionThread.detach();

    return 0;
}
