        items[i].dblValue = i * 1.23;

        records[i]->dataItem = (struct item*)malloc(sizeof(struct item));
        memcpy(records[i]->dataItem, &items[i], sizeof(struct item));
    }

    jlong totalMemoryUsage = 0;

    // Calculate total memory usage
    for (int i = 0; i < num_records; ++i) {
        jlong size = (jlong)(sizeof(long) + sizeof(double) + STRING_LENGTH * sizeof(char)
            + sizeof(unsigned int) + sizeof(Record*) + sizeof(int)
            + strlen(records[i]->identifier) + 1 + sizeof(struct item));
        totalMemoryUsage += size;
    }

    while (totalMemoryUsage > MAX_MEMORY_USAGE && num_records > 0) {
        release_lru_record(records, &num_records);

        // Recalculate memory usage
