    char* str;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t total_memory;
    pthread_mutex_t lock;
} MemoryPool;

void init_random() {
    srand((unsigned)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* allocate_string(size_t length) {
    if (length > MAX_STRING_LENGTH) length = MAX_STRING_LENGTH;
    char* str = (char*)malloc(length);
    memset(str, 0, length);
    return str;
}

MemoryPool* init_memory_pool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->head = NULL;
    pool->total_memory = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void free_string(char* str) {
    if (str) free(str);
}

void destroy_pool(MemoryPool* pool) {
    Node* current = pool->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free_string(temp->record.str);
        free(temp);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void insert_record(MemoryPool* pool, int min_val, int max_val) {
    pthread_mutex_lock(&pool->lock);

    if (pool->total_memory > MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded!\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    pool->total_memory += sizeof(Record) + MAX_STRING_LENGTH;

    new_node->record.value = random_int(min_val, max_val);
    new_node->record.str = allocate_string(MAX_STRING_LENGTH);

    // Insert at head for simplicity
    new_node->next = pool->head;
    pool->head = new_node;

    pthread_mutex_unlock(&pool->lock);
}

void delete_record(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->head) {
        printf("No records to delete!\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    Node* temp = pool->head;
    pool->head = pool->head->next;

    free_string(temp->record.str);
    pool->total_memory -= sizeof(Record) + MAX_STRING_LENGTH;
    free(temp);

    pthread_mutex_unlock(&pool->lock);
}

void traverse_records(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    Node* current = pool->head;
    while (current) {
        printf("Value: %d, String: %s\n", current->record.value, current->record.str);
        current = current->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    init_random();
    MemoryPool* pool = init_memory_pool();

    // Example usage
    insert_record(pool, 1, 100);
    insert_record(pool, 1, 100);

    traverse_records(pool);

    delete_record(pool);
    traverse_records(pool);

    destroy_pool(pool);
    return 0;
}
