    qsort(records, num_records, sizeof(record), [](const void *a, const void *b) -> int {
        return ((record*)a)->value - ((record*)b)->value;
    });

    return records;
}

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = capacity;
    table->count = 0;
    table->buckets = calloc(capacity, sizeof(HashEntry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    return table;
}

unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

