    if ((double)table->count / table->capacity >= LOAD_FACTOR) {
        // Rehashing logic here
    }

    unsigned long bucket_index = hash(key, table->capacity);
    HashEntry *entry = malloc(sizeof(HashEntry));
    if (!entry) return -1;

    entry->key = key;
    entry->index = index;
    entry->next = table->buckets[bucket_index];
    table->buckets[bucket_index] = entry;
    ++table->count;

    return 0;
}

record* find_record_by_key(HashTable *table, int key) {
    unsigned long bucket_index = hash(key, table->capacity);
    for (HashEntry *entry = table->buckets[bucket_index]; entry; entry = entry->next) {
        if (entry->key == key) {
            return &records[entry->index];
        }
    }
    return NULL;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashEntry *entry = table->buckets[i];
        while (entry) {
            HashEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

