    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        deallocate_record(&(temp->record));
        free(temp);
    }
    pthread_mutex_destroy(&collection->lock);
    pthread_cond_destroy(&collection->cond);
    free(collection);
}

void insert_record(RecordCollection* collection, int min_val, int max_val) {
    pthread_mutex_lock(&collection->lock);

    while (collection->total_memory_allocated >= MEMORY_THRESHOLD) {
        pthread_cond_wait(&collection->cond, &collection->lock);
    }

    Record* record = allocate_record();
    record->value = rand() % (max_val - min_val + 1) + min_val;
    record->str = malloc(MAX_STRING_LENGTH);
    snprintf(record->str, MAX_STRING_LENGTH, "String_%d", record->value);

    Node* new_node = malloc(sizeof(Node));
    new_node->record = *record;
    new_node->next = collection->head;
    collection->head = new_node;

    collection->total_memory_allocated += sizeof(Record) + MAX_STRING_LENGTH;

    pthread_mutex_unlock(&collection->lock);
}

