    free(int_array);

    EVP_CIPHER_CTX ctx;
    if (initialize_cipher(&ctx, "password", 10000) != 0) {
        log_error("Cipher initialization failed");
    } else {
        // Use the cipher context
        EVP_CIPHER_CTX_cleanup(&ctx);
    }
}

int main() {
    srand(time(NULL));
    manage_structures();
    return 0;
}
