}

void* aligned_realloc(void *ptr, size_t alignment, size_t old_size, size_t new_size) {
    void *new_ptr = NULL;
#if defined(_WIN32)
    new_ptr = _aligned_realloc(ptr, new_size, alignment);
#else
    if (posix_memalign(&new_ptr, alignment, new_size)) {
        new_ptr = NULL;
    }
    free(ptr);
#endif
    return new_ptr;
}

void log_error(const char *message) {
