int init_module(ModuleConfig config, DataRecord ***records, sem_t **semaphore) {
    if (config.max_records == 0 || config.random_value_range == 0 || config.initial_semaphore_value < 0) {
        log_error("Invalid configuration parameters.");
        return -1;
    }

    size_t record_size = sizeof(DataRecord);
    size_t total_size = config.max_records * record_size;

    if (total_size > SIZE_MAX / config.max_records) {
        log_error("Requested memory size exceeds system limits.");
        return -2;
    }

    *records = aligned_alloc(16, total_size);
    if (*records == NULL) {
        log_error("Memory allocation failed for records.");
        return -3;
    }

    sem_init(semaphore, 0, config.initial_semaphore_value);

    for (size_t i = 0; i < config.max_records; ++i) {
        (*records)[i].rnti = rand() % 1000; // Example RNTI value
        (*records)[i].crc_ind_rel8.CRCFLAG = rand() % config.random_value_range;
    }

    return 0;
}

void cleanup_module(DataRecord **records, sem_t *semaphore) {
    free(*records);
    sem_destroy(semaphore);
}
