#define ALIGNMENT 32
#define NODE_COUNT 100
#define ITEM_PER_NODE 10
#define KEY_LENGTH 8
#define HASH_TABLE_INITIAL_CAPACITY 128

typedef struct Item {
    int key;
    char string[KEY_LENGTH + 1];
    struct Item* next;
} Item;

typedef struct Node {
    double value;
    Item* items_head;
} Node;

typedef struct Record {
    int value;
