static void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Failed to allocate
    }
    return ptr;
}

static void free_aligned(void* ptr) {
    free(ptr);
}

typedef struct {
    void* pool;
    size_t capacity;
    size_t used;
} CustomAllocator;

static CustomAllocator custom_allocator_create(size_t initial_capacity) {
    CustomAllocator allocator = {
        .pool = aligned_alloc(initial_capacity, ALIGNMENT),
        .capacity = initial_capacity,
        .used = 0
    };
    return allocator;
}

static void* custom_allocate(CustomAllocator* allocator, size_t size) {
    if (allocator->used + size > allocator->capacity) {
        size_t new_capacity = allocator->capacity * 2;
        void* new_pool = aligned_alloc(new_capacity, ALIGNMENT);
        if (!new_pool) {
            return NULL; // Failed to allocate
        }
        memcpy(new_pool, allocator->pool, allocator->used);
        free_aligned(allocator->pool);
        allocator->pool = new_pool;
        allocator->capacity = new_capacity;
    }

    void* ptr = (char*)allocator->pool + allocator->used;
    allocator->used += size;
    return ptr;
}

static void custom_deallocate(CustomAllocator* allocator) {
    free_aligned(allocator->pool);
    allocator->pool = NULL;
    allocator->capacity = 0;
    allocator->used = 0;
}

static unsigned int hash(int key, size_t table_size) {
    return (unsigned int)(key % table_size);
}

static Node* initialize_nodes(CustomAllocator* allocator) {
    Node* nodes = custom_allocate(allocator, NODE_COUNT * sizeof(Node));
