        Item* head = custom_allocate(allocator, ITEM_PER_NODE * sizeof(Item));

        Item* current = head;
        for (int j = 0; j < ITEM_PER_NODE - 1; ++j) {
            current->key = rand() % 1000000; // Unique integer key
            for (int k = 0; k < KEY_LENGTH; ++k) {
                char c = (rand() % 2) ? (rand() % 26 + 'A') : (rand() % 10 + '0');
                current->string[k] = c;
            }
            current->string[KEY_LENGTH] = '\0';
            current->next = custom_allocate(allocator, sizeof(Item));
            current = current->next;
        }

        // Initialize the last item
        current->key = rand() % 1000000; 
        for (int k = 0; k < KEY_LENGTH; ++k) {
            char c = (rand() % 2) ? (rand() % 26 + 'A') : (rand() % 10 + '0');
            current->string[k] = c;
        }
        current->string[KEY_LENGTH] = '\0';
        current->next = NULL;

        nodes[i].items_head = head;
    }

    return nodes;
}

static int* create_hash_table(CustomAllocator* allocator) {
    size_t table_size = HASH_TABLE_INITIAL_CAPACITY;
    int* hash_table = custom_allocate(allocator, table_size * sizeof(int));
    for (size_t i = 0; i < table_size; ++i) {
        hash_table[i] = -1; // Sentinel value indicating empty slot
    }
