#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <stdint.h>

#define ALIGNMENT 32
#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2
#define ITEM_STRING_LENGTH 8

typedef struct {
    int key;
    char str[ITEM_STRING_LENGTH + 1];
} item;

typedef struct node {
    double value;
    item *items;
    size_t item_count;
    size_t capacity;
} node;

typedef struct hash_table {
    node **nodes;
    size_t count;
    size_t capacity;
} hash_table;

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__GNUC__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#else
#error "Platform not supported"
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__GNUC__)
    free(ptr);
#endif
}

hash_table* create_hash_table(size_t initial_capacity) {
    hash_table *table = (hash_table*)aligned_alloc(ALIGNMENT, sizeof(hash_table));
    table->nodes = (node**)aligned_alloc(ALIGNMENT, initial_capacity * sizeof(node*));
    table->count = 0;
    table->capacity = initial_capacity;
    memset(table->nodes, 0, initial_capacity * sizeof(node*));
    return table;
}

void free_hash_table(hash_table *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->nodes[i]) {
            aligned_free(table->nodes[i]->items);
            aligned_free(table->nodes[i]);
        }
    }
    aligned_free(table->nodes);
    aligned_free(table);
}

int hash(int key, size_t capacity) {
    return abs(key % capacity);
}

void resize_hash_table(hash_table *table) {
    size_t new_capacity = table->capacity * GROWTH_FACTOR;
    node **new_nodes = (node**)aligned_alloc(ALIGNMENT, new_capacity * sizeof(node*));
    memset(new_nodes, 0, new_capacity * sizeof(node*));

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->nodes[i]) {
            int index = hash(table->nodes[i]->items[0].key, new_capacity);
            while (new_nodes[index]) {
                index = (index + 1) % new_capacity;
            }
            new_nodes[index] = table->nodes[i];
        }
    }

    aligned_free(table->nodes);
    table->nodes = new_nodes;
    table->capacity = new_capacity;
}

void insert_into_hash_table(hash_table *table, node *node_item) {
    if (table->count >= table->capacity) {
        resize_hash_table(table);
    }
    int index = hash(node_item->items[0].key, table->capacity);
    while (table->nodes[index]) {
        index = (index + 1) % table->capacity;
    }
    table->nodes[index] = node_item;
    table->count++;
}

node* create_node(double value) {
    node *n = (node*)aligned_alloc(ALIGNMENT, sizeof(node));
    n->value = value;
    n->item_count = 0;
    n->capacity = INITIAL_CAPACITY;
    n->items = (item*)aligned_alloc(ALIGNMENT, n->capacity * sizeof(item));
    return n;
}

void free_node(node *n) {
    aligned_free(n->items);
    aligned_free(n);
}

node** initialize_nodes(size_t num_nodes, int min_value, int max_value) {
    node **nodes = (node**)aligned_alloc(ALIGNMENT, num_nodes * sizeof(node*));

    srand(time(NULL));  // Initialize random seed
    for (size_t i = 0; i < num_nodes; ++i) {
        double value = sqrt((double)(rand() % (max_value - min_value + 1)) + min_value);

        node *n = create_node(value);
        size_t initial_items_count = rand() % INITIAL_CAPACITY;
        n->item_count = initial_items_count;

        for (size_t j = 0; j < initial_items_count; ++j) {
            int key = rand();
            char str[ITEM_STRING_LENGTH + 1];
            for (int k = 0; k < ITEM_STRING_LENGTH; ++k) {
                str[k] = (rand() % 2) ? 'a' + rand() % 26 : '0' + rand() % 10;
            }
            str[ITEM_STRING_LENGTH] = '\0';

            if (n->item_count == n->capacity) {
                n->capacity *= GROWTH_FACTOR;
                item *new_items = (item*)aligned_alloc(ALIGNMENT, n->capacity * sizeof(item));
                memcpy(new_items, n->items, n->item_count * sizeof(item));
                aligned_free(n->items);
                n->items = new_items;
            }

            n->items[n->item_count].key = key;
            strcpy(n->items[n->item_count].str, str);
            ++n->item_count;
        }

        nodes[i] = n;
    }

    return nodes;
}

int compare_nodes(const void *a, const void *b) {
    node *node_a = *(node**)a;
    node *node_b = *(node**)b;
    return (node_a->value < node_b->value) ? -1 : 1;
}

hash_table* manage_complex_structures(size_t num_nodes, int min_value, int max_value) {
    hash_table *table = create_hash_table(INITIAL_CAPACITY);

    node **nodes = initialize_nodes(num_nodes, min_value, max_value);

    for (size_t i = 0; i < num_nodes; ++i) {
        insert_into_hash_table(table, nodes[i]);
    }

    qsort(nodes, num_nodes, sizeof(node*), compare_nodes);

    // Optional: verify integrity of the data structure
    for (size_t i = 0; i < num_nodes - 1; ++i) {
        if (nodes[i]->value > nodes[i + 1]->value) {
            fprintf(stderr, "Data integrity check failed\n");
        }
    }

    // Return the hash table containing all nodes.
    return table;
}

int main() {
    size_t num_nodes = 10;
    int min_value = 1;
    int max_value = 100;

    hash_table *table = manage_complex_structures(num_nodes, min_value, max_value);

    // Use the structure for further processing

    free_hash_table(table);

    return 0;
}
```

### Key Points
- The code provides functions to allocate aligned memory using a custom allocator.
- Implements a basic hash table with linear probing and resizing when full.
- Nodes are initialized with random double values from their square roots, along with linked lists of items.
- Each item is populated with unique keys and random alphanumeric strings.
- After initialization, nodes are sorted based on the `double` value for efficiency in lookups.
- Includes mechanisms to handle memory allocation failures gracefully.']

