typedef struct Record {
    int key;
    double value;
    char* metadata;
    long timestamp;  // Milliseconds since epoch
    struct Record* next;
    struct Record* prev;
} Record;

#define ALIGNMENT 16

Record* allocate_aligned(size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        return NULL;
    }
    return (Record*)ptr;
}

void free_aligned(Record* records, size_t count) {
