int get_timestamp_ms() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (tv.tv_sec * 1000) + (tv.tv_usec / 1000);
}

int verify_integrity(Record* head) {
    if (!head) return 1; // Empty list is fine

    Record* slow = head;
    Record* fast = head->next;

    while (fast && fast->next) {
        if (slow == fast) return 0; // Cycle detected
        slow = slow->next;
        fast = fast->next->next;
    }

    Record* current = head;
    while (current) {
        if (current->prev != NULL && current->prev->next != current) return 0;
        if (current->next != NULL && current->next->prev != current) return 0;
        current = current->next;
    }

    return 1; // Integrity verified
}

void populate_record(Record* record, int key, double value, const char* metadata) {
    record->key = key;
    record->value = value;
    record->metadata = strdup(metadata);
    if (!record->metadata) { 
        fprintf(stderr, "Memory allocation for metadata failed\n");
        exit(EXIT_FAILURE); 
    }
    record->timestamp = get_timestamp_ms();
}

void manage_storage_hierarchy(Record** head, size_t count) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    *head = allocate_aligned(sizeof(Record) * count);
    if (!*head) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        (*head)[i].next = (&(*head)[i + 1]);
        (*head)[i].prev = (&(*head)[i - 1]);

        // Simulate data population
        populate_record(&(*head)[i], i, (double)i * 2.5, "metadata");

        if (i == count - 1) {
            (*head)[i].next = NULL;
        }
    }

    pthread_mutex_lock(&lock);
    if (!verify_integrity(*head)) {
        fprintf(stderr, "Data structure integrity check failed\n");
        free_aligned(*head, count);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&lock);

    // Example of handling a data source failure
    for (size_t i = 0; i < count; ++i) {
        if ((*head)[i].value == -1.0) { // Simulate missing or corrupted value
            (*head)[i].value = 0.0;
            fprintf(stderr, "Fallback mechanism applied to record %zu\n", i);
        }
    }

    pthread_mutex_destroy(&lock);
}

int main() {
    Record* storage_head = NULL;
    size_t data_count = 10; // Example count

    manage_storage_hierarchy(&storage_head, data_count);

    for (size_t i = 0; i < data_count; ++i) {
        printf("Record %zu: Key=%d, Value=%.2f, Metadata=%s, Timestamp=%ld\n", 
            i, storage_head[i].key, storage_head[i].value, storage_head[i].metadata, storage_head[i].timestamp);
    }

    free_aligned(storage_head, data_count);

    return 0;
}
