    int quantity;
    float price;
    char *description;
    struct stock_item *prev, *next;
} StockItem;

typedef struct {
    StockItem *head, *tail;
} ItemList;

#define ALIGNMENT 128

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void aligned_free(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

float adjust_price(Category category, int quantity) {
    float base_price = 10.0f; // Base price for simplicity

    switch (category) {
        case ELECTRONICS:
            return base_price * (1 + 0.05 * quantity / 100);
        case CLOTHING:
            return base_price * (1 + 0.03 * quantity / 100);
        case GROCERIES:
            return base_price * (1 - 0.02 * quantity / 100);
    }

    return base_price;
}

void initialize_stock_item(StockItem* item, Category category, int quantity) {
    item->category = category;
    item->quantity = quantity;
    item->price = adjust_price(category, quantity);

    const char *template_str = "Category: %d, Quantity: %d";
    size_t template_len = strlen(template_str);
    size_t desc_size = snprintf(NULL, 0, template_str, category, quantity) + 1;

    item->description = aligned_alloc(ALIGNMENT, desc_size);

    if (item->description) {
        snprintf(item->description, desc_size, template_str, category, quantity);
    } else {
        fprintf(stderr, "Memory allocation failed for description\n");
    }
}

ItemList* create_item_list() {
    ItemList *list = aligned_alloc(ALIGNMENT, sizeof(ItemList));
    if (!list) {
