size_t current_memory_usage = 0;

void log_memory_adjustment(size_t amount, const char* action) {
    printf("Memory %s by %zu bytes.\n", action, amount);
}

void initialize_arrays(long **offsets, int **keys, Record ***records, char ***metadata_strings, time_t **timestamps, size_t record_count) {
    pthread_t self = pthread_self();
    long seed = (long)self;
    srand(seed);

    // Allocate memory for arrays
    *offsets = malloc(record_count * sizeof(long));
    *keys = malloc(record_count * sizeof(int));
    *records = malloc(record_count * sizeof(Record*));
    *metadata_strings = malloc(record_count * sizeof(char *));
    *timestamps = malloc(record_count * sizeof(time_t));

    if (!*offsets || !*keys || !*records || !*metadata_strings || !*timestamps) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if (!(*records)[i]) {
            fprintf(stderr, "Failed to allocate memory for records[i]\n");
            exit(EXIT_FAILURE);
        }

        // Initialize metadata string
        snprintf((*metadata_strings)[i], 256, "Config_%zu_Timestamp_%ld", i, time(NULL));

        (*records)[i]->value = rand() % 100;  // Random value within a range (example: 0-99)
        sprintf((*records)[i]->string_rep, "Record_%zu_%ld", i, time(NULL));

        (*records)[i]->item = malloc(sizeof(Item));
        if (!(*records)[i]->item) {
            fprintf(stderr, "Failed to allocate memory for item\n");
            exit(EXIT_FAILURE);
        }

        // Initialize Item structure
        (*records)[i]->item->size = sizeof(double);  // Using double here
        (*records)[i]->item->d_value = 
            ((*records)[i]->value + time(NULL) + (rand() % 100)) / 3.0;

        strcpy((*records)[i]->metadata, (*metadata_strings)[i]);
        (*records)[i]->timestamp = time(NULL);

        // Update memory usage
        pthread_mutex_lock(&mutex);
        current_memory_usage += sizeof(long) + sizeof(int) + 
                                sizeof(Record*) + sizeof(char *) + sizeof(time_t) +
                                sizeof(Record) + sizeof(Item);
        log_memory_adjustment(current_memory_usage, "allocated");

        if (current_memory_usage > MAX_MEMORY_USAGE) {
            // Free memory of least recently used records
            free((*records)[i]);
            current_memory_usage -= sizeof(Record) + sizeof(Item);
            log_memory_adjustment(sizeof(Record) + sizeof(Item), "freed");
        }
        pthread_mutex_unlock(&mutex);
    }

    // Ensure the total memory usage is below limit
    if (current_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeded after allocation.\n");
        exit(EXIT_FAILURE);
    }
}

