### Java Code

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class ConnectionManager {

    private static final int RETRY_LIMIT = 3;
    private static final long TIMEOUT_MILLIS = 5000; // Timeout for connection attempts

    public void establishConnection(String host, int port) {
        int retryCount = 0;

        while (retryCount < RETRY_LIMIT) {
            try (SocketChannel socketChannel = SocketChannel.open()) {
                socketChannel.configureBlocking(false);

                if (socketChannel.connect(new InetSocketAddress(host, port)).get() || 
                    socketChannel.finishConnect()) {

                    // Connection successful
                    System.out.println("Connection established to " + host + ":" + port);
                    return;
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Failed to connect: " + e.getMessage());
                retryCount++;

                if (retryCount >= RETRY_LIMIT) {
                    System.err.println("Reached maximum retry attempts. Exiting.");
                }

                try {
                    Thread.sleep(TIMEOUT_MILLIS);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        System.err.println("Connection failed after multiple attempts.");
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        manager.establishConnection("example.com", 8080);
    }
}
```

