#define ALIGNMENT 32

typedef struct node {
    char *buffer;
    size_t length;
} node;

typedef struct event {
    time_t timestamp;
    node *node_ref;
} event;

typedef struct log_entry {
    char message[256];
} log_entry;

void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
#if defined(_WIN32) || defined(_WIN64)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // posix_memalign returns non-zero on failure
    }
#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;  // posix_memalign returns non-zero on failure
    }
#endif
    return ptr;
}

int validate_log_entry(log_entry* entry) {
    // Simple validation: ensure message is not empty and does not exceed buffer limits.
    return strlen(entry->message) > 0 && strlen(entry->message) < sizeof(entry->message);
}

void initialize_data_structures(node **nodes, event *events, log_entry *logs, size_t num_nodes, size_t num_logs, size_t node_buffer_size) {
    // Calculate aligned buffer size
    size_t aligned_node_buffer_size = ((node_buffer_size + (ALIGNMENT - 1)) / ALIGNMENT) * ALIGNMENT;

    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i] = malloc(sizeof(node));
        if (!nodes[i]) {
            fprintf(stderr, "Memory allocation failed for node %zu\n", i);
            exit(EXIT_FAILURE);
        }

        // Allocate and align buffer
        nodes[i]->buffer = aligned_alloc(aligned_node_buffer_size, ALIGNMENT);
        if (!nodes[i]->buffer) {
            fprintf(stderr, "Memory allocation failed for node buffer %zu\n", i);
            free(nodes[i]);
            exit(EXIT_FAILURE);
        }

        nodes[i]->length = aligned_node_buffer_size;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        events[i].timestamp = time(NULL); // Unique timestamp for each event
        events[i].node_ref = nodes[i];
    }

    for (size_t i = 0; i < num_logs; ++i) {
        snprintf(logs[i].message, sizeof(logs[i].message), "Log entry %zu", i);

        if (!validate_log_entry(&logs[i])) {
            fprintf(stderr, "Invalid log entry at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
