```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
} Record;

// Configuration structure
typedef struct {
    size_t max_records;
    int min_value;
    int max_value;
    size_t alignment_boundary;
    int max_retries;
    const char *log_file_path;
} Config;

// Function prototypes
void log_message(const char *message);
void handle_allocation_failure(void **ptr, size_t size, int retries, int max_retries);
size_t aligned_alloc(size_t size, size_t alignment);
void integrity_check(Record *records, size_t num_records, int min_value, int max_value);

// Main function to manage dynamic memory allocation
int allocate_and_initialize(Config config) {
    FILE *log_file = fopen(config.log_file_path, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    Record *record_array = NULL;
    size_t total_size = 0;
    int retries = 0;

    while (retries < config.max_retries) {
        total_size = sizeof(Record) * config.max_records;

        handle_allocation_failure((void **)&record_array, total_size, retries, config.max_retries);
        if (!record_array) {
            retries++;
            log_message("Allocation failed, retrying...");
            continue;
        }

        // Align the memory
        record_array = (Record *)aligned_alloc(config.alignment_boundary, total_size);
        if (!record_array) {
            free(record_array);
            retries++;
            log_message("Aligned allocation failed, retrying...");
            continue;
        }

        // Initialize records with random values within specified range
        srand((unsigned int)time(NULL));
        for (size_t i = 0; i < config.max_records; ++i) {
            record_array[i].value = rand() % (config.max_value - config.min_value + 1) + config.min_value;
        }

        // Perform integrity check
        integrity_check(record_array, config.max_records, config.min_value, config.max_value);

        log_message("Memory allocation and initialization successful.");
        break;
    }

    if (!record_array) {
        log_message("Failed to allocate memory after maximum retries.");
        fclose(log_file);
        return -1;
    }

    // Log final allocation details
    fprintf(log_file, "Allocated size: %zu, Alignment: %zu\n", total_size, config.alignment_boundary);
    fclose(log_file);

    // Clean up resources (for demonstration purposes)
    free(record_array);
    record_array = NULL;

    return 0;
}

// Utility function for logging messages
void log_message(const char *message) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("allocation_log.txt", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open default log file.\n");
        }
    }

    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);  // Ensure the message is written immediately
    }
}

// Handle allocation failures with retries
void handle_allocation_failure(void **ptr, size_t size, int retries, int max_retries) {
    *ptr = malloc(size);
    if (*ptr == NULL && retries < max_retries - 1) {
        free(*ptr);  // Safe to call free(NULL)
        usleep(100000);  // Sleep for 0.1 seconds before retrying
    }
}

// Align memory allocation
size_t aligned_alloc(size_t size, size_t alignment) {
    void *mem = NULL;
#ifdef _WIN32
    mem = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&mem, alignment, size)) {
        return 0;  // Allocation failed
    }
#endif
    return (size_t)mem;
}

// Perform an integrity check on the records
void integrity_check(Record *records, size_t num_records, int min_value, int max_value) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value < min_value || records[i].value > max_value) {
            fprintf(stderr, "Integrity check failed: Record[%zu] value out of range.\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    Config config = {1000, 1, 100, 16, 3, "allocation_log.txt"};

    if (allocate_and_initialize(config) != 0) {
        fprintf(stderr, "Memory allocation and initialization failed.\n");
        return EXIT_FAILURE;
    }

    printf("Operation completed successfully.\n");
    return EXIT_SUCCESS;
}
```

### Explanation:

1. **Configuration Management**: The `Config` structure allows flexible setting of parameters such as maximum records, value range for records, alignment boundary, and logging details.

2. **Memory Allocation and Alignment**: The function uses platform-specific methods (`_aligned_malloc` on Windows and `posix_memalign` on others) to allocate aligned memory. A utility function `aligned_alloc` abstracts this logic.

3. **Retry Mechanism**: If an allocation fails, the program retries up to a configured limit with a brief pause between attempts (`usleep`). The function gracefully handles repeated failures by logging each attempt.

4. **Integrity Check**: After initializing records, the function verifies that all values fall within the specified range and logs errors if not.

5. **Logging**: Logs are maintained in both a file (specified in `Config`) and a default log (`allocation_log.txt`). All messages include details about allocations and retries for better traceability.

6. **Error Handling**: The code checks allocation results and handles errors by logging them, ensuring that failures are documented without crashing the program unless critical issues arise during integrity checks.']

