int thread_safe_random(int min, int max) {
    static unsigned int seed = 0;
    pthread_mutex_lock(&rand_lock);

    if (seed == 0) {
        srand(time(NULL));
        seed = rand();
    }

    int result = min + rand_r(&seed) % (max - min + 1);
    pthread_mutex_unlock(&rand_lock);
    return result;
}

