    *keys = (int *)allocate_aligned_memory(num_keys * sizeof(int), alignment);

    if (!*offsets || !*keys) {
        log_error("Memory allocation failed");
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize offsets and keys
    for (int i = 0; i < num_offsets; i++) {
        (*offsets)[i] = thread_safe_random(0, 100000); // Example range
    }

    for (int i = 0; i < num_keys; i++) {
