#endif
    return ptr;
}

// Helper function for freeing aligned memory
void aligned_free(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Generate a random alphanumeric string
void generate_random_string(char* str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

// Create a new item
Item* create_item(int key, size_t string_length) {
    Item* item = (Item*)aligned_alloc(ALIGNMENT, sizeof(Item));
    if (!item) return NULL;

    item->key = key;
    generate_random_string(item->string, string_length);
    item->next = NULL;
    return item;
}

// Create a new node
Node* create_node(double value, Item* items) {
    Node* node = (Node*)aligned_alloc(ALIGNMENT, sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->items = items;
    return node;
}

// Create a new record
Record* create_record(long offset, int key, Node* node) {
    Record* record = (Record*)aligned_alloc(ALIGNMENT, sizeof(Record));
    if (!record) return NULL;

    record->offset = offset;
    record->key = key;
    record->node = node;
    record->next = NULL;
    return record;
}

// Add a record to the collection
void add_record(Record** head, Record* new_record) {
    new_record->next = *head;
    *head = new_record;
}

// Delete a record from the collection
void delete_record(Record** head, int key) {
    Record **indirect = head;

    while (*indirect && (*indirect)->key != key) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        Record* to_delete = *indirect;
        *indirect = (*indirect)->next;
        free(to_delete->node);
        aligned_free(to_delete);
    }
}

