    RecordSet *record_set = malloc(sizeof(RecordSet));
    if (!record_set) return NULL;

    record_set->records = malloc(initial_capacity * sizeof(Record));
    if (!record_set->records) {
        free(record_set);
        return NULL;
    }

    record_set->capacity = initial_capacity;
    record_set->count = 0;
    pthread_mutex_init(&record_set->lock, NULL);

    return record_set;
}

void resize_record_set(RecordSet *record_set, size_t new_capacity) {
    Record *new_records = realloc(record_set->records, new_capacity * sizeof(Record));
    if (!new_records) return;

    record_set->records = new_records;
    record_set->capacity = new_capacity;
}

int insert_record(RecordSet *record_set, int key_range_min, int key_range_max) {
    pthread_mutex_lock(&record_set->lock);

    if (record_set->count >= record_set->capacity) {
        resize_record_set(record_set, record_set->capacity * 2);
