    atomic_int offset_thread_created = 0;
    atomic_int keys_thread_created = 0;
    atomic_int records_thread_created = 0;

    // Function to initialize offsets
    auto init_offsets = [](void *arg) {
        long *offsets = (long *)arg;
        for (size_t i = 0; i < offsets_size; ++i) {
            offsets[i] = i * sizeof(long);
        }
        atomic_fetch_add(&offset_thread_created, 1);
    };

    // Function to initialize keys
    auto init_keys = [](void *arg) {
        int *keys = (int *)arg;
        for (size_t i = 0; i < keys_size; ++i) {
            keys[i] = thread_safe_random(0, 100); // Example range
        }
        atomic_fetch_add(&keys_thread_created, 1);
    };

    // Function to initialize records
    auto init_records = [](void *arg) {
        record *records = (record *)arg;
        for (size_t i = 0; i < records_size; ++i) {
            records[i].value = thread_safe_random(rand_min, rand_max);
        }
        atomic_fetch_add(&records_thread_created, 1);
    };

    pthread_create(&threads[0], NULL, reinterpret_cast<void *(*)(void *)>(init_offsets), offsets);
    pthread_create(&threads[1], NULL, reinterpret_cast<void *(*)(void *)>(init_keys), keys);
    pthread_create(&threads[2], NULL, reinterpret_cast<void *(*)(void *)>(init_records), records);

    // Wait for all threads to complete
    for (int i = 0; i < 3; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!(offset_thread_created && keys_thread_created && records_thread_created)) {
        fprintf(stderr, "Initialization failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Return pointer to allocated and initialized data structures
    void *result[3] = {offsets, keys, records};
    return result;
}

int main() {
    size_t offsets_size = 1000;
    size_t keys_size = 500;
    size_t records_size = 200;
    int rand_min = -50;
    int rand_max = 50;

    void *data_structures[3];
    data_structures[0] = init_data_structures(offsets_size, keys_size, records_size, rand_min, rand_max);

    if (data_structures[0]) {
        long *offsets = (long *)data_structures[0][0];
        int *keys = (int *)data_structures[0][1];
        record *records = (record *)data_structures[0][2];

        // Use the data structures as needed...

        free(offsets);
        free(keys);
        free(records);
    } else {
        fprintf(stderr, "Failed to initialize data structures\n");
    }

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used for thread-safe random number generation.
- **Error Handling**: The function checks for memory allocation failures and cleans up resources if any allocation fails.
- **Concurrency**: Three threads are created to initialize the data structures concurrently, improving performance while ensuring data integrity with atomic operations.']

