} RecordList;

#define INITIAL_CAPACITY 10

// Function to load configuration from JSON file
void load_config(const char *filename, int *map_width, int *map_height, int *tile_size, float *viewport_speed) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    json_t *width = json_object_get(root, "map_width");
    json_t *height = json_object_get(root, "map_height");
    json_t *tile_size_json = json_object_get(root, "tile_size");
    json_t *speed = json_object_get(root, "viewport_speed");

    if (!json_is_integer(width) || !json_is_integer(height) ||
        !json_is_real(tile_size_json) || !json_is_real(speed)) {
        fprintf(stderr, "Invalid JSON format\n");
        json_decref(root);
        exit(EXIT_FAILURE);
    }

    *map_width = json_integer_value(width);
    *map_height = json_integer_value(height);
    *tile_size = (int)json_number_value(tile_size_json);
    *viewport_speed = (float)json_number_value(speed);

    json_decref(root);
}

// Function to create a new record
Record* create_record(int key, long offset) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    new_record->key = key;
    new_record->offset = malloc(sizeof(long));
    if (!new_record->offset) {
        free(new_record);
        perror("Failed to allocate memory for offset");
        exit(EXIT_FAILURE);
    }
    *new_record->offset = offset;
    new_record->next = NULL;
    return new_record;
}

// Function to insert a record into the list
void insert_record(RecordList *list, Record *record) {
    pthread_mutex_lock(&list->lock);

    record->next = list->head;
    list->head = record;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

// Garbage collection function to remove unused records (example implementation)
void garbage_collect(RecordList *list, int threshold) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    Record *prev = NULL;

    while (current != NULL) {
        // Example condition for removing a record
        if (current->offset == NULL || current->key < threshold) {
            if (prev == NULL) { // Removing head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->offset);
            free(current);
            list->size--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup function to free all records
void cleanup(RecordList *list) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp->offset);
        free(temp);
    }
    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    int map_width, map_height, tile_size;
    float viewport_speed;

    load_config("config.json", &map_width, &map_height, &tile_size, &viewport_speed);

    RecordList list = { .head = NULL, .size = 0 };
    pthread_mutex_init(&list.lock, NULL);

    // Example usage
    insert_record(&list, create_record(1, 100));
    garbage_collect(&list, 50);
    cleanup(&list);

    return 0;
}
```

This code provides a basic structure for managing records using linked lists and includes thread safety, JSON configuration loading, and error handling. Adjust the logic in `garbage_collect` to fit your specific criteria for removing unused records.']

