#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define SESSION_ID_LEN 32
#define INITIAL_CAPACITY 16

typedef struct {
    char session_id[SESSION_ID_LEN];
    time_t expiration_time;
    char* permissions; // Permissions stored as a string for simplicity.
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// Helper function prototypes
Session* find_session_by_id(SessionManager* manager, const char* session_id);
void fetch_permissions(char** permissions);

// Public API functions
int create_or_update_session(SessionManager* manager, const char* session_id, time_t expiration_time);
int update_permissions(SessionManager* manager, const char* session_id, const char* new_permissions);
void terminate_expired_sessions(SessionManager* manager);
SessionManager* initialize_manager();
void destroy_manager(SessionManager* manager);

// Internal functions
static void expand_capacity_if_needed(SessionManager* manager);
static Session* create_session(const char* session_id, time_t expiration_time);
static int add_or_update_internal(SessionManager* manager, const char* session_id, time_t expiration_time);
static void remove_expired_sessions(SessionManager* manager);
static void perform_garbage_collection(SessionManager* manager);

// Implementation of public API functions
SessionManager* initialize_manager() {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->sessions = (Session*)calloc(INITIAL_CAPACITY, sizeof(Session));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    return manager;
}

void destroy_manager(SessionManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i].permissions);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int create_or_update_session(SessionManager* manager, const char* session_id, time_t expiration_time) {
    if (!manager || !session_id) return -1;

    pthread_mutex_lock(&manager->lock);

    Session* existing = find_session_by_id(manager, session_id);
    int result;
    if (existing) {
        existing->expiration_time = expiration_time;
        result = 0; // Updated
    } else {
        result = add_or_update_internal(manager, session_id, expiration_time);
    }

    pthread_mutex_unlock(&manager->lock);

    return result;
}

int update_permissions(SessionManager* manager, const char* session_id, const char* new_permissions) {
    if (!manager || !session_id || !new_permissions) return -1;

    pthread_mutex_lock(&manager->lock);

    Session* session = find_session_by_id(manager, session_id);
    int result = 0; // Success

    if (session) {
        free(session->permissions);
        fetch_permissions(&(session->permissions));
        strncpy(session->permissions, new_permissions, SESSION_ID_LEN - 1);
        session->permissions[SESSION_ID_LEN - 1] = '\0';
    } else {
        result = -1; // Session not found
    }

    pthread_mutex_unlock(&manager->lock);

    return result;
}

void terminate_expired_sessions(SessionManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    remove_expired_sessions(manager);
    perform_garbage_collection(manager);
    pthread_mutex_unlock(&manager->lock);
}

// Implementation of internal functions
static void expand_capacity_if_needed(SessionManager* manager) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Session* new_sessions = (Session*)realloc(manager->sessions, new_capacity * sizeof(Session));
        if (!new_sessions) return;

        memset(new_sessions + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(Session));
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
}

static Session* create_session(const char* session_id, time_t expiration_time) {
    Session* new_session = (Session*)malloc(sizeof(Session));
    if (!new_session) return NULL;

    strncpy(new_session->session_id, session_id, SESSION_ID_LEN - 1);
    new_session->session_id[SESSION_ID_LEN - 1] = '\0';
    new_session->expiration_time = expiration_time;
    fetch_permissions(&(new_session->permissions));

    return new_session;
}

static int add_or_update_internal(SessionManager* manager, const char* session_id, time_t expiration_time) {
    expand_capacity_if_needed(manager);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            manager->sessions[i].expiration_time = expiration_time;
            return 1; // Added
        }
    }

    Session* new_session = create_session(session_id, expiration_time);
    if (!new_session) return -1;

    manager->sessions[manager->count++] = *new_session;
    free(new_session);

    return 0;
}

static void remove_expired_sessions(SessionManager* manager) {
    time_t now = time(NULL);
    for (size_t i = 0; i < manager->count;) {
        if (manager->sessions[i].expiration_time <= now) {
            free(manager->sessions[i].permissions);
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(Session));
            --manager->count;
        } else {
            ++i;
        }
    }
}

static void perform_garbage_collection(SessionManager* manager) {
    // Example logic: Triggered based on certain conditions, e.g., every N operations.
}

static Session* find_session_by_id(SessionManager* manager, const char* session_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) {
            return &manager->sessions[i];
        }
    }
    return NULL;
}

// Example implementation of permissions fetcher
static void fetch_permissions(char** permissions) {
    // Simulate fetching from an external service.
    *permissions = strdup("read-write");
}
