// Helper function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // posix_memalign returns 0 on failure
    }
    return ptr;
}

// Check if pointer is correctly aligned
int is_aligned(void* ptr, size_t alignment) {
    return ((uintptr_t)ptr % alignment) == 0;
}

// Generate a unique identifier for initialization
void generate_unique_id(char *id_buffer, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < length - 1; ++i) {
        id_buffer[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    id_buffer[length - 1] = '\0';
}

// Simulate high latency
void simulate_latency(int milliseconds) {
    usleep(milliseconds * 1000);
}

