        return -1;
    }

    record_array = aligned_alloc(alignment, num_records * sizeof(Record));
    if (!record_array || !is_aligned(record_array, alignment)) {
        free(offset_array);
        free(key_array);
        fprintf(stderr, "Failed to allocate or align RecordArray.\n");
        return -1;
    }

