typedef struct {
    double value;
    char buffer[256];
} data_t;

typedef enum { INIT, RUNNING, COMPLETED } status_t;

typedef struct {
    time_t timestamp;
    status_t status;
} event_t;

typedef struct {
    int rows;
    int cols;
    int **data;
} matrix_t;

#define ALIGNMENT 32
#define DOUBLE_RANGE_MAX 100.0
#define BUFFER_STRING "predefined"
#define DEFAULT_STATUS INIT

// Alignment helper function
void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

// Fibonacci calculation with memoization
int fibonacci(int n, int **memo, pthread_mutex_t *lock) {
    if (n <= 1)
        return n;

    pthread_mutex_lock(lock);
    if (memo[n] != -1) {
        pthread_mutex_unlock(lock);
        return memo[n];
    }
    pthread_mutex_unlock(lock);

    int a = fibonacci(n - 1, memo, lock);
    int b = fibonacci(n - 2, memo, lock);

    pthread_mutex_lock(lock);
    memo[n] = a + b;
    pthread_mutex_unlock(lock);

    return memo[n];
}

// Initialize matrix with Fibonacci values
void init_fibonacci_matrix(matrix_t *matrix) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int **memo = aligned_malloc(matrix->rows * sizeof(int*), ALIGNMENT);
    for (int i = 0; i < matrix->rows; ++i) {
        memo[i] = aligned_malloc(matrix->cols * sizeof(int), ALIGNMENT);
        memset(memo[i], -1, matrix->cols * sizeof(int));
    }

    for (int i = 0; i < matrix->rows; ++i) {
        for (int j = 0; j < matrix->cols; ++j) {
            matrix->data[i][j] = fibonacci(j, memo + i, &lock);
        }
    }

    pthread_mutex_destroy(&lock);
    for (int i = 0; i < matrix->rows; ++i) {
        free(memo[i]);
    }
    free(memo);
}

// Function to initialize structures
void* init_structures(int num_nodes, int num_events, int rows, int cols) {
    // Allocate and align memory for node pointers array
    data_t **nodes = aligned_malloc(num_nodes * sizeof(data_t*), ALIGNMENT);
    if (!nodes) return NULL;

    // Initialize each node's data structure
    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = aligned_malloc(sizeof(data_t), ALIGNMENT);
        if (!nodes[i]) {
            for (int j = 0; j < i; ++j) free(nodes[j]);
            free(nodes);
            return NULL;
        }

        // Generate random double within specified range
        srand(time(NULL) + i);  // Seed with different value per iteration
        nodes[i]->value = ((double)rand() / RAND_MAX) * DOUBLE_RANGE_MAX;

        // Fill char buffer with repeated predefined string
        int repeat_count = 10;  // Example repeat count
        memset(nodes[i]->buffer, '\0', sizeof(nodes[i]->buffer));
        for (int j = 0; j < repeat_count && strlen(nodes[i]->buffer) + strlen(BUFFER_STRING) < sizeof(nodes[i]->buffer); ++j) {
            strcat(nodes[i]->buffer, BUFFER_STRING);
        }
    }

    // Allocate and initialize event structures
    event_t *events = aligned_malloc(num_events * sizeof(event_t), ALIGNMENT);
    if (!events) {
        for (int i = 0; i < num_nodes; ++i) free(nodes[i]);
        free(nodes);
        return NULL;
    }

    time_t current_time = time(NULL);
    for (int i = 0; i < num_events; ++i) {
        events[i].timestamp = current_time;
        events[i].status = DEFAULT_STATUS;
    }

    // Allocate and initialize matrix structure
    matrix_t *matrix = aligned_malloc(sizeof(matrix_t), ALIGNMENT);
    if (!matrix) {
        free(events);
        for (int i = 0; i < num_nodes; ++i) free(nodes[i]);
        free(nodes);
        return NULL;
    }

    matrix->rows = rows;
    matrix->cols = cols;

    // Allocate memory for matrix
    matrix->data = aligned_malloc(rows * sizeof(int*), ALIGNMENT);
    if (!matrix->data) {
        free(matrix);
        free(events);
        for (int i = 0; i < num_nodes; ++i) free(nodes[i]);
        free(nodes);
        return NULL;
    }

    for (int i = 0; i < rows; ++i) {
        matrix->data[i] = aligned_malloc(cols * sizeof(int), ALIGNMENT);
        if (!matrix->data[i]) {
            for (int j = 0; j < i; ++j) free(matrix->data[j]);
            free(matrix->data);
            free(matrix);
            free(events);
            for (int k = 0; k < num_nodes; ++k) free(nodes[k]);
            free(nodes);
            return NULL;
        }
    }

    // Populate the matrix with Fibonacci sequence values
    init_fibonacci_matrix(matrix);

    // Bundle everything into a struct to be returned
    typedef struct {
        data_t **nodes;
        event_t *events;
        matrix_t *matrix;
    } structures_t;

    structures_t *result = aligned_malloc(sizeof(structures_t), ALIGNMENT);
    if (!result) {
        for (int i = 0; i < rows; ++i) free(matrix->data[i]);
        free(matrix->data);
        free(matrix);
        free(events);
        for (int j = 0; j < num_nodes; ++j) free(nodes[j]);
        free(nodes);
        return NULL;
    }

    result->nodes = nodes;
    result->events = events;
    result->matrix = matrix;

    return result;
}
