#define ALIGNMENT 64

typedef struct {
    char *content;
    size_t size;
    char *metadata; // Optional metadata field
    atomic_int ref_count;
} data_block;

// Aligns a given pointer to the specified boundary
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

data_block* initialize_data_blocks(int num_blocks, size_t block_size, char start_char) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    data_block* blocks = aligned_alloc(ALIGNMENT, sizeof(data_block) * num_blocks);

    if (!blocks) {
        perror("Failed to allocate memory for data blocks");
        return NULL;
    }

    for (int i = 0; i < num_blocks; ++i) {
        blocks[i].content = aligned_alloc(ALIGNMENT, block_size);
        if (!blocks[i].content) {
            perror("Failed to allocate content buffer");
            // Free allocated resources before exiting
            while (--i >= 0) free(blocks[i].content);
            free(blocks);
            return NULL;
        }

        blocks[i].size = block_size;
        blocks[i].metadata = NULL; // Initialize metadata as needed
        atomic_init(&blocks[i].ref_count, 1); // Initialize reference count

        for (size_t j = 0; j < block_size; ++j) {
            blocks[i].content[j] = start_char + j % 256;
        }
    }

    return blocks;
}

int verify_data_blocks(data_block* blocks, int num_blocks) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_blocks; ++i) {
        if (!blocks[i].content || !atomic_load(&blocks[i].ref_count)) {
            return 0; // Verification failed
        }

        char expected_char = blocks[i].content[0];
        for (size_t j = 0; j < blocks[i].size; ++j) {
            if (blocks[i].content[j] != expected_char + j % 256) {
                return 0; // Content verification failed
            }
        }
    }

    return 1; // Verification successful
}

data_block* copy_data_block(const data_block* original, int alignment) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    data_block* new_block = aligned_alloc(alignment ? alignment : ALIGNMENT,
                                          sizeof(data_block));
    if (!new_block) {
        perror("Failed to allocate memory for copied block");
        return NULL;
    }

    new_block->content = aligned_alloc(ALIGNMENT, original->size);
    if (!new_block->content) {
        perror("Failed to allocate content buffer in copy");
        free(new_block); // Free allocated resources before exiting
        return NULL;
    }

    new_block->size = original->size;
    new_block->metadata = NULL; // Initialize metadata as needed
    atomic_store(&new_block->ref_count, 1);

    memcpy(new_block->content, original->content, original->size);

    return new_block;
}

void free_data_blocks(data_block* blocks, int num_blocks) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_blocks; ++i) {
        if (!atomic_fetch_sub(&blocks[i].ref_count, 1)) {
            free(blocks[i].content);
        }
    }

    free(blocks);
}
