// Structure definitions
typedef struct {
    size_t size;
    union {
        double f_value;
        char* s_value;
    };
} item;

typedef struct {
    int value;
    char identifier[20];
    item *data;
} record;

typedef struct {
    char string[50];
    unsigned int number;
} complex_struct;

#define MAX_MEMORY_USAGE 800 * 1024 // 800 KB
#define PREDEFINED_STRING "INITIALIZED"
#define RANDOM_RANGE_MAX 100

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_data(long **long_array, double *double_array, complex_struct *complex_array,
                     int *int_keys, record *records, size_t count) {
    size_t total_memory_usage = 0;
    pthread_mutex_lock(&mutex);

    // Memory allocation for long integer pointers
    for (size_t i = 0; i < count; ++i) {
        long_array[i] = (long*) malloc(sizeof(long));
        if (!long_array[i]) { handle_error(); }
    }

    // Memory allocation and initialization for double precision numbers
    total_memory_usage += count * sizeof(double);
    for (size_t i = 0; i < count; ++i) {
        double_array[i] = (rand() % RANDOM_RANGE_MAX + 1.0);
    }

    // Memory allocation and initialization for complex struct objects
    for (size_t i = 0; i < count; ++i) {
        strcpy(complex_array[i].string, PREDEFINED_STRING);
        complex_array[i].number = rand() % RANDOM_RANGE_MAX;
        total_memory_usage += sizeof(complex_struct);
    }

    // Memory allocation and initialization for int keys
    for (size_t i = 0; i < count; ++i) {
        int_keys[i] = rand();
    }

    // Memory allocation and initialization for records
    for (size_t i = 0; i < count; ++i) {
        records[i].value = i;
        time_t t = time(NULL);
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID_%lu_%zu", (unsigned long)t, i);

        // Allocate item structure
        records[i].data = (item*) malloc(sizeof(item));
        if (!records[i].data) { handle_error(); }

        total_memory_usage += sizeof(record) + strlen(records[i].identifier) * sizeof(char);
    }

    // Ensure memory usage does not exceed the limit
    manage_memory_usage(total_memory_usage, long_array, double_array, complex_array,
                        int_keys, records, count);

    pthread_mutex_unlock(&mutex);
}

void handle_error() {
    perror("Error in allocation");
    exit(EXIT_FAILURE);
}

void manage_memory_usage(size_t total_memory_usage, long **long_array, double *double_array, 
                         complex_struct *complex_array, int *int_keys, record *records, size_t count) {

    while (total_memory_usage > MAX_MEMORY_USAGE) {
        // Release memory from the least recently used records (simple example)
        for (size_t i = 0; i < count && total_memory_usage > MAX_MEMORY_USAGE; ++i) {
            if (records[i].data) {
                free(records[i].data);
                records[i].data = NULL;
                total_memory_usage -= sizeof(item);
                // Break after freeing one record to re-evaluate the memory usage
                break;
            }
        }
    }
}

void cleanup(long **long_array, size_t count_long, double *double_array, 
             complex_struct *complex_array, int *int_keys, record *records, size_t count_record) {
    pthread_mutex_lock(&mutex);

    // Free long integer pointers
    for (size_t i = 0; i < count_long; ++i) {
        free(long_array[i]);
    }

    // Double array cleanup
    free(double_array);

    // Complex struct array cleanup
    free(complex_array);

    // Int keys and record cleanup
    for (size_t i = 0; i < count_record; ++i) {
        if (records[i].data) {
            free(records[i].data);
        }
    }

    free(int_keys);
    free(records);

    pthread_mutex_unlock(&mutex);
}

