#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    char *content;
    size_t size;
    void *metadata;
} data_block;

typedef struct {
    data_block *blocks;
    size_t count;
    size_t alignment;
    pthread_mutex_t lock;
} data_manager;

#define ALIGNMENT_DEFAULT 64

size_t aligned_alloc(size_t alignment, size_t size) {
    if (alignment & (alignment - 1)) return NULL; // Ensure power of two
    void *ptr = malloc(size + alignment);
    if (!ptr) return NULL;

    uintptr_t addr = (uintptr_t)ptr;
    uintptr_t offset = (alignment - (addr % alignment)) % alignment;
    return (void *)(addr + offset);
}

data_manager* initialize_data_manager(size_t block_count, size_t alignment) {
    data_manager *manager = malloc(sizeof(data_manager));
    if (!manager) return NULL;

    manager->blocks = malloc(block_count * sizeof(data_block));
    if (!manager->blocks) {
        free(manager);
        return NULL;
    }

    manager->count = block_count;
    manager->alignment = alignment ? alignment : ALIGNMENT_DEFAULT;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int allocate_and_initialize_blocks(data_manager *manager, size_t sizes[], char start_char) {
    if (!manager || !sizes) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        data_block *block = &manager->blocks[i];

        block->size = sizes[i] > 0 ? sizes[i] : 0;
        if (!block->size) continue;

        block->content = aligned_alloc(manager->alignment, block->size);
        if (!block->content) {
            // Handle allocation failure: rollback
            for (size_t j = 0; j < i; ++j) {
                free(manager->blocks[j].content);
            }
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }

        char ch = start_char + i;
        for (size_t j = 0; j < block->size; ++j) {
            block->content[j] = ch++;
        }

        // Optional: set metadata
        block->metadata = NULL;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void verify_content_buffers(data_manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        data_block *block = &manager->blocks[i];

        char expected_char = 'A' + i;
        for (size_t j = 0; j < block->size; ++j) {
            if (block->content[j] != expected_char++) {
                printf("Content verification failed at block %zu, byte %zu\n", i, j);
                return;
            }
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_data_manager(data_manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->blocks[i].content);
    }

    free(manager->blocks);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Usage example
int main() {
    size_t sizes[] = {10, 20, 30};
    data_manager *dm = initialize_data_manager(3, ALIGNMENT_DEFAULT);

    if (allocate_and_initialize_blocks(dm, sizes, 'A') == 0) {
        verify_content_buffers(dm);
    } else {
        printf("Allocation failed\n");
    }

    free_data_manager(dm);
    return 0;
}
