#define MAX_RETRIES 5
#define LOG_FILE "memory_management.log"

typedef struct {
    int value;
} Record;

typedef struct {
    size_t num_records;
    Record *records;
} RecordArray;

typedef struct {
    size_t offset_size;
    char *offsets;
} OffsetArray;

