void generate_random_values(Record *records, int min_value, int max_value, unsigned int seed);

// Thread-safe logging function
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    printf("%s", message); // Also print to console
    pthread_mutex_unlock(&log_mutex);
}

// Free allocated resources
void free_resources(OffsetArray *offset_array, KeyArray *key_array, RecordArray *record_array) {
    if (offset_array->offsets != NULL) {
        free(offset_array->offsets);
    }
    if (key_array->keys != NULL) {
        free(key_array->keys);
    }
    if (record_array->records != NULL) {
        free(record_array->records);
    }
}

// Allocate and initialize a RecordArray
RecordArray allocate_record_array(size_t num_records, int min_value, int max_value) {
    RecordArray record_array;
    size_t alignment = 16;
    size_t record_size = sizeof(Record);
    size_t total_size = round_up_to_boundary(num_records * record_size, alignment);

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        void *aligned_ptr = aligned_alloc(alignment, total_size);
        if (aligned_ptr && validate_alignment(aligned_ptr, alignment)) {
            record_array.num_records = num_records;
            record_array.records = (Record *)aligned_ptr;

            // Generate random values
            unsigned int seed = time(NULL);  // Example: use current time as seed
            generate_random_values(record_array.records, min_value, max_value, seed);

            log_message("Successfully allocated and initialized RecordArray.");
            return record_array;
        } else {
            log_message("Failed to allocate aligned memory. Attempting retry...");
        }
    }

    log_message("Exceeded maximum retries for allocation.");
    record_array.num_records = 0;
    record_array.records = NULL;
    return record_array;
}

int validate_alignment(void *ptr, size_t alignment) {
    return ((uintptr_t)ptr % alignment == 0);
}

size_t round_up_to_boundary(size_t size, size_t boundary) {
    if (boundary == 0 || (size % boundary) == 0)
        return size;
    return size + boundary - (size % boundary);
}

void generate_random_values(Record *records, int min_value, int max_value, unsigned int seed) {
    srand(seed);
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

// Main function to demonstrate usage
