    int min_value = 0;
    int max_value = 100;

    // Example configuration parsing (simplified)
    if (argc > 1) max_records = atoi(argv[1]);
    if (argc > 2) min_value = atoi(argv[2]);
    if (argc > 3) max_value = atoi(argv[3]);

