    // Example usage of the allocated RecordArray
    for (size_t i = 0; i < record_array.num_records; ++i) {
        printf("Record %zu: Value = %d\n", i, record_array.records[i].value);
    }

    free_resources(NULL, NULL, &record_array);

    return 0;
}
