#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <string.h>
#include <time.h>

#define ALIGNMENT 16
#define DEFAULT_STATUS_CHAR 'A'

typedef struct {
    int value;
    double timestamp;
    char status;
} Record;

// Custom memory pool allocator
typedef struct {
    void *pool;
    size_t block_size;
    size_t num_blocks;
    size_t offset;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    if (block_size % ALIGNMENT != 0) {
        block_size += (ALIGNMENT - (block_size % ALIGNMENT));
    }
    size_t total_size = block_size * num_blocks;
    void *pool = aligned_alloc(ALIGNMENT, total_size);
    if (!pool) {
        fprintf(stderr, "Memory pool allocation failed\n");
        return NULL;
    }

    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) {
        free(pool);
        fprintf(stderr, "Memory pool structure allocation failed\n");
        return NULL;
    }

    mp->pool = pool;
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->offset = 0;

    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    if (mp->offset + mp->block_size > mp->num_blocks * mp->block_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        return NULL;
    }

    void *ptr = (char*)mp->pool + mp->offset;
    mp->offset += mp->block_size;

    return ptr;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        free(mp);
    }
}

// Function to dynamically allocate and initialize memory
int* init_data_structures(size_t num_offsets, size_t num_keys, size_t num_records) {
    MemoryPool *mp = create_memory_pool(sizeof(long), num_offsets + num_keys);
    if (!mp) return NULL;

    long *offsets = (long*)allocate_from_pool(mp);
    int *keys = (int*)allocate_from_pool(mp);

    if (!offsets || !keys) {
        destroy_memory_pool(mp);
        return NULL;
    }

    Record *records = aligned_alloc(ALIGNMENT, num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Records allocation failed\n");
        destroy_memory_pool(mp);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // Random number between 0 and 99
        records[i].timestamp = (double)(rand() % 100000);
        records[i].status = DEFAULT_STATUS_CHAR + (i % 26); // Default status based on index
    }

    // Verify integrity
    for (size_t i = 0; i < num_offsets; ++i) {
        if (((uintptr_t)&offsets[i] % ALIGNMENT) != 0) {
            fprintf(stderr, "Offset alignment failed\n");
            free(records);
            destroy_memory_pool(mp);
            return NULL;
        }
    }

    for (size_t i = 0; i < num_keys; ++i) {
        if (((uintptr_t)&keys[i] % ALIGNMENT) != 0) {
            fprintf(stderr, "Key alignment failed\n");
            free(records);
            destroy_memory_pool(mp);
            return NULL;
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        if (((uintptr_t)&records[i] % ALIGNMENT) != 0) {
            fprintf(stderr, "Record alignment failed\n");
            free(records);
            destroy_memory_pool(mp);
            return NULL;
        }
    }

    printf("Data structures initialized successfully.\n");

    // Returning keys array as an example; adjust based on actual use case
    destroy_memory_pool(mp);
    return keys;
}

int main() {
    size_t num_offsets = 10;
    size_t num_keys = 5;
    size_t num_records = 20;

    int *keys = init_data_structures(num_offsets, num_keys, num_records);
    if (keys) {
        printf("Keys initialized successfully.\n");
    } else {
        printf("Initialization failed.\n");
    }

    return 0;
}
