    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

int is_aligned(void *ptr, size_t alignment) {
    uintptr_t address = (uintptr_t)ptr;
    return (address % alignment) == 0;
}

void initialize_item(item *item, int key) {
    item->key = key;
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (int i = 0; i < ITEM_STRING_LENGTH; ++i) {
        item->string[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    item->string[ITEM_STRING_LENGTH] = '\0';
}

node* create_nodes(int node_count, int items_per_node) {
    pthread_mutex_lock(&lock);

    srand((unsigned int)time(NULL));

    // Allocate memory for nodes
    size_t node_size = sizeof(node) + (sizeof(item*) * (items_per_node - 1));
    node *nodes = aligned_alloc(sizeof(node), ALIGNMENT);
    if (!nodes || !is_aligned(nodes, ALIGNMENT)) {
        fprintf(stderr, "Failed to allocate or align memory for nodes.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate and initialize items for each node
    for (int i = 0; i < node_count; ++i) {
        double rand_value = sqrt((double)(rand() % 100 + 1));

        nodes[i].value = rand_value;

        item *items = aligned_alloc(sizeof(item) * items_per_node, ALIGNMENT);
        if (!items || !is_aligned(items, ALIGNMENT)) {
            fprintf(stderr, "Failed to allocate or align memory for items.\n");
            pthread_mutex_unlock(&lock);

            // Free previously allocated nodes
            free(nodes);
            return NULL;
        }

        nodes[i].items_head = items;
        for (int j = 0; j < items_per_node; ++j) {
            initialize_item(&items[j], i * items_per_node + j);
        }
    }

    pthread_mutex_unlock(&lock);

    // Verify integrity of allocations and data
    for (int i = 0; i < node_count; ++i) {
        if (!is_aligned((void*)&nodes[i].value, ALIGNMENT)) {
            fprintf(stderr, "Node value misalignment detected.\n");
            free(nodes);
            return NULL;
        }

        item *items = nodes[i].items_head;
        for (int j = 0; j < items_per_node; ++j) {
            if (!is_aligned((void*)&items[j], ALIGNMENT)) {
                fprintf(stderr, "Item misalignment detected.\n");
                free(nodes);
                return NULL;
            }

            // Verify item key uniqueness
            int unique_keys[items_per_node];
            memset(unique_keys, 0, sizeof(unique_keys));
            for (int k = 0; k < items_per_node; ++k) {
                if (unique_keys[items[k].key]++) {
                    fprintf(stderr, "Duplicate item key detected.\n");
                    free(nodes);
                    return NULL;
                }
            }
        }
    }

    return nodes;
}
