// Forward declaration for helper function
float generateRandomFloat(float min, float max, bool inclusiveMin, bool inclusiveMax);

class Range {
public:
    long offsetMin;
    long offsetMax;
    int keyMin;
    int keyMax;

    Range(long om, long ox, int km, int kx) : offsetMin(om), offsetMax(ox), keyMin(km), keyMax(kx) {}

    bool overlaps(const Range& other) const {
        return !(offsetMax < other.offsetMin || offsetMin > other.offsetMax ||
                 keyMax < other.keyMin || keyMin > other.keyMax);
    }

    void merge(Range& other) {
        offsetMin = std::min(offsetMin, other.offsetMin);
        offsetMax = std::max(offsetMax, other.offsetMax);
        keyMin = std::min(keyMin, other.keyMin);
        keyMax = std::max(keyMax, other.keyMax);
    }
};

class RangeManager {
private:
    std::vector<Range> ranges;
    mutable std::mutex mtx;

public:
    void addRange(const Range& range) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& r : ranges) {
            if (r.overlaps(range)) {
                r.merge(range);
                return;
            }
        }
        ranges.push_back(range);
        mergeOverlappingRanges();
    }

    void removeRange(const Range& range) {
        std::lock_guard<std::mutex> lock(mtx);
        ranges.erase(std::remove_if(ranges.begin(), ranges.end(),
                                    [&range](const Range& r) { return r.overlaps(range); }),
                     ranges.end());
    }

    void modifyRange(long offsetMin, long offsetMax, int keyMin, int keyMax) {
        std::lock_guard<std::mutex> lock(mtx);
        // Example modification: remove old and add new
        removeRange(Range(offsetMin, offsetMax, keyMin, keyMax));
        addRange(Range(offsetMin, offsetMax, keyMin, keyMax));
    }

    void mergeOverlappingRanges() {
        if (ranges.size() < 2) return;

        std::sort(ranges.begin(), ranges.end(),
                  [](const Range& a, const Range& b) {
                      return a.offsetMin < b.offsetMin || 
                             (a.offsetMin == b.offsetMin && a.keyMin < b.keyMin);
                  });

        for (size_t i = 1; i < ranges.size(); ++i) {
            if (ranges[i - 1].overlaps(ranges[i])) {
                ranges[i - 1].merge(ranges[i]);
                ranges.erase(ranges.begin() + i);
                --i;
            }
        }
    }

    int generateRandomInt(int min, int max, bool inclusiveMin = true, bool inclusiveMax = true) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min, max);

        return dis(gen);
    }

    float generateRandomFloat(float min, float max, bool inclusiveMin = true, bool inclusiveMax = true) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> dis(inclusiveMin ? min : min + 1e-9f,
                                                  inclusiveMax ? max : max - 1e-9f);

        return dis(gen);
    }

    void splitRange(const Range& range, const std::function<bool(const Range&)>& criteria) {
        std::lock_guard<std::mutex> lock(mtx);
        // Example: Split based on some criteria
        if (criteria(range)) {
            long midOffset = (range.offsetMin + range.offsetMax) / 2;
            int midKey = (range.keyMin + range.keyMax) / 2;

            addRange(Range(range.offsetMin, midOffset, range.keyMin, midKey));
            addRange(Range(midOffset + 1, range.offsetMax, midKey + 1, range.keyMax));
        }
    }

    void logCurrentState() const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& r : ranges) {
            std::cout << "Range: [" << r.offsetMin << ", " << r.offsetMax << "] "
                      << "[" << r.keyMin << ", " << r.keyMax << "]" << std::endl;
        }
    }

    // Example function to integrate with external configuration service
    void fetchAndApplyConfig() {
        // Placeholder for fetching and applying configurations dynamically
    }
};

int main() {
    RangeManager manager;

    manager.addRange(Range(0, 10, 0, 5));
    manager.addRange(Range(5, 15, 3, 8));

    manager.logCurrentState();

    manager.splitRange(manager.generateRandomInt(0, 10), [](const Range& r) {
        return (r.offsetMax - r.offsetMin) > 5;
    });

    manager.logCurrentState();

    std::cout << "Random Int: " << manager.generateRandomInt(1, 100) << std::endl;
    std::cout << "Random Float: " << manager.generateRandomFloat(0.0f, 10.0f) << std::endl;

    return 0;
}
```

