                println!("Test {} failed.", label);
            } else {
                println!("Test {} passed.", label);
            }
        })
    }, max_concurrent_tests)
}

fn run_tests<F>(f: F, max_concurrent_tests: usize) where F: Fn(&str, Box<dyn FnOnce() + Send>) + Sync + Send + 'static {
    let mut test_queue = VecDeque::new();

    // Example tests
    test_queue.push_back(("Test 1", Box::new(|| {
        println!("Executing Test 1");
    })));
    test_queue.push_back(("Test 2", Box::new(|| {
        println!("Executing Test 2");
    })));

    let active_tests = Arc::new(Mutex::new(0));

    while !test_queue.is_empty() {
        let (label, test_fn) = test_queue.pop_front().unwrap();

        if *active_tests.lock().unwrap() < max_concurrent_tests {
            *active_tests.lock().unwrap_mut() += 1;
            f(label, test_fn);

            // Simulate the end of a test
            thread::spawn(move || {
                std::thread::sleep(Duration::from_secs(2));
                let mut active = active_tests.lock().unwrap();
                *active -= 1;
            });
        } else {
            // Re-queue if max concurrency reached
            test_queue.push_back((label, test_fn));
        }
    }

    // Wait for all tests to finish (simplified)
    while *active_tests.lock().unwrap() > 0 {
        thread::sleep(Duration::from_millis(100));
    }
}

