    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = aligned_alloc(64, OFFSET_COUNT * sizeof(long));
    if (!offsets) HANDLE_ERROR("Failed to allocate memory for offsets");

    int *keys = aligned_alloc(64, KEY_COUNT * sizeof(int));
    if (!keys) { free(offsets); HANDLE_ERROR("Failed to allocate memory for keys"); }

    record *records = malloc(INITIAL_RECORDS * sizeof(record));
    if (!records) { free(offsets); free(keys); HANDLE_ERROR("Failed to allocate memory for records"); }

    initialize_random(seed);

    // Initialize offsets and keys
    memset(offsets, 0, OFFSET_COUNT * sizeof(long));
    memset(keys, 0, KEY_COUNT * sizeof(int));

    // Initialize records with random values within a range
    int min_value = 1;
    int max_value = 100;

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < INITIAL_RECORDS; ++i) {
        records[i].value = random_in_range(min_value, max_value);
    }
    pthread_mutex_unlock(&mutex);

    log_message("Memory allocation and initialization successful");

    // Function to resize the record array
    int resize_records(record **records_ptr, size_t current_size, size_t new_size) {
        pthread_mutex_lock(&mutex);
        record *new_records = realloc(*records_ptr, new_size * sizeof(record));
        if (!new_records) { 
            log_message("Failed to reallocate memory for records");
            return -1; 
        }

        // Initialize new elements
        memset(new_records + current_size, 0, (new_size - current_size) * sizeof(record));

        pthread_mutex_unlock(&mutex);

        *records_ptr = new_records;
        return 0;
    }

    // Example of resizing logic
    if (resize_records(&records, INITIAL_RECORDS, MAX_RECORDS)) {
        free(offsets);
        free(keys);
        free(records);
        HANDLE_ERROR("Record array resizing failed");
    }

    log_message("Record array resized successfully");

    // Serialization function (example: simple binary serialization)
    void serialize_record(record *rec, FILE *file) {
        fwrite(rec, sizeof(record), 1, file);
    }

    // Deserialization function
    record deserialize_record(FILE *file) {
        record rec;
        fread(&rec, sizeof(record), 1, file);
        return rec;
    }

    // Cleanup resources
    free(offsets);
    free(keys);

    pthread_mutex_destroy(&mutex);

    // Example of freeing records properly
    if (records) {
        free(records);
        log_message("Memory freed successfully");
    }

    return 0;
}

int main() {
    manage_memory_allocation(42); // Seed for reproducibility
    return 0;
}
