['Below is a C implementation that manages a collection of records using a doubly linked list with thread-safe operations. The code uses mutexes for synchronization and handles memory management efficiently.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    long *ptr_long;
    int *ptr_int;
    int ref_count;
    struct Record *prev;
    struct Record *next;
} Record;

typedef struct List {
    Record *head;
    Record *tail;
    pthread_mutex_t lock;
} List;

List *init_list(size_t initial_size, int min_value, int max_value) {
    if (initial_size <= 0 || min_value > max_value) return NULL;

    List *list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        add_record(list, rand() % (max_value - min_value + 1) + min_value);
    }

    return list;
}

Record *find_or_create_record(List *list, int value) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current != NULL) {
        if (current->value == value) {
            current->ref_count++;
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    new_record->value = value;
    new_record->ptr_long = malloc(sizeof(long));
    new_record->ptr_int = malloc(sizeof(int));
    new_record->ref_count = 1;
    new_record->prev = list->tail;
    new_record->next = NULL;

    if (list->tail) {
        list->tail->next = new_record;
    } else {
        list->head = new_record;
    }
    list->tail = new_record;

    pthread_mutex_unlock(&list->lock);
    return new_record;
}

int add_record(List *list, int value) {
    Record *record = find_or_create_record(list, value);
    if (!record) return -1; // Memory allocation failure

    // Initialize pointers with random values for demonstration
    *(record->ptr_long) = rand();
    *(record->ptr_int) = rand();

    return 0;
}

int remove_record(List *list, int value) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current != NULL) {
        if (current->value == value) {
            current->ref_count--;
            if (current->ref_count > 0) {
                pthread_mutex_unlock(&list->lock);
                return 0; // Still in use
            }

            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }

            free(current->ptr_long);
            free(current->ptr_int);
            free(current);

            pthread_mutex_unlock(&list->lock);
            return 0; // Removed
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void print_records(List *list) {
    pthread_mutex_lock(&list->lock);

    Record *current = list->head;
    while (current != NULL) {
        printf("Value: %d, Ref Count: %d\n", current->value, current->ref_count);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(List **list) {
    if (!list || !*list) return;

    pthread_mutex_lock(&(*list)->lock);

    Record *current = (*list)->head;
    while (current != NULL) {
        Record *to_delete = current;
        current = current->next;

        free(to_delete->ptr_long);
        free(to_delete->ptr_int);
        free(to_delete);
    }

    pthread_mutex_unlock(&(*list)->lock);
    pthread_mutex_destroy(&(*list)->lock);
    free(*list);
    *list = NULL;
}

int main() {
    List *record_list = init_list(10, 1, 100);

    if (!record_list) {
        fprintf(stderr, "Failed to initialize list\n");
        return EXIT_FAILURE;
    }

    add_record(record_list, 42);
    print_records(record_list);

    remove_record(record_list, 42);
    print_records(record_list);

    destroy_list(&record_list);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to protect the list during modifications.
- **Memory Management**: Each record's memory is managed with reference counting.
- **Initialization and Cleanup**: Functions for initializing, destroying, adding, removing, and printing records are provided.
- **Error Handling**: Checks for memory allocation failures are included.']

