#[derive(Debug)]
struct Task {
    priority: u8,
    status: String,
    resource_allocation: u32,
    milestone: String,
    dependencies: LinkedList<Dependency>,
}

impl Task {
    fn new(priority: u8, resource_allocation: u32, milestone: &str) -> Self {
        Task {
            priority,
            status: "pending".to_string(),
            resource_allocation,
            milestone: milestone.to_string(),
            dependencies: LinkedList::new(),
        }
    }

    fn update_status(&mut self, completion_time: Duration, resources: u32) {
        // Example state machine logic
        match (self.priority, completion_time.as_secs(), resources) {
            (_, t, r) if t > 3600 && r < 50 => self.status = "in-progress".to_string(),
            (_, _, _) if self.dependencies.is_empty() => self.status = "completed".to_string(),
            _ => (),
        }
    }

    fn add_dependency(&mut self, dependency: Dependency) {
        self.dependencies.push_back(dependency);
    }
}

#[derive(Debug)]
struct Dependency {
    task_id: u32,
    weight: f64,
    due_date: Duration,
}

impl Dependency {
    fn new(task_id: u32, completion_time: Duration) -> Self {
        let weight = thread_rng().gen_range(0.1..1.0);
        // Example calculation for due date
        let due_date = completion_time + Duration::from_secs((weight * 1000.0) as u64);

        Dependency { task_id, weight, due_date }
    }
}

fn initialize_project_structure() -> Vec<Task> {
    let mut tasks = vec![];
    for i in 0..10 {
        let priority = i % 5;
        let resource_allocation = (i * 10) as u32;
        let milestone = format!("Milestone {}", i + 1);
        let mut task = Task::new(priority, resource_allocation, &milestone);

        for j in 0..3 {
            let completion_time = Duration::from_secs(j as u64 * 1000);
            let dependency = Dependency::new(i * 10 + j, completion_time);
            task.add_dependency(dependency);
        }

        // Example logic to update status
        task.update_status(Duration::from_secs(7200), task.resource_allocation);

        tasks.push(task);
    }
    tasks
}

