```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const stream = require('stream');
const events = require('events');

class DataStreamer extends events.EventEmitter {
  constructor(baseDir = process.cwd(), bufferSize = 1024 * 1024) {
    super();
    this.baseDir = baseDir;
    this.bufferSize = bufferSize;
    this.internalBuffer = new stream.PassThrough();
    this.isPaused = false;
    this.dataQueue = [];
    this.currentStream = null;
    this.diskStoragePath = path.join(this.baseDir, 'data_storage');
    if (!fs.existsSync(this.diskStoragePath)) {
      fs.mkdirSync(this.diskStoragePath, { recursive: true });
    }
  }

  resolveFilePath(filePath) {
    return path.resolve(this.baseDir, filePath);
  }

  async streamData(filePath, options = {}) {
    const resolvedPath = this.resolveFilePath(filePath);

    if (options.useDisk && !this.isPaused) {
      const fileName = `${Date.now()}.data`;
      const diskFilePath = path.join(this.diskStoragePath, fileName);

      return new Promise((resolve, reject) => {
        fs.createReadStream(resolvedPath)
          .on('error', reject)
          .pipe(fs.createWriteStream(diskFilePath))
          .on('finish', () => resolve(diskFilePath));
      });
    }

    if (this.isPaused || this.currentStream) return;

    const readStream = fs.createReadStream(resolvedPath, {
      highWaterMark: this.bufferSize,
      autoClose: true
    });

    this.currentStream = readStream;

    readStream.on('data', chunk => {
      if (!this.isPaused && this.internalBuffer.write(chunk) === false) {
        this.emit('backpressure');
      }
    }).on('end', () => {
      this.internalBuffer.end();
      this.currentStream = null;
      this.emit('end');
    }).on('error', err => {
      this.emit('error', err);
    });

    return new Promise((resolve, reject) => {
      readStream.on('open', resolve).on('error', reject);
    });
  }

  pause() {
    if (!this.isPaused) {
      this.isPaused = true;
      this.internalBuffer.pause();
      if (this.currentStream) {
        this.currentStream.pause();
      }
    }
  }

  resume() {
    if (this.isPaused) {
      this.isPaused = false;
      this.internalBuffer.resume();
      if (this.currentStream) {
        this.currentStream.resume();
      }
    }
  }

  getBuffer() {
    return this.internalBuffer;
  }
}

// Example usage:
const streamer = new DataStreamer('/base/directory');

streamer.on('error', err => console.error(err));
streamer.streamData('largefile.txt').then(() => {
  console.log('Streaming completed.');
}).catch(err => {
  console.error('Error during streaming:', err);
});

streamer.pause();
// Do other operations or wait
setTimeout(() => streamer.resume(), 5000);

```

