#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants
#define MEMORY_LIMIT 1024 * 1024 * 100 // 100 MB limit
#define ALIGNMENT 16
#define KEY_COUNT 10
#define RECORD_SIZE sizeof(record_t)
#define BUFFER_SIZE 4096

typedef struct {
    int value;
} record_t;

typedef struct {
    pthread_mutex_t lock;
    long *offsets;
    int *keys;
    record_t **records;
    size_t used_memory;
    char string[256];
    unsigned int random_value;
} data_struct_t;

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

unsigned int generate_random(unsigned int min, unsigned int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_data_struct(data_struct_t *ds) {
    pthread_mutex_init(&ds->lock, NULL);
    ds->offsets = aligned_alloc(ALIGNMENT, sizeof(long) * KEY_COUNT);
    ds->keys = malloc(sizeof(int) * KEY_COUNT);
    ds->records = malloc(sizeof(record_t*) * KEY_COUNT);
    ds->used_memory = 0;

    if (!ds->offsets || !ds->keys || !ds->records) {
        // Handle memory allocation failure
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < KEY_COUNT; ++i) {
        ds->offsets[i] = i * RECORD_SIZE;
        ds->keys[i] = i;
        ds->records[i] = malloc(RECORD_SIZE);

        if (!ds->records[i]) {
            // Handle memory allocation failure
            while (i-- > 0) free(ds->records[i]);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            pthread_mutex_destroy(&ds->lock);
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        ds->used_memory += RECORD_SIZE;
        if (ds->used_memory > MEMORY_LIMIT) {
            // Release least recently used records
            while (ds->used_memory > MEMORY_LIMIT && i >= 0) {
                free(ds->records[i]);
                --i;
                ds->used_memory -= RECORD_SIZE;
            }
        }

        ds->string[0] = 'A'; // Initialize char string with a constant value
        ds->random_value = generate_random(1, 100); // Random unsigned int within range

        ds->records[i]->value = i; // Initialize record structure
    }
}

void free_data_struct(data_struct_t *ds) {
    for (int i = 0; i < KEY_COUNT; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]);
        }
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
}

