#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdalign.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define ALIGNMENT 32

typedef struct {
    char buffer[128];
    double value;
} CustomObject;

typedef struct {
    CustomObject *objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

int align_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

CustomObject* allocate_aligned(size_t num_elements, size_t element_size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    if (!(_aligned_malloc((num_elements * element_size), alignment))) {
        return NULL;
    }
#else
    if (posix_memalign(&ptr, alignment, num_elements * element_size)) {
        return NULL;
    }
#endif
    return ptr ? ((CustomObject*)ptr) : NULL;
}

void free_aligned(CustomObject* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int resize_list(DynamicList *list, size_t new_capacity) {
    if (new_capacity > MAX_LIST_SIZE) {
        fprintf(stderr, "Warning: Attempt to exceed maximum list capacity.\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    CustomObject* new_objects = allocate_aligned(new_capacity, sizeof(CustomObject), ALIGNMENT);
    if (!new_objects) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    memcpy(new_objects, list->objects, list->count * sizeof(CustomObject));
    free_aligned(list->objects);

    list->objects = new_objects;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int add_to_list(DynamicList *list, CustomObject obj) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 16 : list->capacity * 2;
        if (resize_list(list, new_capacity)) {
            return -1; // Resize failed
        }
    }

    pthread_mutex_lock(&list->lock);
    memcpy(&list->objects[list->count], &obj, sizeof(CustomObject));
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

int validate_list(DynamicList *list) {
    if (!list || !list->objects) {
        fprintf(stderr, "Error: Invalid list.\n");
        return -1;
    }

    for (size_t i = 0; i < list->count; ++i) {
        CustomObject *obj = &list->objects[i];
        if (alignof(obj->buffer) != ALIGNMENT || alignof(obj->value) != ALIGNMENT) {
            fprintf(stderr, "Error: Alignment mismatch.\n");
            return -1;
        }
    }

    return 0; // Validation successful
}

void initialize_list(DynamicList *list) {
    list->objects = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(DynamicList *list) {
    free_aligned(list->objects);
    pthread_mutex_destroy(&list->lock);
}
