typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    uint16_t vlan_tag; // 12 bits for priority, 12 bits for VID
    uint8_t vlan_priority;
    int ip_checksum_required;
} NICB;

// Function to generate a random VLAN tag with user-defined priority
uint16_t generate_vlan_tag(uint8_t priority) {
    if (priority > 15)
        return 0; // Invalid priority, returning default tag

    srand(time(NULL));
    uint16_t vlan_vid = rand() % 4096; // Random VID between 0 and 4095
    return ((priority & 0x0F) << 13) | (vlan_vid & 0x1FFF);
}

// Function to initialize and populate an array of NICB structures
int initialize_nicbs(NICB *nicb_array, size_t num_nicbs, uint8_t vlan_priority, int ip_checksum_required) {
    if (!nicb_array || num_nicbs == 0 || num_nicbs > MAX_NICBS)
        return -1; // Invalid input parameters

    for (size_t i = 0; i < num_nicbs; ++i) {
        // Initialize MAC addresses with random values
        for (int j = 0; j < 6; ++j) {
            nicb_array[i].mac_header.dest_mac[j] = rand() % 256;
            nicb_array[i].mac_header.src_mac[j] = rand() % 256;
        }

        // Set VLAN tag with the specified priority
        nicb_array[i].vlan_tag = generate_vlan_tag(vlan_priority);

        // Store configuration settings
        nicb_array[i].vlan_priority = vlan_priority;
        nicb_array[i].ip_checksum_required = ip_checksum_required;

