#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define ALIGNMENT 1024

typedef enum {
    ONLINE,
    OFFLINE,
    DEGRADED
} DeviceStatus;

typedef enum {
    ERROR,
    WARNING,
    INFO
} EventType;

typedef struct EventNode {
    EventType type;
    time_t timestamp;
    int severity_level;
    struct EventNode* next;
} EventNode;

typedef struct {
    char* location;
    int maintenance_window; // 0 or 1 for false/true
    DeviceStatus status;
    float performance_metric;
    EventNode* events;
} DeviceNode;

typedef struct {
    DeviceNode* devices;
} NetworkNode;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#ifdef _WIN32
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned(void* ptr) {
#ifdef _WIN32
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

DeviceStatus determine_status(float performance_metric, time_t last_online_time, int maintenance_window) {
    // Simple state machine logic for demonstration purposes.
    if (maintenance_window) return DEGRADED;
    if (performance_metric > 0.8) return ONLINE;
    if (performance_metric < 0.2) return OFFLINE;
    return DEGRADED;
}

int main() {
    NetworkNode* network_node = aligned_alloc(ALIGNMENT, sizeof(NetworkNode));
    if (!network_node) {
        fprintf(stderr, "Memory allocation failed for NetworkNode\n");
        return EXIT_FAILURE;
    }
    memset(network_node, 0, sizeof(NetworkNode));

    size_t num_devices = 5; // Example number of devices
    network_node->devices = aligned_alloc(ALIGNMENT, num_devices * sizeof(DeviceNode));
    if (!network_node->devices) {
        fprintf(stderr, "Memory allocation failed for DeviceNodes\n");
        free_aligned(network_node);
        return EXIT_FAILURE;
    }
    memset(network_node->devices, 0, num_devices * sizeof(DeviceNode));

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_devices; ++i) {
        network_node->devices[i].location = aligned_alloc(ALIGNMENT, 100);
        if (!network_node->devices[i].location) {
            fprintf(stderr, "Memory allocation failed for Device location\n");
            continue;
        }
        snprintf(network_node->devices[i].location, 100, "Location_%zu", i);

        network_node->devices[i].maintenance_window = rand() % 2; // Random maintenance window
        network_node->devices[i].performance_metric = ((float)rand() / RAND_MAX);
        time_t last_online_time = time(NULL); // Placeholder for actual last online time

        network_node->devices[i].status = determine_status(
            network_node->devices[i].performance_metric,
            last_online_time,
            network_node->devices[i].maintenance_window
        );

        size_t num_events = rand() % 10 + 1; // Random number of events per device
        network_node->devices[i].events = aligned_alloc(ALIGNMENT, num_events * sizeof(EventNode));
        if (!network_node->devices[i].events) {
            fprintf(stderr, "Memory allocation failed for EventNodes\n");
            free_aligned(network_node->devices[i].location);
            continue;
        }
        memset(network_node->devices[i].events, 0, num_events * sizeof(EventNode));

        for (size_t j = 0; j < num_events; ++j) {
            network_node->devices[i].events[j].type = (EventType)(rand() % 3);
            network_node->devices[i].events[j].timestamp = time(NULL) - rand() % 100000;
            network_node->devices[i].events[j].severity_level =
                (int)(network_node->devices[i].performance_metric * 10.0);

            // Link events
            if (j > 0) {
                network_node->devices[i].events[j-1].next = &network_node->devices[i].events[j];
            }
        }

        // Terminate the event list
        network_node->devices[i].events[num_events - 1].next = NULL;
    }

    printf("NetworkNode initialization completed successfully.\n");

    // Cleanup (example, normally you'd have a more complex cleanup process)
    for (size_t i = 0; i < num_devices; ++i) {
        free_aligned(network_node->devices[i].location);
        free_aligned(network_node->devices[i].events);
    }
    free_aligned(network_node->devices);
    free_aligned(network_node);

    return EXIT_SUCCESS;
}
