#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define task status enumeration
typedef enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
} TaskStatus;

// Define a dependency node
typedef struct DependencyNode {
    int task_id;
    float weight;
    struct DependencyNode *next;
} DependencyNode;

// Define a task node
typedef struct TaskNode {
    int priority;
    TaskStatus status;
    DependencyNode *dependencies;
    struct TaskNode *next;
} TaskNode;

// Define a project node
typedef struct ProjectNode {
    TaskNode *tasks;
    struct ProjectNode *next;
} ProjectNode;

// Mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to align memory to 256-byte boundaries
void* aligned_alloc(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, 256, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Function to free a task's dependencies list
void free_dependencies(DependencyNode *deps) {
    while (deps) {
        DependencyNode *temp = deps;
        deps = deps->next;
        free(temp);
    }
}

// Function to free a project's tasks list
void free_tasks(TaskNode *tasks) {
    while (tasks) {
        TaskNode *temp = tasks;
        free_dependencies(temp->dependencies);
        tasks = tasks->next;
        free(temp);
    }
}

// Function to initialize a new task node
TaskNode* create_task(int priority, TaskStatus status) {
    TaskNode *task = aligned_alloc(sizeof(TaskNode));
    if (!task) return NULL;

    task->priority = priority;
    task->status = status;
    task->dependencies = NULL;
    task->next = NULL;

    return task;
}

// Function to initialize a new dependency node
DependencyNode* create_dependency(int task_id, float weight) {
    DependencyNode *dependency = aligned_alloc(sizeof(DependencyNode));
    if (!dependency) return NULL;

    dependency->task_id = task_id;
    dependency->weight = weight;
    dependency->next = NULL;

    return dependency;
}

// Function to add a dependency to a task
void add_dependency(TaskNode *task, int task_id, float weight) {
    pthread_mutex_lock(&lock);

    DependencyNode *new_dep = create_dependency(task_id, weight);
    if (!new_dep) {
        printf("Memory allocation failed for dependency.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_dep->next = task->dependencies;
    task->dependencies = new_dep;

    pthread_mutex_unlock(&lock);
}

// Function to initialize a new project node
ProjectNode* create_project() {
    ProjectNode *project = aligned_alloc(sizeof(ProjectNode));
    if (!project) return NULL;

    project->tasks = NULL;
    project->next = NULL;

    return project;
}

// Function to add a task to a project
void add_task(ProjectNode *project, TaskNode *task) {
    pthread_mutex_lock(&lock);

    task->next = project->tasks;
    project->tasks = task;

    pthread_mutex_unlock(&lock);
}

// Test framework function
void run_test(const char *label, void (*f)(void)) {
    printf("Running test: %s\n", label);

    // Reset mocking library (simulated)
    printf("Resetting mock library 'projectkit'.\n");

    f(); // Run the test function

    printf("Test '%s' completed.\n", label);
}

// Example test functions
void test_create_project_and_task() {
    ProjectNode *project = create_project();
    if (!project) {
        printf("Failed to create project.\n");
        return;
    }

    TaskNode *task = create_task(1, PENDING);
    if (!task) {
        printf("Failed to create task.\n");
        free_tasks(project->tasks);
        free(project);
        return;
    }

    add_task(project, task);

    printf("Project and task created successfully.\n");

    free_tasks(project->tasks);
    free(project);
}

void test_add_dependency() {
    ProjectNode *project = create_project();
    if (!project) {
        printf("Failed to create project.\n");
        return;
    }

    TaskNode *task = create_task(2, IN_PROGRESS);
    if (!task) {
        printf("Failed to create task.\n");
        free_tasks(project->tasks);
        free(project);
        return;
    }

    add_task(project, task);

    add_dependency(task, 1, 0.5f);

    printf("Dependency added successfully.\n");

    free_tasks(project->tasks);
    free(project);
}

int main() {
    run_test("Create Project and Task", test_create_project_and_task);
    run_test("Add Dependency", test_add_dependency);

    return 0;
}
```

This code provides a simplified project management system with task dependencies, ensuring thread safety and memory alignment. The test framework runs tests sequentially, logging progress and results to the console.']

