            free(records[i]);
            return NULL;
        }

        records[i]->item_ptr->size = sizeof(double);
        records[i]->item_ptr->data.cPtr = strdup("Dynamic String");
    }

    size_t totalMemoryUsage = 0;
    for (size_t i = 0; i < numElements; ++i) {
        totalMemoryUsage += sizeof(long *);
        totalMemoryUsage += sizeof(double);
        totalMemoryUsage += sizeof(struct { char str[50]; unsigned int uiValue; });
        totalMemoryUsage += sizeof(int);
        totalMemoryUsage += sizeof(Record *);
    }

    pthread_mutex_lock(&mutex);
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        // Free least recently used records
        for (size_t i = 0; i < numElements && totalMemoryUsage > MAX_MEMORY_USAGE; ++i) {
            free(records[i]->item_ptr->data.cPtr);
            free(records[i]->item_ptr);
            free(records[i]);
            totalMemoryUsage -= sizeof(Record *);
        }
