        return NULL;
    }

    (*env)->CallStaticVoidMethod(env, cls, mid);

    // Clean up
    free_memory(longArray, doubleArray, structArray, intKeys, records, numElements);
    (*jvm)->DestroyJavaVM(jvm);

    return NULL;
}

