#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <stdint.h>

#define MAX_NODES 10
#define MAX_ITEMS_PER_NODE 5
#define ITEM_STRING_LENGTH 8
#define MEMORY_ALIGNMENT 64
#define DOUBLE_PRECISION 0.001

typedef struct Item {
    int key;
    char string[ITEM_STRING_LENGTH + 1];
    union {
        struct Item *next_item;
        short value;
    } metadata;
} Item;

typedef struct Node {
    double value;
    Item *items[MAX_ITEMS_PER_NODE];
    int num_items;
    int *dynamic_array;
    size_t array_size;
} Node;

// Simple hash table for item keys
#define HASH_TABLE_SIZE 100

typedef struct HashTableEntry {
    int key;
    struct HashTableEntry *next;
} HashTableEntry;

HashTableEntry *hash_table[HASH_TABLE_SIZE];

unsigned int hash(int key) {
    return key % HASH_TABLE_SIZE;
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i)
        hash_table[i] = NULL;
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashTableEntry *entry = hash_table[i];
        while (entry) {
            HashTableEntry *to_free = entry;
            entry = entry->next;
            free(to_free);
        }
    }
}

int add_to_hash_table(int key) {
    unsigned int index = hash(key);
    HashTableEntry *entry = hash_table[index];

    while (entry) {
        if (entry->key == key)
            return 0; // Key already exists
        entry = entry->next;
    }

    entry = malloc(sizeof(HashTableEntry));
    if (!entry) return -1;

    entry->key = key;
    entry->next = hash_table[index];
    hash_table[index] = entry;
    return 1;
}

void free_item(Item *item) {
    if (item->metadata.next_item)
        free(item->metadata.next_item);
    free(item);
}

Node **create_nodes(size_t num_nodes, int range_min, int range_max) {
    Node **nodes = aligned_alloc(MEMORY_ALIGNMENT, sizeof(Node *) * num_nodes);

    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i] = malloc(sizeof(Node));
        if (!nodes[i]) continue;

        // Initialize node value
        int rand_int = range_min + rand() % (range_max - range_min + 1);
        nodes[i]->value = round(sqrt(rand_int) / DOUBLE_PRECISION) * DOUBLE_PRECISION;

        for (int j = 0; j < MAX_ITEMS_PER_NODE; ++j) {
            if (add_to_hash_table(j)) { // Ensure unique key
                Item *item = malloc(sizeof(Item));
                if (!item) continue;

                item->key = j;
                srand(time(NULL) + rand()); // Seed for randomness

                // Generate random alphanumeric string
                const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
                for (int k = 0; k < ITEM_STRING_LENGTH; ++k)
                    item->string[k] = charset[rand() % (sizeof(charset) - 1)];
                item->string[ITEM_STRING_LENGTH] = '\0';

                // Populate metadata based on probability
                if ((rand() % 100) < 50) { // Example: 50% chance for each case
                    item->metadata.value = rand() % 100;
                } else {
                    Item *next_item = malloc(sizeof(Item));
                    next_item->key = j + 1; // Sample linked structure
                    item->metadata.next_item = next_item;
                }

                nodes[i]->items[j] = item;
                nodes[i]->num_items++;
            }
        }
    }

    return nodes;
}

void free_nodes(Node **nodes, size_t num_nodes) {
    for (size_t i = 0; i < num_nodes; ++i) {
        Node *node = nodes[i];
        if (!node) continue;

        for (int j = 0; j < MAX_ITEMS_PER_NODE; ++j) {
            if (node->items[j]) free_item(node->items[j]);
        }

        free(node);
    }
    free(nodes);
}

int main() {
    srand(time(NULL));
    init_hash_table();

    Node **nodes = create_nodes(MAX_NODES, 1, 100);

    // Example logging of node data
    for (size_t i = 0; i < MAX_NODES; ++i) {
        if (!nodes[i]) continue;
        printf("Node %zu: Value = %.3f\n", i, nodes[i]->value);
        for (int j = 0; j < nodes[i]->num_items; ++j) {
            Item *item = nodes[i]->items[j];
            if (!item) continue;

            printf("  Item %d: Key = %d, String = '%s'\n", item->key,
                   item->key, item->string);
        }
    }

    free_nodes(nodes, MAX_NODES);
    free_hash_table();

    return 0;
}
