['```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DataStructureManager {

    private static final Logger logger = Logger.getLogger(DataStructureManager.class.getName());
    private static final int ALIGNMENT = 32;
    private Node[] nodeArray;
    private int size;
    private int capacity;
    private UnionFind unionFind;
    private ConcurrentHashMap<Integer, Boolean> itemKeyMap;

    public DataStructureManager(int initialCapacity) {
        this.capacity = calculateAlignedSize(initialCapacity);
        this.size = 0;
        this.nodeArray = new Node[capacity];
        this.unionFind = new UnionFind();
        this.itemKeyMap = new ConcurrentHashMap<>();
    }

    private int calculateAlignedSize(int size) {
        return ((size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    }

    public synchronized void resizeIfNeeded() {
        if (size >= capacity * 0.75) {
            int newCapacity = calculateAlignedSize(capacity * 2);
            Node[] newArray = new Node[newCapacity];
            System.arraycopy(nodeArray, 0, newArray, 0, size);
            nodeArray = newArray;
            capacity = newCapacity;
        }
    }

    public synchronized void addNode(double value) {
        try {
            resizeIfNeeded();
            Node newNode = new Node(value);
            int index = size++;
            nodeArray[index] = newNode;
            logger.log(Level.INFO, "Node added at index {0}", index);
        } catch (OutOfMemoryError e) {
            handleMemoryError(e);
        }
    }

    public synchronized void addItem(int key, String str) {
        if (!itemKeyMap.putIfAbsent(key, true) == null) {
            for (Node node : nodeArray) {
                if (node != null) {
                    node.addItem(new Item(key, str));
                    break;
                }
            }
        } else {
            logger.log(Level.WARNING, "Duplicate key: {0}", key);
        }
    }

    public int countDisjointPairs(int[] array) {
        unionFind.reset();
        for (int value : array) {
            unionFind.union(value, value + 1); // Example union logic
        }
        return unionFind.countDisjointSets();
    }

    private void handleMemoryError(OutOfMemoryError e) {
        logger.log(Level.SEVERE, "Memory allocation error: {0}", e.getMessage());
        System.gc(); // Attempt to free memory
        if (capacity > ALIGNMENT * 4) {
            int newCapacity = calculateAlignedSize(capacity / 2);
            Node[] newArray = new Node[newCapacity];
            size = Math.min(size, newCapacity);
            System.arraycopy(nodeArray, 0, newArray, 0, size);
            nodeArray = newArray;
            capacity = newCapacity;
        }
    }

    public static class Node {
        double value;
        LinkedList<Item> items;

        Node(double value) {
            this.value = value;
            this.items = new LinkedList<>();
        }

        void addItem(Item item) {
            items.add(item);
        }
    }

    public static class Item {
        int key;
        String str;

        Item(int key, String str) {
            this.key = key;
            this.str = str;
        }
    }

    private static class UnionFind {
        private Map<Integer, Integer> parent = new HashMap<>();
        private Set<Integer> sets = ConcurrentHashMap.newKeySet();

        void reset() {
            parent.clear();
            sets.clear();
        }

        int find(int x) {
            if (!parent.containsKey(x)) {
                parent.put(x, x);
                sets.add(x);
            }
            if (x != parent.get(x)) {
                parent.put(x, find(parent.get(x)));
            }
            return parent.get(x);
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent.put(rootX, rootY);
                sets.remove(rootX);
            }
        }

        int countDisjointSets() {
            return sets.size();
        }
    }

    public static void main(String[] args) {
        DataStructureManager manager = new DataStructureManager(10);

        // Example usage
        manager.addNode(1.23);
        manager.addItem(100, "test");
        manager.addItem(101, "example");

        int[] array = {1, 2, 3, 4, 5};
        System.out.println("Disjoint pairs count: " + manager.countDisjointPairs(array));
    }
}
```

### Documentation and Best Practices

#### Integration into Existing Systems
- **Initialization**: Instantiate `DataStructureManager` with an initial capacity based on expected usage.
- **Node Management**: Use `addNode(double value)` to add new nodes. Ensure thread safety by calling this method within synchronized blocks if needed.
- **Item Management**: Use `addItem(int key, String str)` to add items. Duplicate keys are logged and ignored.
- **Disjoint Pairs Calculation**: Call `countDisjointPairs(int[] array)` to determine the number of disjoint sets in an integer array.

#### Error Handling
- The function handles memory allocation errors by attempting garbage collection and resizing if necessary.
- Logs critical operations for monitoring and debugging.

#### Thread Safety
- Use synchronized methods or blocks when accessing shared resources to prevent data corruption.

#### Performance Considerations
- Align memory allocations to 32 bytes for performance optimization.
- Dynamically resize the node array to maintain efficiency under varying loads.

#### Logging
- Critical operations are logged using `java.util.logging.Logger` to facilitate debugging and performance monitoring.

This implementation ensures efficient management of data structures, dynamic resizing, error handling, and thread safety, making it suitable for real-time data processing in constrained environments.']

