#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

#define MAX_RECORDS 10000

typedef struct {
    long *offsets;
    int *ids;
    record *records;
    size_t count;
} DataStructures;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

DataStructures* initialize_data_structures(size_t num_records) {
    if (num_records > MAX_RECORDS) return NULL;

    pthread_mutex_lock(&lock);

    DataStructures *ds = malloc(sizeof(DataStructures));
    if (!ds) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    ds->offsets = calloc(num_records, sizeof(long));
    ds->ids = calloc(num_records, sizeof(int));
    ds->records = malloc(num_records * sizeof(record));
    ds->count = num_records;

    if (!ds->offsets || !ds->ids || !ds->records) {
        free(ds->offsets);
        free(ds->ids);
        free(ds->records);
        free(ds);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        ds->offsets[i] = (long)i;
        ds->ids[i] = (int)(i + 1);
        ds->records[i].value = rand() % 100 + 1;
    }

    pthread_mutex_unlock(&lock);
    return ds;
}

void free_data_structures(DataStructures *ds) {
    if (!ds) return;

    pthread_mutex_lock(&lock);

    free(ds->offsets);
    free(ds->ids);
    free(ds->records);
    free(ds);

    pthread_mutex_unlock(&lock);
}

int main() {
    size_t num_records = 1000;
    DataStructures *data_structures = initialize_data_structures(num_records);

    if (data_structures) {
        // Use the data structures
        free_data_structures(data_structures);
    } else {
        fprintf(stderr, "Failed to initialize data structures.\n");
    }

    return 0;
}
