        free_memory(keys, offsets, records);
        fprintf(stderr, "Duplicate keys found.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize offsets and records with some values
    for (long i = 0; i < offset_count; ++i) {
        offsets[i] = rand() % 1000; // Example offset value
    }

    for (int i = 0; i < key_count; ++i) {
        records[i].value = keys[i];
        records[i].timestamp = time(NULL);
    }

    sort_records_by_key(records, keys, key_count);

    pthread_mutex_unlock(&lock);

    // For demonstration purposes
    printf("Initialization complete.\n");

    // Free allocated memory
    free_memory(keys, offsets, records);
}

int* allocate_keys(int count) {
    return (int*)malloc(sizeof(int) * count);
}

long* allocate_offsets(long count) {
    return (long*)malloc(sizeof(long) * count);
}

record* allocate_records(int count) {
    return (record*)malloc(sizeof(record) * count);
}

void free_memory(int* keys, long* offsets, record* records) {
    if (keys) free(keys);
    if (offsets) free(offsets);
    if (records) free(records);
}

int validate_unique_keys(int* keys, int count) {
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) {
                return 0;
            }
        }
    }
    return 1;
}

void sort_records_by_key(record* records, int* keys, int count) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if (keys[j] > keys[j + 1]) {
                // Swap keys
                int temp_key = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = temp_key;

                // Swap records
                record temp_record = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp_record;
            }
        }
    }
}

int main() {
    initialize_arrays(1000, 500);
    return 0;
}
