['Below is the C code implementing the described functionality for managing memory in a high-performance logging system:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    char content[51];
} string;

record* initialize_logging_system(size_t num_entries) {
    if (num_entries == 0 || num_entries > 100000) return NULL;

    long *file_offsets = malloc(num_entries * sizeof(long));
    int *unique_ids = malloc(num_entries * sizeof(int));
    record *records = malloc(num_entries * sizeof(record));
    string *strings = malloc(num_entries * sizeof(string));

    if (!file_offsets || !unique_ids || !records || !strings) {
        free(file_offsets);
        free(unique_ids);
        free(records);
        free(strings);
        return NULL;
