```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MEMORY_LIMIT (1 * 1024 * 1024) // 1 MB
#define STRING_VALUE "CONSTANT_STRING"
#define UINT_RANGE_MIN 10
#define UINT_RANGE_MAX 100

typedef struct {
    size_t size;
    union {
        double d_val;
        char *s_ptr;
    } u;
} Item;

typedef struct {
    int number;
    char id[20];
    Item* item;
} Record;

typedef struct {
    char string[50];
    unsigned int value;
} CustomStruct;

typedef struct {
    long *long_array[MAX_RECORDS];
    double double_array[MAX_RECORDS];
    CustomStruct struct_array[MAX_RECORDS];
    Record record_array[MAX_RECORDS];
    pthread_mutex_t lock;
    size_t used_memory;
} DataManager;

void init_manager(DataManager* manager);
void cleanup_manager(DataManager* manager);
int add_record(DataManager* manager, int index);

DataManager* create_data_manager() {
    DataManager *manager = (DataManager *)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    memset(manager, 0, sizeof(DataManager));
    init_manager(manager);
    return manager;
}

void init_manager(DataManager* manager) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        char time_str[20];
        snprintf(time_str, sizeof(time_str), "id_%d_%ld", i, time(NULL));

        long *long_ptr = (long *)malloc(sizeof(long));
        *long_ptr = rand() % 100;

        manager->long_array[i] = long_ptr;

        manager->double_array[i] = (double)rand();

        snprintf(manager->struct_array[i].string, sizeof(manager->struct_array[i].string), STRING_VALUE);
        manager->struct_array[i].value = UINT_RANGE_MIN + rand() % (UINT_RANGE_MAX - UINT_RANGE_MIN + 1);

        Record *record = &manager->record_array[i];
        record->number = rand() % 100 + 1;
        strncpy(record->id, time_str, sizeof(record->id) - 1);

        Item *item = (Item *)malloc(sizeof(Item));
        item->size = sizeof(double);
        item->u.d_val = (double)rand();

        record->item = item;

        // Add up the memory usage
        manager->used_memory += sizeof(long) + sizeof(double) +
                                sizeof(manager->struct_array[i]) +
                                sizeof(Record) + sizeof(Item);

        if (manager->used_memory > MEMORY_LIMIT) {
            free(item);
            record->item = NULL;
            manager->used_memory -= sizeof(Item);
            break; // Ensure we don't exceed memory limit
        }
    }
}

void cleanup_manager(DataManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_RECORDS && manager->long_array[i]; ++i) {
        free(manager->long_array[i]);
        manager->long_array[i] = NULL;

        Item *item = manager->record_array[i].item;
        if (item) {
            free(item);
            manager->record_array[i].item = NULL;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(DataManager* manager, int index) {
    pthread_mutex_lock(&manager->lock);

    if (index >= MAX_RECORDS || !manager->long_array[index]) return -1;

    long *new_long_ptr = (long *)malloc(sizeof(long));
    if (!new_long_ptr) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    *new_long_ptr = rand() % 100;

    double new_double_val = (double)rand();

    snprintf(manager->struct_array[index].string, sizeof(manager->struct_array[index].string), STRING_VALUE);
    manager->struct_array[index].value = UINT_RANGE_MIN + rand() % (UINT_RANGE_MAX - UINT_RANGE_MIN + 1);

    Record *record = &manager->record_array[index];
    record->number = rand() % 100 + 1;

    char time_str[20];
    snprintf(time_str, sizeof(time_str), "id_%d_%ld", index, time(NULL));
    strncpy(record->id, time_str, sizeof(record->id) - 1);

    Item *new_item = (Item *)malloc(sizeof(Item));
    if (!new_item) {
        free(new_long_ptr);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    new_item->size = sizeof(double);
    new_item->u.d_val = (double)rand();

    manager->long_array[index] = new_long_ptr;
    manager->double_array[index] = new_double_val;
    record->item = new_item;

    // Calculate the memory
    size_t additional_memory = sizeof(long) + sizeof(double) +
                               sizeof(manager->struct_array[index]) +
                               sizeof(Record) + sizeof(Item);

    if (manager->used_memory + additional_memory > MEMORY_LIMIT) {
        free(new_long_ptr);
        manager->long_array[index] = NULL;

        free(new_item);
        record->item = NULL;

        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory limit exceeded
    }

    manager->used_memory += additional_memory;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Usage example (not part of task)
int main() {
    DataManager* manager = create_data_manager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize data manager.\n");
        return EXIT_FAILURE;
    }

    add_record(manager, 5); // Example usage

    cleanup_manager(manager);
    return EXIT_SUCCESS;
}
```

### Java Method for Connection Management

Here's a simple example of how the Java method might look, focusing on connection management and reconnection:

```java
import java.nio.channels.SocketChannel;
import java.io.IOException;

public class ConnectionManager {
    private final String address;
    private SocketChannel channel;

    public ConnectionManager(String address) {
        this.address = address;
    }

    public void connect() throws IOException {
        if (channel != null && channel.isOpen()) {
            return; // Already connected
        }

        try {
            channel = SocketChannel.open();
            channel.configureBlocking(false);
            channel.connect(/* obtain remote address somehow */);

            // Handle connection states here

        } catch (IOException e) {
            handleConnectionError(e);
        }
    }

    private void handleConnectionError(IOException e) {
        closeConnectionGracefully();

        try {
            Thread.sleep(5000); // Grace period for reconnection
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt(); // Handle interruption
        }

        connect(); // Attempt reconnection
    }

    private void closeConnectionGracefully() {
        if (channel != null && channel.isOpen()) {
            try {
                channel.close();
            } catch (IOException e) {
                System.err.println("Failed to close the connection: " + e.getMessage());
            }
            notifyMessageSystemOfClosure(); // Notify the message system
        }
    }

    private void notifyMessageSystemOfClosure() {
        // Implement messaging system notification logic here
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager("remote_address");

        try {
            manager.connect();
        } catch (IOException e) {
            System.err.println("Failed to establish connection: " + e.getMessage());
        }
    }
}
```

