typedef struct {
    int field1;
    double field2;
} Metadata;

typedef struct {
    time_t timestamp;
    uint32_t unique_id;
    Metadata metadata;
} LogEntry;

#define MAX_LOG_ENTRIES 1000
#define FIELD1_MIN 0
#define FIELD1_MAX 100
#define FIELD2_MIN 0.0
#define FIELD2_MAX 1.0

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

LogEntry* allocate_log_entries(size_t count);
uint32_t generate_unique_id();
Metadata generate_random_metadata();
void free_resources(LogEntry *log_entries, uint32_t *unique_ids, time_t *timestamps);

// Function to manage resources for distributed logging system
void manage_logging_system(size_t log_count) {
    LogEntry *log_entries = allocate_log_entries(log_count);
    if (!log_entries) return;

    uint32_t *unique_ids = (uint32_t *)malloc(log_count * sizeof(uint32_t));
    time_t *timestamps = (time_t *)malloc(log_count * sizeof(time_t));

    if (!unique_ids || !timestamps) {
        free_resources(log_entries, unique_ids, timestamps);
        return;
    }

    for (size_t i = 0; i < log_count; ++i) {
        pthread_mutex_lock(&log_mutex);

        timestamps[i] = time(NULL);
        unique_ids[i] = generate_unique_id();
        log_entries[i].metadata = generate_random_metadata();

        log_entries[i].timestamp = timestamps[i];
        log_entries[i].unique_id = unique_ids[i];

        pthread_mutex_unlock(&log_mutex);
    }

    // Handle high volume or scale horizontally as needed
    // Example: split logs into multiple files or data stores

    free_resources(log_entries, unique_ids, timestamps);
}

LogEntry* allocate_log_entries(size_t count) {
    LogEntry *entries = (LogEntry *)malloc(count * sizeof(LogEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed for log entries\n");
    }
    return entries;
}

uint32_t generate_unique_id() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ((uint32_t)(ts.tv_sec ^ (unsigned long)getpid()) << 16) | (uint32_t)ts.tv_nsec;
}

Metadata generate_random_metadata() {
    Metadata meta;
    srand(time(NULL));
    meta.field1 = rand() % (FIELD1_MAX - FIELD1_MIN + 1) + FIELD1_MIN;
    meta.field2 = ((double)rand() / RAND_MAX) * (FIELD2_MAX - FIELD2_MIN) + FIELD2_MIN;
    return meta;
}

void free_resources(LogEntry *log_entries, uint32_t *unique_ids, time_t *timestamps) {
    if (log_entries) free(log_entries);
    if (unique_ids) free(unique_ids);
    if (timestamps) free(timestamps);
}
```

