    uint16_t tpid;
    uint16_t priority:3;
    uint16_t cfi:1;
    uint16_t vid:12;
    MAC_HEADER mac_header;
} VLAN_TAG;

typedef struct {
    MAC_HEADER mac_header;
    VLAN_TAG vlan_tag;
} NICB;

// Function prototypes
