int get_random_vlan(uint16_t *priority, uint16_t *vid);
size_t configure_memory_allocation(size_t requested_size);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_nicb_array(NICB **nicbs, size_t count, unsigned int min_mac[6], unsigned int max_mac[6]) {
    if (!nicbs || count == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    *nicbs = (NICB *)malloc(configure_memory_allocation(count * sizeof(NICB)));
    if (*nicbs == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    size_t initialized_count = 0;
    for (size_t i = 0; i < count; ++i) {
        NICB *current_nicb = &(*nicbs)[i];

        // Random MAC address generation
        uint32_t random_mac[3] = { rand(), rand(), rand() };
        for (int j = 0; j < 6; ++j) {
            current_nicb->mac_header.dest_mac[j] = ((random_mac[j / 2] >> (8 * (5 - j % 2))) & 0xFF);
            if (current_nicb->mac_header.dest_mac[j] < min_mac[j]) {
                current_nicb->mac_header.dest_mac[j] = min_mac[j];
            } else if (current_nicb->mac_header.dest_mac[j] > max_mac[j]) {
                current_nicb->mac_header.dest_mac[j] = max_mac[j];
            }
        }

        // Copy dest MAC to src for simplicity
        memcpy(current_nicb->mac_header.src_mac, current_nicb->mac_header.dest_mac, 6);

        if (get_random_vlan(&current_nicb->vlan_tag.priority, &current_nicb->vlan_tag.vid) == 0) {
            ++initialized_count;
        } else {
            fprintf(stderr, "Failed to generate VLAN tag for NICB index %zu.\n", i);
        }
    }

    pthread_mutex_unlock(&mutex);

    printf("Initialization report: %zu successfully initialized, %zu failed.\n",
           initialized_count, count - initialized_count);
}

int get_random_vlan(uint16_t *priority, uint16_t *vid) {
    if (!priority || !vid) return 1;

    *priority = rand() & 0x07;
    *vid = (rand() & 0xFFF);
    return 0;
}

size_t configure_memory_allocation(size_t requested_size) {
    // Placeholder for actual memory configuration logic
    size_t aligned_size = ((requested_size + 1023) / 1024) * 1024; // Align to nearest 1KB boundary
    return aligned_size;
}
