        fprintf(stderr, "Invalid number of records. Must be between 1 and 10,000.\n");
        return NULL;
    }

    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *ids = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)malloc(num_records * sizeof(record));

    if (!offsets || !ids || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(ids);
        free(records);
        return NULL;
