// Lock for managing concurrent access
pthread_mutex_t event_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize an array of Events with random data
void init_events(Event **events, int num_events, size_t payload_size) {
    pthread_mutex_lock(&event_lock);

    // Allocate memory for events and their payloads
    *events = malloc(num_events * sizeof(Event));
    if (*events == NULL) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_events; ++i) {
        // Get current timestamp
        time(&((*events)[i].timestamp));

        // Generate unique ID based on timestamp and process ID
        snprintf((*events)[i].unique_id, sizeof((*events)[i].unique_id),
                 "event_%ld_%d", (*events)[i].timestamp, (int)getpid());

        // Allocate memory for payload and fill with random data
        (*events)[i].payload = malloc(payload_size);
        if ((*events)[i].payload == NULL) {
            perror("Failed to allocate memory for event payload");
            exit(EXIT_FAILURE);
        }

        // Populate payload with random values within a specified range (0-255)
        for (size_t j = 0; j < payload_size; ++j) {
            (*events)[i].payload[j] = rand() % 256;
        }
    }

    pthread_mutex_unlock(&event_lock);
}

// Function to clean up allocated resources
void cleanup_events(Event *events, int num_events, size_t payload_size) {
    if (events != NULL) {
        for (int i = 0; i < num_events; ++i) {
            free(events[i].payload);
        }
        free(events);
    }
}

// Main function to demonstrate usage
int main() {
    srand((unsigned int)time(NULL));

    const int num_events = 100;
    const size_t payload_size = 128;

    Event *events = NULL;

    // Initialize events with random data
    init_events(&events, num_events, payload_size);

    // Simulate event processing (placeholder for actual logic)
    printf("Processing %d events...\n", num_events);

    // Cleanup allocated resources after processing
    cleanup_events(events, num_events, payload_size);

    return 0;
}
```

This code defines a C program that initializes an array of `Event` structures with random data. It uses mutex locks to ensure thread safety when accessing shared resources during dynamic memory allocation. The function `init_events` allocates memory for the events and their payloads, while `cleanup_events` deallocates it. This example assumes usage in a multithreaded context where concurrent access needs protection via locking mechanisms.']

