#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB

typedef struct {
    size_t size;
    union {
        double d_value;
        char *str_ptr;
    } data;
} Item;

typedef struct {
    int value;
    char identifier[64];
    Item *item_ptr;
} Record;

// Global variables for memory management
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
long long current_memory_usage = 0;
Record **records_array;
int records_count = 0;

void initialize_system(size_t initial_size);
void free_system();
void add_record(int key, int value);
void *free_least_recently_used(void *arg);
Item* create_item(double d_value);
Item* create_item_with_string(char *str);

// JNI methods
#include <jni.h>

static JavaVM *jvm = NULL;

JNIEXPORT jint JNICALL JNI_OnLoad(JavaVM *vm, void *reserved) {
    jvm = vm;
    return JNI_VERSION_1_6;
}

void setup_java_environment(JNIEnv **env) {
    (*jvm)->AttachCurrentThread(jvm, (void **) env, NULL);
}

void detach_from_jni_thread() {
    if (jvm != NULL) {
        jvm->DetachCurrentThread(jvm);
    }
}

// Example Java component for connection management
extern "C" void manage_java_connection(JNIEnv *env) {
    jclass channelClass = (*env)->FindClass(env, "com/example/JavaChannel");
    jmethodID connectMethod = (*env)->GetMethodID(env, channelClass, "connect", "()V");

    // Connection logic with error handling and reconnection
    if (connectMethod != NULL) {
        (*env)->CallVoidMethod(env, (*env)->NewObject(env, channelClass), connectMethod);
    }
}

void log_memory_usage() {
    pthread_mutex_lock(&memory_lock);
    printf("Current memory usage: %lld bytes\n", current_memory_usage);
    pthread_mutex_unlock(&memory_lock);
}

// Implement the main C function for dynamic allocation and initialization
void initialize_system(size_t initial_size) {
    records_array = (Record **) malloc(initial_size * sizeof(Record *));
    if (!records_array) {
        perror("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }
}

Item* create_item(double d_value) {
    Item* item = (Item*) malloc(sizeof(Item));
    if (!item) {
        perror("Failed to allocate memory for item");
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);
    current_memory_usage += sizeof(Item);
    pthread_mutex_unlock(&memory_lock);

    item->size = sizeof(double);
    item->data.d_value = d_value;

    return item;
}

Item* create_item_with_string(char *str) {
    Item* item = (Item*) malloc(sizeof(Item));
    if (!item) {
        perror("Failed to allocate memory for item");
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);
    current_memory_usage += sizeof(Item) + strlen(str) + 1; // +1 for null terminator
    pthread_mutex_unlock(&memory_lock);

    item->size = strlen(str) + 1;
    item->data.str_ptr = strdup(str);

    return item;
}

void add_record(int key, int value) {
    pthread_mutex_lock(&memory_lock);

    if (current_memory_usage >= MAX_MEMORY_USAGE) {
        // Free least recently used record
        free_least_recently_used(NULL);
    }

    Record *new_record = (Record *) malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    snprintf(new_record->identifier, sizeof(new_record->identifier), "ID_%d_%ld", key, time(NULL));
    new_record->value = value;

    Item *item = create_item(value); // Example item creation
    if (!item) {
        free(new_record);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    new_record->item_ptr = item;

    records_array[records_count++] = new_record;

    pthread_mutex_unlock(&memory_lock);

    log_memory_usage();
}

void *free_least_recently_used(void *arg) {
    if (records_count == 0) return NULL;

    // Simple strategy: free the last record
    Record *record_to_free = records_array[--records_count];
    pthread_mutex_lock(&memory_lock);

    current_memory_usage -= sizeof(Record) + record_to_free->item_ptr->size;

    free(record_to_free->item_ptr->data.str_ptr);  // Only if it's a string item
    free(record_to_free->item_ptr);
    free(record_to_free);

    pthread_mutex_unlock(&memory_lock);

    return NULL;
}

void free_system() {
    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < records_count; ++i) {
        free(records_array[i]->item_ptr->data.str_ptr); // Only if it's a string item
        free(records_array[i]->item_ptr);
        free(records_array[i]);
    }

    free(records_array);
    current_memory_usage = 0;

    pthread_mutex_unlock(&memory_lock);

    log_memory_usage();
}

