#define ALIGNMENT 1024

typedef enum {
    PLANNING,
    DEVELOPMENT,
    REVIEW
} ActivityType;

typedef struct ConstraintNode {
    int dependency_id;
    float limit;
    time_t deadline;
    struct ConstraintNode* next;
} ConstraintNode;

typedef struct ActivityNode {
    int priority;
    ActivityType type;
    int resource_demand;
    int criticality; // Use 0 or 1 for boolean representation
    struct ConstraintNode* constraints;
    struct ActivityNode* next;
} ActivityNode;

typedef struct Schedule {
    ActivityNode* head;
} Schedule;

// Function to align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#else
    #error "Platform not supported for aligned allocation"
#endif
    return ptr;
}

// Function to free aligned memory
void aligned_free(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    free(ptr);
#else
    #error "Platform not supported for aligned deallocation"
#endif
}

// Function to initialize constraints
ConstraintNode* init_constraints(int num_constraints, int dependency_id) {
    ConstraintNode* head = NULL;
    ConstraintNode* current = NULL;

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_constraints; ++i) {
        ConstraintNode* new_node = aligned_alloc(ALIGNMENT, sizeof(ConstraintNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        new_node->dependency_id = dependency_id + i;
        new_node->limit = (float)(rand() % 100) / 10.0; // Random limit between 0 and 10
        new_node->deadline = time(NULL) + ((i + 1) * 60); // Deadline in minutes from now
        new_node->next = NULL;

        if (!head) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

// Function to initialize activities based on a state machine
ActivityType determine_activity_type(int priority, int progress, int resource_demand) {
    if (priority > 5 && resource_demand < 50) {
        return PLANNING;
    } else if (progress > 50) {
        return DEVELOPMENT;
    } else {
        return REVIEW;
    }
}

// Function to initialize the schedule
Schedule* init_schedule(int num_activities, int max_constraints_per_activity) {
    Schedule* schedule = aligned_alloc(ALIGNMENT, sizeof(Schedule));
    if (!schedule) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    schedule->head = NULL;

    for (int i = 0; i < num_activities; ++i) {
        ActivityNode* new_activity = aligned_alloc(ALIGNMENT, sizeof(ActivityNode));
        if (!new_activity) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        new_activity->priority = rand() % 10; // Random priority between 0 and 9
        int progress = rand() % 100; // Simulated progress percentage
        new_activity->type = determine_activity_type(new_activity->priority, progress, i * 10);
        new_activity->resource_demand = i * 10;
        new_activity->criticality = (i % 2 == 0) ? 1 : 0; // Alternating criticality for simplicity

        new_activity->constraints = init_constraints(rand() % max_constraints_per_activity + 1, i);
        if (!new_activity->constraints) {
            fprintf(stderr, "Memory allocation failed\n");
            aligned_free(new_activity);
            return NULL;
        }

        new_activity->next = schedule->head;
        schedule->head = new_activity;
    }

    // Verify integrity
    ActivityNode* current = schedule->head;
    while (current) {
        if (!current->constraints && rand() % 10 > 5) { // Simulate constraint presence check
            fprintf(stderr, "Integrity check failed\n");
            return NULL;
        }
        current = current->next;
    }

    return schedule;
}

// Main function to demonstrate usage
int main() {
    int num_activities = 10;
    int max_constraints_per_activity = 5;

    Schedule* schedule = init_schedule(num_activities, max_constraints_per_activity);
    if (!schedule) {
        fprintf(stderr, "Failed to initialize schedule\n");
        return EXIT_FAILURE;
    }

    printf("Schedule initialized successfully with %d activities.\n", num_activities);

    // Cleanup
    ActivityNode* activity = schedule->head;
    while (activity) {
        ConstraintNode* constraint = activity->constraints;
        while (constraint) {
            ConstraintNode* temp = constraint;
            constraint = constraint->next;
            aligned_free(temp);
        }
        ActivityNode* temp_activity = activity;
        activity = activity->next;
        aligned_free(temp_activity);
    }
    aligned_free(schedule);

    return EXIT_SUCCESS;
}
