import requests
import time
from datetime import datetime
import logging

LOG_FILE = 'export_log.txt'
EXPORT_URL = 'http://example.com/export'
RETRY_INTERVAL_SECONDS = 5
MAX_RETRIES = 3

logging.basicConfig(filename=LOG_FILE, level=logging.INFO)

def export_data(data):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            response = requests.post(EXPORT_URL, json=data)
            if response.status_code == 200:
                logging.info(f"Data exported successfully at {datetime.now()}")
                return True
            else:
                logging.warning(f"Export failed with status code {response.status_code} at {datetime.now()}")
        except requests.RequestException as e:
            logging.error(f"Request error: {e} at {datetime.now()}")

        retries += 1
        time.sleep(RETRY_INTERVAL_SECONDS)

    return False

def main():
    while True:
        data = {
            'active_connections': 10,  # Example data
            'connection_failures': 2,
            'retry_attempts': 3
        }

        success = export_data(data)
        if not success:
            logging.error("Failed to export data after retries")

        time.sleep(60)  # Wait before next export attempt

if __name__ == "__main__":
    main()
