#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int value;
} record;

typedef struct hash_table_node {
    int key;
    long offset;
    struct hash_table_node* next;
} hash_table_node;

typedef struct {
    hash_table_node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table(size_t capacity) {
    hash_table* table = malloc(sizeof(hash_table));
    table->buckets = calloc(capacity, sizeof(hash_table_node*));
    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash_function(int key, size_t capacity) {
    return ((unsigned long)key * 2654435761U) % capacity;
}

void resize_hash_table(hash_table* table);

int insert_to_hash_table(hash_table* table, int key, long offset) {
    unsigned long index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->lock);

    for (hash_table_node* node = table->buckets[index]; node; node = node->next) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->lock);
            return 0; // Key already exists
        }
    }

    hash_table_node* new_node = malloc(sizeof(hash_table_node));
    new_node->key = key;
    new_node->offset = offset;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    if (++table->size > (unsigned long)table->capacity * LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->lock);
    return 1; // Inserted successfully
}

void resize_hash_table(hash_table* table) {
    size_t new_capacity = table->capacity * 2;
    hash_table_node** new_buckets = calloc(new_capacity, sizeof(hash_table_node*));

    for (size_t i = 0; i < table->capacity; ++i) {
        hash_table_node* node = table->buckets[i];
        while (node) {
            unsigned long new_index = hash_function(node->key, new_capacity);
            hash_table_node* next_node = node->next;
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void initialize_data(long* offsets, int* keys, record** records, size_t num_elements,
                     int range_min, int range_max, hash_table** mapping) {
    *mapping = create_hash_table(INITIAL_CAPACITY);

    offsets = malloc(num_elements * sizeof(long));
    keys = malloc(num_elements * sizeof(int));
    *records = malloc(num_elements * sizeof(record));

    if (!offsets || !keys || !*records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = rand(); 
        keys[i] = rand() % 10000; // Assume a range for demonstration
        insert_to_hash_table(*mapping, keys[i], offsets[i]);
        (*records)[i].value = range_min + (rand() % (range_max - range_min + 1));
    }
}

void free_resources(long* offsets, int* keys, record* records, hash_table* mapping) {
    for (size_t i = 0; i < mapping->capacity; ++i) {
        hash_table_node* node = mapping->buckets[i];
        while (node) {
            hash_table_node* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(mapping->buckets);
    pthread_mutex_destroy(&mapping->lock);
    free(mapping);

    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

void update_records_periodically(record* records, size_t num_elements,
                                 int range_min, int range_max) {
    // This would be implemented with periodic logic using timers or external triggers
    for (size_t i = 0; i < num_elements; ++i) {
        records[i].value = range_min + (rand() % (range_max - range_min + 1));
    }
}

// Usage example:
int main() {
    size_t num_elements = 100;
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;
    hash_table* mapping = NULL;

