// Memory Protection Flags (bitmask)
typedef enum {
    PROT_READ = 1 << 0,
    PROT_WRITE = 1 << 1,
    PROT_EXEC = 1 << 2,
} prot_flags_t;

// Page Table Entry structure
typedef struct {
    uintptr_t physical_address;
    uint64_t flags; // Includes protection flags and other attributes
} PTE_t;

// MMU Structure with virtual memory addresses and a Page Table Entry
typedef struct {
    void* vaddr;
    PTE_t pte;
} MMUEntry_t;

// Memory Policy Configuration structure
typedef struct {
    size_t page_size;
    prot_flags_t protection;
    size_t alignment;
} mem_policy_t;

// Function to dynamically allocate memory for the array of MMU entries
MMUEntry_t* init_mmu_array(size_t num_entries, mem_policy_t policy) {
    if (num_entries == 0 || num_entries > MAX_MMU_ENTRIES) {
        fprintf(stderr, "Invalid number of MMU entries.\n");
        return NULL;
    }

    // Adjust page size and alignment based on policy
    size_t page_size = policy.page_size ? policy.page_size : DEFAULT_PAGE_SIZE;
    size_t alignment = policy.alignment ? policy.alignment : DEFAULT_ALIGNMENT;

    MMUEntry_t* mmu_array = (MMUEntry_t*)malloc(num_entries * sizeof(MMUEntry_t));
    if (!mmu_array) {
        fprintf(stderr, "Memory allocation failed for MMU array.\n");
        return NULL;
    }

    // Initialize MMU entries
    for (size_t i = 0; i < num_entries; ++i) {
        mmu_array[i].vaddr = aligned_alloc(alignment, page_size);
        if (!mmu_array[i].vaddr) {
            fprintf(stderr, "Memory allocation failed for virtual address %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(mmu_array[j].vaddr);
            }
            free(mmu_array);
            return NULL;
        }

        mmu_array[i].pte.physical_address = (uintptr_t)mmu_array[i].vaddr;
        mmu_array[i].pte.flags = policy.protection;
    }

    return mmu_array;
}

