        records[i].value = rand() % 50 + 1; // Random value within a specified range
        records[i].key_ptr = &keys[i];
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < *max_records; ++i) {
        if (records[i].key_ptr < keys || records[i].key_ptr >= &keys[*max_records]) {
            log_memory_event("Invalid pointer detected", FAILURE);
            pthread_mutex_unlock(&lock);
            pthread_mutex_destroy(&lock);
            free(offsets); offsets = NULL;
            free(keys); keys = NULL;
            free(records); records = NULL;
            return FAILURE;
        }
    }
    pthread_mutex_unlock(&lock);

    log_memory_event("Memory allocated and validated", SUCCESS);

