    }

    // Clean up
    log_memory_event("Deallocating memory", SUCCESS);
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&lock);

    return SUCCESS;
}

void* handle_concurrent_access(void *records_ptr) {
