#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int ref_count;
} record;

typedef struct {
    int key;
    long offset;
} key_offset_map;

typedef struct {
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    key_offset_map **map;
    size_t map_capacity;
} dataset;

dataset* initialize_dataset(size_t initial_capacity) {
    dataset *ds = malloc(sizeof(dataset));
    if (!ds) return NULL;

    ds->capacity = initial_capacity;
    ds->count = 0;

    ds->records = calloc(ds->capacity, sizeof(record *));
    if (!ds->records) {
        free(ds);
        return NULL;
    }

    ds->map_capacity = ds->capacity;
    ds->map = malloc(ds->map_capacity * sizeof(key_offset_map *));
    if (!ds->map) {
        free(ds->records);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    return ds;
}

int add_record(dataset *ds, int key, int value, long offset) {
    pthread_mutex_lock(&ds->lock);

    if (ds->count >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        record **new_records = realloc(ds->records, new_capacity * sizeof(record *));
        if (!new_records) {
            pthread_mutex_unlock(&ds->lock);
            return -1; // Memory allocation failure
        }
        ds->records = new_records;
        ds->capacity = new_capacity;

        key_offset_map **new_map = realloc(ds->map, new_capacity * sizeof(key_offset_map *));
        if (!new_map) {
            pthread_mutex_unlock(&ds->lock);
            return -1; // Memory allocation failure
        }
        ds->map = new_map;
        ds->map_capacity = new_capacity;
    }

    record *rec = malloc(sizeof(record));
    if (!rec) {
        pthread_mutex_unlock(&ds->lock);
        return -1; // Memory allocation failure
    }

    rec->value = value;
    rec->offset = malloc(sizeof(long));
    if (!rec->offset) {
        free(rec);
        pthread_mutex_unlock(&ds->lock);
        return -1; // Memory allocation failure
    }
    *rec->offset = offset;
    rec->ref_count = 1;

    ds->records[ds->count++] = rec;

    key_offset_map *map_entry = malloc(sizeof(key_offset_map));
    if (!map_entry) {
        free(rec);
        pthread_mutex_unlock(&ds->lock);
        return -1; // Memory allocation failure
    }
    map_entry->key = key;
    map_entry->offset = offset;

    ds->map[ds->count - 1] = map_entry;

    pthread_mutex_unlock(&ds->lock);

    return 0;
}

record* get_record(dataset *ds, int key) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count; ++i) {
        if (key == ds->map[i]->key) {
            ds->records[i]->ref_count++;
            pthread_mutex_unlock(&ds->lock);
            return ds->records[i];
        }
    }

    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

void release_record(record *rec) {
    if (--rec->ref_count == 0) {
        free(rec->offset);
        free(rec);
    }
}

void shutdown_dataset(dataset *ds) {
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]->offset);
        free(ds->records[i]);
        free(ds->map[i]);
    }

    free(ds->records);
    free(ds->map);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int main() {
    dataset *ds = initialize_dataset(10);
    if (!ds) return -1;

    add_record(ds, 1, 100, 200L);
    record *rec = get_record(ds, 1);

    if (rec) {
        printf("Record value: %d\n", rec->value);
        release_record(rec);
    }

    shutdown_dataset(ds);
    return 0;
}
