#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_DEVICES 1000

typedef struct {
    float measurement;
    char identifier[10];
    int status; // 0: not ready, 1: ready
} Device;

typedef struct {
    Device *devices;
    size_t count;
    pthread_mutex_t lock;
} DeviceCollection;

DeviceCollection* init_device_collection(size_t initial_size) {
    DeviceCollection *collection = malloc(sizeof(DeviceCollection));
    collection->devices = calloc(initial_size, sizeof(Device));
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void insert_device(DeviceCollection *collection, float measurement, const char* identifier, int status) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_DEVICES) {
        fprintf(stderr, "Maximum device limit reached.\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Device new_device = { .measurement = measurement, .status = status };
    strncpy(new_device.identifier, identifier, sizeof(new_device.identifier) - 1);
    new_device.identifier[sizeof(new_device.identifier) - 1] = '\0';

    collection->devices[collection->count++] = new_device;

    pthread_mutex_unlock(&collection->lock);
}

void update_device(DeviceCollection *collection, const char* identifier, float measurement, int status) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->devices[i].identifier, identifier) == 0) {
            collection->devices[i].measurement = measurement;
            collection->devices[i].status = status;
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    fprintf(stderr, "Device not found.\n");
    pthread_mutex_unlock(&collection->lock);
}

void delete_device(DeviceCollection *collection, const char* identifier) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->devices[i].identifier, identifier) == 0) {
            memmove(&collection->devices[i], &collection->devices[i + 1],
                    (--collection->count - i) * sizeof(Device));
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }

    fprintf(stderr, "Device not found.\n");
    pthread_mutex_unlock(&collection->lock);
}

void free_device_collection(DeviceCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->devices);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void log_change(const char* action, const Device* device) {
    // Log the change with minimal overhead
    printf("Action: %s - ID: %s - Measurement: %.2f - Status: %d\n",
           action, device->identifier, device->measurement, device->status);
}

void populate_initial_data(DeviceCollection *collection, const float* measurements,
                           const char** identifiers, int* statuses, size_t num_devices) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < num_devices; ++i) {
        if (!identifiers[i] || statuses[i] < 0) continue; // Skip invalid data

        Device new_device = { .measurement = measurements[i], .status = statuses[i] };
        strncpy(new_device.identifier, identifiers[i], sizeof(new_device.identifier) - 1);
        new_device.identifier[sizeof(new_device.identifier) - 1] = '\0';

        if (collection->count >= MAX_DEVICES) break;

        collection->devices[collection->count++] = new_device;
    }

    pthread_mutex_unlock(&collection->lock);
}

void periodic_update(DeviceCollection *collection) {
    // Implement integration with external monitoring system
    // For simplicity, we'll just print the devices every update cycle.
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        printf("Periodic Update - ID: %s - Measurement: %.2f - Status: %d\n",
               collection->devices[i].identifier, collection->devices[i].measurement,
               collection->devices[i].status);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Example usage
int main() {
    DeviceCollection *collection = init_device_collection(10);

    float measurements[] = { 1.0f, 2.5f };
    const char* identifiers[] = { "Device1", "Device2" };
    int statuses[] = { 1, 0 };

    populate_initial_data(collection, measurements, identifiers, statuses, 2);

    insert_device(collection, 3.7f, "Device3", 1);
    update_device(collection, "Device2", 4.5f, 1);
    delete_device(collection, "Device1");

    periodic_update(collection);

    free_device_collection(collection);

    return 0;
}
