typedef struct Item {
    int key;
    char str[11]; // Fixed-length alphanumeric string (10 chars + null terminator)
} Item;

typedef struct Node {
    double value;
    struct Item *items;
    struct Node *next;
} Node;

typedef struct Record {
    short value;
    char identifier;
    float *float_ptr;
    Node *node_list;
} Record;

void initialize_random() {
    time_t t;
    srand((unsigned) time(&t));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_alphanumeric_string(size_t length) {
    static const char alphanum[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";

    char *str = malloc(length + 1);
    for (size_t i = 0; i < length; i++) {
        str[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
    }
    str[length] = '\0';
    return str;
}

float* allocate_aligned_float(float min, float max, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, sizeof(float)) != 0) {
        return NULL; // Allocation failed
    }
    *(float *)ptr = min + ((max - min) * rand() / RAND_MAX);
    return ptr;
}

Node* create_node(int key, double value, size_t item_count) {
    Node *node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->items = calloc(item_count, sizeof(Item));
    if (!node->items) {
        free(node);
        return NULL;
    }

    for (size_t i = 0; i < item_count; i++) {
        node->items[i].key = key + i;
        char *random_str = generate_alphanumeric_string(10);
        strncpy(node->items[i].str, random_str, sizeof(node->items[i].str));
        free(random_str);
    }

    node->next = NULL;
    return node;
}

Record* manage_records(size_t record_count, float float_min, float float_max,
                       int key_min, int key_max, size_t item_count_per_node,
                       double value_range_min, double value_range_max, size_t alignment) {

    if (record_count == 0) return NULL;

    Record *records = malloc(record_count * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < record_count; i++) {
        records[i].value = random_int(-32768, 32767);
        records[i].identifier = 'A' + rand() % 26;

        records[i].float_ptr = allocate_aligned_float(float_min, float_max, alignment);
        if (!records[i].float_ptr) {
            for (size_t j = 0; j < i; j++) {
                free(records[j].float_ptr);
            }
            free(records);
            return NULL;
        }

        double random_value = sqrt(random_int((int)value_range_min, (int)value_range_max));
        records[i].node_list = create_node(random_int(key_min, key_max), random_value, item_count_per_node);
        if (!records[i].node_list) {
            for (size_t j = 0; j <= i; j++) {
                free(records[j].float_ptr);
                Node *current = records[j].node_list;
                while (current) {
                    Node *next = current->next;
                    free(current->items);
                    free(current);
                    current = next;
                }
            }
            free(records);
            return NULL;
        }
    }

    // Simulated data source update
    // fetch_new_ranges_from_external_source(&float_min, &float_max, &value_range_min, &value_range_max);

    return records; // Caller is responsible for freeing memory
}

// Example usage
int main() {
    initialize_random();

    size_t record_count = 5;
    Record *records = manage_records(record_count,
                                     0.0f, 1.0f, 
                                     0, 100, 
                                     3, // Number of items per node
                                     0.0, 100.0, // Value range for sqrt calculation
                                     32);

    if (records) {
        // Use the records...

        // Free allocated memory
