use std::collections::{HashMap, LinkedList};
use std::sync::{Arc, Mutex};
use std::env;
use std::fs;
use std::path::PathBuf;
use std::thread;
use std::time::{Duration, Instant};
use crossbeam_channel::{bounded, Sender, Receiver};

#[derive(Debug)]
enum Severity {
    Debug,
    Info,
    Warning,
    Error,
}

#[derive(Debug)]
struct Context {
    key: String,
    value: String,
    next: Option<Box<Context>>,
}

#[derive(Debug)]
struct LogEntry {
    timestamp: Instant,
    severity: Severity,
    message: String,
    context: LinkedList<Context>,
}

#[derive(Default)]
struct Logger {
    entries: Mutex<HashMap<u64, LogEntry>>,
}

impl Logger {
    fn new() -> Self {
        Logger::default()
    }

    fn add_entry(&self, entry: LogEntry) {
        let mut entries = self.entries.lock().unwrap();
        entries.insert(entry.timestamp.elapsed().as_millis(), entry);
    }
}

fn check_and_run(label: &str, f: impl FnOnce() + Send + 'static, timeout: Duration) -> Result<(), String> {
    let (tx, rx): (Sender<()>, Receiver<_>) = bounded(1);
    thread::spawn(move || {
        tx.send(()).unwrap();
        thread::sleep(timeout);
        if rx.recv().is_err() {
            eprintln!("Check '{}' timed out", label);
        }
    });

    f();

    match rx.recv_timeout(Duration::from_millis(100)) {
        Ok(_) => Ok(()),
        Err(_) => Err(format!("Check '{}' did not complete in time", label)),
    }
}

fn initialize_logging_system() {
    let logger = Logger::new();

    // Check if configuration path is set
