#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

#define FLOAT_ALLOC_ALIGN 32

typedef struct Item {
    int key;
    char str[10]; // Fixed length alphanumeric string
} Item;

typedef struct Node {
    double value;
    struct Node* next;
    Item item;
} Node;

typedef struct Record {
    short short_value;
    char identifier;
    float *float_ptr;
    Node* node_list_head;
} Record;

typedef struct OffsetKey {
    long offset;
    int key;
} OffsetKey;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_random() {
    time_t t;
    srand((unsigned) time(&t));
}

float* aligned_alloc_float(float min_val, float max_val) {
    void *ptr;
    if (posix_memalign(&ptr, FLOAT_ALLOC_ALIGN, sizeof(float))) {
        return NULL; // Allocation failed
    }
    *(float*)ptr = ((max_val - min_val) * rand() / RAND_MAX) + min_val;
    return (float *)ptr;
}

Node* create_node(int key_range_min, int key_range_max, double value_range_min, double value_range_max) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
    snprintf(node->str, sizeof(node->str), "%d%s", node->key, "random");
    node->value = sqrt((double)(rand() % (int)((value_range_max * value_range_max) - (value_range_min * value_range_min)) + (value_range_min * value_range_min)));
    node->next = NULL;
    return node;
}

Record* allocate_records(size_t record_count, float float_min, float float_max, int key_range_min, int key_range_max,
                         double value_range_min, double value_range_max) {
    if (record_count <= 0 || float_min >= float_max || key_range_min > key_range_max ||
        value_range_min > value_range_max) return NULL;

    Record *records = calloc(record_count, sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < record_count; ++i) {
        records[i].short_value = rand();
        records[i].identifier = 'A' + (rand() % 26);
        records[i].float_ptr = aligned_alloc_float(float_min, float_max);
        if (!records[i].float_ptr) {
            free_records(records, i); // Clean up on failure
            return NULL;
        }

        records[i].node_list_head = create_node(key_range_min, key_range_max,
                                                value_range_min, value_range_max);
        if (!records[i].node_list_head) {
            free_float_ptr(records[i].float_ptr);
            free_records(records, i); // Clean up on failure
            return NULL;
        }
    }

    return records;
}

OffsetKey* allocate_offset_keys(size_t count) {
    OffsetKey *offsets = calloc(count, sizeof(OffsetKey));
    if (!offsets) return NULL;

    for (size_t i = 0; i < count; ++i) {
        offsets[i].offset = rand();
        offsets[i].key = rand() % 1000;
    }

    return offsets;
}

void* allocate_record_array(size_t size, int max_val) {
    if (size == 0 || max_val <= 0) return NULL;

    void *array = malloc(2 * size * sizeof(int));
    if (!array) return NULL;

    for (size_t i = 0; i < 2 * size; ++i) {
        int value;
        do {
            value = rand() % max_val;
        } while ((i > 0) && (value == ((int*)array)[i - 1]));
        ((int*)array)[i] = value;
    }

    return array;
}

void free_records(Record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i].float_ptr) {
            free(records[i].float_ptr);
        }
        Node* node = records[i].node_list_head;
        while (node) {
            Node *next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(records);
}

void free_float_ptr(float* ptr) {
    if (ptr) {
        free(ptr);
    }
}

int main() {
    initialize_random();

    size_t n = 10; // Example count
    float float_min = 0.0, float_max = 100.0;
    int key_range_min = 1, key_range_max = 100;
    double value_range_min = 0.0, value_range_max = 50.0;

    Record* records = allocate_records(n, float_min, float_max, key_range_min, key_range_max,
                                       value_range_min, value_range_max);
    if (!records) {
        fprintf(stderr, "Failed to allocate records\n");
        return EXIT_FAILURE;
    }

    OffsetKey* offset_keys = allocate_offset_keys(n);
    if (!offset_keys) {
        free_records(records, n);
        fprintf(stderr, "Failed to allocate offset keys\n");
        return EXIT_FAILURE;
    }

    void *record_array = allocate_record_array(n, 1000);
    if (!record_array) {
        free(offset_keys);
        free_records(records, n);
        fprintf(stderr, "Failed to allocate record array\n");
        return EXIT_FAILURE;
    }

    // Use records, offset_keys and record_array...

    pthread_mutex_lock(&lock); 
    free(offset_keys);
    free(record_array);
    free_records(records, n);
    pthread_mutex_unlock(&lock);

    return 0;
}
