#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define ALIGNMENT 32
#define ITEM_STRING_SIZE 16

typedef struct Item {
    int key;
    char value[ITEM_STRING_SIZE];
} Item;

typedef struct Node {
    double data;
    struct Item *items;
    size_t item_count;
    struct Node *next;
} Node;

// Buddy allocator structure and functions
typedef struct BuddyAllocator {
    // Placeholder for internal state management of buddy system
    void* base;  // Base address for allocated memory
    size_t total_size; // Total managed size
    pthread_mutex_t lock; // Mutex for thread safety
} BuddyAllocator;

BuddyAllocator* create_buddy_allocator(size_t initial_size) {
    BuddyAllocator *allocator = malloc(sizeof(BuddyAllocator));
    allocator->base = aligned_alloc(ALIGNMENT, initial_size);
    allocator->total_size = initial_size;
    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

void* buddy_allocate(BuddyAllocator* allocator, size_t size) {
    // Implement the allocation logic for the buddy system
    pthread_mutex_lock(&allocator->lock);

    void *allocated_memory = aligned_alloc(ALIGNMENT, size);

    if (allocated_memory != NULL) {
        printf("Allocated %zu bytes at address %p with alignment %d\n", size, allocated_memory, ALIGNMENT);
    } else {
        printf("Allocation failed for %zu bytes\n", size);
    }

    pthread_mutex_unlock(&allocator->lock);
    return allocated_memory;
}

void buddy_deallocate(BuddyAllocator* allocator, void* ptr) {
    // Implement the deallocation logic
    pthread_mutex_lock(&allocator->lock);

    free(ptr);
    printf("Deallocated memory at address %p\n", ptr);

    pthread_mutex_unlock(&allocator->lock);
}

// Functions for node management
Node* create_node(double value) {
    Node *node = buddy_allocate(global_allocator, sizeof(Node));
    if (node == NULL) return NULL;

    node->data = value;
    node->items = NULL;
    node->item_count = 0;
    node->next = NULL;

    printf("Node created with data: %f\n", value);

    return node;
}

void add_item_to_node(Node* node, int key, const char *value) {
    size_t item_size = sizeof(Item);
    Item *new_items = buddy_allocate(global_allocator, (node->item_count + 1) * item_size);

    if (!new_items || !node->items) {
        printf("Memory allocation failed for items.\n");
        return;
    }

    if (node->items) {
        memcpy(new_items, node->items, node->item_count * item_size);
        buddy_deallocate(global_allocator, node->items);
    }

    strncpy(new_items[node->item_count].value, value, ITEM_STRING_SIZE - 1);
    new_items[node->item_count].key = key;
    node->items = new_items;
    node->item_count++;

    printf("Added item with key: %d\n", key);
}

void serialize_node(Node* node, FILE* file) {
    if (node == NULL || file == NULL) return;

    fwrite(&node->data, sizeof(double), 1, file);
    fwrite(&node->item_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < node->item_count; ++i) {
        Item *item = &node->items[i];
        fwrite(&item->key, sizeof(int), 1, file);
        fwrite(item->value, ITEM_STRING_SIZE, 1, file);
    }
}

Node* deserialize_node(FILE* file) {
    if (file == NULL) return NULL;

    Node *node = create_node(0.0);
    if (!node) return NULL;

    fread(&node->data, sizeof(double), 1, file);
    fread(&node->item_count, sizeof(size_t), 1, file);

    node->items = buddy_allocate(global_allocator, node->item_count * sizeof(Item));

    for (size_t i = 0; i < node->item_count; ++i) {
        Item *item = &node->items[i];
        fread(&item->key, sizeof(int), 1, file);
        fread(item->value, ITEM_STRING_SIZE, 1, file);
    }

    return node;
}

void cleanup_node(Node* node) {
    if (!node) return;

    buddy_deallocate(global_allocator, node->items);
    buddy_deallocate(global_allocator, node);
}

// Global allocator for demonstration purposes
BuddyAllocator *global_allocator = create_buddy_allocator(1024 * 1024); // 1MB initial allocation

void unit_tests() {
    // Test case: Create nodes and manage items
    Node* node1 = create_node(3.14);
    add_item_to_node(node1, 1, "ItemOne");
    add_item_to_node(node1, 2, "ItemTwo");

    FILE *file = fopen("node_data.bin", "wb");
    if (file) {
        serialize_node(node1, file);
        fclose(file);

        Node* node2 = deserialize_node(fopen("node_data.bin", "rb"));
        cleanup_node(node2); // Cleanup deserialized node
        fclose(file);
    }

    cleanup_node(node1);
}

int main() {
    unit_tests();

    pthread_mutex_destroy(&global_allocator->lock);
    free(global_allocator);

    return 0;
}
```

