#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

#define ALIGNMENT 16
#define MEMORY_LIMIT_PERCENTAGE 0.8

// Function to get available memory (platform-dependent)
size_t get_available_memory() {
    // This is a placeholder for actual implementation which varies by OS
    return 1024 * 1024 * 1024; // Assume 1GB available for simplicity
}

// Align memory address to specified boundary
void* align_alloc(size_t size, size_t alignment) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

int is_pow2(uint64_t x) {
    return (x & (x - 1)) == 0;
}

uint64_t round_up(uint64_t value, uint64_t multiple) {
    if (is_pow2(multiple))
        return (value + multiple - 1) & ~(multiple - 1);
    else
        return ((value + multiple - 1) / multiple) * multiple;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Hash table for key uniqueness check
typedef struct hash_node {
    int key;
    struct hash_node* next;
} hash_node;

#define HASH_TABLE_SIZE 65536

hash_node* hash_table[HASH_TABLE_SIZE];

unsigned int hash_function(int key) {
    return key & (HASH_TABLE_SIZE - 1);
}

int hash_insert(int key) {
    unsigned int index = hash_function(key);
    for (hash_node* node = hash_table[index]; node != NULL; node = node->next) {
        if (node->key == key)
            return 0;
    }
    hash_node* new_node = align_alloc(sizeof(hash_node), ALIGNMENT);
    if (!new_node)
        return 0;

    new_node->key = key;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
    return 1;
}

void free_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_node* node = hash_table[i];
        while (node != NULL) {
            hash_node* next = node->next;
            free(node);
            node = next;
        }
    }
}

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t count;
} file_index;

file_index* initialize_file_index(size_t num_records) {
    size_t available_memory = get_available_memory();
    size_t max_memory_usage = available_memory * MEMORY_LIMIT_PERCENTAGE;
    size_t offsets_size = (num_records / 2) * sizeof(long);
    size_t keys_size = num_records * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    if (offsets_size + keys_size + records_size > max_memory_usage) {
        log_error("Memory usage exceeds limit");
        return NULL;
    }

    file_index* index = align_alloc(sizeof(file_index), ALIGNMENT);
    if (!index) {
        log_error("Failed to allocate memory for file_index");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));

    index->offsets = align_alloc(offsets_size, ALIGNMENT);
    if (!index->offsets) {
        log_error("Failed to allocate memory for offsets");
        free(index);
        return NULL;
    }

    index->keys = align_alloc(keys_size, ALIGNMENT);
    if (!index->keys) {
        log_error("Failed to allocate memory for keys");
        free(index->offsets);
        free(index);
        return NULL;
    }

    index->records = align_alloc(records_size, ALIGNMENT);
    if (!index->records) {
        log_error("Failed to allocate memory for records");
        free(index->keys);
        free(index->offsets);
        free(index);
        return NULL;
    }

    memset(hash_table, 0, sizeof(hash_table));

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);

        // Generate random offset
        index->offsets[i] = rand() % 1000000;

        // Calculate key and check uniqueness
        int key = index->offsets[i] & 0xFFFF;
        if (!hash_insert(key)) {
            log_error("Duplicate key found or hash table insertion failed");
            pthread_mutex_unlock(&lock);
            continue; // Handle duplicate key scenario gracefully
        }

        index->keys[i] = key;

        // Generate unique record value
        int random_value = rand() % 1000000;
        if (__builtin_add_overflow(key, random_value, &index->records[i].value)) {
            log_error("Integer overflow occurred during record initialization");
            pthread_mutex_unlock(&lock);
            continue; // Handle overflow scenario gracefully
        }

        pthread_mutex_unlock(&lock);
    }

    index->count = num_records;

    free_hash_table();
    return index;
}

void free_file_index(file_index* index) {
    if (!index)
        return;

    free(index->offsets);
    free(index->keys);
    free(index->records);
    free(index);
}
