    static char log_buffer[LOG_BUFFER_SIZE];
    static size_t log_position = 0;

    size_t message_length = strlen(message);
    if (log_position + message_length >= LOG_BUFFER_SIZE) {
        log_position = 0;
    }
    memcpy(log_buffer + log_position, message, message_length);
    log_position += message_length;
    log_buffer[log_position] = '\n';
}

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (size > 0 && _aligned_malloc != NULL) {
        ptr = _aligned_malloc(size, alignment);
    }
#else
    if (posix_memalign(&ptr, alignment, size) == 0) {
        // Success
    } else {
        ptr = NULL;
    }
#endif
    if (!ptr) {
        log_message("Memory allocation failed.");
    }
    return ptr;
}

void free_aligned(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr); // posix_memalign uses free for deallocation.
#endif
}

int is_power_of_two(size_t x) {
    return (x != 0) && ((x & (x - 1)) == 0);
}

size_t align_up(size_t size, size_t alignment) {
    if (!is_power_of_two(alignment)) {
        log_message("Alignment must be a power of two.");
        exit(EXIT_FAILURE);
    }
    return (size + alignment - 1) & ~(alignment - 1);
}

void check_memory_threshold() {
    if (total_memory_usage > MEMORY_THRESHOLD) {
        // Trigger garbage collection
        log_message("Memory usage exceeded threshold, triggering garbage collection.");
        // For simplicity, assume all memory can be freed.
        total_memory_usage = 0;
    }
}

int verify_range(long* array, size_t size, long min_value, long max_value) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] < min_value || array[i] > max_value) {
            log_message("Offset out of range detected.");
            return -1;
        }
    }
    return 0;
}

int verify_uniqueness(int* keys, size_t size) {
