#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int key;
    float value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* data;
} MemoryManager;

#define ERROR_CODE (-1)

int allocate_memory(MemoryManager** manager, size_t n, size_t m) {
    if (n <= 0 || m <= 0) return ERROR_CODE;

    *manager = malloc(sizeof(MemoryManager));
    if (*manager == NULL) return ERROR_CODE;

    // Allocate memory for arrays
    (*manager)->offsets = malloc(n * sizeof(long));
    (*manager)->keys = malloc(m * sizeof(int));
    (*manager)->data = malloc(n * sizeof(record));

    if ((*manager)->offsets == NULL || 
        (*manager)->keys == NULL ||
        (*manager)->data == NULL) {
        free((*manager)->offsets);
        free((*manager)->keys);
        free((*manager)->data);
        free(*manager);
        return ERROR_CODE;
    }

    // Initialize timestamps and random values
    time_t current_time = time(NULL);

    for (size_t i = 0; i < n; ++i) {
        (*manager)->offsets[i] = current_time + i;
        (*manager)->data[i].timestamp = current_time + i;

        // Ensure unique keys within the limit of m
        if (i < m) {
            (*manager)->keys[i] = i;
        } else {
            break;  // No more unique keys possible within the int range
        }

        // Assign random value between 0.0 and 1.0
        (*manager)->data[i].value = (float)rand() / RAND_MAX;
    }

    return 0;  // Success
}

void cleanup_memory(MemoryManager* manager) {
    if (manager != NULL) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->data);
        free(manager);
    }
}

MemoryManager* manage_memory(size_t n, size_t m) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);
    MemoryManager* manager = NULL;
    int result = allocate_memory(&manager, n, m);
    pthread_mutex_unlock(&lock);

    if (result == ERROR_CODE && manager != NULL) {
        cleanup_memory(manager);
        return NULL;
    }

    return manager;
}
