// Define constants
#define MAX_NICBS 10000
#define VLAN_ID_MAX 4095

typedef struct {
    uint8_t mac_address[6];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    char eth_mac_address[18]; // Format: XX:XX:XX:XX:XX:XX
    uint16_t vlan_tag;        // VLAN ID + priority bits
    int vlan_priority;
    int ip_header_checksum_enabled;
} NICB;

// Function prototypes for external NMS system
int validate_mac_address(const MAC_HEADER *mac);
void log_error(const char *message);

typedef struct {
    size_t size;
    NICB **array;
    const char **backup_mac_addresses;
    uint32_t seed;
    int (*validate_mac)(const MAC_HEADER *);
} NICB_Init_Params;

// Helper functions
uint16_t generate_vlan_tag(uint32_t seed);
void populate_nicb(NICB *nicb, const char *eth_mac_address, uint32_t vlan_seed, int priority, int checksum_enabled);

// Thread function prototype
void* init_nicb_thread(void *arg);

// Main initialization function
int initialize_nicbs(NICB_Init_Params *params) {
    if (params == NULL || params->size > MAX_NICBS || params->array == NULL || params->validate_mac == NULL) {
        log_error("Invalid input parameters.");
        return -1;
    }

    srand(params->seed);

    NICB **nicb_array = malloc(params->size * sizeof(NICB *));
    if (nicb_array == NULL) {
        log_error("Memory allocation failed for NICB array.");
        return -1;
    }

    pthread_t threads[MAX_NICBS];
    int thread_count = 0;

    for (size_t i = 0; i < params->size; ++i) {
        if (thread_count >= MAX_NICBS / 2 || i % (MAX_NICBS / 10) == 0) { // Adjust to balance threads
            pthread_join(threads[thread_count - 1], NULL);
            thread_count = 0;
        }

        NICB_Init_Params *thread_params = malloc(sizeof(NICB_Init_Params));
        if (thread_params == NULL) {
            log_error("Memory allocation failed for thread parameters.");
            free(nicb_array);
            return -1;
        }
        memcpy(thread_params, params, sizeof(NICB_Init_Params));

        thread_params->array = &nicb_array[i];
        pthread_create(&threads[thread_count], NULL, init_nicb_thread, (void *)thread_params);
        thread_count++;
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    *params->array = nicb_array;
    return 0;
}

// Thread function to initialize a single NICB
void* init_nicb_thread(void *arg) {
    NICB_Init_Params *params = (NICB_Init_Params *)arg;
    NICB **nicb_ptr = params->array;

    for (int j = 0; j < strlen(params->backup_mac_addresses[0]); ++j) { // Loop through backup addresses if needed
        MAC_HEADER mac_header;
        strncpy((char *)mac_header.mac_address, params->backup_mac_addresses[j], 17);

        if (params->validate_mac(&mac_header)) {
            *nicb_ptr = malloc(sizeof(NICB));
            if (*nicb_ptr == NULL) {
                log_error("Memory allocation failed for NICB.");
                return NULL;
            }
            populate_nicb(*nicb_ptr, params->backup_mac_addresses[j], params->seed, params->vlan_priority, params->ip_header_checksum_enabled);
        } else {
            log_error("Invalid MAC address encountered.");
        }
    }

    free(params); // Free thread-specific parameters
    return NULL;
}

// Populate a single NICB structure
void populate_nicb(NICB *nicb, const char *eth_mac_address, uint32_t vlan_seed, int priority, int checksum_enabled) {
    strncpy(nicb->eth_mac_address, eth_mac_address, 17);
    nicb->vlan_tag = (priority << 13) | generate_vlan_tag(vlan_seed); // Set VLAN ID and priority
    nicb->vlan_priority = priority;
    nicb->ip_header_checksum_enabled = checksum_enabled;
}

// Generate a random VLAN tag based on seed
uint16_t generate_vlan_tag(uint32_t seed) {
    srand(seed);
    return rand() % (VLAN_ID_MAX + 1); // Ensure VLAN ID is within valid range
}
