    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));

    if (!*records || !offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        free(*records);
        free(offsets);
        free(keys);
        return -1;
