#define INSUFFICIENT_RESOURCES -1

typedef struct {
    long timestamp;
    int key;
    float value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
} data_manager_t;

int generate_unique_keys(int *keys, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        keys[i] = i;
    }
    return 0; // No errors
}

int allocate_and_initialize_data_manager(size_t n, size_t m, long memory_limit, int reduce_on_exceed, data_manager_t **manager) {
    if (n == 0 || m == 0 || memory_limit <= 0 || manager == NULL) {
        return INSUFFICIENT_RESOURCES;
    }

    // Calculate total memory required
    size_t offset_size = n * sizeof(long);
    size_t key_size = n * sizeof(int);
    size_t record_size = n * sizeof(record);

    if (offset_size + key_size + record_size > memory_limit) {
        fprintf(stderr, "Warning: Memory usage exceeds the limit.\n");
        return reduce_on_exceed ? 0 : INSUFFICIENT_RESOURCES;
    }

    // Allocate memory
    long *offsets = (long *)malloc(offset_size);
    int *keys = (int *)malloc(key_size);
    record *records = (record *)malloc(record_size);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets); // Free what was allocated
        free(keys);
        free(records);
        return INSUFFICIENT_RESOURCES;
    }

    // Initialize offsets and records
    time_t current_time = time(NULL);
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = (long)(current_time + i); // Simple initialization with incremental offset

        if (generate_unique_keys(keys, n) != 0) {
            fprintf(stderr, "Error: Key generation failed.\n");
            free(offsets);
            free(keys);
            free(records);
            return INSUFFICIENT_RESOURCES;
        }

        records[i].timestamp = offsets[i];
        records[i].key = keys[i];
        records[i].value = (float)(rand() / (RAND_MAX + 1.0)); // Random float [0, 1)
    }

    *manager = malloc(sizeof(data_manager_t));
    if (!*manager) {
        fprintf(stderr, "Error: Failed to allocate memory for data manager.\n");
        free(offsets);
        free(keys);
        free(records);
        return INSUFFICIENT_RESOURCES;
    }

    (*manager)->offsets = offsets;
    (*manager)->keys = keys;
    (*manager)->records = records;

    return 0; // Success
}

void serialize_data_manager(const data_manager_t *manager, const char *filename) {
    if (!manager || !filename) {
        fprintf(stderr, "Error: Invalid arguments for serialization.\n");
        return;
    }

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    size_t n = (size_t)(manager->records - manager->keys) / sizeof(record); // Calculate number of records
    fwrite(manager->offsets, sizeof(long), n, file);
    fwrite(manager->keys, sizeof(int), n, file);
    fwrite(manager->records, sizeof(record), n, file);

    if (ferror(file)) {
        perror("Failed to write data to file");
    }

    fclose(file);
}

void free_data_manager(data_manager_t *manager) {
    if (!manager) return;

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}
