    // Populate each MMU structure
    for (size_t i = 0; i < array_size; ++i) {
        (*mmu_array)[i].page_table = malloc(entry_count * sizeof(PTE));
        if ((*mmu_array)[i].page_table == NULL) {
            fprintf(stderr, "Memory allocation failed for page table.\n");
            // Free previously allocated memory
            while (i > 0) {
                free((*mmu_array)[--i].page_table);
            }
            free(*mmu_array);
            *mmu_array = NULL;
            return;
        }

        (*mmu_array)[i].num_entries = entry_count;
        (*mmu_array)[i].virtual_memory_base = (void *)((unsigned long)physical_memory_block + i * block_size);

        for (size_t j = 0; j < entry_count; ++j) {
            PTE *pte = &((*mmu_array)[i].page_table[j]);
            pte->physical_address = ((unsigned long)physical_memory_block + i * block_size + j * sizeof(PTE));
            pte->protection_flags = policy.enable_protection ? 1 : 0; // Example flag
            pte->valid_bit = 1;

            if (policy.alignment > 0) {
                // Ensure physical address is aligned
                unsigned long aligned_address = ((pte->physical_address + policy.alignment - 1) / policy.alignment) * policy.alignment;
                pte->physical_address = aligned_address;
            }
        }

        // Additional logic for dynamic configuration, monitoring, etc., would be implemented here.
    }

    printf("MMU array initialized successfully.\n");
}

// Example usage
int main() {
    MMU_Structure *mmu_array;
    Allocation_Policy policy = {1, 4096}; // Enable protection and set alignment to 4KB

    initialize_mmu_array(&mmu_array, 10, 100, malloc(1024 * 1024), 1024 * 64, policy, BATCH_MODE);

    if (mmu_array) {
        free(mmu_array);
    }

    return 0;
}
