#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <inttypes.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    long timestamp;
    int key;
    float value;
} Record;

// Error codes
#define SUCCESS 0
#define ERROR_INSUFFICIENT_MEMORY -1
#define ERROR_INVALID_INPUT -2

// Mutex for thread safety
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize records
int manage_memory(size_t n, size_t m) {
    if (n == 0 || m > INT_MAX) {
        return ERROR_INVALID_INPUT;
    }

    // Allocate memory for arrays
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    pthread_mutex_lock(&memory_lock);

    offsets = malloc(n * sizeof(long));
    if (!offsets) {
        pthread_mutex_unlock(&memory_lock);
        return ERROR_INSUFFICIENT_MEMORY;
    }

    keys = malloc(m * sizeof(int));
    if (!keys) {
        free(offsets);
        pthread_mutex_unlock(&memory_lock);
        return ERROR_INSUFFICIENT_MEMORY;
    }

    records = calloc(n, sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&memory_lock);
        return ERROR_INSUFFICIENT_MEMORY;
    }

    // Initialize timestamps
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    for (size_t i = 0; i < n; ++i) {
        records[i].timestamp = ts.tv_sec + (ts.tv_nsec / 1e9);
        if (i < m) {
            keys[i] = (int)i;
        }
    }

    // Assign random values
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < n; ++i) {
        records[i].value = ((float)rand() / RAND_MAX);
    }

    pthread_mutex_unlock(&memory_lock);

    // Cleanup routine function
    void cleanup(void **offsets, void **keys, void **records) {
        pthread_mutex_lock(&memory_lock);

        if (*offsets) free(*offsets);
        if (*keys) free(*keys);
        if (*records) free(*records);

        *offsets = NULL;
        *keys = NULL;
        *records = NULL;

        pthread_mutex_unlock(&memory_lock);
    }

    return SUCCESS;
}

// Example usage
int main() {
    size_t n = 1000; // Number of records
    size_t m = 1000; // Range for unique keys

    int result = manage_memory(n, m);

    if (result == SUCCESS) {
        printf("Memory managed successfully.\n");
    } else {
        fprintf(stderr, "Error: %d\n", result);
    }

    return result;
}
```

