import java.nio.channels.SocketChannel;
import java.net.InetSocketAddress;
import java.io.IOException;

public class RemoteConnectionManager {

    private static final int TIMEOUT_MS = 5000; // Timeout for connection attempts

    public void connectToRemote(String address) {
        SocketChannel channel = null;

        try {
            channel = SocketChannel.open();
            channel.configureBlocking(false);
            boolean connected = channel.connect(new InetSocketAddress(address, 8080)).isDone();

            if (!connected) {
                long start = System.currentTimeMillis();
                while (channel.finishConnect() == false) {
                    if ((System.currentTimeMillis() - start) > TIMEOUT_MS) {
                        throw new IOException("Connection attempt timed out");
                    }
                }
            }

            // Simulate message sending on connection close
            channel.close(); 
            sendMessageOnClose();

        } catch (IOException e) {
            System.err.println("Failed to connect: " + e.getMessage());
        } finally {
            if (channel != null) {
                try {
                    channel.close();
                } catch (IOException e) {
                    // Ignore IOException on close
                }
            }
        }
    }

    private void sendMessageOnClose() {
        System.out.println("Connection closed, sending message to messaging system.");
    }
}
