<?php

function authenticateUser($clientId, $clientSecret, $authUrl, $redirectUri) {
    session_start();

    if (!isset($_GET['code'])) {
        // Generate authorization URL
        $params = [
            'response_type' => 'code',
            'client_id' => $clientId,
            'redirect_uri' => $redirectUri,
            'scope' => '',
            'state' => ''
        ];

        $authUrlWithParams = $authUrl . '?' . http_build_query($params);
        header("Location: " . $authUrlWithParams);
        exit;
    } else {
        // Exchange authorization code for access token
        $code = $_GET['code'];
        $tokenUrl = "$authUrl/token";

        $data = [
            'grant_type' => 'authorization_code',
            'client_id' => $clientId,
            'client_secret' => $clientSecret,
            'redirect_uri' => $redirectUri,
            'code' => $code
        ];

        $options = [
            'http' => [
                'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                'method'  => 'POST',
                'content' => http_build_query($data),
            ]
        ];

        $context  = stream_context_create($options);
        $result = file_get_contents($tokenUrl, false, $context);

        if ($result === FALSE) {
            die('Error obtaining access token');
        }

        $response = json_decode($result);

        // Store the access token in a session variable
        $_SESSION['access_token'] = $response->access_token;

        // Retrieve user information
        $userInfoUrl = "$authUrl/userinfo";

        $options = [
            'http' => [
                'header'  => "Authorization: Bearer {$_SESSION['access_token']}\r\n",
                'method'  => 'GET',
            ]
        ];

        $context  = stream_context_create($options);
        $userInfoResult = file_get_contents($userInfoUrl, false, $context);

        if ($userInfoResult === FALSE) {
            die('Error retrieving user information');
        }

        return json_decode($userInfoResult);
    }
}
