['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define MAX_VALUES_PER_ENTRY 50
#define ALIGNMENT 128

typedef struct Value {
    double numeric;
    char *str;
    union {
        long int_val;
        struct Value *ptr_value;
    } metadata;
} Value;

typedef struct Record {
    time_t timestamp;
    char identifier[20];
    union {
        double distribution_val;
        float skewed_val;
    } metadata;
} Record;

typedef struct EntryNode {
    char *key;
    time_t timestamp;
    int status;
    Value *values;
    size_t value_count;
    Record *records;
    size_t record_count;
    struct EntryNode *left, *right;
} EntryNode;

typedef struct BalancedBSTree {
    EntryNode *root;
    pthread_mutex_t lock;
} BalancedBSTree;

BalancedBSTree tree = {NULL, PTHREAD_MUTEX_INITIALIZER};

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || defined(__APPLE__)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#elif defined(__unix__) || defined(__APPLE__)
    free(ptr);
#endif
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int is_power_of_two(size_t x) {
    return (x != 0) && ((x & (x - 1)) == 0);
}

size_t align_size_up(size_t size, size_t alignment) {
    if (!is_power_of_two(alignment)) {
        log_error("Alignment must be a power of two.");
        exit(EXIT_FAILURE);
    }
    return (size + alignment - 1) & ~(alignment - 1);
}

int add_entry(BalancedBSTree *tree, const char* key, EntryNode **new_node);

void insert_value(EntryNode *entry, double numeric_val, const char *str, long int metadata_long) {
    entry->values = realloc(entry->values, sizeof(Value) * (entry->value_count + 1));
    if (!entry->values) {
        log_error("Failed to allocate memory for value.");
        return;
    }

    Value *value = &entry->values[entry->value_count++];
    value->numeric = numeric_val;
    size_t str_len = strlen(str);
    value->str = aligned_alloc(ALIGNMENT, sizeof(char) * (str_len + 1));
    if (!value->str) {
        log_error("Failed to allocate memory for string.");
        free(entry->values);
        entry->values = NULL;
        return;
    }
    strcpy(value->str, str);

    value->metadata.int_val = metadata_long;

    // Calculate weighted average
    double sum = 0.0;
    for (size_t i = 0; i < entry->value_count; ++i) {
        sum += entry->values[i].numeric;
    }
    if (entry->value_count > 1) {
        value->numeric = round(sum / entry->value_count * pow(10, 5)) / pow(10, 5);
    }
}

void insert_record(EntryNode *entry) {
    time_t now = time(NULL);
    Record new_record;
    new_record.timestamp = now;

    // Generate unique alphanumeric identifier
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t len = strlen(charset);
    for (size_t i = 0; i < sizeof(new_record.identifier) - 1; ++i) {
        int index = rand() % len;
        new_record.identifier[i] = charset[index];
    }
    new_record.identifier[sizeof(new_record.identifier) - 1] = '\0';

    entry->records = realloc(entry->records, sizeof(Record) * (entry->record_count + 1));
    if (!entry->records) {
        log_error("Failed to allocate memory for record.");
        return;
    }

    // Check uniqueness
    for (size_t i = 0; i < entry->record_count; ++i) {
        if (strcmp(entry->records[i].identifier, new_record.identifier) == 0) {
            insert_record(entry); // Retry with a different identifier
            return;
        }
    }

    new_record.metadata.distribution_val = rand() % 100 / 100.0;

    entry->records[entry->record_count++] = new_record;
}

int add_entry(BalancedBSTree *tree, const char* key, EntryNode **new_node) {
    pthread_mutex_lock(&tree->lock);

    // Create a new entry node
    if (strlen(key) >= 256) { // Assuming max key length is 255
        log_error("Key too long.");
        return -1;
    }
    *new_node = aligned_alloc(ALIGNMENT, sizeof(EntryNode));
    if (!*new_node) {
        pthread_mutex_unlock(&tree->lock);
        log_error("Failed to allocate memory for entry node.");
        return -1;
    }

    (*new_node)->key = strdup(key);
    (*new_node)->timestamp = time(NULL);
    (*new_node)->status = 0;
    (*new_node)->values = NULL;
    (*new_node)->value_count = 0;
    (*new_node)->records = NULL;
    (*new_node)->record_count = 0;
    (*new_node)->left = (*new_node)->right = NULL;

    // Insert node into balanced BST
    EntryNode **current = &tree->root;
    while (*current) {
        int cmp = strcmp((*current)->key, key);
        if (cmp < 0) {
            current = &(*current)->right;
        } else if (cmp > 0) {
            current = &(*current)->left;
        } else {
            pthread_mutex_unlock(&tree->lock);
            log_error("Duplicate entry key.");
            return -1; // Duplicate key
        }
    }

    *current = *new_node;
    pthread_mutex_unlock(&tree->lock);
    return 0;
}

void populate_entry(EntryNode *entry) {
    for (size_t i = 0; i < MAX_VALUES_PER_ENTRY; ++i) {
        char str[50];
        snprintf(str, sizeof(str), "Value %zu", i + 1);
        insert_value(entry, rand() % 100 / 10.0, str, rand());
    }

    for (size_t i = 0; i < MAX_ENTRIES / 10; ++i) {
        insert_record(entry);
    }
}

int verify_data_integrity(EntryNode *entry) {
    if (!entry->records) return 1;

    for (size_t i = 0; i < entry->record_count; ++i) {
        for (size_t j = i + 1; j < entry->record_count; ++j) {
            if (strcmp(entry->records[i].identifier, entry->records[j].identifier) == 0) {
                log_error("Duplicate record identifier found.");
                return 0;
            }
        }
    }

    return 1;
}

void traverse_and_populate(BalancedBSTree *tree) {
    pthread_mutex_lock(&tree->lock);

    void recursive_traverse(EntryNode *node) {
        if (!node) return;

        populate_entry(node);
        recursive_traverse(node->left);
        recursive_traverse(node->right);
    }

    recursive_traverse(tree->root);

    pthread_mutex_unlock(&tree->lock);
}

int main() {
    srand(time(NULL));

    EntryNode *new_node = NULL;
    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        char key[10];
        snprintf(key, sizeof(key), "Key%zu", i + 1);

        if (add_entry(&tree, key, &new_node)) {
            log_error("Failed to add entry.");
            return EXIT_FAILURE;
        }
    }

    traverse_and_populate(&tree);

    // Verify integrity
    void verify_recursive(EntryNode *node) {
        if (!node) return;

        if (!verify_data_integrity(node)) {
            log_error("Data integrity check failed.");
            exit(EXIT_FAILURE);
        }

        verify_recursive(node->left);
        verify_recursive(node->right);
    }

    verify_recursive(tree.root);

    printf("All entries populated and verified successfully.\n");

    // Cleanup
    void free_tree(EntryNode *node) {
        if (!node) return;

        for (size_t i = 0; i < node->value_count; ++i) {
            free_aligned(node->values[i].str);
        }
        free(node->values);
        free(node->records);
        free(node->key);

        free_tree(node->left);
        free_tree(node->right);

        free_aligned(node);
    }

    pthread_mutex_lock(&tree.lock);
    free_tree(tree.root);
    tree.root = NULL;
    pthread_mutex_unlock(&tree.lock);

    return EXIT_SUCCESS;
}
