    size_t capacity = 10;
    Data **dataArray = malloc(capacity * sizeof(Data *));
    if (!dataArray) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        fclose(file);
        return NULL;
    }

    *numEntries = 0;

    while (fgets(buffer, bufferSize, file)) {
        // Reallocate more space if necessary
        if (*numEntries >= capacity) {
            capacity *= 2;
            Data **newArray = realloc(dataArray, capacity * sizeof(Data *));
            if (!newArray) {
                fprintf(stderr, "Error: Memory reallocation failed\n");
                fclose(file);

                // Free previously allocated memory
                for (size_t i = 0; i < *numEntries; ++i) {
                    free(dataArray[i]);
                }
                free(dataArray);
                return NULL;
            }
            dataArray = newArray;
        }

        Data *data = malloc(sizeof(Data));
        if (!data) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            fclose(file);

            // Free previously allocated memory
            for (size_t i = 0; i < *numEntries; ++i) {
                free(dataArray[i]);
            }
            free(dataArray);
            return NULL;
        }

        if (sscanf(buffer, "%d %lf %c", &data->intValue, &data->doubleValue, &data->charValue) == 3) {
            dataArray[*numEntries] = data;
            (*numEntries)++;
        } else {
            fprintf(stderr, "Warning: Incomplete or invalid line encountered\n");
            free(data);
        }
    }

    fclose(file);

    return dataArray;
}

// Function to free the allocated memory for data structures
void freeDataArray(Data **dataArray, size_t numEntries) {
    if (!dataArray) return;

    for (size_t i = 0; i < numEntries; ++i) {
        free(dataArray[i]);
    }
    free(dataArray);
}

int main() {
    const char *filename = "data.txt";
    size_t numEntries;

    Data **dataArray = readDataFromFile(filename, &numEntries);

    if (dataArray) {
        // Use the data as needed...

        // Free allocated memory
        freeDataArray(dataArray, numEntries);
    }

