        strcpy(records[i].hexStringPtr, records[i].hexBuffer);

        free(records[i].hexBuffer); // Free placeholder
    }
    return 0;
}

int allocateAndInitialize(long numOffsets, int numKeys, size_t numRecords, int rangeMin, int rangeMax, long **offsetArray, int **keysArray, record ***recordsArray) {
    if (numOffsets <= 0 || numKeys <= 0 || numRecords <= 0) return -1;

    srand(time(NULL)); // Seed random number generator

    *offsetArray = malloc(numOffsets * sizeof(long));
    if (!*offsetArray) return -1;

    *keysArray = malloc(numKeys * sizeof(int));
    if (!*keysArray) {
        free(*offsetArray);
        return -1;
    }

    *recordsArray = malloc(numRecords * sizeof(record *));
    if (!*recordsArray) {
        free(*offsetArray);
        free(*keysArray);
        return -1;
    }

    for (size_t i = 0; i < numOffsets; ++i) {
        (*offsetArray)[i] = rand() % 1000000; // Example offset
    }

    for (int i = 0; i < numKeys; ++i) {
        (*keysArray)[i] = i + 1; // Example keys
    }

    *recordsArray = malloc(numRecords * sizeof(record));
    if (!*recordsArray[0]) {
        free(*offsetArray);
        free(*keysArray);
        free(*recordsArray);
        return -1;
    }

    int status = initializeRecords(*recordsArray, *offsetArray, *keysArray, numRecords, rangeMin, rangeMax);

    if (status != 0) {
        for (size_t i = 0; i < numRecords; ++i) {
            free((*recordsArray)[i].hexStringPtr);
        }
        free(*recordsArray);
        free(*offsetArray);
        free(*keysArray);
        return -1;
    }

    return 0;
}

void cleanup(long *offsetArray, int *keysArray, record **recordsArray, size_t numRecords) {
    if (offsetArray) free(offsetArray);
    if (keysArray) free(keysArray);

    for (size_t i = 0; i < numRecords; ++i) {
        if ((*recordsArray)[i].hexStringPtr) {
            free((*recordsArray)[i].hexStringPtr);
        }
    }

    if (*recordsArray) {
        free(*recordsArray);
        *recordsArray = NULL;
    }
}

