typedef struct {
    size_t size;
    union {
        double d_value;
        char *str_value;
    } data;
} item;

typedef struct {
    int key;
    char string[256];
    item* item_ptr;
    time_t timestamp;
} record;

#define MAX_RECORDS 1000
#define MEMORY_LIMIT (1024 * 1024) // 1 MB

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t current_memory_usage = 0;

void free_least_recently_used(record **records, int *count);
int log_memory_adjustment();

record* initialize_records(int count, int key_min, int key_max, const char* config) {
    record *records = malloc(count * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < count; ++i) {
        records[i].key = key_min + rand() % (key_max - key_min + 1);
        snprintf(records[i].string, sizeof(records[i].string), "%d-%ld-%s", i, time(NULL), config);

        item *it = malloc(sizeof(item));
        if (!it) {
            perror("Memory allocation failed for item");
            free_least_recently_used(&records, &count);
            continue;
        }

        it->size = rand() % 100; // Example size

        char *str_value = malloc(256); // Example string allocation
        if (str_value) {
            snprintf(str_value, 256, "Item for record %d", i);
            it->data.str_value = str_value;
        } else {
            it->data.d_value = rand() / (double)RAND_MAX; // Fallback to double
        }

        records[i].item_ptr = it;
        records[i].timestamp = time(NULL);

        pthread_mutex_lock(&mutex);
        current_memory_usage += sizeof(record) + sizeof(item) + 256; // Estimate memory usage
        if (current_memory_usage > MEMORY_LIMIT) {
            free_least_recently_used(&records, &count);
        }
        pthread_mutex_unlock(&mutex);
    }

    return records;
}

void free_least_recently_used(record **records, int *count) {
    if (!*records || !*count) return;

    // For simplicity, assume the first record is LRU
    item *item_to_free = (*records)[0].item_ptr;
    if (item_to_free->data.str_value) {
        free(item_to_free->data.str_value);
    }
    free(item_to_free);

    for (int i = 1; i < *count; ++i) {
        (*records)[i - 1] = (*records)[i];
    }

    --(*count);
    pthread_mutex_lock(&mutex);
    current_memory_usage -= sizeof(record) + sizeof(item) + 256;
    if (log_memory_adjustment()) {
        printf("Memory adjusted, new usage: %zu\n", current_memory_usage);
    }
    pthread_mutex_unlock(&mutex);
}

int log_memory_adjustment() {
    // Placeholder for logging logic
    return 1; // Assume successful logging
}
