import java.io.IOException;
import java.nio.channels.SocketChannel;
import java.net.InetSocketAddress;

public class ConnectionManager {

    private static final int RETRY_LIMIT = 3;
    private static final long TIMEOUT_MS = 5000;

    public SocketChannel establishConnection(String host, int port) {
        for (int attempt = 1; attempt <= RETRY_LIMIT; attempt++) {
            try (SocketChannel channel = SocketChannel.open()) {
                channel.configureBlocking(false);
                if (channel.connect(new InetSocketAddress(host, port)).isValid() ||
                        channel.finishConnect()) {

                    System.out.println("Connected to " + host + ":" + port);
                    return channel;
                }

                Thread.sleep(TIMEOUT_MS); // Wait before retry
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
                if (attempt == RETRY_LIMIT) {
                    System.err.println("Failed to establish connection after " + attempt + " attempts.");
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        SocketChannel channel = manager.establishConnection("example.com", 8080);

        if (channel != null) {
            try {
                // Use the connection
            } finally {
                channel.close(); // Ensure resources are released
            }
        }
    }
}
