#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_DEFINITIONS 10000

typedef struct {
    int minValue;
    int maxValue;
    double minDoubleValue;
    double maxDoubleValue;
} ResourceDef;

typedef struct {
    int intValue;
    double doubleValue;
    char charValue;
} StructData;

typedef struct {
    int key;
    long offset;
    StructData *dataPtr;
    pthread_mutex_t mutex; // Mutex for synchronizing access to this resource
} Resource;

typedef struct {
    ResourceDef definitions[MAX_DEFINITIONS];
    size_t count;
    pthread_mutex_t globalMutex; // Global mutex for managing overall structure
} ResourceManager;

// Function prototypes
void initializeResourceManager(ResourceManager *manager);
int loadDefinitionsFromFile(ResourceManager *manager, const char *filename);
double generateRandomDouble(double min, double max, int inclusive);
long generateRandomLong(long min, long max, int inclusive);
void mergeOverlappingResources(ResourceManager *manager);
void splitResource(Resource *resource, ResourceDef criteria, ResourceManager *newManager);
int dynamicUpdate(ResourceManager *manager, const char *filename);

// Initialize the resource manager
void initializeResourceManager(ResourceManager *manager) {
    pthread_mutex_init(&manager->globalMutex, NULL);
    manager->count = 0;
}

// Load definitions from file
int loadDefinitionsFromFile(ResourceManager *manager, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    pthread_mutex_lock(&manager->globalMutex);

    for (size_t i = 0; i < MAX_DEFINITIONS && fscanf(file, "%d %d %lf %lf",
        &manager->definitions[i].minValue,
        &manager->definitions[i].maxValue,
        &manager->definitions[i].minDoubleValue,
        &manager->definitions[i].maxDoubleValue) == 4;) {

        manager->count++;
        if (manager->count >= MAX_DEFINITIONS) break;
    }

    pthread_mutex_unlock(&manager->globalMutex);
    fclose(file);

    return 0;
}

// Generate a random double
double generateRandomDouble(double min, double max, int inclusive) {
    double result = ((double) rand() / RAND_MAX) * (max - min) + min;
    if (!inclusive && result == max) --result; // Exclude upper bound if not inclusive
    return result;
}

// Generate a random long
long generateRandomLong(long min, long max, int inclusive) {
    long range = max - min + 1;
    long result = rand() % range + min;
    if (!inclusive && result == max) --result; // Exclude upper bound if not inclusive
    return result;
}

// Merge overlapping resources into contiguous blocks
void mergeOverlappingResources(ResourceManager *manager) {
    pthread_mutex_lock(&manager->globalMutex);

    for (size_t i = 0; i < manager->count - 1; ++i) {
        ResourceDef *current = &manager->definitions[i];
        for (size_t j = i + 1; j < manager->count;) {
            ResourceDef *next = &manager->definitions[j];

            if ((current->minValue <= next->maxValue && current->maxValue >= next->minValue) ||
                (current->minDoubleValue <= next->maxDoubleValue &&
                 current->maxDoubleValue >= next->minDoubleValue)) {

                // Merge resources
                current->maxValue = current->maxValue > next->maxValue ? current->maxValue : next->maxValue;
                current->maxDoubleValue = current->maxDoubleValue > next->maxDoubleValue ? current->maxDoubleValue : next->maxDoubleValue;

                for (size_t k = j; k < manager->count - 1; ++k) {
                    manager->definitions[k] = manager->definitions[k + 1];
                }
                --manager->count;
            } else {
                ++j;
            }
        }
    }

    pthread_mutex_unlock(&manager->globalMutex);
}

// Split a resource based on given criteria
void splitResource(Resource *resource, ResourceDef criteria, ResourceManager *newManager) {
    // Implementation to be done by developer
    // This function should create new resources in `newManager` based on the splitting logic.
}

// Dynamic update of resources from file
int dynamicUpdate(ResourceManager *manager, const char *filename) {
    pthread_mutex_lock(&manager->globalMutex);

    if (loadDefinitionsFromFile(manager, filename) != 0) {
        pthread_mutex_unlock(&manager->globalMutex);
        return -1;
    }

    mergeOverlappingResources(manager); // Optionally called to handle new definitions

    pthread_mutex_unlock(&manager->globalMutex);
    return 0;
}

// Memory management and cleanup
void freeResourceManager(ResourceManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->definitions[i].dataPtr != NULL) {
            free(manager->definitions[i].dataPtr);
        }
    }

    pthread_mutex_destroy(&manager->globalMutex);
}

int main() {
    ResourceManager manager;
    initializeResourceManager(&manager);

    // Load initial definitions
    if (loadDefinitionsFromFile(&manager, "resource_definitions.txt") != 0) {
        fprintf(stderr, "Error loading resource definitions.\n");
        return EXIT_FAILURE;
    }

    mergeOverlappingResources(&manager);

    // Dynamic updates
    if (dynamicUpdate(&manager, "updated_resource_definitions.txt") != 0) {
        fprintf(stderr, "Error updating resource definitions dynamically.\n");
    }

    freeResourceManager(&manager);
    return EXIT_SUCCESS;
}
``` 

This code provides a starting point for managing resources with specified minimum and maximum values. It includes initialization, dynamic updates from files, merging of overlapping resources, and basic concurrency control using mutexes. The implementation assumes that the resource definitions are read into memory as `ResourceDef` structures, which may include both integer and double value boundaries.']

