    // Implementation for splitting a range into non-overlapping sub-ranges
}

void add_range(int min, int max, int inclusive_min, int inclusive_max) {
    pthread_mutex_lock(&resource_manager.mutex);

    if (resource_manager.count >= MAX_RANGES) {
        fprintf(stderr, "Maximum number of ranges reached.\n");
        pthread_mutex_unlock(&resource_manager.mutex);
        return;
    }

    resource_manager.ranges[resource_manager.count].min = min;
    resource_manager.ranges[resource_manager.count].max = max;
    resource_manager.ranges[resource_manager.count].inclusive_min = inclusive_min;
    resource_manager.ranges[resource_manager.count].inclusive_max = inclusive_max;
    resource_manager.count++;

    merge_ranges(resource_manager.ranges, resource_manager.count);
    pthread_mutex_unlock(&resource_manager.mutex);
}

Record *generate_records(size_t record_count) {
    Record *records = (Record *)malloc(record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_lock(&resource_manager.mutex);

    for (size_t i = 0; i < record_count; ++i) {
        int range_index = rand() % resource_manager.count;
        Range r = resource_manager.ranges[range_index];

        if (r.inclusive_min) {
            records[i].value = random_int(r.min, r.max);
        } else {
            records[i].value = random_int(r.min + 1, r.max - 1);
        }
    }

    pthread_mutex_unlock(&resource_manager.mutex);

    return records;
}

void free_resources() {
    pthread_mutex_lock(&resource_manager.mutex);

    if (resource_manager.ranges) {
        free(resource_manager.ranges);
        resource_manager.ranges = NULL;
    }

    resource_manager.count = 0;

    pthread_mutex_unlock(&resource_manager.mutex);
}

void *thread_safe_generate(void *arg) {
    size_t record_count = *(size_t *)arg;
    Record *records = generate_records(record_count);

    if (records) {
        // Process records
        free(records);
    }

    return NULL;
}

void initialize_resource_manager() {
    resource_manager.ranges = (Range *)malloc(MAX_RANGES * sizeof(Range));
    if (!resource_manager.ranges) {
        perror("Failed to allocate memory for ranges");
        exit(EXIT_FAILURE);
    }

    resource_manager.count = 0;
    pthread_mutex_init(&resource_manager.mutex, NULL);
}

void cleanup_resource_manager() {
    free_resources();
    pthread_mutex_destroy(&resource_manager.mutex);
}

int main() {
    initialize_random();
    initialize_resource_manager();

    // Example usage
    add_range(1, 100, 1, 1); // inclusive [1, 100]

    size_t record_count = 10;
    pthread_t threads[100];
    for (int i = 0; i < 100; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_generate, &record_count);
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_resource_manager();
    return 0;
}
