#include <time.h>
#include <stdalign.h>

#define ALIGNMENT 32
#define ITEM_STRING_LEN 10

typedef struct Item {
    int key;
    char string[ITEM_STRING_LEN];
} Item;

typedef struct Node {
    double value;
    Item *items;
    size_t num_items;
} Node;

Node **allocate_nodes(size_t num_nodes, size_t items_per_node) {
    Node **nodes = (Node **)aligned_alloc(ALIGNMENT, num_nodes * sizeof(Node *));
    if (!nodes) {
        perror("Failed to allocate nodes");
        return NULL;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i] = (Node *)aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Failed to allocate node %zu\n", i);
            while (i > 0) {
                free(nodes[--i]);
            }
            free(nodes);
            return NULL;
        }

        srand(time(NULL) + i); // Seed for randomness
        nodes[i]->value = sqrt(rand() % 100);

        nodes[i]->items = (Item *)aligned_alloc(ALIGNMENT, items_per_node * sizeof(Item));
        if (!nodes[i]->items) {
            fprintf(stderr, "Failed to allocate items for node %zu\n", i);
            free(nodes[i]);
            while (--i >= 0) {
                free(nodes[i]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i]->num_items = items_per_node;
        for (size_t j = 0; j < items_per_node; ++j) {
            nodes[i]->items[j].key = rand() % 10000; // Unique key
            for (int k = 0; k < ITEM_STRING_LEN - 1; ++k) {
