                nodes[i]->items[j].string[k] = random_char;
            }
            nodes[i]->items[j].string[ITEM_STRING_LEN - 1] = '\0';
        }
    }

    return nodes;
}

void free_nodes(Node **nodes, size_t num_nodes) {
