    for (size_t i = 0; i < num_nodes; ++i) {
        if (nodes[i]) {
            free(nodes[i]->items);
            free(nodes[i]);
        }
    }

    free(nodes);
}

// C++ code
#include <iostream>
#include <vector>
#include <unordered_set>
#include <chrono>

struct Record {
    int value;
};

class UnionFind {
public:
    UnionFind(size_t n) : parent(n), rank(n, 0) {
        for (size_t i = 0; i < n; ++i)
            parent[i] = i;
    }

    size_t find(size_t u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unite(size_t u, size_t v) {
        u = find(u);
        v = find(v);

        if (u != v) {
            if (rank[u] < rank[v])
                std::swap(u, v);

            parent[v] = u;
            if (rank[u] == rank[v])
                ++rank[u];
        }
    }

private:
    std::vector<size_t> parent, rank;
};

void manage_arrays(size_t num_offsets, size_t num_keys) {
    long *offsets = new(std::nothrow) long[num_offsets];
    int *keys = new(std::nothrow) int[num_keys];

    if (!offsets || !keys) {
        std::cerr << "Memory allocation failed" << std::endl;
        delete[] offsets;
        delete[] keys;
        return;
    }

    std::unordered_set<int> key_set;

    for (size_t i = 0; i < num_keys; ++i) {
        int random_key = rand() % 10000;
        while (key_set.count(random_key)) {
            random_key = rand() % 10000;
        }
        keys[i] = random_key;
        key_set.insert(random_key);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand();
    }

    Record *records = new(std::nothrow) Record[num_keys];
    if (!records) {
        std::cerr << "Memory allocation failed" << std::endl;
        delete[] offsets;
        delete[] keys;
        return;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        records[i].value = rand() % 100;
    }

    UnionFind uf(num_keys);

    auto start = std::chrono::high_resolution_clock::now();
    for (size_t i = 1; i < num_keys; ++i) {
        uf.unite(keys[0], keys[i]);
    }
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double, std::milli> duration = end - start;
    std::cout << "Union-Find operation took: " << duration.count() << " ms\n";

    delete[] offsets;
    delete[] keys;
    delete[] records;
}

int main() {
    size_t num_nodes = 10, items_per_node = 5;
    Node **nodes = allocate_nodes(num_nodes, items_per_node);
    if (nodes) {
        // Verify and use nodes
        free_nodes(nodes, num_nodes);
    }

    manage_arrays(1000, 500);

    return 0;
}
```

### Explanation:

- The C function `allocate_nodes` allocates memory for an array of `Node` pointers. Each `Node` contains a double value and a linked list of `Item` structures. Memory is aligned to 32 bytes using `aligned_alloc`.

- The function initializes each node's double value with the square root of a random integer and populates items with unique keys and random alphanumeric strings.

- The C++ function `manage_arrays` handles memory allocation for arrays of long offsets and int keys, ensuring no duplicates in keys. It uses a Union-Find data structure to determine disjoint pairs efficiently.

- Both functions include error handling for memory allocation failures and ensure proper cleanup of allocated resources.']

