        if (!nodes[i]) {
            // Free already allocated memory
            for (size_t j = 0; j < i; ++j) {
                free_aligned(nodes[j]);
            }
            free_aligned(nodes);
            return NULL;
        }

        int random_int = rand() % 1000;
