        for (size_t j = 0; j < ITEM_LIST_SIZE; ++j) {
            nodes[i]->items[j] = aligned_alloc(sizeof(item), ALIGNMENT);
            if (!nodes[i]->items[j]) {
                // Free already allocated memory
                free_aligned(nodes[i]);
                for (size_t k = 0; k < i; ++k) {
                    for (size_t l = 0; l < ITEM_LIST_SIZE; ++l) {
                        free_aligned(nodes[k]->items[l]);
                    }
                    free_aligned(nodes[k]);
                }
                free_aligned(nodes);
