void* allocate_and_initialize(int long_offset_count, int int_key_count, int record_value_min, int record_value_max) {
    // Constraints: Memory must be aligned to a 16-byte boundary for performance optimization.
    // Ensure the total allocated memory does not exceed system-defined limits to prevent performance degradation.
    // Implement robust error handling for memory allocation failures and ensure the application can recover gracefully.
    // Design a mechanism to verify the integrity of the allocated data post-initialization.
    // Consider system dependencies and external data sources that may impact memory allocation and data initialization.
    // Ensure that the data initialization process is efficient and does not introduce bottlenecks in high-load scenarios.

    // Calculate total memory required for long offsets, int keys, and records.
    size_t long_offset_size = long_offset_count * sizeof(long);
    size_t int_key_size = int_key_count * sizeof(int);
    size_t record_size = int_key_count * sizeof(Record);
    size_t total_memory = long_offset_size + int_key_size + record_size;

    // Check if the total memory exceeds system-defined limits.
    if (total_memory > INT_MAX) {
        fprintf(stderr, "Total memory required exceeds system limits.\n");
        return NULL;
    }

    // Allocate memory while ensuring alignment to a 16-byte boundary.
    void* aligned_memory = malloc(total_memory);
    if (!aligned_memory) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Align memory to 16-byte boundary.
    char* aligned_ptr = (char*)(((uintptr_t)aligned_memory + 15) & ~15);

    long* long_offsets = (long*)(aligned_ptr);
    aligned_ptr += long_offset_size;

    int* int_keys = (int*)(aligned_ptr);
    aligned_ptr += int_key_size;

    Record* records = (Record*)(aligned_ptr);

