typedef struct {
    int key;
    char string_rep[64];
    Item* item;
} Record;

Record records[MAX_RECORDS];

void init_records(int min_key, int max_key) {
    srand(time(NULL));
    size_t total_memory_used = 0;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        char buffer[64];
        time_t now = time(NULL);
        snprintf(buffer, sizeof(buffer), "ID_%d_%ld", i, now);

        Item* item = malloc(sizeof(Item));
        if (!item) break;

        struct timeval tv;
        gettimeofday(&tv, NULL);
        double time_seconds = tv.tv_sec + (double)tv.tv_usec / 1e6;

        item->size = sizeof(double);
        item->data.d_value = (key + time_seconds) / 2.0;

        records[i].key = key;
        strcpy(records[i].string_rep, buffer);
        records[i].item = item;

        total_memory_used += sizeof(Record) + sizeof(Item);

        if (total_memory_used > MEMORY_LIMIT) {
            free(item);
            records[i] = (Record){0};
            --i; // Retry current index
        }
    }

    // Invoke Java method to connect using JNI
