        inetAddress,
        (jint)8080
    );

    (*env)->CallStaticVoidMethod(env, cls, methodId, inetSocketAddress);

    (*env)->DeleteLocalRef(env, inetSocketAddress);
    (*env)->DeleteLocalRef(env, inetAddress);
    (*env)->DeleteLocalRef(env, cls);

    // Detach current thread from JVM
    (*jvm)->DetachCurrentThread(jvm);
}

