import java.util.concurrent.TimeUnit;

public class Connection {

    public static void establishConnection(InetSocketAddress address) {
        try (SocketChannel channel = SocketChannel.open()) {
            channel.configureBlocking(false);

            int retries = 0;
            while (!channel.finishConnect() && retries < 10) {
                TimeUnit.MILLISECONDS.sleep(100); // Sleep for a short time before retrying
                retries++;
            }

            if (!channel.isConnected()) {
                System.err.println("Failed to connect after retries");
                return;
            }

            // Use the channel here as needed

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
