NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_crc_pdu_array(size_t N, unsigned int seed) {
    if (N == 0) {
        return NULL;
    }

    srand(seed);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        return NULL;
    }

    // Initialize each structure in the array
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1; // Example initialization
        array[i].RNTI = rand(); // Random RNTI
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random tag value within a byte range

        // Set CRCFLAG based on a pseudo-random value
        int random_value = rand();
        if (random_value % 2 == 0) {
            array[i].CRCFLAG = 1;
        } else {
            array[i].CRCFLAG = 0;
        }
    }

    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}

