            if (Unsafe.IsAddressAligned(htmlContent) || !MemoryUsageIsWithinLimits())
            {
                return StatusCode(500, "Memory allocation failed or exceeded limits.");
            }

            // Asynchronously update content using the service class
            await _contentService.UpdateHtmlContentAsync(pageSectionId, elementId, htmlContent);

            // Log success
