#define IP_CHECKSUM_FLAG (1 << 5)
#define RECORDS_COUNT 100
#define INT_RANGE_MIN 0
#define INT_RANGE_MAX 255

typedef struct {
    uint8_t dest[MAC_ADDR_SIZE];
    uint8_t src[MAC_ADDR_SIZE];
    uint16_t vlan_tag;
    uint8_t config_flags;
} MAC_HEADER;

