} NICB;

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    NICB *nicbs;
} AllocatedData;

void align_malloc(size_t size, void **ptr) {
    void *p = NULL;
    if (posix_memalign(&p, ALIGNMENT, size)) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    *ptr = p;
}

int rand_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

void initialize_data(AllocatedData *data) {
