    for (int i = 0; i < NUM_NICB; ++i) {
        data->nicbs[i].mac_header.vlan_tag = rand_range(0, VLAN_TAG_RANGE - 1);
        data->nicbs[i].mac_header.config_flags = rand() & IP_CHECKSUM_FLAG;
    }

    align_malloc(NUM_NICB * sizeof(long), (void **)&data->offsets);
    for (int i = 0; i < NUM_NICB; ++i) {
        data->offsets[i] = rand(); // Random long offset
    }

    align_malloc(NUM_NICB * sizeof(int), (void **)&data->keys);
    for (int i = 0; i < NUM_NICB; ++i) {
        data->keys[i] = rand_range(0, INT_MAX); // Random int key
    }

    align_malloc(RECORDS_COUNT * sizeof(record), (void **)&data->records);
    for (int i = 0; i < RECORDS_COUNT; ++i) {
        data->records[i].value = rand_range(INT_RANGE_MIN, INT_RANGE_MAX);
    }
}

void verify_data_integrity(AllocatedData *data) {
    // Implement basic integrity checks
    if (!data || !data->nicbs || !data->offsets || !data->keys || !data->records) {
        fprintf(stderr, "Data allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < NUM_NICB; ++i) {
        if (data->nicbs[i].mac_header.vlan_tag >= VLAN_TAG_RANGE ||
            data->offsets[i] == 0 || data->keys[i] == 0) {
            fprintf(stderr, "Data integrity check failed\n");
            exit(EXIT_FAILURE);
        }
    }
    for (int i = 0; i < RECORDS_COUNT; ++i) {
        if (data->records[i].value < INT_RANGE_MIN ||
            data->records[i].value > INT_RANGE_MAX) {
            fprintf(stderr, "Data integrity check failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

void free_allocated_data(AllocatedData *data) {
    free(data->nicbs);
    free(data->offsets);
    free(data->keys);
    free(data->records);
}

int main() {
