    size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = n * element_size;

    if (total_memory_required > max_size_bytes) {
        log_message("Exceeded maximum memory limit");
        return NULL;
    }

    uint8_t* aligned_ptr = aligned_alloc(total_memory_required, ALIGNMENT);
    if (!aligned_ptr) {
        log_message("Memory allocation failed due to alignment constraints");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_ptr;

    srand(seed);

    for (size_t i = 0; i < n; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand() & 0xFFFF;

        if (!validate_rnti(pdu_array[i].RNTI)) {
            log_message("Invalid RNTI encountered, using default");
            pdu_array[i].RNTI = DEFAULT_RNTI;
        }

        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return pdu_array;
}

void output_to_file(const NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t n, const char* filename, const char* format) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        log_message("File opening failed");
        return;
    }

    if (strcmp(format, "CSV") == 0) {
        fprintf(file, "RX_UE_INFORMATION_TAG,RNTI,CRCFLAG\n");
        for (size_t i = 0; i < n; ++i) {
            fprintf(file, "%u,%hu,%d\n", pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
    } else if (strcmp(format, "JSON") == 0) {
        fprintf(file, "[\n");
        for (size_t i = 0; i < n; ++i) {
            fprintf(file, "\t{\"RX_UE_INFORMATION_TAG\":%u,\"RNTI\":%hu,\"CRCFLAG\":%d}",
                    pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI, pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
            if (i < n - 1) {
                fprintf(file, ",");
            }
            fprintf(file, "\n");
        }
        fprintf(file, "]\n");
    } else {
        log_message("Unsupported file format");
    }

    fclose(file);
}

int main() {
    size_t n = 10;
    size_t max_size_bytes = 1024; // Example size
    unsigned int seed = 42;

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_crc_indication_pdu_array(n, max_size_bytes, seed);

    if (pdu_array) {
        output_to_file(pdu_array, n, "output.csv", "CSV");
        free_aligned((uint8_t*)pdu_array);
    }

    return 0;
}
