typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    char dns_servers[MAX_DNS_ENTRIES][64];
    int dns_count;
} NetworkConfig;

typedef struct {
    NetworkConfig *configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

static void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

static int is_valid_ip(const char *ip) {
    // Simplified validation for example purposes
    return strlen(ip) < 16 && strchr(ip, '.') != NULL;
}

void initialize_manager(ConfigManager *manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->configs = (NetworkConfig *)aligned_alloc(ALIGNMENT, initial_capacity * sizeof(NetworkConfig));
    if (!manager->configs) {
        perror("Failed to allocate memory for configs");
        exit(EXIT_FAILURE);
    }
}

void free_manager(ConfigManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->configs);
}

NetworkConfig* create_config(ConfigManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkConfig *new_configs = (NetworkConfig *)aligned_alloc(ALIGNMENT, new_capacity * sizeof(NetworkConfig));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->lock);
            perror("Failed to reallocate memory for configs");
            exit(EXIT_FAILURE);
        }
        memcpy(new_configs, manager->configs, manager->count * sizeof(NetworkConfig));
        free(manager->configs);
        manager->configs = new_configs;
        manager->capacity = new_capacity;
    }

    NetworkConfig *config = &manager->configs[manager->count++];
    snprintf(config->ip_address, 16, "192.168.%d.%d", rand() % 256, rand() % 256);
    snprintf(config->subnet_mask, 16, "255.255.255.%d", (rand() % 2 + 1) * 128);
    snprintf(config->gateway, 16, "192.168.0.1");
    config->dns_count = 0;

    pthread_mutex_unlock(&manager->lock);
    return config;
}

void add_dns_server(NetworkConfig *config, const char *dns_ip) {
    if (config->dns_count >= MAX_DNS_ENTRIES || !is_valid_ip(dns_ip)) {
        fprintf(stderr, "Invalid DNS IP or max entries reached\n");
        return;
    }

    strncpy(config->dns_servers[config->dns_count], dns_ip, sizeof(config->dns_servers[0]));
    config->dns_count++;
}

void verify_config_integrity(NetworkConfig *config) {
    if (!is_valid_ip(config->ip_address) || !is_valid_ip(config->subnet_mask)) {
        fprintf(stderr, "Invalid IP configuration\n");
        exit(EXIT_FAILURE);
    }
}
