    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Create threads for parallel initialization
    for (i = 0; i < 4; ++i) {
        thread_status = pthread_create(&threads[i], &attr, initialize_nicb, nicb_array + (NICB_SIZE / 4) * i);
        if (thread_status != 0) {
            log_error("Failed to create threads for NICB initialization.");
            free(nicb_array);
            return -2; // Thread creation failure
        }
    }

    // Wait for all threads to complete
    for (i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_attr_destroy(&attr);

    // Log and report any needed information to NMS (simplified here)
    printf("Network interfaces initialized successfully.\n");

    free(nicb_array); // Free allocated memory
    return 0; // Success
