#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 10000

typedef struct {
    short value;
    char identifier;
    float *data;
} Record;

// Global variables for tracking allocations and thread safety
static size_t total_allocations = 0;
static pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int allocate_memory(size_t num_records, long **offsets, int **keys, Record ***records);
void deallocate_memory(long *offsets, int *keys, Record **records, size_t num_records);
int serialize_state(const char *filename, const long *offsets, const int *keys, const Record *records, size_t num_records);
void log_allocation_event(const char *message);

// Function to allocate memory
int allocate_memory(size_t num_records, long **offsets, int **keys, Record ***records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum allowed.\n");
        return -1;
    }

    pthread_mutex_lock(&allocation_mutex);

    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(Record *));
    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&allocation_mutex);
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if (!(*records)[i]) {
            fprintf(stderr, "Error: Record allocation failed.\n");
            deallocate_memory(*offsets, *keys, *records, i);
            pthread_mutex_unlock(&allocation_mutex);
            return -1;
        }
        (*records)[i]->data = malloc(sizeof(float));
        if (!(*records)[i]->data) {
            fprintf(stderr, "Error: Float allocation failed.\n");
            deallocate_memory(*offsets, *keys, *records, i + 1);
            pthread_mutex_unlock(&allocation_mutex);
            return -1;
        }
    }

    total_allocations += (num_records * 3) + num_records;
    log_allocation_event("Memory allocated for records.");

    pthread_mutex_unlock(&allocation_mutex);
    return 0;
}

// Function to deallocate memory
void deallocate_memory(long *offsets, int *keys, Record **records, size_t num_records) {
    if (!offsets || !keys || !records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]->data);
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    pthread_mutex_lock(&allocation_mutex);
    total_allocations -= (num_records * 3) + num_records;
    pthread_mutex_unlock(&allocation_mutex);
}

// Function to serialize state
int serialize_state(const char *filename, const long *offsets, const int *keys, const Record *records, size_t num_records) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file for serialization.\n");
        return -1;
    }

    fwrite(offsets, sizeof(long), num_records, file);
    fwrite(keys, sizeof(int), num_records, file);

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i]->value, sizeof(short), 1, file);
        fwrite(&records[i]->identifier, sizeof(char), 1, file);
        float *data = records[i]->data;
        fwrite(data, sizeof(float), 1, file);
    }

    fclose(file);
    return 0;
}

// Function to log allocation events
void log_allocation_event(const char *message) {
    // Integrate with existing logging framework here
    printf("Log: %s\n", message);  // Placeholder for actual logging
}
