    if (*allocated_records > 0) {
        free((*records)[*allocated_records - 1].item_ptr->data.c_value);
        free((*records)[*allocated_records - 1].item_ptr);
        --(*allocated_records);
        log_event("Released LRU record");
    }
}

void manage_memory(size_t long_int_count, size_t double_count, size_t struct_count, size_t int_key_count, size_t record_count) {
    pthread_mutex_lock(&lock);

    long *long_int_array = (long*) malloc(long_int_count * sizeof(long));
    double *double_array = (double*) malloc(double_count * sizeof(double));
    Record *records = (Record*) calloc(record_count, sizeof(Record));

    size_t total_memory_usage = long_int_count * sizeof(long) + double_count * sizeof(double) +
                                record_count * sizeof(Record);

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (RAND_INT_MAX - RAND_INT_MIN + 1) + RAND_INT_MIN;
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID_%zu_%ld", i, time(NULL));

        Item *item = (Item*) malloc(sizeof(Item));
        total_memory_usage += sizeof(Item);

        item->size = rand() % 100 + 1; // Example size
        char *str = (char *) malloc(item->size);
        memset(str, INIT_CHAR_VALUE, item->size);

        item->data.c_value = str;
        records[i].item_ptr = item;
    }

    while (total_memory_usage > MAX_MEMORY_USAGE) {
        release_lru_record(&records, &record_count);
        total_memory_usage = long_int_count * sizeof(long) + double_count * sizeof(double) +
                             record_count * sizeof(Record);
    }

    // Free allocated resources
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].item_ptr->data.c_value);
        free(records[i].item_ptr);
    }

    free(long_int_array);
    free(double_array);
    free(records);

    pthread_mutex_unlock(&lock);
}

// JNI function to call Java method
void call_java_method() {
    // Simplified placeholder for calling a Java method using JNI
    JNIEnv *env;
    JavaVM *jvm; 
