```java
import java.io.IOException;
import java.nio.channels.SocketChannel;

public class ConnectionManager {

    private static final int INITIAL_BACKOFF = 500; // in milliseconds

    public static void connect() {
        int backoff = INITIAL_BACKOFF;
        boolean connected = false;

        while (!connected) {
            try (SocketChannel channel = SocketChannel.open()) {
                if (channel.connect(new java.net.InetSocketAddress("example.com", 8080)).get(true)) {
                    System.out.println("Connected successfully");
                    connected = true;
                } else {
                    throw new IOException("Failed to connect");
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Connection failed, retrying in " + backoff + "ms: " + e.getMessage());
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                backoff *= 2;
            }
        }
    }

    public static void main(String[] args) {
        connect();
    }
}
```

