int failed_mac_validations = 0;

void initialize_nicbs(NICB **nicb_array, size_t count, const char *backup_macs[], int backup_count) {
    if (count > MAX_NICB_COUNT || nicb_array == NULL) {
        log_message("Invalid input parameters.");
        return;
    }

    // Allocate memory for NICBs
    *nicb_array = malloc(count * sizeof(NICB));
    if (*nicb_array == NULL) {
        log_message("Memory allocation failed.");
        return;
    }

    pthread_t threads[MAX_NICB_COUNT];
    for (size_t i = 0; i < count; ++i) {
        if (pthread_create(&threads[i], NULL, nicb_initializer_thread, (void*)(intptr_t)i) != 0) {
            log_message("Thread creation failed.");
            free_nicbs(nicb_array, count);
            return;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* nicb_initializer_thread(void* arg) {
    size_t index = (size_t)(intptr_t)arg;
    NICB *nicb_array = (NICB**)pthread_getspecific(&lock); // Assume some mechanism to pass this

    char mac_str[18] = "00:11:22:33:44:55"; // Example MAC address
    int retries = 0;
    int valid_mac = validate_mac_with_nms(mac_str);

    while (!valid_mac && retries < MAX_RETRIES) {
        if (retries < backup_count) {
            mac_str = backup_macs[retries];
        } else {
            log_message("All MAC addresses invalid.");
            return NULL;
        }
        valid_mac = validate_mac_with_nms(mac_str);
        retries++;
    }

    if (!valid_mac) {
        pthread_mutex_lock(&lock);
        failed_mac_validations++;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Populate NICB
    MAC_HEADER *mac_header = &nicb_array[index].header;
    memcpy(mac_header->mac_address, mac_str, 6);

    memcpy(nicb_array[index].mac_address, mac_str, 6);

    // Generate VLAN tag
    srand(time(NULL) + index); // Custom seed for deterministic behavior
    nicb_array[index].vlan.vlan_tag = htons(rand() % 4096);
    nicb_array[index].vlan.priority = rand() % 8;
    nicb_array[index].vlan.cfi = 0;

    log_message("NICB initialized successfully.");
    return NULL;
}

void log_message(const char* message) {
    printf("%s\n", message); // Simple logging to console
}

void free_nicbs(NICB** nicb_array, size_t count) {
    if (nicb_array && *nicb_array) {
        free(*nicb_array);
        *nicb_array = NULL;
    }
}
