void *DynamicResourceManagerInit(int initial_semaphore_value, const char *password) {
    sem_t semaphore;
    if (sem_init(&semaphore, 0, initial_semaphore_value) != 0) {
        return NULL;
    }

    ResourceManagerData *data = calloc(1, sizeof(*data));
    if (!data) {
        sem_destroy(&semaphore);
        return NULL;
    }

    data->num_elements = 0;

    // Allocate aligned memory
    posix_memalign((void**)&data->records, ALIGNMENT, MAX_ELEMENTS * sizeof(record));
    posix_memalign((void**)&data->offsets, ALIGNMENT, MAX_ELEMENTS * sizeof(long));
    posix_memalign((void**)&data->keys, ALIGNMENT, MAX_ELEMENTS * sizeof(int));

    if (!data->records || !data->offsets || !data->keys) {
        free(data->records);
        free(data->offsets);
        free(data->keys);
        sem_destroy(&semaphore);
        free(data);
        return NULL;
    }

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        data->records[i].ref_count = 0;
        data->keys[i] = -1;

        if (data->num_elements >= MAX_ELEMENTS && data->num_elements % CHUNK_SIZE == 0) {
            record *new_records = realloc(data->records, (data->num_elements + CHUNK_SIZE) * sizeof(record));
            long *new_offsets = realloc(data->offsets, (data->num_elements + CHUNK_SIZE) * sizeof(long));
            int *new_keys = realloc(data->keys, (data->num_elements + CHUNK_SIZE) * sizeof(int));

            if (!new_records || !new_offsets || !new_keys) {
                break;
            }

            data->records = new_records;
            data->offsets = new_offsets;
            data->keys = new_keys;
        }

        int key;
        do {
            key = rand() % 1000; // Example range
        } while (key >= 0 && data->keys[key] != -1);

        data->records[data->num_elements].value = rand() % 1000; // Example range
        data->records[data->num_elements].key = key;
        data->offsets[data->num_elements] = rand() % 10000; // Example offset range
        data->keys[key] = data->num_elements;

        ++data->num_elements;
    }

    // Verify integrity (example)
    for (size_t i = 0; i < data->num_elements; ++i) {
        if (data->records[i].key != data->keys[data->records[i].value]) {
            sem_destroy(&semaphore);
            free(data->records);
            free(data->offsets);
            free(data->keys);
            free(data);
            return NULL;
        }
    }

    // OpenSSL encryption setup
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        sem_destroy(&semaphore);
        free(data->records);
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, hash, hash) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        sem_destroy(&semaphore);
        free(data->records);
        free(data->offsets);
        free(data->keys);
        free(data);
        return NULL;
    }

    // Simulate server interaction (pseudo-code)
    int fetch_theme_assets() {
        // Simulated network call
        return 1; // Success or failure
    }

    const char *theme_dir = "default_theme";
    if (!fetch_theme_assets()) {
        for (int retries = 0; retries < 5; ++retries) {
            sleep(1 << retries); // Exponential backoff
            if (fetch_theme_assets()) break;
        }
    }

    sem_destroy(&semaphore);
    EVP_CIPHER_CTX_free(ctx);

    return data;
}
