#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include "jpeg2pdf.h"  // Assume this is the third-party library for JPEG to PDF conversion

#define ALIGNMENT 16
#define MAX_CRCFLAG 255
#define NUM_THREADS 4

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRC_INDICATION_REL8_TAG;
        uint8_t CRCFLAG;
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char *input_file;
    char *output_file;
} FilePair;

void *process_files(void *arg);
void adjust_crcflag_range(int system_load);
void log_event(const char *level, const char *message);

// Global variables for dynamic range adjustment
int crcflag_min = 0;
int crcflag_max = MAX_CRCFLAG;
pthread_mutex_t lock;

int main(int argc, char **argv) {
    if (argc < 3 || (argc - 1) % 2 != 0) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> [...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_files = (argc - 1) / 2;
    FilePair *file_pairs = malloc(num_files * sizeof(FilePair));
    if (!file_pairs) {
        perror("Failed to allocate memory for file pairs");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_files; ++i) {
        file_pairs[i].input_file = argv[2 * i + 1];
        file_pairs[i].output_file = argv[2 * i + 2];
    }

    pthread_t threads[NUM_THREADS];
    int files_per_thread = (num_files + NUM_THREADS - 1) / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS && i * files_per_thread < num_files; ++i) {
        int start = i * files_per_thread;
        int end = (i + 1) * files_per_thread;
        if (end > num_files) end = num_files;

        pthread_create(&threads[i], NULL, process_files, file_pairs + start);
    }

    for (int i = 0; i < NUM_THREADS && i * files_per_thread < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(file_pairs);
    return EXIT_SUCCESS;
}

void *process_files(void *arg) {
    FilePair *file_pair = (FilePair *)arg;

    // Allocate aligned memory for NFAPI_CRC_INDICATION_PDU_T
    void *ptr = malloc(ALIGNMENT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        log_event("ERROR", "Memory allocation failed");
        return NULL;
    }
    uintptr_t addr = (uintptr_t)ptr;
    if (addr % ALIGNMENT != 0) {
        ptr = malloc(ALIGNMENT * sizeof(NFAPI_CRC_INDICATION_PDU_T) + ALIGNMENT);
        if (!ptr) {
            log_event("ERROR", "Aligned memory allocation failed");
            free(ptr);
            return NULL;
        }
        addr = (uintptr_t)ptr;
        ptr = (void *)(addr + ALIGNMENT - addr % ALIGNMENT);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)ptr;

    for (int i = 0; i < sizeof(ptr) / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand() & 0xFFFF;
        pthread_mutex_lock(&lock);
        int crcflag = rand() % (crcflag_max - crcflag_min + 1) + crcflag_min;
        pthread_mutex_unlock(&lock);

        if (crcflag < crcflag_min || crcflag > crcflag_max) {
            log_event("ERROR", "CRCFLAG validation failed");
        }

        pdu_array[i].crc_info.CRC_INDICATION_REL8_TAG = rand();
        pdu_array[i].crc_info.CRCFLAG = crcflag;
    }

    // JPEG to PDF conversion
    if (jpeg2pdf_convert(file_pair->input_file, file_pair->output_file) != 0) {
        log_event("ERROR", "JPEG to PDF conversion failed");
    }

    free(ptr);
    return NULL;
}

void adjust_crcflag_range(int system_load) {
    pthread_mutex_lock(&lock);
    if (system_load > 80) { // High load
        crcflag_min = MAX_CRCFLAG / 4;
        crcflag_max = 3 * MAX_CRCFLAG / 4;
    } else { // Normal load
        crcflag_min = 0;
        crcflag_max = MAX_CRCFLAG;
    }
    pthread_mutex_unlock(&lock);
}

void log_event(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}
```

