    size_t array_size = calculate_array_size(max_mem_usage);

    long* offsets = custom_memory_pool_init(array_size * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        offsets[i] = rand() % 100000;
    }

