#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 50000
#define TOTAL_MEMORY_LIMIT (10 * 1024 * 1024)
#define CHUNK_SIZE 1000

typedef struct {
    int value;
    double timestamp;
    char status;
} Record;

typedef struct Node {
    int key;
    Record* record;
    struct Node* next;
} Node;

typedef struct {
    Node** table;
    size_t capacity;
    pthread_mutex_t lock;
} HashTable;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    HashTable hash_table;
    size_t num_records;
    pthread_mutex_t reset_lock;
} DataStructure;

static void* custom_alloc(size_t size) {
    return malloc(size);
}

static void custom_free(void* ptr) {
    free(ptr);
}

static unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

static HashTable* create_hash_table(size_t capacity) {
    HashTable* table = (HashTable*)custom_alloc(sizeof(HashTable));
    table->table = (Node**)custom_alloc(capacity * sizeof(Node*));
    memset(table->table, 0, capacity * sizeof(Node*));
    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

static void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            custom_free(temp);
        }
    }
    custom_free(table->table);
    pthread_mutex_destroy(&table->lock);
    custom_free(table);
}

static Record* allocate_chunk(size_t num_chunks, size_t chunk_size) {
    size_t total_size = num_chunks * CHUNK_SIZE * sizeof(Record);
    return (Record*)custom_alloc(total_size);
}

DataStructure* initialize_data_structure() {
    DataStructure* ds = (DataStructure*)custom_alloc(sizeof(DataStructure));
    pthread_mutex_init(&ds->reset_lock, NULL);

    // Memory calculations
    size_t record_mem_limit = TOTAL_MEMORY_LIMIT - sizeof(DataStructure) * 2;
    size_t max_records = record_mem_limit / sizeof(Record);
    if (max_records > MAX_RECORDS) {
        max_records = MAX_RECORDS;
    }

    size_t num_chunks = (max_records + CHUNK_SIZE - 1) / CHUNK_SIZE;

    // Allocate memory
    ds->offsets = (long*)custom_alloc(max_records * sizeof(long));
    ds->keys = (int*)custom_alloc(max_records * sizeof(int));
    ds->records = allocate_chunk(num_chunks, CHUNK_SIZE);
    ds->num_records = 0;

    size_t hash_capacity = max_records / 10;
    ds->hash_table = *create_hash_table(hash_capacity);

    return ds;
}

void free_data_structure(DataStructure* ds) {
    pthread_mutex_lock(&ds->reset_lock);
    for (size_t i = 0; i < ds->num_records; ++i) {
        unsigned long index = hash(ds->keys[i], ds->hash_table.capacity);
        Node** node_ptr = &ds->hash_table.table[index];

        while (*node_ptr && (*node_ptr)->key != ds->keys[i]) {
            node_ptr = &(*node_ptr)->next;
        }

        if (*node_ptr) {
            Node* temp = *node_ptr;
            *node_ptr = temp->next;
            custom_free(temp);
        }
    }

    free_hash_table(&ds->hash_table);
    custom_free(ds->records);
    custom_free(ds->keys);
    custom_free(ds->offsets);
    pthread_mutex_unlock(&ds->reset_lock);
    pthread_mutex_destroy(&ds->reset_lock);
    custom_free(ds);
}

void reset_data_structure(DataStructure* ds) {
    pthread_mutex_lock(&ds->reset_lock);

    // Free hash table nodes
    for (size_t i = 0; i < ds->hash_table.capacity; ++i) {
        Node* node = ds->hash_table.table[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            custom_free(temp);
        }
        ds->hash_table.table[i] = NULL;
    }

    // Reset record count
    ds->num_records = 0;

    pthread_mutex_unlock(&ds->reset_lock);
}

DataStructure* initialize_and_get_data_structure() {
    DataStructure* ds = initialize_data_structure();

    // Example initialization logic; would use actual data in real implementation.
    for (size_t i = 0; i < MAX_RECORDS && ds->num_records < MAX_RECORDS; ++i) {
        pthread_mutex_lock(&ds->hash_table.lock);

        int key = rand() % MAX_RECORDS;
        Record* record = &ds->records[ds->num_records++];

        // Initialize record
        record->value = rand();
        record->timestamp = (double)rand() / RAND_MAX * 1000;
        record->status = 'A' + rand() % 26;

        unsigned long index = hash(key, ds->hash_table.capacity);
        Node* new_node = (Node*)custom_alloc(sizeof(Node));
        new_node->key = key;
        new_node->record = record;
        new_node->next = ds->hash_table.table[index];
        ds->hash_table.table[index] = new_node;

        pthread_mutex_unlock(&ds->hash_table.lock);
    }

    return ds;
}
