#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* manage_memory(int max_elements, const char *unique_keys[], int num_unique_keys,
                      int min_value, int max_value) {
    if (max_elements > 10000 || num_unique_keys > max_elements || max_value < min_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    // Allocate memory for offsets and keys
    long *offsets = malloc(max_elements * sizeof(long));
    int *keys = malloc(max_elements * sizeof(int));

    if (!offsets || !keys) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate keys array with unique values from input
    bool key_exists[10001] = {false};  // Since keys are int, use a boolean array for tracking

    for (int i = 0; i < num_unique_keys; ++i) {
        int key = atoi(unique_keys[i]);
        if (key <= 0 || key > 10000) {
            fprintf(stderr, "Invalid key value: %d\n", key);
            free(offsets);
            free(keys);
            return NULL;
        }
        if (key_exists[key]) {
            fprintf(stderr, "Duplicate key detected: %d\n", key);
            free(offsets);
            free(keys);
            return NULL;
        }
        keys[i] = key;
        key_exists[key] = true;
    }

    // Allocate memory for records
    Record *records = malloc(num_unique_keys * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate the records array
    srand((unsigned int)time(NULL));  // Seed random number generator

    for (int i = 0; i < num_unique_keys; ++i) {
        records[i].offset = offsets[i] = rand() % (max_elements * 100); // Example offset generation
        records[i].key = keys[i];
        records[i].value = min_value + rand() % ((max_value - min_value) + 1);
    }

    free(offsets);
    free(keys);

    return records;
}

int main() {
    const char *keys[] = {"1001", "2002", "3003"};
    Record *records = manage_memory(10000, keys, 3, -1000, 1000);

    if (records) {
        for (int i = 0; i < 3; ++i) {
            printf("Record %d: Offset=%ld, Key=%d, Value=%d\n", i + 1,
                   records[i].offset, records[i].key, records[i].value);
        }
        free(records); // Clean up dynamically allocated memory
