['```python
import ctypes
import random
import threading
import requests
from queue import Queue
import logging
import time

# Setup custom logger
logger = logging.getLogger('DataProcessing')
handler = logging.StreamHandler()
formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)
logger.setLevel(logging.DEBUG)

class MemoryPool:
    def __init__(self):
        self.pool = Queue()

    def allocate(self, size):
        try:
            records = [None] * size
            for i in range(size):
                self.pool.put(records[i])
            return records
        except Exception as e:
            logger.error("Memory allocation failed: %s", str(e))
            raise

    def deallocate(self, record):
        try:
            self.pool.get_nowait()
        except Exception as e:
            logger.warning("Deallocation failed: %s", str(e))

def fetch_config():
    url = "http://config-service.local/config"
    try:
        response = requests.get(url)
        response.raise_for_status()
        config = response.json()
        validate_config(config)
        return config
    except Exception as e:
        logger.error("Failed to fetch configuration: %s", str(e))
        raise

def validate_config(config):
    if 'int_range' not in config or 'long_range' not in config or 'float_range' not in config:
        raise ValueError("Invalid configuration format")

class Record(ctypes.Structure):
    _fields_ = [
        ("int_field", ctypes.c_int),
        ("long_field", ctypes.c_long),
        ("float_field", ctypes.c_float)
    ]

def generate_random_values(config):
    return {
        "int_value": random.randint(*config['int_range']),
        "long_value": random.randint(*config['long_range']),
        "float_value": random.uniform(*config['float_range'])
    }

def process_records(memory_pool, config, num_records=10):
    records = memory_pool.allocate(num_records)

    for i in range(num_records):
        values = generate_random_values(config)
        record = Record()
        record.int_field = values["int_value"]
        record.long_field = values["long_value"]
        record.float_field = values["float_value"]

        # Store the record
        records[i] = record

    return records

def flush_to_storage(records):
    try:
        for record in records:
            # Simulate encryption and compression
            data = f"{record.int_field},{record.long_field},{record.float_field}"
            logger.info("Flushing record: %s", data)
            time.sleep(0.1)  # Simulate network delay
    except Exception as e:
        logger.error("Failed to flush records: %s", str(e))
        raise

def main(config_params):
    try:
        config = fetch_config()
        memory_pool = MemoryPool()

        while True:
            records = process_records(memory_pool, config)
            flush_to_storage(records)

            # Simulate periodic flushing
            time.sleep(5)  

    except Exception as e:
        logger.critical("An error occurred: %s", str(e))

if __name__ == "__main__":
    main({})
``` 

This script initializes a memory pool for record storage, fetches configuration from an external service, validates it, and uses random values to populate records. It integrates custom logging, handles synchronous dependencies like fetching configurations, processes data concurrently using threading, and includes error handling with rollback capabilities. The periodic flush simulates real-time processing while considering network reliability and compression efficiency.']

