    return (NFAPI_CRC_INDICATION_PDU_T*)ptr;
}

void process_files(Config* config) {
    pthread_t threads[MAX_THREADS];
    int active_threads = 0;

    for (int i = 0; i < config->num_files; ++i) {
        if (active_threads >= MAX_THREADS) {
            for (int j = 0; j < MAX_THREADS; ++j) {
                pthread_join(threads[j], NULL);
            }
            active_threads = 0;
        }

        int rc = pthread_create(&threads[active_threads++], NULL, process_file, &config->file_paths[i]);
        if (rc != 0) {
            fprintf(stderr, "Error creating thread\n");
        }
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* process_file(void* arg) {
    char** file_path = (char**)arg;
    FILE* file = fopen(*file_path, "rb");

    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(fsize + 1);
    fread(buffer, 1, fsize, file);
    fclose(file);

    // Process data in parallel
    int num_elements = fsize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* indications = allocate_nfa_indications(num_elements);

    if (!indications) {
        free(buffer);
        return NULL;
    }

    // Simulate processing
    memcpy(indications, buffer, fsize);

    char output_path[256];
    snprintf(output_path, sizeof(output_path), "%s/output_%d.pdf", config->output_dir, rand());

    convert_to_pdf((const char*)indications, output_path);
    generate_thumbnail(output_path);

    free(buffer);
    free(indications);

    return NULL;
}

