#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_LENGTH 16
#define OFFSET_ARRAY_SIZE 100
#define KEY_ARRAY_SIZE 100
#define RECORD_ARRAY_SIZE 50

typedef struct {
    int value;
} record;

u_char* resolve_hostname(const char *hostname, int *error) {
    struct hostent *host_info;
    u_char ip_address[MAX_IP_LENGTH];

    if (!hostname || strlen(hostname) > MAX_HOSTNAME_LENGTH) {
        *error = EINVAL;
        return NULL;
    }

    host_info = gethostbyname(hostname);
    if (host_info == NULL) {
        *error = h_errno ? h_errno : ENODATA;
        return NULL;
    }

    inet_ntop(AF_INET, host_info->h_addr, ip_address, sizeof(ip_address));

    u_char *ip_array = malloc(MAX_IP_LENGTH);
    if (!ip_array) {
        *error = errno;
        return NULL;
    }
    memcpy(ip_array, ip_address, MAX_IP_LENGTH);

    return ip_array;
}

void* manage_memory(void* arg) {
    long *offsets = (long*)malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    int *keys = (int*)malloc(KEY_ARRAY_SIZE * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        pthread_exit(NULL);
    }

    pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < OFFSET_ARRAY_SIZE; ++i) {
        pthread_mutex_lock(&offset_lock);
        offsets[i] = i * 10L;
        pthread_mutex_unlock(&offset_lock);
    }

    for (size_t i = 0; i < KEY_ARRAY_SIZE; ++i) {
        pthread_mutex_lock(&key_lock);
        keys[i] = rand() % 100;
        pthread_mutex_unlock(&key_lock);
    }

    free(offsets);
    free(keys);

    pthread_exit(NULL);
}

record* initialize_record_array(size_t size, int min_value, int max_value) {
    record *records = malloc(size * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *hostname = argv[1];
    int error;

    u_char *ip_address = resolve_hostname(hostname, &error);
    if (!ip_address) {
        perror("DNS resolution failed");
        return EXIT_FAILURE;
    }

    printf("IP Address: %s\n", ip_address);
    free(ip_address);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_memory, NULL)) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    record *records = initialize_record_array(RECORD_ARRAY_SIZE, 1, 100);
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < RECORD_ARRAY_SIZE; ++i) {
        printf("Record %zu: %d\n", i, records[i].value);
    }

    free(records);

    pthread_join(thread_id, NULL);

    return EXIT_SUCCESS;
}
