#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include "log.h" // Hypothetical logging library

#define MAX_OFFSETS 10000
#define MAX_KEYS 10000
#define MAX_LABEL_LENGTH 10
#define MAX_RECORDS 5000
#define VALUE_MIN -1000
#define VALUE_MAX 1000

typedef struct {
    long offset;
    int key;
    int value;
    char label[MAX_LABEL_LENGTH];
    int status; // 1 for success, 0 for error
} record_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t interrupted = 0;

void handle_signal(int signum) {
    interrupted = 1;
}

int validate_unique_keys(const int *keys, size_t count) {
    // Simple uniqueness check
    if (count > MAX_KEYS) return 0;

    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) return 0;
        }
    }
    return 1;
}

int validate_unique_labels(const char **labels, size_t count) {
    // Simple uniqueness check
    if (count > MAX_OFFSETS) return 0;

    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (strcmp(labels[i], labels[j]) == 0) return 0;
        }
    }
    return 1;
}

record_t* allocate_records(const int *keys, size_t key_count, const char **labels, size_t label_count, int allow_duplicate_labels) {
    if (!validate_unique_keys(keys, key_count)) {
        log_error("Duplicate keys found");
        return NULL;
    }

    if (!allow_duplicate_labels && !validate_unique_labels(labels, label_count)) {
        log_error("Duplicate labels found");
        return NULL;
    }

    size_t record_count = key_count;
    if (record_count > MAX_RECORDS) record_count = MAX_RECORDS;

    pthread_mutex_lock(&mutex);
    if (interrupted) {
        pthread_mutex_unlock(&mutex);
        log_info("Allocation interrupted.");
        return NULL;
    }

    // Single memory allocation for simplicity
    record_t *records = malloc(record_count * sizeof(record_t));
    if (!records) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    char unique_label_chars[MAX_LABEL_LENGTH] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    // Populate records
    for (size_t i = 0; i < record_count; ++i) {
        if (interrupted) {
            free(records);
            pthread_mutex_unlock(&mutex);
            log_info("Allocation interrupted.");
            return NULL;
        }

        records[i].offset = rand() % MAX_OFFSETS;
        records[i].key = keys[i];
        records[i].value = (rand() % (VALUE_MAX - VALUE_MIN + 1)) + VALUE_MIN;

        if (!allow_duplicate_labels) {
            char *unique_label = labels[i];
            for (size_t j = 0; j < strlen(labels[i]); ++j) {
                size_t pos = rand() % strlen(unique_label_chars);
                unique_label[j] = unique_label_chars[pos];
            }
            strncpy(records[i].label, unique_label, MAX_LABEL_LENGTH - 1);
        } else {
            strncpy(records[i].label, labels[i], MAX_LABEL_LENGTH - 1);
        }

        records[i].status = 1; // Assume success

        log_info("Record populated: Key=%d Value=%d Label=%s Status=%d", records[i].key, records[i].value, records[i].label, records[i].status);
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

int main() {
    signal(SIGINT, handle_signal);

    // Sample usage
    int keys[MAX_KEYS] = { /* Populate with unique keys */ };
    size_t key_count = 0; // Set the actual count

    char *labels[MAX_OFFSETS] = { /* Populate with labels */ };
    size_t label_count = 0; // Set the actual count

    record_t *records = allocate_records(keys, key_count, labels, label_count, 0);

    if (records) {
        // Use records
        free(records);
    }

    return 0;
}
```

### Key Points:
- **Memory Management**: A single allocation is used for the `record_t` array to minimize overhead.
- **Signal Handling**: Uses a signal handler to set an interrupt flag, ensuring graceful termination and memory cleanup.
- **Thread Safety**: Utilizes mutexes to ensure thread safety during critical sections.
- **Logging**: Logs detailed information about each record's status and properties.
- **Error Handling**: Checks for key and label uniqueness, logs errors on failures, and handles allocation errors gracefully.']

