int disk_io_rate = 0;
int memory_allocation = 0;
int error_rate = 0;

void initializeFSCBArray(FileSystemControlBlock fscbs[], int count, FileSystemConfig config) {
    if (count <= 0 || count > MAX_FSCBS) {
        fprintf(stderr, "Invalid number of FSCBs requested.\n");
        return;
    }

    for (int i = 0; i < count; ++i) {
        pthread_mutex_init(&fscbs[i].lock, NULL);
        fscbs[i].config = config;

        // Dynamically allocate the file content buffer
        fscbs[i].acl.header.content_buffer = (char*)malloc(FILE_CONTENT_BUFFER_SIZE);
        if (!fscbs[i].acl.header.content_buffer) {
            fprintf(stderr, "Memory allocation failed for FSCB %d.\n", i);
            continue;
        }
        fscbs[i].acl.header.buffer_size = FILE_CONTENT_BUFFER_SIZE;

        // Initialize the name and other metadata as needed
        fscbs[i].name = (char*)malloc(256);  // Example fixed size
        if (!fscbs[i].name) {
