            free(fscbs[i].acl.header.content_buffer);
            continue;
        }
        snprintf(fscbs[i].name, 256, "File_%d", i);

        // Log initialization
        pthread_mutex_lock(&perf_monitor_lock);
        disk_io_rate++;
        memory_allocation += FILE_CONTENT_BUFFER_SIZE + 256; // Buffer size + name
        pthread_mutex_unlock(&perf_monitor_lock);
    }
}

void freeFSCBArray(FileSystemControlBlock fscbs[], int count) {
    for (int i = 0; i < count; ++i) {
        if (fscbs[i].acl.header.content_buffer) {
            free(fscbs[i].acl.header.content_buffer);
        }
        if (fscbs[i].name) {
            free(fscbs[i].name);
        }
        pthread_mutex_destroy(&fscbs[i].lock);
    }
}

void logEvent(const char* event) {
    // Simplified logging mechanism
    printf("Log: %s\n", event);

    pthread_mutex_lock(&perf_monitor_lock);
    disk_io_rate++;  // Example increment for logging activity
    pthread_mutex_unlock(&perf_monitor_lock);
}

int main() {
    FileSystemConfig config = {1, 0, 1}; // Enable journaling and compression
    FileSystemControlBlock fscbs[MAX_FSCBS];

    initializeFSCBArray(fscbs, 10, config); // Initialize with 10 FSCBs

    logEvent("Initialized FSCB array");

    freeFSCBArray(fscbs, 10);

    return 0;
}
