#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_BUFFER_LENGTH 100

typedef struct {
    int value;
    char *buffer;
    size_t length;
} record;

// Function prototypes
void log_event(const char *event);
int allocate_memory(long **offsets, int **keys, record ***records, size_t offset_size, size_t key_size, size_t record_count, size_t max_record_buffer_length, size_t max_total_memory);
void initialize_records(record *records, size_t record_count, int min_value, int max_value, const char *words[], size_t num_words, size_t max_record_buffer_length);
void free_resources(long *offsets, int *keys, record *records);

pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Example usage
    long *offsets;
    int *keys;
    record *records;

    const char *words[] = {"apple", "banana", "cherry"};
    size_t num_words = sizeof(words) / sizeof(words[0]);

    if (allocate_memory(&offsets, &keys, &records, 10, 5, 3, MAX_BUFFER_LENGTH, SIZE_MAX, 1024 * 1024)) {
        // Initialize records with random values and predefined words
        initialize_records(records, 3, 1, 100, words, num_words, MAX_BUFFER_LENGTH);

        // Use the arrays...

        // Free allocated resources
        free_resources(offsets, keys, records);
    } else {
        fprintf(stderr, "Memory allocation failed.\n");
    }

    return 0;
}

void log_event(const char *event) {
    printf("Log: %s\n", event);
}

int allocate_memory(long **offsets, int **keys, record ***records, size_t offset_size, size_t key_size, size_t record_count, size_t max_record_buffer_length, size_t max_total_memory) {
    pthread_mutex_lock(&memory_mutex);

    size_t total_offset_memory = offset_size * sizeof(long);
    size_t total_key_memory = key_size * sizeof(int);
    size_t total_record_memory = record_count * (sizeof(record) + max_record_buffer_length);

    if (total_offset_memory + total_key_memory + total_record_memory > max_total_memory) {
        log_event("Memory allocation failed: Exceeded maximum allowed memory.");
        pthread_mutex_unlock(&memory_mutex);
        return -1;
    }

    *offsets = malloc(total_offset_memory);
    *keys = malloc(total_key_memory);
    record **temp_records = malloc(record_count * sizeof(record *));

    if (!*offsets || !*keys || !temp_records) {
        log_event("Memory allocation failed: malloc returned NULL.");
        free(*offsets);
        free(*keys);
        free(temp_records);
        pthread_mutex_unlock(&memory_mutex);
        return -1;
    }

    *records = calloc(record_count, sizeof(record));
    if (!*records) {
        log_event("Memory allocation failed: calloc for records returned NULL.");
        free(*offsets);
        free(*keys);
        free(temp_records);
        pthread_mutex_unlock(&memory_mutex);
        return -1;
    }

    for (size_t i = 0; i < record_count; ++i) {
        temp_records[i] = *records + i;
        temp_records[i]->buffer = (*records + i)->buffer;
        memset((*records + i)->buffer, 0, max_record_buffer_length);
    }

    log_event("Memory allocated successfully.");
    pthread_mutex_unlock(&memory_mutex);

    // Set output parameters
    *records = (record *)temp_records;

    return 0;
}

void initialize_records(record *records, size_t record_count, int min_value, int max_value, const char *words[], size_t num_words, size_t max_record_buffer_length) {
    srand(time(NULL));

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        const char *word = words[rand() % num_words];

        if (strlen(word) >= max_record_buffer_length) {
            strncpy(records[i].buffer, word, max_record_buffer_length - 1);
            records[i].buffer[max_record_buffer_length - 1] = '\0';
        } else {
            strcpy(records[i].buffer, word);
        }

        records[i].length = strlen(records[i].buffer);
    }
}

void free_resources(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);

    log_event("Resources freed successfully.");
}
