#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <time.h>

// Alignment macros
#define ALIGN16 __attribute__((aligned(16)))
#define ALIGN256 __attribute__((aligned(256)))

typedef struct dependency {
    int task_id;
    float weight; // Assuming weight is a float within specified range.
    struct dependency* next;
} ALIGN16 Dependency;

typedef struct task_node {
    int priority;
    char status[10];  // pending, in-progress, completed
    struct task_node* next;
    Dependency* dependencies;
} ALIGN256 TaskNode;

typedef struct record {
    int value;
    long* offsets;
    int* keys;
    TaskNode* tasks_head;
} ALIGN16 Record;

// Semaphore for thread safety
sem_t semaphore;

void initialize_records(Record** records, size_t num_records) {
    if (num_records == 0 || records == NULL) return;

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100; // Random value within range [0, 99]

        size_t num_offsets = rand() % 10 + 1; // Example: up to 10 offsets
        (*records)[i].offsets = malloc(num_offsets * sizeof(long));
        if ((*records)[i].offsets == NULL) {
            perror("Failed to allocate memory for offsets");
            exit(EXIT_FAILURE);
        }

        size_t num_keys = rand() % 5 + 1; // Example: up to 5 keys
        (*records)[i].keys = malloc(num_keys * sizeof(int));
        if ((*records)[i].keys == NULL) {
            perror("Failed to allocate memory for keys");
            exit(EXIT_FAILURE);
        }

        size_t num_tasks = rand() % 3 + 1; // Example: up to 3 tasks
        TaskNode* current_task = NULL;

        for (size_t j = 0; j < num_tasks; ++j) {
            TaskNode* task_node = malloc(sizeof(TaskNode));
            if (task_node == NULL) {
                perror("Failed to allocate memory for task node");
                exit(EXIT_FAILURE);
            }

            task_node->priority = rand() % 10 + 1;
            strcpy(task_node->status, "pending"); // Default status

            size_t num_dependencies = rand() % 5 + 1; // Example: up to 5 dependencies
            Dependency* current_dep = NULL;

            for (size_t k = 0; k < num_dependencies; ++k) {
                Dependency* dep = malloc(sizeof(Dependency));
                if (dep == NULL) {
                    perror("Failed to allocate memory for dependency");
                    exit(EXIT_FAILURE);
                }

                dep->task_id = rand() % 1000 + 1;
                dep->weight = (float)(rand() % 10 + 1); // Random weight within range [1, 10]

                if (!current_dep) {
                    task_node->dependencies = dep;
                    current_dep = dep;
                } else {
                    current_dep->next = dep;
                    current_dep = dep;
                }
            }

            task_node->next = NULL;

            if (!current_task) {
                (*records)[i].tasks_head = task_node;
                current_task = task_node;
            } else {
                current_task->next = task_node;
                current_task = task_node;
            }
        }
    }
}

void serialize_records(const Record* records, size_t num_records, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&num_records, sizeof(size_t), 1, file);

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].value, sizeof(int), 1, file);

        size_t num_offsets = records[i].offsets ? (strlen(records[i].offsets) / sizeof(long)) : 0;
        fwrite(&num_offsets, sizeof(size_t), 1, file);

        if (num_offsets > 0) {
            fwrite(records[i].offsets, sizeof(long), num_offsets, file);
        }

        size_t num_keys = records[i].keys ? (strlen(records[i].keys) / sizeof(int)) : 0;
        fwrite(&num_keys, sizeof(size_t), 1, file);

        if (num_keys > 0) {
            fwrite(records[i].keys, sizeof(int), num_keys, file);
        }

        TaskNode* task_node = records[i].tasks_head;

        while (task_node) {
            fwrite(&task_node->priority, sizeof(int), 1, file);
            fwrite(task_node->status, sizeof(char) * 10, 1, file);

            Dependency* dep = task_node->dependencies;

            size_t num_dependencies = 0;
            while (dep) {
                ++num_dependencies;
                dep = dep->next;
            }

            fwrite(&num_dependencies, sizeof(size_t), 1, file);

            dep = task_node->dependencies;

            while (dep) {
                fwrite(&dep->task_id, sizeof(int), 1, file);
                fwrite(&dep->weight, sizeof(float), 1, file);

                dep = dep->next;
            }

            task_node = task_node->next;
        }
    }

    fclose(file);
}

void deserialize_records(Record** records, size_t* num_records, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(num_records, sizeof(size_t), 1, file);

    *records = malloc(*num_records * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *num_records; ++i) {
        fread(&(*records)[i].value, sizeof(int), 1, file);

        size_t num_offsets;
        fread(&num_offsets, sizeof(size_t), 1, file);

        (*records)[i].offsets = malloc(num_offsets * sizeof(long));
        if ((*records)[i].offsets == NULL) {
            perror("Failed to allocate memory for offsets");
            fclose(file);
            exit(EXIT_FAILURE);
        }

        fread((*records)[i].offsets, sizeof(long), num_offsets, file);

        size_t num_keys;
        fread(&num_keys, sizeof(size_t), 1, file);

        (*records)[i].keys = malloc(num_keys * sizeof(int));
        if ((*records)[i].keys == NULL) {
            perror("Failed to allocate memory for keys");
            fclose(file);
            exit(EXIT_FAILURE);
        }

        fread((*records)[i].keys, sizeof(int), num_keys, file);

        TaskNode* task_node_head = NULL;
        TaskNode* current_task = NULL;

        while (1) {
            int priority;
            char status[10];

            if (fread(&priority, sizeof(int), 1, file) != 1 || fread(status, sizeof(char) * 10, 1, file) != 1) {
                break; // End of tasks
            }

            TaskNode* new_task = malloc(sizeof(TaskNode));
            if (new_task == NULL) {
                perror("Failed to allocate memory for task node");
                fclose(file);
                exit(EXIT_FAILURE);
            }

            new_task->priority = priority;
            strcpy(new_task->status, status);

            size_t num_dependencies;
            fread(&num_dependencies, sizeof(size_t), 1, file);

            Dependency* current_dep = NULL;

            while (num_dependencies--) {
                int task_id;
                float weight;

                fread(&task_id, sizeof(int), 1, file);
                fread(&weight, sizeof(float), 1, file);

                Dependency* new_dep = malloc(sizeof(Dependency));
                if (new_dep == NULL) {
                    perror("Failed to allocate memory for dependency");
                    fclose(file);
                    exit(EXIT_FAILURE);
                }

                new_dep->task_id = task_id;
                new_dep->weight = weight;

                if (!current_task) {
                    new_task->dependencies = new_dep;
                    current_dep = new_dep;
                } else {
                    current_dep->next = new_dep;
                    current_dep = new_dep;
                }
            }

            new_task->next = NULL;

            if (!task_node_head) {
                (*records)[i].tasks_head = new_task;
                task_node_head = new_task;
                current_task = new_task;
            } else {
                current_task->next = new_task;
                current_task = new_task;
            }
        }
    }

    fclose(file);
}

void free_records(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        TaskNode* task_node = records[i].tasks_head;

        while (task_node) {
            Dependency* dep = task_node->dependencies;

            while (dep) {
                Dependency* temp_dep = dep;
                dep = dep->next;

                free(temp_dep);
            }

            TaskNode* temp_task = task_node;
            task_node = task_node->next;

            free(temp_task);
        }

        if (records[i].offsets) free(records[i].offsets);
        if (records[i].keys) free(records[i].keys);
    }

    free(records);
}

void test_module() {
    sem_init(&semaphore, 0, 1);

    Record* records = NULL;
    size_t num_records = 5; // Example number of records

    initialize_records(&records, num_records);

    char filename[] = "records.dat";
    serialize_records(records, num_records, filename);

    Record* deserialized_records = NULL;
    deserialize_records(&deserialized_records, &num_records, filename);

    free_records(records, num_records);
    free_records(deserialized_records, num_records);

    sem_destroy(&semaphore);
}

int main() {
    test_module();
    return 0;
}
