// Define a structure for record
typedef struct {
    int value;
} Record;

// Define a structure for managing memory dynamically
typedef struct {
    size_t offset_size;
    size_t key_size;
    size_t record_count;
    int *offsets;
    char **keys;
    Record *records;

    pthread_mutex_t mutex;
    // Additional fields to manage dynamic adjustments if needed
} MemoryManager;

// Function prototypes for initialization and cleanup
MemoryManager* init_memory_manager(size_t offset_capacity, size_t key_capacity, size_t record_capacity);
void free_memory_manager(MemoryManager *manager);

// Function prototype for thread-safe data management
int add_record(MemoryManager *manager, const char *key, int value);

// Serialization/Deserialization functions (mock implementations)
char* serialize_data(const MemoryManager *manager);
int deserialize_data(MemoryManager *manager, const char *data, size_t length);

MemoryManager* init_memory_manager(size_t offset_capacity, size_t key_capacity, size_t record_capacity) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);

    manager->offset_size = 0;
    manager->key_size = 0;
    manager->record_count = 0;
    manager->offsets = malloc(offset_capacity * sizeof(int));
    manager->keys = malloc(key_capacity * sizeof(char*));
    manager->records = malloc(record_capacity * sizeof(Record));

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
        return NULL;
    }

    return manager;
}

void free_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->key_size; ++i) {
        free(manager->keys[i]);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_record(MemoryManager *manager, const char *key, int value) {
    if (!manager || !key) return -1;

    pthread_mutex_lock(&manager->mutex);

    // Check for space and reallocate if needed
    if (manager->record_count >= manager->offset_size) {
        size_t new_capacity = manager->offset_size ? manager->offset_size * 2 : 8;

        int *new_offsets = realloc(manager->offsets, new_capacity * sizeof(int));
        Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));

        if (!new_offsets || !new_records) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failure
        }

        manager->offsets = new_offsets;
        manager->records = new_records;

        manager->offset_size = new_capacity;
    }

    if (manager->key_size >= manager->record_count) {
        size_t new_key_capacity = manager->key_size ? manager->key_size * 2 : 8;

        char **new_keys = realloc(manager->keys, new_key_capacity * sizeof(char*));

        if (!new_keys) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failure
        }

        manager->keys = new_keys;

        for (size_t i = manager->key_size; i < new_key_capacity; ++i) {
            manager->keys[i] = NULL;
        }

        manager->key_size = new_key_capacity;
    }

    // Add record and key
    int index = manager->record_count++;
    manager->records[index].value = value;

    char *new_key = strdup(key);
    if (!new_key) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Allocation failure
    }

    manager->keys[index] = new_key;
    manager->offsets[index] = index;

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

char* serialize_data(const MemoryManager *manager) {
    size_t total_length = sizeof(size_t); // Version or format identifier

    for (size_t i = 0; i < manager->record_count; ++i) {
        total_length += strlen(manager->keys[i]) + 1; // Key length
        total_length += sizeof(int);                  // Value size
    }

    char *buffer = malloc(total_length);
    if (!buffer) return NULL;

    size_t offset = 0;
    memcpy(buffer + offset, &manager->record_count, sizeof(size_t));
    offset += sizeof(size_t);

    for (size_t i = 0; i < manager->record_count; ++i) {
        size_t key_length = strlen(manager->keys[i]) + 1;

        memcpy(buffer + offset, &key_length, sizeof(size_t));
        offset += sizeof(size_t);

        memcpy(buffer + offset, manager->keys[i], key_length);
        offset += key_length;

        memcpy(buffer + offset, &(manager->records[i].value), sizeof(int));
        offset += sizeof(int);
    }

    return buffer;
}

int deserialize_data(MemoryManager *manager, const char *data, size_t length) {
    if (!manager || !data) return -1;

    pthread_mutex_lock(&manager->mutex);

    const char *current = data;

    // Read version or format identifier
    size_t record_count;
    memcpy(&record_count, current, sizeof(size_t));
    current += sizeof(size_t);

    for (size_t i = 0; i < record_count; ++i) {
        if (!add_record(manager, "", 0)) { // Reserve space without key value yet
            size_t key_length;
            memcpy(&key_length, current, sizeof(size_t));
            current += sizeof(size_t);

            char *key = strndup(current, key_length - 1);
            current += key_length;

            int value;
            memcpy(&value, current, sizeof(int));
            current += sizeof(int);

            // Update the record with actual values
            manager->records[manager->record_count - 1].value = value;
            free(manager->keys[manager->record_count - 1]);
            manager->keys[manager->record_count - 1] = key;
        } else {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failure or inconsistency
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

// Example usage
int main() {
    MemoryManager *manager = init_memory_manager(4, 4, 4);

    add_record(manager, "key1", 100);
    add_record(manager, "key2", 200);

    char* serialized_data = serialize_data(manager);
    if (serialized_data) {
        printf("Serialized data length: %zu\n", strlen(serialized_data));
        free(serialized_data);
    }

    MemoryManager *new_manager = init_memory_manager(4, 4, 4);
    deserialize_data(new_manager, serialized_data, strlen(serialized_data));

    // Clean up
    free_memory_manager(manager);
    free_memory_manager(new_manager);

    return 0;
}
