#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 10000
#define SENSITIVE_NUMBERS { -999, 0, 999 }
#define NUM_SENSITIVE (sizeof(SENSITIVE_NUMBERS) / sizeof(int))

typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Global mutex for synchronization
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

bool is_sensitive(int num);
int generate_non_sensitive_random(int min, int max);

void* manage_memory_and_records(size_t offsets_size, size_t keys_size, int value_range_min, int value_range_max) {
    if (offsets_size > MAX_ARRAY_SIZE || keys_size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Array sizes exceed maximum allowed limit.\n");
        return NULL;
    }

    long* offsets = (long*)malloc(offsets_size * sizeof(long));
    int* keys = (int*)malloc(keys_size * sizeof(int));

    if (!offsets || !keys) {
        perror("Failed to allocate memory for arrays.");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Simulating allocation monitoring
    size_t total_memory = offsets_size * sizeof(long) + keys_size * sizeof(int);
    const size_t max_capacity = MAX_ARRAY_SIZE * (sizeof(long) + sizeof(int));
    if (total_memory > 0.8 * max_capacity) {
        fprintf(stderr, "Memory usage approaching capacity limit.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Using a simple hash table to manage keys
    Record* records = NULL;
    size_t records_size = keys_size; // Initially assume maximum possible unique keys

    records = (Record*)malloc(records_size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        free(offsets);
        free(keys);
        return NULL;
    }

    bool used_keys[MAX_ARRAY_SIZE] = { false };
    pthread_t threads[10]; // For handling up to 10 concurrent requests

    for (size_t i = 0; i < keys_size; ++i) {
        int key = rand() % MAX_ARRAY_SIZE;

        pthread_mutex_lock(&lock);
        while (used_keys[key]) {
            key = rand() % MAX_ARRAY_SIZE;
        }
        used_keys[key] = true;
        pthread_mutex_unlock(&lock);

        Record record = { offsets[i], key, generate_non_sensitive_random(value_range_min, value_range_max) };
        records[i] = record;
    }

    free(offsets);
    free(keys);

    return (void*)records;
}

bool is_sensitive(int num) {
    int sensitive_nums[] = SENSITIVE_NUMBERS;
    for (int i = 0; i < NUM_SENSITIVE; ++i) {
        if (num == sensitive_nums[i]) return true;
    }
    return false;
}

int generate_non_sensitive_random(int min, int max) {
    int value;
    do {
        value = rand() % (max - min + 1) + min;
    } while (is_sensitive(value));
    return value;
}

int main() {
    srand(time(NULL)); // Seed for randomness

    size_t offsets_size = 5000;
    size_t keys_size = 5000;
    int value_range_min = -1000;
    int value_range_max = 1000;

    Record* records = (Record*)manage_memory_and_records(offsets_size, keys_size, value_range_min, value_range_max);
    if (!records) {
        fprintf(stderr, "Failed to manage memory and create records.\n");
        return EXIT_FAILURE;
    }

    // Use the records...

    free(records);
    return EXIT_SUCCESS;
}
