### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 500 * 1024 // 500 KB
#define RECORD_SIZE sizeof(struct record)
#define TIMESTAMP_LEN 20

typedef struct item {
    size_t size;
    union {
        double dbl;
        char *str;
    } data;
} item;

typedef struct record {
    int value;
    char unique_id[TIMESTAMP_LEN];
    item *item_ptr;
} record;

typedef struct my_struct {
    char string[256];
    unsigned int number;
    int key_count;
    int *keys;
    record **records;
    size_t records_size;
} my_struct;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

size_t total_memory_usage = 0;
my_struct *struct_array = NULL;
long *long_array = NULL;
double *double_array = NULL;

void log_message(const char *message) {
    printf("%s\n", message);
}

void free_record(record *rec) {
    if (rec->item_ptr != NULL) {
        free(rec->item_ptr->data.str); // Free only if it's a string
        free(rec->item_ptr);
    }
    free(*rec->records);
    free(rec->records);
    total_memory_usage -= RECORD_SIZE;
}

void manage_memory() {
    pthread_mutex_lock(&memory_lock);
    while (total_memory_usage > MAX_MEMORY_USAGE) {
        // Simple LRU: Assume the last record added is least recently used
        if (struct_array && struct_array->records_size > 0) {
            free_record(struct_array->records[struct_array->records_size - 1]);
            struct_array->records_size--;
        }
    }
    pthread_mutex_unlock(&memory_lock);
}

void allocate_structs(size_t count) {
    pthread_mutex_lock(&memory_lock);

    if (total_memory_usage + sizeof(my_struct) * count > MAX_MEMORY_USAGE) {
        log_message("Memory limit exceeded, cannot allocate more structs");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    struct_array = realloc(struct_array, sizeof(my_struct) * count);
    long_array = realloc(long_array, sizeof(long) * count);
    double_array = realloc(double_array, sizeof(double) * count);

    for (size_t i = 0; i < count; ++i) {
        struct_array[i].string[0] = '\0';
        struct_array[i].number = 0;
        struct_array[i].key_count = 0;
        struct_array[i].keys = NULL;
        struct_array[i].records_size = 0;
        struct_array[i].records = malloc(sizeof(record*) * 10); // Initial capacity

        total_memory_usage += sizeof(my_struct);
    }

    pthread_mutex_unlock(&memory_lock);
}

void initialize_record(int index, my_struct *s) {
    time_t now = time(NULL);
    char timestamp[TIMESTAMP_LEN];
    strftime(timestamp, TIMESTAMP_LEN, "%Y%m%d%H%M%S", localtime(&now));

    record *rec = malloc(RECORD_SIZE + sizeof(char) * (TIMESTAMP_LEN - 1));
    snprintf(rec->unique_id, TIMESTAMP_LEN, "ID_%d_%s", index, timestamp);

    rec->value = index;
    item *item_ptr = malloc(sizeof(item));
    item_ptr->size = sizeof(double);
    item_ptr->data.dbl = 0.0; // or item_ptr->data.str = strdup("example");

    rec->item_ptr = item_ptr;

    if (s->records_size >= 10) {
        s->records = realloc(s->records, sizeof(record*) * (s->records_size + 10));
    }

    s->records[s->records_size++] = rec;
    total_memory_usage += RECORD_SIZE;

    manage_memory();
}

void free_all() {
    pthread_mutex_lock(&memory_lock);

    if (struct_array) {
        for (size_t i = 0; i < sizeof(struct_array) / sizeof(my_struct); ++i) {
            for (size_t j = 0; j < struct_array[i].records_size; ++j) {
                free_record(struct_array[i].records[j]);
            }
            if (struct_array[i].keys) free(struct_array[i].keys);
        }
        free(struct_array->records);
        free(struct_array);
    }

    free(long_array);
    free(double_array);

    total_memory_usage = 0;

    pthread_mutex_unlock(&memory_lock);
}

// Sample use case
int main() {
    allocate_structs(10); // Example allocation

    initialize_record(1, &struct_array[0]); // Initialize a record for struct 0

    free_all();

    return 0;
}
