#define ALIGNMENT 32

void *aligned_malloc(size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, ALIGNMENT);
#else
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
