Node *init_node(double value) {
    Node *node = (Node *)aligned_malloc(sizeof(Node));
    if (!node) return NULL;

    pthread_mutex_init(&node->lock, NULL);
    node->value = value;
    node->head = NULL;
    return node;
}

// Add an item to the list within a node
void add_item_to_node(Node *node, int key, const char *data) {
    if (!node || !data) return;

    pthread_mutex_lock(&node->lock);
    Item *new_item = init_item(key, data);
    if (new_item) {
        new_item->next = node->head;
        node->head = new_item;
    }
    pthread_mutex_unlock(&node->lock);
}

// Verify the integrity of a node's linked list
int verify_node_integrity(Node *node) {
    Item *current = node->head;
    while (current) {
        if (!current->data) return 0; // Data pointer should not be NULL
        current = current->next;
    }
    return 1;
}

// Free a node and its linked list
void free_node(Node *node) {
    if (!node) return;

    pthread_mutex_lock(&node->lock);
    Item *current = node->head;
    while (current) {
        Item *temp = current;
        current = current->next;
        free(temp->data); // Free string data
        aligned_free(temp);
    }
    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);
    aligned_free(node);
}

