#define MAX_RANGES 10000
#define MEM_POOL_SIZE 50000
#define EXPORT_INTERVAL_MS 60000

typedef struct {
    int min;
    int max;
    int is_inclusive_min;
    int is_inclusive_max;
} Range;

typedef struct {
    int value;
} Record;

typedef struct MemoryPoolNode {
    void* memory_block;
    size_t block_size;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* head;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct FlexibleResourceManager {
    Range ranges[MAX_RANGES];
    int range_count;
    MemoryPool mem_pool;
    pthread_mutex_t mutex;
    FILE* log_file;
    time_t last_export_time;
} FlexibleResourceManager;

// Function prototypes
void initMemoryPool(MemoryPool* pool, size_t block_size);
void* allocateFromPool(MemoryPool* pool);
void freeToPool(MemoryPool* pool, void* memory_block);
long generateRandomLongInRange(Range range);
float generateRandomFloatInRange(Range range);
int logConnection(FlexibleResourceManager* manager, const char* message);
void exportLogs(const FlexibleResourceManager* manager);

// Initialize memory pool
void initMemoryPool(MemoryPool* pool, size_t block_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
}

// Allocate memory from pool
void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    MemoryPoolNode* node = pool->head;
    if (node) {
        void* block = node->memory_block;
        pool->head = node->next;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);

    // Allocate new memory if pool is empty
    MemoryPoolNode* newNode = malloc(sizeof(MemoryPoolNode));
    newNode->memory_block = malloc(block_size);
    newNode->block_size = block_size;
    newNode->next = NULL;

    return newNode->memory_block;
}

// Free memory to pool
void freeToPool(MemoryPool* pool, void* memory_block) {
    MemoryPoolNode* node = malloc(sizeof(MemoryPoolNode));
    node->memory_block = memory_block;
    node->block_size = 0; // Size is not important for reuse
    node->next = NULL;

    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);
}

// Generate random long within range
long generateRandomLongInRange(Range range) {
    srand((unsigned int)time(NULL));
    long min = range.is_inclusive_min ? range.min : range.min + 1;
    long max = range.is_inclusive_max ? range.max : range.max - 1;
    return (rand() % (max - min + 1)) + min;
}

// Generate random float within range
float generateRandomFloatInRange(Range range) {
    srand((unsigned int)time(NULL));
    float min = range.is_inclusive_min ? (float)range.min : (float)(range.min + 1);
    float max = range.is_inclusive_max ? (float)range.max : (float)(range.max - 1);
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

// Log connection
int logConnection(FlexibleResourceManager* manager, const char* message) {
    pthread_mutex_lock(&manager->mutex);
    if (!manager->log_file) {
        manager->log_file = fopen("connection_log.txt", "a");
    }
    if (manager->log_file) {
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file);
    }
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Export logs
