#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <math.h>

// Constants for alignment and logging
#define ALIGNMENT 64
#define MAX_THREADS 10

typedef struct ByteData {
    size_t length;
    uint8_t *data;
} ByteData;

typedef struct EntryNode {
    unsigned int key;
    float value;
    time_t timestamp;
    ByteData bytes;
    struct EntryNode *left;
    struct EntryNode *right;
} EntryNode;

typedef struct BinaryTree {
    EntryNode *root;
} BinaryTree;

// Logger for tracking memory usage
void log_memory_usage(size_t size) {
    printf("Allocated %zu bytes\n", size);
}

// Align allocation to the specified boundary
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    log_memory_usage(size);
    return ptr;
}

// Function to calculate checksum of data
uint32_t calculate_checksum(void *data, size_t length) {
    uint8_t *bytes = (uint8_t *)data;
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}

// Thread-safe memory pool manager
typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = (MemoryPool*)aligned_alloc(ALIGNMENT, sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = aligned_alloc(ALIGNMENT, mp->pool_size);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_allocate(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->pool_size < mp->block_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    void *ptr = mp->pool;
    mp->pool = (uint8_t*)mp->pool + mp->block_size;
    mp->pool_size -= mp->block_size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to initialize an entry
EntryNode* init_entry(unsigned int key, float value, time_t timestamp, size_t byte_length) {
    EntryNode *entry = (EntryNode*)aligned_alloc(ALIGNMENT, sizeof(EntryNode));
    entry->key = key;
    entry->value = value;
    entry->timestamp = timestamp;
    entry->bytes.length = byte_length;
    entry->bytes.data = (uint8_t*)aligned_alloc(ALIGNMENT, byte_length);
    for (size_t i = 0; i < byte_length; ++i) {
        entry->bytes.data[i] = rand() % 256;
    }
    return entry;
}

// Function to manage allocation and initialization
EntryNode** initialize_entries(size_t num_entries, size_t max_byte_length) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    EntryNode **entries = (EntryNode**)aligned_alloc(ALIGNMENT, sizeof(EntryNode*) * num_entries);
    MemoryPool *mp = create_memory_pool(sizeof(EntryNode), num_entries);

    for (size_t i = 0; i < num_entries; ++i) {
        pthread_mutex_lock(&lock);
        float value = expf((float)(rand() % 100));
        time_t timestamp = time(NULL);
        size_t byte_length = rand() % max_byte_length + 1;

        EntryNode *entry = init_entry(i, value, timestamp, byte_length);
        entries[i] = entry;

        // Verify checksum
        uint32_t checksum = calculate_checksum(entry->bytes.data, entry->bytes.length);
        printf("Checksum for entry %zu: %u\n", i, checksum);

        pthread_mutex_unlock(&lock);
    }

    destroy_memory_pool(mp);
    pthread_mutex_destroy(&lock);

    return entries;
}

int main() {
    srand((unsigned int)time(NULL));
    size_t num_entries = 10;
    size_t max_byte_length = 256;

    EntryNode **entries = initialize_entries(num_entries, max_byte_length);

    // Clean up
    for (size_t i = 0; i < num_entries; ++i) {
        free(entries[i]->bytes.data);
        free(entries[i]);
    }
    free(entries);

    return 0;
}
