#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>

#define MAX_NODES 100
#define ITEMS_PER_NODE 10
#define STRING_LENGTH 16
#define ALIGNMENT 64

typedef struct {
    double value;
} node_data;

typedef union {
    struct item* ptr;
    short int_val;
} metadata;

typedef struct item {
    int key;
    char str[STRING_LENGTH];
    metadata meta;
    struct item* next;
} item;

typedef struct {
    node_data* data;
    item* head;
    int* int_array;
    size_t int_array_size;
} node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

int random_seed = 0;
void set_random_seed(int seed) {
    random_seed = seed;
}

double generate_double() {
    int rand_val = rand_r(&random_seed);
    double sqrt_val = sqrt(rand_val);
    return round(sqrt_val * 1000.0) / 1000.0; // Round to three decimal places
}

char* generate_random_string(size_t length) {
    static const char alphanum[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";
    char* str = (char*)aligned_alloc(ALIGNMENT, sizeof(char) * length);
    if (!str) return NULL;

    for (size_t i = 0; i < length - 1; ++i) {
        str[i] = alphanum[rand_r(&random_seed) % (sizeof(alphanum) - 1)];
    }
    str[length - 1] = '\0';
    return str;
}

item* create_item(int key, char* str, metadata meta) {
    item* it = (item*)aligned_alloc(ALIGNMENT, sizeof(item));
    if (!it) return NULL;

    it->key = key;
    strncpy(it->str, str, STRING_LENGTH - 1);
    it->str[STRING_LENGTH - 1] = '\0';
    it->meta = meta;
    it->next = NULL;
    return it;
}

node* allocate_and_initialize_nodes(size_t num_nodes) {
    if (num_nodes > MAX_NODES || !aligned_alloc(ALIGNMENT, sizeof(node) * num_nodes)) {
        fprintf(stderr, "Allocation failed: exceeded node limit or memory allocation error\n");
        return NULL;
    }

    node* nodes = (node*)aligned_alloc(ALIGNMENT, sizeof(node) * num_nodes);
    if (!nodes) return NULL;

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_nodes; ++i) {
        node& n = nodes[i];

        // Allocate and initialize array of node_data
        n.data = (node_data*)aligned_alloc(ALIGNMENT, sizeof(node_data));
        if (!n.data) goto cleanup;

        n.data->value = generate_double();

        // Initialize linked list of items
        n.head = NULL;
        for (int j = 0; j < ITEMS_PER_NODE; ++j) {
            int key = rand_r(&random_seed) % 10000;
            char* str = generate_random_string(STRING_LENGTH);
            if (!str) goto cleanup;

            metadata meta;
            double prob = ((double)rand_r(&random_seed)) / RAND_MAX;
            if (prob < 0.5) {
                meta.int_val = rand_r(&random_seed) % 100;
            } else {
                meta.ptr = create_item(key, str, meta);
                if (!meta.ptr) goto cleanup;
            }

            item* new_item = create_item(key, str, meta);
            if (!new_item) goto cleanup;

            new_item->next = n.head;
            n.head = new_item;
        }

        // Allocate dynamic array of integers
        size_t int_array_size = rand_r(&random_seed) % 100 + 1;
        n.int_array = (int*)aligned_alloc(ALIGNMENT, sizeof(int) * int_array_size);
        if (!n.int_array) goto cleanup;

        for (size_t k = 0; k < int_array_size; ++k) {
            n.int_array[k] = rand_r(&random_seed) % 100;
        }
        n.int_array_size = int_array_size;
    }

    pthread_mutex_unlock(&lock);
    return nodes;

cleanup:
    fprintf(stderr, "Error during initialization: memory allocation failed\n");
    for (size_t i = 0; i < num_nodes; ++i) {
        node& n = nodes[i];
        free(n.data);

        item* it = n.head;
        while (it) {
            item* next = it->next;
            if (it->meta.ptr) free(it->meta.ptr);
            free(it);
            it = next;
        }

        free(n.int_array);
    }
    free(nodes);
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    set_random_seed(42); // For reproducibility
    size_t num_nodes = 5; // Example number of nodes

    node* nodes = allocate_and_initialize_nodes(num_nodes);

    if (nodes) {
        printf("Nodes initialized successfully.\n");
        free(nodes);
    }

    return 0;
}
