import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class ConnectionManager {

    private static final int MAX_RETRIES = 5;
    private static final String SERVER_ADDRESS = "localhost";
    private static final int SERVER_PORT = 8080;

    public void establishConnection() {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try (SocketChannel socketChannel = SocketChannel.open()) {
                socketChannel.connect(new InetSocketAddress(SERVER_ADDRESS, SERVER_PORT));

                // Connection established
                System.out.println("Connected to server on attempt " + attempt);
                monitorConnection(socketChannel);

                return;
            } catch (IOException e) {
                System.err.println("Attempt " + attempt + " failed: " + e.getMessage());
                if (attempt == MAX_RETRIES) {
                    System.err.println("All connection attempts failed.");
                }
                try {
                    Thread.sleep(1000); // Wait before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    System.err.println("Thread interrupted during sleep: " + ie.getMessage());
                }
            }
        }
    }

    private void monitorConnection(SocketChannel socketChannel) throws IOException {
        while (!socketChannel.finishConnect()) {
            // Wait for the connection to complete
        }

        // Monitor and handle connection state here (e.g., read/write operations)
        System.out.println("Monitoring connection...");

        // Properly close the connection after use
        if (socketChannel.isConnected()) {
            socketChannel.close();
            System.out.println("Connection closed.");
        }
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        manager.establishConnection();
    }
}
