['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define ALIGNMENT 64

typedef struct Edge {
    int target;
    double weight;
} Edge;

typedef struct Node {
    int id;
    Edge *edges;
    size_t edge_count;
    pthread_mutex_t lock; // for thread safety
} Node;

typedef struct Graph {
    Node **nodes;
    size_t node_count;
    pthread_mutex_t graph_lock;
} Graph;

static void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // posix_memalign sets errno on failure
    }
    return ptr;
}

Graph* create_graph() {
    Graph *graph = aligned_alloc(ALIGNMENT, sizeof(Graph));
    if (!graph) {
        perror("Failed to allocate memory for graph");
        return NULL;
    }

    pthread_mutex_init(&graph->graph_lock, NULL);
    graph->nodes = NULL;
    graph->node_count = 0;

    return graph;
}

int add_node(Graph *graph, int id) {
    if (!graph) return -1;

    Node *new_node = aligned_alloc(ALIGNMENT, sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return -1;
    }

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->id = id;
    new_node->edges = NULL;
    new_node->edge_count = 0;

    pthread_mutex_lock(&graph->graph_lock);

    Node **nodes = realloc(graph->nodes, (graph->node_count + 1) * sizeof(Node*));
    if (!nodes) {
        perror("Failed to reallocate memory for nodes");
        pthread_mutex_unlock(&graph->graph_lock);
        return -1;
    }

    graph->nodes = nodes;
    graph->nodes[graph->node_count++] = new_node;

    pthread_mutex_unlock(&graph->graph_lock);

    return 0; // success
}

int add_edge(Graph *graph, int src_id, int dest_id, double weight) {
    if (!graph || !weight) return -1;

    Node *src = NULL;
    Node *dest = NULL;

    pthread_mutex_lock(&graph->graph_lock);
    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i]->id == src_id) {
            src = graph->nodes[i];
        } else if (graph->nodes[i]->id == dest_id) {
            dest = graph->nodes[i];
        }
    }
    pthread_mutex_unlock(&graph->graph_lock);

    if (!src || !dest) return -1;

    pthread_mutex_lock(&src->lock);
    src->edges = realloc(src->edges, (src->edge_count + 1) * sizeof(Edge));
    if (!src->edges) {
        perror("Failed to reallocate memory for edges");
        pthread_mutex_unlock(&src->lock);
        return -1;
    }

    src->edges[src->edge_count].target = dest_id;
    src->edges[src->edge_count].weight = weight;
    ++(src->edge_count);

    pthread_mutex_unlock(&src->lock);

    return 0; // success
}

int remove_node(Graph *graph, int id) {
    if (!graph) return -1;

    pthread_mutex_lock(&graph->graph_lock);
    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i]->id == id) {
            free(graph->nodes[i]->edges);
            pthread_mutex_destroy(&(graph->nodes[i]->lock));

            Node **nodes = realloc(graph->nodes, (--graph->node_count) * sizeof(Node*));
            if (!nodes && graph->node_count > 0) { // handle case where reallocation fails
                perror("Failed to reallocate memory for nodes");
                pthread_mutex_unlock(&graph->graph_lock);
                return -1;
            }
            graph->nodes = nodes;

            free(graph->nodes[i]);
            memmove(&(graph->nodes[i]), &(graph->nodes[i + 1]), sizeof(Node*) * (graph->node_count - i));
            break;
        }
    }
    pthread_mutex_unlock(&graph->graph_lock);

    return 0; // success
}

int verify_graph(Graph *graph) {
    if (!graph) return -1;

    for (size_t i = 0; i < graph->node_count; ++i) {
        Node *node = graph->nodes[i];

        if (!node) return -1;
        if (node->id < 0 || node->edge_count < 0) return -1;

        pthread_mutex_lock(&node->lock);
        for (size_t j = 0; j < node->edge_count; ++j) {
            Edge *edge = &(node->edges[j]);
            if (edge == NULL || edge->weight <= 0.0) return -1;
        }
        pthread_mutex_unlock(&node->lock);
    }

    return 0; // success
}

void destroy_graph(Graph *graph) {
    if (!graph) return;

    pthread_mutex_lock(&graph->graph_lock);

    for (size_t i = 0; i < graph->node_count; ++i) {
        free(graph->nodes[i]->edges);
        pthread_mutex_destroy(&(graph->nodes[i]->lock));
        free(graph->nodes[i]);
    }

    free(graph->nodes);
    pthread_mutex_unlock(&graph->graph_lock);

    pthread_mutex_destroy(&graph->graph_lock);
    free(graph);
}
