#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define ALIGNMENT 16

typedef struct dir_entry {
    char *file_name;
    int file_size;
    struct dir_entry *subdir;
} dir_entry;

void* aligned_malloc(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        return NULL;
    }
    return ptr;
}

void aligned_free(void *ptr) {
    free(ptr);
}

typedef struct {
    pthread_mutex_t lock;
} dir_system;

dir_entry* create_dir_entry(const char *file_name, int file_size, dir_entry *subdir) {
    dir_entry *entry = (dir_entry*)aligned_malloc(sizeof(dir_entry));
    if (!entry) return NULL;

    entry->file_name = aligned_malloc(strlen(file_name) + 1);
    if (!entry->file_name) {
        aligned_free(entry);
        return NULL;
    }
    strcpy(entry->file_name, file_name);

    entry->file_size = file_size;
    entry->subdir = subdir;

    return entry;
}

int verify_dir_entry(dir_entry *entry) {
    if (!entry) return 0;
    if (!(entry->file_name && strlen(entry->file_name))) return 0;
    if (entry->subdir && !verify_dir_entry(entry->subdir)) return 0;
    return 1;
}

void free_dir_entry(dir_entry *entry) {
    if (entry) {
        aligned_free(entry->file_name);
        free_dir_entry(entry->subdir);
        aligned_free(entry);
    }
}

dir_entry* build_directory(const char **files, int *sizes, int num_files, dir_system *ds) {
    pthread_mutex_lock(&ds->lock);

    dir_entry *root = NULL;
    for (int i = 0; i < num_files; ++i) {
        dir_entry *new_entry = create_dir_entry(files[i], sizes[i], root);
        if (!new_entry) {
            free_directory(root);
            pthread_mutex_unlock(&ds->lock);
            return NULL;
        }
        new_entry->subdir = root;
        root = new_entry;
    }

    int valid = verify_dir_entry(root);
    pthread_mutex_unlock(&ds->lock);

    if (!valid) {
        free_directory(root);
        return NULL;
    }

    return root;
}

void free_directory(dir_entry *root) {
    dir_entry *current = root;
    while (current) {
        dir_entry *next = current->subdir;
        free_dir_entry(current);
        current = next;
    }
}

int main() {
    const char *files[] = {"file1.txt", "file2.txt"};
    int sizes[] = {100, 200};
    dir_system ds = {PTHREAD_MUTEX_INITIALIZER};

    dir_entry *root = build_directory(files, sizes, 2, &ds);
    if (root) {
        printf("Directory built successfully.\n");
        free_directory(root);
    } else {
        printf("Failed to build directory.\n");
    }

    pthread_mutex_destroy(&ds.lock);

    return 0;
}
