    char string[20];
    Metadata metadata;
} Item;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void aligned_free(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    free(ptr);
#endif
}

int initialize_data(int max_nodes, int max_items, long** offsets, int** keys,
                    Record*** records, size_t* record_sizes,
                    Node*** nodes, Item*** items) {
    srand((unsigned)time(NULL));

    // Allocate and initialize arrays of offsets and keys
    *offsets = aligned_alloc(ALIGNMENT, max_nodes * sizeof(long));
    if (!(*offsets)) return -1;
    *keys = aligned_alloc(ALIGNMENT, max_items * sizeof(int));
    if (!(*keys)) {
        aligned_free(*offsets);
        return -1;
    }

    // Initialize offsets and keys
    for (int i = 0; i < max_nodes; ++i) {
        (*offsets)[i] = rand() % 1000000L;
    }
    for (int i = 0; i < max_items; ++i) {
        (*keys)[i] = rand() % 10000;
    }

    // Allocate and initialize arrays of records
    *records = aligned_alloc(ALIGNMENT, max_nodes * sizeof(Record*));
    if (!(*records)) return -1;
    *record_sizes = aligned_alloc(ALIGNMENT, max_nodes * sizeof(size_t));
    if (!(*record_sizes)) {
        aligned_free(*offsets);
        aligned_free(*keys);
        aligned_free(*records);
        return -1;
    }

    for (int i = 0; i < max_nodes; ++i) {
        size_t record_count = rand() % 100 + 1; // Random number of records
        (*record_sizes)[i] = record_count;
        (*records)[i] = aligned_alloc(ALIGNMENT, record_count * sizeof(Record));
        if (!(*records)[i]) return -1;

        for (size_t j = 0; j < record_count; ++j) {
            (*records)[i][j].value = rand() % 10000;
        }
    }

    // Allocate and initialize array of node pointers
    *nodes = aligned_alloc(ALIGNMENT, max_nodes * sizeof(Node*));
    if (!(*nodes)) return -1;

    for (int i = 0; i < max_nodes; ++i) {
        (*nodes)[i] = aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!(*nodes)[i]) return -1;
        (*nodes)[i]->value = rand() % 100000.0;
        (*nodes)[i]->next = NULL;
    }

    // Allocate and initialize linked list of items
    *items = aligned_alloc(ALIGNMENT, max_items * sizeof(Item*));
    if (!(*items)) return -1;

    for (int i = 0; i < max_items; ++i) {
        (*items)[i] = aligned_alloc(ALIGNMENT, sizeof(Item));
        if (!(*items)[i]) return -1;
        (*items)[i]->key = rand() % 10000;
        snprintf((*items)[i]->string, sizeof((*items)[i]->string), "Item_%d", i);

        // Randomly decide metadata type
        int metadata_type = rand() % 2;
        if (metadata_type == 0) {
            (*items)[i]->metadata.item_ptr = NULL; // or point to another item
        } else {
            (*items)[i]->metadata.value = rand() % 100;
        }
    }

    return 0;
}

void free_resources(long* offsets, int* keys,
                    Record** records, size_t* record_sizes,
                    Node** nodes, Item** items, int max_nodes) {
    for (int i = 0; i < max_nodes; ++i) {
        aligned_free(records[i]);
        aligned_free(nodes[i]);
    }
    aligned_free(offsets);
    aligned_free(keys);
    aligned_free(records);
    aligned_free(record_sizes);
    aligned_free(nodes);
    for (int i = 0; i < MAX_ITEMS; ++i) {
        aligned_free(items[i]);
    }
    aligned_free(items);
}

int main() {
    long* offsets;
    int* keys;
    Record** records;
    size_t* record_sizes;
    Node** nodes;
    Item** items;

    if (initialize_data(MAX_NODES, MAX_ITEMS, &offsets, &keys,
                        &records, &record_sizes, &nodes, &items) != 0) {
        log_error("Failed to initialize data structures");
        return EXIT_FAILURE;
    }

    // Use the initialized data...

    free_resources(offsets, keys, records, record_sizes, nodes, items, MAX_NODES);
    return EXIT_SUCCESS;
}
