        allocate_aligned_memory((void**)&keys, key_array_size, 64) < 0) {
        return -1;
    }

    node **nodes = NULL;
    if (allocate_aligned_memory((void**)&nodes, MAX_NODES * sizeof(node*), 64) < 0) {
        free(offsets);
        free(keys);
        return -1;
    }

    for (int i = 0; i < MAX_NODES; ++i) {
        size_t record_array_size = max_records_per_node * sizeof(record);
        nodes[i] = NULL;

        if (allocate_aligned_memory((void**)&nodes[i], record_array_size, 64) < 0) {
            free(offsets);
            free(keys);

            for (int j = 0; j < i; ++j) {
                free(nodes[j]);
            }
            free(nodes);
            return -1;
        }

        for (size_t j = 0; j < max_records_per_node; ++j) {
            ((record *)nodes[i])[j].value = rand() % 100 + 1;
        }
    }

    item *items_head = NULL, **items_tail = &items_head;

    srand(time(NULL));

    for (int i = 0; i < MAX_ITEMS; ++i) {
        item *new_item = malloc(sizeof(item));
        if (!new_item) {
            log_message("Memory allocation failed");
            break;
        }

        new_item->key = rand() % 1000 + 1;
        snprintf(new_item->string, sizeof(new_item->string), "Item_%d", i);

        int rand_choice = rand() % 2;
        if (rand_choice == 0) {
            new_item->meta.fixed_value = rand() % 50 + 1;
        } else {
            item *existing_item = malloc(sizeof(item));
            if (!existing_item) {
                free(new_item);
                break;
            }
            existing_item->key = rand() % 1000 + 1;
            snprintf(existing_item->string, sizeof(existing_item->string), "Linked_Item_%d", i);

            new_item->meta.next_item = existing_item;
        }

        *items_tail = new_item;
        items_tail = &new_item->next;

    }

    // Free allocated memory after use (example)
    free(offsets);
    free(keys);

    for (int i = 0; i < MAX_NODES; ++i) {
        free(nodes[i]);
    }
    free(nodes);

    item *current = items_head;
    while (current) {
        item *next = current->meta.next_item ? NULL : current->next;
        free(current);
        if (!next && current->meta.next_item) {
            free(current->meta.next_item);
        }
        current = next;
    }

    return 0;
}

int main() {
