typedef struct {
    time_t timestamp;
    char status;
    double amount;
} Transaction;

typedef struct {
    int total_transactions;
    double average_amount;
    double max_amount;
    double min_amount;
} SummaryStats;

void manage_memory(Transaction **transactions, size_t *transaction_count, size_t memory_budget,
                   time_t start_time_window, time_t end_time_window, double min_amount_range, 
                   double max_amount_range) {

    // Calculate maximum number of transactions based on the estimated size
    size_t transaction_size = sizeof(Transaction);
    size_t max_transactions = memory_budget / transaction_size;

    // Allocate initial array for transactions
    *transactions = (Transaction *)malloc(max_transactions * transaction_size);
    if (*transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand((unsigned int)time(NULL));
    SummaryStats stats = {0, 0.0, -1e9, 1e9};
    for (size_t i = 0; i < max_transactions; ++i) {
        // Generate random transaction data
        time_t current_time = start_time_window + rand() % ((end_time_window - start_time_window) + 1);
        char status = 'P'; // Assume 'P' for pending as a placeholder
        double amount = min_amount_range + (rand() / (RAND_MAX / (max_amount_range - min_amount_range)));

        if (current_time > end_time_window) break; // Exit loop if time exceeds window

        (*transactions)[i].timestamp = current_time;
        (*transactions)[i].status = status;
        (*transactions)[i].amount = amount;

        stats.total_transactions++;
        stats.average_amount += amount;
        if (amount > stats.max_amount) {
            stats.max_amount = amount;
        }
        if (amount < stats.min_amount) {
            stats.min_amount = amount;
        }

        // Check if we've exceeded the time window
        if (current_time >= end_time_window || i + 1 == max_transactions) break;
    }

    *transaction_count = stats.total_transactions;

    // Calculate average amount
    if (stats.total_transactions > 0) {
        stats.average_amount /= stats.total_transactions;
    } else {
        stats.max_amount = stats.min_amount = 0; // Reset if no transactions occurred
    }

    printf("Summary Statistics:\n");
    printf("Total Transactions: %d\n", stats.total_transactions);
    printf("Average Amount: %.2f\n", stats.average_amount);
    printf("Max Amount: %.2f\n", stats.max_amount);
    printf("Min Amount: %.2f\n", stats.min_amount);

    // If needed, reallocate transactions to a smaller array
    if (*transaction_count < max_transactions) {
        *transactions = (Transaction *)realloc(*transactions, (*transaction_count) * transaction_size);
        if (*transactions == NULL && *transaction_count > 0) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(*transactions); // Attempt to clean up
            *transactions = NULL;
        }
    }

    // Return the summary stats for further use or display
}

int main() {
    const size_t memory_budget = 1024 * 1024; // e.g., 1 MB limit
    Transaction *transactions = NULL;
    size_t transaction_count = 0;

    manage_memory(&transactions, &transaction_count, memory_budget,
                  time(NULL) - 86400, time(NULL), 10.0, 1000.0); // Example: Last 24 hours, $10 to $1000

    free(transactions);
    return 0;
}
