#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_RECORDS 1000
#define CACHE_SIZE 10
#define LRU_THRESHOLD_PERCENTAGE 75

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct CacheNode {
    Record record;
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

typedef struct LRUCache {
    CacheNode* head;
    CacheNode* tail;
    size_t cache_size;
    size_t usage_count;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* initialize_cache(size_t initial_size) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = NULL;
    cache->tail = NULL;
    cache->cache_size = initial_size;
    cache->usage_count = 0;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void free_cache_node(CacheNode* node) {
    if (node) {
        free(node);
    }
}

void remove_from_list(CacheNode** head, CacheNode* node) {
    if (*head == node) *head = node->next;
    if (node->next) node->next->prev = node->prev;
    if (node->prev) node->prev->next = node->next;
}

void add_to_front(CacheNode** head, CacheNode* node) {
    node->next = *head;
    node->prev = NULL;
    if (*head) (*head)->prev = node;
    *head = node;
    if (!(*head)->next) (*head)->next = NULL;
}

void access_cache(LRUCache* cache, Record record) {
    pthread_mutex_lock(&cache->lock);

    CacheNode* current = cache->tail;
    while (current) {
        if (current->record.key == record.key) {
            remove_from_list(&(cache->head), current);
            add_to_front(&(cache->head), current);
            pthread_mutex_unlock(&cache->lock);
            return;
        }
        current = current->prev;
    }

    CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!new_node) {
        pthread_mutex_unlock(&cache->lock);
        return;
    }
    new_node->record = record;
    add_to_front(&(cache->head), new_node);

    if (++(cache->usage_count) > cache->cache_size) {
        CacheNode* lru = cache->tail;
        remove_from_list(&(cache->head), lru);
        free_cache_node(lru);
        --(cache->usage_count);
    }

    pthread_mutex_unlock(&cache->lock);
}

void resize_cache(LRUCache* cache, size_t new_size) {
    pthread_mutex_lock(&cache->lock);
    while (cache->usage_count > new_size) {
        CacheNode* lru = cache->tail;
        remove_from_list(&(cache->head), lru);
        free_cache_node(lru);
        --(cache->usage_count);
    }
    cache->cache_size = new_size;
    pthread_mutex_unlock(&cache->lock);
}

void initialize_records(Record records[], size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].offset = rand() % 10000;
        records[i].key = rand() % 1000;
    }
}

void log_event(const char* event) {
    printf("%s\n", event);
}

void manage_records(Record records[], size_t record_count, LRUCache* cache) {
    pthread_t threads[record_count];

    for (size_t i = 0; i < record_count; ++i) {
        if (pthread_create(&threads[i], NULL, (void*)access_cache, (void*)&cache)) {
            log_event("Thread creation failed.");
        }
    }

    for (size_t i = 0; i < record_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    Record records[MAX_RECORDS];
    initialize_records(records, MAX_RECORDS);

    LRUCache* cache = initialize_cache(CACHE_SIZE);
    if (!cache) {
        log_event("Cache initialization failed.");
        return 1;
    }

    manage_records(records, MAX_RECORDS, cache);

    resize_cache(cache, CACHE_SIZE * 2); // Example of resizing

    pthread_mutex_destroy(&cache->lock);
    free(cache);

    return 0;
}
