#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <memory>
#include <random>
#include <algorithm>
#include <chrono>
#include <atomic>
#include <fstream>

struct Task {
    int id;
    std::string description;
    int priority;
    std::chrono::system_clock::time_point deadline;

    bool operator<(const Task& other) const {
        return priority > other.priority; // Higher priority tasks come first
    }
};

class LRUCache {
private:
    struct CacheEntry {
        Task task;
        size_t lastUsedTime;
    };

    std::unordered_map<int, std::list<CacheEntry>::iterator> cacheMap;
    std::list<CacheEntry> itemList;
    const size_t maxSize;

public:
    LRUCache(size_t size) : maxSize(size) {}

    void put(const Task& task) {
        auto it = cacheMap.find(task.id);
        if (it != cacheMap.end()) {
            itemList.erase(it->second);
            cacheMap.erase(it);
        } else if (itemList.size() == maxSize) {
            cacheMap.erase(itemList.back().task.id);
            itemList.pop_back();
        }
        itemList.push_front({task, std::chrono::system_clock::now()});
        cacheMap[task.id] = itemList.begin();
    }

    bool get(int taskId, Task& task) const {
        auto it = cacheMap.find(taskId);
        if (it == cacheMap.end()) return false;
        task = it->second->task;
        return true;
    }
};

class TaskManager {
private:
    std::priority_queue<Task> tasksQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    LRUCache cache;
    size_t maxCacheSize;
    const double resizeThresholdPercentage;
    std::atomic<size_t> taskCount{0};
    std::vector<std::thread> workerThreads;

    void fetchTasksFromExternalService() {
        // Placeholder for fetching tasks from an external service
        // Simulate network delay and variable task formats
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> priorityDist(1, 10);
        std::uniform_int_distribution<> idDist(1, 1000);

        Task task;
        task.id = idDist(gen);
        task.priority = priorityDist(gen);
        task.deadline = std::chrono::system_clock::now() + std::chrono::seconds(priorityDist(gen) * 60);
        task.description = "Task" + std::to_string(task.id);

        {
            std::lock_guard<std::mutex> lock(queueMutex);
            tasksQueue.push(task);
        }
        cv.notify_one();
    }

    void resizeCacheIfNeeded() {
        if (cache.size() > maxCacheSize * resizeThresholdPercentage) {
            cache.resize(maxCacheSize * 2); // Example resizing strategy
        }
    }

    void log(const std::string& message) const {
        std::ofstream logFile("task_manager.log", std::ios_base::app);
        logFile << "[" << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) 
                << "] " << message << std::endl;
    }

public:
    TaskManager(size_t cacheSize, double resizeThreshold)
        : maxCacheSize(cacheSize), resizeThresholdPercentage(resizeThreshold) {
        cache = LRUCache(maxCacheSize);
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            workerThreads.emplace_back(&TaskManager::worker, this);
        }
    }

    ~TaskManager() {
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.detach();
            }
        }
    }

    void startFetchingTasks() {
        std::thread(&TaskManager::fetchTasksFromExternalService, this).detach();
    }

    void worker() {
        while (true) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !tasksQueue.empty(); });
                task = tasksQueue.top();
                tasksQueue.pop();
                resizeCacheIfNeeded();
            }
            log("Task scheduled: " + task.description);
            cache.put(task);
        }
    }

    void monitorQueue() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            size_t currentSize = 0;
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                currentSize = tasksQueue.size();
            }
            if (currentSize > maxCacheSize * 2) { // Example threshold
                log("Alert: Task queue length exceeded limit");
            }
        }
    }

    void startMonitoring() {
        std::thread(&TaskManager::monitorQueue, this).detach();
    }
};

int main() {
    TaskManager manager(10, 0.75);
    manager.startFetchingTasks();
    manager.startMonitoring();

    // Simulate running for some time
    std::this_thread::sleep_for(std::chrono::minutes(1));

    return 0;
}
