// Implement serialization and deserialization functions

size_t serializeUserProfile(UserProfile* profile, uint8_t** output) {
    if (!profile || !output) return 0;

    // Calculate total size needed for serialization
    size_t nameSize = strlen(profile->name) + 1;
    size_t emailSize = strlen(profile->email) + 1;
    size_t paymentMethodSize = profile->paymentCount * sizeof(PaymentMethod);
    size_t addressSize = profile->addressCount * sizeof(ShippingAddress);
    size_t orderHistoryBaseSize = profile->orderCount * sizeof(OrderHistory);
    size_t itemsSize = 0;

    for (size_t i = 0; i < profile->orderCount; ++i) {
        itemsSize += profile->orderHistories[i].itemCount * sizeof(Item);
    }

    size_t totalSize = sizeof(UserProfile) + nameSize + emailSize +
                       paymentMethodSize + addressSize + orderHistoryBaseSize + itemsSize;

    // Allocate memory for serialized data
    *output = (uint8_t*)malloc(totalSize);
    if (!*output) return 0;

    uint8_t* ptr = *output;

    // Serialize each field
    memcpy(ptr, profile->name, nameSize); ptr += nameSize;
    memcpy(ptr, profile->email, emailSize); ptr += emailSize;
    memcpy(ptr, profile->paymentMethods, paymentMethodSize); ptr += paymentMethodSize;
    memcpy(ptr, profile->shippingAddresses, addressSize); ptr += addressSize;

    for (size_t i = 0; i < profile->orderCount; ++i) {
        OrderHistory* order = &profile->orderHistories[i];
        memcpy(ptr, order, sizeof(OrderHistory)); ptr += sizeof(OrderHistory);
        memcpy(ptr, order->items, order->itemCount * sizeof(Item)); ptr += itemsSize;
    }

    return totalSize;
}

bool deserializeUserProfile(const uint8_t* input, size_t length, UserProfile** profile) {
    if (!input || !profile) return false;

    UserProfile* pProfile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!pProfile) return false;

    const uint8_t* ptr = input;

    // Deserialize each field
    memcpy(pProfile->name, ptr, 50); ptr += 50;
    memcpy(pProfile->email, ptr, 100); ptr += 100;

    // Assuming fixed counts for simplicity; in practice, these would be stored and read
    pProfile->paymentMethods = (PaymentMethod*)malloc(2 * sizeof(PaymentMethod));
    pProfile->shippingAddresses = (ShippingAddress*)malloc(2 * sizeof(ShippingAddress));
    pProfile->orderHistories = (OrderHistory*)malloc(2 * sizeof(OrderHistory));

    memcpy(pProfile->paymentMethods, ptr, 2 * sizeof(PaymentMethod)); ptr += 2 * sizeof(PaymentMethod);
    memcpy(pProfile->shippingAddresses, ptr, 2 * sizeof(ShippingAddress)); ptr += 2 * sizeof(ShippingAddress);

    for (size_t i = 0; i < 2; ++i) {
        OrderHistory* order = &pProfile->orderHistories[i];
        memcpy(order, ptr, sizeof(OrderHistory)); ptr += sizeof(OrderHistory);
        order->items = (Item*)malloc(3 * sizeof(Item));
        memcpy(order->items, ptr, 3 * sizeof(Item)); ptr += 3 * sizeof(Item);
    }

    *profile = pProfile;
    return true;
}

// Implement mock database functions

void createUserProfile(const UserProfile* profile) {
    // Simulate creating a user profile in the mock database
    printf("Creating user profile\n");
}

void updateUserProfile(uint64_t userId, const UserProfile* profile) {
    // Simulate updating a user profile in the mock database
    printf("Updating user profile with ID: %llu\n", userId);
}

void deleteUserProfile(uint64_t userId) {
    // Simulate deleting a user profile from the mock database
    printf("Deleting user profile with ID: %llu\n", userId);
}
