#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Structure Definitions
typedef struct {
    uint64_t timestamp;
    char* message;
} Event;

typedef struct {
    int node_id;
    Event** events;
    size_t event_count;
} Node;

#define ALIGNMENT 64

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    if (((uintptr_t)ptr = posix_memalign(&ptr, alignment, size))) {
        ptr = NULL;
    }
#endif
    return ptr;
}

int is_valid_timestamp(uint64_t timestamp) {
    // Example of a valid range: Unix epoch to current time + 10 years
    uint64_t max_timestamp = 1ULL << 63 - 1;
    return (timestamp > 0 && timestamp <= max_timestamp);
}

void initialize_node(Node* node, int id, size_t event_count) {
    if (!node) return;

    node->node_id = id;
    node->events = aligned_alloc(ALIGNMENT, event_count * sizeof(Event*));
    memset(node->events, 0, event_count * sizeof(Event*));

    for (size_t i = 0; i < event_count; ++i) {
        node->events[i] = aligned_alloc(ALIGNMENT, sizeof(Event));
        node->events[i]->timestamp = rand(); // Mock timestamp
        node->events[i]->message = strdup("Default message");

        if (!is_valid_timestamp(node->events[i]->timestamp)) {
            fprintf(stderr, "Invalid timestamp detected!\n");
            free(node->events[i]);
            node->events[i] = NULL;
        }
    }

    node->event_count = event_count;
}

Node** allocate_and_initialize_nodes(size_t num_nodes, size_t* events_per_node) {
    if (!num_nodes || !events_per_node) return NULL;

    Node** nodes = aligned_alloc(ALIGNMENT, num_nodes * sizeof(Node*));
    memset(nodes, 0, num_nodes * sizeof(Node*));

    for (size_t i = 0; i < num_nodes; ++i) {
        if (errno == ENOMEM) {
            fprintf(stderr, "Out of memory\n");
            // Handle memory cleanup
            while (i > 0) { 
                --i;
                free(nodes[i]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i] = aligned_alloc(ALIGNMENT, sizeof(Node));
        initialize_node(nodes[i], i, events_per_node[i]);

        if (!nodes[i]) {
            fprintf(stderr, "Failed to allocate node %zu\n", i);
            // Handle memory cleanup
            while (i > 0) { 
                --i;
                free(nodes[i]);
            }
            free(nodes);
            return NULL;
        }
    }

    return nodes;
}

void deallocate_nodes(Node** nodes, size_t num_nodes) {
    if (!nodes) return;

    for (size_t i = 0; i < num_nodes; ++i) {
        Node* node = nodes[i];
        if (!node) continue;

        for (size_t j = 0; j < node->event_count; ++j) {
            free(node->events[j]->message);
            free(node->events[j]);
        }

        free(node->events);
        free(node);
    }

    free(nodes);
}

int main() {
    size_t num_nodes = 5;
    size_t events_per_node[] = {3, 2, 4, 1, 5};

    Node** nodes = allocate_and_initialize_nodes(num_nodes, events_per_node);

    if (nodes) {
        // Use the allocated nodes
        for (size_t i = 0; i < num_nodes; ++i) {
            printf("Node %zu has %zu events:\n", nodes[i]->node_id, nodes[i]->event_count);
            for (size_t j = 0; j < nodes[i]->event_count; ++j) {
                if (nodes[i]->events[j]) {
                    printf("\tEvent %zu: Time=%llu, Message=%s\n",
                           j, nodes[i]->events[j]->timestamp,
                           nodes[i]->events[j]->message);
                }
            }
        }

        // Deallocate the allocated nodes
        deallocate_nodes(nodes, num_nodes);
    } else {
        fprintf(stderr, "Failed to allocate nodes.\n");
    }

    return 0;
}
