#include <time.h>

#define ALIGNMENT 16
#define MAX_KEYS 1000
#define VALUE_RANGE_LOW 1
#define VALUE_RANGE_HIGH 100

typedef struct {
    int value;
    char log[256];
} Record;

// Helper function to align size to the nearest boundary
size_t align_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

int is_power_of_two(size_t x) {
    return (x != 0) && ((x & (x - 1)) == 0);
}

void* aligned_alloc(size_t alignment, size_t size) {
    if (!is_power_of_two(alignment)) {
        fprintf(stderr, "Alignment must be a power of two\n");
        return NULL;
    }

    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        perror("Failed to allocate aligned memory");
    }
    return ptr;
}

void free_aligned(void* ptr) {
    free(ptr);
}

int generate_unique_key(int keys[], int num_keys, int range) {
    while (1) {
        int key = rand() % range;
        for (int i = 0; i < num_keys; ++i) {
            if (keys[i] == key) return -1; // Collision detected
        }
        return key;
    }
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int allocate_records(Record** records_out, size_t num_records) {
    int* keys = (int*)aligned_alloc(ALIGNMENT, MAX_KEYS * sizeof(int));
    if (!keys) return -1;

    Record* records = (Record*)aligned_alloc(ALIGNMENT, num_records * sizeof(Record));
    if (!records) {
        log_error("Failed to allocate memory for records");
        free_aligned(keys);
        return -1;
    }

    srand(time(NULL));

    int num_keys = 0;
    for (size_t i = 0; i < num_records; ++i) {
        while (num_keys >= MAX_KEYS) {
            log_error("Maximum number of unique keys reached");
            free_aligned(keys);
            free_aligned(records);
            return -1;
        }

        int key = generate_unique_key(keys, num_keys, MAX_KEYS);
        if (key == -1) {
            log_error("Failed to generate a unique key");
            free_aligned(keys);
            free_aligned(records);
            return -1;
        }

        keys[num_keys++] = key;

        records[i].value = VALUE_RANGE_LOW + rand() % (VALUE_RANGE_HIGH - VALUE_RANGE_LOW + 1);
        snprintf(records[i].log, sizeof(records[i].log), "Record for key: %d", key);
    }

    *records_out = records;
    free_aligned(keys);

    return 0; // Success
}

void check_data_integrity(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value < VALUE_RANGE_LOW || records[i].value > VALUE_RANGE_HIGH) {
            log_error("Data corruption detected in record values");
            break;
        }
    }
}

void free_records(Record* records) {
    free_aligned(records);
}

int main() {
    size_t num_records = 100; // Example number of records
    Record* records = NULL;

    if (allocate_records(&records, num_records) == -1) {
        return EXIT_FAILURE;
    }

    check_data_integrity(records, num_records);

    free_records(records);
    return EXIT_SUCCESS;
}
