#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <errno.h>

#define ALIGNMENT 64
#define MAX_MEMORY_USAGE_RATIO 0.5

typedef struct {
    uint64_t timestamp;
    char* message;
} Event;

typedef struct {
    int id;
    Event** events;
    size_t event_count;
    size_t max_events;
    pthread_mutex_t lock;
} Node;

void align_malloc(size_t size, void **ptr) {
    void *p = NULL;
    if (posix_memalign(&p, ALIGNMENT, size)) {
        perror("Memory alignment failed");
        exit(EXIT_FAILURE);
    }
    *ptr = p;
}

int check_memory_usage() {
    // Placeholder for actual memory usage calculation
    return 0; 
}

void log_events_processed(Node* nodes, int node_count) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    for (int i = 0; i < node_count; ++i) {
        printf("Node %d processed %zu events\n", nodes[i].id, nodes[i].event_count);
    }
    pthread_mutex_unlock(&log_mutex);
}

void resize_events(Node* node) {
    size_t new_size = node->max_events * 2;
    Event** new_events = aligned_alloc(ALIGNMENT, new_size * sizeof(Event*));
    if (!new_events) {
        perror("Failed to reallocate memory for events");
        exit(EXIT_FAILURE);
    }
    memcpy(new_events, node->events, node->event_count * sizeof(Event*));
    free(node->events);
    node->events = new_events;
    node->max_events = new_size;
}

Node* initialize_nodes(int node_count, size_t initial_event_capacity) {
    Node* nodes = (Node*)malloc(node_count * sizeof(Node));
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < node_count; ++i) {
        pthread_mutex_init(&nodes[i].lock, NULL);
        nodes[i].id = i;
        nodes[i].event_count = 0;
        nodes[i].max_events = initial_event_capacity;

        align_malloc(initial_event_capacity * sizeof(Event*), (void**)&nodes[i].events);

        for (size_t j = 0; j < initial_event_capacity; ++j) {
            nodes[i].events[j] = NULL;
        }
    }

    return nodes;
}

int verify_integrity(Node* nodes, int node_count) {
    for (int i = 0; i < node_count; ++i) {
        pthread_mutex_lock(&nodes[i].lock);
        for (size_t j = 0; j < nodes[i].event_count; ++j) {
            if (!nodes[i].events[j]) continue;
            if (nodes[i].events[j]->timestamp == 0 || !nodes[i].events[j]->message) {
                pthread_mutex_unlock(&nodes[i].lock);
                return -1; // Integrity check failed
            }
        }
        pthread_mutex_unlock(&nodes[i].lock);
    }
    return 0; // All good
}

void process_node(Node* node, uint64_t timestamp, const char* message) {
    pthread_mutex_lock(&node->lock);

    if (node->event_count >= node->max_events || 
        check_memory_usage() > MAX_MEMORY_USAGE_RATIO * 1024 * 1024 * 1024) { // assuming 1GB as total memory for example
        resize_events(node);
    }

    align_malloc(sizeof(Event), (void**)&(node->events[node->event_count]));
    node->events[node->event_count]->timestamp = timestamp;
    node->events[node->event_count]->message = strdup(message);
    ++node->event_count;

    pthread_mutex_unlock(&node->lock);
}

void free_nodes(Node* nodes, int node_count) {
    for (int i = 0; i < node_count; ++i) {
        pthread_mutex_lock(&nodes[i].lock);
        for (size_t j = 0; j < nodes[i].event_count; ++j) {
            if (nodes[i].events[j]) {
                free(nodes[i].events[j]->message);
                free(nodes[i].events[j]);
            }
        }
        free(nodes[i].events);
        pthread_mutex_unlock(&nodes[i].lock);
    }

    for (int i = 0; i < node_count; ++i) {
        pthread_mutex_destroy(&nodes[i].lock);
    }

    free(nodes);
}
