void free_resources(long **longArray, size_t longSize,
                    double *doubleArray, size_t doubleSize,
                    char **stringArray, unsigned int *uintArray, size_t structSize,
                    int *intKeys, Record **records, size_t recordSize) {
    for (size_t i = 0; i < longSize; ++i) free(longArray[i]);
    free(longArray);

    free(doubleArray);

    for (size_t i = 0; i < structSize; ++i) {
        free(stringArray[i]);
    }
    free(stringArray);
    free(uintArray);

    free(intKeys);

    for (size_t i = 0; i < recordSize; ++i) {
        free(records[i]->identifier);
        if (records[i]->item_ptr->data.cPointer)
            free(records[i]->item_ptr->data.cPointer);
        free(records[i]->item_ptr);
        free(records[i]);
    }
    free(records);
}

void manage_memory_allocation(int longCount, int doubleCount, int structCount, int keyCount, int recordCount) {
    if (longCount <= 0 || doubleCount <= 0 || structCount <= 0 ||
        keyCount <= 0 || recordCount <= 0) {
        fprintf(stderr, "Invalid input sizes.\n");
        return;
    }

    size_t totalMemory = 0;

    long **longArray = malloc(longCount * sizeof(long *));
    if (!longArray) { perror("Failed to allocate memory for long array"); exit(EXIT_FAILURE); }
    for (int i = 0; i < longCount; ++i) {
        longArray[i] = malloc(sizeof(long));
        totalMemory += sizeof(long);
    }

    double *doubleArray = malloc(doubleCount * sizeof(double));
    if (!doubleArray) { free_resources(&longArray, longCount, NULL, 0, NULL, NULL, 0, NULL, NULL, 0); perror("Failed to allocate memory for doubles"); exit(EXIT_FAILURE); }
    totalMemory += doubleCount * sizeof(double);

    char **stringArray = malloc(structCount * sizeof(char *));
    if (!stringArray) { free_resources(&longArray, longCount, &doubleArray, doubleCount, NULL, NULL, 0, NULL, NULL, 0); perror("Failed to allocate memory for strings"); exit(EXIT_FAILURE); }
    unsigned int *uintArray = malloc(structCount * sizeof(unsigned int));
    if (!uintArray) { free_resources(&longArray, longCount, &doubleArray, doubleCount, &stringArray, NULL, structCount, NULL, NULL, 0); perror("Failed to allocate memory for uints"); exit(EXIT_FAILURE); }
    for (int i = 0; i < structCount; ++i) {
        stringArray[i] = strdup(STRING_CONSTANT);
        totalMemory += strlen(STRING_CONSTANT) + 1;
        uintArray[i] = rand() % (UINT_RANGE_MAX - UINT_RANGE_MIN + 1) + UINT_RANGE_MIN;
    }

    int *intKeys = malloc(keyCount * sizeof(int));
    if (!intKeys) { free_resources(&longArray, longCount, &doubleArray, doubleCount, &stringArray, &uintArray, structCount, NULL, NULL, 0); perror("Failed to allocate memory for keys"); exit(EXIT_FAILURE); }
    totalMemory += keyCount * sizeof(int);

    Record **records = malloc(recordCount * sizeof(Record *));
    if (!records) { free_resources(&longArray, longCount, &doubleArray, doubleCount, &stringArray, &uintArray, structCount, &intKeys, NULL, 0); perror("Failed to allocate memory for records"); exit(EXIT_FAILURE); }
    for (int i = 0; i < recordCount; ++i) {
        records[i] = malloc(sizeof(Record));
        snprintf(records[i]->identifier, sizeof(records[i]->identifier), "ID_%d", i);
        time(&records[i]->current_time);
        strncpy(records[i]->prefix, "UserPrefix_", sizeof(records[i]->prefix) - 1);
        Item *item = malloc(sizeof(Item));
        item->size = sizeof(double); // Example
        item->data.dValue = (double)i;
        records[i]->item_ptr = item;
        totalMemory += sizeof(Record) + strlen(records[i]->identifier) + sizeof(item);
    }

    if (totalMemory > MEMORY_LIMIT) {
        fprintf(stderr, "Exceeded memory limit. Releasing resources...\n");
        free_resources(&longArray, longCount, &doubleArray, doubleCount, &stringArray, &uintArray, structCount, &intKeys, records, recordCount);
        return;
    }

    // Simulate work
    printf("Memory allocation successful.\n");

    // Free resources at the end
    free_resources(&longArray, longCount, &doubleArray, doubleCount, &stringArray, &uintArray, structCount, &intKeys, records, recordCount);
}

