#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import stdatomic
#include <pthread.h>
#include <time.h>

#define LOG_BUFFER_SIZE 1024
#define ALIGNMENT 256

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} log_severity_t;

typedef struct {
    atomic_int ref_count;
    pthread_mutex_t lock;
    char *buffer;
    size_t capacity;
    size_t used;
    time_t timestamp;
    log_severity_t severity;
    char message[256];
    char metadata[128];
} LogEntry;

// Align a pointer to the specified alignment
void* align_pointer(void *ptr, size_t alignment) {
    uintptr_t addr = (uintptr_t)ptr;
    return (void*)((addr + alignment - 1) & ~(alignment - 1));
}

LogEntry* create_log_entry() {
    LogEntry *entry = aligned_alloc(ALIGNMENT, sizeof(LogEntry));
    if (!entry) return NULL;

    pthread_mutex_init(&entry->lock, NULL);
    entry->buffer = aligned_alloc(ALIGNMENT, LOG_BUFFER_SIZE);
    if (!entry->buffer) {
        free(entry);
        return NULL;
    }

    atomic_store(&entry->ref_count, 1);
    entry->capacity = LOG_BUFFER_SIZE;
    entry->used = 0;

    return entry;
}

void destroy_log_entry(LogEntry *entry) {
    if (!entry) return;

    pthread_mutex_destroy(&entry->lock);
    free(entry->buffer);
    atomic_fetch_sub(&entry->ref_count, 1);
    free(entry);
}

int log_message(LogEntry **entries, size_t max_entries, log_severity_t severity, const char *message, const char *metadata) {
    time_t now = time(NULL);
    if (now == ((time_t)-1)) return -1; // Timestamp error

    LogEntry *new_entry = create_log_entry();
    if (!new_entry) return -2; // Memory allocation failure

    pthread_mutex_lock(&new_entry->lock);
    new_entry->timestamp = now;
    new_entry->severity = severity;
    strncpy(new_entry->message, message, sizeof(new_entry->message) - 1);
    strncpy(new_entry->metadata, metadata, sizeof(new_entry->metadata) - 1);

    if (entries == NULL || atomic_load(&entries[0]->ref_count) < max_entries) {
        for (size_t i = 0; i < max_entries && entries[i]; ++i) {
            if (atomic_load(&entries[i]->ref_count) <= 0) {
                entries[i] = new_entry;
                pthread_mutex_unlock(&new_entry->lock);
                return 0;
            }
        }
    }

    pthread_mutex_unlock(new_entry->lock);
    destroy_log_entry(new_entry);
    return -3; // No available space
}

void print_logs(LogEntry **entries, size_t max_entries) {
    for (size_t i = 0; i < max_entries; ++i) {
        if (!entries[i]) continue;

        pthread_mutex_lock(&entries[i]->lock);
        printf("Timestamp: %ld\n", entries[i]->timestamp);
        printf("Severity: %d\n", entries[i]->severity);
        printf("Message: %s\n", entries[i]->message);
        printf("Metadata: %s\n", entries[i]->metadata);
        pthread_mutex_unlock(&entries[i]->lock);
    }
}

int main() {
    const size_t max_entries = 10;
    LogEntry *log_entries[max_entries] = {0};

    log_message(log_entries, max_entries, LOG_INFO, "Server started", "Instance-1");
    log_message(log_entries, max_entries, LOG_WARNING, "High memory usage detected", "Instance-2");

    print_logs(log_entries, max_entries);

    for (size_t i = 0; i < max_entries; ++i) {
        if (log_entries[i]) {
            destroy_log_entry(log_entries[i]);
        }
    }

    return 0;
}
