void initialize_records(Record **records, KeyOffsetPair **key_offset_pairs, int *record_count, int key_range, int offset_boundary, int debug, int external_data_source_status) {
    if (!records || !key_offset_pairs || !record_count) {
        fprintf(stderr, "Invalid input pointers.\n");
        return;
    }

    // Calculate memory size requirements
