    void *memory_block = memalign(offset_boundary, total_size);
    if (!memory_block) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Cast the allocated memory to the appropriate types
    char *ptr = (char *)memory_block;
    *records = (Record *)(ptr);
    *key_offset_pairs = (KeyOffsetPair *)(ptr + sizeof(Record) * (*record_count));

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize the key and offset pairs
    for (int i = 0; i < *record_count; ++i) {
        (*key_offset_pairs)[i].key = rand() % key_range;
        (*key_offset_pairs)[i].offset = i * 1024; // Example offset calculation
    }

    // Initialize the records with random values within a specified range
    for (int i = 0; i < *record_count; ++i) {
        (*records)[i].value = rand() % key_range;
    }

    // Fetch additional data from an external source if available
    if (external_data_source_status) {
        // Simulate fetching additional data
        for (int i = 0; i < *record_count; ++i) {
            // Placeholder for fetching data from an external source
            (*key_offset_pairs)[i].offset += rand() % 512; // Random adjustment based on external data
        }
    }

    // Verify integrity by checking for zero-initialized memory regions
    for (int i = 0; i < *record_count; ++i) {
        if ((*records)[i].value == 0 || (*key_offset_pairs)[i].offset == 0) {
            fprintf(stderr, "Integrity check failed at index %d\n", i);
        }
    }

    // Debug information
    if (debug) {
        printf("Records initialized with count: %d\n", *record_count);
        for (int i = 0; i < *record_count; ++i) {
            printf("Record %d: Value = %d, Key = %d, Offset = %ld\n",
                   i, (*records)[i].value, (*key_offset_pairs)[i].key, (*key_offset_pairs)[i].offset);
        }
    }

    // Free the allocated memory block
    free(memory_block);
