#define ALIGNMENT 128

typedef enum {
    ELECTRONICS,
    CLOTHING,
    GROCERIES
} Category;

typedef struct stock_item {
    Category category;
    int quantity;
    float price;
    char *description;
    struct stock_item *prev;
    struct stock_item *next;
} StockItem;

StockItem* create_stock_item(Category category, int quantity, float market_index) {
    void *ptr = NULL;
    size_t offset = (ALIGNMENT - sizeof(StockItem)) % ALIGNMENT;
    ptr = aligned_alloc(ALIGNMENT, sizeof(StockItem) + offset);

    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    StockItem *item = (StockItem *)((uintptr_t)ptr + offset);
    item->category = category;
    item->quantity = quantity;
    item->price = market_index * 10.0; // Example pricing model

    char description_template[] = "Category: %s, Quantity: %d, Market Index: %.2f";
    size_t desc_len = snprintf(NULL, 0, description_template,
                               category == ELECTRONICS ? "Electronics" :
                               (category == CLOTHING ? "Clothing" : "Groceries"),
                               quantity, market_index) + 1;

    item->description = aligned_alloc(ALIGNMENT, desc_len);
    if (!item->description) {
        fprintf(stderr, "Memory allocation for description failed\n");
        free(ptr);
        return NULL;
    }

    snprintf(item->description, desc_len,
             description_template,
             category == ELECTRONICS ? "Electronics" :
             (category == CLOTHING ? "Clothing" : "Groceries"),
             quantity, market_index);

    item->prev = item->next = NULL;

    return item;
}

void destroy_stock_item(StockItem *item) {
    if (item) {
        free(item->description);
        void *ptr = ((uintptr_t)item - ((uintptr_t)item % ALIGNMENT));
        free(ptr);
    }
}

StockItem* add_item_to_list(StockItem **head, StockItem *new_item) {
    if (!head || !new_item)
        return NULL;

    new_item->next = *head;
    if (*head) {
        (*head)->prev = new_item;
    }

    *head = new_item;
    return *head;
}

void remove_item_from_list(StockItem **head, StockItem *item_to_remove) {
    if (!head || !*head || !item_to_remove)
        return;

    if (item_to_remove->prev) {
        item_to_remove->prev->next = item_to_remove->next;
    } else {
        *head = item_to_remove->next;
    }

    if (item_to_remove->next) {
        item_to_remove->next->prev = item_to_remove->prev;
    }
}

