#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define structure for metadata
typedef struct {
    size_t size;
    size_t alignment;
} Metadata;

// Structure definition for a record
typedef struct {
    int value;
} Record;

// Alignment helper function
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_POSIX_C_SOURCE) || defined(__APPLE__)
    ptr = memalign(alignment, size);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // posix_memalign returns 0 on success
    }
#endif
    if (!ptr) {
        fprintf(stderr, "Aligned allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to generate a random int within a specified range
int generate_random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Thread-safe data structure manager
typedef struct {
    long *offsets; 
    size_t num_offsets;

    int *keys; 
    size_t num_keys;

    Record *records; 
    size_t num_records;

    Metadata *metadata;

    pthread_mutex_t lock;
} DataStructureManager;

DataStructureManager* create_data_structure_manager(size_t num_offsets, size_t num_keys, size_t num_records) {
    DataStructureManager *manager = malloc(sizeof(DataStructureManager));
    if (!manager) return NULL;

    manager->offsets = aligned_alloc(16, sizeof(long) * num_offsets);
    for (size_t i = 0; i < num_offsets; ++i) {
        manager->offsets[i] = (long)i;
    }

    // Allocate and initialize unique keys
    manager->keys = malloc(sizeof(int) * num_keys);
    if (!manager->keys) return NULL;

    int *visited = calloc(100, sizeof(int));  // Assumed range for uniqueness check
    size_t idx;
    for (idx = 0; idx < num_keys; ++idx) {
        int key;
        do {
            key = rand() % 100;
        } while (visited[key]);
        manager->keys[idx] = key;
        visited[key] = 1;
    }
    free(visited);

    // Allocate and initialize records with random numbers
    manager->records = aligned_alloc(sizeof(int), sizeof(Record) * num_records);
    if (!manager->records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        manager->records[i].value = generate_random_int(1, 100);
    }

    // Initialize metadata
    manager->metadata = malloc(sizeof(Metadata) * 4);  // Four data structures
    if (!manager->metadata) return NULL;

    manager->metadata[0] = (Metadata){.size = num_offsets * sizeof(long), .alignment = 16};
    manager->metadata[1] = (Metadata){.size = num_keys * sizeof(int), .alignment = sizeof(int)};
    manager->metadata[2] = (Metadata){.size = num_records * sizeof(Record), .alignment = sizeof(Record)};
    manager->metadata[3] = (Metadata){.size = 0, .alignment = 0};  // Placeholder for future metadata

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void free_data_structure_manager(DataStructureManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    if (manager->offsets) free(manager->offsets);
    if (manager->keys) free(manager->keys);
    if (manager->records) free(manager->records);
    if (manager->metadata) free(manager->metadata);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    srand((unsigned int)time(NULL));
    size_t num_offsets = 100;
    size_t num_keys = 50;
    size_t num_records = 75;

    DataStructureManager *manager = create_data_structure_manager(num_offsets, num_keys, num_records);
    if (!manager) {
        fprintf(stderr, "Failed to create data structure manager\n");
        return EXIT_FAILURE;
    }

    // Demonstrate thread-safe access
    pthread_mutex_lock(&manager->lock);
    printf("First key: %d\n", manager->keys[0]);
    pthread_mutex_unlock(&manager->lock);

    free_data_structure_manager(manager);
    return 0;
}
