- **Uniqueness of Keys**: Implemented by checking a visited array to ensure all keys are unique within a given range.

- **Random Record Values**: Initialized using a simple random number generator function.

- **Concurrency**: A mutex (`pthread_mutex_t`) is used to manage concurrent access, preventing race conditions during data structure operations.

- **Memory Management**: Functions to allocate and free memory dynamically while handling allocation failures gracefully.

- **Metadata Storage**: Metadata for each data structure is stored in an array to keep track of size and alignment.

This implementation provides a basic framework that can be expanded or optimized further depending on specific use cases, such as using more sophisticated synchronization techniques or exploring memory-mapped files for very large datasets.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    short value;
    char identifier;
    float *dynamicFloat;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t num_records;
    pthread_mutex_t lock;
    int total_allocations;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_capacity) {
    if (initial_capacity > MAX_RECORDS) return NULL;

    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offsets = (long *)calloc(initial_capacity, sizeof(long));
    manager->keys = (int *)calloc(initial_capacity, sizeof(int));
    manager->records = (Record *)calloc(initial_capacity, sizeof(Record));

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->records[i].dynamicFloat = (float*)malloc(sizeof(float));
        if (!manager->records[i].dynamicFloat) {
            // Handle allocation failure
            free(manager->offsets);
            free(manager->keys);
            for (size_t j = 0; j < i; ++j) {
                free(manager->records[j].dynamicFloat);
            }
            free(manager->records);
            free(manager);
            return NULL;
        }
    }

    manager->num_records = initial_capacity;
    manager->total_allocations = initial_capacity * (1 + sizeof(float));

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_records; ++i) {
        free(manager->records[i].dynamicFloat);
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);

    free(manager);
}

int resize_memory_manager(MemoryManager *manager, size_t new_capacity) {
    if (!manager || new_capacity > MAX_RECORDS) return -1;

    pthread_mutex_lock(&manager->lock);

    long *new_offsets = (long *)realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(manager->keys, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Record *new_records = (Record *)realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) {
        free(new_offsets);
        free(new_keys);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = manager->num_records; i < new_capacity; ++i) {
        new_records[i].dynamicFloat = (float*)malloc(sizeof(float));
        if (!new_records[i].dynamicFloat) {
            // Handle allocation failure
            while (i > 0) free(new_records[--i].dynamicFloat);
            free(new_offsets);
            free(new_keys);
            free(new_records);
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->num_records = new_capacity;

    manager->total_allocations += (new_capacity - manager->num_records) * (1 + sizeof(float));

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int add_record(MemoryManager *manager, long offset, int key, short value, char identifier, float floatValue) {
    if (!manager || manager->num_records >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t current_capacity = manager->num_records;

    if (current_capacity == 0 || (long)(current_capacity * 1.5) > current_capacity) {
        int resize_result = resize_memory_manager(manager, (size_t)(current_capacity * 1.5));
        if (resize_result != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->offsets[manager->num_records] = offset;
    manager->keys[manager->num_records] = key;

    manager->records[manager->num_records].value = value;
    manager->records[manager->num_records].identifier = identifier;
    *(manager->records[manager->num_records].dynamicFloat) = floatValue;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int serialize_memory_manager(const MemoryManager *manager, const char *filename) {
    if (!manager || !filename) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&(manager->num_records), sizeof(size_t), 1, file);
    fwrite(manager->offsets, sizeof(long), manager->num_records, file);
    fwrite(manager->keys, sizeof(int), manager->num_records, file);

    for (size_t i = 0; i < manager->num_records; ++i) {
        fwrite(&(manager->records[i].value), sizeof(short), 1, file);
        fwrite(&(manager->records[i].identifier), sizeof(char), 1, file);
        float *dynamicFloat = manager->records[i].dynamicFloat;
        if (dynamicFloat) {
            fwrite(dynamicFloat, sizeof(float), 1, file);
        }
    }

    fclose(file);
    return 0;
}

int deserialize_memory_manager(MemoryManager **manager, const char *filename) {
    if (!manager || !filename) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, file);

    MemoryManager *new_manager = create_memory_manager(num_records);
    if (!new_manager) {
        fclose(file);
        return -1;
    }

    fread(new_manager->offsets, sizeof(long), num_records, file);
    fread(new_manager->keys, sizeof(int), num_records, file);

    for (size_t i = 0; i < num_records; ++i) {
        fread(&(new_manager->records[i].value), sizeof(short), 1, file);
        fread(&(new_manager->records[i].identifier), sizeof(char), 1, file);
        float floatValue;
        fread(&floatValue, sizeof(float), 1, file);
        *(new_manager->records[i].dynamicFloat) = floatValue;
    }

    fclose(file);

    *manager = new_manager;
    return 0;
}

void log_memory_usage(const MemoryManager *manager) {
    if (!manager) return;

    printf("Memory Usage:\n");
    printf("Number of Records: %zu\n", manager->num_records);
    printf("Total Allocations: %d\n", manager->total_allocations);
}
