#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include <curl/curl.h>

typedef struct {
    int min;
    int max;
    int inclusive_min;
    int inclusive_max;
} Range;

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t count;
    pthread_mutex_t mutex;
} ResourceCoordinator;

#define POOL_SIZE 1024
long memory_pool[POOL_SIZE];
size_t pool_index = 0;

void* allocate_memory(size_t size) {
    if (pool_index + size > POOL_SIZE) return NULL; // Out of memory
    void *ptr = &memory_pool[pool_index];
    pool_index += size;
    return ptr;
}

void deallocate_memory(void) {
    pool_index = 0; // Simple reset, assuming only one allocator
}

int random_in_range(int min, int max) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    srand(tv.tv_usec ^ (tv.tv_sec << 16));
    return rand() % (max - min + 1) + min;
}

void merge_ranges(Range *ranges, size_t count) {
    // Simplified merging logic
    if (count < 2) return;

    qsort(ranges, count, sizeof(Range), [](const void* a, const void* b) {
        Range *rangeA = (Range *)a;
        Range *rangeB = (Range *)b;
        return rangeA->min - rangeB->min;
    });

    for (size_t i = 0; i < count - 1;) {
        Range current = ranges[i];
        if ((current.max >= ranges[i + 1].min && 
             (!current.inclusive_max || (current.max > ranges[i + 1].min))) ||
            (current.inclusive_max && current.max == ranges[i + 1].min)) {
            current.max = ranges[i + 1].max;
            current.inclusive_max = (ranges[i + 1].inclusive_max && 
                                     (!current.inclusive_max || current.max > ranges[i + 1].min));
            i++;
        }
        ranges[i] = current;
    }
}

void split_ranges(Range *ranges, size_t count) {
    // Simplified splitting logic
    for (size_t i = 0; i < count;) {
        Range current = ranges[i];
        if (current.max - current.min > 10) { // Example split condition
            Range newRange;
            newRange.min = current.min;
            newRange.max = (current.min + current.max) / 2;
            newRange.inclusive_min = current.inclusive_min;
            newRange.inclusive_max = !newRange.inclusive_max;

            ranges[i] = newRange;
            newRange.min += 1;
            newRange.inclusive_min = !newRange.inclusive_min;
            memcpy(&ranges[i + 1], &newRange, sizeof(Range));
            i += 2; // Move past the newly created range
        } else {
            i++;
        }
    }
}

void setup_logging() {
    // Placeholder for logging setup
}

void log_message(const char *message) {
    printf("%s\n", message);
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userp) {
    return size * nmemb;
}

void send_log_data(const char* data) {
    CURL *curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/log");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(data));
        curl_easy_setopt(curl, CURLOPT_COPYPOSTFIELDS, data);
        CURLcode res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }
}

void ResourceCoordinator_init(ResourceCoordinator *rc, size_t count) {
    rc->offsets = (long*) allocate_memory(count * sizeof(long));
    rc->keys = (int*) allocate_memory(count * sizeof(int));
    rc->records = (Record*) allocate_memory(count * sizeof(Record));
    rc->count = count;
    pthread_mutex_init(&rc->mutex, NULL);
}

void ResourceCoordinator_cleanup(ResourceCoordinator *rc) {
    deallocate_memory();
    pthread_mutex_destroy(&rc->mutex);
}

void fill_records(ResourceCoordinator *rc, Range ranges[], size_t range_count) {
    pthread_mutex_lock(&rc->mutex);

    for (size_t i = 0; i < rc->count; ++i) {
        int min = ranges[i % range_count].min;
        int max = ranges[i % range_count].max;

        struct timeval start, end;
        gettimeofday(&start, NULL);

        rc->records[i].value = random_in_range(min, max);

        gettimeofday(&end, NULL);
        long elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

        if (elapsed_us > 2000) {
            log_message("Random generation took longer than expected");
        }
    }

    pthread_mutex_unlock(&rc->mutex);
}

void ResourceCoordinator_manage(ResourceCoordinator *rc, Range ranges[], size_t range_count) {
    merge_ranges(ranges, range_count);
    split_ranges(ranges, range_count);

    fill_records(rc, ranges, range_count);

    char log_data[256];
    snprintf(log_data, sizeof(log_data), "Managed %zu records", rc->count);
    send_log_data(log_data);
}

void stress_test(ResourceCoordinator *rc) {
    pthread_t threads[100];

    for (int i = 0; i < 100; ++i) {
        pthread_create(&threads[i], NULL, (void*) ResourceCoordinator_manage, rc);
    }

    for (int i = 0; i < 100; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    setup_logging();

    ResourceCoordinator rc;
    Range ranges[] = {{0, 10, 1, 1}, {5, 15, 1, 0}};
    size_t range_count = sizeof(ranges) / sizeof(Range);

    ResourceCoordinator_init(&rc, 100);

    stress_test(&rc);

    ResourceCoordinator_cleanup(&rc);
    return 0;
}
