long largest_integer(int *data, size_t count) {
    if (count == 0) return -1; // or some appropriate error indication
    long max = data[0];
    for (size_t i = 1; i < count; ++i) {
        if (data[i] > max) {
            max = data[i];
        }
    }
    return max;
}

void process_and_analyze_numbers(const char *filename, int num_offsets, int num_keys, int min_val, int max_val) {
    srand(time(NULL));

    // Allocate memory dynamically
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        log_error("Memory allocation failed for offsets.");
        return;
    }

    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        log_error("Memory allocation failed for keys.");
        return;
    }

    record *records = (record *)malloc(num_offsets * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        log_error("Memory allocation failed for records.");
        return;
    }

    // Initialize records with random values within the specified range
    for (int i = 0; i < num_offsets; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open file.");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    int *input_data = NULL;
    size_t data_size = 0;

    // Efficiently read integers from the file
    while (1) {
        int temp;
        if (fscanf(file, "%d", &temp) != 1) {
            if (!feof(file)) {
                log_error("Failed to read integer from file.");
            }
            break;
        }

        input_data = (int *)realloc(input_data, (data_size + 1) * sizeof(int));
        if (!input_data) {
            log_error("Memory reallocation failed during reading input data.");
            fclose(file);
            free(records);
            free(keys);
            free(offsets);
            return;
        }

        input_data[data_size++] = temp;
    }

    fclose(file);

    if (data_size > 0) {
        long max_value = largest_integer(input_data, data_size);
        printf("Largest integer found: %ld\n", max_value);
    } else {
        log_error("No integers read from the file.");
    }

    // Free allocated resources
    free(input_data);
    free(records);
    free(keys);
    free(offsets);
}
