static int validate_mac_address(const uint8_t *mac, const uint8_t **backup_macs, size_t backup_size);
static uint16_t generate_vlan_tag(uint16_t seed);

NICBManager* initialize_nicbs(size_t nicb_count, InterfaceType interface_type,
                             uint16_t init_seed, const uint8_t **backup_macs, size_t backup_size) {
    if (interface_type != GIGABIT && interface_type != FAST_ETH && interface_type != WIRELESS) {
        log_message("Unsupported interface type.");
        return NULL;
    }

    NICBManager *manager = malloc(sizeof(NICBManager));
    if (!manager) {
        log_message("Memory allocation for manager failed.");
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    manager->count = 0;
    manager->failed_mac_validations = 0;

    manager->nicb_array = malloc(sizeof(NICB) * nicb_count);
    if (!manager->nicb_array) {
        log_message("Memory allocation for NICB array failed.");
        free(manager);
        return NULL;
    }

    pthread_t threads[MAX_NICB];
    size_t thread_count = (nicb_count < MAX_NICB) ? nicb_count : MAX_NICB;

    srand(init_seed);

    for (size_t i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, populate_nicb, (void*)(manager + i)) != 0) {
            log_message("Thread creation failed.");
        }
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    manager->count = nicb_count;
    return manager;
}

static void* populate_nicb(void *arg) {
    NICBManager *manager = (NICBManager*)arg;
    size_t index = (size_t)arg - sizeof(NICBManager);

    for (int retries = 0; retries < RETRY_LIMIT; ++retries) {
        // Random MAC address generation or retrieval logic
        uint8_t mac[6] = {0}; // Example placeholder MAC
        if (!nms_validate_mac(mac)) {
            if (!validate_mac_address(mac, manager->backup_macs, manager->backup_size)) {
                pthread_mutex_lock(&manager->mutex);
                manager->failed_mac_validations++;
                pthread_mutex_unlock(&manager->mutex);

                log_message("All backup MAC addresses failed.");
                return NULL; // Skip this NICB
            }
        }

        manager->nicb_array[index].mac_header.dst[0] = mac[0];  // Example assignment
        manager->nicb_array[index].mac_header.src[0] = mac[5];

        manager->nicb_array[index].vlan_tag = generate_vlan_tag(1234); // Seed example

        break; // Exit retry loop on success
    }

    return NULL;
}

static int validate_mac_address(const uint8_t *mac, const uint8_t **backup_macs, size_t backup_size) {
    for (size_t i = 0; i < backup_size; ++i) {
        if (nms_validate_mac(backup_macs[i])) {
            memcpy(mac, backup_macs[i], 6);
            return 1;
        }
    }
    return 0;
}

static uint16_t generate_vlan_tag(uint16_t seed) {
    srand(seed);
    return rand() & 0xFFF; // Generate VLAN tag
}

void log_message(const char *message) {
    printf("Log: %s\n", message); // Simple logging to console
}
