#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure representing a record in the resource management system.
typedef struct ResourceRecord {
    int key;
    double value;
    char *name; // Dynamically allocated string
    struct ResourceRecord *next; // Pointer to next record, forming a singly linked list
} ResourceRecord;

#define ALIGNMENT 16

// Function to allocate memory with alignment.
void* aligned_alloc(size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, ALIGNMENT);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        ptr = NULL; // posix_memalign returns non-zero on failure
    }
#else
    #error "Platform not supported for aligned allocation"
#endif
    return ptr;
}

// Function to free the allocated memory with alignment.
void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    free(ptr);
#else
    #error "Platform not supported for freeing aligned allocation"
#endif
}

// Function to initialize a ResourceRecord, with error checking and memory alignment.
ResourceRecord* init_resource_record(int key, double value, const char *name) {
    // Allocate the resource record structure
    ResourceRecord *record = (ResourceRecord *)aligned_alloc(sizeof(ResourceRecord), ALIGNMENT);
    if (!record) {
        fprintf(stderr, "Memory allocation failed for ResourceRecord\n");
        return NULL;
    }

    // Initialize fields of the record
    record->key = key;
    record->value = value;

    // Allocate and copy the name string with alignment
    size_t len = strlen(name) + 1; // Include space for null-terminator
    record->name = (char *)aligned_alloc(len, ALIGNMENT);
    if (!record->name) {
        fprintf(stderr, "Memory allocation failed for ResourceRecord's name\n");
        aligned_free(record);
        return NULL;
    }

    strncpy(record->name, name, len);

    // Initialize the next pointer to NULL
    record->next = NULL;

    return record;
}

// Function to verify the integrity of a single resource record.
int verify_resource_record(ResourceRecord *record) {
    if (!record)
        return 0; // Null record is not valid

    if (record->key == 0 && strcmp(record->name, "") == 0 && record->value == 0.0)
        return 1;

    if (!record->name || !*record->name) {
        fprintf(stderr, "Invalid or empty name in ResourceRecord\n");
        return 0;
    }

    // Further integrity checks can be added as needed
    return 1;
}

// Function to verify the linked list of resource records.
int verify_resource_list(ResourceRecord *head) {
    if (!head)
        return 0; // An empty list is not considered valid

    ResourceRecord *current = head;
    while (current) {
        if (!verify_resource_record(current)) {
            fprintf(stderr, "Integrity check failed for ResourceRecord\n");
            return 0;
        }
        current = current->next;
    }

    return 1; // All records verified successfully
}

// Function to free the entire linked list of resource records.
void free_resource_list(ResourceRecord *head) {
    while (head) {
        ResourceRecord *temp = head;
        head = head->next;

        aligned_free(temp->name);
        aligned_free(temp);
    }
}
