void align_to_boundary(void **ptr, size_t alignment) {
    uintptr_t address = (uintptr_t)(*ptr);
    if ((address % alignment) != 0) {
        address += alignment - (address % alignment);
    }
    *ptr = (void *)address;
}

node* allocate_node(size_t array_size) {
    node *n = (node*)aligned_alloc(ALIGNMENT, sizeof(node));
    align_to_boundary((void**)&(n->array), ALIGNMENT);
    n->array = (int*)malloc(array_size * sizeof(int));
    if (!n || !n->array) {
        free(n ? n : NULL);
        return NULL;
    }
    n->head = NULL; // Initialize linked list head
    n->array_size = array_size;
    return n;
}

void initialize_node(node *n, double min_val, double max_val) {
    n->value = (double)(rand() / (RAND_MAX / (max_val - min_val)) + min_val);
