['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define ALIGNMENT 64
#define MAX_NODES 1000
#define MAX_ITEMS 100

typedef struct Item {
    int key;
    char *string;
    union {
        struct Item *metadata_ptr;
        short metadata_value;
    };
} Item;

typedef struct Node {
    double value;
    Item *items;
    size_t item_count;
    int *int_array;
    size_t array_size;
    struct Node *next;
} Node;

typedef struct Record {
    int values[10]; // Adjust as necessary
} Record;

typedef struct DataPipeline {
    long *offsets;
    size_t offset_count;
    int *keys;
    size_t key_count;
    Record *records;
    size_t record_count;
    Node **nodes;
    size_t node_count;
    pthread_mutex_t lock;
    uint64_t checksum;
} DataPipeline;

// Alignment macro
#define ALIGNED_ALLOC(size) \
    _aligned_malloc((size), ALIGNMENT)

// Logging function
void log_message(const char *message) {
    printf("%s\n", message); // Replace with more sophisticated logging if needed
}

// Memory allocation with error handling and alignment
void* safe_aligned_alloc(size_t size, const char *context) {
    void *ptr = ALIGNED_ALLOC(size);
    if (!ptr) {
        log_message("Memory allocation failed for: ");
        fprintf(stderr, "%s\n", context);
        exit(EXIT_FAILURE); // Graceful exit or fallback strategy can be implemented here
    }
    return ptr;
}

// Simple checksum function
uint64_t calculate_checksum(void *data, size_t size) {
    uint8_t *bytes = (uint8_t*) data;
    uint64_t checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum += bytes[i];
    }
    return checksum;
}

// Function to initialize the DataPipeline
DataPipeline* init_data_pipeline(size_t offset_count, size_t key_count, size_t record_count, size_t node_count) {
    if (node_count > MAX_NODES || key_count > MAX_ITEMS || offset_count > MAX_ITEMS) {
        log_message("Exceeded maximum allowed number of nodes or items");
        return NULL;
    }

    DataPipeline *pipeline = safe_aligned_alloc(sizeof(DataPipeline), "DataPipeline");

    pipeline->offsets = safe_aligned_alloc(offset_count * sizeof(long), "offsets");
    pipeline->keys = safe_aligned_alloc(key_count * sizeof(int), "keys");
    pipeline->records = safe_aligned_alloc(record_count * sizeof(Record), "records");
    pipeline->nodes = safe_aligned_alloc(node_count * sizeof(Node*), "nodes");

    memset(pipeline->nodes, 0, node_count * sizeof(Node*));

    pthread_mutex_init(&pipeline->lock, NULL);

    // Initialize checksum
    pipeline->checksum = calculate_checksum(pipeline, sizeof(DataPipeline));

    return pipeline;
}

// Function to clean up the DataPipeline
void cleanup_data_pipeline(DataPipeline *pipeline) {
    if (!pipeline) return;

    free(pipeline->offsets);
    free(pipeline->keys);
    free(pipeline->records);

    for (size_t i = 0; i < MAX_NODES && pipeline->nodes[i]; ++i) {
        Node *node = pipeline->nodes[i];
        free(node->items);
        free(node->int_array);
        free(node);
    }

    free(pipeline->nodes);
    pthread_mutex_destroy(&pipeline->lock);
    _aligned_free(pipeline);
}

// Thread-safe function to add a node
void add_node(DataPipeline *pipeline, double value) {
    if (pthread_mutex_lock(&pipeline->lock)) {
        log_message("Failed to lock mutex");
        return;
    }

    for (size_t i = 0; i < MAX_NODES && pipeline->nodes[i]; ++i);

    if (i >= MAX_NODES) {
        pthread_mutex_unlock(&pipeline->lock);
        log_message("Exceeded maximum node count");
        return;
    }

    Node *node = safe_aligned_alloc(sizeof(Node), "Node");
    node->value = value;
    node->items = NULL; // Initialize other fields as necessary
    node->item_count = 0;
    node->int_array = NULL; // Initialize dynamically sized array if needed
    node->array_size = 0;
    node->next = NULL;

    pipeline->nodes[i] = node;

    pthread_mutex_unlock(&pipeline->lock);
}

// Example usage
int main() {
    DataPipeline *pipeline = init_data_pipeline(100, 100, 10, 50);

    add_node(pipeline, 3.14);

    cleanup_data_pipeline(pipeline);
    return 0;
}
```

### Key Points:
- **Memory Alignment:** Used `_aligned_malloc` for aligned memory allocation to optimize performance.
- **Thread Safety:** Employed `pthread_mutex_t` for synchronization and thread safety during modifications of shared data structures.
- **Graceful Failure Handling:** Implemented graceful failure handling in case of memory allocation errors, including logging mechanisms.
- **Dynamic Resizing & Integrity Check:** While dynamic resizing isn't explicitly shown here, this code lays the groundwork by providing structured initialization and cleanup. The checksum is calculated to verify integrity.
- **Logging System:** Simple logging function to facilitate tracking operations and failures.

This implementation offers a solid foundation while considering performance, maintainability, and error handling in a multi-threaded environment.']

