    totalMemoryUsage += sizeof(long*) * longArraySize;
    totalMemoryUsage += sizeof(double) * doubleArraySize;
    totalMemoryUsage += sizeof(struct { char str[50]; unsigned int value; }) * structArraySize;
    totalMemoryUsage += sizeof(int) * structArraySize;
    for (int i = 0; i < recordCount; ++i) {
        Record rec = recordArray[i];
        totalMemoryUsage += sizeof(Record) + strlen(rec.identifier) + sizeof(size_t);
        if (rec.itemPtr->u.strPtr != NULL) {
            totalMemoryUsage += strlen(rec.itemPtr->u.strPtr);
        }
    }

    checkAndFreeMemoryIfNeeded(totalMemoryUsage);

    pthread_mutex_unlock(&memoryLock);
}

Item* createItem(size_t size, void *value, char type) {
    Item *item = malloc(sizeof(Item));
    item->size = size;

    if (type == 'd') {
        item->u.dValue = *(double*)value;
    } else if (type == 's') {
        item->u.strPtr = strdup((char *)value);
    }

    return item;
}

Record* createRecord(int index) {
    Record *record = malloc(sizeof(Record));
    record->itemPtr = NULL;

    snprintf(record->identifier, sizeof(record->identifier), "ID_%d_%ld", index, time(NULL));

    // Example initialization
    double exampleValue = (double)index;
    record->itemPtr = createItem(sizeof(exampleValue), &exampleValue, 'd');

    return record;
}

void releaseMemory() {
    pthread_mutex_lock(&memoryLock);

    for (int i = 0; i < longArraySize; ++i) {
        if (longArray[i] != NULL) free(longArray[i]);
    }
    free(longArray);

    free(doubleArray);

    for (int i = 0; i < structArraySize; ++i) {
        free(structArray[i].str);
    }
    free(structArray);

    free(keyArray);

    for (int i = 0; i < recordCount; ++i) {
        if (recordArray[i].itemPtr != NULL) {
            free(recordArray[i].itemPtr->u.strPtr);
            free(recordArray[i].itemPtr);
        }
        free(recordArray[i]);
    }

    free(recordArray);

    pthread_mutex_unlock(&memoryLock);
}

void checkAndFreeMemoryIfNeeded(size_t currentUsage) {
    while (currentUsage > MAX_MEMORY_USAGE) {
        // Implement logic to release memory from the least recently used records
        // Placeholder for demonstration purposes
        if (recordCount > 0 && recordArray != NULL) {
            Record *rec = recordArray[recordCount - 1];

            free(rec->itemPtr->u.strPtr);
            free(rec->itemPtr);
            free(rec);

            recordCount--;
            currentUsage -= sizeof(Record) + strlen(rec->identifier) + sizeof(size_t);
        }
    }
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    initializeDataStructures(10, 10, 5, 3);

    // For demonstration purposes: simulate cleanup on program exit.
    atexit(releaseMemory);

    return 0;
}
