### Part 2: Java Component for Remote Connection

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class RemoteConnectionManager {
    private static final int TIMEOUT = 5000; // milliseconds

    public void establishConnection(String host, int port) throws IOException {
        ExecutorService executor = Executors.newSingleThreadExecutor();

        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);

        try {
            boolean connected = false;

            while (!connected && !Thread.currentThread().isInterrupted()) {
                try {
                    socketChannel.connect(new InetSocketAddress(host, port));

                    if (socketChannel.finishConnect()) {
                        System.out.println("Connection established");
                        connected = true;

                        executor.submit(() -> {
                            // Handle connection logic
                            try {
                                while (!Thread.currentThread().isInterrupted()) {
                                    ByteBuffer buffer = ByteBuffer.allocate(256);
                                    int bytesRead = socketChannel.read(buffer);

                                    if (bytesRead == -1) {
                                        closeConnection();
                                        break;
                                    }

                                    buffer.flip();
                                    System.out.println("Received: " + new String(buffer.array(), 0, bytesRead));
                                }
                            } catch (IOException e) {
                                System.err.println("I/O error: " + e.getMessage());
                                closeConnection();
                            }
                        });
                    }
                } catch (IOException e) {
                    System.err.println("Attempt to connect failed: " + e.getMessage());

                    try {
                        Thread.sleep(TIMEOUT);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        } finally {
            if (!connected && socketChannel.isOpen()) {
                closeConnection(socketChannel, executor);
            }
        }
    }

    private void closeConnection() throws IOException {
        System.out.println("Closing connection");
        // Simulate sending message to a messaging system upon disconnection
    }

    private void closeConnection(SocketChannel channel, ExecutorService executor) throws IOException {
        channel.close();
        executor.shutdownNow();
        closeConnection();
    }

    public static void main(String[] args) {
        RemoteConnectionManager manager = new RemoteConnectionManager();

        try {
            manager.establishConnection("localhost", 8080);
        } catch (IOException e) {
            System.err.println("Error establishing connection: " + e.getMessage());
        }
    }
}
