### Part 3: C Program for Command-Line Parsing

```c
#include <stdio.h>
#include <stdlib.h>

void printUsage() {
    printf("Usage:\n");
    printf("\t--manpage : Show manual page\n");
    printf("\t-cs       : Compile and start\n");
    printf("\t-o output_file : Specify output file\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printUsage();
        return EXIT_FAILURE;
    }

    FILE *inputFile = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // Handle --manpage option
            printf("Man page information.\n");
        } else if (strcmp(argv[i], "-cs") == 0) {
            // Handle -cs option
            printf("Compile and start.\n");
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            // Handle -o output_file option
            printf("Output file specified: %s\n", argv[++i]);
        } else {
            inputFile = fopen(argv[i], "r");
            if (!inputFile) {
                perror("Error opening file");
                return EXIT_FAILURE;
            }

            int lineNumber = 0;
            char *line = NULL;
            size_t len = 0;

            while (getline(&line, &len, inputFile) != -1) {
                ++lineNumber;
            }

            printf("Number of lines: %d\n", lineNumber);
            free(line);
            fclose(inputFile);
        }
    }

    return EXIT_SUCCESS;
}
