    fn join_timeout(self, duration: Duration) -> Result<(), ()>;
}

impl<F> JoinTimeout for F
where
    F: std::future::Future,
{
    fn join_timeout(mut self, duration: Duration) -> Result<(), ()> {
        let handle = std::thread::spawn(move || {
            let result = futures_util::executor::block_on(self);
