#define ALIGNMENT 64

typedef struct {
    time_t timestamp;
    int priority;
    int status; // e.g., 0 or 1
} Entry;

typedef struct Node {
    void (*comparator)(const void*, const void*);
    Entry* entries;
    size_t entry_count;
    pthread_mutex_t lock;
    struct Node* left;
    struct Node* right;
} Node;

// Function prototypes
Node* create_node(void (*comp_func)(const void*, const void*), size_t alignment);
void free_node(Node* node, size_t alignment);
int allocate_aligned_memory(void** ptr, size_t size, size_t alignment);
void populate_tree(Node* root, int max_entries);
void log_test_info(const char* module_name, const char* test_name);

// Comparator example
int compare_entries_by_priority(const void* a, const void* b) {
    Entry* entry_a = (Entry*)a;
    Entry* entry_b = (Entry*)b;
    return entry_a->priority - entry_b->priority;
}

Node* create_node(void (*comp_func)(const void*, const void*), size_t alignment) {
    Node* node = NULL;
    if (allocate_aligned_memory((void**)&node, sizeof(Node), alignment)) {
        memset(node, 0, sizeof(Node));
        pthread_mutex_init(&node->lock, NULL);
        node->comparator = comp_func;
    }
    return node;
}

void free_node(Node* node, size_t alignment) {
    if (node) {
        pthread_mutex_destroy(&node->lock);
        free(node->entries);
        free_aligned_memory((void*)node, sizeof(Node), alignment);
    }
}

int allocate_aligned_memory(void** ptr, size_t size, size_t alignment) {
    void* raw_ptr = NULL;
    if (posix_memalign(&raw_ptr, alignment, size)) {
        printf("Memory allocation failed\n");
        return 0;
    }
    *ptr = raw_ptr;
    return 1;
}

void free_aligned_memory(void* ptr, size_t size, size_t alignment) {
    if (ptr) {
        free(ptr);
    }
}

void populate_tree(Node* root, int max_entries) {
    if (!root) return;

    pthread_mutex_lock(&root->lock);

    const int range = 100;
    const int priority_weights[] = {1, 2, 3}; // Example weights for priorities 0, 1, 2
    double total_weight = 0.0;
    for (int i = 0; i < sizeof(priority_weights) / sizeof(priority_weights[0]); ++i)
        total_weight += priority_weights[i];

    root->entries = malloc(max_entries * sizeof(Entry));
    if (!root->entries) {
        pthread_mutex_unlock(&root->lock);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < max_entries; ++i) {
        Entry* entry = &root->entries[i];

        // Populate timestamp
        time_t current_time = time(NULL);
        int offset = rand() % range;
        entry->timestamp = current_time + offset;

        // Determine priority based on weights
        double r = (double)rand() / RAND_MAX * total_weight;
        int cumulative_weight = 0;
        for (int j = 0; j < sizeof(priority_weights) / sizeof(priority_weights[0]); ++j) {
            cumulative_weight += priority_weights[j];
            if (r <= cumulative_weight) {
                entry->priority = j;
                break;
            }
        }

        // Set status based on predefined conditions
        entry->status = (entry->timestamp % 2 == 0) ? 1 : 0;

        // Insertion logic for balanced BST goes here (omitted for brevity)
    }

    root->entry_count = max_entries;
    pthread_mutex_unlock(&root->lock);
}

void log_test_info(const char* module_name, const char* test_name) {
    printf("Testing Module: %s\n", module_name);
    printf("Running Test: %s\n", test_name);
}

typedef void (*test_func)(const char*, int);

void run_tests(test_func tests[], size_t num_tests, int max_entries) {
    for (size_t i = 0; i < num_tests; ++i) {
        const char* module_name = "DynamicTreeModule";
        log_test_info(module_name, tests[i].__func__);

        // Reset mocking library
        printf("Resetting blueslip library\n");

        Node* root = create_node(compare_entries_by_priority, ALIGNMENT);
        if (!root) {
            printf("Failed to initialize tree node.\n");
            continue;
        }

        populate_tree(root, max_entries);

        // Verify integrity of allocated data
        pthread_mutex_lock(&root->lock);
        for (size_t j = 0; j < root->entry_count; ++j) {
            Entry* entry = &root->entries[j];
            printf("Entry %zu: timestamp=%ld, priority=%d, status=%d\n", j, entry->timestamp, entry->priority, entry->status);
        }
        pthread_mutex_unlock(&root->lock);

        free_node(root, ALIGNMENT);
    }
}

void test_case_1(const char* label, int max_entries) {
    printf("Running %s with max_entries=%d\n", label, max_entries);
    // Test logic here
}

void test_case_2(const char* label, int max_entries) {
