['Below is an implementation outline for the described modular C library that manages Network Interface Control Blocks (NICBs). The code includes key components to address the requirements outlined in your task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>

#define MAX_NICBS 1024

typedef struct {
    unsigned char mac_header[14]; // Assuming standard MAC header size
    unsigned char source_mac[6];
    unsigned char destination_mac[6];
    unsigned short vlan_tag;
    unsigned char vlan_priority;
    int ip_checksum_enabled; // Optional IP header checksum setting
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    EVP_CIPHER_CTX *cipher_ctx;
    HMAC_CTX *hmac_ctx;
    pthread_mutex_t lock; // For thread safety
} NICB;

typedef struct {
    unsigned char* key;
    size_t key_size;
    int enabled;
} CryptoPolicy;

typedef struct {
    NICB nicbs[MAX_NICBS];
    int count;
    pthread_rwlock_t rwlock; // Read-write lock for performance
} NICBManager;

NICBManager manager = { .count = 0, .rwlock = PTHREAD_RWLOCK_INITIALIZER };

void initialize_nicb(NICB *nicb) {
    EVP_CIPHER_CTX_init(nicb->cipher_ctx);
    HMAC_CTX_init(nicb->hmac_ctx);
    pthread_mutex_init(&nicb->lock, NULL);
}

void free_nicb_resources(NICB *nicb) {
    EVP_CIPHER_CTX_cleanup(nicb->cipher_ctx);
    HMAC_CTX_cleanup(nicb->hmac_ctx);
    pthread_mutex_destroy(&nicb->lock);
}

int add_nicb(const MAC_HEADER *header, const CryptoPolicy *policy) {
    pthread_rwlock_wrlock(&manager.rwlock);

    if (manager.count >= MAX_NICBS) {
        pthread_rwlock_unlock(&manager.rwlock);
        return -1; // Error: NICB array full
    }

    NICB *nicb = &manager.nicbs[manager.count++];
    memcpy(&nicb->mac_header, header, sizeof(MAC_HEADER));

    if (policy->enabled) {
        nicb->cipher_ctx = EVP_CIPHER_CTX_new();
        nicb->hmac_ctx = HMAC_CTX_new();
        initialize_nicb(nicb);
        // Configure cryptographic operations based on policy
    } else {
        nicb->cipher_ctx = NULL;
        nicb->hmac_ctx = NULL;
    }

    pthread_rwlock_unlock(&manager.rwlock);
    return 0; // Success
}

void remove_nicb(int index) {
    pthread_rwlock_wrlock(&manager.rwlock);

    if (index < 0 || index >= manager.count) {
        pthread_rwlock_unlock(&manager.rwlock);
        return;
    }

    free_nicb_resources(&manager.nicbs[index]);
    memmove(&manager.nicbs[index], &manager.nicbs[index + 1],
            sizeof(NICB) * (manager.count - index - 1));
    manager.count--;

    pthread_rwlock_unlock(&manager.rwlock);
}

void log_event(const char *event) {
    // Non-blocking logging mechanism
    printf("Log: %s\n", event); 
}

// Further functions to handle cryptographic operations, dynamic threading,
// and hardware acceleration would be implemented here.

int main() {
    MAC_HEADER header = { .vlan_tag = 0x1234 };
    CryptoPolicy policy = { .key = (unsigned char*)"secret_key", .key_size = 16, .enabled = 1 };

    if (add_nicb(&header, &policy) == 0) {
        log_event("NICB added successfully");
    } else {
        log_event("Failed to add NICB");
    }

    return 0;
}
```

### Key Features Implemented:
- **NICB Management**: Functions to add and remove NICBs safely using a read-write lock.
- **Cryptographic Context Initialization**: Using OpenSSL for cryptographic operations. Cryptographic contexts are initialized based on policy settings.
- **Thread Safety**: Mutexes ensure thread safety for individual NICBs, while a read-write lock manages access to the NICB array.
- **Logging**: A simple logging function that records events without blocking.

This implementation serves as a starting point and can be expanded with additional functionalities like hardware acceleration support, dynamic algorithm management, fault tolerance, and performance monitoring as described in your task.']

['Below is the implementation of the `ResourceManagerInit` function in C, followed by a PHP script to initialize and configure the web application layer.

### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 1024
#define EXPANSION_SIZE 512
#define ALIGNMENT 16
#define MAX_RANDOM_INT 1000000

typedef struct {
    int value;
    int key;
    size_t ref_count;
} Record;

typedef struct {
    Record *records;
    long *offsets;
    int *keys;
    size_t capacity;
    sem_t semaphore;
} ResourceManager;

void align_pointer(void **ptr, size_t alignment) {
    void *original = *ptr;
    if (alignment & (alignment - 1)) {
        fprintf(stderr, "Alignment must be a power of two\n");
        exit(EXIT_FAILURE);
    }
    *ptr = (void *)(((uintptr_t)original + alignment - 1) & ~(alignment - 1));
}

ResourceManager* ResourceManagerInit() {
    ResourceManager *manager = malloc(sizeof(ResourceManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    align_pointer((void**)&manager->records, ALIGNMENT);
    manager->records = calloc(manager->capacity, sizeof(Record));
    align_pointer((void**)&manager->offsets, ALIGNMENT);
    manager->offsets = calloc(manager->capacity, sizeof(long));
    align_pointer((void**)&manager->keys, ALIGNMENT);
    manager->keys = calloc(manager->capacity, sizeof(int));

    if (!manager->records || !manager->offsets || !manager->keys) {
        free(manager->records);
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < manager->capacity; ++i) {
        do {
            manager->records[i].value = rand() % MAX_RANDOM_INT;
        } while (manager->keys[i] != 0 || find(manager->keys, manager->capacity, manager->records[i].value));

        manager->records[i].key = i;
        manager->records[i].ref_count = 1;
        manager->offsets[i] = rand() % MAX_RANDOM_INT; // Example offset initialization
    }

    sem_init(&manager->semaphore, 0, 1);

    return manager;
}

int find(int *array, size_t size, int value) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == value) return 1;
    }
    return 0;
}

void ResourceManagerCleanup(ResourceManager *manager) {
    if (!manager) return;

    sem_destroy(&manager->semaphore);
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free(manager);
}
```

