typedef struct {
    char *name;
    int value;
} Item;

// Function prototypes for Java integration (JNI)
void callJavaWebSocketMethod();

// C function to manage allocation and initialization of Items
int initializeItems(Item **items, size_t count, const char *prefix) {
    if (!items || !count || !prefix) return -1;

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of Item pointers
    *items = (Item **)malloc(count * sizeof(Item *));
    if (*items == NULL) return -2;

    // Initialize each Item structure
    for (size_t i = 0; i < count; ++i) {
        // Create a unique name with prefix and index
        char *nameStr = (char *)malloc(strlen(prefix) + 20); // Enough space for suffix
        if (!nameStr) goto cleanup;

        snprintf(nameStr, strlen(prefix) + 20, "%s_%zu", prefix, i);

        // Allocate memory for the name string within the Item structure
        (*items)[i] = (Item *)malloc(sizeof(Item));
        if ((*items)[i] == NULL) {
            free(nameStr);
            goto cleanup;
        }

        (*items)[i]->name = nameStr;

        // Initialize integer value to a random number in a specified range
        (*items)[i]->value = rand() % 100 + 1; // Random value between 1 and 100

        printf("Item %zu: Name = %s, Value = %d\n", i, (*items)[i]->name, (*items)[i]->value);
    }

    // After initialization, call Java method for WebSocket connection
    callJavaWebSocketMethod();

    return 0;

cleanup:
    for (size_t i = 0; i < count; ++i) {
        if ((*items)[i]) {
            free((*items)[i]->name);
            free(*items[i]);
        }
    }
    free(*items);
    *items = NULL;
    return -3;
}

// JNI C function to call Java WebSocket method
#include <jni.h>

JavaVM *jvm; // Global variable for JVM instance

void callJavaWebSocketMethod() {
    JNIEnv *env;
    if (jvm->GetEnv((void**)&env, JNI_VERSION_1_6) != JNI_OK) {
        return;
    }

    jclass cls = env->FindClass("com/example/WebSocketClient");
    if (!cls) {
        return;
    }

    jmethodID mid = env->GetStaticMethodID(cls, "setupWebSocket", "()V");
    if (!mid) {
        return;
    }

    env->CallStaticVoidMethod(cls, mid);
}
