// Java class for WebSocket client
package com.example;

import javax.websocket.*;
import java.net.URI;
import java.io.IOException;

@ClientEndpoint
public class WebSocketClient {

    private static Session userSession = null;

    public static void setupWebSocket() {
        try {
            WebSocketContainer container = ContainerProvider.getWebSocketContainer();
            String uri = "ws://example.com/websocket";

            // Connect to WebSocket server
            userSession = container.connectToServer(WebSocketClient.class, URI.create(uri));
            System.out.println("Connected to the WebSocket server.");

            // Example of handling different states and messages
            userSession.addMessageHandler(new MessageHandler.Whole<String>() {
                @Override
                public void onMessage(String message) {
                    System.out.println("Received: " + message);
                }
            });
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    @OnOpen
    public void onOpen(Session session) {
        System.out.println("WebSocket connection opened.");
    }

    @OnClose
    public void onClose(Session session, CloseReason closeReason) {
        System.out.println("WebSocket connection closed: " + closeReason);
        userSession = null;
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        System.err.println("Error occurred: " + throwable.getMessage());
    }
}
