    char description[512];
} EventLogEntry;

typedef struct {
    ServerSettings server_settings;
    AlarmThreshold alarm_thresholds[10]; // Assume a max of 10 thresholds
    NotificationChannel notification_channels[5]; // Assume a max of 5 channels
    EventLogEntry historical_event_logs[1000]; // Assume a log size for example
} Configuration;

// Global configuration and lock for concurrency control
Configuration current_config;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility functions to handle alignment, memory, etc.
void align8(void *ptr) {
    uintptr_t addr = (uintptr_t)ptr;
    if (addr & 0x7) {
        void **aligned_ptr = (void **)(((addr + 7) & ~0x7));
        *aligned_ptr = ptr;
    }
}

// Serialization function
size_t serialize_config(Configuration *config, char **output_json) {
    json_t *root = json_object();

    json_t *server_settings = json_pack("{s:i,s:s,s:s}",
                                        "port", config->server_settings.port,
                                        "protocol", config->server_settings.protocol,
                                        "auth_credentials", config->server_settings.auth_credentials);
    json_object_set_new(root, "server_settings", server_settings);

    // Serialize other components...

    char *json_str = json_dumps(root, JSON_COMPACT);
    size_t compressed_size = compressBound(strlen(json_str));

    if (compressed_size > MAX_CONFIG_SIZE) {
        fprintf(stderr, "Serialized data exceeds system limits\n");
        return 0;
    }

    unsigned char *compressed_data = malloc(compressed_size);
    compress((unsigned char *)compressed_data, &compressed_size, (const unsigned char *)json_str, strlen(json_str));

    *output_json = strndup((char*)compressed_data, compressed_size);

    free(json_str);
    json_decref(root);
    free(compressed_data);

    return compressed_size;
}

// Deserialization function
int deserialize_config(const char *input_json, size_t size, Configuration *config) {
    unsigned char *decompressed_data = malloc(size * 2); // Assume decompressed data won't exceed double the compressed size
    uLongf decompressed_size = size * 2;

    if (uncompress(decompressed_data, &decompressed_size, (const unsigned char *)input_json, size) != Z_OK) {
        fprintf(stderr, "Failed to decompress input data\n");
        free(decompressed_data);
        return -1;
    }

    json_error_t error;
    json_t *root = json_loads((char*)decompressed_data, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        free(decompressed_data);
        return -1;
    }

    // Parse and populate configuration

    json_decref(root);
    free(decompressed_data);

    return 0;
}

// HTTP method implementations
void http_get_config(const char *user) {
    pthread_mutex_lock(&config_lock);
    // Implement user validation...
    char *json_output = NULL;
    size_t output_size = serialize_config(&current_config, &json_output);

    if (output_size > 0) {
        printf("%s\n", json_output); // This would be the HTTP response body
    }

    free(json_output);
    pthread_mutex_unlock(&config_lock);
}

void http_put_config(const char *user, const char *input_json, size_t input_size) {
    pthread_mutex_lock(&config_lock);
    // Implement user validation...
    if (deserialize_config(input_json, input_size, &current_config) == 0) {
        printf("Configuration updated successfully\n");
    } else {
        fprintf(stderr, "Failed to update configuration\n");
    }
    pthread_mutex_unlock(&config_lock);
}

void http_post_reset(const char *user, const char *body) {
    pthread_mutex_lock(&config_lock);
    // Implement user validation...
    if (strcmp(body, "RESET") == 0) {
        memset(&current_config, 0, sizeof(Configuration));
        current_config.server_settings.port = DEFAULT_PORT;
        strcpy(current_config.server_settings.protocol, DEFAULT_PROTOCOL);
        printf("Configuration reset to default values\n");
    } else {
        fprintf(stderr, "Invalid reset request body\n");
    }
    pthread_mutex_unlock(&config_lock);
}

