// Assuming these structures are defined elsewhere in your codebase
typedef struct {
    double latitude;
    double longitude;
} location_t;

typedef struct {
    float elevation;
    float temperature;
    location_t location;
} cell_data;

typedef cell_data* terrain_grid;

#define MEMORY_ALIGNMENT 128

void process_terrain(const char *input_file, const char *output_file,
                     float min_elevation, float max_temperature,
                     int new_rows, int new_cols) {

    FILE *file = fopen(input_file, "r");
    if (!file) {
        fprintf(stderr, "Error opening input file: %s\n", input_file);
        return;
    }

    // Read grid dimensions from the file
    int rows, cols;
    fscanf(file, "%d %d", &rows, &cols);

    size_t cell_size = sizeof(cell_data);
    size_t padding = (MEMORY_ALIGNMENT - (cell_size % MEMORY_ALIGNMENT)) % MEMORY_ALIGNMENT;
    size_t total_size = ((size_t)rows * cols * (cell_size + padding));

    void* buffer = aligned_alloc(MEMORY_ALIGNMENT, total_size);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return;
    }

    terrain_grid grid = (terrain_grid)buffer;

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            fscanf(file, "%f %f %lf %lf", &grid[i][j].elevation, 
                                           &grid[i][j].temperature,
                                           &grid[i][j].location.latitude,
                                           &grid[i][j].location.longitude);
        }
    }

    fclose(file);

    // Log processing start
    printf("Processing dataset: %s\n", input_file);

    // Filtering step based on elevation and temperature
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j].elevation < min_elevation || 
                grid[i][j].temperature > max_temperature) {

                // Mark or handle cells that do not meet criteria
                grid[i][j].elevation = FLT_MAX;
                grid[i][j].temperature = FLT_MAX;
            }
        }
    }

    // Optionally resize the grid to new dimensions
    if (new_rows > 0 && new_cols > 0) {
        terrain_grid resized_grid = malloc(new_rows * sizeof(cell_data*) + 
                                           new_rows * new_cols * sizeof(cell_data));

        for (int i = 0; i < new_rows; ++i) {
            resized_grid[i] = (cell_data*)(resized_grid + new_rows);
            for (int j = 0; j < new_cols; ++j) {
                int src_i = i * rows / new_rows;
                int src_j = j * cols / new_cols;

                resized_grid[i][j].elevation = grid[src_i][src_j].elevation;
                resized_grid[i][j].temperature = grid[src_i][src_j].temperature;
                resized_grid[i][j].location.latitude = 
                    grid[src_i][src_j].location.latitude;
                resized_grid[i][j].location.longitude = 
                    grid[src_i][src_j].location.longitude;
            }
        }

        // Free old grid
        free(buffer);

        buffer = aligned_alloc(MEMORY_ALIGNMENT, new_rows * sizeof(cell_data*) +
                                           new_rows * new_cols * sizeof(cell_data));
        if (!buffer) {
            fprintf(stderr, "Memory allocation failed for resized grid\n");
            free(resized_grid);
            return;
        }

        memcpy(buffer, resized_grid, new_rows * sizeof(cell_data*) + 
                                  new_rows * new_cols * sizeof(cell_data));

        free(resized_grid);

        // Update grid to point to the new memory
        grid = (terrain_grid)buffer;

        rows = new_rows;
        cols = new_cols;
    }

    // Log processing completion and save results
    file = fopen(output_file, "w");
    if (!file) {
        fprintf(stderr, "Error opening output file: %s\n", output_file);
        return;
    }

    fprintf(file, "%d %d\n", rows, cols);

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j].elevation != FLT_MAX && 
                grid[i][j].temperature != FLT_MAX) {

                fprintf(file, "%f %f %lf %lf\n", grid[i][j].elevation,
                                                  grid[i][j].temperature,
                                                  grid[i][j].location.latitude,
                                                  grid[i][j].location.longitude);
            }
        }
    }

    fclose(file);

    printf("Processed dataset and saved to: %s\n", output_file);
}
