typedef struct {
    int packet_id;
    unsigned char *payload;
    size_t payload_size;
    size_t header_len;
    time_t timestamp;
} DataPacket;

DataPacket* initialize_data_packets(size_t num_packets, const size_t *payload_sizes) {
    if (num_packets == 0 || payload_sizes == NULL) {
        fprintf(stderr, "Invalid number of packets or payload sizes.\n");
        return NULL;
    }

    DataPacket *packets = malloc(num_packets * sizeof(DataPacket));
    if (!packets) {
        perror("Failed to allocate memory for data packets");
        return NULL;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        DataPacket *packet = &packets[i];

        packet->packet_id = (int)i + 1;

        // Dynamically allocate payload
        packet->payload_size = payload_sizes[i];
        packet->payload = malloc(packet->payload_size);
        if (!packet->payload) {
            perror("Failed to allocate memory for packet payload");
            free(packets); // Free previously allocated packets
            return NULL;
        }

        // Assign a sample header length, ensuring it does not exceed the maximum
        packet->header_len = (MAX_HEADER_LEN < 10 ? MAX_HEADER_LEN : 10);

        // Record the creation timestamp
        packet->timestamp = time(NULL);

        // For logging purposes, you might add:
        printf("Packet %d created at %ld with payload size %zu and header length %zu\n", 
               packet->packet_id, packet->timestamp, packet->payload_size, packet->header_len);
    }

    return packets;
}

void free_data_packets(DataPacket *packets, size_t num_packets) {
    if (packets == NULL) return;

    for (size_t i = 0; i < num_packets; ++i) {
        DataPacket *packet = &packets[i];
        if (packet->payload) {
            free(packet->payload);
        }
    }

    free(packets);
}

