#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define PAGE_SIZE_4KB 4096
#define PAGE_SIZE_2MB (2 * 1024 * 1024)
#define PAGE_SIZE_1GB (1024 * 1024 * 1024)

typedef struct {
    unsigned long virtual_address;
    unsigned long physical_address;
    int cache_control_flags;
} PageTableEntry;

typedef struct {
    PageTableEntry pte;
    char log[256];
} MMU;

typedef enum { PAGE_4KB, PAGE_2MB, PAGE_1GB } PageSizeType;

// Mock MMS callback function
int mms_is_valid_virtual_address(unsigned long virtual_address);

void *initialize_mmu(void *arg);
void log_message(const char *message);

typedef struct {
    MMU **mmu_array;
    unsigned int size;
    unsigned long seed;
    PageSizeType page_size;
    unsigned long* backup_addresses;
    unsigned int num_backups;
    pthread_mutex_t lock;
} InitConfig;

MMU* allocate_mmu_array(unsigned int size, const char *log_file) {
    MMU *array = (MMU*)malloc(size * sizeof(MMU));
    if (!array) {
        log_message("Memory allocation failed for MMU array.");
        return NULL;
    }
    return array;
}

void free_mmu_array(MMU *mmu_array, unsigned int size) {
    if (mmu_array) {
        for (unsigned int i = 0; i < size; ++i) {
            free(mmu_array[i].log);
        }
        free(mmu_array);
    }
}

int validate_page_size(PageSizeType page_size) {
    return (page_size == PAGE_4KB || page_size == PAGE_2MB || page_size == PAGE_1GB);
}

void initialize_mmus(unsigned int size, unsigned long seed, PageSizeType page_size,
                     unsigned long* backup_addresses, unsigned int num_backups, const char *log_file) {
    if (!validate_page_size(page_size)) {
        log_message("Invalid page size selected.");
        return;
    }

    MMU **mmu_array = allocate_mmu_array(size, log_file);
    if (!mmu_array) return;

    InitConfig config = { mmu_array, size, seed, page_size, backup_addresses, num_backups, PTHREAD_MUTEX_INITIALIZER };

    pthread_t threads[size];
    for (unsigned int i = 0; i < size; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_mmu, &config)) {
            log_message("Failed to create thread.");
        }
    }

    for (unsigned int i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_mmu_array(mmu_array[0], config.size); // mmu_array is MMU**
}

void *initialize_mmu(void *arg) {
    InitConfig *config = (InitConfig *)arg;
    srand(config->seed + (intptr_t)arg);

    for (unsigned int i = 0; i < config->size; ++i) {
        unsigned long virtual_address = rand() % UINT32_MAX;

        if (!mms_is_valid_virtual_address(virtual_address)) {
            pthread_mutex_lock(&config->lock);
            log_message("Invalid virtual address detected.");

            for (unsigned int j = 0; j < config->num_backups; ++j) {
                if (mms_is_valid_virtual_address(config->backup_addresses[j])) {
                    virtual_address = config->backup_addresses[j];
                    break;
                }
            }

            pthread_mutex_unlock(&config->lock);

            if (!mms_is_valid_virtual_address(virtual_address)) {
                snprintf(config->mmu_array[i][0].log, sizeof(config->mmu_array[i][0].log),
                         "All virtual addresses invalid for MMU[%d]", i);
                continue;
            }
        }

        config->mmu_array[i][0].pte.virtual_address = virtual_address;
        config->mmu_array[i][0].pte.physical_address = (unsigned long)&config->mmu_array[i][0] +
                                                       sizeof(PageTableEntry); // Mock physical address
        snprintf(config->mmu_array[i][0].log, sizeof(config->mmu_array[i][0].log),
                 "MMU[%d]: Virtual address %lx initialized.", i, virtual_address);
    }

    return NULL;
}

void log_message(const char *message) {
    // Implement logging to a file or console
    printf("%s\n", message);
}
```

### Explanation:
- **Memory Management**: The code dynamically allocates and frees an array of MMU structures.
- **Page Size Validation**: Validates supported page sizes (4KB, 2MB, 1GB).
- **MMS Integration**: Mock function `mms_is_valid_virtual_address` checks address validity.
- **Thread Safety**: Uses mutexes to prevent race conditions when logging messages.
- **Multi-threading**: Initializes MMUs in parallel using pthreads.
- **Logging**: Simple logging mechanism to track initialization process and errors.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_RECORDS 50000
#define INITIAL_CAPACITY 1000

typedef struct {
    short value;
    char identifier;
    float *float_ptr;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t record;
} data_record_t;

typedef struct {
    data_record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t allocation_count;
} dynamic_storage_t;

// Initialize the storage system
int init_storage(dynamic_storage_t *storage) {
    if (storage == NULL) return -1;

    storage->records = (data_record_t *)malloc(INITIAL_CAPACITY * sizeof(data_record_t));
    if (!storage->records) return -2;

    storage->capacity = INITIAL_CAPACITY;
    storage->count = 0;
    pthread_mutex_init(&storage->lock, NULL);
    storage->allocation_count = 0;

    return 0;
}

// Resize the underlying data structure
int resize_storage(dynamic_storage_t *storage) {
    if (storage == NULL || storage->capacity >= MAX_RECORDS) return -1;

    size_t new_capacity = storage->capacity * 2 < MAX_RECORDS ? storage->capacity * 2 : MAX_RECORDS;
    data_record_t *new_records = (data_record_t *)realloc(storage->records, new_capacity * sizeof(data_record_t));

    if (!new_records) return -2;

    storage->records = new_records;
    storage->capacity = new_capacity;

    return 0;
}

// Add a record to the storage
int add_record(dynamic_storage_t *storage, long offset, int key, short value, char identifier, float *float_data) {
    if (storage == NULL || storage->count >= MAX_RECORDS) return -1;

    pthread_mutex_lock(&storage->lock);

    // Resize if necessary
    if (storage->capacity <= storage->count) {
        int resize_result = resize_storage(storage);
        if (resize_result != 0) {
            pthread_mutex_unlock(&storage->lock);
            return resize_result;
        }
    }

    data_record_t *new_record = &storage->records[storage->count++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->record.value = value;
    new_record->record.identifier = identifier;

    float *float_copy = malloc(sizeof(float));
    if (!float_copy) {
        pthread_mutex_unlock(&storage->lock);
        return -3;
    }

    *float_copy = *float_data;
    new_record->record.float_ptr = float_copy;

    storage->allocation_count++;

    pthread_mutex_unlock(&storage->lock);

    return 0;
}

// Serialize the current state to a file
int serialize_state(const dynamic_storage_t *storage, const char *filename) {
    if (storage == NULL || filename == NULL) return -1;

    FILE *file = fopen(filename, "wb");
    if (!file) return -2;

    fwrite(&storage->count, sizeof(size_t), 1, file);
    fwrite(storage->records, sizeof(data_record_t), storage->count, file);

    fclose(file);

    return 0;
}

// Deserialize the state from a file
int deserialize_state(dynamic_storage_t *storage, const char *filename) {
    if (storage == NULL || filename == NULL) return -1;

    FILE *file = fopen(filename, "rb");
    if (!file) return -2;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    // Resize storage to the deserialized state
    int resize_result = resize_storage(storage);
    if (resize_result != 0 || count > storage->capacity) {
        fclose(file);
        return resize_result;
    }

    size_t read_count = fread(storage->records, sizeof(data_record_t), count, file);

    if (read_count < count) {
        fclose(file);
        return -3;
    }

    storage->count = count;

    fclose(file);

    return 0;
}

// Clean up and free resources
void cleanup_storage(dynamic_storage_t *storage) {
    if (storage == NULL) return;

    pthread_mutex_lock(&storage->lock);

    for (size_t i = 0; i < storage->count; ++i) {
        free(storage->records[i].record.float_ptr);
    }

    free(storage->records);
    pthread_mutex_unlock(&storage->lock);

    pthread_mutex_destroy(&storage->lock);
}

// Example usage
int main() {
    dynamic_storage_t storage;

    if (init_storage(&storage) != 0) {
        fprintf(stderr, "Failed to initialize storage\n");
        return -1;
    }

    float data = 3.14f;
    add_record(&storage, 12345L, 1, 42, 'A', &data);

    serialize_state(&storage, "storage.bin");

    dynamic_storage_t new_storage;
    if (init_storage(&new_storage) != 0 || deserialize_state(&new_storage, "storage.bin") != 0) {
        fprintf(stderr, "Failed to load storage\n");
        cleanup_storage(&storage);
        return -1;
    }

    // Perform operations with the deserialized state...

    cleanup_storage(&storage);
    cleanup_storage(&new_storage);

    return 0;
}
```']

