#define CACHE_SIZE 10
#define MEMORY_LIMIT_MB 100
#define ALLOCATION_ALIGNMENT 16
#define VALUE_MIN -1000
#define VALUE_MAX 1000

typedef struct {
    int key;
    long offset;
} record_t;

// Cache structure with LRU policy
typedef struct {
    pthread_mutex_t lock;
    record_t* data[CACHE_SIZE];
    int age[CACHE_SIZE];
    size_t count;
} cache_t;

cache_t cache = {.count = 0};

void log_event(const char* event) {
    // Simple logging mechanism; replace with more sophisticated logging if needed
    printf("LOG: %s\n", event);
}

void alert_admin(const char* message) {
    fprintf(stderr, "ALERT: %s\n", message);
}

size_t get_memory_usage() {
    // Placeholder for actual memory usage retrieval function
    return 0;
}

int align_size(size_t size, size_t alignment) {
    if (alignment & (alignment - 1)) {  // Not a power of two
        fprintf(stderr, "Alignment is not a power of two\n");
        return 0;
    }
    return (size + alignment - 1) & ~(alignment - 1);
}

record_t* allocate_and_initialize(size_t num_records) {
    size_t total_size = sizeof(record_t) * num_records;
    total_size = align_size(total_size, ALLOCATION_ALIGNMENT);

    if (get_memory_usage() > MEMORY_LIMIT_MB * 1024 * 1024) {
        alert_admin("Memory limit exceeded");
        return NULL;
    }

    record_t* records = (record_t*)aligned_alloc(ALLOCATION_ALIGNMENT, total_size);
    if (!records) {
        log_event("Memory allocation failed for records");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % 1000;
        records[i].offset = rand() % 1000000;

        // Initialize record values with random integers within the specified range
        int value = VALUE_MIN + (rand() % (VALUE_MAX - VALUE_MIN + 1));
        log_event("Record initialized");
    }

    return records;
}

void cache_access(record_t* rec) {
    pthread_mutex_lock(&cache.lock);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.data[i] && cache.data[i]->key == rec->key) {
            log_event("Cache hit");

            // Update LRU
            int oldest_index = -1, oldest_age = INT_MAX;
            for (int j = 0; j < CACHE_SIZE; ++j) {
                if (cache.age[j] < oldest_age) {
                    oldest_age = cache.age[j];
                    oldest_index = j;
                }
                cache.age[j]++;
            }

            record_t* temp = cache.data[i];
            cache.data[i] = cache.data[oldest_index];
            cache.data[oldest_index] = temp;

            pthread_mutex_unlock(&cache.lock);
            return;
        }
    }

    log_event("Cache miss");

    // Evict least recently used item
    int oldest_index = -1, oldest_age = INT_MAX;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache.age[i] < oldest_age) {
            oldest_age = cache.age[i];
            oldest_index = i;
        }
        cache.age[i]++;
    }

    // Add new record to cache
    if (cache.count < CACHE_SIZE) {
        cache.data[cache.count++] = rec;
    } else {
        free(cache.data[oldest_index]);  // Free old data if needed
        cache.data[oldest_index] = rec;
    }

    pthread_mutex_unlock(&cache.lock);
}

int main() {
    pthread_mutex_init(&cache.lock, NULL);

    size_t num_records = 100; // Example number of records to allocate and initialize
    record_t* records = allocate_and_initialize(num_records);
    if (!records) return 1;

    for (size_t i = 0; i < num_records; ++i) {
        cache_access(&records[i]);
    }

    free(records);

    pthread_mutex_destroy(&cache.lock);
    return 0;
}
