record_t *allocate_record(slab_allocator_t *allocator, int key) {
    if (allocator->used >= allocator->capacity) {
        size_t new_capacity = allocator->capacity * 2;
        size_t record_size = sizeof(record_t);

        align_size(&record_size);

        record_t *new_records = realloc(allocator->records, new_capacity * record_size);
        if (!new_records) return NULL;

        allocator->records = new_records;
        allocator->capacity = new_capacity;
    }

    pthread_mutex_lock(&allocator->lock);

    record_t *record = &allocator->records[allocator->used++];

    pthread_mutex_unlock(&allocator->lock);

    record->key = key | ((rand() << 16) & 0xFFFF0000);
    return record;
}

