import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.Future;

public class DataStreamer {

    public void streamDataAsync(String serverAddress, int port) {
        try (AsynchronousSocketChannel client = AsynchronousSocketChannel.open()) {
            InetSocketAddress hostAddress = new InetSocketAddress(serverAddress, port);

            Future<Void> future = client.connect(hostAddress).thenRun(() -> {
                ByteBuffer buffer = ByteBuffer.allocate(1024);

                // Example of data reading logic
                client.read(buffer).get();

                String data = new String(buffer.array()).trim();
                System.out.println("Received: " + data);

            }).exceptionally(ex -> {
                logError("Connection error", ex);
                return null;
            });

            // Wait for the future to complete
            future.get();

        } catch (IOException | InterruptedException e) {
            logError("I/O or Interrupt Error occurred", e);
        }
    }

    private void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
        e.printStackTrace();
    }
}
