#include "mp3_header.h"
#include "mp3_compression_lib.h"  // Hypothetical third-party library header

#define MAX_THREADS 8
#define ALIGNMENT 16

typedef struct {
    char *file_path;
    int bitrate;
} AudioFileTask;

// Global thread pool variables
pthread_t threads[MAX_THREADS];
sem_t task_queue;
sem_t available_threads;
int shutdown = 0;

// Memory aligned allocation function
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Thread pool worker function
void* process_audio_file(void *arg) {
    while (!shutdown || sem_value(&task_queue) > 0) {
        AudioFileTask task;
        if (sem_wait(&task_queue) == 0 && !shutdown) { // Wait for a task or shutdown signal
            task = *(AudioFileTask*)arg;

            MP3_HEADER *header_array = NULL;
            size_t header_count = 1;  // Assume one header per file, modify as needed

            // Allocate memory for MP3 headers with alignment
            header_array = aligned_alloc(ALIGNMENT, sizeof(MP3_HEADER) * header_count);
            if (!header_array) {
                fprintf(stderr, "Memory allocation failed\n");
                continue;
            }

            // Initialize and validate MP3 header (hypothetical function)
            if (!initialize_and_validate_mp3_header(header_array, task.file_path)) {
                fprintf(stderr, "Validation failed for file: %s\n", task.file_path);
            } else {
                // Process audio with third-party library
                char output_path[256];
                snprintf(output_path, sizeof(output_path), "./output/%s.mp3", extract_filename(task.file_path));

                int compression_result = compress_audio_file(
                    task.file_path,
                    output_path,
                    header_array->sample_rate,
                    task.bitrate
                );

                if (compression_result != 0) {
                    fprintf(stderr, "Compression failed for file: %s\n", task.file_path);
                } else {
                    // Generate metadata tags
                    generate_metadata_tags(output_path, header_array->sample_rate, get_audio_duration(output_path));
                }
            }

            free(header_array); 
        }
        sem_post(&available_threads);  // Signal that this thread is available again
    }
    return NULL;
}

// Function to initialize and start the thread pool
void init_thread_pool() {
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_audio_file, NULL);
    }
    sem_init(&task_queue, 0, 0); // Initialize task queue semaphore with no tasks
    sem_init(&available_threads, 0, MAX_THREADS); // Available threads initialized to max count
}

// Function to add a task to the thread pool
void enqueue_task(AudioFileTask task) {
    for (;;) {
        if (sem_trywait(&available_threads) == 0) { // Try to get an available thread
            AudioFileTask *task_ptr = malloc(sizeof(AudioFileTask));
            if (!task_ptr) {
                fprintf(stderr, "Failed to allocate memory for task\n");
                continue;
            }
            *task_ptr = task;
            sem_post(&task_queue);  // Signal that a new task is ready
            break;
        }
    }
}

// Function to shutdown the thread pool
void shutdown_thread_pool() {
    shutdown = 1;  // Set shutdown flag
    for (int i = 0; i < MAX_THREADS; ++i) {  // Wake up all threads
        sem_post(&task_queue);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);  // Wait for threads to finish
    }
}

// Main function to process audio files
void process_audio_files(char **file_paths, int count, int bitrate) {
    init_thread_pool();

    AudioFileTask tasks[count];
    for (int i = 0; i < count; ++i) {
        tasks[i].file_path = file_paths[i];
        tasks[i].bitrate = bitrate;
        enqueue_task(tasks[i]);
    }

    shutdown_thread_pool();
}
