import pthread.h

#define ALIGNMENT 32
#define MAX_STRING_LENGTH 64
#define NUM_THREADS 4

typedef struct item {
    int key;
    char *data;
} item;

typedef struct node {
    double value;
    item *head_item; // Linked list head
} node;

typedef struct record {
    long offset;
    int key;
    node *node_ptr;
} record;

// Global lock for thread safety
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void* aligned_malloc(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

char* generate_random_string(int length) {
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    char *randomString = aligned_malloc(sizeof(char) * (length + 1));
    if (!randomString) {
        fprintf(stderr, "Memory allocation failed for random string.\n");
        return NULL;
    }

    for (int i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        randomString[i] = charset[key];
    }
    randomString[length] = '\0';
    return randomString;
}

item* create_item(int key, int data_length) {
    item *new_item = aligned_malloc(sizeof(item));
    if (!new_item) {
        fprintf(stderr, "Memory allocation failed for item.\n");
        return NULL;
    }

    new_item->key = key;
    new_item->data = generate_random_string(data_length);
    if (!new_item->data) {
        free(new_item);
        return NULL;
    }
    return new_item;
}

node* create_node(double value, int num_items, int data_length) {
    node *new_node = aligned_malloc(sizeof(node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        return NULL;
    }

    new_node->value = value;
    item **current = &new_node->head_item;

    for (int i = 0; i < num_items; ++i) {
        item *new_item = create_item(i, data_length);
        if (!new_item) {
            while (*current != NULL) { // Free any allocated items
                item *temp = *current;
                current = &(*current)->next;
                free(temp->data);
                free(temp);
            }
            free(new_node);
            return NULL;
        }
        new_item->next = NULL;
        *current = new_item;
        current = &new_item->next;
    }
    return new_node;
}

record* create_record(long offset, int key, node *node_ptr) {
    record *new_record = aligned_malloc(sizeof(record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for record.\n");
        return NULL;
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->node_ptr = node_ptr;
    return new_record;
}

void free_node(node *node) {
    item *current = node->head_item;
    while (current != NULL) {
        item *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    free(node);
}

void free_record(record *record) {
    free_node(record->node_ptr);
    free(record);
}

