    exit(EXIT_FAILURE);
}

// Thread-safe function to add a record
record* thread_safe_add_record(long offset, int key, double value, int num_items, int data_length) {
    pthread_mutex_lock(&global_lock);

    node *new_node = create_node(value, num_items, data_length);
    if (!new_node) {
        handle_error("Failed to add new record.");
    }

    record *new_record = create_record(offset, key, new_node);
    if (!new_record) {
        free_node(new_node);
        handle_error("Failed to create new record.");
    }

    pthread_mutex_unlock(&global_lock);
    return new_record;
}

void* thread_function(void *arg) {
    long offset = (long)arg;
    record *record = thread_safe_add_record(offset, rand() % 1000, (double)(rand() % 100), 5, MAX_STRING_LENGTH);

    if (!record) {
        log_message("Error creating record in thread.");
    }
    free_record(record);
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (long i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, &thread_function, (void *)i)) {
            handle_error("Failed to create thread.");
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Simulate data integration
    integrate_data_from_source();

    return 0;
}
