#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void log_event(const char* event) {
    printf("Log: %s\n", event);
}

long allocate_aligned(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    log_event("Aligned memory allocated.");
    return (long)ptr;
}

int check_alignment(long address, size_t alignment) {
    return ((uintptr_t)address % alignment) == 0;
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    log_event("Standard memory allocated.");
    return ptr;
}

void free_memory(void* ptr, const char* type) {
    free(ptr);
    log_event(type " memory deallocated.");
}

int verify_unique_keys(int* keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) return 0;
        }
    }
    return 1;
}

void initialize_records(Record* records, size_t count, int min_val, int max_val) {
    srand((unsigned)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

typedef struct {
    size_t size;
    size_t alignment;
} Metadata;

void manage_memory(size_t long_count, size_t int_count, size_t record_count,
                   size_t metadata_count, size_t alignment_boundary,
                   int key_min, int key_max) {

    // Allocate aligned array of 'long' integers
    size_t long_size = long_count * sizeof(long);
    long* offsets = (long*)allocate_aligned(long_size, alignment_boundary);

    // Allocate array of unique 'int' keys
    size_t int_size = int_count * sizeof(int);
    int* keys = (int*)allocate_memory(int_size);

    for (size_t i = 0; i < int_count; ++i) {
        do {
            keys[i] = rand() % (key_max - key_min + 1) + key_min;
        } while (!verify_unique_keys(keys, i + 1));
    }

    // Allocate array of 'Record' structures
    size_t record_size = record_count * sizeof(Record);
    Record* records = (Record*)allocate_memory(record_size);
    initialize_records(records, record_count, key_min, key_max);

    // Metadata storage
    Metadata* metadata = (Metadata*)allocate_memory(metadata_count * sizeof(Metadata));

    metadata[0].size = long_size;
    metadata[0].alignment = alignment_boundary;
    metadata[1].size = int_size;
    metadata[1].alignment = sizeof(int);
    metadata[2].size = record_size;
    metadata[2].alignment = sizeof(Record);

    // Verify integrity
    if (!check_alignment((long)offsets, alignment_boundary)) {
        fprintf(stderr, "Alignment check failed for offsets.\n");
        exit(EXIT_FAILURE);
    }
    if (!verify_unique_keys(keys, int_count)) {
        fprintf(stderr, "Duplicate key detected.\n");
        exit(EXIT_FAILURE);
    }

    // Log successful initialization
    log_event("Memory management completed successfully.");

    // Free allocated memory (example of cleanup)
    free_memory(offsets, "long_offsets");
    free_memory(keys, "int_keys");
    free_memory(records, "records");
    free_memory(metadata, "metadata");
}

int main() {
    manage_memory(10, 5, 7, 3, 16, 0, 100);
    return 0;
}
