#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define ALIGNMENT 32
#define MAX_FEATURES 1000
#define MAX_SAMPLES 500

struct sample {
    int index;
    char string[256];
    union {
        struct sample *next_sample;
        short count;
    } metadata;
};

struct feature {
    double weight;
    unsigned char binary_flag;
    struct sample *samples[MAX_SAMPLES];
};

struct series {
    float values[100]; // Assume a fixed size for simplicity
};

typedef struct {
    long timestamps[1000]; // Assume a fixed size for simplicity
    int indices[1000];
    struct series series_array[10]; // Assume a fixed size for simplicity
    struct feature **features;
} complex_data_structure;

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_POSIX_C_SOURCE) || defined(__linux__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#else
    ptr = _aligned_malloc(size, alignment);
#endif
    return ptr;
}

void free_aligned(void *ptr) {
#if defined(_POSIX_C_SOURCE) || defined(__linux__)
    free(ptr);
#else
    _aligned_free(ptr);
#endif
}

complex_data_structure* initialize_complex_data_structure(int num_features, int max_samples_per_feature) {
    complex_data_structure *cds = aligned_alloc(ALIGNMENT, sizeof(complex_data_structure));
    if (!cds) {
        fprintf(stderr, "Failed to allocate memory for complex data structure.\n");
        return NULL;
    }

    srand(time(NULL));

    // Initialize timestamps and indices
    for (int i = 0; i < 1000; ++i) {
        cds->timestamps[i] = rand() % 1000000L;
        cds->indices[i] = rand() % 1000;
    }

    // Initialize series values
    for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 100; ++j) {
            cds->series_array[i].values[j] = ((float)rand() / RAND_MAX) * 100.0f;
        }
    }

    // Allocate features array
    cds->features = aligned_alloc(ALIGNMENT, num_features * sizeof(struct feature *));
    if (!cds->features) {
        fprintf(stderr, "Failed to allocate memory for features.\n");
        free_aligned(cds);
        return NULL;
    }

    for (int i = 0; i < num_features; ++i) {
        cds->features[i] = aligned_alloc(ALIGNMENT, sizeof(struct feature));
        if (!cds->features[i]) {
            fprintf(stderr, "Failed to allocate memory for feature %d.\n", i);
            for (int j = 0; j < i; ++j) {
                free_aligned(cds->features[j]);
            }
            free_aligned(cds->features);
            free_aligned(cds);
            return NULL;
        }

        cds->features[i]->weight = ((double)rand() / RAND_MAX) * 100.0;
        cds->features[i]->binary_flag = rand() % 2;

        for (int j = 0; j < max_samples_per_feature; ++j) {
            cds->features[i]->samples[j] = aligned_alloc(ALIGNMENT, sizeof(struct sample));
            if (!cds->features[i]->samples[j]) {
                fprintf(stderr, "Failed to allocate memory for sample %d in feature %d.\n", j, i);
                while (j-- > 0) {
                    free_aligned(cds->features[i]->samples[j]);
                }
                free_aligned(cds->features[i]);
                continue;
            }

            cds->features[i]->samples[j]->index = rand() % 10000;
            snprintf(cds->features[i]->samples[j]->string, sizeof(cds->features[i]->samples[j]->string), "Sample_%d", j);

            if (rand() % 2) {
                cds->features[i]->samples[j]->metadata.next_sample = NULL; // Simplified for demo
            } else {
                cds->features[i]->samples[j]->metadata.count = rand() % 100;
            }
        }
    }

    return cds;
}

void free_complex_data_structure(complex_data_structure *cds) {
    if (!cds) return;

    for (int i = 0; i < MAX_FEATURES; ++i) {
        struct feature *feature = cds->features[i];
        if (feature) {
            for (int j = 0; j < MAX_SAMPLES; ++j) {
                free_aligned(feature->samples[j]);
            }
            free_aligned(feature);
        }
    }

    free_aligned(cds->features);
    free_aligned(cds);
}

int main() {
    int num_features = 500;
    int max_samples_per_feature = 50;

    complex_data_structure *cds = initialize_complex_data_structure(num_features, max_samples_per_feature);
    if (!cds) {
        fprintf(stderr, "Initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Use the data structure...

    free_complex_data_structure(cds);

    return EXIT_SUCCESS;
}
```']

