#include <pthread.h>

// Define the constants and limits
#define MAX_LABEL_LENGTH 256
#define ALIGNMENT_BOUNDARY 256

typedef struct {
    void *buffer;
    uint64_t timestamp;
} LargeData;

typedef struct {
    char label[MAX_LABEL_LENGTH + 1];
    uint64_t unique_id;
} Metadata;

typedef struct {
    LargeData *large_data_ptr;
    Metadata *metadata_ptr;
    atomic_int occurrence_count;
} EventLogEntry;

// Function prototypes
void *aligned_alloc(size_t alignment, size_t size);
void free_aligned(void *ptr);
int allocate_large_data_records(LargeData **records, size_t num_records, size_t buffer_size);
int allocate_metadata_entries(Metadata **entries, size_t num_entries, const char *labels[], uint64_t unique_ids[]);
int allocate_event_log_entries(EventLogEntry **logs, size_t num_logs, LargeData *large_datas[], Metadata *metadatas[], pthread_mutex_t *mutex);

// Helper function for aligned memory allocation
void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Failed to allocate memory
    }
    return ptr;
}

// Free aligned memory
void free_aligned(void *ptr) {
    free(ptr);
}

int allocate_large_data_records(LargeData **records, size_t num_records, size_t buffer_size) {
    if (!records || !num_records || !buffer_size) return -1;

    *records = (LargeData *)malloc(num_records * sizeof(LargeData));
    if (!*records) {
        fprintf(stderr, "Error: Memory allocation failed for large_data records.\n");
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].buffer = aligned_alloc(ALIGNMENT_BOUNDARY, buffer_size);
        if (!(*records)[i].buffer) {
            fprintf(stderr, "Error: Aligned memory allocation failed for large_data record %zu.\n", i);
            for (size_t j = 0; j < i; ++j) {
                free_aligned((*records)[j].buffer);
            }
            free(*records);
            *records = NULL;
            return -1;
        }
        (*records)[i].timestamp = 0; // Initialize timestamp
    }

    return 0;
}

int allocate_metadata_entries(Metadata **entries, size_t num_entries, const char *labels[], uint64_t unique_ids[]) {
    if (!entries || !num_entries || !labels || !unique_ids) return -1;

    *entries = (Metadata *)malloc(num_entries * sizeof(Metadata));
    if (!*entries) {
        fprintf(stderr, "Error: Memory allocation failed for metadata entries.\n");
        return -1;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        size_t label_length = strlen(labels[i]);
        if (label_length > MAX_LABEL_LENGTH) {
            fprintf(stderr, "Error: Label length exceeds maximum allowed limit.\n");
            free(*entries);
            *entries = NULL;
            return -1;
        }

        strncpy((*entries)[i].label, labels[i], label_length + 1);
        (*entries)[i].unique_id = unique_ids[i];
    }

    return 0;
}

int allocate_event_log_entries(EventLogEntry **logs, size_t num_logs, LargeData *large_datas[], Metadata *metadatas[], pthread_mutex_t *mutex) {
    if (!logs || !num_logs || !large_datas || !metadatas || !mutex) return -1;

    *logs = (EventLogEntry *)malloc(num_logs * sizeof(EventLogEntry));
    if (!*logs) {
        fprintf(stderr, "Error: Memory allocation failed for event log entries.\n");
        return -1;
    }

    pthread_mutex_lock(mutex);
    for (size_t i = 0; i < num_logs; ++i) {
        (*logs)[i].large_data_ptr = large_datas[i];
        (*logs)[i].metadata_ptr = metadatas[i];
        atomic_init(&(*logs)[i].occurrence_count, 0);
    }
    pthread_mutex_unlock(mutex);

    return 0;
}

// Function to initialize and manage allocations
int init_event_logging_system(size_t num_large_data, size_t buffer_size,
                              size_t num_metadata, const char *metadata_labels[], uint64_t metadata_ids[],
                              size_t num_logs, LargeData *large_datas[], Metadata *metadatas[]) {

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    LargeData *large_data_records = NULL;
    Metadata *metadata_entries = NULL;
    EventLogEntry *event_log_entries = NULL;

    int status = 0;

    // Allocate and initialize large data records
    if (allocate_large_data_records(&large_data_records, num_large_data, buffer_size) != 0) {
        status = -1;
    }

    // Allocate and initialize metadata entries
    if (status == 0 && allocate_metadata_entries(&metadata_entries, num_metadata, metadata_labels, metadata_ids) != 0) {
        status = -1;
    }

    // Allocate and initialize event log entries
    if (status == 0 && allocate_event_log_entries(&event_log_entries, num_logs, large_datas, metadatas, &mutex) != 0) {
        status = -1;
    }

    if (status != 0) {
        fprintf(stderr, "Error: Initialization failed. Cleaning up.\n");
        if (large_data_records) free_large_data_records(large_data_records, num_large_data);
        if (metadata_entries) free(metadata_entries);
        if (event_log_entries) free(event_log_entries);
    } else {
        // Integrity check and return the initialized structures
        printf("Initialization successful. Structures are ready for use.\n");
    }

    pthread_mutex_destroy(&mutex);

    // Return status: 0 on success, -1 on failure
    return status;
}

void free_large_data_records(LargeData *records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free_aligned(records[i].buffer);
    }
    free(records);
}
