```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

public class AuthenticationService
{
    private readonly ConcurrentDictionary<string, UserAccount> _users = new();
    private readonly ILogger _logger;

    public AuthenticationService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public bool CreateUser(string username, string password, int minPasswordLength = 8)
    {
        if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
            return false;

        if (_users.ContainsKey(username))
            return false;

        if (password.Length < minPasswordLength)
            return false;

        var userAccount = new UserAccount
        {
            Username = username,
            PasswordHash = ComputeSha256Hash(password),
            FailedLoginAttempts = 0,
            IsLockedOut = false
        };

        _users.TryAdd(username, userAccount);

        _logger.LogEvent($"User created: {username}");
        return true;
    }

    public bool AuthenticateUser(string username, string password)
    {
        if (_users.TryGetValue(username, out var user))
        {
            if (user.IsLockedOut)
                return false;

            if (user.PasswordHash == ComputeSha256Hash(password))
            {
                _logger.LogEvent($"Successful login: {username}");
                user.FailedLoginAttempts = 0;
                return true;
            }

            user.FailedLoginAttempts++;
            if (user.FailedLoginAttempts >= 5) // configurable lockout threshold
            {
                user.IsLockedOut = true;
                _logger.LogEvent($"User locked out: {username} after 5 failed attempts");
            }
        }

        _logger.LogEvent($"Failed login attempt for user: {username}");
        return false;
    }

    private string ComputeSha256Hash(string rawData)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(rawData));
            StringBuilder builder = new();
            foreach (byte b in bytes) builder.Append(b.ToString("x2"));
            return builder.ToString();
        }
    }

    // Logger interface for abstraction
    public interface ILogger
    {
        void LogEvent(string message);
    }

    public class UserAccount
    {
        public string Username { get; set; }
        public string PasswordHash { get; set; }
        public int FailedLoginAttempts { get; set; }
        public bool IsLockedOut { get; set; }
    }
}
