#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <time.h>
#include "jna/JNA.h"

typedef struct item {
    int key;
    char str[16];
} Item;

typedef struct node {
    double value;
    Item* items;
    size_t itemCount;
    struct node* next;  // Linked list
} Node;

void initializeDataStructures(Node** nodes, size_t count, size_t maxMemoryUsage);

// Example of a function that aligns memory allocation to the nearest multiple of boundary
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (size == 0 || (alignment & (alignment - 1)) != 0) { // Check for power of two and non-zero size
        return NULL;
    }
    if ((ptr = _aligned_malloc(size, alignment)) == NULL) {
        return NULL;
    }
#elif defined(__linux__) || defined(__unix__)
    int result;
    if (posix_memalign(&ptr, alignment, size, &result) != 0) {
        ptr = NULL;
    }
#else
    ptr = malloc(size);
#endif
    return ptr;
}

void initializeDataStructures(Node** nodes, size_t count, size_t maxMemoryUsage) {
    if (!nodes || count == 0)
        return;

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < count; ++i) {
        Node* node = aligned_alloc(32, sizeof(Node));

        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        int randInt = rand() % 100;
        node->value = sqrt(randInt);

        // Simulating a list of items with random data
        size_t itemCount = (rand() % 10) + 1; // 1 to 10 items per node
        Node* current = NULL;

        for (size_t j = 0; j < itemCount; ++j) {
            Item* item = aligned_alloc(32, sizeof(Item));
            if (!item) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }

            item->key = rand() % 100;
            for (int k = 0; k < 16; ++k) { // Random alphanumeric string
                char c = (rand() % 2 == 0) ? ('a' + rand() % 26) : ('0' + rand() % 10);
                item->str[k] = c;
            }
            item->str[15] = '\0';

            if (!current) {
                node->items = item;
            } else {
                current->next = item;
            }

            current = item;
        }

        nodes[i] = node;

        // Verify integrity
        if (node->value < 0 || node->items == NULL)
        {
            fprintf(stderr, "Data integrity check failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

