['Below is a C code implementation for managing a dynamic list of Network Interface Control Block (NICB) structures with the described features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_INTERFACES 1024

typedef struct {
    unsigned char mac_header[14];
    unsigned char destination_mac[6];
    unsigned char source_mac[6];
} MAC_HEADER;

typedef struct {
    unsigned int vlan_id;
    unsigned char priority;
    unsigned short ip_checksum; // Optional
} VLAN_TAG;

typedef struct NICB {
    MAC_HEADER header;
    VLAN_TAG *vlan_tags;
    size_t vlan_count;
    pthread_mutex_t lock;
    struct NICB *next;
} NICB;

typedef struct {
    NICB *head;
    pthread_rwlock_t list_lock;
} InterfaceList;

// Function prototypes
void initialize_list(InterfaceList *list);
int add_interface(InterfaceList *list, MAC_HEADER header, VLAN_TAG *vlan_tags, size_t vlan_count);
int remove_interface(InterfaceList *list, unsigned char *source_mac);
void cleanup_list(InterfaceList *list);

void load_cryptography() {
    OpenSSL_add_all_algorithms();
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest_alias("MD5", "md5");
    EVP_add_digest(EVP_sha256());
    EVP_add_digest_alias("SHA256", "sha256");
}

void initialize_list(InterfaceList *list) {
    list->head = NULL;
    pthread_rwlock_init(&list->list_lock, NULL);
}

int add_interface(InterfaceList *list, MAC_HEADER header, VLAN_TAG *vlan_tags, size_t vlan_count) {
    if (!list || !header.destination_mac || !header.source_mac || !vlan_tags) return -1;

    NICB *new_nicb = (NICB *)malloc(sizeof(NICB));
    if (!new_nicb) return -1;

    memcpy(&new_nicb->header, &header, sizeof(MAC_HEADER));
    new_nicb->vlan_tags = (VLAN_TAG *)malloc(vlan_count * sizeof(VLAN_TAG));
    if (!new_nicb->vlan_tags) {
        free(new_nicb);
        return -1;
    }
    memcpy(new_nicb->vlan_tags, vlan_tags, vlan_count * sizeof(VLAN_TAG));
    new_nicb->vlan_count = vlan_count;

    pthread_mutex_init(&new_nicb->lock, NULL);

    pthread_rwlock_wrlock(&list->list_lock);
    new_nicb->next = list->head;
    list->head = new_nicb;
    pthread_rwlock_unlock(&list->list_lock);

    return 0;
}

int remove_interface(InterfaceList *list, unsigned char *source_mac) {
    if (!list || !source_mac) return -1;

    pthread_rwlock_wrlock(&list->list_lock);
    NICB **current = &list->head;
    while (*current) {
        NICB *entry = *current;
        if (memcmp(entry->header.source_mac, source_mac, 6) == 0) {
            *current = entry->next;
            pthread_mutex_destroy(&entry->lock);
            free(entry->vlan_tags);
            free(entry);
            pthread_rwlock_unlock(&list->list_lock);
            return 0;
        }
        current = &entry->next;
    }
    pthread_rwlock_unlock(&list->list_lock);
    return -1;
}

void cleanup_list(InterfaceList *list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->list_lock);
    NICB *current = list->head;
    while (current) {
        NICB *next = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current->vlan_tags);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_rwlock_unlock(&list->list_lock);
    pthread_rwlock_destroy(&list->list_lock);
}

int main() {
    InterfaceList list;
    initialize_list(&list);

    load_cryptography();

    // Example usage
    MAC_HEADER header = {{0}};
    VLAN_TAG vlan_tags[2] = {{100, 5}, {200, 10}};
    add_interface(&list, header, vlan_tags, 2);

    unsigned char source_mac[6] = {0};
    remove_interface(&list, source_mac);

    cleanup_list(&list);

    EVP_cleanup();
    return 0;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` for individual NICB locks and `pthread_rwlock_t` for the list lock.
- **Cryptography**: Initializes OpenSSL algorithms and adds support for AES, MD5, SHA256, etc.
- **Error Handling**: Checks for null pointers and allocation failures.
- **Dynamic Management**: Supports adding/removing interfaces dynamically.
- **Memory Management**: Properly allocates/free memory for NICB structures and VLAN tags.']

