```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/mman.h>
#include <errno.h>

#define MAX_RECORDS 10000
#define INITIAL_CAPACITY 100

typedef struct {
    short value;
    char identifier;
    float *floatPtr;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int total_allocations;
} RecordManager;

// Error codes
#define ERROR_INVALID_INPUT -1
#define ERROR_OUT_OF_MEMORY -2
#define SUCCESS 0

// Logging function (stub)
void log_message(const char* message) {
    // Integrate with existing logging framework
    printf("%s\n", message);
}

RecordManager *create_record_manager() {
    RecordManager *manager = malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = calloc(INITIAL_CAPACITY, sizeof(Record));
    if (!manager->records) {
        free(manager);
        log_message("Failed to allocate initial memory.");
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->total_allocations = 0;

    pthread_mutex_init(&manager->lock, NULL);

    // Shared memory for inter-process communication
    int shm_fd = shm_open("/record_manager_shm", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
    if (shm_fd == -1) {
        log_message("Failed to create shared memory.");
        return NULL;
    }
    ftruncate(shm_fd, sizeof(RecordManager));
    manager->shared_memory = mmap(NULL, sizeof(RecordManager), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);

    if (manager->shared_memory == MAP_FAILED) {
        log_message("Failed to map shared memory.");
        return NULL;
    }
    memcpy(manager->shared_memory, manager, sizeof(RecordManager));

    close(shm_fd);
    return manager;
}

int add_record(RecordManager *manager, short value, char identifier) {
    if (!manager) return ERROR_INVALID_INPUT;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_RECORDS) {
        log_message("Maximum record limit reached.");
        pthread_mutex_unlock(&manager->lock);
        return ERROR_OUT_OF_MEMORY;
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_RECORDS) new_capacity = MAX_RECORDS;

        Record *temp_records = realloc(manager->records, new_capacity * sizeof(Record));
        if (!temp_records) {
            log_message("Failed to reallocate memory.");
            pthread_mutex_unlock(&manager->lock);
            return ERROR_OUT_OF_MEMORY;
        }

        manager->records = temp_records;
        manager->capacity = new_capacity;
    }

    Record *new_record = &manager->records[manager->count++];
    new_record->value = value;
    new_record->identifier = identifier;

    float *float_value = malloc(sizeof(float));
    if (!float_value) {
        log_message("Failed to allocate memory for float.");
        pthread_mutex_unlock(&manager->lock);
        return ERROR_OUT_OF_MEMORY;
    }

    new_record->floatPtr = float_value;
    manager->total_allocations++;

    // Log allocation event
    char message[100];
    snprintf(message, sizeof(message), "Record added: %d records total, %d allocations", manager->count, manager->total_allocations);
    log_message(message);

    pthread_mutex_unlock(&manager->lock);
    return SUCCESS;
}

void cleanup_record_manager(RecordManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i].floatPtr);
    }

    free(manager->records);

    munmap(manager->shared_memory, sizeof(RecordManager));
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example usage
int main() {
    RecordManager *manager = create_record_manager();
    if (!manager) return 1;

    add_record(manager, 42, 'A');
    cleanup_record_manager(manager);

    return 0;
}
```

### Key Features:

- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations.
- **Dynamic Memory Management**: Handles dynamic allocation and resizing of records.
- **Error Handling**: Provides error codes for invalid inputs or memory issues.
- **Logging**: Logs important events for auditing purposes.
- **Inter-process Communication**: Uses shared memory (`shm_open`, `mmap`) for inter-process communication.
- **Extensibility**: Designed to allow easy modification and addition of new fields.']

