};

struct Event {
    time_t timestamp;
    int severity;
    Event* next;

    Event(time_t ts, int sev) : timestamp(ts), severity(sev), next(nullptr) {}

    void addEvent(Event* new_event) {
        if (!new_event) return;
        new_event->next = events;
        events = new_event;
    }
};

class SensorManager {
private:
