    size_t max_memory_usage_kb;
    std::atomic<size_t> total_memory_used_kb;
    std::mutex mtx;

    bool verifyIntegrity(Sensor* sensor) const {
        return sensor != nullptr && sensor->events != nullptr;
    }

public:
    SensorManager(size_t maxMemoryUsageKB = 50)
        : max_memory_usage_kb(maxMemoryUsageKB), total_memory_used_kb(0) {}

    ~SensorManager() {
        for (auto sensor : sensors) {
            clearEvents(sensor);
            delete sensor;
        }
    }

    bool allocateSensors(size_t num_sensors) {
        std::lock_guard<std::mutex> lock(mtx);

        if ((total_memory_used_kb + (num_sensors * sizeof(Sensor))) > max_memory_usage_kb * 1024) {
            releaseLeastUsedSensors(num_sensors);
        }

        for (size_t i = 0; i < num_sensors; ++i) {
            Sensor* sensor = static_cast<Sensor*>(aligned_alloc(16, sizeof(Sensor)));
            if (!sensor || !verifyIntegrity(sensor)) return false;

            total_memory_used_kb += sizeof(Sensor);
            sensors.push_back(sensor);
        }

        return true;
    }

    void releaseLeastUsedSensors(size_t count) {
        // Implement logic to identify and release least used sensors
        while (sensors.size() > count && total_memory_used_kb > max_memory_usage_kb * 1024) {
            Sensor* sensor = sensors.back();
            clearEvents(sensor);
            free(sensor);
            total_memory_used_kb -= sizeof(Sensor);
            sensors.pop_back();
        }
    }

    void clearEvents(Sensor* sensor) {
        Event* current = sensor->events;
        while (current != nullptr) {
            Event* next = current->next;
            delete current;
            current = next;
        }
        sensor->events = nullptr;
    }

    bool addEventToSensor(size_t index, time_t timestamp, int severity) {
        if (index >= sensors.size()) return false;

        std::lock_guard<std::mutex> lock(mtx);
        Sensor* sensor = sensors[index];
        if (!verifyIntegrity(sensor)) return false;

        Event* new_event = new Event(timestamp, severity);
        if (!new_event) return false;

        sensor->addEvent(new_event);
        total_memory_used_kb += sizeof(Event);

        return true;
    }
};

