from logging.handlers import RotatingFileHandler
import gzip
import shutil
import os

class SystemMonitor:
    def __init__(self, cpu_threshold=80, memory_threshold=70, io_threshold=100):
        self.cpu_threshold = cpu_threshold
        self.memory_threshold = memory_threshold
        self.io_threshold = io_threshold
        self.logger = self.setup_logger()

    def setup_logger(self):
        logger = logging.getLogger("SystemMonitor")
        handler = RotatingFileHandler("system_monitor.log", maxBytes=5*1024*1024, backupCount=3)
        logger.addHandler(handler)
        return logger

    def compress_and_archive_logs(self, remote_server_path):
        if os.path.getsize("system_monitor.log") > 4 * 1024 * 1024:
            with open('system_monitor.log', 'rb') as f_in, gzip.open('system_monitor.log.gz', 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)
            os.remove('system_monitor.log')
            # Code to transfer file to remote_server_path

    def monitor(self):
        while True:
            cpu_usage = psutil.cpu_percent(interval=1)
            memory_info = psutil.virtual_memory()
            disk_io = psutil.disk_io_counters()

            self.logger.info(f"CPU Usage: {cpu_usage}%")
            self.logger.info(f"Memory Usage: {memory_info.percent}%")
            self.logger.info(f"Disk Read Count: {disk_io.read_count}, Write Count: {disk_io.write_count}")

            if cpu_usage > self.cpu_threshold or memory_info.percent > self.memory_threshold:
                self.alert(cpu_usage, memory_info.percent)

            if disk_io.write_bytes + disk_io.read_bytes > self.io_threshold * 1024:
                self.compress_and_archive_logs('/remote/server/path')

            time.sleep(5) # Adjust interval as needed

    def alert(self, cpu_usage, memory_usage):
        print(f"Alert! CPU Usage: {cpu_usage}%, Memory Usage: {memory_usage}%")

    def start_monitoring(self):
        monitoring_thread = threading.Thread(target=self.monitor)
        monitoring_thread.start()

class ServiceManager:
    def __init__(self, critical_services):
        self.critical_services = critical_services

    def restart_service(self, service_name):
        print(f"Restarting {service_name}...")

    def manage_services(self):
        while True:
            for service in self.critical_services:
                if not self.check_service_health(service):
                    self.restart_service(service)
            time.sleep(10)

    def check_service_health(self, service_name):
        # Implement health check logic
        return True

if __name__ == "__main__":
    system_monitor = SystemMonitor()
    critical_services = ['service1', 'service2']
    service_manager = ServiceManager(critical_services)

    system_monitor.start_monitoring()
    service_manager.manage_services()
