#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdint.h>

#ifdef _WIN32
    #include <windows.h>
#else
    #include <semaphore.h>
#endif

#define MAX_MEMORY_USAGE 1048576 // 1 MB limit
#define ALIGNMENT 16
#define RECORD_COUNT 100
#define OFFSET_SIZE sizeof(long)
#define KEY_SIZE sizeof(int)

typedef struct {
    int value;
} record_t;

typedef struct {
    record_t *records;
    long *offsets;
    int *keys;
    HANDLE semaphore; // Windows specific
#ifdef _WIN32
    sem_t posix_semaphore;
#endif
} ResourceManager_t;

void align_memory(void **ptr, size_t alignment) {
    void *original = *ptr;
    uintptr_t offset = (uintptr_t)(alignment - 1) + (uintptr_t)original;
    offset -= offset % alignment;
    *ptr = (void *)offset;
}

ResourceManager_t* ResourceManager(int semaphore_initial_value) {
    size_t record_size = sizeof(record_t);
    size_t total_size = 0;

    // Allocate memory for records
    record_t *records = aligned_alloc(ALIGNMENT, RECORD_COUNT * record_size);
    if (!records) return NULL; 
    align_memory((void**)&records, ALIGNMENT);
    total_size += (uintptr_t)records & (ALIGNMENT - 1);

    // Allocate memory for offsets
    long *offsets = aligned_alloc(ALIGNMENT, RECORD_COUNT * OFFSET_SIZE);
    if (!offsets) {
        free(records);
        return NULL;
    }
    align_memory((void**)&offsets, ALIGNMENT);
    total_size += (uintptr_t)offsets & (ALIGNMENT - 1);

    // Allocate memory for keys
    int *keys = aligned_alloc(ALIGNMENT, RECORD_COUNT * KEY_SIZE);
    if (!keys) {
        free(records);
        free(offsets);
        return NULL;
    }
    align_memory((void**)&keys, ALIGNMENT);
    total_size += (uintptr_t)keys & (ALIGNMENT - 1);

    // Check total memory usage
    if (total_size > MAX_MEMORY_USAGE) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    ResourceManager_t *manager = malloc(sizeof(ResourceManager_t));
    if (!manager) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    manager->records = records;
    manager->offsets = offsets;
    manager->keys = keys;

#ifdef _WIN32
    // Initialize semaphore for Windows
    manager->semaphore = CreateSemaphore(NULL, semaphore_initial_value, SEMAPHORE_MAX_COUNT, NULL);
#else
    // Initialize semaphore for POSIX systems
    if (sem_init(&manager->posix_semaphore, 0, semaphore_initial_value) != 0) {
        free(manager);
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }
#endif

    srand((unsigned int)time(NULL));
    for (int i = 0; i < RECORD_COUNT; ++i) {
        manager->records[i].value = rand() % 100; // Random value between 0 and 99
        manager->offsets[i] = rand();             // Random long offset
        manager->keys[i] = rand() % 256;          // Random key byte value
    }

    // Verify integrity (simple check for demonstration)
    for (int i = 0; i < RECORD_COUNT; ++i) {
        if (manager->records[i].value == -1 || 
            manager->offsets[i] == 0 || 
            manager->keys[i] == -1) {
            #ifdef _WIN32
                CloseHandle(manager->semaphore);
            #else
                sem_destroy(&manager->posix_semaphore);
            #endif
            free(manager->records);
            free(manager->offsets);
            free(manager->keys);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void cleanup(ResourceManager_t *manager) {
    if (!manager) return;

#ifdef _WIN32
    CloseHandle(manager->semaphore);
#else
    sem_destroy(&manager->posix_semaphore);
#endif

    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free(manager);
}
