#include <stdio.h>
#include <stdlib.h>
import <stdint.h>
#include <pthread.h>

#define CRCFLAG_MAX 255

// Structure Definitions
typedef struct {
    uint32_t rnti;
    // Additional fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t crcflag;
    // Additional fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
static size_t failure_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread safety

// Memory Pool Structure (simplified for illustration)
typedef struct {
    void *pool;
    size_t block_size;
    size_t num_blocks;
} MemoryPool;

MemoryPool memory_pool;

// Function to initialize the memory pool
void init_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool.block_size = block_size;
    memory_pool.num_blocks = num_blocks;
    memory_pool.pool = malloc(block_size * num_blocks);
}

// Function to clean up the memory pool
void cleanup_memory_pool() {
    free(memory_pool.pool);
    pthread_mutex_destroy(&lock);
}

// Allocate a block from the memory pool
void* allocate_block_from_pool() {
    static size_t current_index = 0;

    if (current_index >= memory_pool.num_blocks) return NULL;

    void *block = ((uint8_t*)memory_pool.pool) + current_index * memory_pool.block_size;
    pthread_mutex_lock(&lock);
    ++current_index;
    pthread_mutex_unlock(&lock);

    return block;
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu_list(size_t n, size_t block_size) {
    if (n == 0 || memory_pool.pool == NULL) {
        fprintf(stderr, "Invalid input or uninitialized memory pool\n");
        return NULL;
    }

    init_memory_pool(block_size, n);

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = allocate_block_from_pool();
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed for PDU list\n");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        // Create RX_UE_INFORMATION_TAG
        pdu_list[i].rx_ue_information_tag.rnti = rand() % 10000;  // Example RNTI assignment

        // Set RNTI
        pdu_list[i].rnti = pdu_list[i].rx_ue_information_tag.rnti;

        // Validate and set CRCFLAG in CRC_INDICATION_REL8_TAG
        uint8_t crcflag = rand() % 300;  // Random value for demonstration
        if (crcflag <= CRCFLAG_MAX) {
            pdu_list[i].crc_indication_rel8_tag.crcflag = crcflag;
        } else {
            pthread_mutex_lock(&lock);
            ++failure_count;
            pthread_mutex_unlock(&lock);
            fprintf(stderr, "Invalid CRCFLAG value: %u\n", crcflag);
        }
    }

    return pdu_list;
}

// Example usage
int main() {
    size_t num_pdus = 1000; // Number of PDUs to create
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    NFAPI_CRC_INDICATION_PDU_T *pdus = create_crc_pdu_list(num_pdus, block_size);
    if (!pdus) {
        fprintf(stderr, "Failed to create PDU list\n");
        cleanup_memory_pool();
        return EXIT_FAILURE;
    }

    // Use the PDUs...

    cleanup_memory_pool();
    return EXIT_SUCCESS;
}
