#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define MEMORY_THRESHOLD (1024 * 1024) // 1 MB for example

typedef struct {
    int value;
    char *str;
} Record;

typedef struct {
    Record **records;
    size_t count;
    pthread_mutex_t lock;
    size_t total_allocated_memory;
    pthread_mutex_t mem_lock;
} RecordCollection;

// Memory pool management
#define POOL_SIZE 1024 // Example size, adjust as needed
char memory_pool[POOL_SIZE];
size_t next_free_index = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (next_free_index + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return malloc(size); // Fallback to standard allocation
    }

    void *ptr = &memory_pool[next_free_index];
    next_free_index += size;
    pthread_mutex_unlock(&pool_lock);

    return ptr;
}

void custom_free(void *ptr, size_t size) {
    // Custom free is a no-op; memory pool manages free space
}

// Initialize record collection
RecordCollection* init_record_collection(size_t initial_size) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    pthread_mutex_init(&collection->lock, NULL);
    pthread_mutex_init(&collection->mem_lock, NULL);

    collection->records = (Record**)custom_malloc(initial_size * sizeof(Record*));
    collection->count = 0;
    collection->total_allocated_memory = initial_size * sizeof(Record*);

    return collection;
}

// Add record
void add_record(RecordCollection *collection, int value, const char *str) {
    pthread_mutex_lock(&collection->lock);

    size_t new_count = collection->count + 1;
    if (new_count > collection->count) { // Check for overflow
        Record **new_records = (Record**)custom_malloc(new_count * sizeof(Record*));
        memcpy(new_records, collection->records, collection->count * sizeof(Record*));

        pthread_mutex_lock(&collection->mem_lock);
        size_t additional_memory = new_count * sizeof(Record*);
        if (collection->total_allocated_memory + additional_memory > MEMORY_THRESHOLD) {
            fprintf(stderr, "Memory threshold exceeded\n");
            pthread_mutex_unlock(&collection->mem_lock);
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->total_allocated_memory += additional_memory;
        pthread_mutex_unlock(&collection->mem_lock);

        custom_free(collection->records, collection->count * sizeof(Record*));
        collection->records = new_records;
    }

    Record *record = (Record*)custom_malloc(sizeof(Record) + MAX_STRING_LENGTH);
    record->value = value;

    strncpy(record->str, str, MAX_STRING_LENGTH - 1);
    record->str[MAX_STRING_LENGTH - 1] = '\0';

    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->lock);
}

// Read record
Record* read_record(RecordCollection *collection, size_t index) {
    pthread_mutex_lock(&collection->lock);
    Record *record = NULL;
    if (index < collection->count) {
        record = collection->records[index];
    }
    pthread_mutex_unlock(&collection->lock);
    return record;
}

// Free collection
void free_record_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->mem_lock);

    for (size_t i = 0; i < collection->count; ++i) {
        custom_free(collection->records[i], sizeof(Record) + MAX_STRING_LENGTH);
    }

    custom_free(collection->records, collection->count * sizeof(Record*));
    pthread_mutex_unlock(&collection->mem_lock);

    pthread_mutex_destroy(&collection->lock);
    pthread_mutex_destroy(&collection->mem_lock);
    free(collection);
}

// Test module
void test_record_collection() {
    RecordCollection *collection = init_record_collection(10);

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < 20; ++i) {
        int value = rand() % 100;
        char str[MAX_STRING_LENGTH] = "TestString";
        add_record(collection, value, str);
    }

    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = read_record(collection, i);
        if (record != NULL) {
            printf("Record %zu: Value=%d, String=%s\n", i, record->value, record->str);
        }
    }

    free_record_collection(collection);
}

int main() {
    test_record_collection();
    return 0;
}
