['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MAC_ADDRESS 6

typedef struct {
    uint8_t source[6];
    uint8_t destination[6];
} MAC_HEADER;

typedef struct {
    uint16_t tag; // VLAN ID
    uint3 priority;
} VLAN_TAG;

typedef struct {
    int enable_interface;
    int calculate_ip_checksum;
} CONFIG_OPTIONS;

typedef struct NICB {
    MAC_HEADER mac_header;
    VLAN_TAG vlan_tag;
    CONFIG_OPTIONS config_options;
} NICB;

// Custom memory pool for efficient allocation
#define MEMORY_POOL_SIZE 1024 * 64 // Adjust size as needed

static uint8_t memory_pool[MEMORY_POOL_SIZE];
static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_size = 0;

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&mem_lock);
    if (allocated_size + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mem_lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[allocated_size];
    allocated_size += size;
    pthread_mutex_unlock(&mem_lock);
    return ptr;
}

void custom_free_all() {
    pthread_mutex_lock(&mem_lock);
    allocated_size = 0;
    pthread_mutex_unlock(&mem_lock);
}

// Thread-safe hash table for NICB management
#define HASH_TABLE_SIZE 256

typedef struct HashNode {
    uint32_t key; // Simple key based on NICB pointer
    struct NICB* nicb;
    struct HashNode* next;
} HashNode;

static HashNode* hash_table[HASH_TABLE_SIZE];
static pthread_mutex_t hash_locks[HASH_TABLE_SIZE];

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_locks[i], NULL);
    }
}

uint32_t hash_function(struct NICB* nicb) {
    return ((uintptr_t)nicb >> 3) & (HASH_TABLE_SIZE - 1); // Simple hash function
}

void insert_nicb_to_table(struct NICB* nicb) {
    uint32_t index = hash_function(nicb);
    pthread_mutex_lock(&hash_locks[index]);

    HashNode* node = (HashNode*)custom_alloc(sizeof(HashNode));
    if (!node) {
        pthread_mutex_unlock(&hash_locks[index]);
        return; // Out of memory
    }

    node->key = ((uintptr_t)nicb >> 3);
    node->nicb = nicb;
    node->next = hash_table[index];
    hash_table[index] = node;

    pthread_mutex_unlock(&hash_locks[index]);
}

struct NICB* get_nicb_from_table(uintptr_t key) {
    uint32_t index = key & (HASH_TABLE_SIZE - 1);
    pthread_mutex_lock(&hash_locks[index]);

    HashNode* current = hash_table[index];
    while (current) {
        if (current->key == key) {
            struct NICB* nicb = current->nicb;
            pthread_mutex_unlock(&hash_locks[index]);
            return nicb;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&hash_locks[index]);
    return NULL; // Not found
}

void init_and_populate_nicbs(NICB** nicbs, size_t count) {
    if (!nicbs || count == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        NICB* nicb = custom_alloc(sizeof(NICB));
        if (!nicb) {
            fprintf(stderr, "Memory allocation failed at index %zu\n", i);
            break;
        }

        // Populate MAC address with random data
        for (int j = 0; j < MAX_MAC_ADDRESS; ++j) {
            nicb->mac_header.source[j] = rand() % 256;
            nicb->mac_header.destination[j] = rand() % 256;
        }

        // Generate a random VLAN tag
        nicb->vlan_tag.tag = (rand() % 4096) | ((rand() % 8) << 13);
        nicb->config_options.enable_interface = 1; // Default enabled
        nicb->config_options.calculate_ip_checksum = 0; // Default not calculated

        insert_nicb_to_table(nicb);

        nicbs[i] = nicb;
    }
}

void reconfigure_nicb(uintptr_t key, uint16_t new_vlan_tag, const uint8_t* new_mac_address) {
    struct NICB* nicb = get_nicb_from_table(key);
    if (!nicb) {
        fprintf(stderr, "NICB not found for key: %u\n", key);
        return;
    }

    pthread_mutex_lock(&hash_function(nicb));
    memcpy(nicb->mac_header.source, new_mac_address, MAX_MAC_ADDRESS);
    nicb->vlan_tag.tag = new_vlan_tag;
    pthread_mutex_unlock(&hash_function(nicb));
}

void cleanup_nicbs() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        pthread_mutex_lock(&hash_locks[i]);

        HashNode* current = hash_table[i];
        while (current) {
            HashNode* next = current->next;
            custom_alloc(-sizeof(HashNode)); // Custom free logic
            current = next;
        }
        hash_table[i] = NULL;

        pthread_mutex_unlock(&hash_locks[i]);
    }

    custom_free_all();
}

int main() {
    size_t count = 10; // Example count, adjust as needed
    NICB* nicbs[count];

    init_hash_table();
    init_and_populate_nicbs(nicbs, count);

    // Example reconfiguration of the first NICB
    uint8_t new_mac_address[MAX_MAC_ADDRESS] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06};
    reconfigure_nicb((uintptr_t)nicbs[0], 100, new_mac_address);

    cleanup_nicbs();

    return 0;
}
```

### Explanation:
- **Custom Allocator**: A simple fixed-size memory pool with a mutex for thread-safe allocation is used to minimize fragmentation and improve performance.
- **Thread-Safe Hash Table**: Each bucket in the hash table has its own mutex, allowing concurrent access while avoiding contention across different buckets.
- **Initialization and Reconfiguration**: The NICBs are initialized with random MAC addresses and VLAN tags. They can be reconfigured by accessing them through a key-based lookup in the thread-safe hash table.
- **Concurrency Management**: Use of mutexes ensures that operations on shared data structures (memory pool and hash table) are safe across multiple threads.
- **Cleanup Functionality**: Provides mechanisms to free allocated memory and reset state when necessary.

This implementation focuses on balancing performance, safety, and ease of management for large-scale NICB arrays.']

