        if (!sub_array) {
            free(nicb_array.nicbs);
            log_error("Memory allocation failed for sub-array.");
            return ERROR_MEMORY_ALLOCATION_FAILURE;
        }
        sub_array->nicbs = nicb_array.nicbs + (i * chunk_size);
        sub_array->count = (i == 3) ? count - (chunk_size * i) : chunk_size;

        pthread_create(&threads[i], NULL, worker_thread, (void*)sub_array);
    }

    for (int i = 0; i < 4; ++i)
        pthread_join(threads[i], NULL);

    free(nicb_array.nicbs);

    if (failed_mac_validations > 0) {
