typedef struct Record {
    int key;
    double value;
    char *identifier;
    char *additionalData;
    struct Record *next;
} Record;

// Function to verify the integrity of the linked list and allocated memory
int verifyLinkedListIntegrity(Record *head) {
    if (!head) return 1; // Empty list is considered valid

    int seenCount = 0;
    unsigned long seenIdentifiers[1024] = {0}; // Assuming a reasonable max number of records for hashing

    Record *current = head, *prev = NULL;

    while (current) {
        if (!current->identifier || !current->additionalData) return 0; // Null pointers in strings

        // Check for cycles
        unsigned long identifierHash = hashIdentifier(current->identifier);

        if (seenIdentifiers[identifierHash % 1024]) return 0;
        seenIdentifiers[identifierHash % 1024] = 1;
        seenCount++;

        prev = current;
        current = current->next;

        // Check for memory leaks
        if (!current && prev) break; // Normal termination

        if (prev == current) {
            return 0; // Cycle detected
        }
    }

    return seenCount > 0; // Return true if at least one record was found and no issues were detected
}

unsigned long hashIdentifier(const char *identifier) {
    unsigned long hash = 5381;
    int c;

    while ((c = *identifier++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

// Function to free all allocated memory for the linked list
void freeLinkedList(Record *head) {
    Record *current = head, *next;

    while (current != NULL) {
        next = current->next;

        free(current->identifier);
        free(current->additionalData);

        free(current);
        current = next;
    }
}

// Function to handle memory allocation errors
void handleMemoryError(void **ptr, const char *message) {
    if (!*ptr) {
        fprintf(stderr, "Memory allocation error: %s\n", message);

        // Free any previously allocated resources before returning or exiting
        freeLinkedList((Record *) ptr);

        exit(EXIT_FAILURE); // Or return an error code based on function requirements
    }
}
