struct CustomAllocator;

impl CustomAllocator {
    fn allocate<T>(&self, layout: std::alloc::Layout) -> *mut T {
        let aligned_size = (layout.size() + ALIGNMENT - 1) & !(ALIGNMENT - 1);
        let ptr = unsafe { libc::aligned_alloc(ALIGNMENT, aligned_size) };
        if ptr.is_null() {
            panic!("Failed to allocate memory");
        }
        ptr as *mut T
    }

    fn deallocate<T>(&self, ptr: *mut T) {
        unsafe { libc::free(ptr as *mut libc::c_void) };
    }
}

