#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define ALIGNMENT 32
#define LOG_LEVEL_DEBUG 1
#define NUM_ENTRIES 1000

typedef struct {
    time_t timestamp;
    int log_level;
    char message[256];
    int error_code;
} log_entry;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
#endif
    return ptr;
}

void free_aligned(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

typedef struct {
    log_entry* entries;
    pthread_spinlock_t lock;
} logging_system;

logging_system* init_logging_system(size_t num_entries, size_t entry_size) {
    logging_system* system = (logging_system*)malloc(sizeof(logging_system));
    if (!system) return NULL;

    size_t total_size = num_entries * entry_size + sizeof(void*);
    size_t aligned_size = ((total_size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;

    system->entries = (log_entry*)aligned_alloc(ALIGNMENT, aligned_size);
    if (!system->entries) {
        free(system);
        return NULL;
    }

    pthread_spin_init(&system->lock, PTHREAD_PROCESS_PRIVATE);

    for (size_t i = 0; i < num_entries; ++i) {
        system->entries[i].timestamp = time(NULL);
        system->entries[i].log_level = LOG_LEVEL_DEBUG;
        snprintf(system->entries[i].message, sizeof(system->entries[i].message), "Log entry %zu", i);
        system->entries[i].error_code = 0;
    }

    return system;
}

void destroy_logging_system(logging_system* system) {
    if (system) {
        pthread_spin_destroy(&system->lock);
        free_aligned(system->entries);
        free(system);
    }
}

void populate_log_entries(logging_system* system, size_t start_index, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        size_t index = start_index + i;
        pthread_spin_lock(&system->lock);

        if (index < NUM_ENTRIES) {
            system->entries[index].timestamp = time(NULL);
            system->entries[index].log_level = LOG_LEVEL_DEBUG;
            snprintf(system->entries[index].message, sizeof(system->entries[index].message), "Updated log entry %zu", index);
            system->entries[index].error_code = 0; // Simulate a change in error code
        }

        pthread_spin_unlock(&system->lock);
    }
}

void* thread_function(void* arg) {
    logging_system* system = (logging_system*)arg;
    size_t num_threads = 4;
    size_t entries_per_thread = NUM_ENTRIES / num_threads;

    populate_log_entries(system, pthread_self() % num_threads * entries_per_thread, entries_per_thread);

    return NULL;
}

int main() {
    size_t entry_size = sizeof(log_entry);
    logging_system* system = init_logging_system(NUM_ENTRIES, entry_size);
    if (!system) {
        fprintf(stderr, "Failed to initialize logging system\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, system)) {
            perror("Thread creation failed");
            destroy_logging_system(system);
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Verify integrity of allocated data
    for (size_t i = 0; i < NUM_ENTRIES; ++i) {
        if (!system->entries[i].timestamp || !system->entries[i].message[0]) {
            fprintf(stderr, "Data corruption detected\n");
            destroy_logging_system(system);
            return EXIT_FAILURE;
        }
    }

    destroy_logging_system(system);

    return EXIT_SUCCESS;
}
