    time_t mtime;
    time_t ctime;
    mode_t mode;
    uid_t uid;
    gid_t gid;
} FileMetadata;

typedef struct {
    FileMetadata metadata;
    unsigned char hash[EVP_MAX_MD_SIZE];
    size_t hash_len;
} FSCB;

static void log_message(int level, const char *message) {
    if (level <= LOG_LEVEL) { // Assume LOG_LEVEL is defined globally
        printf("%s\n", message);
    }
}

void initialize_fscb_array() {
    EVP_add_digest("SHA256", EVP_sha256(), NULL);
    EVP_add_digest("SHA3_256", EVP_sha3_256(), NULL);
    EVP_add_digest("BLAKE2B", EVP_blake2b(), NULL);

    EVP_add_cipher("AES-128-CBC", EVP_aes_128_cbc(), NULL);
    EVP_add_cipher("AES-128-GCM", EVP_aes_128_gcm(), NULL);

    FSCB fscbs[MAX_FILES];
    memset(fscbs, 0, sizeof(FSCB) * MAX_FILES);

