        fscbs[i].metadata.uid = getuid();
        fscbs[i].metadata.gid = getgid();

        const char *digest_name = "SHA256";
        EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
        if (!mdctx) {
            log_message(1, "Failed to create EVP_MD_CTX");
            continue;
        }

        if (EVP_DigestInit_ex(mdctx, EVP_get_digestbyname(digest_name), NULL) != 1) {
            log_message(1, "Failed to initialize digest context");
            EVP_MD_CTX_free(mdctx);
            continue;
        }

        const char *data = "Sample data for hashing";
        if (EVP_DigestUpdate(mdctx, data, strlen(data)) != 1) {
            log_message(1, "Failed to update digest");
            EVP_MD_CTX_free(mdctx);
            continue;
        }

        if (EVP_DigestFinal_ex(mdctx, fscbs[i].hash, &fscbs[i].hash_len) != 1) {
            log_message(1, "Failed to finalize digest");
            EVP_MD_CTX_free(mdctx);
            continue;
        }

        EVP_MD_CTX_free(mdctx);

        // Handle encryption setup if needed
    }
