import random
import math

class Node:
    def __init__(self, value):
        self.key = 0
        self.value = value
        self.items = []
        self.next = None

def initialize_node(seed_value, num_items):
    initial_value = calculate_value(seed_value)
    return populate_items(Node(initial_value), num_items)

def allocate_item(key, string_seed):
    unique_string = generate_unique_string(string_seed)
    return {'key': key, 'string': unique_string}

def populate_items(node, num_items):
    for i in range(num_items):
        item = allocate_item(i + 1, random.randint(0, 10000))
        node.items.append(item)
    return node

def calculate_value(seed_value):
    return math.sqrt(seed_value)

def verify_node(node):
    valid = True
    for item in node.items:
        if not (isinstance(item['key'], int) and isinstance(item['string'], str)):
            valid = False
            break
    return valid

def generate_unique_string(seed):
    random.seed(seed)
    chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
    return ''.join(random.choice(chars) for _ in range(10))

# Example usage:
if __name__ == "__main__":
    seed_value = 16.0  # Example seed value
    num_items = 5      # Number of items per node

    new_node = initialize_node(seed_value, num_items)

    if verify_node(new_node):
        print("Node verification passed.")
    else:
        print("Node verification failed.")

    for item in new_node.items:
        print(f"Key: {item['key']}, String: {item['string']}")
