#define ALIGNMENT 64
#define MAX_NODES 100
#define ITEMS_PER_NODE 10
#define ALPHANUM_LENGTH 8

struct node {
    double value;
};

struct item {
    int key;
    std::string data;
    std::string metadata;
    item* next;
};

void alignAndAllocate(void*& ptr, size_t& size) {
    void* alignedPtr = nullptr;
#ifdef _WIN32
    if (posix_memalign(&alignedPtr, ALIGNMENT, size)) {
        throw std::bad_alloc();
    }
#else
    alignedPtr = std::aligned_alloc(ALIGNMENT, size);
    if (!alignedPtr) {
        throw std::bad_alloc();
    }
#endif
    ptr = alignedPtr;
}

double calculateRandomDouble(int min, int max) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min, max);
    return round(sqrt(dis(gen)) * 1000.0) / 1000.0;
}

std::string generateAlphanumericString(size_t length) {
    const char* chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, strlen(chars) - 1);

    std::string result(length, '\0');
    for (size_t i = 0; i < length; ++i) {
        result[i] = chars[dis(gen)];
    }
    return result;
}

std::string generateMetadata() {
    // Simulate predefined probability distribution
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 10);

    if (dis(gen) < 5) {
        return "TypeA";
    } else {
        return "TypeB";
    }
}

void logError(const std::string& message) {
    std::cerr << "[ERROR] " << message << std::endl;
}

void manageMemory() {
    try {
        node* nodes[MAX_NODES];
        size_t arraySize = sizeof(node*) * MAX_NODES;
        alignAndAllocate(nodes, arraySize);

        item* headItem = nullptr;
        alignAndAllocate(headItem, sizeof(item));

        int* dynamicIntArray = nullptr;
        size_t dynamicArraySize = 10; // Initial size
        alignAndAllocate(dynamicIntArray, sizeof(int) * dynamicArraySize);

        std::mutex mtx;

        for (int i = 0; i < MAX_NODES; ++i) {
            nodes[i] = nullptr;
            size_t nodeSize = sizeof(node);
            alignAndAllocate(nodes[i], nodeSize);
            nodes[i]->value = calculateRandomDouble(1, 100);

            item* currentItem = headItem;
            for (int j = 0; j < ITEMS_PER_NODE; ++j) {
                item* newItem = nullptr;
                size_t itemSize = sizeof(item);
                alignAndAllocate(newItem, itemSize);

                std::lock_guard<std::mutex> lock(mtx);

                newItem->key = i * ITEMS_PER_NODE + j;  // Unique key generation
                newItem->data = generateAlphanumericString(ALPHANUM_LENGTH);
                newItem->metadata = generateMetadata();
                newItem->next = nullptr;

                if (!currentItem) {
                    headItem = newItem;
                } else {
                    while (currentItem->next) {
                        currentItem = currentItem->next;
                    }
                    currentItem->next = newItem;
                }

                currentItem = newItem; // Move to the next item
            }
        }

        int initialCapacity = 10;
        std::vector<int> vectorIntArray(initialCapacity);

        for (int i = 0; i < MAX_NODES; ++i) {
            if (i >= dynamicArraySize) {
                size_t newSize = std::max(dynamicArraySize * 2, i + 1);
                int* newDynamicIntArray = nullptr;
                alignAndAllocate(newDynamicIntArray, sizeof(int) * newSize);

                std::copy(dynamicIntArray, dynamicIntArray + dynamicArraySize, newDynamicIntArray);
                delete[] dynamicIntArray;
                dynamicIntArray = newDynamicIntArray;
                dynamicArraySize = newSize;
            }

            dynamicIntArray[i] = static_cast<int>(nodes[i]->value);
        }

    } catch (const std::bad_alloc& e) {
        logError("Memory allocation failed: " + std::string(e.what()));
    } catch (...) {
        logError("An unexpected error occurred.");
    }
}

int main() {
    manageMemory();
    return 0;
}
