#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    int *keyPointer;
} record;

void reset_records(record *records, size_t record_count, const int *keys) {
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = -1; // Indicating uninitialized state
        records[i].keyPointer = NULL;
    }
}

int initialize_memory(long *offsets, size_t offset_count,
                      int *keys, size_t key_count,
                      record *records, size_t record_count,
                      size_t memory_limit) {

    // Calculate required memory
    size_t total_memory_required =
        sizeof(long) * offset_count +
        sizeof(int) * key_count +
        sizeof(record) * record_count;

    if (total_memory_required > memory_limit) {
        fprintf(stderr, "Memory limit exceeded.\n");
        return -1; // Memory allocation failed due to exceeding limit
    }

    // Allocate and initialize memory for offsets
    long *allocated_offsets = malloc(total_memory_required);
    if (!allocated_offsets) {
        perror("Failed to allocate memory for offsets");
        return -1;
    }
    memcpy(allocated_offsets, offsets, sizeof(long) * offset_count);

    // Calculate remaining memory after allocating offsets
    size_t remaining_memory = total_memory_required - (sizeof(long) * offset_count);

    // Allocate and initialize keys
    int *allocated_keys = (int *)(allocated_offsets + offset_count);
    if (!allocated_keys && key_count > 0) {
        perror("Failed to allocate memory for keys");
        free(allocated_offsets);
        return -1;
    }
    memcpy(allocated_keys, keys, sizeof(int) * key_count);

    // Calculate remaining memory after allocating keys
    remaining_memory -= (sizeof(int) * key_count);

    // Allocate and initialize records
    record *allocated_records = (record *)(allocated_keys + key_count);
    if (!allocated_records && record_count > 0) {
        perror("Failed to allocate memory for records");
        free(allocated_offsets);
        return -1;
    }
    memcpy(allocated_records, records, sizeof(record) * record_count);

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Populate records with unique random values and key pointers
    for (size_t i = 0; i < record_count; ++i) {
        allocated_records[i].value = rand() % 1000 + 1; // Random range [1, 1000]
        allocated_records[i].keyPointer = &allocated_keys[i];
    }

    // Replace original pointers with newly allocated ones
    memcpy(offsets, allocated_offsets, sizeof(long) * offset_count);
    memcpy(keys, allocated_keys, sizeof(int) * key_count);
    memcpy(records, allocated_records, sizeof(record) * record_count);

    return 0; // Success
}

void free_memory(void *memory_block, size_t total_size) {
    if (memory_block) {
        free(memory_block);
    }
}

int main() {
    long offsets[] = {0};
    int keys[5] = {1, 2, 3, 4, 5};
    record records[5] = {{0}, {0}, {0}, {0}, {0}};

    size_t memory_limit = sizeof(long) * 10 + sizeof(int) * 20 + sizeof(record) * 15;

    if (initialize_memory(offsets, 1, keys, 5, records, 5, memory_limit) != 0) {
        fprintf(stderr, "Initialization failed.\n");
        return -1;
    }

    // Demonstrate reset functionality
    reset_records(records, 5, keys);

    // Free allocated memory (in practice this would be managed by a higher-level logic)
    free_memory(offsets, sizeof(long));

    printf("Memory management completed successfully.\n");

    return 0;
}
```

### Explanation:

1. **Data Structure Management**: The function accepts arrays for `long` offsets, `int` keys, and `record` structures.
2. **Memory Allocation & Initialization**: Memory is allocated based on the total memory required, ensuring it doesn't exceed the specified limit.
3. **Random Number Generation**: Uses a pseudo-random number generator initialized with `srand(time(NULL))` for simplicity; in multi-threaded contexts, consider more sophisticated solutions like thread-local storage or mutexes.
4. **Error Handling**: Includes checks and error messages for allocation failures.
5. **Reset Functionality**: A separate function to reset records without re-allocating memory.
6. **Memory Deallocation**: The `free_memory` function is used to deallocate resources properly.

This implementation prioritizes safety, performance, and scalability within the outlined constraints. Further refinement might be required for specific multi-threaded or high-performance environments.']

['Below is a modular implementation in C for a scalable network interface management system with support for dynamic addition/removal of interfaces, feature toggling, and integration with existing network stacks:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_INTERFACES 10000

typedef struct {
    int id;
    char name[32];
    unsigned char enabled; // 1 for enabled, 0 for disabled
    unsigned char link_aggregation_enabled;
    unsigned char qos_enabled;
    unsigned char encryption_enabled;
} NetworkInterface;

typedef struct {
    NetworkInterface *interfaces[MAX_INTERFACES];
    pthread_mutex_t lock;
    size_t count;
} InterfaceManager;

// Function Prototypes
int initialize_interface_manager(InterfaceManager *manager);
void destroy_interface_manager(InterfaceManager *manager);
int add_interface(InterfaceManager *manager, const char *name);
int remove_interface(InterfaceManager *manager, int id);
int enable_feature(NetworkInterface *interface, unsigned char link_agg, unsigned char qos, unsigned char encryption);
int disable_feature(NetworkInterface *interface);

// Initialization and Cleanup
int initialize_interface_manager(InterfaceManager *manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    memset(manager->interfaces, 0, sizeof(manager->interfaces));
    return 0;
}

void destroy_interface_manager(InterfaceManager *manager) {
    for (size_t i = 0; i < MAX_INTERFACES && manager->interfaces[i] != NULL; ++i) {
        free(manager->interfaces[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}

// Interface Management
int add_interface(InterfaceManager *manager, const char *name) {
    if (pthread_mutex_lock(&manager->lock)) return -1;

    if (manager->count >= MAX_INTERFACES) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Out of capacity
    }

    NetworkInterface *interface = malloc(sizeof(NetworkInterface));
    if (!interface) {
        pthread_mutex_unlock(&manager->lock);
        return -3; // Memory allocation failed
    }

    interface->id = manager->count;
    strncpy(interface->name, name, sizeof(interface->name) - 1);
    interface->enabled = 0;
    interface->link_aggregation_enabled = 0;
    interface->qos_enabled = 0;
    interface->encryption_enabled = 0;

    manager->interfaces[manager->count++] = interface;

    pthread_mutex_unlock(&manager->lock);
    return interface->id;
}

int remove_interface(InterfaceManager *manager, int id) {
    if (pthread_mutex_lock(&manager->lock)) return -1;

    for (size_t i = 0; i < MAX_INTERFACES; ++i) {
        if (manager->interfaces[i] && manager->interfaces[i]->id == id) {
            free(manager->interfaces[i]);
            memmove(&manager->interfaces[i], &manager->interfaces[i + 1], sizeof(NetworkInterface*) * (manager->count - i - 1));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -2; // Interface not found
}

// Feature Management
int enable_feature(NetworkInterface *interface, unsigned char link_agg, unsigned char qos, unsigned char encryption) {
    if (!interface->enabled) return -1;

    interface->link_aggregation_enabled = link_agg;
    interface->qos_enabled = qos;
    interface->encryption_enabled = encryption;
    return 0;
}

int disable_feature(NetworkInterface *interface) {
    if (!interface->enabled) return -1;

    interface->link_aggregation_enabled = 0;
    interface->qos_enabled = 0;
    interface->encryption_enabled = 0;
    return 0;
}

// Usage Example
int main() {
    InterfaceManager manager;
    initialize_interface_manager(&manager);

    int id1 = add_interface(&manager, "eth0");
    if (id1 >= 0) {
        // Enable features for the newly added interface
        NetworkInterface *iface = manager.interfaces[id1];
        iface->enabled = 1;
        enable_feature(iface, 1, 1, 1);
    }

    int id2 = add_interface(&manager, "eth1");
    if (id2 >= 0) {
        NetworkInterface *iface = manager.interfaces[id2];
        iface->enabled = 1;
        enable_feature(iface, 0, 1, 0);
    }

    remove_interface(&manager, id1);

    destroy_interface_manager(&manager);
    return 0;
}
```

### Explanation

- **Thread Safety**: Mutexes are used to ensure thread-safe operations on the interface manager.
- **Scalability and Performance**: The design allows adding up to 10,000 interfaces efficiently using dynamic memory allocation.
- **Feature Management**: Interfaces can dynamically enable or disable advanced features like link aggregation, QoS, and encryption.
- **Modularity**: Functions are clearly separated for initialization, management, and feature control, allowing easy extension or modification.

This code provides a foundational structure to be expanded with additional error handling, logging mechanisms, integration hooks, and more detailed monitoring and reporting as needed.']

