#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define ALIGNMENT 16
#define INITIAL_CAPACITY 10
#define SYSTEM_LIMIT 1024 * 1024 // Example system limit in bytes

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG data;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    sem_t rwsem;
} ResourceModule;

static void log_message(const char *level, const char *message) {
    printf("[%s] %s\n", level, message);
}

ResourceModule* initialize_module(size_t initial_capacity) {
    if (initial_capacity > SYSTEM_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_message("ERROR", "Requested capacity exceeds system limits.");
        return NULL;
    }

    ResourceModule *module = malloc(sizeof(ResourceModule));
    if (!module) {
        log_message("ERROR", "Failed to allocate memory for module structure.");
        return NULL;
    }

    size_t aligned_capacity = ((initial_capacity + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    void *ptr = memalign(ALIGNMENT, aligned_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        log_message("ERROR", "Failed to allocate memory for records.");
        free(module);
        return NULL;
    }

    module->records = ptr;
    module->capacity = initial_capacity;
    module->count = 0;

    pthread_mutex_init(&module->lock, NULL);
    sem_init(&module->rwsem, 0, 1); // Initialize semaphore for RW lock

    log_message("INFO", "Module initialized successfully.");
    return module;
}

void resize_module(ResourceModule *module) {
    size_t new_capacity = module->capacity * 2;
    if (new_capacity > SYSTEM_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_message("WARNING", "Cannot resize beyond system limits. No resizing performed.");
        return;
    }

    void *ptr = memalign(ALIGNMENT, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ptr) {
        log_message("ERROR", "Failed to allocate memory for resized records.");
        return;
    }

    memcpy(ptr, module->records, module->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free(module->records);
    module->records = ptr;
    module->capacity = new_capacity;

    log_message("INFO", "Module resized successfully.");
}

void add_record(ResourceModule *module, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    sem_wait(&module->rwsem);

    pthread_mutex_lock(&module->lock);
    if (module->count == module->capacity) {
        resize_module(module);
    }

    CRC_INDICATION_REL8_TAG *record = &module->records[module->count].data;
    record->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    record->RNTI = RNTI;
    module->records[module->count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    module->count++;

    pthread_mutex_unlock(&module->lock);
    sem_post(&module->rwsem);

    log_message("INFO", "Record added successfully.");
}

void cleanup_module(ResourceModule *module) {
    if (!module) return;

    free(module->records);
    pthread_mutex_destroy(&module->lock);
    sem_destroy(&module->rwsem);
    free(module);

    log_message("INFO", "Module cleaned up successfully.");
}
