pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void manageMemoryAndRemoteConnections() {
    pthread_mutex_lock(&memory_lock);

    size_t total_memory_usage = 0;
    int num_long_pointers = 10; // Example value
    int num_doubles = 20;       // Example value
    int num_structs = 30;       // Example value
    int num_int_keys = 15;      // Example value
    int num_records = 25;       // Example value

    long* long_array = (long*)malloc(num_long_pointers * sizeof(long));
    double* double_array = (double*)malloc(num_doubles * sizeof(double));
    char** struct_strings = (char**)malloc(num_structs * sizeof(char*));
    unsigned int* struct_uints = (unsigned int*)malloc(num_structs * sizeof(unsigned int));
    int* int_keys = (int*)malloc(num_int_keys * sizeof(int));
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    total_memory_usage += num_long_pointers * sizeof(long);
    total_memory_usage += num_doubles * sizeof(double);
    total_memory_usage += num_structs * (sizeof(char*) + sizeof(unsigned int));
    total_memory_usage += num_int_keys * sizeof(int);
    total_memory_usage += num_records * sizeof(Record);

    if (!long_array || !double_array || !struct_strings || !struct_uints || !int_keys || !records) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    for (int i = 0; i < num_structs; ++i) {
        struct_strings[i] = strdup(STRING_CONSTANT);
        struct_uints[i] = rand() % (RAND_MAX - RAND_MIN + 1) + RAND_MIN;

        total_memory_usage += strlen(struct_strings[i]) + 1;
    }

    for (int i = 0; i < num_records; ++i) {
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID_%d_%ld", i, time(NULL));

        records[i].item_ptr = malloc(sizeof(Item));
        if (!records[i].item_ptr) {
            fprintf(stderr, "Memory allocation for record item failed.\n");
            pthread_mutex_unlock(&memory_lock);
            return;
        }

        records[i].value = rand() % 100; // Example value

        total_memory_usage += sizeof(Item);

        struct timeval tv;
        gettimeofday(&tv, NULL);
        if (tv.tv_usec > 500000) {  // Arbitrary condition for demonstration
            records[i].item_ptr->data.num = (double)(rand() / (RAND_MAX + 1.0));
        } else {
            char* str_temp = strdup("Example String");
            records[i].item_ptr->data.str_ptr = str_temp;
            total_memory_usage += strlen(str_temp) + 1;
        }
    }

    // Memory usage check
    if (total_memory_usage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeded. Releasing least recently used records.\n");

        int excess_memory = total_memory_usage - MAX_MEMORY_USAGE;
        while (excess_memory > 0 && num_records > 0) {
            Item* item_to_free = records[--num_records].item_ptr;

            if (item_to_free->data.str_ptr) {
                free(item_to_free->data.str_ptr);
