        if (struct_strings[i]) {
            free(struct_strings[i]);
        }
    }

    free(long_array);
    free(double_array);
    free(struct_strings);
    free(struct_uints);
    free(int_keys);

    for (int i = 0; i < num_records; ++i) {
        if (records[i].item_ptr) {
            if (records[i].item_ptr->data.str_ptr) {
                free(records[i].item_ptr->data.str_ptr);
            }
            free(records[i].item_ptr);
        }
    }

    free(records);

    pthread_mutex_unlock(&memory_lock);
}

void *testThreadFunction(void* arg) {
    manageMemoryAndRemoteConnections();
    return NULL;
}
