```javascript
function traverseDOM(node, selector, testFunc, result = []) {
    if (!node) return result;

    const matchesSelector = node.matches(selector);
    const matchesTestFunc = testFunc(node);

    if (matchesSelector && matchesTestFunc) {
        result.push(node);
    }

    Array.from(node.children).forEach(child => traverseDOM(child, selector, testFunc, result));

    return result;
}
