// Function to align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Error handling macro for allocations
#define HANDLE_ALLOC_ERROR(ptr) \
    if (!ptr) { \
        fprintf(stderr, "Memory allocation error\n"); \
        exit(EXIT_FAILURE); \
    }

// Function to create a new content node
Content* create_content(const char *title) {
    Content *content = (Content*)aligned_alloc(ALIGNMENT, sizeof(Content));
    HANDLE_ALLOC_ERROR(content);

    content->title = strdup(title);
    if (!content->title) {
        free(content);
        return NULL;
    }

    // Use a natural language generator for the description
    char *description_template = "This page is about %s.";
    size_t desc_len = snprintf(NULL, 0, description_template, title) + 1;
    content->description = (char*)aligned_alloc(ALIGNMENT, desc_len);
    HANDLE_ALLOC_ERROR(content->description);

    snprintf(content->description, desc_len, description_template, title);

    content->children = NULL;
    content->fields = NULL;
    content->next = NULL;

    return content;
}

// Function to add a field to a content node
bool add_field(Content *content, const char *name, FieldType type, const char *value) {
    Field *field = (Field*)aligned_alloc(ALIGNMENT, sizeof(Field));
    HANDLE_ALLOC_ERROR(field);

    field->name = strdup(name);
    if (!field->name) {
        free(field);
        return false;
    }

    field->type = type;

    field->value = NULL;
    if (type == TYPE_STRING) {
        field->value = strdup(value);
        if (!field->value) {
            free(field->name);
            free(field);
            return false;
        }
    }

    // Append to the list of fields
    Field *current = content->fields;
    if (!current) {
        content->fields = field;
    } else {
        while (current->next) {
            current = current->next;
        }
        current->next = field;
    }

    return true;
}

// Recursive traversal function to populate descriptions
void traverse_and_populate(Content *content) {
    if (!content) return;

    // Populate description based on title using a natural language generator
    char *description_template = "This page contains information about %s.";
    size_t desc_len = snprintf(NULL, 0, description_template, content->title) + 1;
    char *new_description = (char*)aligned_alloc(ALIGNMENT, desc_len);
    HANDLE_ALLOC_ERROR(new_description);

    snprintf(new_description, desc_len, description_template, content->title);
    free(content->description); // Free old description
    content->description = new_description;

    traverse_and_populate(content->children);

    Field *field = content->fields;
    while (field) {
        if (field->type == TYPE_STRING) {
            size_t val_len = snprintf(NULL, 0, "Field: %s has value: %s", field->name, field->value) + 1;
            char *updated_val = (char*)aligned_alloc(ALIGNMENT, val_len);
            HANDLE_ALLOC_ERROR(updated_val);

            snprintf(updated_val, val_len, "Field: %s has value: %s", field->name, field->value);
            free(field->value); // Free old value
            field->value = updated_val;
        }
        field = field->next;
    }
}

// HTTP API simulation functions for update and delete
bool update_content(Content *content, const char *updated_title) {
    if (!content || !updated_title) return false;

    free(content->title);
    content->title = strdup(updated_title);
    if (!content->title) return false;

    // Validate new data (simplified)
    if (strlen(updated_title) == 0) return false;

    // Update description
    char *description_template = "This page has been updated to be about %s.";
    size_t desc_len = snprintf(NULL, 0, description_template, content->title) + 1;
    char *new_description = (char*)aligned_alloc(ALIGNMENT, desc_len);
    HANDLE_ALLOC_ERROR(new_description);

    snprintf(new_description, desc_len, description_template, content->title);
    free(content->description); // Free old description
    content->description = new_description;

    return true;
}

bool delete_content(Content **content) {
    if (!content || !*content) return false;

    Content *current = *content;
    while (current && current->next) {
        current = current->next;
    }

    // Free fields
    Field *field = (*content)->fields;
    while (field) {
        Field *tmp = field;
        field = field->next;
        free(tmp->name);
        if (tmp->type == TYPE_STRING) free(tmp->value);
        free(tmp);
    }

    // Free content
    free((*content)->title);
    free((*content)->description);
    free(*content);

    *content = NULL;

    return true;
}

// Testing framework setup and execution
void test_framework() {
