void initialize_data_processing_module(size_t num_doubles, size_t num_indices, size_t num_elements, size_t num_operations) {
    double *double_array = NULL;
    unsigned short *short_index = NULL;
    Element **element_array = NULL;
    Operation *operation_array = NULL;

    if (!allocate_memory(&double_array, &short_index, &element_array, num_elements, &operation_array, num_operations)) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize double array with example values
