    if (posix_memalign(&ptr, alignment, size)) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

DataStructureManager* initialize_manager() {
    DataStructureManager* manager = align_malloc(ALIGNMENT, sizeof(DataStructureManager));
    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = (long*)align_malloc(ALIGNMENT, MAX_NODES * sizeof(long));
    manager->keys = (int*)align_malloc(ALIGNMENT, MAX_NODES * sizeof(int));
    manager->records = (Record**)align_malloc(ALIGNMENT, MAX_NODES * sizeof(Record*));
    manager->nodes = (Node**)align_malloc(ALIGNMENT, MAX_NODES * sizeof(Node*));

    for (size_t i = 0; i < MAX_NODES; ++i) {
        manager->records[i] = align_malloc(ALIGNMENT, sizeof(Record));
        manager->nodes[i] = align_malloc(ALIGNMENT, sizeof(Node));
        *(manager->records[i]) = (Record){ rand() % 100 }; // Initialize with random value
    }

    manager->items_head = NULL;
    manager->num_nodes = MAX_NODES;
    manager->num_items = 0;

    return manager;
}

void add_item(DataStructureManager* manager, int key, const char* str, short metadata) {
    pthread_mutex_lock(&manager->lock);

    LinkedListNode* new_node = align_malloc(ALIGNMENT, sizeof(LinkedListNode));
    strncpy(new_node->item.str, str, STRING_LENGTH - 1);
    new_node->item.key = key;
    new_node->item.metadata.metadata = metadata;

    new_node->next = manager->items_head;
    manager->items_head = new_node;
    manager->num_items++;

    pthread_mutex_unlock(&manager->lock);

    // Log item addition
    printf("Added item with key: %d\n", key);
}

void synchronize_with_warehouse(DataStructureManager* manager) {
    // Simulate synchronization logic
    printf("Synchronizing data with external warehouse...\n");
}

void monitor_health(DataStructureManager* manager) {
    // Monitor memory and structure health
    if (manager->num_items > MAX_ITEMS) {
        fprintf(stderr, "Warning: Item count exceeds maximum limit\n");
    }
}

void cleanup_manager(DataStructureManager* manager) {
    pthread_mutex_destroy(&manager->lock);

    for (size_t i = 0; i < manager->num_nodes; ++i) {
        free(manager->records[i]);
        free(manager->nodes[i]);
    }

    LinkedListNode* current = manager->items_head;
    while (current) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->nodes);
    free(manager);
}

void* process_data(void* arg) {
    DataStructureManager* manager = (DataStructureManager*)arg;

    // Simulate processing
    synchronize_with_warehouse(manager);

    return NULL;
}

int main() {
