    DataStructureManager* manager = initialize_manager();

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, process_data, manager);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    monitor_health(manager);

    add_item(manager, 1, "Example Item", 42);

    cleanup_manager(manager);

    return 0;
}
