// Function to generate a pseudo-random alphanumeric string of fixed length
void generate_unique_id(char *buffer, size_t buffer_size, unsigned int seed) {
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    srand(seed);

    for (size_t i = 0; i < buffer_size - 1; i++) {
        int key = rand() % (sizeof(charset) - 1);
        buffer[i] = charset[key];
    }
    buffer[buffer_size - 1] = '\0';
}

// Function to create a new Node with unique identifier and priority
Node* create_node(const char *external_id, unsigned int seed, size_t id_length) {
    if (external_id == NULL || strlen(external_id) != id_length) return NULL;

    // Allocate memory for the node structure
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        return NULL;
    }

    // Allocate and initialize the string identifier using external data source
    newNode->identifier = strdup(external_id);
    if (!newNode->identifier) {
        free(newNode);
        perror("Failed to allocate memory for node identifier");
        return NULL;
    }

    // Set priority based on seed
    rand_r(&seed);  // Using rand_r for better random number generation in multi-threaded environments
    newNode->priority = rand() % 100; // Priority range [0, 99]

    // Initialize the next pointer to NULL
    newNode->next = NULL;

    return newNode;
}

// Function to free a Node and its associated memory
void delete_node(Node *node) {
    if (node) {
        free(node->identifier);
        free(node);
    }
}

// Example usage of the linked list management
