    };

    for (size_t i = 0; i < sizeof(ids) / sizeof(ids[0]); ++i) {
        Node* newNode = create_node(ids[i], seed + i, id_length);
        if (!newNode) break;

        // Insert at the beginning of the list
        newNode->next = head;
        head = newNode;
    }

    // Print and free nodes for demonstration purposes
