        free(processor->nicbs);
        free(processor);
    }
}

int initialize_nicb_array(size_t count, size_t batch_size) {
    if (count == 0 || batch_size == 0) return -1;

    BatchProcessor *processor = init_batch_processor(count, batch_size);
    if (!processor) return -1;

    pthread_t threads[2];
    int thread_result;
    void* thread_return_value;

    // Initialize NICBs in batches using multi-threading.
    for (size_t i = 0; i < count; i += batch_size) {
        size_t current_batch_size = (i + batch_size > count) ? (count - i) : batch_size;
        BatchProcessor batch = {processor->nicbs + i, current_batch_size, batch_size};

        thread_result = pthread_create(&threads[0], NULL, initialize_nicb_batch, &batch);
        if (thread_result != 0) {
            log_message("Failed to create a thread for NICB initialization.");
            break;
        }

        thread_result = pthread_join(threads[0], &thread_return_value);
        if (thread_result != 0) {
            log_message("Thread did not finish execution properly.");
        }

        // Here you could add logic to handle pausing and resuming, based on external input.
    }

    finalize_batch_processor(processor);

    return 0;
}

void* initialize_nicb_batch(void *arg) {
    BatchProcessor *batch = (BatchProcessor *)arg;

    for (size_t i = 0; i < batch->count; ++i) {
        NICB *nicb = &batch->nicbs[i];

        // Generate MAC_HEADER and VLAN Tag
        memset(nicb->header.mac_header, 0x00, sizeof(nicb->header.mac_header));
        generate_vlan_tag(); // Simulating with a random value for this example

        // Validate the MAC Address
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (validate_mac_address(nicb->header.mac_address)) {
                nicb->vlan_tag = generate_vlan_tag();
                break;
            } else {
                log_message("MAC address validation failed, retrying...");
                retries++;
                // Exponential backoff
                usleep((1 << retries) * 1000);
            }
        }

        if (retries == MAX_RETRIES) {
            log_message("Failed to validate MAC address after maximum retries.");
        }

        printf("Batch progress: Initialized %zu/%zu NICBs\n", i + 1, batch->count);
    }

    return NULL;
}

int main() {
    size_t total_nicbs = 10000; // Example large array
    size_t batch_size = 500;     // Example configurable batch size

    if (initialize_nicb_array(total_nicbs, batch_size) != 0) {
        log_message("Failed to initialize NICB array.");
    } else {
        printf("Successfully initialized all NICBs.\n");
    }

    return 0;
}
```

