    size_t block_size;
} BuddyAllocator;

// Initialize buddy allocator
void initialize_allocator(BuddyAllocator* alloc, void* memory, size_t total_size, size_t block_size) {
    alloc->start = memory;
    alloc->size = 0;
    alloc->total_size = total_size;
    alloc->block_size = block_size;
}

// Custom allocation function using buddy system
void* buddy_allocate(BuddyAllocator* alloc, size_t size) {
    if (alloc->size + size > alloc->total_size) return NULL;

    void* ptr = (char*)alloc->start + alloc->size;
    alloc->size += size;
    return ptr;
}

// Custom free function for buddy allocator
void buddy_free(BuddyAllocator* alloc, void* ptr) {
    // No-op in simple implementation; would need to manage free list in full implementation.
}

// Initialize random number generator
void seed_rng() {
    srand((unsigned int)time(NULL));
}

// Create a new record with key and offset
Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->offset = offset;
    record->next = NULL;

    return record;
}

// Insert a record into the linked list
void insert_record(Record** head, int key, long offset) {
    Record* new_record = create_record(key, offset);
    if (!new_record) return;

    new_record->next = *head;
    *head = new_record;
}

// Delete a record from the linked list by key
void delete_record(Record** head, int key) {
    Record **ptr = head, *temp;
    while (*ptr) {
        if ((*ptr)->key == key) {
            temp = *ptr;
            *ptr = (*ptr)->next;
            free(temp);
            return;
        }
        ptr = &(*ptr)->next;
    }
}

// Performance monitoring
void monitor_performance(clock_t start_time, size_t initial_memory_usage) {
    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    printf("Initialization Time: %.2f seconds\n", time_taken);
    printf("Memory Usage: %zu bytes\n", initial_memory_usage);
}

// Main function to manage records
void manage_records() {
    BuddyAllocator allocator;
    void* memory = malloc(MAX_RECORDS * sizeof(Record));
    initialize_allocator(&allocator, memory, MAX_RECORDS * sizeof(Record), sizeof(Record));

    clock_t start_time = clock();
    size_t initial_memory_usage = sizeof(memory);

    seed_rng();

    Record* head = NULL;

    // Example operations
    for (int i = 0; i < 10000; ++i) {
        int key = rand() % MAX_RECORDS;
        long offset = rand() % 1000000L;
        insert_record(&head, key, offset);
    }

    delete_record(&head, 1234);

    monitor_performance(start_time, initial_memory_usage);

    // Cleanup
    while (head) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
    buddy_free(&allocator, memory);
    free(memory);
}

int main() {
    manage_records();
    return 0;
}
