['Below is a C implementation that fulfills the described requirements for managing dynamic memory for interconnected data structures efficiently:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *data;
    int priority;
} node;

typedef struct {
    int value;
} record;

// Function prototypes
void initialize_memory(size_t num_records, size_t id_seed, int min_priority, int max_priority);
record* manage_dynamic_memory(size_t num_records, size_t id_seed, int min_priority, int max_priority);
void free_resources(long *offsets, int *ids, record **records, node **nodes, size_t count);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* manage_dynamic_memory(size_t num_records, size_t id_seed, int min_priority, int max_priority) {
    long *offsets = NULL;
    int *ids = NULL;
    record *records = NULL;
    node *nodes = NULL;

    // Initialize random number generator
    srand((unsigned int)id_seed);

    // Allocate memory for offsets and ids
    offsets = (long *)calloc(num_records, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free_resources(offsets, ids, &records, &nodes, num_records);
        return NULL;
    }

    ids = (int *)calloc(num_records, sizeof(int));
    if (!ids) {
        fprintf(stderr, "Memory allocation failed for ids\n");
        free_resources(offsets, ids, &records, &nodes, num_records);
        return NULL;
    }

    // Allocate memory for records
    records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free_resources(offsets, ids, &records, &nodes, num_records);
        return NULL;
    }

    // Populate offsets and ids with sequential numbers
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = (long)i;
        ids[i] = (int)(i + 1);
    }

    // Allocate memory for nodes and initialize them
    nodes = (node *)malloc(num_records * sizeof(node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes\n");
        free_resources(offsets, ids, &records, &nodes, num_records);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_records; ++i) {
        // Generate a unique alphanumeric identifier
        size_t id_len = snprintf(NULL, 0, "%lu", ids[i]) + 1;
        nodes[i].data = (char *)malloc(id_len);
        if (!nodes[i].data) {
            fprintf(stderr, "Memory allocation failed for node data\n");
            free_resources(offsets, ids, &records, &nodes, num_records);
            return NULL;
        }
        snprintf(nodes[i].data, id_len, "%lu", ids[i]);

        // Set priority based on random number generation
        nodes[i].priority = rand() % (max_priority - min_priority + 1) + min_priority;

        // Initialize record value with a random integer in the given range
        records[i].value = rand() % (max_priority - min_priority + 1) + min_priority;
    }
    pthread_mutex_unlock(&lock);

    printf("Dynamic memory management completed successfully.\n");

    return records;
}

void free_resources(long *offsets, int *ids, record **records, node **nodes, size_t count) {
    if (offsets) free(offsets);
    if (ids) free(ids);
    if (*records) free(*records);
    for (size_t i = 0; i < count && nodes && nodes[i]; ++i) {
        if (nodes[i].data) free(nodes[i].data);
    }
    if (nodes) free(nodes);
}

int main() {
    size_t num_records = 50000;
    size_t id_seed = time(NULL);
    int min_priority = 1, max_priority = 100;

    record *records = manage_dynamic_memory(num_records, id_seed, min_priority, max_priority);

    if (records) {
        // Use the records as needed...
        free(records);
    }

    return 0;
}
```

