This implementation is modular, maintainable, and optimized for handling up to 50,000 records efficiently.']

['Below is a C implementation for managing a doubly-linked list of `Item` structures, considering your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define an Item structure with a dynamically allocated filename and timestamp.
typedef struct Item {
    char *filename;
    int timestamp;
    struct Item *prev;
    struct Item *next;
} Item;

// Define the doubly-linked list structure with mutex for thread safety.
typedef struct {
    Item *head;
    pthread_mutex_t lock; // Mutex to handle concurrent access
} DoublyLinkedList;

// Function prototypes
void initList(DoublyLinkedList *list);
Item* createNewItem(const char *baseName, int timeReference);
void insertItem(DoublyLinkedList *list, Item *item);
void removeItem(DoublyLinkedList *list, Item *item);
void freeItemList(DoublyLinkedList *list);
char* generateUniqueFilename(char *buffer, size_t bufferSize);

// Initialize the list and its mutex
void initList(DoublyLinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Create a new Item with a unique filename and timestamp.
Item* createNewItem(const char *baseName, int timeReference) {
    Item *item = (Item *)malloc(sizeof(Item));
    if (!item) return NULL;

    // Generate a system-unique filename
    const size_t bufferSize = 256;
    char buffer[bufferSize];
    item->filename = generateUniqueFilename(buffer, bufferSize);
    if (!item->filename) {
        free(item);
        return NULL;
    }

    item->timestamp = timeReference;
    item->prev = NULL;
    item->next = NULL;

    return item;
}

// Insert an Item into the doubly-linked list.
void insertItem(DoublyLinkedList *list, Item *item) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) { // If list is empty
        list->head = item;
    } else { // Otherwise, add to the end of the list
        Item *current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = item;
        item->prev = current;
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove an Item from the doubly-linked list.
void removeItem(DoublyLinkedList *list, Item *item) {
    if (!item) return;

    pthread_mutex_lock(&list->lock);

    // Adjust pointers
    if (item->prev) item->prev->next = item->next;
    if (item->next) item->next->prev = item->prev;
    if (list->head == item) list->head = item->next;

    free(item->filename);
    free(item);

    pthread_mutex_unlock(&list->lock);
}

// Free all Items in the doubly-linked list.
void freeItemList(DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Item *current = list->head;
    while (current) {
        Item *next = current->next;
        free(current->filename);
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Generate a unique filename by using system-generated strings.
char* generateUniqueFilename(char *buffer, size_t bufferSize) {
    // Using snprintf and time for simplicity. Consider more robust methods in production.
    char baseName[] = "file_XXXXXX";
    if (snprintf(buffer, bufferSize, "%s%ld", baseName, time(NULL)) >= bufferSize) {
        return NULL;
    }
    return strdup(buffer);
}

// Main function for demonstration purposes
int main() {
    DoublyLinkedList list;
    initList(&list);

    int referenceTime = time(NULL); // Current time as a sample reference

    Item *item1 = createNewItem("file_", referenceTime);
    if (item1) insertItem(&list, item1);

    Item *item2 = createNewItem("file_", referenceTime + 1);
    if (item2) insertItem(&list, item2);

    // Example removal of the first item
    removeItem(&list, list.head);

    freeItemList(&list);

    pthread_mutex_destroy(&list.lock); // Clean up mutex

    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex is used to ensure thread safety during operations on the doubly-linked list.
- **Memory Management**: Proper allocation and deallocation of memory for filenames prevent leaks.
- **File Naming**: Generates unique filenames using a simple method; further enhancements could include system-specific calls like `mkstemp`.
- **Scalability & Performance**: The implementation prioritizes performance through efficient insertion/removal operations in the list and minimizes overhead with concurrent access handling.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct entry {
    int key;
    unsigned int ref_count;
    struct entry *next;
} Entry;

typedef struct node {
    long timestamp;
    struct entry *entry_list;
} Node;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(long timestamp) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;

    node->timestamp = timestamp;
    node->entry_list = NULL;
    pthread_mutex_init(&mutex, NULL);

    return node;
}

Entry* add_entry_to_node(Node *node, int key) {
    pthread_mutex_lock(&mutex);

    Entry *new_entry = (Entry *)malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    new_entry->key = key;
    new_entry->ref_count = 1; // Initial reference count
    new_entry->next = node->entry_list;
    node->entry_list = new_entry;

    pthread_mutex_unlock(&mutex);
    return new_entry;
}

void increment_ref(Entry *entry) {
    if (entry) entry->ref_count++;
}

void decrement_ref(Entry *entry) {
    if (!entry || --entry->ref_count == 0) {
        pthread_mutex_lock(&mutex);

        // Remove the entry from the node's list
        Entry **curr = &(node->entry_list), *temp;
        while (*curr && *curr != entry) {
            curr = &((*curr)->next);
        }

        if (*curr == entry) {
            temp = *curr;
            *curr = temp->next;
            free(temp);
        }

        pthread_mutex_unlock(&mutex);
    }
}

void cleanup_node(Node *node) {
    if (!node) return;

    Entry **curr = &(node->entry_list), *temp;

    while (*curr) {
        temp = *curr;
        *curr = temp->next;
        free(temp);
    }

    pthread_mutex_destroy(&mutex);
    free(node);
}

int main() {
    Node *node = create_node(1234567890L);
    if (!node) {
        printf("Failed to allocate node\n");
        return 1;
    }

    Entry *entry = add_entry_to_node(node, 42);
    if (!entry) {
        printf("Failed to add entry\n");
        cleanup_node(node);
        return 1;
    }

    increment_ref(entry);
    decrement_ref(entry); // Should be deallocated
    decrement_ref(entry); // No effect since ref_count is already zero

    Entry *another_entry = add_entry_to_node(node, 84);
    if (!another_entry) {
        printf("Failed to add another entry\n");
        cleanup_node(node);
        return 1;
    }

    decrement_ref(another_entry);

    cleanup_node(node); // Cleans up all remaining entries
    return 0;
}
```']

