#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

// Initialize the collection
RecordCollection* init_record_collection(size_t initial_capacity) {
    RecordCollection* rc = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!rc) return NULL;

    rc->offsets = (long*)calloc(initial_capacity, sizeof(long));
    rc->keys = (int*)calloc(initial_capacity, sizeof(int));
    rc->records = (record**)calloc(initial_capacity, sizeof(record*));
    rc->capacity = initial_capacity;
    rc->count = 0;

    if (!rc->offsets || !rc->keys || !rc->records) {
        free(rc->offsets);
        free(rc->keys);
        free(rc->records);
        free(rc);
        return NULL;
    }

    pthread_mutex_init(&rc->lock, NULL);
    return rc;
}

// Resize the collection
int resize_record_collection(RecordCollection* rc, size_t new_capacity) {
    long* new_offsets = (long*)realloc(rc->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(rc->keys, new_capacity * sizeof(int));
    record** new_records = (record**)realloc(rc->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_records) {
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return -1;
    }

    rc->offsets = new_offsets;
    rc->keys = new_keys;
    rc->records = new_records;
    rc->capacity = new_capacity;

    // Initialize new elements
    for (size_t i = rc->count; i < new_capacity; ++i) {
        rc->offsets[i] = 0;
        rc->keys[i] = 0;
        rc->records[i] = NULL;
    }

    return 0;
}

// Generate random value based on distribution type
int generate_random_value(int distribution_type) {
    int value;
    if (distribution_type == 1) { // Uniform distribution
        value = rand() % 100; // Example range
    } else { // Gaussian distribution
        double mean = 50.0, stddev = 15.0;
        static const double scale = 1.0 / sqrt(12.0);
        value = (int)(mean + stddev * scale * ((double)rand() / RAND_MAX));
    }
    return value;
}

// Add a record in a thread-safe manner
void add_record(RecordCollection* rc, int distribution_type) {
    pthread_mutex_lock(&rc->lock);

    if (rc->count == rc->capacity) {
        if (resize_record_collection(rc, rc->capacity * 2) != 0) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&rc->lock);
            return;
        }
    }

    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        printf("Memory allocation failed for record\n");
        pthread_mutex_unlock(&rc->lock);
        return;
    }

    new_record->value = generate_random_value(distribution_type);

    rc->records[rc->count] = new_record;
    rc->offsets[rc->count] = (long)rc->count; // Example offset calculation
    rc->keys[rc->count] = rand() % 1000; // Random key

    printf("Record added: value=%d, offset=%ld, key=%d\n", new_record->value, rc->offsets[rc->count], rc->keys[rc->count]);

    rc->count++;

    pthread_mutex_unlock(&rc->lock);
}

// Perform integrity check
void integrity_check(RecordCollection* rc) {
    for (size_t i = 0; i < rc->count; ++i) {
        if (rc->offsets[i] != (long)i || rc->keys[i] == 0 || rc->records[i] == NULL) {
            printf("Integrity check failed at index %zu\n", i);
        }
    }
}

// Free resources
void free_record_collection(RecordCollection* rc) {
    pthread_mutex_lock(&rc->lock);

    for (size_t i = 0; i < rc->count; ++i) {
        free(rc->records[i]);
    }

    free(rc->offsets);
    free(rc->keys);
    free(rc->records);

    pthread_mutex_unlock(&rc->lock);
    pthread_mutex_destroy(&rc->lock);
    free(rc);
}

int main() {
    srand(time(NULL));

    RecordCollection* rc = init_record_collection(10);
    if (!rc) return 1;

    // Simulate concurrent additions
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, (void*)add_record, (void*)(long)(i % 2)); // Alternate distribution types
    }
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    integrity_check(rc);

    free_record_collection(rc);
    return 0;
}
```']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_ALIGNMENT 16
#define MAX_RECORDS 10000

typedef struct {
    int value;
} record_t;

typedef struct MemoryPoolNode {
    void *ptr;
    size_t size;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *freeList;
    pthread_mutex_t lock;
    size_t totalAllocated;
    size_t successfulAllocations;
    size_t failedAllocations;
} MemoryPool;

MemoryPool memoryPool = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0, 0};

void log_message(const char* level, const char* message) {
    time_t now = time(NULL);
    printf("[%s] [%ld]: %s\n", level, now, message);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

void init_memory_pool() {
    // Preallocate a large block of memory for the pool
    void *block = aligned_alloc(MEMORY_ALIGNMENT, 1024 * 1024); // 1 MB pool

    if (!block) {
        log_message("ERROR", "Failed to initialize memory pool.");
        return;
    }

    size_t blockSize = 128; // Size of each block within the pool
    for (size_t i = 0; i < 1024 * 1024 / blockSize; i++) {
        MemoryPoolNode *node = aligned_alloc(MEMORY_ALIGNMENT, sizeof(MemoryPoolNode));
        if (!node) {
            log_message("ERROR", "Failed to allocate memory pool node.");
            continue;
        }
        node->ptr = (char*)block + i * blockSize;
        node->size = blockSize;
        node->next = memoryPool.freeList;
        memoryPool.freeList = node;
    }

    memoryPool.totalAllocated = 1024 * 1024;
}

void* pool_alloc(size_t size) {
    pthread_mutex_lock(&memoryPool.lock);
    for (MemoryPoolNode **current = &memoryPool.freeList; *current != NULL;) {
        MemoryPoolNode *node = *current;
        if (node->size >= size) {
            *current = node->next;
            memoryPool.successfulAllocations++;
            pthread_mutex_unlock(&memoryPool.lock);
            return node->ptr;
        }
        current = &node->next;
    }

    // Attempt to allocate from the system if pool is exhausted
    void *newBlock = aligned_alloc(MEMORY_ALIGNMENT, size);
    if (!newBlock) {
        memoryPool.failedAllocations++;
        pthread_mutex_unlock(&memoryPool.lock);
        log_message("WARNING", "Failed allocation, no free blocks available.");
        return NULL;
    }

    MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
    node->ptr = newBlock;
    node->size = size;
    node->next = memoryPool.freeList;
    memoryPool.freeList = node;

    memoryPool.totalAllocated += size;
    pthread_mutex_unlock(&memoryPool.lock);
    return newBlock;
}

void pool_free(void *ptr) {
    MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
    node->ptr = ptr;
    node->size = 128; // Assume block size for simplicity
    node->next = memoryPool.freeList;

    pthread_mutex_lock(&memoryPool.lock);
    memoryPool.freeList = node;
    pthread_mutex_unlock(&memoryPool.lock);
}

record_t* allocate_records(size_t count, int min_val, int max_val, unsigned int seed) {
    srand(seed);

    record_t *records = pool_alloc(count * sizeof(record_t));
    if (!records) {
        log_message("ERROR", "Failed to allocate records.");
        return NULL;
    }

    for (size_t i = 0; i < count; i++) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
        if (records[i].value < min_val || records[i].value > max_val) {
            log_message("ERROR", "Record value out of range.");
            pool_free(records);
            return NULL;
        }
    }

    return records;
}

void cleanup_memory_pool() {
    pthread_mutex_lock(&memoryPool.lock);

    MemoryPoolNode *current = memoryPool.freeList;
    while (current) {
        MemoryPoolNode *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&memoryPool.lock);
}

int main(int argc, char **argv) {
    init_memory_pool();

    size_t num_records = 5000; // Example number of records
    record_t *records = allocate_records(num_records, 10, 100, 42);

    if (records) {
        log_message("INFO", "Records allocated successfully.");
    }

    cleanup_memory_pool();
    return 0;
}
```

This code demonstrates a memory pool strategy for managing `record` structures in C. It includes features like aligned allocation, logging, and error handling while supporting concurrent access through mutex locks. This implementation optimizes performance by minimizing frequent allocations and reusing free blocks within the memory pool.']

