// Struct to hold a record
typedef struct {
    int key;
    int value;
} Record;

// Struct for the dynamic collection of records
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} RecordCollection;

// Logging levels
typedef enum {
    LOG_NONE,
    LOG_INFO,
    LOG_DEBUG
} LogLevel;

// Global logging level
LogLevel current_log_level = LOG_NONE;

// Function prototypes
void log_message(LogLevel level, const char *message);
RecordCollection* create_collection(size_t initial_capacity);
int add_record(RecordCollection *collection, int key, int value);
int resize_collection_if_needed(RecordCollection *collection);
int validate_records(const RecordCollection *collection);
void load_initial_parameters_from_config(RecordCollection *collection);

// Function to initialize a collection
RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(initial_capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    load_initial_parameters_from_config(collection);

    log_message(LOG_INFO, "Collection created with capacity: %zu", initial_capacity);
    return collection;
}

// Function to add a record
int add_record(RecordCollection *collection, int key, int value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity && !resize_collection_if_needed(collection)) {
        log_message(LOG_INFO, "Failed to resize the collection");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            // Overwrite existing record
            collection->records[i].value = value;
            pthread_mutex_unlock(&collection->lock);
            return 1;
        }
    }

    collection->records[collection->count++] = (Record){.key = key, .value = value};
    log_message(LOG_DEBUG, "Added record: key=%d, value=%d", key, value);

    if (!validate_records(collection)) {
        log_message(LOG_INFO, "Validation failed after adding a record");
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Function to resize the collection
int resize_collection_if_needed(RecordCollection *collection) {
    size_t new_capacity = collection->capacity * 2;

    Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) {
        log_message(LOG_INFO, "Failed to allocate memory during resizing");
        return -1;
    }

    collection->records = new_records;
    collection->capacity = new_capacity;
    log_message(LOG_DEBUG, "Resized collection to capacity: %zu", new_capacity);
    return 0;
}

// Function to validate records
int validate_records(const RecordCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == 0) { // Example validation logic
            log_message(LOG_INFO, "Validation error at index %zu", i);
            return 0;
        }
    }

    log_message(LOG_DEBUG, "Records validated successfully");
    return 1;
}

// Function to load initial parameters from a config service
void load_initial_parameters_from_config(RecordCollection *collection) {
    // Simulate loading configuration: Set max capacity threshold for resizing
    size_t initial_capacity = 10;  // Example value

    collection->capacity = initial_capacity;
    log_message(LOG_INFO, "Loaded initial capacity from config: %zu", initial_capacity);
}

// Logging function
void log_message(LogLevel level, const char *message, ...) {
    if (level > current_log_level) return;

    va_list args;
    va_start(args, message);

    printf("Log [%d]: ", level);
    vprintf(message, args);
    printf("\n");

    va_end(args);
}

// Unit tests
void test_add_record() {
    RecordCollection *collection = create_collection(2);
    if (!collection) return;

    add_record(collection, 1, 100);
    add_record(collection, 2, 200);

    // Test resizing behavior
    for (int i = 3; i <= 5; ++i) {
        add_record(collection, i, i * 100);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void run_unit_tests() {
    test_add_record();
    printf("All tests passed.\n");
}

int main() {
    current_log_level = LOG_DEBUG;
    run_unit_tests();

    return 0;
}
