#define MAX_LOG_MESSAGE_LENGTH 256
#define DEFAULT_SEVERITY_LEVEL 1

typedef struct log_entry {
    time_t timestamp;
    int severity_level;
    char *message;
} log_entry;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_random_string(char* str, size_t length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (length) {
        for (size_t n = 0; n < length - 1; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length - 1] = '\0';
    } else {
        *str = '\0';
    }
    return 0;
}

int init_log_entries(log_entry **entries, size_t num_entries) {
    if (entries == NULL || num_entries == 0) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&mutex);

    *entries = malloc(num_entries * sizeof(log_entry));
    if (*entries == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // Memory allocation failure
    }

    for (size_t i = 0; i < num_entries; ++i) {
        (*entries)[i].timestamp = time(NULL);
        (*entries)[i].severity_level = DEFAULT_SEVERITY_LEVEL;
        (*entries)[i].message = malloc(MAX_LOG_MESSAGE_LENGTH * sizeof(char));
        if ((*entries)[i].message == NULL) {
            // Cleanup in case of failure
            for (size_t j = 0; j < i; ++j) {
                free((*entries)[j].message);
            }
            free(*entries);
            pthread_mutex_unlock(&mutex);
            return -3; // Memory allocation failure for message buffer
        }

        generate_random_string((*entries)[i].message, MAX_LOG_MESSAGE_LENGTH);
    }

    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

void cleanup_log_entries(log_entry *entries, size_t num_entries) {
    if (entries == NULL || num_entries == 0) {
        return;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        free(entries[i].message);
    }

    free(entries);
}
