#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_HEADER_LEN 1024
#define INITIAL_CAPACITY 10

typedef struct {
    int packet_id;
    char *payload;
    size_t payload_len;
    size_t header_len;
    time_t last_modified;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t total_memory_usage;
    size_t peak_memory_usage;
    size_t memory_allocation_count;
} PacketArray;

void update_timestamp(DataPacket *packet) {
    packet->last_modified = time(NULL);
}

int validate_header_len(size_t header_len) {
    return header_len <= MAX_HEADER_LEN;
}

PacketArray* init_packet_array() {
    PacketArray *array = malloc(sizeof(PacketArray));
    array->packets = malloc(INITIAL_CAPACITY * sizeof(DataPacket *));
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->total_memory_usage = 0;
    array->peak_memory_usage = 0;
    array->memory_allocation_count = 0;
    return array;
}

void free_packet(DataPacket *packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

void resize_array(PacketArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    DataPacket **new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket *));
    if (new_packets) {
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->lock);
}

void add_packet(PacketArray *array, int packet_id, const char *payload, size_t payload_len, size_t header_len) {
    if (!validate_header_len(header_len)) return;

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        resize_array(array, array->capacity * 2);
    }

    DataPacket *packet = malloc(sizeof(DataPacket));
    packet->packet_id = packet_id;
    packet->payload = malloc(payload_len);
    memcpy(packet->payload, payload, payload_len);
    packet->payload_len = payload_len;
    packet->header_len = header_len;
    update_timestamp(packet);

    array->packets[array->count++] = packet;

    size_t current_memory_usage = 0;
    for (size_t i = 0; i < array->count; ++i) {
        current_memory_usage += sizeof(DataPacket) + array->packets[i]->payload_len;
    }
    if (current_memory_usage > array->peak_memory_usage) {
        array->peak_memory_usage = current_memory_usage;
    }

    pthread_mutex_unlock(&array->lock);
}

void remove_packet(PacketArray *array, int packet_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->packet_id == packet_id) {
            free_packet(array->packets[i]);
            memmove(&array->packets[i], &array->packets[i + 1], (array->count - i - 1) * sizeof(DataPacket *));
            array->count--;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void filter_packets(PacketArray *array, int (*filter_func)(int packet_id)) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (!filter_func(array->packets[i]->packet_id)) {
            free_packet(array->packets[i]);
            memmove(&array->packets[i], &array->packets[i + 1], (array->count - i - 1) * sizeof(DataPacket *));
            array->count--;
            --i;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void serialize_packet_array(PacketArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->packets[i]->packet_id, sizeof(int), 1, file);
        fwrite(&array->packets[i]->payload_len, sizeof(size_t), 1, file);
        fwrite(&array->packets[i]->header_len, sizeof(size_t), 1, file);
        fwrite(array->packets[i]->payload, sizeof(char), array->packets[i]->payload_len, file);
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
}

void deserialize_packet_array(PacketArray *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    resize_array(array, count);
    array->count = count;

    for (size_t i = 0; i < count; ++i) {
        DataPacket *packet = malloc(sizeof(DataPacket));
        fread(&packet->packet_id, sizeof(int), 1, file);
        fread(&packet->payload_len, sizeof(size_t), 1, file);
        fread(&packet->header_len, sizeof(size_t), 1, file);

        packet->payload = malloc(packet->payload_len);
        fread(packet->payload, sizeof(char), packet->payload_len, file);

        update_timestamp(packet);
        array->packets[i] = packet;
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
}

void cleanup_packet_array(PacketArray *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free_packet(array->packets[i]);
    }
    free(array->packets);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void report_memory_usage(PacketArray *array) {
    pthread_mutex_lock(&array->lock);

    printf("Total Memory Usage: %zu bytes\n", array->total_memory_usage);
    printf("Peak Memory Usage: %zu bytes\n", array->peak_memory_usage);
    printf("Active Packets: %zu\n", array->count);

    pthread_mutex_unlock(&array->lock);
}
