#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    double amplitude;
    float frequency;
} Signal;

typedef struct MemoryPool {
    void* blocks[100];
    size_t block_size;
    int used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

static MemoryPool pool = { .block_size = 0, .used_blocks = 0 };

// Logging function prototype
void log_message(const char *message);

// Helper functions for memory alignment and logging
static void* aligned_malloc(size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, 32);
#else
    if (posix_memalign(&ptr, 32, size)) {
        return NULL; // Failed to allocate memory
    }
#endif
    return ptr;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Thread-safe allocation function
Signal* create_signals(size_t count, unsigned int seed) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Signal* signals = NULL;

    pthread_mutex_lock(&mutex);

    if (pool.block_size < sizeof(Signal) * count + 2 * count * sizeof(float)) {
        // Allocate new block if the current pool is insufficient
        size_t required_size = sizeof(Signal) * count + 2 * count * sizeof(float);
        void* block = aligned_malloc(required_size);

        if (block == NULL) {
            log_message("Memory allocation failed. Trying a smaller block size.");
            // Attempt to allocate a smaller block size or handle fallback
            // For simplicity, we won't demonstrate this fully here.
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        pool.blocks[pool.used_blocks++] = block;
        pool.block_size = required_size;
    } else {
        for (int i = 0; i < pool.used_blocks; ++i) {
            if (strncmp(pool.blocks[i], "USED", 4) != 0) { // Check if the block is not used
                signals = (Signal*)pool.blocks[i];
                strncpy((char*)signals, "USED", 4); // Mark as used
                break;
            }
        }

        if (!signals) {
            log_message("No free memory blocks available.");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        signals[i].amplitude = ((double)rand() / RAND_MAX) * 10.0; // Example amplitude range
        signals[i].frequency = ((float)rand() / RAND_MAX) * 5.0 + 1.0; // Example frequency range

        if (signals[i].amplitude < 0 || signals[i].frequency <= 0) {
            log_message("Signal integrity check failed.");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    pthread_mutex_unlock(&mutex);

    log_message("Signals created successfully.");
    return signals;
}

// Cleanup function for memory pool
void cleanup_memory_pool() {
    for (int i = 0; i < pool.used_blocks; ++i) {
#if defined(_WIN32)
        _aligned_free(pool.blocks[i]);
#else
        free(pool.blocks[i]);
#endif
    }
    pthread_mutex_destroy(&mutex);
}

// Example main function demonstrating usage
int main(int argc, char **argv) {
    size_t num_signals = 100;
    unsigned int seed = 42;

    Signal* signals = create_signals(num_signals, seed);

    if (signals != NULL) {
        // Use signals here...

        cleanup_memory_pool();
    }

    return 0;
}
