// Function for logging errors
void log_invalid_value(const char* value_type, float value) {
    if (strcmp(value_type, "SNR") == 0) {
        invalid_snr_count++;
    } else if (strcmp(value_type, "NF") == 0) {
        invalid_nf_count++;
    }
}

// Memory pool allocation function
int allocate_memory_pool(NFAMemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->size = 0;
    pool->frames = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T) * capacity);
    return pool->frames != NULL ? 1 : 0;
}

// Free the memory pool
void free_memory_pool(NFAMemoryPool* pool) {
    if (pool && pool->frames) {
        free(pool->frames);
    }
}

// Initialize NFAPI_RX_FRAME_T list with valid values
int initializeNfarList(NFAMemoryPool* pool, size_t M, int* ueIdentifiers) {
    if (!allocate_memory_pool(pool, M)) {
        printf("Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < M; ++i) {
        // Randomly generated SNR and NF values for demonstration purposes
        float snr = ((float)(rand() % 101)) * -1.0f;  // Range: [-100, 0]
        float nf = (float)(rand() % 71);               // Range: [0, 70]

