            continue;
        }
        if (nf < MIN_NF || nf > MAX_NF) {
            log_invalid_value("NF", nf);
            continue;
        }

        // Assuming ueIdentifiers is a valid input array with at least M elements
        NFAPI_RX_FRAME_T frame = {ueIdentifiers[i], snr, nf};
        if (pool->size < pool->capacity) {
            pool->frames[pool->size++] = frame;
        }
    }

