import <string.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <netinet/in.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <dns_sd.h>

// Define the MAC_HEADER structure
typedef struct {
    u_char source[6];
    u_char destination[6];
    u_short vlan_tag;
} MAC_HEADER;

// Define VLAN tag with priority
typedef union {
    struct {
        u_int16_t priority:3;
        u_int16_t cfi:1;
        u_int16_t vlan_id:12;
    };
    u_int16_t as_u16;
} VLAN_TAG;

// Define the NICB structure
typedef struct {
    MAC_HEADER mac_header;
    char ip_address[INET_ADDRSTRLEN];
} NICB;

#define MAX_NICBS 1000

void handle_dns_error(const char *hostname) {
    fprintf(stderr, "DNS resolution failed for hostname: %s\n", hostname);
}

u_char* resolve_hostname_to_ip(const char *hostname) {
    struct addrinfo hints, *res;
    u_char *ip_address = malloc(INET_ADDRSTRLEN);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        handle_dns_error(hostname);
        free(ip_address);
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);

    freeaddrinfo(res);
    return ip_address;
}

void generate_random_mac(u_char mac[6]) {
    // Generate a random MAC address
    srand((unsigned int)time(NULL));
    for (int i = 0; i < 5; ++i) {
        mac[i] = rand() % 256;
    }
    mac[5] = (rand() % 2) * 2; // Ensure the last bit is zero
}

void initialize_nicb_array(NICB *nicbs, int count, const char *hostname, u_int16_t vlan_id, u_char vlan_priority) {
    if (!nicbs || count <= 0 || !hostname) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    pthread_t dns_thread;
    u_char *ip_address = NULL;

    // DNS resolution in a separate thread
    void* async_dns_resolution(void* arg) {
        char *host = (char*)arg;
        ip_address = resolve_hostname_to_ip(host);
        if (!ip_address) {
            handle_dns_error(host);
        }
        return NULL;
    }

    pthread_create(&dns_thread, NULL, async_dns_resolution, (void *)hostname);
    pthread_detach(dns_thread);

    for (int i = 0; i < count && i < MAX_NICBS; ++i) {
        generate_random_mac(nicbs[i].mac_header.source);
        generate_random_mac(nicbs[i].mac_header.destination);

        VLAN_TAG vlan_tag;
        vlan_tag.priority = vlan_priority;
        vlan_tag.vlan_id = vlan_id;
        nicbs[i].mac_header.vlan_tag = htons(vlan_tag.as_u16);

        if (ip_address) {
            strncpy(nicbs[i].ip_address, ip_address, INET_ADDRSTRLEN);
            free(ip_address);  // Free after using
        }
    }
}

int main() {
    NICB nicb_array[MAX_NICBS];
    initialize_nicb_array(nicb_array, MAX_NICBS, "example.com", 100, 5);

    for (int i = 0; i < MAX_NICBS && strlen(nicb_array[i].ip_address) > 0; ++i) {
        printf("NICB %d: MAC Source: %02x:%02x:%02x:%02x:%02x:%02x, "
               "MAC Destination: %02x:%02x:%02x:%02x:%02x:%02x, "
               "IP Address: %s\n",
               i,
               nicb_array[i].mac_header.source[0], nicb_array[i].mac_header.source[1],
               nicb_array[i].mac_header.source[2], nicb_array[i].mac_header.source[3],
               nicb_array[i].mac_header.source[4], nicb_array[i].mac_header.source[5],
               nicb_array[i].mac_header.destination[0], nicb_array[i].mac_header.destination[1],
               nicb_array[i].mac_header.destination[2], nicb_array[i].mac_header.destination[3],
               nicb_array[i].mac_header.destination[4], nicb_array[i].mac_header.destination[5],
               nicb_array[i].ip_address);
    }

    return 0;
}
