['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    short value;
    char identifier;
    float *float_ptr;
} record;

typedef struct {
    long *offsets;
    int capacity_offsets;
    size_t size_offsets;

    int *keys;
    int capacity_keys;
    size_t size_keys;

    record **records;
    int capacity_records;
    size_t size_records;

    pthread_mutex_t lock;
} DataManager;

DataManager* create_data_manager(int initial_capacity) {
    DataManager *manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->offsets = (long *)malloc(initial_capacity * sizeof(long));
    manager->capacity_offsets = initial_capacity;
    manager->size_offsets = 0;

    manager->keys = (int *)malloc(initial_capacity * sizeof(int));
    manager->capacity_keys = initial_capacity;
    manager->size_keys = 0;

    manager->records = (record **)malloc(initial_capacity * sizeof(record *));
    manager->capacity_records = initial_capacity;
    manager->size_records = 0;

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int resize_data_manager(DataManager *manager) {
    pthread_mutex_lock(&manager->lock);

    int new_capacity = 2 * manager->capacity_records;
    if (new_capacity > 10000) new_capacity = 10000;

    long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));
    record **new_records = realloc(manager->records, new_capacity * sizeof(record *));

    if (!new_offsets || !new_keys || !new_records) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->capacity_offsets = new_capacity;
    manager->capacity_keys = new_capacity;
    manager->capacity_records = new_capacity;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int add_record(DataManager *manager, long offset, int key, short value, char identifier) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size_records == manager->capacity_records) {
        if (resize_data_manager(manager) != 0) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Resize failed
        }
    }

    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    new_record->value = value;
    new_record->identifier = identifier;
    new_record->float_ptr = malloc(sizeof(float));
    if (!new_record->float_ptr) {
        free(new_record);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    manager->offsets[manager->size_offsets++] = offset;
    manager->keys[manager->size_keys++] = key;
    manager->records[manager->size_records++] = new_record;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void free_data_manager(DataManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size_records; ++i) {
        if (manager->records[i]) {
            if (manager->records[i]->float_ptr) {
                free(manager->records[i]->float_ptr);
            }
            free(manager->records[i]);
        }
    }

    pthread_mutex_lock(&manager->lock);

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example serialization function
int serialize_data_manager(DataManager *manager, FILE *file) {
    if (!manager || !file) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t total_records = manager->size_records;
    fwrite(&total_records, sizeof(size_t), 1, file);

    for (size_t i = 0; i < total_records; ++i) {
        record *rec = manager->records[i];
        long offset = manager->offsets[i];
        int key = manager->keys[i];

        fwrite(&offset, sizeof(long), 1, file);
        fwrite(&key, sizeof(int), 1, file);
        fwrite(rec, sizeof(record), 1, file);
    }

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

// Example deserialization function
DataManager* deserialize_data_manager(FILE *file) {
    if (!file) return NULL;

    size_t total_records;
    fread(&total_records, sizeof(size_t), 1, file);

    DataManager *manager = create_data_manager(total_records);
    if (!manager) return NULL;

    for (size_t i = 0; i < total_records; ++i) {
        long offset;
        int key;
        record rec;

        fread(&offset, sizeof(long), 1, file);
        fread(&key, sizeof(int), 1, file);
        fread(&rec, sizeof(record), 1, file);

        add_record(manager, offset, key, rec.value, rec.identifier);

        // Assuming the float_ptr needs to be managed post-deserialization
        if (rec.float_ptr) {
            manager->records[i]->float_ptr = malloc(sizeof(float));
            *(manager->records[i]->float_ptr) = *rec.float_ptr;
            free(rec.float_ptr);
        }
    }

    return manager;
}
```']

