        size_t currentUsage = getMemoryUsage();
        while (currentUsage > MEMORY_LIMIT) {
            freeLeastRecentlyUsedRecord();
            currentUsage = getMemoryUsage();
        }
        pthread_mutex_unlock(&memoryMutex);
