['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_RECORDS 10
#define MAX_STRING_LENGTH 256
#define MEMORY_THRESHOLD (1024 * 1024 * 50) // Example threshold: 50 MB

typedef struct {
    int value;
    char* str;
} Record;

typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
    uint16_t vlan_tag;
    int vlan_priority; // Optional configuration
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    Record records[MAX_RECORDS];
    size_t record_count;
} NICB;

typedef struct {
    void* ptr;
    size_t size;
} MemoryBlock;

typedef struct {
    MemoryBlock* blocks;
    size_t total_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool(size_t initial_size) {
    pthread_mutex_lock(&pool.lock);
    if (pool.blocks == NULL || initial_size > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded or already initialized.\n");
        exit(EXIT_FAILURE);
    }

    pool.blocks = malloc(initial_size / sizeof(MemoryBlock));
    for (size_t i = 0; i < initial_size / sizeof(MemoryBlock); ++i) {
        pool.blocks[i].ptr = NULL;
        pool.blocks[i].size = 0;
    }
    pool.total_size = initial_size;
    pthread_mutex_unlock(&pool.lock);
}

void* allocate(size_t size) {
    pthread_mutex_lock(&pool.lock);

    for (size_t i = 0; i < pool.total_size / sizeof(MemoryBlock); ++i) {
        if (pool.blocks[i].ptr == NULL) {
            void* memory = malloc(size);
            pool.blocks[i].ptr = memory;
            pool.blocks[i].size = size;

            pthread_mutex_unlock(&pool.lock);
            return memory;
        }
    }

    fprintf(stderr, "Memory allocation failed: threshold exceeded.\n");
    pthread_mutex_unlock(&pool.lock);
    exit(EXIT_FAILURE);
}

void free_memory(void* ptr) {
    pthread_mutex_lock(&pool.lock);

    for (size_t i = 0; i < pool.total_size / sizeof(MemoryBlock); ++i) {
        if (pool.blocks[i].ptr == ptr) {
            free(ptr);
            pool.blocks[i].ptr = NULL;
            pool.blocks[i].size = 0;
            break;
        }
    }

    pthread_mutex_unlock(&pool.lock);
}

void initialize_nicb_array(NICB* array, size_t count, int value_range_min, int value_range_max) {
    if (array == NULL || count == 0) return;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        // Initialize MAC addresses and VLAN tag
        for (int j = 0; j < 6; ++j) {
            array[i].mac_header.dest_mac[j] = rand() % 256;
            array[i].mac_header.src_mac[j] = rand() % 256;
        }

        array[i].mac_header.vlan_tag = ((rand() % 4094) + 1) | (0x1000 >> rand() % 3); // Example: include priority bits
        array[i].mac_header.vlan_priority = rand() % 8; // Optional configuration

        // Initialize records
        for (int j = 0; j < MAX_RECORDS; ++j) {
            if (rand() % 2) { // Randomly decide to add a record
                array[i].records[j].value = value_range_min + rand() % (value_range_max - value_range_min + 1);
                size_t str_len = rand() % (MAX_STRING_LENGTH + 1);
                char* str = (char*)allocate(str_len * sizeof(char));
                snprintf(str, str_len, "Record_%zu_%d", i, j); // Example string
                array[i].records[j].str = str;
            }
        }

        array[i].record_count = MAX_RECORDS; // This should be adjusted based on actual records added
    }
}

void free_nicb_array(NICB* array, size_t count) {
    if (array == NULL || count == 0) return;

    for (size_t i = 0; i < count; ++i) {
        for (int j = 0; j < MAX_RECORDS; ++j) {
            if (array[i].records[j].str != NULL) {
                free_memory(array[i].records[j].str);
                array[i].records[j].str = NULL;
            }
        }
    }

    // Optional: Free memory pool blocks
    pthread_mutex_lock(&pool.lock);
    for (size_t i = 0; i < pool.total_size / sizeof(MemoryBlock); ++i) {
        if (pool.blocks[i].ptr != NULL) {
            free(pool.blocks[i].ptr);
            pool.blocks[i].ptr = NULL;
        }
    }
    pthread_mutex_unlock(&pool.lock);

    if (pool.blocks != NULL) {
        free(pool.blocks);
        pool.blocks = NULL;
    }

    pool.total_size = 0;
}

int main() {
    size_t nicb_count = 100; // Example count
    NICB* array = (NICB*)malloc(nicb_count * sizeof(NICB));

    initialize_memory_pool(1024); // Example initial size: 1 KB blocks

    initialize_nicb_array(array, nicb_count, 0, 100);

    free_nicb_array(array, nicb_count);
    free(array);

    return 0;
}
