#include <fstream>

// Custom Logger Interface
class ILogger {
public:
    virtual void Log(const std::string& message) = 0;
};

class ConsoleLogger : public ILogger {
public:
    void Log(const std::string& message) override {
        std::cout << message << std::endl;
    }
};

class FileLogger : public ILogger {
private:
    std::ofstream fileStream;

public:
    FileLogger(const std::string& filename) {
        fileStream.open(filename, std::ios::out | std::ios::app);
    }

    ~FileLogger() {
        if (fileStream.is_open()) {
            fileStream.close();
        }
    }

    void Log(const std::string& message) override {
        if (fileStream.is_open()) {
            fileStream << message << std::endl;
        }
    }
};

// Station Record Structure
struct StationRecord {
    double temperature;
    std::string stationID;

    StationRecord(double temp, const std::string& id)
        : temperature(temp), stationID(id) {}
};

// Monitoring Manager Class
class MonitoringManager {
private:
    std::vector<StationRecord> records;
    std::mutex mtx;
    ILogger* logger;

public:
    MonitoringManager(ILogger* log) : logger(log) {}

    void AddTemperatureReading(double temp, const std::string& stationID) {
        if (temp < -50.0 || temp > 60.0) { // Valid temperature range
            return; // Invalid reading ignored
        }

        std::lock_guard<std::mutex> lock(mtx);
        records.emplace_back(temp, stationID);

        ProcessRecords();
    }

    void ProcessRecords() {
        if (records.empty()) {
            return;
        }

        double sum = 0.0;
        for (const auto& record : records) {
            sum += record.temperature;
        }
        double averageTemp = sum / records.size();

        double maxDeviation = 0.0;
        std::string stationWithMaxDeviation;

        for (const auto& record : records) {
            double deviation = std::abs(record.temperature - averageTemp);
            if (deviation > maxDeviation) {
                maxDeviation = deviation;
                stationWithMaxDeviation = record.stationID;
            }
        }

        logger->Log("Average Temperature: " + std::to_string(averageTemp));
        logger->Log("Station with Max Deviation (" + std::to_string(maxDeviation) +
                    "): " + stationWithMaxDeviation);
    }
};

// Test Suite
void RunTests() {
    ConsoleLogger consoleLogger;
    MonitoringManager manager(&consoleLogger);

    // Simulate temperature readings
    manager.AddTemperatureReading(23.5, "Station1");
    manager.AddTemperatureReading(25.0, "Station2");
    manager.AddTemperatureReading(22.8, "Station3");

    // Test with invalid reading
    manager.AddTemperatureReading(-100.0, "InvalidStation"); // Out of range

    // Simulate more readings to test average calculation and deviation detection
    manager.AddTemperatureReading(30.0, "Station4");
    manager.AddTemperatureReading(18.5, "Station5");

    std::cout << "Tests Completed." << std::endl;
}

int main() {
    RunTests();
    return 0;
}
