#[derive(Debug)]
struct Record {
    int_val: i32,
    double_val: f64,
    next: *mut Record,
    additional_data: *mut u8,
}

fn allocate_aligned<T>(size: usize) -> *mut T {
    let layout = Layout::from_size_align(size, 16).expect("Invalid layout");
    unsafe { alloc(layout) as *mut T }
}

unsafe fn initialize_record(int_min: i32, int_max: i32, double_min: f64, double_max: f64, num_records: usize) -> Result<*mut Record, &'static str> {
    let mut records: Vec<*mut Record> = Vec::with_capacity(num_records);

    for _ in 0..num_records {
        let record_ptr = allocate_aligned::<Record>(mem::size_of::<Record>() + 64); // Additional space for string
        if record_ptr.is_null() {
            return Err("Memory allocation failed");
        }

        let data_str_len = 32; // Example length
        let additional_data_ptr = allocate_aligned::<u8>(data_str_len);
        if additional_data_ptr.is_null() {
            dealloc(record_ptr as *mut u8, Layout::from_size_align(mem::size_of::<Record>() + data_str_len, 16).unwrap());
            return Err("Memory allocation failed");
        }

        let record = &mut *(record_ptr as *mut Record);
        record.int_val = rand::random::<i32>() % (int_max - int_min) + int_min;
        record.double_val = rand::random::<f64>() * (double_max - double_min) + double_min;
        record.next = ptr::null_mut();
        mem::forget(CString::new(format!("Data_{}", rand::random::<u32>()).as_str()));
        ptr::copy_nonoverlapping((additional_data_ptr as *const u8).add(1), additional_data_ptr, data_str_len - 1);
        (*additional_data_ptr.offset(data_str_len - 1)) = 0;

        record.additional_data = additional_data_ptr;
        records.push(record_ptr);
    }

    // Link the records into a singly linked list
    for i in 0..records.len() - 1 {
        unsafe { *(records[i] as *mut Record).next = records[i + 1]; }
    }

    Ok(records.first().unwrap())
}

fn verify_integrity(head: *const Record, num_records: usize) -> bool {
    let mut current = head;
    for _ in 0..num_records {
        if current.is_null() { return false; }
        unsafe {
            if (*current).int_val < -1_000_000 || (*current).int_val > 1_000_000 {
                return false;
            }
            if (*current).double_val < -1e10 || (*current).double_val > 1e10 {
                return false;
            }
        }

        let additional_data_ptr = unsafe { (*current).additional_data };
        if additional_data_ptr.is_null() { return false; }

        // Verify null-terminated string
        let data_slice = unsafe { slice::from_raw_parts(additional_data_ptr, 32) }; // Example length
        if !data_slice.ends_with(&[0]) {
            return false;
        }

        current = (*current).next;
    }
    true
}

fn main() -> Result<(), &'static str> {
    let num_records: usize = 100; // Example number of records

    let start_time = Instant::now();

    unsafe {
        match initialize_record(-1_000_000, 1_000_000, -1e10, 1e10, num_records) {
            Ok(head) => {
                if verify_integrity(head, num_records) {
                    // Perform operations
                } else {
                    return Err("Data integrity check failed");
                }

                let end_time = start_time.elapsed();
                println!("Time taken: {:?}", end_time);

                // Clean up records (example only)
                let mut current = head;
                while !current.is_null() {
                    let next = unsafe { (*current).next };
                    dealloc(current as *mut u8, Layout::from_size_align(mem::size_of::<Record>() + 64, 16).unwrap());
                    current = next;
                }
            },
            Err(e) => return Err(e),
        }
    }

    Ok(())
}

fn get_resident_set_size() -> usize {
