#include <time.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define MEMORY_ALIGN_BOUNDARY 16
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 1000

typedef struct {
    int value;
    long offset;
    int key;
    unsigned int ref_count;
} record_t;

sem_t *init_semaphore(unsigned int initial_value) {
    sem_t *sem = (sem_t *)aligned_alloc(MEMORY_ALIGN_BOUNDARY, sizeof(sem_t));
    if (!sem || sem_init(sem, 0, initial_value) != 0) {
        free(sem);
        return NULL;
    }
    return sem;
}

void destroy_semaphore(sem_t *sem) {
    if (sem) {
        sem_destroy(sem);
        aligned_free(sem);
    }
}

record_t **DynamicResourceManagerInit(size_t num_records, int theme_directory[256]) {
    record_t *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    size_t current_size = 0;
    sem_t *sem = init_semaphore(1);
    if (!sem) return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while (current_size < num_records) {
        size_t new_size = current_size + ((num_records - current_size > CHUNK_SIZE) ? CHUNK_SIZE : (size_t)(num_records - current_size));
        if (new_size > MAX_ELEMENTS) break;

        records = realloc(records, new_size * sizeof(record_t));
        offsets = realloc(offsets, new_size * sizeof(long));
        keys = realloc(keys, new_size * sizeof(int));

        if (!records || !offsets || !keys) {
            free(records);
            free(offsets);
            free(keys);
            destroy_semaphore(sem);
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        for (size_t i = current_size; i < new_size; ++i) {
            records[i].value = rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1) + RANDOM_RANGE_MIN;
            records[i].offset = i * sizeof(record_t);
            records[i].key = rand(); // Assume keys are unique for simplicity
            records[i].ref_count = 0;
        }

        current_size = new_size;
    }

    pthread_mutex_lock(&lock);
    srand(time(NULL));
    int used_keys[MAX_ELEMENTS] = {0};

    bool valid_keys = true;
    for (size_t i = 0; i < num_records && valid_keys; ++i) {
        while (used_keys[records[i].key]) {
            records[i].key = rand();
        }
        used_keys[records[i].key] = 1;
    }

    pthread_mutex_unlock(&lock);

    destroy_semaphore(sem);
    pthread_mutex_destroy(&lock);

    if (!valid_keys) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Simulate fetching theme assets from a server
    // This is a placeholder for actual network operations and cache management logic

    if (theme_directory[0] == '\0') {
        strcpy(theme_directory, "default_theme");
    }

    printf("Using theme directory: %s\n", theme_directory);

    return malloc(sizeof(record_t *) * 3);
}
