// Function to ensure capacity for records array
static void ensure_capacity(RecordManager* manager) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        if ((new_capacity * sizeof(Node*)) > MAX_MEMORY_USAGE) {
            fprintf(stderr, "Exceeded maximum memory usage\n");
            exit(EXIT_FAILURE);
        }

