    free(manager->records);
    manager->records = NULL;
    manager->count = 0;

    binary_read_data(file, &manager->records, sizeof(Node*) * INITIAL_RECORD_CAPACITY);
    manager->capacity = INITIAL_RECORD_CAPACITY;

    while (manager->count < manager->capacity && manager->records[manager->count] != NULL) {
        manager->count++;
    }

    destroy_avl_tree(manager->tree);  // Assume this function destroys the existing AVL Tree
    manager->tree = binary_deserialize_avl_tree(file);  // Assume this function deserializes AVL tree

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

// Function to iterate records forward
void iterate_forward(RecordManager* manager, void (*callback)(int id, float measurement)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]) {
            callback(manager->records[i]->id, manager->records[i]->measurement);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to iterate records backward
void iterate_backward(RecordManager* manager, void (*callback)(int id, float measurement)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = manager->count; i > 0; --i) {
        if (manager->records[i - 1]) {
            callback(manager->records[i - 1]->id, manager->records[i - 1]->measurement);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to find a node by ID
static Node* find_node_by_id(Node** head, int id) {
    for (Node* current = *head; current != NULL; current = current->next) {
        if (current->id == id) return current;
    }
    return NULL;
}

// Cleanup function to free resources
void cleanup_record_manager(RecordManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i]) {
            free(manager->records[i]);
        }
    }

    free(manager->records);
    destroy_avl_tree(manager->tree);  // Assume this function destroys the AVL Tree

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
