#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <stdint.h>

#define ALIGNED_ALLOC(alignment, size) _aligned_malloc(size, alignment)
#define ALIGNED_FREE(ptr) _aligned_free(ptr)

typedef struct {
    int key;
    char string[16]; // Example fixed length
} Item;

typedef struct Node {
    double value;
    Item *items;
    size_t items_count;
    size_t capacity;
    struct Node* next; // For linked list functionality if needed
} Node;

// Hash table entry for fast lookups
typedef struct {
    int key;
    size_t index;
} HashEntry;

#define INITIAL_CAPACITY 16

Node* create_node(double value, size_t initial_capacity) {
    Node *node = (Node*) ALIGNED_ALLOC(32, sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->items_count = 0;
    node->capacity = initial_capacity;
    node->items = (Item*) ALIGNED_ALLOC(32, initial_capacity * sizeof(Item));
    if (!node->items) {
        ALIGNED_FREE(node);
        return NULL;
    }

    return node;
}

int grow_items(Node* node) {
    size_t new_capacity = node->capacity * 2;
    Item *new_items = (Item*) ALIGNED_ALLOC(32, new_capacity * sizeof(Item));
    if (!new_items) return -1;

    memcpy(new_items, node->items, node->items_count * sizeof(Item));

    ALIGNED_FREE(node->items);
    node->items = new_items;
    node->capacity = new_capacity;

    return 0;
}

int initialize_structures(Node **nodes, HashEntry **hash_table, size_t num_nodes) {
    srand(time(NULL));
    size_t hash_size = num_nodes * 2; // Simple load factor consideration
    *nodes = (Node*) ALIGNED_ALLOC(32, num_nodes * sizeof(Node));
    if (!*nodes) return -1;

    *hash_table = (HashEntry*) ALIGNED_ALLOC(32, hash_size * sizeof(HashEntry));
    if (!*hash_table) {
        ALIGNED_FREE(*nodes);
        return -1;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        int rand_int = rand() % 100 + 1; // Example range
        double value = sqrt(rand_int);

        Node *node = create_node(value, INITIAL_CAPACITY);
        if (!node) return -1;

        (*nodes)[i] = *node;
        ALIGNED_FREE(node);

        int key = rand() % 1000; // Unique integer key

        for (size_t j = 0; j < i + 1; ++j) { // Ensure uniqueness
            if ((*hash_table)[j].key == key) {
                key = rand() % 1000;
                j = -1;
            }
        }

        (*hash_table)[i] = (HashEntry){ .key = key, .index = i };

        int item_count = rand() % INITIAL_CAPACITY + 1; // Random number of items
        for (size_t k = 0; k < item_count; ++k) {
            if ((*nodes)[i].items_count == (*nodes)[i].capacity && grow_items(&(*nodes)[i]) != 0)
                return -1;

            Item *item = &((*nodes)[i].items)[(*nodes)[i].items_count++];
            item->key = rand() % 10000; // Example unique key generation

            for (int l = 0; l < sizeof(item->string); ++l) {
                char c = 'A' + rand() % 26;
                if ((rand() % 2) == 1)
                    c += ('a' - 'A');
                item->string[l] = c;
            }
        }
    }

    // Simple sort by value (could use qsort or another sorting method)
    for (size_t i = 0; i < num_nodes - 1; ++i) {
        for (size_t j = i + 1; j < num_nodes; ++j) {
            if ((*nodes)[i].value > (*nodes)[j].value) {
                Node temp = (*nodes)[i];
                (*nodes)[i] = (*nodes)[j];
                (*nodes)[j] = temp;

                HashEntry hash_temp = (*hash_table)[i];
                (*hash_table)[i] = (*hash_table)[j];
                (*hash_table)[j] = hash_temp;
            }
        }
    }

    return 0;
}

void free_structures(Node *nodes, size_t num_nodes, HashEntry *hash_table) {
    for (size_t i = 0; i < num_nodes; ++i) {
        ALIGNED_FREE(nodes[i].items);
    }

    ALIGNED_FREE(nodes);
    ALIGNED_FREE(hash_table);
}

int main() {
    size_t num_nodes = 10;
    Node *nodes = NULL;
    HashEntry *hash_table = NULL;

    if (initialize_structures(&nodes, &hash_table, num_nodes) == -1) {
        fprintf(stderr, "Failed to initialize structures\n");
        return EXIT_FAILURE;
    }

    // Example usage
    for (size_t i = 0; i < num_nodes; ++i) {
        printf("Node %zu: Value=%.2f, Key=%d\n", i, nodes[i].value, hash_table[i].key);
    }

    free_structures(nodes, num_nodes, hash_table);

    return EXIT_SUCCESS;
}
```

### Key Points:
- Memory alignment is ensured using `_aligned_malloc` to align allocations on 32-byte boundaries.
- The `initialize_structures` function initializes nodes and their items with random values, ensuring unique keys for the hash table entries.
- Nodes are sorted by their double value after initialization.
- A simple linear search mechanism within a loop sorts the data. In practice, this can be replaced with more efficient sorting algorithms like `qsort`.
- The code includes basic error handling to check if memory allocations succeed and cleans up in case of failures.
- Structures are freed using `_aligned_free` for consistency with their allocation method.

This implementation balances between efficient memory use, alignment requirements, and simplicity, considering the constraints described.']

