#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB
#define INITIAL_CAPACITY 100
#define RESIZE_THRESHOLD 0.8
#define LOG_FILE "data_log.txt"

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
    size_t node_count;
    size_t memory_usage;
} LinkedList;

// Cache structure
typedef struct Cache {
    Record* records;
    int capacity;
    int hit_count;
    pthread_rwlock_t rwlock;
} Cache;

// Global variables for the system
LinkedList list;
Cache cache;

void init_list(LinkedList* list) {
    list->head = NULL;
    list->node_count = 0;
    list->memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
}

Record create_record(int min_val, int max_val) {
    Record rec;
    rec.value = rand() % (max_val - min_val + 1) + min_val;
    return rec;
}

void log_operation(const char* operation, const Record* record) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s: %d\n", operation, record->value);
        fclose(file);
    }
}

int add_record(LinkedList* list, int min_val, int max_val) {
    pthread_mutex_lock(&list->lock);

    if ((list->memory_usage + sizeof(Node)) > MAX_MEMORY_USAGE) {
        printf("Memory limit exceeded.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = create_record(min_val, max_val);
    log_operation("ADD", &new_node->data);

    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;
    list->memory_usage += sizeof(Node);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void serialize_list(const LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file) {
        Node* current = list->head;
        while (current) {
            fwrite(&(current->data), sizeof(Record), 1, file);
            current = current->next;
        }
        fclose(file);
    }
}

void deserialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file) {
        Record rec;
        while (fread(&rec, sizeof(Record), 1, file)) {
            add_record(list, -1000, 1000); // Using default range for simplicity
        }
        fclose(file);
    }
}

void init_cache(Cache* cache, int capacity) {
    cache->records = (Record*)malloc(sizeof(Record) * capacity);
    if (!cache->records) {
        printf("Cache initialization failed.\n");
        exit(EXIT_FAILURE);
    }
    cache->capacity = capacity;
    cache->hit_count = 0;
    pthread_rwlock_init(&cache->rwlock, NULL);
}

int get_from_cache(Cache* cache, int index) {
    if (index < 0 || index >= cache->capacity) return -1;

    pthread_rwlock_rdlock(&cache->rwlock);
    int value = cache->records[index].value;
    pthread_rwlock_unlock(&cache->rwlock);

    return value;
}

int set_in_cache(Cache* cache, int index, Record record) {
    if (index < 0 || index >= cache->capacity) return -1;

    pthread_rwlock_wrlock(&cache->rwlock);
    cache->records[index] = record;
    cache->hit_count++;
    pthread_rwlock_unlock(&cache->rwlock);

    return 0;
}

// Function to resize the linked list, if necessary
void maybe_resize_list(LinkedList* list) {
    size_t current_usage = list->memory_usage;

    if ((float)current_usage / MAX_MEMORY_USAGE > RESIZE_THRESHOLD) {
        // Logic to manage resizing and memory management
        printf("Resizing needed but not implemented in this outline.\n");
    }
}

// Function to handle concurrent operations on the linked list
void* thread_func(void* arg) {
    int min_val = 1, max_val = 100;
    while (add_record(&list, min_val, max_val) == 0);
    return NULL;
}

int main() {
    srand(time(NULL));
    init_list(&list);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    serialize_list(&list, "data.bin");
    deserialize_list(&list, "data.bin");

    init_cache(&cache, INITIAL_CAPACITY);

    return 0;
}
```

### Key Points:

- **Thread Safety**: Using mutexes for write operations and read-write locks for the cache ensures thread-safe access.
- **Serialization/Deserialization**: The list can be serialized to and deserialized from a binary file.
- **Logging**: Operations are logged in a simple text file for audit purposes.
- **Caching**: A basic caching mechanism is included to optimize repeated reads.
- **Memory Management**: Dynamic memory allocation with checks against the maximum memory limit.

This code provides a starting point. Further enhancements, such as more sophisticated resizing strategies or advanced concurrency control mechanisms like lock-free data structures, can be implemented based on specific requirements and performance profiling.']

