    char* result = aligned_malloc(length * sizeof(char));
    if (!result) exit(EXIT_FAILURE);

    for (size_t i = 0; i < length; ++i) {
        size_t index = rand() % (sizeof(charset) - 1);
        result[i] = charset[index];
    }
    result[length] = '\0';

    return result;
}

void init_random_generator(unsigned int seed) {
    srand(seed);
}

LinkedListNode* create_linked_list(size_t count) {
    LinkedListNode* head = aligned_malloc(sizeof(LinkedListNode));
    if (!head) exit(EXIT_FAILURE);

    head->data = aligned_malloc(count * sizeof(Item));
    if (!head->data) exit(EXIT_FAILURE);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_init(&((Item*)head->data)[i].lock, NULL);
        ((Item*)head->data)[i].key = rand() % ITEM_KEY_RANGE;
        ((Item*)head->data)[i].alphanumeric = *generate_random_alphanumeric_string(ALPHANUMERIC_LENGTH);
        if (rand() / (RAND_MAX + 1.0) < METADATA_PROBABILITY_DISTRIBUTION) {
            ((Item*)head->data)[i].metadata.item_ptr = NULL; // Example, could point to another item
        } else {
            ((Item*)head->data)[i].metadata.short_value = rand() % 100;
        }
        ((Item*)head->data)[i].usage_count = 0;

        LinkedListNode* node = &((LinkedListNode*)((char*)head->data + i * sizeof(Item)));
        node->next = (i < count - 1) ? (LinkedListNode*)((char*)head->data + (i + 1) * sizeof(Item)) : NULL;
    }

    return head;
}

void free_linked_list(LinkedListNode* head, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_destroy(&((Item*)((char*)head->data + i * sizeof(Item)))->lock);
    }
    aligned_free(head->data);
    aligned_free(head);
}

void increment_ref_count(Node* node) {
    pthread_mutex_lock(&node->lock);
    node->ref_count++;
    pthread_mutex_unlock(&node->lock);
}

void decrement_ref_count_and_garbage_collect(Node* node, LinkedListNode** head, size_t item_count) {
    pthread_mutex_lock(&node->lock);
    if (--node->ref_count == 0) {
        for (size_t i = 0; i < item_count; ++i) {
            Item* item = &((Item*)((char*)(*head)->data + i * sizeof(Item)));
            pthread_mutex_lock(&item->lock);
            if (--item->usage_count == 0) {
                // Free metadata if it's a pointer
                if (item->metadata.item_ptr != NULL) {
                    aligned_free(item->metadata.item_ptr);
                }
            }
            pthread_mutex_unlock(&item->lock);
        }
        free_linked_list(*head, item_count);
        *head = NULL;
    }
    pthread_mutex_unlock(&node->lock);
}

void* manage_data_structures(unsigned int seed) {
    init_random_generator(seed);

    Node** nodes = aligned_malloc(MAX_NODES * sizeof(Node*));
    if (!nodes) exit(EXIT_FAILURE);

    LinkedListNode** heads = aligned_malloc(MAX_NODES * sizeof(LinkedListNode*));
    if (!heads) exit(EXIT_FAILURE);

    for (int i = 0; i < MAX_NODES; ++i) {
        nodes[i] = aligned_malloc(sizeof(Node));
        if (!nodes[i]) exit(EXIT_FAILURE);

        pthread_mutex_init(&nodes[i]->lock, NULL);
        nodes[i]->ref_count = 1;

        heads[i] = create_linked_list(NODES_PER_ITEM);

        for (int j = 0; j < NODES_PER_ITEM; ++j) {
            Item* item = &((Item*)((char*)heads[i]->data + j * sizeof(Item)));
            pthread_mutex_lock(&item->lock);
            item->usage_count++;
            pthread_mutex_unlock(&item->lock);
        }

        nodes[i]->value = random_double(1, 100);

        // Integrity check: Ensure valid pointers and consistent ref counts
        if (!nodes[i] || !heads[i]) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }
    }

    return malloc(sizeof(struct {
        Node** nodes;
        LinkedListNode** heads;
    }));
}
```

