NetworkDevice* initialize_network_device(void (*nms_callback)(const char*, void*), void *nms_context,
                                         const char **interface_names, const char **mac_addresses,
                                         int interface_count) {
    NetworkDevice *device = aligned_alloc(sizeof(NetworkDevice));
    if (!device) return NULL;

    device->interfaces = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < interface_count; ++i) {
        const char *name = interface_names[i];
        const char *mac_address = mac_addresses[i];

        bool valid_mac = nms_callback(mac_address, nms_context);
        int retry_count = 0;

        while (!valid_mac && retry_count < MAX_RETRIES) {
            // Simulate using a backup MAC address or logging
            log_error("Invalid MAC address. Retrying...");
            retry_count++;
            valid_mac = nms_callback(mac_address, nms_context);  // Retry with the same logic for demonstration
        }

        if (!valid_mac) {
            log_error("Failed to validate MAC address after retries.");
            continue;
        }

        Interface *new_iface = create_interface_node(name, mac_address);
        if (!new_iface) continue;

        pthread_mutex_lock(&lock);

        new_iface->next = device->interfaces;
        device->interfaces = new_iface;

        pthread_mutex_unlock(&lock);
    }

    return device;
}

void cleanup_network_device(NetworkDevice *device) {
    Interface *iface = device->interfaces, *temp_iface;
    while (iface) {
        temp_iface = iface->next;

        free(iface->name);
        free(iface->MAC_address);

        Parameter *param = iface->parameters, *temp_param;
        while (param) {
            temp_param = param->next;
            free(param->key);
            free(param->value);
            free(param);
            param = temp_param;
        }

        free(iface);
        iface = temp_iface;
    }

