        snprintf((*records)[i].identifier, sizeof((*records)[i].identifier),
                 "ID_%zu_%zu", i, get_current_time());

        (*records)[i].pItem = (item*)malloc(sizeof(item));
        if (!(*records)[i].pItem) goto cleanup;

        (*records)[i].pItem->size = sizeof(double);
        (*records)[i].pItem->data.dValue = 0.0; // Initialize with a double
        totalMemoryUsage += sizeof(record) + sizeof(item);
    }

    if (totalMemoryUsage > MEMORY_LIMIT) {
        // Implement LRU eviction policy here to manage memory usage
    }

    log_memory_usage(totalMemoryUsage);

    pthread_mutex_unlock(&lock);
    return 0;

cleanup:
    // Free allocated resources on error
    free(*longPtrArray);
    free(*doubleArray);
    for (size_t i = 0; i < *structCount; ++i) {
        free((*structs)[i].str);
    }
    free(*structs);
    free(*keys);
    for (size_t i = 0; i < *recordCount; ++i) {
        if ((*records)[i].pItem) free((*records)[i].pItem);
    }
    free(*records);

    pthread_mutex_unlock(&lock);
    return -1;
}

// JNI interface to Java
JNIEXPORT void JNICALL Java_MyJavaClass_connect(JNIEnv *env, jobject obj) {
    jclass cls = (*env)->GetObjectClass(env, obj);
    jmethodID midConnect = (*env)->GetMethodID(env, cls, "connect", "()V");

    if (midConnect == NULL) return;

    // Implement connection with retry logic
    int retries = 0;
    while (retries < 5) {
        jint result = (*env)->CallIntMethod(env, obj, midConnect);
        if (result == JNI_TRUE) break; // Connection successful

        retries++;
        sleep(1 << retries); // Exponential backoff
    }
}

// Main function for testing
int main() {
    long* longPtrArray;
    size_t longCount;
    double* doubleArray;
    size_t doubleCount;
    struct { char* str; unsigned int num; }* structs;
    size_t structCount;
    int* keys;
    record* records;
    size_t recordCount;

    if (allocate_and_initialize(&longPtrArray, &longCount,
                                &doubleArray, &doubleCount,
                                &structs, &structCount,
                                &keys, &records, &recordCount) != 0) {
        fprintf(stderr, "Failed to allocate and initialize memory\n");
        return EXIT_FAILURE;
    }

    // Free allocated resources
    free(longPtrArray);
    free(doubleArray);
    for (size_t i = 0; i < structCount; ++i) {
        free(structs[i].str);
    }
    free(structs);
    free(keys);
    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i].pItem) free(records[i].pItem);
    }
    free(records);

    return EXIT_SUCCESS;
}
```

