['Below is an implementation of a C program that manages a dynamic memory pool for records in a multi-threaded environment using mutexes for thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CHAR_FIELD 11 // 10 characters + null terminator
#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    long offset;
    int key;
    char char_field[MAX_CHAR_FIELD];
} Record;

typedef struct {
    Record **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash(int key, size_t capacity) {
    return (unsigned int)(key % capacity);
}

char* random_alphanumeric(size_t length, unsigned int seed) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = malloc(length + 1);
    if (!str) return NULL;

    srand(seed ^ time(NULL));
    for (size_t i = 0; i < length; i++) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
    return str;
}

HashTable* create_table(size_t initial_capacity) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(initial_capacity, sizeof(Record *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void resize_table(HashTable *table);

Record* create_record(long offset, int key, unsigned int seed) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->offset = offset;
    record->key = key;
    strncpy(record->char_field, random_alphanumeric(MAX_CHAR_FIELD - 1, seed), MAX_CHAR_FIELD);
    record->char_field[MAX_CHAR_FIELD - 1] = '\0';

    return record;
}

void add_record(HashTable *table, Record *record) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->size / table->capacity >= LOAD_FACTOR) {
        resize_table(table);
    }

    unsigned int index = hash(record->key, table->capacity);
    while (table->buckets[index] != NULL) {
        index = (index + 1) % table->capacity;
    }

    table->buckets[index] = record;
    table->size++;

    pthread_mutex_unlock(&table->lock);
}

void resize_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Record **new_buckets = calloc(new_capacity, sizeof(Record *));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->capacity; i++) {
        Record *record = table->buckets[i];
        if (record != NULL) {
            unsigned int index = hash(record->key, new_capacity);
            while (new_buckets[index] != NULL) {
                index = (index + 1) % new_capacity;
            }
            new_buckets[index] = record;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

Record* get_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned int index = hash(key, table->capacity);
    size_t start_index = index;

    do {
        Record *record = table->buckets[index];
        if (record != NULL && record->key == key) {
            pthread_mutex_unlock(&table->lock);
            return record;
        }
        index = (index + 1) % table->capacity;
    } while (index != start_index);

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned int index = hash(key, table->capacity);
    size_t start_index = index;

    do {
        Record *record = table->buckets[index];
        if (record != NULL && record->key == key) {
            free(record->char_field); // Free the char field
            free(record);
            table->buckets[index] = NULL;
            table->size--;
            break;
        }
        index = (index + 1) % table->capacity;
    } while (index != start_index);

    pthread_mutex_unlock(&table->lock);
}

void destroy_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]->char_field);
            free(table->buckets[i]);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void* memory_pool(size_t max_records, unsigned int seed) {
    HashTable *table = create_table(INITIAL_CAPACITY);

    if (!table) return NULL;

    for (size_t i = 0; i < max_records; i++) {
        long offset = rand_r(&seed) % 1000000;
        int key = rand_r(&seed) % 10000;

        Record *record = create_record(offset, key, seed);
        add_record(table, record);
    }

    return table->buckets; // Return pointer to first element
}
```

This code manages a dynamic memory pool for records in a multi-threaded application environment. It includes thread-safe operations with mutexes and dynamically resizes the hash table when necessary, ensuring efficient key-based retrieval and handling of concurrent access safely. The random alphanumeric strings are generated using a specified seed, allowing reproducibility across runs.']

