typedef struct {
    int value;
} record;

// Function prototype for the random number generator callback
int (*random_number_generator)(int min, int max);

void generate_records_and_modify_string(int size_limit, char *input_str, int (*callback)(int, int), int rand_min, int rand_max) {
    // Check if input string exceeds the specified size limit
    if (strlen(input_str) > size_limit) {
        return;
    }

    // Assign callback function to the generator pointer for flexibility
    random_number_generator = callback;

    // Efficient memory allocation based on available data
    record *records = malloc(size_limit * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Populate each record with a random number using the provided callback function
    for (int i = 0; i < size_limit; ++i) {
        records[i].value = random_number_generator(rand_min, rand_max);
    }

    // Modify input string to append a slash at the end if under size limit
    int str_len = strlen(input_str);
    if ((str_len + 1) <= size_limit) { // Ensure there's space for the null terminator
        input_str[str_len] = '/';
        input_str[str_len + 1] = '\0';
    }

    // Optionally print records or further process them as needed
    for (int i = 0; i < size_limit && i <= str_len; ++i) {
        printf("Record %d: %d\n", i, records[i].value);
    }

    // Free allocated memory after use to prevent leaks
    free(records);
}
