    inet_pton(AF_INET, "10.0.0.", &((char *)&(header->dst_ip))[12]);
    header->dst_ip.s_addr += (rand() % 255 + 1);

    header->src_port = rand() % 65536;
    header->dst_port = rand() % 65536;

    size_t payload_size = rand() % (MAX_PAYLOAD_SIZE + 1);
    header->payload = (char *)malloc(payload_size);
    if (!header->payload) {
        free(header);
        return NULL;
    }

    for (size_t i = 0; i < payload_size; ++i) {
        header->payload[i] = '!' + (rand() % 94); // Random printable ASCII
    }

    return header;
}

HeaderManager* init_header_manager(size_t max_headers, unsigned int seed) {
    HeaderManager *manager = (HeaderManager *)malloc(sizeof(HeaderManager));
    if (!manager) return NULL;

    manager->headers = (PacketHeader **)calloc(max_headers, sizeof(PacketHeader *));
    if (!manager->headers) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    srand(seed);

    for (size_t i = 0; i < max_headers; ++i) {
        PacketHeader *header = create_packet_header();
        if (!header) continue;

        pthread_mutex_lock(&manager->lock);
        manager->headers[manager->count++] = header;
        pthread_mutex_unlock(&manager->lock);
    }

    return manager;
}

void free_header_manager(HeaderManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        PacketHeader *header = manager->headers[i];
        if (header) {
            free(header->payload);
            free(header);
        }
    }

    free(manager->headers);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    size_t max_headers = 1000;
    unsigned int seed = time(NULL);

    HeaderManager *manager = init_header_manager(max_headers, seed);
