void manage_memory(long *offsets, int num_offsets, 
                   int *keys, int num_keys,
                   record ***records, int num_records, int range_min, int range_max) {
    // Allocate memory for offsets
    offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for keys
    keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Seed random number generator for record initialization
    srand(time(NULL));

    // Allocate and initialize records array with dynamic structures
    *records = (record **)malloc(num_records * sizeof(record *));
    if (!(*records)) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if (!(*records)[i]) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            // Free previously allocated records
            while (--i >= 0)
                free((*records)[i]);
            free(offsets);
            free(keys);
            free(*records);
            exit(EXIT_FAILURE);
        }

        // Initialize each record with a random value within the specified range
        (*records)[i]->value = rand() % (range_max - range_min + 1) + range_min;
    }
}

char* process_string(const char *input, size_t max_length) {
    if (!input)
        return NULL;

    size_t length = strlen(input);
    size_t truncated_length = (length > max_length) ? max_length : length;

    // Allocate memory for the output string
    char *result = (char *)malloc(truncated_length + 1); // +1 for null terminator
    if (!result)
        return NULL;

    strncpy(result, input, truncated_length);
    result[truncated_length] = '\0'; // Null terminate

    return result;
}

int main() {
    long *offsets;
    int *keys;
    record **records;

    manage_memory(offsets, 10, keys, 5, &records, 7, 1, 100);

    char *input_string = "This is a test string to be truncated";
    size_t max_length = 10;
    char *truncated_string = process_string(input_string, max_length);

    if (truncated_string) {
        printf("Truncated String: %s\n", truncated_string);
        free(truncated_string);
    }

    // Free allocated memory
    for (int i = 0; i < 7; ++i)
        free(records[i]);
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
