// Function to align memory allocation.
void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) ptr = NULL;
#else
    int err = posix_memalign(&ptr, alignment, size);
    if (err != 0) ptr = NULL;
#endif
    return ptr;
}

void free_aligned(void *ptr) {
    free(ptr);
