    int validation_failures;
} ProcessData;

void process_files(FilePair *filePairs, size_t count) {
    pthread_t threads[count];
    ProcessData processDataArray[count];

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        memcpy(&processDataArray[i], &filePairs[i], sizeof(FilePair));
        if(pthread_create(&threads[i], NULL, process_file, &processDataArray[i])) {
            log_error("Failed to create thread");
        }
    }

    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* process_file(void* arg) {
