    NFAPI_CRC_INDICATION_PDU_T *nfaArray = aligned_malloc(
        sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structs,
        ALIGNMENT);

    if (!nfaArray) {
        log_error("Memory allocation failed");
        return NULL;
    }

    int validation_failures = 0;

    for (size_t i = 0; i < num_structs; ++i) {
        nfaArray[i].RX_UE_INFORMATION_TAG = rand();  // Placeholder value
        nfaArray[i].RNTI = rand() % 100000;          // Example RNTI generation

        uint8_t crcflag;
        do {
            crcflag = random_crc_flag();
            if (crcflag >= 0 && crcflag <= 255) {   // Validation logic for CRCFLAG
                break;
            }
            ++validation_failures;
        } while (1);

        nfaArray[i].CRCFLAG = crcflag;
    }

    data->validation_failures += validation_failures;

    if (strstr(file_pair.inputFileName, ".jpeg") || strstr(file_pair.inputFileName, ".jpg")) {
        convert_jpeg_to_pdf(file_pair.inputFileName, file_pair.outputFileName);
    } else {
        log_error("Unsupported file format");
    }

    free_aligned(nfaArray);

    return NULL;
}

int convert_jpeg_to_pdf(const char* inputFileName, const char* outputFileName) {
    // Conversion logic using third-party library
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    FILE *inputFile = fopen(inputFileName, "rb");
    if (!inputFile) {
        log_error("Failed to open input JPEG file");
        return -1;
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    jpeg_stdio_src(&cinfo, inputFile);
    (void)jpeg_read_header(&cinfo, TRUE);
    (void)jpeg_start_decompress(&cinfo);

    // Conversion logic here...

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(inputFile);

    return 0;  // Assuming success
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        log_error("Usage: program <input1> <output1> [<input2> <output2> ...]");
        return EXIT_FAILURE;
    }

    FilePair *filePairs = malloc((argc - 1) / 2 * sizeof(FilePair));
    if (!filePairs) {
        log_error("Memory allocation for file pairs failed");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < argc - 1; i += 2) {
        filePairs[i / 2].inputFileName = argv[i + 1];
        filePairs[i / 2].outputFileName = argv[i + 2];
    }

    process_files(filePairs, (argc - 1) / 2);

    free(filePairs);
    return EXIT_SUCCESS;
}
