#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    union {
        int intValue;
        float floatValue;
    } data;
} Data;

typedef struct Node {
    Data* dataPtr;
    int key;
    char typeFlag; // 'i' for integer, 'f' for float
    struct Node* next;
} Node;

Node* create_node(int key, char typeFlag) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    newNode->key = key;
    newNode->typeFlag = typeFlag;
    newNode->dataPtr = (Data*)malloc(sizeof(Data));
    if (!newNode->dataPtr) {
        perror("Failed to allocate memory for data");
        free(newNode);
        return NULL;
    }
    newNode->next = NULL;
    return newNode;
}

void destroy_node(Node* node) {
    if (node) {
        free(node->dataPtr);
        free(node);
    }
}

int parse_line(char* line, Node** head) {
    int key;
    char typeFlag;
    union {
        int intValue;
        float floatValue;
    } value;

    // Expected format: "key,typeFlag,value"
    if (sscanf(line, "%d,%c,%n", &key, &typeFlag, NULL) != 2) {
        fprintf(stderr, "Malformed line: %s\n", line);
        return -1;
    }

    char* valueStr = strchr(line, ',') + 1; // Move past the first comma
    if (typeFlag == 'i' && sscanf(valueStr, "%d%n", &value.intValue, NULL) != 1) {
        fprintf(stderr, "Malformed integer value: %s\n", valueStr);
        return -1;
    } else if (typeFlag == 'f' && sscanf(valueStr, "%f%n", &value.floatValue, NULL) != 1) {
        fprintf(stderr, "Malformed float value: %s\n", valueStr);
        return -1;
    }

    Node* newNode = create_node(key, typeFlag);
    if (!newNode) return -1;

    if (typeFlag == 'i') {
        newNode->dataPtr->intValue = value.intValue;
    } else {
        newNode->dataPtr->floatValue = value.floatValue;
    }

    // Insert node at the beginning for simplicity
    newNode->next = *head;
    *head = newNode;
    return 0;
}

void print_nodes(Node* head) {
    Node* current = head;
    while (current) {
        printf("Key: %d, Type: %c, Value: ", current->key, current->typeFlag);
        if (current->typeFlag == 'i') {
            printf("%d\n", current->dataPtr->intValue);
        } else {
            printf("%.2f\n", current->dataPtr->floatValue);
        }
        current = current->next;
    }
}

void free_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    Node* head = NULL;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';
        if (parse_line(line, &head) != 0) {
            fprintf(stderr, "Error parsing line: %s\n", line);
            free_list(head);
            fclose(file);
            return EXIT_FAILURE;
        }
    }

    print_nodes(head);
    free_list(head);
    fclose(file);

    return EXIT_SUCCESS;
}
