typedef int (*is_prime_func)(int);

// Utility function to check if a number is prime
int default_is_prime(int num) {
    if (num <= 1) return 0;
    if (num == 2) return 1;
    if (num % 2 == 0) return 0;
    for (int i = 3; i * i <= num; i += 2) {
        if (num % i == 0) return 0;
    }
    return 1;
}

// Function to initialize offsets
void init_offsets(long offsets[], int size, long (*init_func)(int)) {
    for (int i = 0; i < size; ++i) {
        offsets[i] = init_func(i);
    }
}

// Utility function to generate random number
long offset_init_function(int index) {
    return index * 10L + 5L;
}

// Function to get next prime number with caching
int get_next_prime(int *index, int primes[], int max_primes, is_prime_func check_prime) {
    if (*index < max_primes && primes[*index] != -1) {
        return primes[(*index)++];
    }

    for (int i = (*index) + 1; i <= MAX_KEY_VALUE; ++i) {
        if (check_prime(i)) {
            primes[*index] = i;
            return i;
        }
    }
    return -1;
}

// Function to initialize keys and records
void manage_memory(long offsets[], int num_offsets, Record **records, int *num_records,
                   is_prime_func check_prime) {

    // Precompute primes for key allocation
    int max_primes = MAX_KEY_VALUE / 10 + 1; // Heuristic value for prime storage
    int primes[max_primes];
    for (int i = 0; i < max_primes; ++i) {
        primes[i] = -1;
    }

    int *keys = NULL;
    keys = malloc(num_offsets * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return;
    }

    int key_index = 0;
    // Allocate and initialize keys
    for (int i = 0; i < num_offsets; ++i) {
        int prime = get_next_prime(&key_index, primes, max_primes, check_prime);
        if (prime == -1) {
            fprintf(stderr, "Failed to generate a sufficient number of primes\n");
            free(keys);
            return;
        }
        keys[i] = prime;
    }

    // Allocate records array
    *records = malloc(num_offsets * sizeof(Record));
    if (!(*records)) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(keys);
        return;
    }

    // Initialize records with random values
    srand((unsigned)time(NULL));
    for (int i = 0; i < num_offsets; ++i) {
        (*records)[i].value = rand() % MAX_KEY_VALUE + 1;
    }

    *num_records = num_offsets;

    free(keys);
}

// Main function to test the implementation
int main(void) {
    long offsets[MAX_OFFSETS];
    Record *records = NULL;
    int num_records = 0;

    init_offsets(offsets, MAX_OFFSETS, offset_init_function);

    manage_memory(offsets, MAX_OFFSETS, &records, &num_records, default_is_prime);

    if (records != NULL) {
        for (int i = 0; i < num_records; ++i) {
            printf("Record %d: Value = %d\n", i, records[i].value);
        }
        free(records);
    }

    return 0;
}
