#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int value;
} record;

int generate_offsets(long start, long end, long step, long **offsets) {
    if (step <= 0 || start > end) return -1;

    long count = 0;
    long current = start;

    while (current + step <= end && count < LONG_MAX / sizeof(long)) {
        current += step;
        count++;
    }

    *offsets = malloc(count * sizeof(long));
    if (!*offsets) return -1;

    current = start;
    for (long i = 0; i < count; i++) {
        (*offsets)[i] = current;
        current += step;
    }

    return count;
}

int validate_and_allocate_keys(int min, int max, int *keys, size_t key_count) {
    if (min > max || key_count == 0) return -1;

    int range_size = max - min + 1;
    if (range_size < key_count) return -1; // Not enough unique keys

    int *key_set = calloc(range_size, sizeof(int));
    if (!key_set) {
        free(keys);
        return -1;
    }

    size_t idx = 0;
    for (int i = min; i <= max && idx < key_count; i++) {
        if (!key_set[i - min]) {
            keys[idx++] = i;
            key_set[i - min] = 1;
        }
    }

    free(key_set);
    return idx;
}

void generate_records(int count, int seed, int value_range_min, int value_range_max, record ***records) {
    if (count <= 0 || value_range_min > value_range_max) {
        *records = NULL;
        return;
    }

    int range_size = value_range_max - value_range_min + 1;
    if (range_size < count) {
        *records = NULL;
        return;
    }

    int *unique_values = malloc(range_size * sizeof(int));
    if (!unique_values) {
        *records = NULL;
        return;
    }

    for (int i = 0; i < range_size; i++) unique_values[i] = 0;

    srand(seed);
    size_t idx = 0;
    while (idx < count) {
        int value = value_range_min + rand() % (value_range_max - value_range_min + 1);
        if (!unique_values[value - value_range_min]) {
            unique_values[value - value_range_min] = 1;
            idx++;
        }
    }

    *records = malloc(count * sizeof(record *));
    if (!*records) {
        free(unique_values);
        return;
    }

    for (size_t i = 0; i < count; i++) {
        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            while (i > 0) {
                free((*records)[--i]);
            }
            free(*records);
            *records = NULL;
            break;
        }

        int value = value_range_min + rand() % (value_range_max - value_range_min + 1);
        (*records)[i]->value = value;
        unique_values[value - value_range_min] = 0; // Reset for next call
    }

    free(unique_values);
}

void cleanup(long *offsets, int *keys, record **records, size_t count) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) {
        for (size_t i = 0; i < count; i++) {
            if (records[i]) free(records[i]);
        }
        free(records);
    }
}

int main() {
    long *offsets;
    int offset_count = generate_offsets(0, 1000000L, 10L, &offsets);

    if (offset_count == -1) {
        fprintf(stderr, "Failed to allocate offsets\n");
        return EXIT_FAILURE;
    }

    size_t key_count = 100;
    int *keys = malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets);
        return EXIT_FAILURE;
    }

    int key_allocation_result = validate_and_allocate_keys(0, 200, keys, key_count);
    if (key_allocation_result == -1 || key_allocation_result != key_count) {
        fprintf(stderr, "Failed to allocate keys\n");
        cleanup(offsets, keys, NULL, 0);
        return EXIT_FAILURE;
    }

    size_t record_count = 50;
    record **records;
    generate_records(record_count, 12345, 0, 1000, &records);

    if (!records) {
        fprintf(stderr, "Failed to allocate records\n");
        cleanup(offsets, keys, NULL, 0);
        return EXIT_FAILURE;
    }

    // Use the data structures as needed...

    cleanup(offsets, keys, records, record_count);
    return EXIT_SUCCESS;
}
