int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number_of_records> [options]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_records = atoi(argv[1]);
    user_options options = {0, 100, 10, 1, 1}; // Default options

    if (num_records <= 0) {
        fprintf(stderr, "Number of records must be positive.\n");
        return EXIT_FAILURE;
    }

    int64_t available_memory = get_available_memory();
    if (available_memory == -1 || num_records > available_memory / sizeof(record)) {
        fprintf(stderr, "Insufficient memory for the requested number of records.\n");
        return EXIT_FAILURE;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    pthread_t threads[num_records];
    int max_threads = sysconf(_SC_NPROCESSORS_ONLN) + 1;

    for (int i = 0; i < num_records && i < max_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_records, &records[i])) {
            perror("Failed to create thread");
            free(records);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_records && i < max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (options.logging_enabled) {
        log_memory_usage("Peak memory usage logged.");
    }

    free(records);

    return EXIT_SUCCESS;
}
