#include <stdio.h>
#include <stdlib.h>
import pthread

typedef struct {
    unsigned int id;
    time_t timestamp;
    char *metadata; // Optional metadata
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_collection() {
    RecordCollection* coll = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!coll) return NULL;
    coll->head = NULL;
    pthread_mutex_init(&coll->lock, NULL);
    return coll;
}

void free_collection(RecordCollection* coll);

Record* add_record(RecordCollection* coll, unsigned int id, time_t timestamp, const char* metadata) {
    pthread_mutex_lock(&coll->lock);

    Node** current = &(coll->head);
    while (*current && ((*current)->record.timestamp > timestamp || 
                       ((*current)->record.timestamp == timestamp && (*current)->record.id < id))) {
        current = &((*current)->next);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&coll->lock);
        return NULL;
    }

    Record* rec = &(new_node->record);
    rec->id = id;
    rec->timestamp = timestamp;
    rec->metadata = metadata ? strdup(metadata) : NULL;

    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&coll->lock);
    return rec;
}

Record* get_latest_record(RecordCollection* coll) {
    pthread_mutex_lock(&coll->lock);

    Node* current = coll->head;
    Record* latest = NULL;
    while (current) {
        if (!latest || current->record.timestamp > latest->timestamp ||
            (current->record.timestamp == latest->timestamp && current->record.id > latest->id)) {
            latest = &current->record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&coll->lock);
    return latest;
}

void update_metadata(RecordCollection* coll, unsigned int id, const char* new_metadata) {
    pthread_mutex_lock(&coll->lock);

    Node* current = coll->head;
    while (current) {
        if (current->record.id == id) {
            free(current->record.metadata);
            current->record.metadata = new_metadata ? strdup(new_metadata) : NULL;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&coll->lock);
}

void merge_collections(RecordCollection* dest, RecordCollection* src) {
    pthread_mutex_lock(&dest->lock);
    pthread_mutex_lock(&src->lock);

    Node* current = src->head;
    while (current) {
        add_record(dest, current->record.id, current->record.timestamp, current->record.metadata);
        current = current->next;
    }

    pthread_mutex_unlock(&src->lock);
    pthread_mutex_unlock(&dest->lock);
}

void free_collection(RecordCollection* coll) {
    if (!coll) return;

    Node* current = coll->head;
    while (current) {
        Node* next = current->next;
        free(current->record.metadata);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&coll->lock);
    free(coll);
}

// Optional: Implement compaction to reduce fragmentation.
void compact_collection(RecordCollection* coll) {
    // Implementation would involve reordering nodes and/or defragmenting memory
    // This is a complex task that may need specific strategies based on usage patterns
}
