#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SNR 0
#define MIN_SNR -100
#define MAX_NF 70
#define MIN_NF 0

typedef struct {
    int ueIdentifier;
    float snr;
    float nf;
} NFAPI_RX_FRAME_T;

// Error codes
#define SUCCESS 0
#define MEMORY_ALLOCATION_FAILURE 1
#define INVALID_PARAMETERS 2

// Function to log invalid values
void log_invalid_value(const char* value_type, float value) {
    printf("Invalid %s value: %.2f\n", value_type, value);
}

// Memory pool for efficient allocation
typedef struct MemoryPool {
    size_t element_size;
    void** free_list;
    size_t pool_size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t pool_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->free_list = (void**)calloc(pool_size, sizeof(void*));
    if (!pool->free_list) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < pool_size - 1; ++i) {
        pool->free_list[i] = (char*)pool->free_list + (i + 1) * element_size;
    }
    pool->free_list[pool_size - 1] = NULL;
    pool->pool_size = pool_size;

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (!pool || !pool->free_list[0]) return NULL;
    void* element = pool->free_list[0];
    for (size_t i = 0; i < pool->pool_size - 1; ++i) {
        if (pool->free_list[i] == element) {
            pool->free_list[i] = pool->free_list[i + 1];
            break;
        }
    }
    return element;
}

void deallocate_to_pool(MemoryPool* pool, void* element) {
    if (!pool || !element) return;
    for (size_t i = 0; i < pool->pool_size - 1; ++i) {
        if (!pool->free_list[i]) {
            ((char**)pool)[i] = element;
            break;
        }
    }
}

// Thread-safe initialization of frames
int initializeNfaApiFrames(NFAPI_RX_FRAME_T* frames, size_t M, MemoryPool* pool) {
    pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    for (size_t i = 0; i < M; ++i) {
        NFAPI_RX_FRAME_T* frame = allocate_from_pool(pool);
        if (!frame) {
            pthread_mutex_destroy(&lock);
            return MEMORY_ALLOCATION_FAILURE;
        }

        pthread_mutex_lock(&lock);

        // Example values, replace with actual logic
        int ueIdentifier = i; // Unique identifier for each UE
        float snr = -50.0f;    // Example SNR value
        float nf = 10.0f;      // Example NF value

        if (snr < MIN_SNR || snr > MAX_SNR) {
            log_invalid_value("SNR", snr);
            pthread_mutex_unlock(&lock);
            deallocate_to_pool(pool, frame);
            continue;
        }

        if (nf < MIN_NF || nf > MAX_NF) {
            log_invalid_value("NF", nf);
            pthread_mutex_unlock(&lock);
            deallocate_to_pool(pool, frame);
            continue;
        }

        frame->ueIdentifier = ueIdentifier;
        frame->snr = snr;
        frame->nf = nf;

        frames[i] = *frame; // Store the configured frame

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return SUCCESS;
}

void update_frame_values(NFAPI_RX_FRAME_T* frames, size_t M) {
    for (size_t i = 0; i < M; ++i) {
        // Example revalidation logic
        if (frames[i].snr < MIN_SNR || frames[i].snr > MAX_SNR) {
            log_invalid_value("SNR", frames[i].snr);
            frames[i].snr = -50.0f; // Reset to a valid value
        }

        if (frames[i].nf < MIN_NF || frames[i].nf > MAX_NF) {
            log_invalid_value("NF", frames[i].nf);
            frames[i].nf = 10.0f; // Reset to a valid value
        }
    }
}

// Function to dynamically adjust the number of frames
void adjust_frame_count(NFAPI_RX_FRAME_T** frames, size_t* current_size, size_t new_size, MemoryPool* pool) {
    if (new_size < *current_size) {
        for (size_t i = new_size; i < *current_size; ++i) {
            deallocate_to_pool(pool, &(*frames)[i]);
        }
    } else if (new_size > *current_size) {
        *frames = realloc(*frames, new_size * sizeof(NFAPI_RX_FRAME_T));
        if (!*frames) return;
        for (size_t i = *current_size; i < new_size; ++i) {
            NFAPI_RX_FRAME_T* frame = allocate_from_pool(pool);
            if (!frame) {
                // Handle allocation failure
                break;
            }
            (*frames)[i] = *frame;
            deallocate_to_pool(pool, frame);
        }
    }
    *current_size = new_size;
}

int main() {
    size_t M = 1000; // Example size
    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_RX_FRAME_T), M);

    if (!pool) {
        fprintf(stderr, "Memory allocation failed\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(M * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        free(pool);
        fprintf(stderr, "Memory allocation failed\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    int result = initializeNfaApiFrames(frames, M, pool);
    if (result != SUCCESS) {
        free(frames);
        free(pool->free_list);
        free(pool);
        return result;
    }

    // Example usage
    update_frame_values(frames, M);

    adjust_frame_count(&frames, &M, 1200, pool); // Dynamically adjust frame count

    free(frames);
    free(pool->free_list);
    free(pool);

    return SUCCESS;
}
