import <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct PduSession {
    int session_id;
} PduSession;

typedef enum { CONNECTED, DISCONNECTED } ConnectionState;

typedef struct UeContext {
    int ue_id;
    PduSession *pdu_sessions;
    size_t pdu_session_count;
    ConnectionState status;
} UeContext;

typedef struct DynamicArray {
    UeContext **contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->contexts = (UeContext**)malloc(INITIAL_CAPACITY * sizeof(UeContext*));
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->contexts[i]->pdu_sessions);
        free(array->contexts[i]);
    }
    free(array->contexts);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_dynamic_array(DynamicArray *array);

UeContext* find_ue_context(DynamicArray *array, int ue_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->contexts[i]->ue_id == ue_id)
            return array->contexts[i];
    }
    return NULL;
}

void add_or_update_ue_context(DynamicArray *array, int ue_id, PduSession *sessions, size_t session_count, ConnectionState status) {
    pthread_mutex_lock(&array->lock);

    UeContext *context = find_ue_context(array, ue_id);
    if (context == NULL) {
        context = (UeContext*)malloc(sizeof(UeContext));
        context->ue_id = ue_id;
        array->contexts[array->size++] = context;
        resize_dynamic_array(array);
    }

    free(context->pdu_sessions);
    context->pdu_sessions = sessions ? malloc(session_count * sizeof(PduSession)) : NULL;
    if (sessions) {
        memcpy(context->pdu_sessions, sessions, session_count * sizeof(PduSession));
    }
    context->pdu_session_count = session_count;
    context->status = status;

    pthread_mutex_unlock(&array->lock);
}

void remove_ue_context(DynamicArray *array, int ue_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->contexts[i]->ue_id == ue_id) {
            free(array->contexts[i]->pdu_sessions);
            free(array->contexts[i]);
            memmove(&array->contexts[i], &array->contexts[i + 1], (--array->size - i) * sizeof(UeContext*));
            resize_dynamic_array(array);
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void resize_dynamic_array(DynamicArray *array) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UeContext **new_contexts = (UeContext**)realloc(array->contexts, new_capacity * sizeof(UeContext*));
        if (!new_contexts) return; // Handle reallocation failure
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }
}

void synchronize_with_database(DynamicArray *array);

typedef struct SyncThreadArgs {
    DynamicArray *array;
} SyncThreadArgs;

void* sync_thread(void *args) {
    SyncThreadArgs *sync_args = (SyncThreadArgs*)args;
    while (1) {
        synchronize_with_database(sync_args->array);
        sleep(10); // Synchronize every 10 seconds
    }
    return NULL;
}

void start_sync_thread(DynamicArray *array) {
    pthread_t sync_tid;
    SyncThreadArgs args = { .array = array };
    pthread_create(&sync_tid, NULL, sync_thread, &args);
}

void synchronize_with_database(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);

    // Simulated database interaction
    printf("Synchronizing with database...\n");
    // Handle network failures gracefully, retry logic can be implemented here

    pthread_mutex_unlock(&array->lock);
}

int main() {
    DynamicArray *ue_contexts = create_dynamic_array();

    PduSession sessions[] = {{1}, {2}};
    add_or_update_ue_context(ue_contexts, 101, sessions, 2, CONNECTED);

    start_sync_thread(ue_contexts);

    // Simulate operations
    remove_ue_context(ue_contexts, 101);
    sleep(20); // Wait for sync thread to run

    destroy_dynamic_array(ue_contexts);
    return 0;
}
