        perror("File opening failed");
        exit(EXIT_FAILURE);
    }

    char line[256];
    *size = 0;

    while (fgets(line, sizeof(line), file)) {
        long offset;
        int key;

        if (sscanf(line, "%ld,%d", &offset, &key) == 2 &&
            offset >= 0 && offset <= MAX_OFFSET && 
            key >= 0 && key < KEY_RANGE) {
            (*size)++;
        }
    }

    rewind(file);

    *offsets = malloc(*size * sizeof(long));
    *keys = malloc(*size * sizeof(int));

    size_t index = 0;
    while (fgets(line, sizeof(line), file)) {
        long offset;
        int key;

        if (sscanf(line, "%ld,%d", &offset, &key) == 2 &&
            offset >= 0 && offset <= MAX_OFFSET && 
            key >= 0 && key < KEY_RANGE) {
            (*offsets)[index] = offset;
            (*keys)[index++] = key;
        }
    }

    fclose(file);
}

void initialize_records(record **records, size_t count) {
    *records = malloc(count * sizeof(record));

    int available_values[KEY_RANGE];
    for (int i = 0; i < KEY_RANGE; i++) {
        available_values[i] = i;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; i++) {
        int value;

        do {
            value = rand() % KEY_RANGE;
        } while (!is_unique(available_values, KEY_RANGE, value));

        (*records)[i].value = available_values[value] = -1; // Mark as used
    }
}

void update_key_offset_pairs(const char *filename, long **offsets, int **keys, size_t *size) {
    load_csv(filename, offsets, keys, size);
}

int main() {
    const char *csv_filename = "data.csv";

    long *offsets;
    int *keys;
    size_t pair_count;

