```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

// Define MAC_HEADER structure (for illustration)
typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
} MAC_HEADER;

// Define Ethernet MAC Addresses
#define ETH_MAC_LENGTH 6

// Define VLAN Tag and Priority
typedef struct {
    uint16_t vlan_tag;
    uint8_t priority;
} VLAN_INFO;

// NICB Structure definition
typedef struct {
    MAC_HEADER mac_header;
    VLAN_INFO vlan_info;
    pthread_mutex_t lock; // For thread-safe access
} NICB;

// Function to generate a random MAC address (placeholder function)
void generate_random_mac_address(uint8_t *mac) {
    for (int i = 0; i < ETH_MAC_LENGTH - 1; ++i) {
        mac[i] = rand() % 256;
    }
    // Set the last byte's least significant bit to 1 to indicate locally administered address
    mac[ETH_MAC_LENGTH - 1] = (rand() % 254) | 0x02;
}

// Initialize an array of NICBs
int init_nicbs(NICB *nicbs, size_t count, uint16_t default_vlan_tag, uint8_t default_priority) {
    if (!nicbs || count == 0) return -1;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (size_t i = 0; i < count; ++i) {
        generate_random_mac_address(nicbs[i].mac_header.dest_mac);
        generate_random_mac_address(nicbs[i].mac_header.src_mac);

        nicbs[i].vlan_info.vlan_tag = default_vlan_tag;
        nicbs[i].vlan_info.priority = default_priority;

        pthread_mutex_init(&nicbs[i].lock, &attr); // Initialize mutex for thread safety
    }

    pthread_mutexattr_destroy(&attr);
    return 0; // Success
}

// Update a specific NICB's VLAN information
int update_nicb_vlan(NICB *nicb, uint16_t vlan_tag, uint8_t priority) {
    if (!nicb) return -1;

    pthread_mutex_lock(&nicb->lock); // Ensure thread-safe update
    nicb->vlan_info.vlan_tag = vlan_tag;
    nicb->vlan_info.priority = priority;
    pthread_mutex_unlock(&nicb->lock);

    return 0; // Success
}

// Example usage
int main() {
    size_t num_nicbs = 100;
    NICB *nicbs = malloc(num_nicbs * sizeof(NICB));

    if (!nicbs) {
        fprintf(stderr, "Failed to allocate memory for NICBs.\n");
        return -1;
    }

    int result = init_nicbs(nicbs, num_nicbs, 100, 5);
    if (result != 0) {
        fprintf(stderr, "Failed to initialize NICBs.\n");
        free(nicbs);
        return -1;
    }

    // Update a specific NICB
    update_nicb_vlan(&nicbs[10], 200, 3);

    // Free allocated resources
    for (size_t i = 0; i < num_nicbs; ++i) {
        pthread_mutex_destroy(&nicbs[i].lock);
    }
    free(nicbs);

    return 0;
}
```

### Explanation:
- **MAC_HEADER** and **VLAN_INFO**: Structures representing the MAC header and VLAN information.
- **NICB**: Structure containing a `MAC_HEADER`, `VLAN_INFO`, and a mutex for thread-safe operations.
- **generate_random_mac_address()**: Utility function to generate random, valid Ethernet MAC addresses.
- **init_nicbs()**: Initializes an array of NICBs with default VLAN settings and randomly generated MAC addresses. Mutexes are initialized for thread safety.
- **update_nicb_vlan()**: Allows updating the VLAN information of a specific NICB in a thread-safe manner using mutex locks.

This implementation focuses on performance, minimizing cache misses by keeping related data close together, and ensuring thread safety with recursive mutexes. Memory management is considered to prevent leaks or corruption in multi-threaded environments.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONTENT_SIZE 1024
#define INITIAL_ARRAY_SIZE 10

typedef struct {
    time_t creation_time;
    time_t modification_time;
    time_t access_time;
} Timestamps;

typedef struct FileMetadata {
    int file_id;
    char *content;
    size_t content_size;
    Timestamps timestamps;
    int ref_count;
    pthread_mutex_t lock;
} FileMetadata;

typedef struct {
    FileMetadata **files;
    size_t capacity;
    size_t count;
    size_t total_memory_usage;
    pthread_rwlock_t rwlock;
} FileManager;

FileManager* initialize_file_manager() {
    FileManager *manager = (FileManager*)malloc(sizeof(FileManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_ARRAY_SIZE;
    manager->count = 0;
    manager->total_memory_usage = 0;
    manager->files = (FileMetadata**)calloc(manager->capacity, sizeof(FileMetadata*));
    pthread_rwlock_init(&manager->rwlock, NULL);

    if (!manager->files) {
        free(manager);
        return NULL;
    }
    return manager;
}

void destroy_file_manager(FileManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        pthread_mutex_lock(&((manager->files[i])->lock));
        free((manager->files[i])->content);
        pthread_mutex_unlock(&((manager->files[i])->lock));
        free(manager->files[i]);
    }
    free(manager->files);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);
}

int add_file(FileManager *manager, int file_id, const char *data, size_t content_size) {
    if (!manager || content_size > MAX_CONTENT_SIZE) return -1;

    pthread_rwlock_wrlock(&manager->rwlock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        FileMetadata **new_files = (FileMetadata**)realloc(manager->files, new_capacity * sizeof(FileMetadata*));
        if (!new_files) {
            pthread_rwlock_unlock(&manager->rwlock);
            return -1;
        }
        memset(new_files + manager->count, 0, (new_capacity - manager->capacity) * sizeof(FileMetadata*));
        manager->files = new_files;
        manager->capacity = new_capacity;
    }

    FileMetadata *file = (FileMetadata*)malloc(sizeof(FileMetadata));
    if (!file) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }
    file->file_id = file_id;
    file->content_size = content_size;
    file->content = (char*)malloc(content_size);
    if (!file->content) {
        free(file);
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }
    memcpy(file->content, data, content_size);

    time_t now = time(NULL);
    file->timestamps.creation_time = now;
    file->timestamps.modification_time = now;
    file->timestamps.access_time = now;
    file->ref_count = 0;

    pthread_mutex_init(&file->lock, NULL);

    manager->files[manager->count++] = file;
    manager->total_memory_usage += sizeof(FileMetadata) + content_size;

    log_event("File created", file_id);

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

void access_file(FileManager *manager, int file_id) {
    if (!manager) return;

    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        FileMetadata *file = manager->files[i];
        pthread_mutex_lock(&file->lock);
        if (file->file_id == file_id) {
            time_t now = time(NULL);
            file->timestamps.access_time = now;
            pthread_mutex_unlock(&file->lock);

            log_event("File accessed", file_id);
            break;
        }
        pthread_mutex_unlock(&file->lock);
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void increment_ref_count(FileManager *manager, int file_id) {
    if (!manager) return;

    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        FileMetadata *file = manager->files[i];
        pthread_mutex_lock(&file->lock);
        if (file->file_id == file_id) {
            file->ref_count++;
            pthread_mutex_unlock(&file->lock);

            log_event("Reference count incremented", file_id);
            break;
        }
        pthread_mutex_unlock(&file->lock);
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void decrement_ref_count(FileManager *manager, int file_id) {
    if (!manager) return;

    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        FileMetadata *file = manager->files[i];
        pthread_mutex_lock(&file->lock);
        if (file->file_id == file_id && --file->ref_count == 0) {
            log_event("File deallocated", file_id);

            free(file->content);
            pthread_mutex_unlock(&file->lock);

            free(file);
            manager->files[i] = manager->files[--manager->count];
            manager->total_memory_usage -= sizeof(FileMetadata) + file->content_size;
        } else {
            pthread_mutex_unlock(&file->lock);
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void log_event(const char *event, int file_id) {
    time_t now = time(NULL);
    printf("[%s] Event: %s - File ID: %d\n", ctime(&now), event, file_id);
}

// Additional functions for serialization, deserialization, filtering,
// iteration and memory monitoring would be implemented here.

int main() {
    FileManager *manager = initialize_file_manager();
    if (!manager) return 1;

    add_file(manager, 1, "Hello, World!", 13);
    access_file(manager, 1);
    increment_ref_count(manager, 1);
    decrement_ref_count(manager, 1);

    destroy_file_manager(manager);
    return 0;
}
```

