#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>

#define ALIGNMENT 32
#define STRING_LENGTH 10

typedef struct Item {
    int key;
    char string[STRING_LENGTH];
    struct Item *next;
} Item;

typedef struct Node {
    double value;
    Item *items_head;
} Node;

typedef struct {
    Node **nodes;
    size_t capacity;
    pthread_mutex_t lock;
} NodeList;

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

double calculate_cube_root(int number) {
    return cbrt(number);
}

int generate_random_int(int min, int max) {
    if (min > max) return 0;
    return rand() % (max - min + 1) + min;
}

void initialize_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';
}

Node* create_node(double value) {
    Node *node = aligned_malloc(sizeof(Node), ALIGNMENT);
    if (!node) return NULL;

    node->value = value;
    node->items_head = NULL;
    return node;
}

Item* create_item(int key, const char *str) {
    Item *item = aligned_malloc(sizeof(Item), ALIGNMENT);
    if (!item) return NULL;

    item->key = key;
    strncpy(item->string, str, STRING_LENGTH - 1);
    item->next = NULL;
    return item;
}

void free_item_list(Item *head) {
    while (head) {
        Item *temp = head;
        head = head->next;
        aligned_free(temp);
    }
}

NodeList* create_node_list(size_t initial_capacity) {
    NodeList *list = aligned_malloc(sizeof(NodeList), ALIGNMENT);
    if (!list) return NULL;

    list->nodes = aligned_malloc(initial_capacity * sizeof(Node*), ALIGNMENT);
    if (!list->nodes) {
        aligned_free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        list->nodes[i] = NULL;
    }
    return list;
}

int resize_node_list(NodeList *list, size_t new_capacity) {
    Node **new_nodes = aligned_malloc(new_capacity * sizeof(Node*), ALIGNMENT);
    if (!new_nodes) return 0;

    for (size_t i = 0; i < new_capacity; ++i) {
        new_nodes[i] = NULL;
    }

    pthread_mutex_lock(&list->lock);
    size_t min_capacity = list->capacity < new_capacity ? list->capacity : new_capacity;

    for (size_t i = 0; i < min_capacity; ++i) {
        new_nodes[i] = list->nodes[i];
    }

    aligned_free(list->nodes);
    list->nodes = new_nodes;
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->lock);

    return 1;
}

int add_node(NodeList *list, double value) {
    if (!list || !value) return -1;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->capacity; ++i) {
        if (!list->nodes[i]) {
            Node *node = create_node(value);
            if (!node) {
                pthread_mutex_unlock(&list->lock);
                return -1;
            }
            list->nodes[i] = node;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }

    if (!resize_node_list(list, list->capacity * 2)) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    add_node(list, value); // Retry adding the node
}

int add_item_to_node(NodeList *list, size_t node_index, int key, const char *str) {
    if (!list || !list->nodes[node_index]) return -1;

    Item **item_ptr = &(list->nodes[node_index]->items_head);
    while (*item_ptr) {
        item_ptr = &((*item_ptr)->next);
    }

    Item *new_item = create_item(key, str);
    if (!new_item) return -1;

    *item_ptr = new_item;
    return 0;
}

void free_node_list(NodeList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->nodes[i]) {
            free_item_list(list->nodes[i]->items_head);
            aligned_free(list->nodes[i]);
        }
    }

    aligned_free(list->nodes);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    aligned_free(list);
}

void populate_node_list(NodeList *list, size_t num_nodes, size_t items_per_node, int rand_range_min, int rand_range_max) {
    if (!list || !num_nodes || !items_per_node) return;

    for (size_t i = 0; i < num_nodes; ++i) {
        double value = calculate_cube_root(generate_random_int(rand_range_min, rand_range_max));
        add_node(list, value);

        char str[STRING_LENGTH];
        initialize_string(str, STRING_LENGTH - 1);

        for (size_t j = 0; j < items_per_node; ++j) {
            int key = generate_random_int(0, 10000);
            add_item_to_node(list, i, key, str);
        }
    }
}

int main() {
    srand(time(NULL));

    size_t num_nodes = 10;
    size_t items_per_node = 5;
    int rand_range_min = 1;
    int rand_range_max = 100;

    NodeList *list = create_node_list(5);
    if (!list) {
        fprintf(stderr, "Failed to initialize node list.\n");
        return EXIT_FAILURE;
    }

    populate_node_list(list, num_nodes, items_per_node, rand_range_min, rand_range_max);

    // Free resources
    free_node_list(list);

    return 0;
}
