```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define ALIGNMENT 16
#define TOTAL_CAPACITY 10000
#define MONITOR_INTERVAL 60 // seconds

typedef struct {
    int value;
    long *offsets;
    int *keys;
    unsigned int ref_count;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t lock;
} ResourceManager;

unsigned long align_up(unsigned long addr, unsigned long alignment) {
    return (addr + alignment - 1) & ~(alignment - 1);
}

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

ResourceManager* ResourceManagerInit() {
    ResourceManager *manager = aligned_alloc(ALIGNMENT, sizeof(ResourceManager));
    if (!manager) {
        perror("Failed to allocate ResourceManager");
        return NULL;
    }

    manager->records = (Record **)aligned_alloc(ALIGNMENT, MAX_ELEMENTS * sizeof(Record *));
    if (!manager->records) {
        free(manager);
        perror("Failed to allocate records array");
        return NULL;
    }
    memset(manager->records, 0, MAX_ELEMENTS * sizeof(Record *));
    manager->capacity = MAX_ELEMENTS;

    pthread_mutex_init(&manager->lock, NULL);

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < TOTAL_CAPACITY; ++i) {
        if (i % manager->capacity == 0 && i > 0) {
            Record **new_records = realloc(manager->records,
                                           (manager->capacity + CHUNK_SIZE) * sizeof(Record *));
            if (!new_records) break;
            memset(new_records + manager->capacity, 0, CHUNK_SIZE * sizeof(Record *));
            manager->records = new_records;
            manager->capacity += CHUNK_SIZE;
        }

        Record *record = aligned_alloc(ALIGNMENT, sizeof(Record));
        if (!record) continue;

        record->value = rand() % 100; // Random value in specified range
        record->offsets = aligned_alloc(ALIGNMENT, MAX_ELEMENTS * sizeof(long));
        record->keys = aligned_alloc(ALIGNMENT, MAX_ELEMENTS * sizeof(int));
        record->ref_count = 0;

        if (!record->offsets || !record->keys) {
            free(record->offsets);
            free(record->keys);
            free(record);
            continue;
        }

        pthread_mutex_lock(&manager->lock);
        manager->records[i % manager->capacity] = record;
        for (size_t j = 0; j < MAX_ELEMENTS; ++j) {
            record->keys[j] = rand() % 100000 + i * 1000; // Ensure unique keys
        }
        pthread_mutex_unlock(&manager->lock);
    }

    // Monitoring thread
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, []() -> void* {
        while (1) {
            sleep(MONITOR_INTERVAL);
            ResourceManager *mgr = /* retrieve resource manager */;
            pthread_mutex_lock(&mgr->lock);
            printf("Current records: %zu\n", mgr->capacity);
            pthread_mutex_unlock(&mgr->lock);
        }
        return NULL;
    }, NULL)) {
        perror("Failed to create monitoring thread");
    }

    return manager;
}

void ResourceManagerDestroy(ResourceManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->capacity; ++i) {
        Record *record = manager->records[i];
        if (record) {
            free(record->offsets);
            free(record->keys);
            free(record);
        }
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
