#define MAX_MEMORY_THRESHOLD 1024 * 1024 // Example threshold: 1MB
#define MAC_ADDR_LENGTH 6
#define VLAN_TAG_RANGE 4096
#define IP_HEADER_CHECKSUM_CONFIG 1
#define NUM_RECS_PER_NICB 10
#define MAX_STRING_LENGTH 255

typedef struct {
    uint8_t mac_addr[MAC_ADDR_LENGTH];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    uint16_t vlan_tag;
} NICB_RECORD;

typedef struct {
    NICB_RECORD records[NUM_RECS_PER_NICB];
    int num_records;
} NICB;

typedef struct {
    char *string_data;
    int value;
} RECORD;

typedef struct MemoryPoolNode {
    void *memory_block;
    size_t block_size;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *free_list_head;
    pthread_mutex_t lock;
    size_t total_allocated_memory;
} MemoryPool;

// Function Prototypes
void initializeMemoryPool(MemoryPool *pool, size_t initial_blocks, size_t block_size);
void* memoryAllocate(MemoryPool *pool, size_t size);
void memoryDeallocate(MemoryPool *pool, void *memory_block, size_t size);
void freeMemoryPool(MemoryPool *pool);

void populateNICBArray(NICB **nicb_array, size_t num_nicbs, int value_range_min, int value_range_max, int max_string_length, unsigned short vlan_priority_config, int ip_checksum_config);
void initializeMACAddress(uint8_t mac_addr[MAC_ADDR_LENGTH]);
uint16_t generateRandomVLANTag();
int randomInRange(int min, int max);

// Function Implementations

void initializeMemoryPool(MemoryPool *pool, size_t initial_blocks, size_t block_size) {
    pool->free_list_head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->total_allocated_memory = 0;

    for (size_t i = 0; i < initial_blocks; ++i) {
        MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
        node->memory_block = malloc(block_size);
        node->block_size = block_size;
        node->next = pool->free_list_head;
        pool->free_list_head = node;
        pool->total_allocated_memory += block_size;
    }
}

void* memoryAllocate(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->total_allocated_memory + size > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory allocation limit exceeded.\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    MemoryPoolNode **curr = &(pool->free_list_head);
    while (*curr != NULL) {
        if ((*curr)->block_size >= size) {
            MemoryPoolNode *node = *curr;
            *curr = node->next;
            pool->total_allocated_memory -= node->block_size;
            pthread_mutex_unlock(&pool->lock);
            return node->memory_block;
        }
        curr = &((*curr)->next);
    }

    pthread_mutex_unlock(&pool->lock);
    MemoryPoolNode *new_node = malloc(sizeof(MemoryPoolNode));
    new_node->memory_block = malloc(size);
    new_node->block_size = size;
    pool->total_allocated_memory += size;

    return new_node->memory_block;
}

void memoryDeallocate(MemoryPool *pool, void *memory_block, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
    node->memory_block = memory_block;
    node->block_size = size;
    node->next = pool->free_list_head;
    pool->free_list_head = node;
    pool->total_allocated_memory -= size;

    pthread_mutex_unlock(&pool->lock);
}

void freeMemoryPool(MemoryPool *pool) {
    MemoryPoolNode *curr = pool->free_list_head;
    while (curr != NULL) {
        MemoryPoolNode *next_node = curr->next;
        free(curr->memory_block);
        free(curr);
        curr = next_node;
    }
    pthread_mutex_destroy(&pool->lock);
}

void populateNICBArray(NICB **nicb_array, size_t num_nicbs, int value_range_min, int value_range_max, int max_string_length, unsigned short vlan_priority_config, int ip_checksum_config) {
    MemoryPool pool;
    initializeMemoryPool(&pool, 1000, sizeof(NICB));

    *nicb_array = malloc(num_nicbs * sizeof(NICB));
    if (!*nicb_array) {
        fprintf(stderr, "Failed to allocate NICB array.\n");
        return;
    }

    for (size_t i = 0; i < num_nicbs; ++i) {
        (*nicb_array)[i].num_records = NUM_RECS_PER_NICB;

        for (int j = 0; j < NUM_RECS_PER_NICB; ++j) {
            RECORD *record = memoryAllocate(&pool, sizeof(RECORD));
            if (!record) {
                fprintf(stderr, "Failed to allocate record.\n");
                continue;
            }

            initializeMACAddress((*nicb_array)[i].records[j].mac_header.mac_addr);
            (*nicb_array)[i].records[j].vlan_tag = generateRandomVLANTag();

            record->value = randomInRange(value_range_min, value_range_max);
            record->string_data = malloc(max_string_length + 1);
            if (record->string_data) {
                snprintf(record->string_data, max_string_length + 1, "Data_%d", j);
            }
        }
    }

    freeMemoryPool(&pool);
}

void initializeMACAddress(uint8_t mac_addr[MAC_ADDR_LENGTH]) {
    for (int i = 0; i < MAC_ADDR_LENGTH; ++i) {
        mac_addr[i] = rand() % 256;
    }
}

uint16_t generateRandomVLANTag() {
    return (rand() % VLAN_TAG_RANGE) | (1 << 13); // Set priority bit
}

int randomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}
