#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Function to initialize the complex data structure
entry_t** init_entries(size_t num_entries) {
    entry_t **entries = (entry_t**) aligned_alloc(ALIGNMENT, sizeof(entry_t*) * num_entries);

    for (size_t i = 0; i < num_entries; ++i) {
        entries[i] = (entry_t*) aligned_alloc(ALIGNMENT, sizeof(entry_t));
        entries[i]->value = 0.0f;
        entries[i]->root = NULL;

