}

// Function to safely free the complex data structure
void free_entries(entry_t **entries, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        // Free binary tree and hash table
        // Implement a post-order traversal to safely delete nodes in the tree
        void free_tree(tree_node_t *node) {
            if (!node) return;
            free_tree(node->left);
            free_tree(node->right);
            aligned_free(node);  // Assuming each node was allocated with aligned_alloc
        }

        free_tree(entries[i]->root);

        for (size_t j = 0; j < MAX_ELEMENTS_PER_ENTRY; ++j) {
            hash_table_entry_t *entry = entries[i]->table[j];
            while (entry) {
                hash_table_entry_t *next = entry->next;
                aligned_free(entry->key);
                aligned_free(entry);  // Assuming each entry was allocated with aligned_alloc
                entry = next;
            }
        }

        aligned_free(entries[i]->table);
        aligned_free(entries[i]);
    }
    aligned_free(entries);
