#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

// Enum for media types
typedef enum {
    VIDEO,
    AUDIO,
    IMAGE
} MediaType;

// Structure to hold property data
typedef struct Property {
    char *name;
    char *value;
    struct Property *next;
} Property;

// Structure to hold container data
typedef struct Container {
    MediaType type;
    float duration;
    uint64_t value; // Derived from hashing function
    Property *properties;
    struct Container *next;
} Container;

// Alignment boundary
#define ALIGNMENT 128

// Function prototypes for alignment and memory management
void* aligned_alloc(size_t size, size_t align);
void free_aligned(void *ptr);

// Hashing function (example)
uint64_t hash_type_duration(MediaType type, float duration) {
    // Simple hash combining type and duration
    return ((uint64_t)type << 32) | (*(uint64_t*)&duration & 0xFFFFFFFF);
}

// Function to create a new property with random value
Property* create_property(const char *name, int value_length) {
    Property *prop = (Property *)aligned_alloc(sizeof(Property), ALIGNMENT);
    prop->name = strdup(name); // Allocate and copy name

    prop->value = (char*)aligned_alloc(value_length + 1, ALIGNMENT);
    for (int i = 0; i < value_length; ++i) {
        prop->value[i] = 'a' + rand() % 26; // Random lowercase letter
    }
    prop->value[value_length] = '\0';

    prop->next = NULL;
    return prop;
}

// Function to create a new container
Container* create_container(MediaType type, float duration) {
    Container *cont = (Container *)aligned_alloc(sizeof(Container), ALIGNMENT);
    cont->type = type;
    cont->duration = duration;
    cont->value = hash_type_duration(type, duration);

    cont->properties = NULL; // Initialize properties linked list
    cont->next = NULL;

    return cont;
}

// Function to add a property to a container
void add_property_to_container(Container *container, const char *name, int value_length) {
    Property *prop = create_property(name, value_length);
    prop->next = container->properties;
    container->properties = prop;
}

// Initialize and manage media items
Container* initialize_media_item() {
    Container *head = create_container(VIDEO, 120.0f); // Example initialization

    add_property_to_container(head, "Resolution", 10);
    add_property_to_container(head, "Codec", 7);

    return head;
}

// Function to free aligned memory
void free_aligned(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}

