// Function to manage dynamic memory allocation for records
typedef struct Record {
    short value;
    char identifier;
    float *dynamic_float;
} Record;

Record* allocate_records(int num_records) {
    Record *records = (Record*)aligned_alloc(sizeof(Record) * num_records, ALIGNMENT);

    for (int i = 0; i < num_records; ++i) {
        records[i].value = (short)i;
        records[i].identifier = 'A' + (i % 26); // Example identifier
        records[i].dynamic_float = (float*)aligned_alloc(sizeof(float), ALIGNMENT);
        *records[i].dynamic_float = i * 1.5f; // Example value
    }

    return records;
