#define ALIGNMENT 64

typedef struct Item {
    int key;
    char str[16];
    time_t timestamp;
    struct Item* next;
} Item;

typedef struct TreeNode {
    double value;
    Item* items_head;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) return NULL;
#else
    if ((intptr_t)ptr % alignment != 0) {
        void* p = malloc(size + alignment);
        if (!p) return NULL;
        ptr = (void*)(((uintptr_t)p + alignment - 1) & ~(alignment - 1));
    }
#endif
    return ptr;
}

bool is_aligned(void* ptr, size_t alignment) {
    return (intptr_t)ptr % alignment == 0;
}

TreeNode* create_node(double value) {
    TreeNode* node = aligned_alloc(ALIGNMENT, sizeof(TreeNode));
    if (!node || !is_aligned(node, ALIGNMENT)) {
        fprintf(stderr, "Memory allocation error or misalignment\n");
        free(node);
        return NULL;
    }
    node->value = value;
    node->items_head = NULL;
    node->left = NULL;
    node->right = NULL;
    return node;
}

Item* create_item(int key) {
    Item* item = aligned_alloc(ALIGNMENT, sizeof(Item));
    if (!item || !is_aligned(item, ALIGNMENT)) {
        fprintf(stderr, "Memory allocation error or misalignment\n");
        free(item);
        return NULL;
    }
    item->key = key;
    srand(time(NULL) + key);
    for (int i = 0; i < sizeof(item->str); ++i)
        item->str[i] = (rand() % 2 == 0 ? 'A' + rand() % 26 : 'a' + rand() % 26);
    item->timestamp = time(NULL);
    item->next = NULL;
    return item;
}

void insert_item(TreeNode* node, Item* item) {
    if (!node || !item) return;
    item->next = node->items_head;
    node->items_head = item;
}

void delete_node(TreeNode** root) {
    if (root && *root) {
        delete_node(&((*root)->left));
        delete_node(&((*root)->right));
        Item* current = (*root)->items_head;
        while (current) {
            Item* next = current->next;
            free(current);
            current = next;
        }
        free(*root);
        *root = NULL;
    }
}

void traverse_inorder(TreeNode* node, void (*callback)(TreeNode*)) {
    if (!node) return;
    traverse_inorder(node->left, callback);
    callback(node);
    traverse_inorder(node->right, callback);
}

