        completedThreads++;
        if (completedThreads == 1) {
            pthread_cond_broadcast(&condVar); // Only the first thread will broadcast.
        }
        pthread_mutex_unlock(&mutex);

        // Perform operations on local data here...

        return NULL;
    }

    size_t threadsPerWorker = count / 4; // Example: divide work among 4 threads
    if (threadsPerWorker == 0) threadsPerWorker = 1;

