    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (long i = range_min; i <= range_max && head == NULL;) {
        pthread_mutex_lock(&lock);
        if (!id_set[i % (range_max - range_min + 1)]) { // Simple hash check
            id_set[i % (range_max - range_min + 1)] = true;
            Element *new_node = (Element*) malloc(sizeof(Element));
            new_node->id = i++;
            new_node->next = NULL;
            *tail = new_node;
            tail = &new_node->next;
        }
        pthread_mutex_unlock(&lock);
    }

    // Validate linked list
    Element *current = head;
    while (current) {
        if (current->id < range_min || current->id > range_max || id_set[current->id % (range_max - range_min + 1)]) {
            fprintf(stderr, "Validation failed for node with ID: %ld\n", current->id);
            // Cleanup
            free(doubles);
            free(chars);
            while (head) {
                Element *temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_destroy(&lock);
            return;
        }
        current = current->next;
    }

    // Call the Java method through JNI or similar
    asyncDataStream(doubles, chars, head);

    // Cleanup
    free(doubles);
    free(chars);
    while (head) {
        Element *temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_destroy(&lock);
}
