import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class AsyncDataStreamer {
    private static final int PORT = 8080;
    private static int maxConcurrentRequests;

    public static void asyncDataStream(double[] doubles, byte[] chars, Element head) {
        maxConcurrentRequests = (int)doubles[0]; // Using first double for demonstration

        try {
            Selector selector = Selector.open();
            ServerSocketChannel serverChannel = ServerSocketChannel.open();
            serverChannel.bind(new InetSocketAddress(PORT));
            serverChannel.configureBlocking(false);
            serverChannel.register(selector, SelectionKey.OP_ACCEPT);

            while (true) { // Replace with an appropriate condition to stop the server
                selector.select();

                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> iter = selectedKeys.iterator();

                while (iter.hasNext()) {
                    SelectionKey key = iter.next();

                    if (!key.isValid()) {
                        continue;
                    }

                    if (key.isAcceptable()) {
                        SocketChannel clientChannel = serverChannel.accept();
                        if (clientChannel != null) {
                            clientChannel.configureBlocking(false);
                            clientChannel.register(selector, SelectionKey.OP_READ);
                        }
                    } else if (key.isReadable()) {
                        handleRead(key);
                    }

                    iter.remove();
                }
            }

        } catch (IOException e) {
            System.err.println("I/O Exception: " + e.getMessage());
            // Implement retry logic or backoff strategy here
        }
    }

    private static void handleRead(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(256);
        int numRead;

        try {
            while ((numRead = client.read(buffer)) > 0) {
                buffer.flip();
                // Process data from buffer
                buffer.clear(); 
            }

            if (numRead == -1) {
                key.cancel();
                client.close();
            }
        } catch (IOException e) {
            key.cancel();
            try {
                client.close();
            } catch (IOException ex) {
                System.err.println("Error closing channel: " + ex.getMessage());
            }
            // Implement retry logic or backoff strategy here
        }
    }

    public static void main(String[] args) {
        // Example initialization for testing
        double[] doubles = {10}; // Just a placeholder value
        byte[] chars = new byte[50]; // Placeholder
        Element head = null; // Create your linked list here

        asyncDataStream(doubles, chars, head);
    }

    static class Element {
        long id;
        Element next;

        public Element(long id) {
            this.id = id;
            this.next = null;
        }
    }
}
