['Below is a C++ implementation for a basic simulation of a network load balancer system using weighted round-robin algorithm with retry and cooldown mechanisms:

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>

// Represents a backend server node
class ServerNode {
public:
    std::string id;
    int weight;
    int activeConnections;

    ServerNode(const std::string& nodeId, int w) : id(nodeId), weight(w), activeConnections(0) {}

    bool isHealthy() const {
        // Simulate health check (in reality, this would involve network checks)
        return rand() % 100 < 90; // 90% chance of being healthy
    }

    void handleRequest() {
        if (isHealthy()) {
            activeConnections++;
            std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 500 + 100)); // Simulate handling time
            activeConnections--;
        } else {
            throw std::runtime_error("Server not healthy");
        }
    }
};

class LoadBalancer {
private:
    std::vector<std::shared_ptr<ServerNode>> servers;
    int currentWeightIndex = -1;
    int currentWeight = 0;
    int maxWeight = 0; // Maximum weight in the pool
    std::mutex mtx;

public:
    void addServer(const std::string& id, int weight) {
        servers.emplace_back(std::make_shared<ServerNode>(id, weight));
        if (weight > maxWeight) {
            maxWeight = weight;
        }
    }

    std::shared_ptr<ServerNode> getNextServer() {
        while (true) {
            std::lock_guard<std::mutex> lock(mtx);
            currentWeightIndex = (currentWeightIndex + 1) % servers.size();
            if (currentWeightIndex == 0) {
                currentWeight = currentWeight > 0 ? currentWeight - 1 : maxWeight;
            }

            auto& server = servers[currentWeightIndex];
            if (server->weight >= currentWeight && server->activeConnections < 10) { // Assume each server can handle up to 10 concurrent requests
                return server;
            }
        }
    }

    void distributeRequest() {
        try {
            for (int attempt = 0; attempt < 3; ++attempt) { // Retry mechanism
                auto server = getNextServer();
                server->handleRequest();
                std::cout << "Request handled by Server: " << server->id << "\n";
                return;
            }
            std::cerr << "Failed to handle request after retries\n";
        } catch (const std::exception& e) {
            std::cerr << "Error handling request: " << e.what() << "\n";
        }
    }

    void performHealthCheck() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(30));

            for (auto& server : servers) {
                if (!server->isHealthy()) {
                    std::cerr << "Server: " << server->id << " is unhealthy\n";
                } else {
                    std::cout << "Server: " << server->id << " is healthy\n";
                }
            }
        }
    }

    void run() {
        std::thread healthCheckThread(&LoadBalancer::performHealthCheck, this);

        for (int i = 0; i < 100; ++i) { // Simulate incoming requests
            distributeRequest();
        }

        if (healthCheckThread.joinable()) {
            healthCheckThread.detach(); // Detach the thread to simulate continuous operation
        }
    }
};

// Example usage
int main() {
    srand(time(0));

    LoadBalancer balancer;
    balancer.addServer("Server1", 5);
    balancer.addServer("Server2", 3);
    balancer.addServer("Server3", 2);

    balancer.run();

    std::this_thread::sleep_for(std::chrono::seconds(60)); // Let the system run for a minute to see health checks
    return 0;
}
```

### Explanation:
- **ServerNode**: Represents each backend server with attributes like ID, weight, and active connections.
- **LoadBalancer**: Manages the pool of servers using weighted round-robin for request distribution. It includes retry logic and periodic health checks.
- **Weighted Round-Robin Algorithm**: Distributes requests based on server weights.
- **Retry Mechanism**: Attempts to handle requests up to three times in case of failures.
- **Health Check**: Runs every 30 seconds to ensure servers are healthy.
- **Logging**: Outputs detailed information about request handling and health checks.

This implementation is a simplified simulation and can be extended for more complex scenarios.']

