    float temperature;
    float humidity;
    float wind_speed;
} SensorReading;

typedef struct {
    SensorReading *readings;
    size_t count;
    float wind_speed_sum;
    pthread_mutex_t lock;
} Dataset;

void initialize_dataset(Dataset *dataset) {
    dataset->count = 0;
    dataset->wind_speed_sum = 0.0f;
    pthread_mutex_init(&dataset->lock, NULL);
}

float generate_random_temperature() {
    return ((float)rand() / RAND_MAX) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;
}

char determine_status_flag(float temperature, int index) {
    if (temperature > 30.0 && index % 2 == 0) {
        return 'H'; // Hot
    } else if (temperature < 10.0 && index % 2 != 0) {
        return 'C'; // Cold
    }
    return 'N'; // Normal
}

void add_reading(Dataset *dataset, float humidity, float wind_speed) {
    pthread_mutex_lock(&dataset->lock);

    size_t new_count = dataset->count + 1;
    SensorReading *new_readings = realloc(dataset->readings, new_count * sizeof(SensorReading));

    if (new_readings == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&dataset->lock);
        return;
    }

    float temperature = generate_random_temperature();
    char status_flag = determine_status_flag(temperature, new_count - 1);

    new_readings[new_count - 1] = (SensorReading){
        .index = new_count - 1,
        .status_flag = status_flag,
        .temperature = temperature,
        .humidity = humidity,
        .wind_speed = wind_speed
    };

    dataset->wind_speed_sum += wind_speed;
    dataset->readings = new_readings;
    dataset->count = new_count;

    pthread_mutex_unlock(&dataset->lock);
}

float get_average_wind_speed(Dataset *dataset) {
    pthread_mutex_lock(&dataset->lock);

    float average = (dataset->count == 0) ? 0.0f : dataset->wind_speed_sum / dataset->count;

    pthread_mutex_unlock(&dataset->lock);
    return average;
}

void cleanup_old_records(Dataset *dataset, size_t max_size) {
    pthread_mutex_lock(&dataset->lock);

    if (dataset->count > max_size) {
        size_t remove_count = dataset->count - max_size;
        SensorReading *trimmed_readings = realloc(dataset->readings, max_size * sizeof(SensorReading));

        if (trimmed_readings == NULL) {
            printf("Memory reallocation failed during cleanup\n");
            pthread_mutex_unlock(&dataset->lock);
            return;
        }

        float wind_speed_sum = 0.0f;
        for (size_t i = 0; i < max_size; ++i) {
            wind_speed_sum += trimmed_readings[i].wind_speed;
        }

        free(dataset->readings);
        dataset->readings = trimmed_readings;
        dataset->count = max_size;
        dataset->wind_speed_sum = wind_speed_sum;
    }

    pthread_mutex_unlock(&dataset->lock);
}

void release_resources(Dataset *dataset) {
    pthread_mutex_lock(&dataset->lock);

    free(dataset->readings);
    dataset->readings = NULL;
    dataset->count = 0;

    pthread_mutex_destroy(&dataset->lock);
}

int main() {
    srand(time(NULL));

    Dataset dataset;
    initialize_dataset(&dataset);

    // Simulating adding readings
    for (int i = 0; i < 100; ++i) {
        add_reading(&dataset, (float)rand()/RAND_MAX * 100.0f, (float)rand()/RAND_MAX * 20.0f);
    }

    printf("Average Wind Speed: %.2f\n", get_average_wind_speed(&dataset));

    // Clean up old records to keep dataset manageable
    cleanup_old_records(&dataset, 50);

    release_resources(&dataset);

    return 0;
}
```

### Key Points:
- **Thread Safety:** Uses a mutex (`pthread_mutex_t`) to ensure safe access and modification of shared data across multiple threads.
- **Memory Management:** Dynamically allocates memory for readings using `realloc` and ensures proper cleanup with `free`.
- **Incremental Average Calculation:** Maintains a running sum for calculating average wind speed efficiently.
- **Cleanup Mechanism:** Periodically trims old records to control dataset size, reallocating only necessary memory.']

