#define MAX_RECORDS 1000
#define MAX_REFERENCES 10000
#define BUFFER_SIZE 1024

typedef struct {
    int value;
    char status_flag;
    double measurement;
} record_t;

typedef struct {
    size_t ref_count;
    pthread_mutex_t lock;
    record_t *data;
} managed_record_t;

typedef struct {
    long *offsets;
    int *keys;
    double *measurements;
    managed_record_t *records;
    double sum_measurements;
    char log_buffer[BUFFER_SIZE];
    int log_index;
    size_t alignment;
    pthread_mutex_t data_lock;
} dataset_t;

void log_message(const char *message) {
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_once(&once, (void (*)(void))pthread_mutex_init);

    pthread_mutex_lock(&log_mutex);
    int len = strlen(message);
    for (int i = 0; i < len; ++i) {
        log_buffer[log_index] = message[i];
        log_index = (log_index + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&log_mutex);
}

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0)
        ptr = NULL;
    return ptr;
}

int random_within_range(int min, int max) {
    static pthread_once_t once = PTHREAD_ONCE_INIT;

    pthread_once(&once, []() { srand(time(NULL)); });

    return rand() % (max - min + 1) + min;
}

char determine_status_flag(int value, size_t index) {
    return (value % 2 == 0 && index % 3 == 0) ? 'A' : 'B';
}

void initialize_record(managed_record_t *managed_record, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&managed_record->lock);

    managed_record->data = aligned_alloc(64, sizeof(record_t));
    if (!managed_record->data) {
        log_message("Failed to allocate record data.\n");
        pthread_mutex_unlock(&managed_record->lock);
        return;
    }

    int value = random_within_range(value_range_min, value_range_max);
    double measurement = sqrt(random_within_range(1, 100));

    managed_record->data->value = value;
    managed_record->data->status_flag = determine_status_flag(value, rand());
    managed_record->data->measurement = measurement;

    managed_record->ref_count = 1;

    pthread_mutex_unlock(&managed_record->lock);
}

void deallocate_record(managed_record_t *managed_record) {
    if (!managed_record || !managed_record->data)
        return;

    pthread_mutex_lock(&managed_record->lock);

    if (--managed_record->ref_count == 0) {
        free(managed_record->data);
        managed_record->data = NULL;
    }

    pthread_mutex_unlock(&managed_record->lock);
}

double manage_data_structure(size_t num_records, int value_range_min, int value_range_max) {
    dataset_t ds;
    memset(&ds, 0, sizeof(dataset_t));

    ds.alignment = 64;
    pthread_mutex_init(&ds.data_lock, NULL);

    size_t total_size = num_records * sizeof(managed_record_t);
    managed_record_t *records = aligned_alloc(ds.alignment, total_size);
    if (!records) {
        log_message("Failed to allocate records.\n");
        return -1.0;
    }

    ds.records = records;

    for (size_t i = 0; i < num_records; ++i) {
        initialize_record(&ds.records[i], value_range_min, value_range_max);

        if (ds.records[i].data) {
            pthread_mutex_lock(&ds.data_lock);
            ds.sum_measurements += ds.records[i].data->measurement;
            pthread_mutex_unlock(&ds.data_lock);
        }
    }

    // Simulate integration with external data source
    log_message("Integrating with external data source...\n");

    // Example of handling resource deallocation
    for (size_t i = 0; i < num_records; ++i) {
        deallocate_record(&ds.records[i]);
    }

    free(records);
    pthread_mutex_destroy(&ds.data_lock);

    return ds.sum_measurements;
}

int main() {
    double sum = manage_data_structure(MAX_RECORDS, 10, 100);
    printf("Sum of measurements: %f\n", sum);
    return 0;
}
