            if (!work_item) {
                // Log error: memory allocation failed
                free_tasks(tasks, i);
                return;
            }

            work_item->id = rand() % 1000 + 1; // Unique identifier generation logic needed

            size_t name_length = rand() % STRING_MAX_LENGTH;
            work_item->name = aligned_alloc(ALIGNMENT, sizeof(char) * (name_length + 1));
