            }

            task->work_items[j] = work_item;
        }

        tasks[i] = task;
    }
}

// Free allocated tasks
void free_tasks(Task **tasks, size_t num_tasks) {
    for (size_t i = 0; i < num_tasks; ++i) {
        Task *task = tasks[i];
        if (!task) continue;

        for (size_t j = 0; j < MAX_WORK_ITEMS_PER_TASK; ++j) {
            WorkItem *work_item = task->work_items[j];
            if (!work_item) break;

            free(work_item->name);
            free(work_item);
        }

        aligned_free(task);
    }
}

