// Assuming imagelib is included here
// #include "imagelib.h"

#define MEMORY_ALIGNMENT 64

typedef struct {
    uint8_t exposure;
    uint32_t capture_time;
} Metadata;

typedef struct pixel_data {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
    uint8_t transparency;
    Metadata metadata;
} PixelData;

typedef struct image_grid {
    size_t rows;
    size_t cols;
    PixelData **data; // Dynamic array of dynamic arrays
} ImageGrid;

// Error handling macro
#define HANDLE_ERROR(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

// Memory allocation with alignment
void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
    if (!ptr) HANDLE_ERROR("Aligned memory allocation failed");
#elif defined(__unix__) || defined(__APPLE__)
    if (posix_memalign(&ptr, alignment, size)) HANDLE_ERROR("Aligned memory allocation failed");
#else
    #error "Platform not supported"
#endif
    return ptr;
}

// Memory deallocation with alignment
void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#elif defined(__unix__) || defined(__APPLE__)
    free(ptr); // posix_memalign frees memory using free()
#else
    #error "Platform not supported"
#endif
}

// Function to process image grid
int process_image_grid(const char *input_file, const char *output_file,
                       uint8_t min_red, uint8_t min_green, uint8_t min_blue, uint8_t min_transparency) {

    FILE *file = fopen(input_file, "rb");
    if (!file) HANDLE_ERROR("Error opening input file");

    // Simulating image data loading
    size_t rows, cols;
    fread(&rows, sizeof(size_t), 1, file);
    fread(&cols, sizeof(size_t), 1, file);

    ImageGrid grid;
    grid.rows = rows;
    grid.cols = cols;

    grid.data = aligned_alloc(MEMORY_ALIGNMENT, rows * sizeof(PixelData *));
    if (!grid.data) HANDLE_ERROR("Error allocating memory for image data");

    for (size_t i = 0; i < rows; ++i) {
        grid.data[i] = aligned_alloc(MEMORY_ALIGNMENT, cols * sizeof(PixelData));
        if (!grid.data[i]) {
            fprintf(stderr, "Memory allocation failed at row %zu\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                aligned_free(grid.data[j]);
            }
            aligned_free(grid.data);
            fclose(file);
            return EXIT_FAILURE;
        }

        fread(grid.data[i], sizeof(PixelData), cols, file);
    }
    fclose(file);

    // Process the image data
    for (size_t i = 0; i < grid.rows; ++i) {
        for (size_t j = 0; j < grid.cols; ++j) {
            PixelData *pixel = &grid.data[i][j];

            if (pixel->red < min_red || pixel->green < min_green ||
                pixel->blue < min_blue || pixel->transparency < min_transparency) {

                // Example filter: set transparency to 0
                pixel->transparency = 0;
            }
        }
    }

    file = fopen(output_file, "wb");
    if (!file) HANDLE_ERROR("Error opening output file");

    fwrite(&grid.rows, sizeof(size_t), 1, file);
    fwrite(&grid.cols, sizeof(size_t), 1, file);

    for (size_t i = 0; i < grid.rows; ++i) {
        fwrite(grid.data[i], sizeof(PixelData), grid.cols, file);
    }
    fclose(file);

    // Free allocated memory
    for (size_t i = 0; i < grid.rows; ++i) {
        aligned_free(grid.data[i]);
    }
    aligned_free(grid.data);

    return EXIT_SUCCESS;
}

int main(int argc, char *argv[]) {
    if (argc != 7) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <min_red> <min_green> <min_blue> <min_transparency>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];

    uint8_t min_red = (uint8_t)atoi(argv[3]);
    uint8_t min_green = (uint8_t)atoi(argv[4]);
    uint8_t min_blue = (uint8_t)atoi(argv[5]);
    uint8_t min_transparency = (uint8_t)atoi(argv[6]);

    return process_image_grid(input_file, output_file, min_red, min_green, min_blue, min_transparency);
}
