['Below is a C implementation of the described functionality using POSIX threads for concurrency, dynamic memory management, and basic logging. This example assumes you have access to standard libraries like `pthread`, `time.h`, and `stdlib.h`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1048576 // Example memory limit in bytes
#define LOG_BUFFER_SIZE 256

typedef struct {
    uint32_t rnti;
    int rx_ue_info_tag;
} UE_TAG_T;

typedef struct {
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint64_t unique_id;
    time_t timestamp;
    UE_TAG_T ue_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    uint64_t true_crc_count;
    pthread_mutex_t lock;
} CRC_Indications_List;

CRC_Indications_List* list_init(size_t initial_capacity) {
    CRC_Indications_List* list = malloc(sizeof(CRC_Indications_List));
    if (!list) return NULL;

    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    list->true_crc_count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void log_message(const char* message) {
    // Simple logging function
    printf("%s\n", message);
}

int resize_list(CRC_Indications_List* list) {
    size_t new_capacity = list->capacity * 2;

    if ((size_t)new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_LIMIT) {
        log_message("Memory limit reached, cannot resize.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_message("Out of memory while resizing list.");
        return -1;
    }

    list->data = new_data;
    list->capacity = new_capacity;

    return 0;
}

int add_pdu(CRC_Indications_List* list, uint32_t rnti, int rx_ue_info_tag) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity && resize_list(list) != 0) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[list->count];
    pdu->unique_id = time(NULL); // Simplified unique ID generation
    pdu->timestamp = time(NULL);
    pdu->ue_tag.rnti = rnti;
    pdu->ue_tag.rx_ue_info_tag = rx_ue_info_tag;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG

    if (pdu->crc_indication_rel8_tag.crcflag) {
        list->true_crc_count++;
    }

    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

uint64_t get_true_crc_count(const CRC_Indications_List* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    uint64_t count = list->true_crc_count;

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return count;
}

void free_list(CRC_Indications_List* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}
```

### Key Points:
- **Thread Safety**: Achieved using `pthread_mutex_t` for locking critical sections.
- **Dynamic Resizing**: The list doubles in size when needed, respecting a predefined memory limit.
- **Logging**: Basic logging via `printf`, which can be expanded to more sophisticated systems if required.
- **Out-of-Memory Handling**: Graceful handling with error messages and checks before allocation attempts.
- **Performance Considerations**: Mutex locks ensure data integrity but may introduce some latency; careful consideration is needed for high-performance scenarios.

This code provides a foundation that can be extended with additional features like integration with external data sources, advanced logging systems, or more sophisticated unique ID generation.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdalign.h>
#include <pthread.h>

// Define alignment boundary
#define ALIGNMENT 16

typedef struct record {
    int id;
    double value;
    struct record *next;
} record;

void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__linux__) || defined(__unix__)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Error
    }
#else
    ptr = aligned_alloc(alignment, size); // C11 standard
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#elif defined(__linux__) || defined(__unix__)
    free(ptr);
#else
    free(ptr);
#endif
}

typedef struct {
    long *offsets;
    int *keys;
    double *values;
    record **records;
} hierarchical_data;

int allocate_hierarchical_data(hierarchical_data *data, size_t offset_count,
                               size_t key_count, size_t value_count,
                               size_t record_count) {

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize data structure
    if (pthread_mutex_lock(&lock)) {
        fprintf(stderr, "Failed to acquire lock\n");
        return -1;
    }

    void *temp_ptr;

    // Allocate array of offsets
    temp_ptr = aligned_alloc(offset_count * sizeof(long), ALIGNMENT);
    if (!temp_ptr) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    data->offsets = (long *)temp_ptr;

    // Allocate array of keys
    temp_ptr = aligned_alloc(key_count * sizeof(int), ALIGNMENT);
    if (!temp_ptr) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        aligned_free(data->offsets);
        pthread_mutex_unlock(&lock);
        return -1;
    }
    data->keys = (int *)temp_ptr;

    // Allocate array of values
    temp_ptr = aligned_alloc(value_count * sizeof(double), ALIGNMENT);
    if (!temp_ptr) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        aligned_free(data->offsets);
        aligned_free(data->keys);
        pthread_mutex_unlock(&lock);
        return -1;
    }
    data->values = (double *)temp_ptr;

    // Allocate array of record pointers
    temp_ptr = aligned_alloc(record_count * sizeof(record*), ALIGNMENT);
    if (!temp_ptr) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        aligned_free(data->offsets);
        aligned_free(data->keys);
        aligned_free(data->values);
        pthread_mutex_unlock(&lock);
        return -1;
    }
    data->records = (record**) temp_ptr;

    // Allocate individual records
    for (size_t i = 0; i < record_count; ++i) {
        temp_ptr = aligned_alloc(sizeof(record), ALIGNMENT);
        if (!temp_ptr) {
            fprintf(stderr, "Failed to allocate memory for a record\n");
            while (--i >= 0) { // Free previously allocated records
                aligned_free(data->records[i]);
            }
            aligned_free(data->offsets);
            aligned_free(data->keys);
            aligned_free(data->values);
            aligned_free(data->records);
            pthread_mutex_unlock(&lock);
            return -1;
        }
        data->records[i] = (record*) temp_ptr;

        // Initialize record
        data->records[i]->id = rand() % 100;   // Example random initialization
        data->records[i]->value = rand() / (double)RAND_MAX * 100.0; // Random double
        data->records[i]->next = NULL;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

void free_hierarchical_data(hierarchical_data *data, size_t record_count) {
    if (!data) return;

    for (size_t i = 0; i < record_count; ++i) {
        aligned_free(data->records[i]);
    }
    aligned_free(data->offsets);
    aligned_free(data->keys);
    aligned_free(data->values);
    aligned_free(data->records);
}

int main() {
    hierarchical_data data;

    if (allocate_hierarchical_data(&data, 10, 20, 30, 5) == -1) {
        fprintf(stderr, "Error allocating hierarchical data\n");
        return EXIT_FAILURE;
    }

    // Use the allocated data...

    free_hierarchical_data(&data, 5);

    return EXIT_SUCCESS;
}
```

This code provides a function to allocate memory for a hierarchical data structure with aligned allocations. It includes error handling and ensures that any allocation failures result in appropriate cleanup to prevent leaks. The use of `pthread_mutex_t` ensures thread safety when accessing shared resources during the allocation process.']

