```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

#define ALLOCATION_LIMIT 1024 * 1024 // Example limit in bytes
#define ALIGNMENT 32
#define ITEM_STRING_LEN 10

typedef struct Item {
    int key;
    char string[ITEM_STRING_LEN];
} Item;

typedef struct Node {
    double value;
    Item* items;
    int itemCount;
    struct Node* next; // Linked list support
} Node;

void align_memory(void** ptr, size_t alignment) {
    *ptr = (void*)(((size_t)(*ptr) + alignment - 1) & ~(alignment - 1));
}

Node** init_nodes(int nodeCount, const int itemMaxPerNode, double (*valueFunc)(int), char *(*stringGen)(int)) {
    Node** nodes = malloc(nodeCount * sizeof(Node*));
    if (!nodes) return NULL;

    srand((unsigned)time(NULL));

    size_t totalSize = 0;
    for (int i = 0; i < nodeCount; ++i) {
        void* alignedPtr = NULL;
        size_t alignmentPadding = ALIGNMENT - (((size_t)&alignedPtr + sizeof(void*)) % ALIGNMENT);

        Node* node = malloc(sizeof(Node) + alignmentPadding);
        if (!node) return NULL;

        align_memory((void**)&(node->items), ALIGNMENT);
        node->items = calloc(itemMaxPerNode, sizeof(Item));
        if (!node->items) {
            free(node);
            return NULL;
        }

        totalSize += sizeof(Node) + alignmentPadding + (itemMaxPerNode * sizeof(Item));

        if (totalSize > ALLOCATION_LIMIT) {
            // Handle memory limit exceeded
            for (int j = 0; j <= i && nodes[j]; ++j) free(nodes[j]);
            free(nodes);
            return NULL;
        }

        node->value = valueFunc(rand() % 100); 
        for (int k = 0; k < itemMaxPerNode; ++k) {
            node->items[k].key = rand();
            strcpy(node->items[k].string, stringGen(rand()));
        }

        node->itemCount = itemMaxPerNode;
        nodes[i] = node;
    }

    return nodes;
}

double calculate_sqrt(int num) {
    return sqrt(num);
}

char* generate_random_string(int seed) {
    static const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";

    char buffer[ITEM_STRING_LEN + 1];
    for (int i = 0; i < ITEM_STRING_LEN; ++i) {
        buffer[i] = charset[rand_r(&seed) % (sizeof(charset) - 1)];
    }
    buffer[ITEM_STRING_LEN] = '\0';
    return strdup(buffer);
}

void release_resources(Node** nodes, int nodeCount) {
    for (int i = 0; i < nodeCount; ++i) {
        if (nodes[i]) {
            free(nodes[i]->items);
            free(nodes[i]);
        }
    }
    free(nodes);
}
```

