import java.net.*;
import java.nio.channels.SocketChannel;
import java.util.concurrent.TimeUnit;

public class RemoteConnection {

    public static void establishConnection(String host, int port) {
        try (SocketChannel socketChannel = SocketChannel.open()) {
            InetAddress address = InetAddress.getByName(host);
            boolean connected = socketChannel.connect(new InetSocketAddress(address, port), 5000); // 5 seconds timeout

            if (!connected) {
                throw new IOException("Connection attempt timed out");
            }

            handleConnectionState(socketChannel);
        } catch (IOException e) {
            System.err.println("Error establishing connection: " + e.getMessage());
        }
    }

    private static void handleConnectionState(SocketChannel socketChannel) throws IOException {
        // Handle connection state changes
        if (socketChannel.isConnected()) {
            System.out.println("Successfully connected to the remote address.");
        } else {
            System.out.println("Failed to establish a connection or it was closed.");
        }
    }

    public static void main(String[] args) {
        // Example usage: Connect to localhost on port 8080
        establishConnection("localhost", 8080);
    }
}
