#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int key;
    float value;
} Record;

#define ALIGNMENT 16

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void aligned_free(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int get_timestamp(long *timestamp) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts)) {
        // Fallback to time in seconds since epoch if high-resolution unavailable.
        *timestamp = (long)time(NULL);
        return 0;
    }
    *timestamp = ts.tv_sec;
    return 1;
}

int main(int argc, char **argv) {
    size_t m = 100; // Example size
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    long* offsets = aligned_alloc(ALIGNMENT, m * sizeof(long));
    int* keys = aligned_alloc(ALIGNMENT, m * sizeof(int));
    Record* records = aligned_alloc(ALIGNMENT, m * sizeof(Record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        goto cleanup;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    atomic_int ref_count = 1;

    for (size_t i = 0; i < m; ++i) {
        offsets[i] = rand() % 10000; // Example offset value
        keys[i] = i;

        long timestamp;
        if (!get_timestamp(&timestamp)) {
            printf("Timestamp retrieval failed, using fallback\n");
        }
        records[i].timestamp = timestamp;
        records[i].key = rand() % 1000 + 1; // Random key in range [1, 1000]
        records[i].value = (float)rand() / RAND_MAX; // Random float between 0.0 and 1.0
    }

    // Example of concurrency-safe access with a lock
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < m; ++i) {
        records[i].key += 10; // Example operation under protection
    }
    pthread_mutex_unlock(&lock);

    // Simulate reference count increment and decrement
    atomic_fetch_add_explicit(&ref_count, 1, memory_order_relaxed);
    if (atomic_load_explicit(&ref_count, memory_order_acquire) == 0) {
        goto cleanup;
    }

    atomic_fetch_sub_explicit(&ref_count, 1, memory_order_release);

cleanup:
    aligned_free(offsets);
    aligned_free(keys);
    aligned_free(records);
    pthread_mutex_destroy(&lock);

    return 0;
}
```

This C code sets up and manages dynamic memory allocation for three arrays (`offsets`, `keys`, `records`), ensuring alignment, handling allocation failures, and providing a concurrency-safe mechanism using mutexes. The records' timestamps are initialized with high-resolution timers when available, and the keys and values are populated as specified. A reference counting approach is used to manage cleanup, and memory is released appropriately at the end of execution or upon encountering an error.']

