#define ALLOCATION_FAILURE -1

// Error tracking mechanism
int error_code = SUCCESS;

// Function prototypes
Record* createRecords(size_t count, const char* flag);
void freeRecords(Record* records, size_t count);
size_t getActiveRecordCount(const Record* records, size_t count);

// Create a flexible record system
Record* createRecords(size_t count, const char* flag) {
    if (count == 0 || !flag) return NULL;

    Record *records = malloc(count * sizeof(Record));
    if (!records) {
        error_code = ALLOCATION_FAILURE;
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < count; ++i) {
        records[i].isActive = rand() % 2; // Randomly activate record
        if (records[i].isActive) {
            int rangeMin = 1, rangeMax = 100;
            records[i].value.key = rand() % (rangeMax - rangeMin + 1) + rangeMin;

            // Optionally allocate secondary array
            size_t secondarySize = rand() % 10; // Example: up to 10 elements
            records[i].secondaryArray = malloc(secondarySize * sizeof(int));
            if (!records[i].secondaryArray) {
                error_code = ALLOCATION_FAILURE;
                freeRecords(records, i);
                return NULL;
            }
            records[i].secondarySize = secondarySize;

            // Initialize secondary array with random values
            for (size_t j = 0; j < secondarySize; ++j) {
                records[i].secondaryArray[j] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
            }
        } else {
            records[i].value.offset = 0; // Default value
            records[i].secondaryArray = NULL;
            records[i].secondarySize = 0;
        }
    }

    return records;
}

// Free allocated memory for records
void freeRecords(Record* records, size_t count) {
    if (!records) return;

    for (size_t i = 0; i < count; ++i) {
        if (records[i].secondaryArray) {
            free(records[i].secondaryArray);
        }
    }

    free(records);
}

// Retrieve the total number of active records
size_t getActiveRecordCount(const Record* records, size_t count) {
    size_t activeCount = 0;
    if (!records) return activeCount;

    for (size_t i = 0; i < count; ++i) {
        if (records[i].isActive) {
            ++activeCount;
        }
    }

    return activeCount;
}

// Example usage
int main() {
    size_t recordCount = 10;
    Record *records = createRecords(recordCount, "key");

    if (error_code == ALLOCATION_FAILURE) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    size_t activeCount = getActiveRecordCount(records, recordCount);
    printf("Total Active Records: %zu\n", activeCount);

    freeRecords(records, recordCount);
    return 0;
}
