// Define data types
typedef enum { TYPE_INT, TYPE_FLOAT, TYPE_STRING } FieldType;
typedef struct {
    char *name;
    FieldType type;
} Field;

// Record structure
typedef struct Record {
    int key;
    void *value;
    Field **fields;
    size_t num_fields;
    struct Record *next;
} Record;

// Hash table entry
typedef struct HashEntry {
    int key;
    Record *record;
    struct HashEntry *next;
} HashEntry;

#define HASH_TABLE_SIZE 101

// Hash function
unsigned int hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

// Initialize hash table
HashEntry *hash_table[HASH_TABLE_SIZE] = { NULL };

// Memory management strategy: simple fixed-size block allocator
#define BLOCK_SIZE 4096
char memory_pool[BLOCK_SIZE];
size_t pool_offset = 0;

void* custom_alloc(size_t size) {
    if (pool_offset + size > BLOCK_SIZE) return NULL;
    void *ptr = &memory_pool[pool_offset];
    pool_offset += size;
    return ptr;
}

void reset_memory_pool() {
    pool_offset = 0;
}

// Create a field
Field* create_field(const char *name, FieldType type) {
    Field *field = (Field*)custom_alloc(sizeof(Field));
    if (!field) return NULL;
    field->name = strdup(name);
    field->type = type;
    return field;
}

// Add record to linked list and hash table
Record* add_record(int key, void *value, Field **fields, size_t num_fields) {
    Record *record = (Record*)custom_alloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->value = value;
    record->num_fields = num_fields;
    record->next = NULL;

    record->fields = (Field**)custom_alloc(num_fields * sizeof(Field*));
    for (size_t i = 0; i < num_fields; ++i) {
        record->fields[i] = fields[i];
    }

    unsigned int index = hash_function(key);
    HashEntry *entry = (HashEntry*)custom_alloc(sizeof(HashEntry));
    if (!entry) return NULL;

    entry->key = key;
    entry->record = record;
    entry->next = hash_table[index];
    hash_table[index] = entry;

    // Log operation
    printf("Record added with key: %d\n", key);

    return record;
}

// Free field
void free_field(Field *field) {
    if (field) {
        free(field->name);
        custom_alloc(0);  // Simulate freeing
    }
}

// Delete a record by key
void delete_record(int key) {
    unsigned int index = hash_function(key);
    HashEntry **entry = &hash_table[index];

    while (*entry) {
        if ((*entry)->key == key) {
            Record *record = (*entry)->record;
            for (size_t i = 0; i < record->num_fields; ++i) {
                free_field(record->fields[i]);
            }
            custom_alloc(0); // Simulate freeing
            *entry = (*entry)->next;

            printf("Record deleted with key: %d\n", key);
            return;
        }
        entry = &(*entry)->next;
    }
}

// Reset system state and external integrations
void reset_system() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashEntry *entry = hash_table[i];
        while (entry) {
            HashEntry *temp = entry;
            entry = entry->next;
            custom_alloc(0); // Simulate freeing
            temp = NULL;
        }
    }
    reset_memory_pool();
}

int main() {
    Field *fields[2] = { create_field("age", TYPE_INT), create_field("name", TYPE_STRING) };

    add_record(1, (void*)"John Doe", fields, 2);
    delete_record(1);

    reset_system();

    return 0;
}
```

This code snippet demonstrates a simple linked list and hash table management system for records with unique keys and dynamic values. It includes custom memory allocation to handle fragmentation and efficient logging. The system can be easily extended by adding new field types or integrating external metadata sources.']

