    if (type == LOG_FILE && !log_file) {
        log_file = fopen("network_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    if (type == LOG_CONSOLE) {
        printf("%s\n", message);
    } else if (type == LOG_FILE && log_file) {
        fprintf(log_file, "%s\n", message);
    }
}

// Function to validate MAC address format
int is_valid_mac_address(const unsigned char* mac) {
    for (int i = 0; i < MAC_ADDRESS_LENGTH; ++i) {
        if ((mac[i] < 0x00 || mac[i] > 0xFF)) return 0;
    }
    return 1;
}

// Function to fetch and validate updated MAC address formats
void update_mac_address_formats() {
    // Placeholder for external data fetching logic
    log_message(LOG_CONSOLE, "Fetching latest MAC address formats...");
    // Simulate network operation
    sleep(1);
    log_message(LOG_CONSOLE, "MAC address formats updated.");
}

// Function to initialize and populate NICB array
int initialize_nicb_array(NICB* nicbs, size_t count) {
    if (!nicbs || count > MAX_NICB) return -1;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_t update_thread;

    // Start thread for updating MAC address formats
    pthread_create(&update_thread, NULL, (void*)update_mac_address_formats, NULL);

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&mutex);

        // Randomly generate MAC addresses and VLAN tag
        for (int j = 0; j < MAC_ADDRESS_LENGTH; ++j) {
            nicbs[i].mac_header.mac_address[j] = rand() % 256;
            nicbs[i].ethernet_mac[j] = rand() % 256;
            nicbs[i].ethernet_mac[MAC_ADDRESS_LENGTH + j] = rand() % 256;
        }

        if (!is_valid_mac_address(nicbs[i].mac_header.mac_address)) {
            log_message(LOG_CONSOLE, "Invalid MAC address detected.");
            pthread_mutex_unlock(&mutex);
            continue;
        }

        nicbs[i].vlan_config.vlan_tag = rand() % 4096;
        nicbs[i].vlan_config.vlan_priority = rand() % 256;
        nicbs[i].vlan_config.ip_checksum_calculation = rand() % 2;

        log_message(LOG_CONSOLE, "NICB initialized successfully.");

        pthread_mutex_unlock(&mutex);
    }

    pthread_join(update_thread, NULL);

    return 0;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    NICB* nicbs = (NICB*)custom_malloc(MAX_NICB * sizeof(NICB));
    initialize_nicb_array(nicbs, MAX_NICB);

    free(nicbs);
    return 0;
}
