#define ALIGNMENT 128

typedef enum { VIDEO, AUDIO, IMAGE, LIVE_STREAM } asset_type_t;

// Align memory allocations to a specific boundary.
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Failed allocation
    }
    return ptr;
}

typedef struct property_node {
    char *name;
    char *value;
    time_t timestamp;
    struct property_node *prev, *next;
} property_node;

typedef struct container_node {
    asset_type_t type;
    float duration;
    struct container_node *prev, *next;
    property_node *properties_head;
} container_node;

typedef struct media_item {
    container_node *head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} media_item;

media_item* initialize_media_item() {
    media_item *item = (media_item *)aligned_alloc(ALIGNMENT, sizeof(media_item));
    if (!item) return NULL;

    item->head = NULL;
    pthread_mutex_init(&item->lock, NULL);
    pthread_cond_init(&item->cond, NULL);
    return item;
}

int add_container(media_item *item, asset_type_t type, float duration) {
    container_node *new_node = (container_node *)aligned_alloc(ALIGNMENT, sizeof(container_node));
    if (!new_node) return -1;

    new_node->type = type;
    new_node->duration = duration;
    new_node->properties_head = NULL;
    new_node->prev = new_node->next = NULL;

    pthread_mutex_lock(&item->lock);

    // Insert the container into the doubly linked list
    if (!item->head) {
        item->head = new_node;
    } else {
        container_node *current = item->head;
        while (current->next) current = current->next;
        current->next = new_node;
        new_node->prev = current;
    }

    pthread_mutex_unlock(&item->lock);
    return 0;
}

int add_property(container_node *container, const char *name, const char *value, time_t timestamp) {
    property_node *new_prop = (property_node *)aligned_alloc(ALIGNMENT, sizeof(property_node));
    if (!new_prop) return -1;

    new_prop->name = strdup(name);
    new_prop->value = strdup(value);
    new_prop->timestamp = timestamp;
    new_prop->prev = new_prop->next = NULL;

    container->properties_head = (container->properties_head == NULL)
        ? new_prop
        : append_property(container->properties_head, new_prop);

    return 0;
}

property_node* append_property(property_node *head, property_node *new_prop) {
    if (!head) return new_prop;

    property_node *current = head;
    while (current->next) current = current->next;

    current->next = new_prop;
    new_prop->prev = current;
    return head;
}

int verify_data_integrity(media_item *item) {
    pthread_mutex_lock(&item->lock);

    container_node *container = item->head;
    while (container) {
        property_node *prop = container->properties_head;
        while (prop) {
            if (prop->timestamp == 0 || strcmp(prop->name, "") == 0) {
                printf("Data integrity check failed.\n");
                pthread_mutex_unlock(&item->lock);
                return -1;
            }
            prop = prop->next;
        }
        container = container->next;
    }

    printf("All data checks passed.\n");
    pthread_mutex_unlock(&item->lock);
    return 0;
}

void log_module_test(const char *label, int (*f)(media_item*), media_item *item) {
    printf("Testing module: %s\n", label);
    if (f(item) == 0) {
        printf("Test '%s' passed.\n", label);
    } else {
