    return ptr;
}

void aligned_free(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

Config* create_config(int thread_pool_size, int timeout_value) {
    Config* config = (Config*)aligned_alloc(sizeof(Config));
    if (!config) return NULL;
    config->thread_pool_size = thread_pool_size;
    config->timeout_value = timeout_value;
    return config;
}

Value* create_value(unsigned int index, size_t data_size) {
    Value* value = (Value*)aligned_alloc(sizeof(Value));
    if (!value) return NULL;

    value->index = index;
    value->data = aligned_alloc(data_size);
    if (!value->data) {
        aligned_free(value);
        return NULL;
    }

    // Initialize with random byte patterns
    unsigned char* data_ptr = (unsigned char*)value->data;
    for (size_t i = 0; i < data_size; ++i) {
        data_ptr[i] = rand() % 256;
    }

    value->next = NULL;
    return value;
}

Entry* create_entry(float initial_value, Config* config, unsigned int num_values) {
    Entry* entry = (Entry*)aligned_alloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->value = initial_value;
    entry->config = config;
    entry->values = NULL;

    for (unsigned int i = 0; i < num_values; ++i) {
        Value* new_value = create_value(i, rand() % 1024 + 1);
        if (!new_value) {
            // Cleanup in case of failure
            while (entry->values) {
                Value* temp = entry->values;
                entry->values = entry->values->next;
                aligned_free(temp->data);
                aligned_free(temp);
            }
            aligned_free(entry);
            return NULL;
        }

        new_value->next = entry->values;
        entry->values = new_value;
    }

    return entry;
}

void verify_entry(Entry* entry) {
    if (!entry) return;

    // Verify config
    if (!entry->config) {
        fprintf(stderr, "Error: Config is NULL\n");
        exit(EXIT_FAILURE);
    }

    // Verify values linked list
    Value* current = entry->values;
    unsigned int index = 0;
    while (current) {
        if (current->index != index) {
            fprintf(stderr, "Error: Index mismatch at value %u\n", index);
            exit(EXIT_FAILURE);
        }
        if (!current->data) {
            fprintf(stderr, "Error: Data is NULL at index %u\n", current->index);
            exit(EXIT_FAILURE);
        }

        // Additional data verification can be added here
        current = current->next;
        ++index;
    }
}

void destroy_entry(Entry* entry) {
    if (!entry) return;

    Value* current = entry->values;
    while (current) {
        Value* temp = current;
        current = current->next;
        aligned_free(temp->data);
        aligned_free(temp);
    }

    aligned_free(entry);
}

int main() {
    Config* config = create_config(4, 30);
    if (!config) return EXIT_FAILURE;

    Entry* entry = create_entry(0.0f, config, 10);
    if (!entry) {
        aligned_free(config);
        return EXIT_FAILURE;
    }

    verify_entry(entry);

    destroy_entry(entry);
    aligned_free(config);

    return EXIT_SUCCESS;
}
