['Below is a simplified code structure for a scalable, distributed indexing system in C++. This example demonstrates key concepts such as resource management, concurrency control, scalability, data integrity, performance optimization, interoperability, and modular design.

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <mutex>
#include <thread>
#include <atomic>
#include <memory>
#include <fstream>
#include <nlohmann/json.hpp> // JSON library for serialization/deserialization

using json = nlohmann::json;

// Document structure
struct Document {
    std::string id;
    std::string content;
    std::unordered_map<std::string, std::string> metadata;
    int numericalId;
    std::string timestamp;
    std::string author;
    std::vector<std::string> tags;
};

class IndexNode {
public:
    IndexNode() = default;

    void insertDocument(const Document& doc) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index_.find(doc.id) != index_.end()) {
            throw std::runtime_error("Duplicate primary key error.");
        }
        index_[doc.id] = doc;
        serializeToDisk();
    }

    bool deleteDocument(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index_.erase(id)) {
            serializeToDisk();
            return true;
        }
        return false;
    }

    Document queryDocument(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = index_.find(id);
        if (it != index_.end()) {
            return it->second;
        }
        throw std::runtime_error("Document not found.");
    }

private:
    void serializeToDisk() {
        // Serialize the current state of the index to disk
        std::ofstream ofs(indexFile_, std::ios::binary);
        json j = json::object();
        for (const auto& [key, doc] : index_) {
            j[key] = doc;
        }
        ofs << j.dump();
    }

    void deserializeFromDisk() {
        // Deserialize the state of the index from disk
        std::ifstream ifs(indexFile_, std::ios::binary);
        json j;
        ifs >> j;
        for (auto& [key, value] : j.items()) {
            Document doc = value.get<Document>();
            index_[doc.id] = doc;
        }
    }

    const std::string indexFile_ = "index.json";
    mutable std::mutex mutex_;
    std::unordered_map<std::string, Document> index_;

    // Constructor
    IndexNode(const std::string& filename) {
        deserializeFromDisk();
    }
};

class DistributedIndexSystem {
public:
    void addDocumentToNode(int nodeId, const Document& doc) {
        if (nodes_.find(nodeId) == nodes_.end()) {
            throw std::runtime_error("Node not found.");
        }
        nodes_[nodeId]->insertDocument(doc);
    }

    bool removeDocumentFromNode(int nodeId, const std::string& id) {
        if (nodes_.find(nodeId) == nodes_.end()) {
            return false;
        }
        return nodes_[nodeId]->deleteDocument(id);
    }

    Document getDocumentFromNode(int nodeId, const std::string& id) {
        if (nodes_.find(nodeId) == nodes_.end()) {
            throw std::runtime_error("Node not found.");
        }
        return nodes_[nodeId]->queryDocument(id);
    }

private:
    std::unordered_map<int, std::unique_ptr<IndexNode>> nodes_;
};

int main() {
    // Example usage
    DistributedIndexSystem system;

    Document doc1 = {"1", "Sample content", {{"key1", "value1"}}, 101, "2023-10-01T12:00:00Z", "Author A", {"tag1", "tag2"}};
    system.addDocumentToNode(0, doc1);

    try {
        Document queriedDoc = system.getDocumentFromNode(0, "1");
        std::cout << "Queried Document ID: " << queriedDoc.id << "\n";
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
    }

    return 0;
}
```

### Key Points:
- **Concurrency Control**: Uses `std::mutex` for thread-safe operations.
- **Serialization/Deserialization**: Utilizes JSON format with the `nlohmann/json` library.
- **Resource Management**: Demonstrates basic disk serialization to handle large data.
- **Modular Design**: The system is designed in a way that allows easy extension and integration.

### Notes:
- This code is a simplified illustration. In practice, you would need more sophisticated handling for distributed systems, including network communication, fault tolerance, and dynamic scaling.
- Libraries like `nlohmann/json` are used here for JSON serialization/deserialization.
- Consider using libraries such as Boost or std::filesystem for advanced file operations and concurrency mechanisms if needed.']

