#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MEMORY_POOL_SIZE 1024 * 1024 // 1MB pool for example
#define RECORD_ALIGNMENT 16
#define NICB_ALIGNMENT 16
#define MAX_RECORDS 1000
#define MAX_NICBS 500

typedef struct {
    uint8_t mac_header[14];
    uint8_t ethernet_mac[6];
    uint8_t vlan_tag[4];
} NICB;

typedef struct {
    int value;
} Record;

// Memory pool and tracking structures
static uint8_t memory_pool[MEMORY_POOL_SIZE];
static size_t pool_offset = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

#define ALIGNED_ALLOC(size, alignment) \
    ({ \
        void *ptr = NULL; \
        if (__builtin_assume_aligned(memory_pool + pool_offset, alignment)) { \
            ptr = memory_pool + pool_offset; \
            pool_offset += ((size + alignment - 1) & ~(alignment - 1)); \
        } \
        ptr; \
    })

// Random number generator
void seed_rng() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Memory allocation and initialization functions
Record* allocate_record(int min_val, int max_val) {
    pthread_mutex_lock(&pool_lock);

    Record *record = (Record *)ALIGNED_ALLOC(sizeof(Record), RECORD_ALIGNMENT);
    if (!record || pool_offset >= MEMORY_POOL_SIZE) {
        fprintf(stderr, "Memory allocation failed for record\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }

    record->value = random_int(min_val, max_val);

    pthread_mutex_unlock(&pool_lock);
    return record;
}

NICB* allocate_nicb() {
    pthread_mutex_lock(&pool_lock);

    NICB *nicb = (NICB *)ALIGNED_ALLOC(sizeof(NICB), NICB_ALIGNMENT);
    if (!nicb || pool_offset >= MEMORY_POOL_SIZE) {
        fprintf(stderr, "Memory allocation failed for NICB\n");
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }

    for (int i = 0; i < 14; ++i) nicb->mac_header[i] = random_int(0, 255);
    for (int i = 0; i < 6; ++i) nicb->ethernet_mac[i] = random_int(0, 255);
    for (int i = 0; i < 4; ++i) nicb->vlan_tag[i] = random_int(0, 255);

    pthread_mutex_unlock(&pool_lock);
    return nicb;
}

// Verification function
void verify_record(Record *record) {
    if (!record || record->value < 0) {
        fprintf(stderr, "Record verification failed\n");
    }
}

void verify_nicb(NICB *nicb) {
    if (!nicb) {
        fprintf(stderr, "NICB verification failed\n");
    }
}

// Example usage
int main() {
    seed_rng();

    Record *record = allocate_record(1, 100);
    NICB *nicb = allocate_nicb();

    verify_record(record);
    verify_nicb(nicb);

    if (record) free(record); // Simulate deallocation
    if (nicb) free(nicb);

    return 0;
}
