// Memory pool structure
typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void init_memory_pool(MemoryPool* mp, size_t size);
void* aligned_alloc(size_t alignment, size_t size);
void* allocate_from_pool(MemoryPool* mp, size_t size);
void deallocate_to_pool(MemoryPool* mp, void* ptr, size_t size);
record* create_record(int min_val, int max_val, MemoryPool* mp);
NICB* create_nicb(MemoryPool* mp);

// Initialize memory pool
void init_memory_pool(MemoryPool* mp, size_t size) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->pool = aligned_alloc(ALIGNMENT, size);
    if (!mp->pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    mp->size = size;
    mp->offset = 0;
}

// Allocate memory with specific alignment
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (alignment % ALIGNMENT != 0 || !IS_ALIGNED(alignment)) {
        fprintf(stderr, "Alignment error\n");
        exit(EXIT_FAILURE);
    }
    ptr = _aligned_malloc(size + alignment - 1, alignment);
#else
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Allocate memory from pool with specific alignment
void* allocate_from_pool(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    void* ptr = NULL;

    if (mp->offset + size <= mp->size) {
        ptr = (char*)mp->pool + mp->offset;
        mp->offset += size;
    }

    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

// Deallocate memory to pool
void deallocate_to_pool(MemoryPool* mp, void* ptr, size_t size) {
    // Simplified: In a real implementation, this would require managing free blocks.
}

// Create and initialize a record
