    record* rec = (record*)allocate_from_pool(mp, RECORD_SIZE);
    if (!rec) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return NULL;
    }

    srand(time(NULL));
    rec->value = min_val + rand() % (max_val - min_val + 1);

    return rec;
}

// Create and initialize a NICB
NICB* create_nicb(MemoryPool* mp) {
    NICB* nicb = (NICB*)allocate_from_pool(mp, NICB_SIZE);
    if (!nicb) {
        fprintf(stderr, "Failed to allocate memory for NICB\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < sizeof(nicb->mac_header); ++i) {
        nicb->mac_header[i] = rand() % 256;
    }

    for (int i = 0; i < sizeof(nicb->vlan_tag); ++i) {
        nicb->vlan_tag[i] = rand() % 256;
    }

    return nicb;
}

// Main function demonstrating the usage
int main() {
    MemoryPool mp;
    init_memory_pool(&mp, 1024 * 1024); // 1MB pool

    record* r = create_record(0, 100, &mp);
    NICB* n = create_nicb(&mp);

    if (r && n) {
        printf("Record value: %d\n", r->value);
        printf("MAC Header: ");
        for (int i = 0; i < sizeof(n->mac_header); ++i) {
            printf("%02x ", n->mac_header[i]);
        }
        printf("\nVLAN Tag: ");
        for (int i = 0; i < sizeof(n->vlan_tag); ++i) {
            printf("%02x ", n->vlan_tag[i]);
        }
