    pthread_mutex_lock(&alloc_mutex);
    void* memory = aligned_alloc(g_config.alignment_offset, size);
    if (!memory && g_config.logging_level > 0) {
        fprintf(stderr, "Memory allocation failed for %zu bytes\n", size);
