#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MEMORY_ALIGNMENT 128
#define PROPERTY_VALUE_LENGTH 20

typedef enum {
    VIDEO,
    AUDIO,
    IMAGE
} MediaType;

typedef struct Property {
    char *name;
    char *value;
    struct Property *next;
} Property;

typedef struct Container {
    MediaType type;
    float duration;
    Property *properties;
    struct Container *next;
} Container;

typedef struct MediaItem {
    Container *containers;
} MediaItem;

typedef struct MemoryPool {
    size_t block_size;
    void *blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *pool = (MemoryPool *)aligned_alloc(MEMORY_ALIGNMENT, sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->blocks = malloc(pool_size);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    memset(pool->blocks, 0, pool_size);
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    void *block = memmem(pool->blocks, pool->block_size, "\0", 1);
    if (block == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    memset(block, 0, pool->block_size);
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void memory_pool_free(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);

    if (block >= pool->blocks && block < ((char*)pool->blocks + pool->block_size)) {
        memset(block, 0, pool->block_size);
    }

    pthread_mutex_unlock(&pool->lock);
}

bool is_valid_memory_block(void *block, size_t size) {
    return memmem(block, size, "\0", 1) != NULL;
}

void log_message(const char *module, const char *test_name, bool verbose, const char *message) {
    if (verbose) {
        printf("Module: %s | Test: %s | Message: %s\n", module, test_name, message);
    }
}

bool generate_unique_property_name(char **name, Property *properties) {
    static char name_base[] = "property_";
    int index = 0;
    bool unique;

    do {
        unique = true;
        asprintf(name, "%s%d", name_base, index);

        for (Property *prop = properties; prop != NULL; prop++) {
            if (strcmp(prop->name, *name) == 0) {
                unique = false;
                break;
            }
        }

        free(*name);
        index++;
    } while (!unique);

    return true;
}

void initialize_property(Property **property, char **name_pool, Property *siblings) {
    generate_unique_property_name(name_pool, siblings);

    *property = (Property *)memory_pool_alloc(global_memory_pool);
    if (*property == NULL) return;

    (*property)->name = strdup(*name_pool);
    (*property)->value = malloc(PROPERTY_VALUE_LENGTH + 1);

    for (int i = 0; i < PROPERTY_VALUE_LENGTH; ++i) {
        (*property)->value[i] = 'a' + rand() % 26;
    }
    (*property)->value[PROPERTY_VALUE_LENGTH] = '\0';
}

void verify_integrity(MediaItem *media_item, bool verbose) {
    if (!media_item) return;

    for (Container *container = media_item->containers; container != NULL; container = container->next) {
        if (container->duration < 0 || !is_valid_memory_block(container, sizeof(Container))) {
            log_message("MediaItem", "VerifyIntegrity", verbose, "Invalid container detected.");
            return;
        }

        for (Property *property = container->properties; property != NULL; property = property->next) {
            if (!is_valid_memory_block(property->name, strlen(property->name) + 1) ||
                !is_valid_memory_block(property->value, PROPERTY_VALUE_LENGTH + 1)) {
                log_message("MediaItem", "VerifyIntegrity", verbose, "Invalid property detected.");
                return;
            }
        }
    }

    log_message("MediaItem", "VerifyIntegrity", verbose, "All data is valid.");
}

void run_test(const char *label, void (*f)(void), bool verbose) {
    log_message("TestFramework", label, verbose, "Starting test.");

    f();

    // Mock reset function
    // mediakit_reset(); 

    verify_integrity(global_media_item, verbose);
    log_message("TestFramework", label, verbose, "Test completed.");
}

MemoryPool *global_memory_pool;
MediaItem *global_media_item;

void setup_test_environment() {
    global_memory_pool = create_memory_pool(1024, 10 * 1024 * 1024); // Example sizes
    if (!global_memory_pool) {
        fprintf(stderr, "Failed to create memory pool.\n");
        exit(EXIT_FAILURE);
    }

    global_media_item = (MediaItem *)memory_pool_alloc(global_memory_pool);
    if (!global_media_item) {
        fprintf(stderr, "Failed to allocate media item.\n");
        exit(EXIT_FAILURE);
    }
}

void example_test_function() {
    Container *container = (Container *)memory_pool_alloc(global_memory_pool);
    if (!container) return;

    container->type = VIDEO;
    container->duration = 120.0f;
    container->properties = NULL;

    char *name_pool;
    Property *property = NULL;

    for (int i = 0; i < 5; ++i) {
        initialize_property(&property, &name_pool, container->properties);
        if (!property) continue;

        property->next = container->properties;
        container->properties = property;
    }

    container->next = global_media_item->containers;
    global_media_item->containers = container;
}

int main() {
    setup_test_environment();

    run_test("ExampleTest", example_test_function, true);

    // Cleanup
    free(global_memory_pool->blocks);
    free(global_memory_pool);

    return 0;
}
