    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Free Aligned Memory
void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Random Number Generator Initialization
void init_random() {
    srand(time(NULL));
}

// Generate a random int in range [min, max]
int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Create and Initialize Node Array
node* initialize_nodes(size_t num_nodes) {
    node *nodes = (node*)aligned_alloc(MEMORY_ALIGN_BOUNDARY, num_nodes * sizeof(node));
    if (!nodes) {
        log_error("Memory allocation failed for nodes");
        return NULL;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i].value = generate_random_int(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);

        size_t num_items = generate_random_int(1, MAX_ITEMS_PER_NODE);
        nodes[i].item_list_head = aligned_alloc(MEMORY_ALIGN_BOUNDARY, num_items * sizeof(item));
        if (!nodes[i].item_list_head) {
            log_error("Memory allocation failed for item list");
            return NULL; // Cleanup should be implemented here in real code
        }

        memset(nodes[i].item_list_head, 0, num_items * sizeof(item));

        nodes[i].offsets = aligned_alloc(MEMORY_ALIGN_BOUNDARY, num_items * sizeof(long));
        if (!nodes[i].offsets) {
            log_error("Memory allocation failed for offsets");
            return NULL; // Cleanup should be implemented here in real code
        }

        memset(nodes[i].offsets, 0, num_items * sizeof(long));

        nodes[i].keys = aligned_alloc(MEMORY_ALIGN_BOUNDARY, num_items * sizeof(int));
        if (!nodes[i].keys) {
            log_error("Memory allocation failed for keys");
            return NULL; // Cleanup should be implemented here in real code
        }

        memset(nodes[i].keys, 0, num_items * sizeof(int));

        // Populate item list as linked list (head only for simplicity)
        for (size_t j = 0; j < num_items - 1; ++j) {
            nodes[i].item_list_head[j].metadata.next_item = &nodes[i].item_list_head[j + 1];
            strcpy(nodes[i].item_list_head[j].data, "Sample Data");
            nodes[i].keys[j] = generate_random_int(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);
        }

        // Last item has no next
        nodes[i].item_list_head[num_items - 1].metadata.value = (short)generate_random_int(0, 10000);
    }

    return nodes;
}

// Create and Initialize Records Array
record* initialize_records(size_t num_records) {
    record *records = (record*)aligned_alloc(MEMORY_ALIGN_BOUNDARY, num_records * sizeof(record));
    if (!records) {
        log_error("Memory allocation failed for records");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random_int(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);
    }

