#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define MEMORY_LIMIT 1024 * 1024 * 256 // Example limit: 256 MB
#define CPU_LIMIT 80 // Example CPU usage threshold in percentage

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    size_t offsets_length;
    int* keys;
    size_t keys_length;
    record* records;
    size_t records_length;
} AllocatedData;

// Function prototypes
void log_error(const char* message);
int validate_memory(void* ptr, size_t size, const char* description);
void free_resources(AllocatedData* data);

AlignedMemory allocate_aligned(size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, 16);
#elif defined(__GNUC__)
    if (posix_memalign(&ptr, 16, size)) {
        return {NULL};
    }
#else
    #error "Platform not supported for aligned memory allocation."
#endif
    return {ptr};
}

int allocate_data(AllocatedData* data, size_t offsets_length, size_t keys_length, size_t records_length,
                  int lower_bound, int upper_bound) {
    if (offsets_length < 0 || keys_length < 0 || records_length < 0 ||
        lower_bound > upper_bound || lower_bound < 0) {
        log_error("Invalid parameters for allocation.");
        return -1;
    }

    size_t total_memory = offsets_length * sizeof(long) + keys_length * sizeof(int) +
                          records_length * sizeof(record);

    if (total_memory > MEMORY_LIMIT) {
        log_error("Exceeded memory limit.");
        return -2;
    }

    AlignedMemory aligned_offsets = allocate_aligned(offsets_length * sizeof(long));
    if (!aligned_offsets.ptr) {
        log_error("Failed to allocate offsets array.");
        return -3;
    }
    if (!validate_memory(aligned_offsets.ptr, offsets_length * sizeof(long), "offsets")) {
        free_resources(data);
        return -4;
    }

    AlignedMemory aligned_keys = allocate_aligned(keys_length * sizeof(int));
    if (!aligned_keys.ptr) {
        log_error("Failed to allocate keys array.");
        free_resources(data);
        return -5;
    }
    if (!validate_memory(aligned_keys.ptr, keys_length * sizeof(int), "keys")) {
        free_resources(data);
        return -6;
    }

    AlignedMemory aligned_records = allocate_aligned(records_length * sizeof(record));
    if (!aligned_records.ptr) {
        log_error("Failed to allocate records array.");
        free_resources(data);
        return -7;
    }
    if (!validate_memory(aligned_records.ptr, records_length * sizeof(record), "records")) {
        free_resources(data);
        return -8;
    }

    data->offsets = aligned_offsets.ptr;
    data->offsets_length = offsets_length;

    data->keys = aligned_keys.ptr;
    data->keys_length = keys_length;

    data->records = aligned_records.ptr;
    data->records_length = records_length;

    for (size_t i = 0; i < records_length; ++i) {
        data->records[i].value = lower_bound + rand() % (upper_bound - lower_bound + 1);
    }

    return 0;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int validate_memory(void* ptr, size_t size, const char* description) {
    if (!ptr || !memset(ptr, 0xAA, size)) {
        log_error("Memory validation failed for ");
        log_error(description);
        return 0;
    }
    return 1;
}

void free_resources(AllocatedData* data) {
    if (data->offsets) _aligned_free(data->offsets);
    if (data->keys) _aligned_free(data->keys);
    if (data->records) _aligned_free(data->records);
}
