}

void free_data_structures(DataStructures* ds) {
    if (!ds) return;

    pthread_mutex_lock(&ds->mutex);

    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);

    for (size_t i = 0; i < ds->rows; ++i) {
        if (ds->matrix[i]) free(ds->matrix[i]);
