    if (ds->matrix) free(ds->matrix);

    node* current = ds->head;
    while (current) {
        node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&ds->mutex);

    pthread_mutex_destroy(&ds->mutex);
    free(ds);
