#define MAX_RETRY 3

typedef struct {
    int value;
} record;

typedef union {
    long* offsetArray;
    int* keyArray;
    record* recordArray;
    uint8_t padding[16]; // Align to 16 bytes
} MemoryUnion;

// Function prototypes
MemoryUnion allocateAndInitialize(int length, int seed, int minVal, int maxVal, size_t systemLimit);
int verifyDataIntegrity(MemoryUnion mu, int length, int seed, int minVal, int maxVal);
size_t getDynamicSystemLimit();
void* alignedAlloc(size_t size, size_t alignment);

// Function to manage dynamic memory allocation
MemoryUnion allocateAndInitialize(int length, int seed, int minVal, int maxVal, size_t systemLimit) {
    MemoryUnion mu = {0};
    int attempts = 0;
    size_t totalSize;

    while (attempts < MAX_RETRY) {
        totalSize = sizeof(long) * length + sizeof(int) * length + length * sizeof(record);

        // Ensure alignment
        if ((totalSize % 16) != 0) {
            totalSize += 16 - (totalSize % 16);
        }

        if (totalSize <= systemLimit) {
            mu.offsetArray = (long*)alignedAlloc(length * sizeof(long), 16);
            mu.keyArray = (int*)alignedAlloc(length * sizeof(int), 16);
            mu.recordArray = (record*)alignedAlloc(length * sizeof(record), 16);

            if (mu.offsetArray && mu.keyArray && mu.recordArray) {
                srand(seed);
                for (int i = 0; i < length; ++i) {
                    mu.offsetArray[i] = rand();
                    mu.keyArray[i] = rand();
                    mu.recordArray[i].value = minVal + rand() % (maxVal - minVal + 1);
                }

                if (verifyDataIntegrity(mu, length, seed, minVal, maxVal)) {
                    return mu;
                }
            }
        }

        systemLimit = getDynamicSystemLimit();
        attempts++;
    }

    // Clean up on failure
    free(mu.offsetArray);
    free(mu.keyArray);
    free(mu.recordArray);

    return mu; // Returns zeroed union if failed
}

// Function to verify data integrity
int verifyDataIntegrity(MemoryUnion mu, int length, int seed, int minVal, int maxVal) {
    srand(seed);
    for (int i = 0; i < length; ++i) {
        int expectedValue = minVal + rand() % (maxVal - minVal + 1);
        if (mu.recordArray[i].value != expectedValue) {
            return 0;
        }
    }
    return 1;
}

// Function to get dynamic system memory limit
size_t getDynamicSystemLimit() {
    // Placeholder for external data source integration
    // Simulate adjustment based on system load
    return 1024 * 1024; // Example: 1 MB
}

// Aligned memory allocation function
void* alignedAlloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}
