#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdint.h>
#include <time.h>

#define ALIGNMENT 32
#define MAX_UINT8_T 255

typedef struct {
    char string[16];
} Item;

typedef struct ItemNode {
    int key;
    Item *item;
    struct ItemNode *next;
} ItemNode;

typedef struct Node {
    double value;
    ItemNode *items_head;
} Node;

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Helper function to allocate aligned memory
void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Helper function to free aligned memory
void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Helper function to generate a random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length - 1; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length - 1] = '\0';
}

// Function to initialize nodes and items
void init_data_structures(Node **nodes, size_t num_nodes, unsigned int min_random, unsigned int max_random, size_t num_items_per_node) {
    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i] = aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Memory allocation failed for Node %zu\n", i);
            exit(EXIT_FAILURE);
        }

        unsigned int random_val = rand() % (max_random - min_random + 1) + min_random;
        nodes[i]->value = sqrt(random_val);

        ItemNode *current_item = NULL;
        for (size_t j = 0; j < num_items_per_node; ++j) {
            ItemNode *new_item_node = aligned_alloc(ALIGNMENT, sizeof(ItemNode));
            if (!new_item_node) {
                fprintf(stderr, "Memory allocation failed for ItemNode in Node %zu\n", i);
                exit(EXIT_FAILURE);
            }

            new_item_node->key = rand();
            new_item_node->item = aligned_alloc(ALIGNMENT, sizeof(Item));
            if (!new_item_node->item) {
                fprintf(stderr, "Memory allocation failed for Item in Node %zu\n", i);
                aligned_free(new_item_node);
                exit(EXIT_FAILURE);
            }

            generate_random_string(new_item_node->item->string, 16);

            new_item_node->next = NULL;
            if (current_item == NULL) {
                nodes[i]->items_head = new_item_node;
            } else {
                current_item->next = new_item_node;
            }
            current_item = new_item_node;
        }
    }
}

// Function to initialize NFAPI_CRC_INDICATION_PDU_T structures
void init_nfa_crc_indications(NFAPI_CRC_INDICATION_PDU_T **indictions, size_t num_indications) {
    size_t crcflag_failures = 0;

    for (size_t i = 0; i < num_indications; ++i) {
        *indictions = aligned_alloc(ALIGNMENT, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*indictions) {
            fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T %zu\n", i);
            exit(EXIT_FAILURE);
        }

        (*indictions)->RX_UE_INFORMATION_TAG = rand() % 256;
        (*indictions)->RNTI = rand();
        (*indictions)->CRC_INDICATION_REL8_TAG = rand() % 256;

        uint8_t crcflag = rand() % (MAX_UINT8_T + 1);
        if (crcflag > MAX_UINT8_T) {
            crcflag_failures++;
            fprintf(stderr, "Invalid CRCFLAG value encountered\n");
        }
        (*indictions)->CRCFLAG = crcflag;

        indictions++;
    }

    printf("Number of CRCFLAG validation failures: %zu\n", crcflag_failures);
}

// Test runner function
void run_test(const char *label, void (*f)(void)) {
    printf("Running test: %s\n", label);
    f();
    printf("Test completed: %s\n", label);
}

int main() {
    srand(time(NULL));

    size_t num_nodes = 10;
    unsigned int min_random = 1;
    unsigned int max_random = 100;
    size_t num_items_per_node = 5;
    size_t num_indications = 20;

    Node *nodes[num_nodes];
    NFAPI_CRC_INDICATION_PDU_T *indictions = NULL;

    run_test("Initialize Data Structures", ^{
        init_data_structures(nodes, num_nodes, min_random, max_random, num_items_per_node);
    });

    run_test("Initialize CRC Indications", ^{
        init_nfa_crc_indications(&indictions, num_indications);
    });

    // Cleanup
    for (size_t i = 0; i < num_nodes; ++i) {
        ItemNode *current_item = nodes[i]->items_head;
        while (current_item != NULL) {
            ItemNode *next_item = current_item->next;
            aligned_free(current_item->item);
            aligned_free(current_item);
            current_item = next_item;
        }
        aligned_free(nodes[i]);
    }

    for (size_t i = 0; i < num_indications; ++i) {
        aligned_free(indictions + i);
    }

    return 0;
}
