// Constants
#define MAX_MEMORY_USAGE 1048576 // 1 MB in bytes
#define STRING_LENGTH 256
#define RANDOM_MIN 0
#define RANDOM_MAX 100
#define CHAR_INIT_VALUE 'A'

typedef union {
    double d;
    char *s;
} DataUnion;

typedef struct item {
    size_t size;
    DataUnion data;
} Item;

typedef struct record {
    int value;
    char identifier[STRING_LENGTH];
    time_t current_time;
    struct record *prev_state;
    Item *item;
} Record;

// Global variables for logging and connection state
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
long total_memory_usage = 0;

void log_memory_usage() {
    pthread_mutex_lock(&memory_lock);
    printf("Total Memory Usage: %ld bytes\n", total_memory_usage);
    pthread_mutex_unlock(&memory_lock);
}

// Function to initialize records with constraints
void initialize_records(int record_count) {
    Record *records[record_count];
    int i;

    for (i = 0; i < record_count; ++i) {
        // Allocate memory and ensure it fits within the limit
        pthread_mutex_lock(&memory_lock);
        if (total_memory_usage + sizeof(Record) > MAX_MEMORY_USAGE) {
            printf("Memory limit exceeded. Releasing LRU records.\n");
            while (total_memory_usage + sizeof(Record) > MAX_MEMORY_USAGE && i >= 0) {
                free(records[--i]->item->data.s);
                free(records[i]->item);
                total_memory_usage -= sizeof(Record);
            }
        }

        Record *record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }

        total_memory_usage += sizeof(Record);

        // Initialize fields
        record->value = rand() % 100; // Example initialization
        snprintf(record->identifier, STRING_LENGTH, "ID_%d", i);
        time(&record->current_time);
