        }

        strcpy(item->data.s, "default_string"); // Initialize char string
        total_memory_usage += STRING_LENGTH;

        records[i] = record;
    }

    log_memory_usage();
}

// Function to clean up allocated memory
void cleanup_records(Record **records, int count) {
