                dep->task_id = rand_r(&seed) % num_tasks; // Unique task ID
                dep->weight = random_float(0.1f, 5.0f); // Random weight in range [0.1, 5.0)
                dep->next = task->dependencies;
                task->dependencies = dep;
            }

            // Insert task into the linked list
            task->next = project->tasks;
            project->tasks = task;
        }
        pthread_mutex_unlock(&lock);
        return project;
    }

