#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

typedef enum { SUCCESS = 0, ERROR } status_t;

status_t initialize_arrays(long size, int range_min, int range_max);
void clear_memory(long *offsets, int *keys, record_t *records, long size);

// Mutex for thread safety
pthread_mutex_t lock;

status_t initialize_arrays(long size, int range_min, int range_max) {
    pthread_mutex_lock(&lock);

    if (size <= 0) {
        printf("Size must be greater than zero.\n");
        pthread_mutex_unlock(&lock);
        return ERROR;
    }

    // Calculate total memory requirement
    long total_memory = sizeof(long) * size + sizeof(int) * size + sizeof(record_t) * size;

    // Check system memory limits (simplified)
    if (total_memory > SIZE_MAX / 2) {
        printf("Memory allocation exceeds safe limit.\n");
        pthread_mutex_unlock(&lock);
        return ERROR;
    }

    long *offsets = malloc(sizeof(long) * size);
    int *keys = malloc(sizeof(int) * size);
    record_t *records = malloc(sizeof(record_t) * size);

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return ERROR;
    }

    // Initialize arrays
    for (long i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = i;

        records[i].value = range_min + rand() % (range_max - range_min + 1);

        // Verify initialization
        if ((offsets[i] != i) || (keys[i] != i) ||
            (records[i].value < range_min || records[i].value > range_max)) {
            printf("Initialization verification failed.\n");
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_unlock(&lock);
            return ERROR;
        }
    }

    // Simulate further operations...

    clear_memory(offsets, keys, records, size);

    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

void clear_memory(long *offsets, int *keys, record_t *records, long size) {
    free(offsets);
    free(keys);
    free(records);
}

// Unit tests
void test_initialize_arrays() {
    srand(time(NULL));

    printf("Test 1: Normal case\n");
    initialize_arrays(10, 0, 100);

    printf("Test 2: Zero size\n");
    initialize_arrays(0, 0, 100);

    printf("Test 3: Large range\n");
    initialize_arrays(5, -1000000, 1000000);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    test_initialize_arrays();

    pthread_mutex_destroy(&lock);
    return 0;
}
