typedef struct CacheNode {
    size_t length;
    void *memory;
    struct CacheNode *next;
} CacheNode;

CacheNode *cache_head = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* cache_alloc(size_t length, size_t chunk_size) {
    pthread_mutex_lock(&cache_lock);
    for (CacheNode *node = cache_head; node != NULL; node = node->next) {
        if (node->length >= length && strlen(node->memory) >= length + 1) {
            void* memory = memmove(node->memory, node->memory + chunk_size, length + 1);
            pthread_mutex_unlock(&cache_lock);
            return memory;
        }
    }

    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->length = length;
    new_node->memory = malloc(length + 1);
    memset(new_node->memory, 0, length + 1);

    new_node->next = cache_head;
    cache_head = new_node;

    pthread_mutex_unlock(&cache_lock);
    return new_node->memory;
}

void init_random_seed() {
    srand(time(NULL)); // Use environment variable or command-line options to set the seed
}

int generate_unique_keys(int keys_size, int *keys) {
