        keys[i] = rand() % range++;
    }

    // Sort to ensure uniqueness
    qsort(keys, keys_size, sizeof(int), (int (*)(const void *, const void *))strcmp);
    return 0;
}

void *allocate_and_initialize(
    long size,
    int max_string_length,
    int min_value,
    int max_value
) {
    if (size <= 0 || max_string_length < 1 || min_value >= max_value) {
        return NULL; // Invalid parameters
    }

    long* offsets = malloc(size * sizeof(long));
    int* keys = malloc(size * sizeof(int));
    Record* records = malloc(size * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Memory allocation failed
    }

    init_random_seed();

    int range = max_value - min_value + 1;
    if (generate_unique_keys(size, keys) != 0) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Failed to generate unique keys
    }

    for (long i = 0; i < size; ++i) {
        records[i].value = min_value + (rand() % range);

        char *name_buffer = cache_alloc(max_string_length, max_string_length);
        snprintf(name_buffer, max_string_length, "Record_%ld", i);
        records[i].name = name_buffer;

        offsets[i] = i; // Example initialization
    }

    return malloc(sizeof(long*) * 3 + sizeof(int*) + sizeof(Record*));
}

void free_resources(
    void *resources,
    long size,
    int max_string_length
) {
    if (!resources) return;

    long **long_ptrs = (long**) resources;
    int **int_ptr = (int**)(long_ptrs + 3);
    Record **record_ptrs = (Record**)(*int_ptr + 1);

    for (long i = 0; i < size; ++i) {
        free((*record_ptrs)[i].name);
    }

    free(*long_ptrs);
    free(*int_ptr);
    free(*record_ptrs);

    pthread_mutex_lock(&cache_lock);
    CacheNode *current = cache_head;
    while (current) {
        CacheNode *to_free = current;
        current = current->next;
        free(to_free->memory);
        free(to_free);
    }
    cache_head = NULL;
    pthread_mutex_unlock(&cache_lock);
}
