#include <time.h>

#define ALIGNMENT 32
#define ITEM_STRING_LENGTH 16
#define MAX_ITEMS_PER_NODE 10
#define NUM_NODES 100
#define ERROR_CODE -1

typedef struct Item {
    int key;
    char string[ITEM_STRING_LENGTH + 1];
} Item;

typedef struct Node {
    double value;
    int id;
    Item* items[MAX_ITEMS_PER_NODE];
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void align_malloc(size_t size, void** ptr) {
    void* raw_ptr;
    if (posix_memalign(&raw_ptr, ALIGNMENT, size)) {
        *ptr = NULL;
        return;
    }
    *ptr = raw_ptr;
}

int allocate_node(Node** head) {
    pthread_mutex_lock(&mutex);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&mutex);
        return ERROR_CODE;
    }

    // Align and initialize items
    for (int i = 0; i < MAX_ITEMS_PER_NODE; ++i) {
        Item* item = (Item*)aligned_alloc(ALIGNMENT, sizeof(Item));
        if (!item) {
            free(new_node);
            pthread_mutex_unlock(&mutex);
            return ERROR_CODE;
        }
        new_node->items[i] = item;
    }

    // Add node to the list
    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&mutex);
    return 0;
}

void initialize_node(Node* node, int id_range_min, int id_range_max) {
    srand(time(NULL) + node->id);

    node->value = ((double)rand() / RAND_MAX) * (id_range_max - id_range_min) + id_range_min;

    for (int i = 0; i < MAX_ITEMS_PER_NODE; ++i) {
        node->items[i]->key = rand();
        for (int j = 0; j < ITEM_STRING_LENGTH; ++j) {
            node->items[i]->string[j] = rand() % 26 + 'A';
        }
        node->items[i]->string[ITEM_STRING_LENGTH] = '\0';
    }
}

void clear_memory(Node* head, long* offsets, int* keys, void** records, size_t record_count) {
    Node* current = head;
    while (current) {
        Node* next_node = current->next;

        for (int i = 0; i < MAX_ITEMS_PER_NODE; ++i) {
            free(current->items[i]);
        }
        free(current);
        current = next_node;
    }

    free(offsets);
    free(keys);
    free(records);
}

void allocate_and_initialize_system(Node** head, long* offsets, int* keys, void** records, size_t record_count, 
                                   int id_range_min, int id_range_max) {

    if (allocate_node(head)) {
        fprintf(stderr, "Error allocating node\n");
        exit(ERROR_CODE);
    }

    for (int i = 0; i < NUM_NODES; ++i) {
        allocate_node(head);
    }

    Node* current = *head;
    while (current) {
        initialize_node(current, id_range_min, id_range_max);
        current = current->next;
    }

    // Allocate and initialize offsets
    align_malloc(record_count * sizeof(long), (void**)&offsets);
    for (size_t i = 0; i < record_count; ++i) {
        offsets[i] = i;
    }

    // Allocate and initialize keys
    align_malloc(record_count * sizeof(int), (void**)&keys);
    for (size_t i = 0; i < record_count; ++i) {
        keys[i] = rand();
    }

    // Allocate and initialize records
    align_malloc(record_count * sizeof(void*), &records);
    for (size_t i = 0; i < record_count; ++i) {
        int* value = malloc(sizeof(int));
        if (!value) {
            clear_memory(*head, offsets, keys, records, record_count);
            exit(ERROR_CODE);
        }
        *value = rand() % 100;
        records[i] = value;
    }
}

int main() {
    Node* head = NULL;
    long* offsets = NULL;
    int* keys = NULL;
    void** records = NULL;
    size_t record_count = 50;

    allocate_and_initialize_system(&head, offsets, keys, records, record_count, 0.0, 100.0);

    // Use the system ...

    clear_memory(head, offsets, keys, records, record_count);

    return 0;
}
