#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Example system memory limit in bytes

typedef struct {
    int value;
    long* offset_ptr;
} record;

void free_resources(long* offsets, int* keys, record* records, size_t num_records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int check_memory_constraints(size_t num_offsets, size_t num_keys, size_t num_records) {
    // Memory usage: sizeof(long) * num_offsets + sizeof(int) * num_keys
    //               + num_records * (sizeof(record) + sizeof(long))
    long memory_usage = 
        num_offsets * sizeof(long) +
        num_keys * sizeof(int) +
        num_records * (sizeof(record) + sizeof(long));

    return memory_usage <= MAX_MEMORY_USAGE;
}

int initialize_data(size_t num_offsets, size_t num_keys, record** records_ptr) {
    if (!check_memory_constraints(num_offsets, num_keys, num_keys)) {
        fprintf(stderr, "Memory limit exceeded. Cannot allocate required resources.\n");
        return 0;
    }

    long* offsets = (long*)calloc(num_offsets, sizeof(long));
    int* keys = (int*)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Failed to allocate memory for offsets or keys.\n");
        free_resources(offsets, keys, NULL, num_keys);
        return 0;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i + 1;
    }

    record* records = (record*)malloc(num_keys * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free_resources(offsets, keys, NULL, num_keys);
        return 0;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < num_keys; ++i) {
        records[i].value = rand() % 100 + 1;
        if (i < num_offsets) {
            records[i].offset_ptr = &offsets[i];
        } else {
            records[i].offset_ptr = NULL; // Handle pointer validity
        }
    }

    *records_ptr = records;

    for (size_t i = 0; i < num_keys; ++i) {
        if (records[i].offset_ptr && (*records[i].offset_ptr == 0)) { 
            fprintf(stderr, "Invalid offset pointer at index %zu\n", i);
            free_resources(offsets, keys, records, num_keys);
            return 0;
        }
    }

    printf("Data initialized successfully.\n");

    // Return all allocated resources for the caller to manage
    return (int)(size_t)offsets + (size_t)keys + (size_t)records; 
}

void cleanup(int memory_handles, long* offsets, int* keys, record* records, size_t num_records) {
    free_resources(offsets, keys, records, num_records);
}

int main() {
    size_t num_offsets = 100;
    size_t num_keys = 150;

    if (num_keys > num_offsets) {
        fprintf(stderr, "Number of keys cannot exceed number of offsets.\n");
        return 1;
    }

    record* records = NULL;
    int memory_handles = initialize_data(num_offsets, num_keys, &records);

    if (!memory_handles) {
        return 1; // Initialization failed
    }

    // Use data...

    cleanup(memory_handles, (long*)memory_handles, (int*)(memory_handles + sizeof(long)*num_offsets),
            records, num_keys);

    return 0;
}
