#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define ALIGNMENT 64
#define MAX_CHILDREN 10
#define KEY_RANGE_LOW 1
#define KEY_RANGE_HIGH 100

typedef struct ListNode {
    struct TreeNode* node;
    struct ListNode* prev;
    struct ListNode* next;
} ListNode;

typedef struct TreeNode {
    int key;
    uint32_t reference_count;
    ListNode* children_head;
    ListNode* children_tail;
} TreeNode;

void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    if ((intptr_t(ptr = memalign(alignment, size))) == -1) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

uint32_t rand_range(uint32_t low, uint32_t high) {
    return low + (rand() % (high - low + 1));
}

char* generate_hex_string(size_t length) {
    char* str = aligned_alloc((length + 1) * sizeof(char), ALIGNMENT);
    if (!str) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < length; ++i) {
        str[i] = (char)(rand() % 16 + '0');
        if (str[i] > '9') {
            str[i] += ('a' - 'A' - 10);
        }
    }
    str[length] = '\0';
    return str;
}

ListNode* create_list_node(TreeNode* node) {
    ListNode* list_node = aligned_alloc(sizeof(ListNode), ALIGNMENT);
    if (!list_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    list_node->node = node;
    list_node->prev = NULL;
    list_node->next = NULL;
    return list_node;
}

void add_child(TreeNode* parent, TreeNode* child) {
    ListNode* new_list_node = create_list_node(child);
    if (!parent->children_head) {
        parent->children_head = parent->children_tail = new_list_node;
    } else {
        parent->children_tail->next = new_list_node;
        new_list_node->prev = parent->children_tail;
        parent->children_tail = new_list_node;
    }
}

TreeNode* create_tree(int depth, int max_depth) {
    if (depth > max_depth || depth < 0) return NULL;

    TreeNode* node = aligned_alloc(sizeof(TreeNode), ALIGNMENT);
    if (!node) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    node->key = depth * rand_range(KEY_RANGE_LOW, KEY_RANGE_HIGH);
    node->reference_count = 1;
    node->children_head = NULL;
    node->children_tail = NULL;

    for (int i = 0; i < MAX_CHILDREN && depth < max_depth; ++i) {
        TreeNode* child_node = create_tree(depth + 1, max_depth);
        if (child_node) {
            add_child(node, child_node);
        }
    }

    char* hex_str = generate_hex_string(depth + 2); // Example length: based on depth
    printf("Node Key: %d, Hex String: %s\n", node->key, hex_str);

    free(hex_str);
    return node;
}

void destroy_tree(TreeNode* root) {
    if (!root) return;

    ListNode* current = root->children_head;
    while (current) {
        ListNode* next = current->next;
        destroy_tree(current->node);
        free_aligned(current);
        current = next;
    }

    free_aligned(root);
}

void verify_tree_integrity(TreeNode* node, int expected_depth) {
    if (!node) return;

    if (node->key != expected_depth * rand_range(KEY_RANGE_LOW, KEY_RANGE_HIGH)) {
        fprintf(stderr, "Integrity check failed at depth %d\n", expected_depth);
        exit(EXIT_FAILURE);
    }

    ListNode* current = node->children_head;
    int depth = 1;
    while (current && depth <= MAX_CHILDREN) {
        verify_tree_integrity(current->node, expected_depth + 1);
        current = current->next;
        ++depth;
    }
}

int main() {
    srand(time(NULL));

    int max_depth = 5; // Example depth
    TreeNode* root = create_tree(0, max_depth);

    if (root) {
        verify_tree_integrity(root, 0);
        destroy_tree(root);
    }

    return 0;
}
