int verify_integrity(DeviceSensorStruct *devices, int count) {
    for (int i = 0; i < count; ++i) {
        if ((uintptr_t)(devices + i) % ALIGNMENT != 0) return -1;
        if (!devices[i].data.sensor_reading || !devices[i].config.configuration_flag) return -2;
    }
    return 0;
}

DeviceSensorStruct* initialize_device_sensor_structs(int count, int *success) {
    DeviceSensorStruct *devices = NULL;
    struct timespec start, end;

    clock_gettime(CLOCK_MONOTONIC, &start);

    devices = aligned_alloc(count * sizeof(DeviceSensorStruct), ALIGNMENT);
    if (!devices) {
        printf("Memory allocation failed.\n");
        *success = 0;
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        devices[i].timestamp = time(NULL);
        devices[i].device_id = i + 1;
        devices[i].data.sensor_reading = rand() % 100; // Example initialization
        devices[i].config.configuration_flag = 1;
        devices[i].config.calibration_factor = 1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double time_taken = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

    printf("Time taken for allocation and initialization: %f seconds\n", time_taken);

    if (verify_integrity(devices, count) != 0) {
        aligned_free(devices);
        *success = 0;
        return NULL;
    }

    *success = 1;
    return devices;
}

void free_device_sensor_structs(DeviceSensorStruct *devices) {
    aligned_free(devices);
}

int main() {
    int device_count = 10; // Example: number of active devices
    DeviceSensorStruct *sensor_data = NULL;
