void initializeData(long numOffsets, int numKeys, record **records) {
    if (numOffsets <= 0 || numKeys <= 0) {
        fprintf(stderr, "Error: numOffsets and numKeys must be positive.\n");
        return;
    }

    // Allocate memory for offset and keys
    long *offsets = (long *)malloc(numOffsets * sizeof(long));
    int *keys = (int *)malloc(numKeys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets and keys with dummy values (e.g., indices)
    for (long i = 0; i < numOffsets; ++i) {
        offsets[i] = i;
    }
    for (int j = 0; j < numKeys; ++j) {
        keys[j] = j;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for records
    *records = (record *)malloc(numOffsets * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records
    for (long i = 0; i < numOffsets; ++i) {
        (*records)[i].offsetPtr = &offsets[i];
        (*records)[i].keyPtr = &keys[i % numKeys]; // Circular assignment for demonstration
        (*records)[i].value = rand() % 1001;
    }

    // Free the dynamically allocated memory (offsets and keys are not freed here because they are referenced by records)
}

void freeRecords(record *records, long numOffsets) {
    if (!records) return;

    // Since offsets and keys were assigned via references in records, no additional deallocation is required here
    free(records);
}
