#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t mutex;
    int *keys;
    int *frequencies;
    size_t size;
} hash_table;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    hash_table *hash_table;
    pthread_rwlock_t rwlock; // Read-write lock for thread-safe access
    size_t total_size;
    size_t max_limit;
} data_structure;

int initialize_data_structure(data_structure *ds, size_t num_elements, size_t max_limit) {
    if (num_elements == 0 || ds == NULL) return -1;

    size_t offset_array_size = sizeof(long) * num_elements;
    size_t key_array_size = sizeof(int) * num_elements;
    size_t record_array_size = sizeof(record) * num_elements;
    size_t hash_table_keys_size = sizeof(int) * num_elements;
    size_t hash_table_frequencies_size = sizeof(int) * num_elements;

    ds->max_limit = max_limit;
    pthread_rwlock_init(&ds->rwlock, NULL);

    // Allocate memory for arrays
    ds->offsets = (long *)malloc(offset_array_size);
    if (!ds->offsets) goto cleanup_and_exit;

    ds->keys = (int *)malloc(key_array_size);
    if (!ds->keys) goto cleanup_and_exit;

    ds->records = (record *)malloc(record_array_size);
    if (!ds->records) goto cleanup_and_exit;

    // Initialize hash table
    ds->hash_table = (hash_table *)malloc(sizeof(hash_table));
    if (!ds->hash_table) goto cleanup_and_exit;

    pthread_mutex_init(&ds->hash_table->mutex, NULL);
    ds->hash_table->keys = (int *)calloc(num_elements, sizeof(int));
    if (!ds->hash_table->keys) goto cleanup_and_exit;

    ds->hash_table->frequencies = (int *)calloc(num_elements, sizeof(int));
    if (!ds->hash_table->frequencies) goto cleanup_and_exit;

    ds->hash_table->size = num_elements;

    // Calculate total allocated memory
    size_t total_allocated_size = offset_array_size + key_array_size +
                                  record_array_size + sizeof(hash_table) +
                                  hash_table_keys_size + hash_table_frequencies_size;
    if (total_allocated_size > max_limit) {
        goto cleanup_and_exit;
    }

    ds->total_size = total_allocated_size;

    // Randomly shuffle records
    srand(time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        int j = rand() % num_elements;
        record temp_record = ds->records[i];
        ds->records[i] = ds->records[j];
        ds->records[j] = temp_record;

        // Swap keys too
        int temp_key = ds->keys[i];
        ds->keys[i] = ds->keys[j];
        ds->keys[j] = temp_key;

        long temp_offset = ds->offsets[i];
        ds->offsets[i] = ds->offsets[j];
        ds->offsets[j] = temp_offset;
    }

    return 0; // Success

cleanup_and_exit:
    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);
    if (ds->hash_table) {
        pthread_mutex_destroy(&ds->hash_table->mutex);
        free(ds->hash_table->keys);
        free(ds->hash_table->frequencies);
        free(ds->hash_table);
    }
    pthread_rwlock_destroy(&ds->rwlock);
    return -1; // Error
}

void cleanup_data_structure(data_structure *ds) {
    if (!ds) return;

    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);

    if (ds->hash_table) {
        pthread_mutex_destroy(&ds->hash_table->mutex);
        free(ds->hash_table->keys);
        free(ds->hash_table->frequencies);
        free(ds->hash_table);
    }

    pthread_rwlock_destroy(&ds->rwlock);
}

int main() {
    size_t num_elements = 1000;
    size_t max_limit = 1024 * 1024; // 1 MB
    data_structure ds;

    if (initialize_data_structure(&ds, num_elements, max_limit) == 0) {
        printf("Data structure initialized successfully.\n");
    } else {
        printf("Failed to initialize data structure.\n");
    }

    cleanup_data_structure(&ds);
    return 0;
}
