typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU* head;
    pthread_mutex_t lock;
} Linked_List;

int is_valid_rnti(int rnti, int min, int max) {
    // Placeholder for actual validation logic
    return (rnti >= min && rnti <= max);
}

int generate_random_number(int min, int max) {
    // Placeholder for random number generation
    return rand() % (max - min + 1) + min;
}

Linked_List* create_linked_list(int num_elements, int rnti_min, int rnti_max) {
    Linked_List* list = (Linked_List*)malloc(sizeof(Linked_List));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;

    int *used_rntis = (int *)calloc((rnti_max - rnti_min + 1), sizeof(int));

    for (int i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&list->lock);

        NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!new_node) {
            // Handle allocation failure
            pthread_mutex_unlock(&list->lock);
            continue;
        }

        int rnti, rx_ue_tag, crc_rel8_tag;

        do {
            rnti = generate_random_number(rnti_min, rnti_max);
        } while (used_rntis[rnti - rnti_min] != 0 || !is_valid_rnti(rnti, rnti_min, rnti_max));

        used_rntis[rnti - rnti_min] = 1;

        rx_ue_tag = generate_random_number(0, 100); // Example range
        crc_rel8_tag = generate_random_number(0, 100); // Example range
        new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
        new_node->RNTI = rnti;
        new_node->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
        new_node->CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        new_node->next = list->head;
        list->head = new_node;

        pthread_mutex_unlock(&list->lock);
    }

    free(used_rntis);
    return list;
}

void destroy_linked_list(Linked_List* list) {
    if (!list) return;

    NFAPI_CRC_INDICATION_PDU *current, *next;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    int num_elements = 1000;
    int rnti_min = 1, rnti_max = 500;

    Linked_List* list = create_linked_list(num_elements, rnti_min, rnti_max);

    // Use the linked list as needed

    destroy_linked_list(list);
    return 0;
}
