#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DESCRIPTION_LEN 256

struct Node {
    int priority;
    struct Node* child;
};

struct Task {
    struct Node* root;
    char* description;
    int estimatedTime;
};

void initializeRandom() {
    srand((unsigned int) time(NULL));
}

int generateRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

struct Node* createNode() {
    struct Node* node = (struct Node*) malloc(sizeof(struct Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for Node.\n");
        exit(EXIT_FAILURE);
    }
    node->priority = generateRandom(1, 1000);
    node->child = NULL; // Child can be set later
    return node;
}

struct Task* createTask(const char* description) {
    struct Task* task = (struct Task*) malloc(sizeof(struct Task));
    if (!task) {
        fprintf(stderr, "Memory allocation failed for Task.\n");
        exit(EXIT_FAILURE);
    }
    task->root = createNode();
    task->description = (char*) malloc(MAX_DESCRIPTION_LEN * sizeof(char));
    if (!task->description) {
        fprintf(stderr, "Memory allocation failed for Task description.\n");
        free(task->root); // Clean up allocated Node
        exit(EXIT_FAILURE);
    }
    strncpy(task->description, description, MAX_DESCRIPTION_LEN - 1);
    task->description[MAX_DESCRIPTION_LEN - 1] = '\0';
    task->estimatedTime = generateRandom(0, 1000);
    return task;
}

void freeNode(struct Node* node) {
    if (node) {
        freeNode(node->child); // Recursively free child nodes
        free(node);
    }
}

void freeTasks(struct Task** tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; ++i) {
        free(tasks[i]->description);
        freeNode(tasks[i]->root);
        free(tasks[i]);
    }
    free(tasks);
}

struct Task* initializeData(int num_nodes, int num_tasks) {
    if (num_nodes <= 0 || num_tasks <= 0) return NULL;

    struct Task** tasks = (struct Task**) malloc(num_tasks * sizeof(struct Task*));
    if (!tasks) {
        fprintf(stderr, "Memory allocation failed for Tasks array.\n");
        exit(EXIT_FAILURE);
    }

    initializeRandom();

    // Initialize nodes and tasks
    for (int i = 0; i < num_tasks; ++i) {
        char description[50];
        snprintf(description, sizeof(description), "Task %d", i + 1);
        tasks[i] = createTask(description);

        // Optionally connect children to form a tree or any other structure
        struct Node* current_node = tasks[i]->root;
        for (int j = 0; j < num_nodes - 1 && current_node != NULL; ++j) {
            struct Node* new_child = createNode();
            current_node->child = new_child;
            current_node = new_child;
        }
    }

    return (struct Task*) tasks;
}

void cleanupData(struct Task** tasks, int num_tasks) {
    if (!tasks) return;
    freeTasks(tasks, num_tasks);
}
