    int num_nodes = 5; // Number of nodes per task tree
    int num_tasks = 3; // Total number of tasks

    struct Task* tasks = initializeData(num_nodes, num_tasks);

    if (tasks) {
        for (int i = 0; i < num_tasks; ++i) {
            printf("Task %d: %s, Estimated Time: %d\n", 
                i + 1, tasks[i]->description, tasks[i]->estimatedTime);
        }
        cleanupData((struct Task**)tasks, num_tasks); // Clean up memory
    }

    return 0;
}
