#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    char *data;          // Alphanumeric identifier
    int priority;        // Initialized based on a seed for pseudo-random number generation
    int priorityLevel;   // Random number between 0 and 1000, inclusive
    record *pRecord;     // Pointer to a `record` structure with random value initialization
} node;

// Function prototypes
node* initialize_nodes(size_t count, unsigned int seed);
void free_resources(node *nodes, size_t count);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

node* initialize_nodes(size_t count, unsigned int seed) {
    if (count == 0 || !seed) return NULL;

    pthread_mutex_lock(&lock);

    // Seed the random number generator
    srand(seed);

    node *nodes = malloc(count * sizeof(node));
    long *fileOffsets = malloc(count * sizeof(long));
    int *uniqueIDs = malloc(count * sizeof(int));

    if (!nodes || !fileOffsets || !uniqueIDs) {
        fprintf(stderr, "Memory allocation failed\n");
        free(nodes);
        free(fileOffsets);
        free(uniqueIDs);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        // Allocate and initialize unique alphanumeric identifier
        nodes[i].data = malloc(11); // Assuming length of 10 characters + '\0'
        if (!nodes[i].data) {
            fprintf(stderr, "Memory allocation failed for data field\n");
            free_resources(nodes, i);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        sprintf(nodes[i].data, "%010ld", (long)i);

        // Initialize priority based on seed
        nodes[i].priority = rand() % 100;

        // Randomize priorityLevel between 0 and 1000
        nodes[i].priorityLevel = rand() % 1001;

        // Allocate and initialize record with random value
        nodes[i].pRecord = malloc(sizeof(record));
        if (!nodes[i].pRecord) {
            fprintf(stderr, "Memory allocation failed for record\n");
            free_resources(nodes, i);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        nodes[i].pRecord->value = rand() % 1000; // Assuming range is [0, 999]

        // Initialize fileOffsets and uniqueIDs
        fileOffsets[i] = (long)(i * sizeof(node)); // Example offset calculation
        uniqueIDs[i] = (int)i;
    }

    pthread_mutex_unlock(&lock);

    // Log success for monitoring purposes
    printf("Successfully initialized %zu nodes\n", count);

    return nodes[0].pRecord; // Return pointer to first record as per requirement
}

void free_resources(node *nodes, size_t count) {
    if (!nodes) return;

    for (size_t i = 0; i < count; ++i) {
        if (nodes[i].data) free(nodes[i].data);
        if (nodes[i].pRecord) free(nodes[i].pRecord);
    }
    free(nodes);
}

int main() {
    size_t node_count = 10;
    unsigned int seed = time(NULL);

    // Initialize nodes and handle resource management
    record *records = initialize_nodes(node_count, seed);
    if (records == NULL) {
        fprintf(stderr, "Failed to initialize nodes\n");
        return EXIT_FAILURE;
    }

    // Use the records as needed...

    // Free resources after use
    node nodes_to_free[node_count];  // Assuming a fixed count for simplicity in this example
    memcpy(nodes_to_free, &records[0], sizeof(node) * node_count);
    free_resources(nodes_to_free, node_count);

    return EXIT_SUCCESS;
}
