#define MEMORY_THRESHOLD_MB (1024 * 10) // Example threshold of 10 MB

typedef enum { PENDING, IN_PROGRESS, COMPLETED } TaskStatus;
typedef struct Dependency {
    int task_id;
    float weight;
    struct Dependency* next;
} Dependency;

typedef struct Task {
    int id;
    int priority;
    TaskStatus status;
    Dependency* dependencies;
    struct Task* next;
} Task;

typedef struct Project {
    Task* tasks;
    pthread_mutex_t lock; // For thread safety
} Project;

// Function prototypes
Project* init_project();
void cleanup_project(Project* project);
Task* create_task(int id, int priority);
Dependency* add_dependency(Task* task, int task_id, float weight);
void update_task_status(Task* task, TaskStatus new_status);
void analyze_performance_and_scaling();
void handle_system_dependencies();

// Memory allocation with alignment
#define aligned_malloc(size) _aligned_malloc(size, ALIGNMENT)
#define aligned_free(ptr) _aligned_free(ptr)

Project* init_project() {
    Project* project = (Project*)aligned_malloc(sizeof(Project));
    assert(project != NULL);
    project->tasks = NULL;
    pthread_mutex_init(&project->lock, NULL);

    // Example: Add tasks and dependencies
    Task* task1 = create_task(1, 3);
    add_dependency(task1, 2, 0.5); // Sample dependency

    pthread_mutex_lock(&project->lock);
    task1->next = project->tasks;
    project->tasks = task1;
    pthread_mutex_unlock(&project->lock);

    return project;
}

void cleanup_project(Project* project) {
    Task* current_task = project->tasks;
    while (current_task != NULL) {
        Dependency* dep = current_task->dependencies;
        while (dep != NULL) {
            Dependency* temp_dep = dep;
            dep = dep->next;
            free(temp_dep);
        }
        Task* temp_task = current_task;
        current_task = current_task->next;
        free(temp_task);
    }

    pthread_mutex_destroy(&project->lock);
    aligned_free(project);
}

Task* create_task(int id, int priority) {
    Task* task = (Task*)aligned_malloc(sizeof(Task));
    assert(task != NULL);

    task->id = id;
    task->priority = priority;
    task->status = PENDING; // Initial status
    task->dependencies = NULL;

    return task;
}

Dependency* add_dependency(Task* task, int task_id, float weight) {
    Dependency* dep = (Dependency*)aligned_malloc(sizeof(Dependency));
    assert(dep != NULL);

    dep->task_id = task_id;
    dep->weight = weight;
    dep->next = task->dependencies;

    task->dependencies = dep;
    return dep;
}

void update_task_status(Task* task, TaskStatus new_status) {
