#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    TYPE_A,
    TYPE_B,
    TYPE_C,
} ItemType;

typedef struct {
    double value;
    ItemType type;
} Item;

#define ALIGNMENT 32

void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        return NULL;
    }
#else
    if ((posix_memalign(&ptr, alignment, size)) != 0) {
        return NULL;
    }
#endif
    return ptr;
}

int allocate_and_initialize(float **floats, char **chars, Item ***items,
                            int n, int m, double min_range, double max_range,
                            ItemType *valid_types, size_t valid_type_count) {
    // Allocate aligned memory for floats
    *floats = (float*)aligned_alloc(n * sizeof(float), ALIGNMENT);
    if (*floats == NULL) return -1;

    // Initialize float values and char flags
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        (*floats)[i] = ((double)rand() / RAND_MAX) * (max_range - min_range) + min_range;
        (*chars)[i] = ((*floats)[i] >= min_range && (*floats)[i] <= max_range) ? 1 : 0;
    }

    // Verify float values
    for (int i = 0; i < n; ++i) {
        if ((*floats)[i] < min_range || (*floats)[i] > max_range) {
            free(*floats);
            return -2;
        }
    }

    // Allocate aligned memory for items
    *items = (Item**)aligned_alloc(m * sizeof(Item*), ALIGNMENT);
    if (*items == NULL) {
        free(*floats);
        return -1;
    }

    for (int i = 0; i < m; ++i) {
        (*items)[i] = (Item*)aligned_alloc(sizeof(Item), ALIGNMENT);
        if ((*items)[i] == NULL) {
            while (--i >= 0) free((*items)[i]);
            free(*items);
            free(*floats);
            return -1;
        }

        // Initialize item values and types
        (*items)[i]->value = ((double)rand() / RAND_MAX) * (max_range - min_range) + min_range;
        int type_index = rand() % valid_type_count;
        (*items)[i]->type = valid_types[type_index];

        // Verify item values and types
        if ((*items)[i]->value < min_range || (*items)[i]->value > max_range) {
            while (--i >= 0) free((*items)[i]);
            free(*items);
            free(*floats);
            return -2;
        }
    }

    return 0; // Success
}

void deallocate_memory(float *floats, char *chars, Item **items, int m) {
    if (floats != NULL) free(floats);
    if (chars != NULL) free(chars);
    for (int i = 0; i < m; ++i) {
        if (items[i] != NULL) free(items[i]);
    }
    free(items);
}

int main() {
    float *floats = NULL;
    char *chars = NULL;
    Item **items = NULL;

    double min_range = 0.0, max_range = 100.0;
    ItemType valid_types[] = {TYPE_A, TYPE_B, TYPE_C};
    size_t valid_type_count = sizeof(valid_types) / sizeof(valid_types[0]);

    int n = 10; // Number of float values
    int m = 5;  // Number of items

    if (allocate_and_initialize(&floats, &chars, &items, n, m, min_range, max_range, valid_types, valid_type_count) != 0) {
        fprintf(stderr, "Error during allocation and initialization\n");
        return EXIT_FAILURE;
    }

    // Use allocated resources...

    deallocate_memory(floats, chars, *items, m);

    return EXIT_SUCCESS;
}
