    pthread_rwlock_wrlock(&data_collection.lock);

    // Insert at head for simplicity
    new_node->data = ds;
    new_node->next = data_collection.head;
    data_collection.head = new_node;

    pthread_rwlock_unlock(&data_collection.lock);
}

void remove_data_structure(const char* str) {
    pthread_rwlock_wrlock(&data_collection.lock);

    Node *current = data_collection.head, *prev = NULL;
    while (current != NULL && strcmp(current->data.str, str) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_rwlock_unlock(&data_collection.lock);
        return; // Not found
    }

    if (prev == NULL) { // Head needs to be removed
        data_collection.head = current->next;
    } else {
        prev->next = current->next;
    }

    custom_free(current->str);
    custom_free(current);

    pthread_rwlock_unlock(&data_collection.lock);
}

int main() {
    initialize_collection(1000); // Initialize with 1000 elements
    process_data(); // Example processing

    add_data_structure("test", 42); // Add a new data structure
    remove_data_structure("example"); // Remove an existing one

