                free(nodes[j].data);
            aligned_free(nodes);
            for (size_t k = 0; k < itemCount; ++k)
                aligned_free(items[k]);
            aligned_free(items);
            return EXIT_FAILURE;
        }

        recPtr->randomValue = rand() % 1000;
        nodes[i].recPtr = recPtr;
    }

    long* fileOffsets = aligned_alloc(nodeCount * sizeof(long));
    int* uniqueIDs = aligned_alloc(nodeCount * sizeof(int));

    if (!fileOffsets || !uniqueIDs) {
        fprintf(stderr, "Memory allocation failed\n");
        for (size_t i = 0; i < nodeCount; ++i) {
            free(nodes[i].data);
            aligned_free(nodes[i].recPtr);
        }
        aligned_free(nodes);

        for (size_t i = 0; i < itemCount; ++i)
            aligned_free(items[i]);
        aligned_free(items);

        if (fileOffsets) aligned_free(fileOffsets);
        if (uniqueIDs) aligned_free(uniqueIDs);

        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < nodeCount; ++i) {
        fileOffsets[i] = rand() % 10000L;
        uniqueIDs[i] = rand() % 1000000 + 1;
    }

    // Example usage
    printf("First item value: %.2f, type: %d\n", items[0]->value, items[0]->type);
    printf("First node priority: %d, level: %d\n", nodes[0].priority, nodes[0].priorityLevel);

    // Cleanup
