```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include "uthash.h"
#include "logging.h"

// Define the structure for each record
typedef struct {
    long offset;
    int key;
    int value;
    UT_hash_handle hh; // makes this structure hashable
} Record;

// Structure to hold our data and manage concurrency
typedef struct {
    Record *records;     // Pointer to list of records
    pthread_mutex_t mutex;  // Mutex for synchronizing access
    size_t record_count;    // Count of current number of records
    size_t capacity;        // Capacity for growth strategy
    logging_config log_cfg; // Logging configuration
} RecordManager;

// Function declarations
RecordManager* initialize_record_manager(size_t initial_capacity, logging_config log_cfg);
void free_record_manager(RecordManager *manager);
int add_record(RecordManager *manager, long offset, int key, int value);
void trim_records(RecordManager *manager);
void print_statistics(const RecordManager *manager);

// Initialize the record manager
RecordManager* initialize_record_manager(size_t initial_capacity, logging_config log_cfg) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->records = NULL;
    manager->record_count = 0;
    manager->capacity = initial_capacity;
    manager->log_cfg = log_cfg;

    logging_init(log_cfg);

    return manager;
}

// Free the record manager and its records
void free_record_manager(RecordManager *manager) {
    Record *current, *tmp;
    HASH_ITER(hh, manager->records, current, tmp) {
        HASH_DEL(manager->records, current);
        free(current);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Add a new record
int add_record(RecordManager *manager, long offset, int key, int value) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return -1;

    record->offset = offset;
    record->key = key;
    record->value = value;

    pthread_mutex_lock(&manager->mutex);

    HASH_ADD_INT(manager->records, key, record);
    manager->record_count++;

    logging_log(manager->log_cfg, "INFO", "Created record with offset: %ld and key: %d", offset, key);

    if (manager->record_count >= manager->capacity) {
        trim_records(manager);
    }

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

// Trim records to maintain performance
void trim_records(RecordManager *manager) {
    // Example strategy: remove least recently used or based on custom criteria
    logging_log(manager->log_cfg, "INFO", "Trimming records...");
    Record *current, *tmp;

    pthread_mutex_lock(&manager->mutex);

    HASH_ITER(hh, manager->records, current, tmp) {
        if (/* some condition to remove a record */) {
            HASH_DEL(manager->records, current);
            free(current);
            manager->record_count--;
        }
    }

    // Optionally increase capacity
    manager->capacity *= 2;

    pthread_mutex_unlock(&manager->mutex);

    logging_log(manager->log_cfg, "INFO", "Trimming complete. Current record count: %zu", manager->record_count);
}

// Print statistics about the current state of the manager
void print_statistics(const RecordManager *manager) {
    printf("Total Records: %zu\n", manager->record_count);
    printf("Capacity: %zu\n", manager->capacity);
}

// Example logging implementation (you'll need to fill in with your actual logic)
