// Function to simulate retrieving states from an external data source.
int retrieve_states(const char *source, long **offsets, int **keys, size_t *num_states) {
    // Simulating retrieval of state count and arrays
    // In a real scenario, this could be a JSON parse or database query result.
    if (strcmp(source, "valid_source") == 0) {
        *num_states = 5; // Example number of states

        // Allocate memory for offsets and keys arrays based on the number of states
        *offsets = (long *)malloc(*num_states * sizeof(long));
        *keys = (int *)malloc(*num_states * sizeof(int));

        if (!*offsets || !*keys) {
            free(*offsets);
            free(*keys);
            return -1; // Memory allocation failed
        }

        // Simulate filling the arrays with some data
        for (size_t i = 0; i < *num_states; ++i) {
            (*offsets)[i] = (long)i * 100;
            (*keys)[i] = (int)(i + 1);
        }

        return 0; // Success
    }

    return -2; // Invalid source
}

// Function to create a new state list by parsing the retrieved data.
typedef struct State {
    int id;
    struct State *next;
} State;

State* create_state_list(size_t num_states) {
    if (num_states == 0) return NULL;

    State *head = NULL, **tail = &head;

    for (size_t i = 0; i < num_states; ++i) {
        State *new_state = malloc(sizeof(State));
        if (!new_state) {
            // Free all previously allocated states on failure
            while (head != NULL) {
                State *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_state->id = (int)i;
        new_state->next = NULL;

        *tail = new_state;
        tail = &new_state->next;
    }

    return head;
}

// Main function to initialize FSA components
State* init_fsa(const char *state_source, int rand_min, int rand_max) {
    long *offsets = NULL;
    int *keys = NULL;
    size_t num_states = 0;

    if (retrieve_states(state_source, &offsets, &keys, &num_states)) {
        // Error handling for failed state retrieval
        return NULL;
    }

    State *new_state_list = create_state_list(num_states);

    if (!new_state_list) {
        free(offsets);
        free(keys);
        return NULL;  // Memory allocation failure during state creation
    }

    Record *records = malloc(num_states * sizeof(Record));
    if (!records) {
        // Handle memory allocation failure for records
        while (offsets != NULL) {
            long temp_offset = offsets[0];
            int temp_key = keys[0];

            free(offsets);
            free(keys);

            offsets = &temp_offset;
            keys = &temp_key;
        }

        return NULL;
    }

    // Initialize the records with random values
    srand((unsigned int)time(NULL));  // Seed for randomness
    for (size_t i = 0; i < num_states; ++i) {
        records[i].value = rand_min + rand() % (rand_max - rand_min + 1);
    }

    State *initial_state_list = create_state_list(0); // Start with an empty list

    if (!initial_state_list) {
        free(offsets);
        free(keys);
        free(records);

        while (new_state_list != NULL) {
            State *temp_state = new_state_list;
            new_state_list = new_state_list->next;

            free(temp_state);
        }

        return NULL; // Handle failure in initial state list creation
    }

    if (initial_state_list == NULL) {
        // Initial list is empty, point head to the new state list directly.
        initial_state_list = new_state_list;
    } else {
        State *current = initial_state_list;

        // Traverse to the end of the initial list and update the 'next' pointer
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_state_list; 
    }

    free(offsets);
    free(keys);

    return initial_state_list;
}

int main() {
    const char *source = "valid_source";
    State *state_list = init_fsa(source, 10, 20);

    if (state_list) {
        printf("FSA initialized successfully.\n");
    } else {
        printf("Failed to initialize FSA.\n");
    }

    // Free memory of state list
    while (state_list != NULL) {
        State *temp = state_list;
        state_list = state_list->next;
        free(temp);
    }

    return 0;
}
