// Thread-safe functions
data_structure_t* safe_create_data_structure(size_t size, int min_val, int max_val) {
    data_structure_t* ds = malloc(sizeof(data_structure_t));
    pthread_mutex_init(&ds->mutex, NULL);
    ds->count = size;

    ds->offsets = (long*)aligned_alloc(8, sizeof(long) * size);
    ds->keys = (int*)aligned_alloc(8, sizeof(int) * size);

    ds->records = (record_t*)malloc(size * sizeof(record_t));
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&ds->mutex);
        ds->offsets[i] = rand() % 100000;
        ds->keys[i] = rand() % 1000;
        ds->records[i].value = min_val + (rand() % (max_val - min_val + 1));
        ds->records[i].offset_ptr = &ds->offsets[i];
        ds->records[i].key_ptr = &ds->keys[i];
        pthread_mutex_unlock(&ds->mutex);
    }
    return ds;
}

