    logger->file_log = fopen(file_path, "a");
    if (!logger->file_log) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    logger->network_logger = network_func ? network_func : NULL;
}

void log_message(logger_t* logger, LogLevel level, const char* message) {
    if (level >= logger->level) {
        fprintf(logger->file_log, "%s\n", message);
        fflush(logger->file_log);
        if (logger->network_logger) {
            logger->network_logger(message);
        }
    }
}

