void destroy_data_structure(data_structure_t* ds) {
    pthread_mutex_destroy(&ds->mutex);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

config_t* load_config_from_file(const char* filepath) {
    config_t* config = malloc(sizeof(config_t));
    // Example: Load configuration from a JSON file
    FILE* fp = fopen(filepath, "r");
    if (!fp) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char* json_str = malloc(fsize + 1);
    fread(json_str, 1, fsize, fp);
    fclose(fp);
    json_str[fsize] = '\0';

    json_object* jobj = json_tokener_parse(json_str);
    free(json_str);

    // Parse and load config data from JSON object
    if (json_object_array_length(jobj) > 0) {
        json_object* server_count_obj = json_object_object_get(jobj, "server_count");
        if (json_object_is_type(server_count_obj, json_type_int)) {
            config->server_count = (size_t)json_object_get_int64(server_count_obj);
        }
    }

    // Continue parsing other fields...

    json_object_put(jobj);  // Decrement reference count
    return config;
}

size_t serialize_config(const config_t* config, uint8_t** buffer) {
    char temp[1024] = {0};
    snprintf(temp, sizeof(temp), "{\"server_count\": %zu}", config->server_count);
    compress_json(json_tokener_parse(temp), (char**)buffer);
    return strlen((const char*)(*buffer)) + 1;
}

void deserialize_config(uint8_t* buffer, size_t size, config_t* config) {
    json_object* jobj = decompress_json((const char*)buffer);
    if (!json_object_is_type(jobj, json_type_object)) {
        fprintf(stderr, "Invalid JSON format\n");
        return;
    }

    // Deserialize fields
    json_object* server_count_obj = json_object_object_get(jobj, "server_count");
    if (json_object_is_type(server_count_obj, json_type_int)) {
        config->server_count = (size_t)json_object_get_int64(server_count_obj);
    }

    // Continue deserializing other fields...

    json_object_put(jobj);  // Decrement reference count
}

void compress_json(json_object* jobj, char** output_str) {
    const size_t buffer_size = json_object_to_json_string_len(jobj) + 1;
    *output_str = malloc(buffer_size);
    strcpy(*output_str, json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY));
}

json_object* decompress_json(const char* input_str) {
    return json_tokener_parse(input_str);
}

// API interface
void handle_get_request(config_t* config) {
    // Convert config to a string or JSON for response
    char* buffer;
    size_t size = serialize_config(config, (uint8_t**)&buffer);
    printf("GET Response: %s\n", buffer);
    free(buffer);
}

void handle_put_request(const char* new_json, config_t* config) {
    json_object* jobj = json_tokener_parse(new_json);
    // Extract data from JSON and update the config
    if (json_object_is_type(jobj, json_type_object)) {
        json_object* server_count_obj = json_object_object_get(jobj, "server_count");
        if (json_object_is_type(server_count_obj, json_type_int)) {
            config->server_count = (size_t)json_object_get_int64(server_count_obj);
        }
    }
    json_object_put(jobj);  // Decrement reference count
}

void handle_post_request(config_t* config) {
    memset(config, 0, sizeof(config_t));
    printf("Configuration reset to defaults.\n");
}

