#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    double value;
    char *str;
} Entry;

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned_alloc(void* ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

Entry* initialize_entries(size_t num_entries, double *values, char **strings, size_t string_len, int alignment) {
    if (num_entries == 0 || values == NULL || strings == NULL) {
        return NULL;
    }

    Entry *entries = aligned_alloc(alignment, num_entries * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        entries[i].value = values[i];

        char *aligned_str = aligned_alloc(alignment, string_len + 1);
        if (!aligned_str) {
            fprintf(stderr, "Failed to allocate memory for string at index %zu\n", i);
            // Free already allocated entries
            for (size_t j = 0; j < i; ++j) {
                free_aligned_alloc(entries[j].str);
            }
            free_aligned_alloc(entries);
            return NULL;
        }

        strncpy(aligned_str, strings[i], string_len);
        aligned_str[string_len] = '\0';
        entries[i].str = aligned_str;
    }

    return entries;
}

int verify_entries(Entry *entries, size_t num_entries) {
    if (!entries) {
        fprintf(stderr, "Entries pointer is NULL\n");
        return 0;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        if (entries[i].value != entries[i].value || entries[i].str == NULL) {
            fprintf(stderr, "Data integrity check failed at index %zu\n", i);
            return 0;
        }
    }

    printf("All entries verified successfully.\n");
    return 1;
}

void log_resource_usage(size_t num_entries) {
    printf("Resource usage: Allocated memory for %zu entries\n", num_entries);
}

int main() {
    size_t num_entries = 3;
    double values[] = {1.23, 4.56, 7.89};
    char *strings[] = {"string1", "string2", "string3"};
    size_t string_len = strlen("string1");

    Entry *entries = initialize_entries(num_entries, values, strings, string_len, 32);
    if (entries) {
        log_resource_usage(num_entries);

        int verified = verify_entries(entries, num_entries);
        if (verified) {
            // Use the entries in your data processing pipeline
        }

        for (size_t i = 0; i < num_entries; ++i) {
            free_aligned_alloc(entries[i].str);
        }
        free_aligned_alloc(entries);
    }

    return 0;
}
