void* init_mmu_array(size_t num_entries, const Config* config) {
    if (!config || num_entries <= 0 || !config->block_size || !config->page_size) {
        logging.error("Invalid input parameters.");
        return NULL;
    }

    size_t entry_size = sizeof(MMUEntry);
    MMUEntry* mmu_array = (MMUEntry*)aligned_alloc(config->alignment, entry_size * num_entries);

    if (!mmu_array) {
