#define BUFFER_SIZE 256

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
} record;

typedef struct log_entry {
    long offset;
    int key;
    record rec;
    struct log_entry* next;
} log_entry;

typedef struct {
    log_entry* head;
    pthread_mutex_t mutex;
    size_t current_size;
    size_t max_size;
    char** error_messages;
    int num_errors;
} logging_system;

logging_system* init_logging_system(int num_records, const char* messages[], size_t max_memory_size, int key_range_min, int key_range_max) {
    if (num_records <= 0 || !messages || max_memory_size == 0) return NULL;

    logging_system* system = (logging_system*)malloc(sizeof(logging_system));
    if (!system) return NULL;

    system->head = NULL;
    pthread_mutex_init(&system->mutex, NULL);
    system->current_size = 0;
    system->max_size = max_memory_size;
    system->error_messages = (char**)malloc(num_records * sizeof(char*));
    system->num_errors = 0;

    if (!system->error_messages) {
        free(system);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&system->mutex);

        log_entry* new_entry = (log_entry*)malloc(sizeof(log_entry));
        if (!new_entry || system->current_size + sizeof(log_entry) > system->max_size) {
            if (system->error_messages[system->num_errors] == NULL) {
                char error_msg[128];
                snprintf(error_msg, sizeof(error_msg), "Allocation failed for record %d", i);
                system->error_messages[system->num_errors++] = strdup(error_msg);
            }
            pthread_mutex_unlock(&system->mutex);
            continue;
        }

        new_entry->offset = (long)i * 10; // Example offset calculation
        new_entry->key = key_range_min + rand() % (key_range_max - key_range_min + 1);
        strncpy(new_entry->rec.buffer, messages[i], BUFFER_SIZE - 1);
        if (strlen(messages[i]) >= BUFFER_SIZE) {
            snprintf(system->error_messages[system->num_errors++], sizeof(char*) * BUFFER_SIZE, "Warning: Message truncated for record %d", i);
            new_entry->rec.buffer[BUFFER_SIZE - 1] = '\0';
        }
        new_entry->rec.value = rand(); // Example value
        new_entry->next = system->head;
        system->head = new_entry;
        system->current_size += sizeof(log_entry);

        pthread_mutex_unlock(&system->mutex);
    }

    return system;
}

void free_logging_system(logging_system* system) {
    if (!system) return;

    log_entry* current = system->head;
    while (current) {
        log_entry* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&system->mutex);

    for (int i = 0; i < system->num_errors; ++i) {
        if (system->error_messages[i]) {
            free(system->error_messages[i]);
        }
    }
    free(system->error_messages);
    free(system);
}

log_entry* find_log_entry(logging_system* system, int key) {
    if (!system) return NULL;

    pthread_mutex_lock(&system->mutex);

    log_entry* current = system->head;
    while (current) {
        if (current->key == key) {
            pthread_mutex_unlock(&system->mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&system->mutex);
    return NULL;
}

log_entry* find_log_offset(logging_system* system, long offset) {
    if (!system) return NULL;

    pthread_mutex_lock(&system->mutex);

    log_entry* current = system->head;
    while (current) {
        if (current->offset == offset) {
            pthread_mutex_unlock(&system->mutex);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&system->mutex);
    return NULL;
}

void add_log_entry(logging_system* system, long offset, int key, const char* message) {
    if (!system || !message) return;

    pthread_mutex_lock(&system->mutex);

    log_entry* new_entry = (log_entry*)malloc(sizeof(log_entry));
    if (!new_entry || system->current_size + sizeof(log_entry) > system->max_size) {
        if (system->num_errors < 10) { // Limit the number of error messages
            char error_msg[128];
            snprintf(error_msg, sizeof(error_msg), "Allocation failed for new entry");
            system->error_messages[system->num_errors++] = strdup(error_msg);
        }
        pthread_mutex_unlock(&system->mutex);
        return;
    }

    new_entry->offset = offset;
    new_entry->key = key;
    strncpy(new_entry->rec.buffer, message, BUFFER_SIZE - 1);
    if (strlen(message) >= BUFFER_SIZE) {
        snprintf(system->error_messages[system->num_errors++], sizeof(char*) * BUFFER_SIZE, "Warning: Message truncated for new entry");
        new_entry->rec.buffer[BUFFER_SIZE - 1] = '\0';
    }
    new_entry->rec.value = rand(); // Example value
    new_entry->next = system->head;
    system->head = new_entry;
    system->current_size += sizeof(log_entry);

    pthread_mutex_unlock(&system->mutex);
}
