```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define CHAR_SET "abcdefghijklmnopqrstuvwxyz"
#define STRING_LENGTH 5

typedef struct Data {
    char *string;
    bool flag;
} Data;

typedef struct Link {
    int index;
    struct Link *next;
} Link;

typedef struct Node {
    int value;
    Link *link;
    Data *data;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* generate_unique_string(size_t length) {
    static size_t counter = 0;
    char *result = malloc(length + 1);
    if (!result) return NULL;

    for (size_t i = 0; i < length; ++i) {
        result[i] = CHAR_SET[(counter + i) % strlen(CHAR_SET)];
    }
    result[length] = '\0';

    counter++;
    return result;
}

void initialize_data(Data *data_array, size_t data_count) {
    for (size_t i = 0; i < data_count; ++i) {
        char *str = generate_unique_string(STRING_LENGTH);
        if (!str) {
            fprintf(stderr, "Failed to allocate memory for string\n");
            exit(EXIT_FAILURE);
        }
        data_array[i].string = str;
        data_array[i].flag = (i < data_count / 2);
    }
}

void traverse_and_update(Node *nodes, size_t node_count, size_t link_count) {
    for (size_t i = 0; i < node_count; ++i) {
        Link *current_link = nodes[i].link;
        while (current_link && current_link->index < link_count) {
            pthread_mutex_lock(&mutex);
            if (strlen(nodes[current_link->index].data->string) % 2 == 0) {
                nodes[current_link->index].data->flag = false;
            }
            pthread_mutex_unlock(&mutex);
            current_link = current_link->next;
        }
    }
}

void free_resources(Node *nodes, size_t node_count, Data *data_array, size_t data_count) {
    for (size_t i = 0; i < node_count; ++i) {
        Link *current_link = nodes[i].link;
        while (current_link) {
            Link *temp = current_link;
            current_link = current_link->next;
            free(temp);
        }
    }

    for (size_t i = 0; i < data_count; ++i) {
        free(data_array[i].string);
    }

    free(nodes);
    free(data_array);
}

void manage_data_structure(size_t node_count, size_t link_count, size_t data_count) {
    Node *nodes = malloc(node_count * sizeof(Node));
    Data *data_array = malloc(node_count * data_count * sizeof(Data));

    if (!nodes || !data_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(nodes);
        free(data_array);
        exit(EXIT_FAILURE);
    }

    initialize_data(data_array, node_count * data_count);

    for (size_t i = 0; i < node_count; ++i) {
        nodes[i].value = i;
        nodes[i].data = &data_array[i * data_count];

        Link *current_link = NULL;
        for (size_t j = 0; j < link_count; ++j) {
            if ((j + 1) % link_count != 0 || i + 1 < node_count) {
                Link *new_link = malloc(sizeof(Link));
                if (!new_link) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free_resources(nodes, node_count, data_array, node_count * data_count);
                    exit(EXIT_FAILURE);
                }
                new_link->index = (i + j + 1) % node_count;
                new_link->next = NULL;

                if (!current_link) {
                    nodes[i].link = new_link;
                } else {
                    current_link->next = new_link;
                }

                current_link = new_link;
            }
        }
    }

    traverse_and_update(nodes, node_count, link_count);

    free_resources(nodes, node_count, data_array, node_count * data_count);
}

int main() {
    size_t node_count = 10;
    size_t link_count = 3;
    size_t data_count = 5;

    manage_data_structure(node_count, link_count, data_count);

    return 0;
}
```

