#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long value;
    int *ptr;
} Offset;

typedef struct {
    int key;
    Offset *offset_ref;
} Record;

typedef struct {
    pthread_mutex_t lock;
    size_t total_allocated;
    size_t current_usage;
} MemoryTracker;

MemoryTracker tracker = {PTHREAD_MUTEX_INITIALIZER, 0, 0};

void log_event(const char *message) {
    // Simple logging function
    printf("%s\n", message);
}

int allocate_and_initialize(
    int num_records, 
    int total_keys, 
    int min_rand_val, 
    int max_rand_val,
    long offsets_size,
    void **records_out,
    void **keys_out,
    void **offsets_out) {

    pthread_mutex_lock(&tracker.lock);

    // Allocate memory for keys
    int *keys = (int *)malloc(total_keys * sizeof(int));
    if (!keys) {
        pthread_mutex_unlock(&tracker.lock);
        log_event("Memory allocation failed for keys.");
        return -1;
    }
    tracker.total_allocated += total_keys * sizeof(int);

    // Allocate memory for offsets
    Offset *offsets = (Offset *)malloc(offsets_size * sizeof(Offset));
    if (!offsets) {
        free(keys);
        pthread_mutex_unlock(&tracker.lock);
        log_event("Memory allocation failed for offsets.");
        return -1;
    }
    tracker.total_allocated += offsets_size * sizeof(Offset);

    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        pthread_mutex_unlock(&tracker.lock);
        log_event("Memory allocation failed for records.");
        return -1;
    }
    tracker.total_allocated += num_records * sizeof(Record);

    // Initialize offsets and records
    srand(time(NULL));  // Seed the random number generator
    for (int i = 0; i < offsets_size; ++i) {
        offsets[i].value = rand() % 100; // Example initialization
        offsets[i].ptr = (int *)malloc(sizeof(int));
        if (!offsets[i].ptr) {
            log_event("Memory allocation failed for offset pointer.");
            free(keys);
            free(offsets);
            free(records);
            pthread_mutex_unlock(&tracker.lock);
            return -1;
        }
        *offsets[i].ptr = rand() % (max_rand_val - min_rand_val + 1) + min_rand_val;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].key = keys[i % total_keys]; // Example key assignment
        records[i].offset_ref = &offsets[i % offsets_size];
    }

    *records_out = records;
    *keys_out = keys;
    *offsets_out = offsets;

    tracker.current_usage = tracker.total_allocated;

    pthread_mutex_unlock(&tracker.lock);
    log_event("Memory allocation and initialization completed successfully.");
    return 0;
}

void free_memory(void *records, void *keys, void *offsets) {
    pthread_mutex_lock(&tracker.lock);

    Record *record_array = (Record *)records;
    int *key_array = (int *)keys;
    Offset *offset_array = (Offset *)offsets;

    if (record_array) {
        for (size_t i = 0; i < num_records; ++i) {
            free(offset_array[i].ptr);
        }
        free(record_array);
    }

    if (key_array) {
        free(key_array);
    }

    if (offset_array) {
        free(offset_array);
    }

    tracker.current_usage = 0;
    pthread_mutex_unlock(&tracker.lock);

    log_event("Memory deallocation completed.");
}

void garbage_collect(void) {
    // Example: simple garbage collection routine
    pthread_mutex_lock(&tracker.lock);

    if (tracker.total_allocated > tracker.current_usage * 2) { // Example threshold
        log_event("Garbage collection triggered.");
        // Perform cleanup logic here

        tracker.total_allocated = tracker.current_usage;
    }

    pthread_mutex_unlock(&tracker.lock);
}

int main() {
    void *records, *keys, *offsets;

    if (allocate_and_initialize(10, 5, 1, 100, 8, &records, &keys, &offsets) == 0) {
        // Use allocated memory...

        garbage_collect(); // Example call

        free_memory(records, keys, offsets);
    } else {
        log_event("Initialization failed.");
    }

    return 0;
}
```

