import java.io.IOException;
import java.nio.channels.SocketChannel;
import java.net.InetSocketAddress;
import javax.swing.SwingUtilities;

public class ConnectionManager {

    static {
        System.loadLibrary("NativeLib"); // Load your C library here
    }

    private volatile boolean connected = false;

    public void initiateConnection() {
        SwingUtilities.invokeLater(() -> {
            try (SocketChannel channel = SocketChannel.open()) {
                channel.configureBlocking(false);
                if (!channel.connect(new InetSocketAddress("localhost", 8080))) {
                    System.out.println("Connection attempt timed out.");
                } else {
                    connected = true;
                    // Handle connection logic
                    channel.close(); // Ensure closure after use
                    sendCloseMessage();
                }
            } catch (IOException e) {
                System.err.println("Failed to connect: " + e.getMessage());
            }
        });
    }

    private void sendCloseMessage() {
        // Send a message to the messaging system indicating connection closure
        if (connected) {
            System.out.println("Connection closed, sending notification.");
            connected = false;
        }
    }

    public native void initiateNativeOperations();

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        manager.initiateConnection();
        manager.initiateNativeOperations();
    }
}
