ActivityNode* create_schedule(int num_activities, int max_memory_size) {
    const size_t alignment = 1024; // Alignment boundary

    ActivityNode* head = (ActivityNode*)aligned_alloc(sizeof(ActivityNode), alignment);
    if (!head) return NULL;

