        current_activity->type = determine_activity_type(priority, progress, resource_demand);
        current_activity->resource_demand = resource_demand;
        current_activity->criticality = (rand() % 2 == 0);

        // Allocate and initialize constraints
        ConstraintNode* constraints = NULL;
        for (int j = 0; j < 3; ++j) { // Example: each activity has up to 3 constraints
            ConstraintNode* new_constraint = (ConstraintNode*)aligned_alloc(sizeof(ConstraintNode), alignment);
            if (!new_constraint) {
                free_schedule(head); // Custom function to free allocated memory
                return NULL;
            }

            new_constraint->dependency_id = rand() % num_activities; // Example dependency ID
            new_constraint->limit = (float)(rand() % 100 + 1) / 10.0;
            new_constraint->deadline = rand() % 1000000;

            new_constraint->next = constraints;
            constraints = new_constraint;
        }
        current_activity->constraints = constraints;

        // Check memory limits
        if ((size_t)((char*)current_activity - (char*)head) + sizeof(ActivityNode) > max_memory_size) {
            free_schedule(head); // Custom function to free allocated memory
            return NULL;
        }

        // Move to the next activity node
        current_activity->next = (ActivityNode*)aligned_alloc(sizeof(ActivityNode), alignment);
        if (!current_activity->next) {
            free_schedule(head); // Custom function to free allocated memory
            return NULL;
        }
        current_activity = current_activity->next;
    }

    current_activity->next = NULL; // Mark end of list
    return head;
}

// Function to free the schedule structure
void free_schedule(ActivityNode* head) {
    ActivityNode* current_activity = head;
    while (current_activity) {
        ConstraintNode* constraints = current_activity->constraints;
        while (constraints) {
            ConstraintNode* temp = constraints;
            constraints = constraints->next;
            aligned_free(temp); // Free with alignment
        }
        ActivityNode* next_activity = current_activity->next;
        aligned_free(current_activity);
        current_activity = next_activity;
    }
}

