pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to calculate aligned address
static inline void* align_pointer(void* ptr, size_t alignment) {
    uintptr_t addr = (uintptr_t)ptr;
    if ((addr % alignment) == 0) return ptr;

    void* aligned_ptr = (void*)((addr + alignment - 1) & ~(alignment - 1));
    free_aligned(ptr); // Free the original unaligned block
    return aligned_ptr;
}

// Function to initialize a node and its items
Node* create_node(int index, int random_range_min, int random_range_max) {
    Node* node = (Node*)aligned_alloc(ALIGNMENT, sizeof(Node));

    if (!node) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);
    total_memory_usage += sizeof(Node);

    // Calculate the double value as square root of a random integer
    int rand_value = (rand() % (random_range_max - random_range_min + 1)) + random_range_min;
    node->value = sqrt(rand_value);

    // Allocate memory for item list
    size_t items_count = (index % 10) + 1; // Example: number of items based on index
    node->item_list = (Item*)aligned_alloc(ALIGNMENT, sizeof(Item) * items_count);
    if (!node->item_list) {
        fprintf(stderr, "Failed to allocate memory for item list\n");
        free_aligned(node);
        pthread_mutex_unlock(&memory_lock);
        total_memory_usage -= sizeof(Node);
        return NULL;
    }

    node->item_count = items_count;

    // Initialize items with unique keys and random strings
    for (size_t i = 0; i < items_count; ++i) {
        node->item_list[i].key = index * 10 + i; // Unique key example
        for (int j = 0; j < ITEM_STRING_LENGTH - 1; ++j) {
            char rand_char = 'a' + (rand() % 26);
            node->item_list[i].string[j] = rand_char;
        }
        node->item_list[i].string[ITEM_STRING_LENGTH - 1] = '\0';
    }

    pthread_mutex_unlock(&memory_lock);

    return node;
}

// Function to initialize nodes array
Node** create_nodes_array(int num_nodes, int random_range_min, int random_range_max) {
    if (num_nodes > MAX_NODES) {
        fprintf(stderr, "Number of nodes exceeds maximum limit\n");
        return NULL;
    }

    Node** nodes = (Node**)aligned_alloc(ALIGNMENT, sizeof(Node*) * num_nodes);
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for nodes array\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < num_nodes; ++i) {
        Node* node = create_node(i, random_range_min, random_range_max);
        if (!node) {
            fprintf(stderr, "Failed to initialize node %d\n", i);

            // Cleanup in case of failure
            while (--i >= 0) free_aligned(nodes[i]);
            free_aligned(nodes);
            pthread_mutex_unlock(&memory_lock);
            total_memory_usage = 0;
            return NULL;
        }
        nodes[i] = node;

        if (total_memory_usage > MEMORY_THRESHOLD) {
            fprintf(stderr, "Memory usage exceeded threshold\n");
            // Cleanup and return NULL
            for (int j = 0; j <= i; ++j) free_aligned(nodes[j]);
            free_aligned(nodes);
            pthread_mutex_unlock(&memory_lock);
            total_memory_usage = 0;
            return NULL;
        }
    }

    pthread_mutex_unlock(&memory_lock);

    // Verify data integrity, e.g., check for valid values
    for (int i = 0; i < num_nodes; ++i) {
        if (nodes[i]->value <= 0) {
            fprintf(stderr, "Data integrity issue at node %d\n", i);
            // Cleanup on integrity failure
            for (int j = 0; j < num_nodes; ++j) free_aligned(nodes[j]);
            free_aligned(nodes);
            return NULL;
        }
    }

    return nodes;
}

// Function to deallocate all nodes and the array of node pointers
void free_nodes_array(Node** nodes, int num_nodes) {
    if (!nodes) return;

    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < num_nodes; ++i) {
        free_aligned(nodes[i]->item_list);
        free_aligned(nodes[i]);
    }

    free_aligned(nodes);
    total_memory_usage = 0;

    pthread_mutex_unlock(&memory_lock);
}

// Mocked external memory management functions
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = malloc(size + alignment - 1 + sizeof(void*));
    if (!ptr) return NULL;

    uintptr_t addr = (uintptr_t)ptr;
    uintptr_t aligned_addr = (addr + alignment - 1) & ~(alignment - 1);
    *((void**)((aligned_addr - sizeof(void*)) + sizeof(char))) = ptr; // Store original pointer

    return (void*)aligned_addr;
}

void free_aligned(void* ptr) {
    if (!ptr) return;

    void* original_ptr = *(void**)((uintptr_t)ptr - sizeof(void*) + sizeof(char));
    free(original_ptr);
}
