#define ALIGNMENT 16

typedef struct {
    int value;
} record;

typedef struct {
    pthread_mutex_t mutex;
    size_t current_size;
    size_t max_size;
    record *records;
    long *offsets;
    int *keys;
} Resource;

void log_event(const char *event) {
    // Placeholder for logging system integration
    printf("%s\n", event);
}

size_t aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return 0;
    }
    return (size_t)ptr;
}

int initialize_resource(Resource *res, size_t initial_size, size_t offset_count, size_t key_count) {
    pthread_mutex_init(&res->mutex, NULL);
    res->current_size = 0;
    res->max_size = 0;

    if (initial_size == 0 || offset_count == 0 || key_count == 0) {
        log_event("Invalid initial sizes.");
        return -1;
    }

    size_t record_size = sizeof(record);
    size_t aligned_record_size = ((record_size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;

    res->records = (record *)aligned_alloc(ALIGNMENT, initial_size * aligned_record_size);
    if (!res->records) {
        log_event("Failed to allocate memory for records.");
        return -1;
    }

    res->offsets = (long *)aligned_alloc(ALIGNMENT, offset_count * sizeof(long));
    if (!res->offsets) {
        free(res->records);
        log_event("Failed to allocate memory for offsets.");
        return -1;
    }

    res->keys = (int *)aligned_alloc(ALIGNMENT, key_count * sizeof(int));
    if (!res->keys) {
        free(res->records);
        free(res->offsets);
        log_event("Failed to allocate memory for keys.");
        return -1;
    }

    res->current_size = initial_size;
    res->max_size = initial_size;

    pthread_mutex_lock(&res->mutex);
    for (size_t i = 0; i < initial_size; ++i) {
        res->records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }
    pthread_mutex_unlock(&res->mutex);

    log_event("Resource initialized successfully.");
    return 0;
}

int resize_resource(Resource *res, size_t new_size) {
    if (new_size <= res->current_size) {
        return 0; // No need to resize down or same size
    }

    pthread_mutex_lock(&res->mutex);

    size_t aligned_record_size = ((sizeof(record) + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    record *new_records = (record *)aligned_alloc(ALIGNMENT, new_size * aligned_record_size);
    if (!new_records) {
        log_event("Failed to allocate memory for resizing records.");
        pthread_mutex_unlock(&res->mutex);
        return -1;
    }

    memcpy(new_records, res->records, res->current_size * sizeof(record));

    free(res->records);
    res->records = new_records;
    res->max_size = new_size;

    log_event("Resource resized successfully.");

    pthread_mutex_unlock(&res->mutex);

    return 0;
}

int verify_resource(Resource *res) {
    for (size_t i = 0; i < res->current_size; ++i) {
        if (res->records[i].value <= 0 || res->records[i].value > 100) {
            log_event("Data integrity check failed.");
            return -1;
        }
    }

    log_event("Data integrity verified successfully.");
    return 0;
}

void cleanup_resource(Resource *res) {
    pthread_mutex_destroy(&res->mutex);
    free(res->records);
    free(res->offsets);
    free(res->keys);
}
