int random_within_range(long min, long max, int inclusive_min, int inclusive_max) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    srand((unsigned int)(tv.tv_sec * 1000000 + tv.tv_usec));
    if (inclusive_min && inclusive_max) {
        return rand() % ((max - min) + 1) + min;
    } else if (inclusive_min) {
        return rand() % ((max - min)) + min;
    } else if (inclusive_max) {
        return rand() % ((max - min) + 1) + min + 1;
    } else {
        return rand() % ((max - min) - 1) + min + 1;
    }
}

void init_record_pool(size_t size) {
    for (size_t i = 0; i < size; ++i) {
        record_pool[i] = malloc(sizeof(Record));
        if (!record_pool[i]) {
            log_event("Failed to allocate memory for Record");
            exit(EXIT_FAILURE);
        }
        pthread_mutex_lock(&resource_manager_mutex);
        offset_values[i] = random_within_range(0, 1000, 1, 0); // example range
        record_pool[i]->value = random_within_range(10, 50, 1, 1); // example range
        current_record_count++;
        pthread_mutex_unlock(&resource_manager_mutex);
    }
}

void free_record_pool() {
    for (size_t i = 0; i < RECORD_POOL_SIZE && record_pool[i]; ++i) {
        free(record_pool[i]);
        record_pool[i] = NULL;
    }
}

// Function to merge ranges and other operations can be added here

void* DynamicResourceManager(void* arg) {
    init_record_pool(RECORD_POOL_SIZE);

    // Simulate processing each record
    for (size_t i = 0; i < current_record_count; ++i) {
        pthread_mutex_lock(&resource_manager_mutex);
        process_data_with_library(record_pool[i]);
        http_post("http://logging-system.com/log", "Record processed");
        pthread_mutex_unlock(&resource_manager_mutex);
        usleep(1000); // Simulate work
    }

    free_record_pool();
    return NULL;
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, DynamicResourceManager, NULL) != 0) {
        log_event("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}
