#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY 1024 * 1024 // Example threshold for total memory allocation

typedef struct FileSystemNode {
    int key;
    double value;
    char* filePath;
    struct FileSystemNode* parent;
    struct FileSystemNode* child;
    struct FileSystemNode* sibling;
} FileSystemNode;

// Helper function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32) || defined(_WIN64)
    if (posix_memalign(&ptr, alignment, size)) return NULL; // Windows-specific check
#else
    if ((ptr = memalign(alignment, size))) return ptr; // POSIX systems
#endif
    return ptr ? ptr : malloc(size); // Fallback to regular malloc on failure
}

// Initialize a file system tree node
FileSystemNode* initNode(int key, double value, const char* filePath) {
    FileSystemNode* node = (FileSystemNode*)aligned_alloc(32, sizeof(FileSystemNode));
    if (!node) return NULL;

    node->key = key;
    node->value = value;
    node->parent = NULL;
    node->child = NULL;
    node->sibling = NULL;

    size_t pathLength = strlen(filePath) + 1; // Include null-terminator
    char* allocatedPath = (char*)aligned_alloc(32, pathLength);
    if (!allocatedPath) {
        free(node);
        return NULL;
    }

    strcpy(allocatedPath, filePath);
    node->filePath = allocatedPath;

    return node;
}

// Function to create and initialize a tree structure
FileSystemNode* createTree(const int keys[], const double values[], const char* filePaths[], size_t count) {
    if (count == 0 || !keys || !values || !filePaths)
        return NULL;

    FileSystemNode* root = initNode(keys[0], values[0], filePaths[0]);
    if (!root)
        return NULL;

    FileSystemNode** currentParents = &root;
    size_t allocatedMemory = sizeof(FileSystemNode) + strlen(filePaths[0]) + 1; // Initial memory usage

    for (size_t i = 1; i < count; ++i) {
        FileSystemNode* newNode = initNode(keys[i], values[i], filePaths[i]);
        if (!newNode) {
            // Cleanup on failure
            while (*currentParents) {
                FileSystemNode* temp = *currentParents;
                *currentParents = (*currentParents)->sibling;
                free(temp->filePath);
                free(temp);
            }
            return NULL;
        }

        // Check memory threshold
        size_t newAllocatedSize = sizeof(FileSystemNode) + strlen(filePaths[i]) + 1;
        if (allocatedMemory + newAllocatedSize > MAX_MEMORY) {
            fprintf(stderr, "Memory allocation exceeded the maximum allowed limit.\n");
            free(newNode->filePath);
            free(newNode);

            // Cleanup
            while (*currentParents) {
                FileSystemNode* temp = *currentParents;
                *currentParents = (*currentParents)->sibling;
                free(temp->filePath);
                free(temp);
            }
            return NULL;
        }

        allocatedMemory += newAllocatedSize;

        // Append node to the last parent in currentParents
        while ((*currentParents)->sibling) {
            currentParents = &(*currentParents)->sibling;
        }
        (*currentParents)->sibling = newNode;
        newNode->parent = *currentParents; // Set parent reference

        // Optionally manage child nodes here if needed
    }

    return root;
}

// Example usage and testing of the function
int main() {
    const int keys[] = {1, 2, 3};
    const double values[] = {1.0, 2.0, 3.0};
    const char* filePaths[] = {"/path/to/file1", "/path/to/file2", "/path/to/file3"};

    FileSystemNode* treeRoot = createTree(keys, values, filePaths, 3);
    if (treeRoot) {
        printf("File System Tree created successfully.\n");
        // Add traversal and verification logic here
    } else {
        fprintf(stderr, "Failed to create the File System Tree.\n");
    }

    return 0;
}
