typedef struct {
    int key;
    char description[65]; // 64 characters + null terminator
} Record;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_records(Record **records, size_t num_records, int min_key, int max_key) {
    if (min_key > max_key || num_records == 0) return -1;

    // Allocate memory for the array of records
    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    pthread_mutex_lock(&mutex);

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (!is_unique_key(*records, key, i));

        (*records)[i].key = key;

        // Generate random alphanumeric string
        for (int j = 0; j < 64; ++j) {
            char rand_char = (rand() % 2 == 0) ? 
                (rand() % 26 + 'a') : (rand() % 10 + '0');
            (*records)[i].description[j] = rand_char;
        }
        (*records)[i].description[64] = '\0'; // Null-terminate the string
    }

    pthread_mutex_unlock(&mutex);

    return 0;
}

int is_unique_key(Record *records, int key, size_t current_index) {
    for (size_t i = 0; i < current_index; ++i) {
        if (records[i].key == key) {
            return 0; // Key not unique
        }
    }
    return 1; // Key is unique
}

void free_records(Record *records) {
    free(records);
}

// Example of integration with a logging system
void log_records(const Record *records, size_t num_records, const char *log_filename) {
    FILE *file = fopen(log_filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        fprintf(file, "Key: %d, Description: %s\n", records[i].key, records[i].description);
    }

    fclose(file);
}

// Example usage
int main() {
    Record *records;
    size_t num_records = 1000;
    int min_key = 1;
    int max_key = 2000;

    if (allocate_records(&records, num_records, min_key, max_key) == -1) {
        return EXIT_FAILURE;
    }

    log_records(records, num_records, "log.txt");

    free_records(records);
    return EXIT_SUCCESS;
}
```

