#define ALIGNMENT 16

typedef struct {
    int value;
} record_t;

// Function to align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__GNUC__) || defined(__clang__)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#else
    ptr = aligned_alloc(alignment, size); // C11 standard function
#endif
    return ptr;
}

// Simple linear congruential generator (LCG) for pseudo-random numbers
uint32_t lcg_random(uint32_t *seed) {
    const uint64_t a = 1664525;
    const uint64_t c = 1013904223;
    *seed = (a * (*seed) + c) & ((1ULL << 32) - 1);
    return (uint32_t)(*seed);
}

int allocate_and_initialize(
    size_t num_offsets,
    size_t num_keys,
    size_t num_records,
    long **offsets,
    int **keys,
    record_t ***records
) {
    // Initialize seed for pseudo-random number generator
    uint32_t seed = (uint32_t)time(NULL);

    // Calculate memory sizes with alignment considerations
    size_t offset_size = num_offsets * sizeof(long);
    size_t key_size = num_keys * sizeof(int);
    size_t record_size = num_records * sizeof(record_t);

    size_t total_size = offset_size + key_size + record_size;
    size_t padding = (ALIGNMENT - (total_size % ALIGNMENT)) % ALIGNMENT;

    // Allocate memory for offsets
    *offsets = (long *)aligned_alloc(ALIGNMENT, offset_size);
    if (*offsets == NULL) return -1;

    // Initialize offsets with pseudo-random values
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = lcg_random(&seed);
    }

    // Allocate memory for keys
    *keys = (int *)aligned_alloc(ALIGNMENT, key_size + padding); // Align the next allocation start
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }
    size_t padded_key_offset = ((key_size + padding) / ALIGNMENT) * ALIGNMENT;

    // Initialize keys with pseudo-random values
    for (size_t i = 0; i < num_keys; ++i) {
        (*keys)[i] = lcg_random(&seed);
    }

    // Allocate memory for records
    *records = (record_t **)aligned_alloc(ALIGNMENT, record_size + padded_key_offset);
    if (*records == NULL) {
        free(*offsets);
        free(*keys - padding);  // Adjusted pointer to original allocation start
        return -1;
    }
    size_t padded_record_offset = (padded_key_offset + record_size) / ALIGNMENT * ALIGNMENT;

    // Initialize records with pseudo-random values
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i]->value = lcg_random(&seed);
    }

    // Verify allocations and integrity of data (simple checks)
    if (memcmp(*offsets, *offsets, offset_size) == NULL &&
        memcmp(*keys - padding, *keys - padding, key_size + padding) == NULL &&
        memcmp(*records, *records, padded_record_offset)) {

        printf("Memory allocation and initialization successful.\n");
        return 0;
    } else {
        // If verification fails
        free(*offsets);
        free(*keys - padding);
        free(*records);
        return -1;
    }
}

int main() {
    long *offsets = NULL;
    int *keys = NULL;
    record_t **records = (record_t **)malloc(num_records * sizeof(record_t*));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records pointers\n");
        return -1;
    }

    // Allocate and initialize arrays
    if (allocate_and_initialize(10, 20, 5, &offsets, &keys, &records) != 0) {
        fprintf(stderr, "Memory allocation failed or data verification error.\n");
        free(records);
        return -1;
    }

    // Use the allocated memory...

    // Free allocations
    free(offsets);
    free(keys);
    for (size_t i = 0; i < 5; ++i) {
        free(records[i]);
    }
    free(records);

    return 0;
}
