typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    _Bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define ALIGNMENT 16
#define MAX_INT_KEYS 1000
#define RAND_MAX_RANGE 100

void log_message(const char *message) {
    // Simple logging mechanism, replace with actual logging in production
    printf("%s\n", message);
}

int aligned_alloc(size_t alignment, size_t size, void **ptr) {
    if (alignment & (alignment - 1)) return -1; // Alignment must be a power of two

    void *mem;
    if (posix_memalign(&mem, alignment, size)) {
        log_message("Memory allocation failed.");
        return -1;
    }
    *ptr = mem;
    return 0;
}

uint32_t xorshift32(uint32_t seed) {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

void initialize_arrays(size_t num_offsets, size_t num_pdus, int min_val, int max_val, long **offsets,
                       NFAPI_CRC_INDICATION_PDU_T **pdus, int **keys) {
    *offsets = NULL;
    *pdus = NULL;
    *keys = NULL;

    uint32_t seed = (uint32_t)time(NULL);

    if (aligned_alloc(ALIGNMENT, num_offsets * sizeof(long), (void **)offsets)) return;
    if (aligned_alloc(ALIGNMENT, num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T), (void **)pdus)) {
        free(*offsets);
        return;
    }
    if (aligned_alloc(ALIGNMENT, MAX_INT_KEYS * sizeof(int), (void **)keys)) {
        free(*offsets);
        free(*pdus);
        return;
    }

    // Populate offsets with example values
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = (long)i * 10; // Example offset calculation
    }

    // Initialize NFAPI_CRC_INDICATION_PDU_T structures
    for (size_t i = 0; i < num_pdus; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = i % 100;
        (*pdus)[i].RNTI = (uint16_t)(i * 3);
        (*pdus)[i].CRC_INDICATION_REL8_TAG = i % 50;
        (*pdus)[i].CRCFLAG = (i % 2 == 0);
    }

    // Populate keys array with pseudo-random numbers
    for (int i = 0; i < MAX_INT_KEYS; ++i) {
        seed = xorshift32(seed);
        int value = min_val + (seed % (max_val - min_val + 1));
        (*keys)[i] = value;
    }

    log_message("Arrays initialized successfully.");
}

int main() {
