    if (offsets && pdus && keys) {
        log_message("Initialization completed successfully.");
        // Use the arrays...

        free(offsets);
        free(pdus);
        free(keys);
    } else {
        log_message("Initialization failed due to memory allocation issues.");
    }

    return 0;
}
