#include <pthread.h>

#define ALIGNMENT 16
#define MAX_ENTRIES 1000000

typedef struct LogEntry {
    size_t index;
    char *message;
    struct LogEntry *next;
} LogEntry;

typedef struct Entry {
    float value;
    time_t timestamp;
    LogEntry *logs;
} Entry;

typedef struct AllocatedArray {
    Entry **entries;
    size_t count;
    pthread_mutex_t lock;
} AllocatedArray;

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

size_t calculate_aligned_size(size_t size, size_t alignment) {
    return ((size + alignment - 1) / alignment) * alignment;
}

int verify_integrity(Entry *entry) {
    // Simple integrity check (expand as needed)
    return entry != NULL && entry->value > 0.0f && entry->timestamp != 0;
}

void free_log_entries(LogEntry *head) {
    LogEntry *current = head, *next;
    while (current) {
        next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
}

void free_entries(Entry **entries, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (entries[i]) {
            free_log_entries(entries[i]->logs);
            free(entries[i]);
        }
    }
    free(entries);
}

AllocatedArray *create_array(size_t entry_count) {
    AllocatedArray *array = aligned_alloc(ALIGNMENT, sizeof(AllocatedArray));
    if (!array) return NULL;

    array->entries = aligned_alloc(ALIGNMENT, calculate_aligned_size(sizeof(Entry *) * entry_count, ALIGNMENT));
    if (!array->entries) {
        free(array);
        return NULL;
    }

    array->count = entry_count;
    pthread_mutex_init(&array->lock, NULL);

    for (size_t i = 0; i < entry_count; ++i) {
        array->entries[i] = aligned_alloc(ALIGNMENT, sizeof(Entry));
        if (!array->entries[i]) {
            free_entries(array->entries, i);
            free(array->entries);
            pthread_mutex_destroy(&array->lock);
            free(array);
            return NULL;
        }

        float random_value = exp((float)rand() / RAND_MAX * 10); // Random exponent
        array->entries[i]->value = random_value;
        array->entries[i]->timestamp = time(NULL);

        LogEntry *log_head = aligned_alloc(ALIGNMENT, sizeof(LogEntry));
        if (!log_head) {
            free(array->entries[i]);
            array->entries[i] = NULL;
            continue;
        }

        log_head->index = i;
        char message_buffer[64];
        snprintf(message_buffer, sizeof(message_buffer), "Event %zu: %ld", i, array->entries[i]->timestamp);
        log_head->message = strdup(message_buffer);
        if (!log_head->message) {
            free(log_head);
            continue;
        }

        log_head->next = NULL;
        array->entries[i]->logs = log_head;

        // Simulate adding more logs
        for (int j = 1; j < 5; ++j) { // Example: Add 4 logs per entry
            LogEntry *new_log = aligned_alloc(ALIGNMENT, sizeof(LogEntry));
            if (!new_log) break;
            new_log->index = i * 1000 + j; // Unique index
            snprintf(message_buffer, sizeof(message_buffer), "Event %zu: %ld", new_log->index, array->entries[i]->timestamp);
            new_log->message = strdup(message_buffer);
            if (!new_log->message) {
                free(new_log);
                break;
            }
            new_log->next = log_head;
            log_head = new_log;
        }
    }

    return array;
}

void destroy_array(AllocatedArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free_entries(array->entries, array->count);
        free(array->entries);
        free(array);
    }
}

