#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 50000
#define MEMORY_LIMIT (MAX_RECORDS * sizeof(record))

typedef struct record {
    int key;
    long offset;
    struct record* next;
} record;

record* head = NULL;

// Custom memory allocator using a simple first-fit strategy for demonstration
void* custom_alloc(size_t size) {
    static char pool[MEMORY_LIMIT];
    static void* free_ptr = pool;

    if (free_ptr + size > pool + MEMORY_LIMIT)
        return NULL; // Out of memory

    void* allocated_memory = free_ptr;
    free_ptr += size;
    return allocated_memory;
}

// Free the entire list to avoid fragmentation
void custom_free() {
    record *current, *next;
    for (current = head; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
    head = NULL;
}

record* create_record(int key, long offset) {
    record* new_rec = (record*)custom_alloc(sizeof(record));
    if (!new_rec) return NULL;

    new_rec->key = key;
    new_rec->offset = offset;
    new_rec->next = NULL;
    return new_rec;
}

void insert_record(int key, long offset) {
    record* new_rec = create_record(key, offset);
    if (new_rec == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    if (!head || head->key > key) {
        new_rec->next = head;
        head = new_rec;
        return;
    }

    record* current = head;
    while (current->next && current->next->key < key) {
        current = current->next;
    }

    new_rec->next = current->next;
    current->next = new_rec;
}

record* find_record(int key) {
    record *current = head;
    while (current != NULL) {
        if (current->key == key)
            return current;
        current = current->next;
    }
    return NULL;
}

void delete_record(int key) {
    if (!head) return;

    record **indirect = &head;
    while (*indirect && (*indirect)->key != key) {
        indirect = &(*indirect)->next;
    }

    if (*indirect) {
        record *to_delete = *indirect;
        *indirect = to_delete->next;
        free(to_delete);
    }
}

