    size_t used_memory;
} performance_monitor;

performance_monitor perf_mon;

void start_performance_monitoring() {
    perf_mon.start_time = clock();
    perf_mon.used_memory = 0; // Would track actual usage in a real implementation
}

double get_initialization_time() {
    return (double)(clock() - perf_mon.start_time) / CLOCKS_PER_SEC;
}

size_t get_memory_usage() {
    return perf_mon.used_memory; // Would reflect actual memory usage
}

