```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_DNS_SERVERS 5
#define ALIGNMENT 32

typedef struct {
    char *ip_address;
    char *subnet_mask;
    char *gateway;
    char **dns_servers;
    size_t dns_count;
} NetworkConfig;

typedef struct {
    NetworkConfig config;
    pthread_mutex_t mutex;
} ManagedNetworkConfig;

static void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // posix_memalign returns 0 on success.
    }
#endif
    return ptr;
}

static void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int init_network_config(ManagedNetworkConfig *mnc, const char *ip_address, 
                        const char *subnet_mask, const char *gateway,
                        const char **dns_servers_list, size_t dns_count) {
    if (pthread_mutex_init(&mnc->mutex, NULL)) {
        return -1;
    }

    mnc->config.ip_address = strdup(ip_address);
    mnc->config.subnet_mask = strdup(subnet_mask);
    mnc->config.gateway = strdup(gateway);

    if (!mnc->config.ip_address || !mnc->config.subnet_mask || !mnc->config.gateway) {
        goto cleanup;
    }

    mnc->config.dns_servers = aligned_alloc(ALIGNMENT, dns_count * sizeof(char *));
    if (!mnc->config.dns_servers) {
        goto cleanup;
    }
    memcpy(mnc->config.dns_servers, dns_servers_list, dns_count * sizeof(char *));

    mnc->config.dns_count = (dns_count > MAX_DNS_SERVERS) ? MAX_DNS_SERVERS : dns_count;

    return 0;

cleanup:
    pthread_mutex_destroy(&mnc->mutex);
    if (mnc->config.ip_address) free(mnc->config.ip_address);
    if (mnc->config.subnet_mask) free(mnc->config.subnet_mask);
    if (mnc->config.gateway) free(mnc->config.gateway);
    if (mnc->config.dns_servers) aligned_free(mnc->config.dns_servers);

    return -1;
}

void destroy_network_config(ManagedNetworkConfig *mnc) {
    pthread_mutex_lock(&mnc->mutex);
    pthread_mutex_unlock(&mnc->mutex); // Ensure mutex is unlocked after lock

    if (pthread_mutex_destroy(&mnc->mutex)) {
        fprintf(stderr, "Failed to destroy mutex\n");
    }

    free(mnc->config.ip_address);
    free(mnc->config.subnet_mask);
    free(mnc->config.gateway);

    aligned_free(mnc->config.dns_servers);
}

void update_network_config(ManagedNetworkConfig *mnc, const char *ip_address,
                           const char *subnet_mask, const char *gateway,
                           const char **dns_servers_list, size_t dns_count) {
    pthread_mutex_lock(&mnc->mutex);

    free(mnc->config.ip_address);
    free(mnc->config.subnet_mask);
    free(mnc->config.gateway);

    mnc->config.ip_address = strdup(ip_address);
    mnc->config.subnet_mask = strdup(subnet_mask);
    mnc->config.gateway = strdup(gateway);

    aligned_free(mnc->config.dns_servers);
    mnc->config.dns_servers = aligned_alloc(ALIGNMENT, dns_count * sizeof(char *));
    memcpy(mnc->config.dns_servers, dns_servers_list, dns_count * sizeof(char *));

    mnc->config.dns_count = (dns_count > MAX_DNS_SERVERS) ? MAX_DNS_SERVERS : dns_count;

    pthread_mutex_unlock(&mnc->mutex);
}

void log_network_config(const ManagedNetworkConfig *mnc, const char *log_file_path) {
    FILE *file = fopen(log_file_path, "a");
    if (file) {
        pthread_mutex_lock((pthread_mutex_t *)&mnc->mutex);

        fprintf(file, "IP Address: %s\n", mnc->config.ip_address);
        fprintf(file, "Subnet Mask: %s\n", mnc->config.subnet_mask);
        fprintf(file, "Gateway: %s\n", mnc->config.gateway);
        for (size_t i = 0; i < mnc->config.dns_count; ++i) {
            fprintf(file, "DNS Server %zu: %s\n", i + 1, mnc->config.dns_servers[i]);
        }

        pthread_mutex_unlock((pthread_mutex_t *)&mnc->mutex);
        fclose(file);
    }
}

void simulate_network_latency() {
    srand(time(NULL));
    int latency = rand() % 100; // Random latency between 0 and 99 milliseconds
    usleep(latency * 1000); // Convert to microseconds
}

// Example of a thread function to update configuration
void* network_update_thread(void *arg) {
    ManagedNetworkConfig *mnc = (ManagedNetworkConfig *)arg;

    const char *new_ip = "192.168.1.2";
    const char *new_subnet_mask = "255.255.255.0";
    const char *new_gateway = "192.168.1.1";

    // Simulate network latency
    simulate_network_latency();

    pthread_mutex_lock(&mnc->mutex);
    update_network_config(mnc, new_ip, new_subnet_mask, new_gateway, NULL, 0);
    log_network_config(mnc, "network_log.txt");
    pthread_mutex_unlock(&mnc->mutex);

    return NULL;
}

int main() {
    ManagedNetworkConfig mnc;

    const char *initial_dns[] = {"8.8.8.8", "8.8.4.4"};
    if (init_network_config(&mnc, "192.168.1.100", "255.255.255.0", "192.168.1.1", initial_dns, 2)) {
        fprintf(stderr, "Failed to initialize network configuration\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, network_update_thread, &mnc) != 0) {
        fprintf(stderr, "Failed to create update thread\n");
        destroy_network_config(&mnc);
        return EXIT_FAILURE;
    }
    pthread_join(thread_id, NULL);

    destroy_network_config(&mnc);

    return EXIT_SUCCESS;
}
```

This code sets up a network configuration with fields for IP address, subnet mask, gateway, and DNS servers. It includes memory alignment to 32 bytes using `posix_memalign` or `_aligned_malloc` depending on the platform. The mutex ensures thread-safe access to the network configuration data structure.

Dynamic updates are supported, and the code simulates random network latency. Logging is managed in a separate function that does not interfere with the main operations due to mutex locking.

When resources need to be cleaned up, the `destroy_network_config` function releases all allocated memory safely while ensuring the mutex is destroyed correctly. This implementation assumes basic error handling for allocation failures and mutex operations.']

