```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define OFFSET_ARRAY_SIZE 5
#define MAX_STRING_LENGTH 128
#define ALIGNMENT_BOUNDARY 32

typedef struct {
    long offsets[OFFSET_ARRAY_SIZE];
    int key;
    char* str; // Variable length string up to MAX_STRING_LENGTH
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    unsigned int* ref_counts;
} Collection;

// Helper function for aligned memory allocation
void* allocate_aligned(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Initialize a collection with specified initial capacity
Collection* init_collection(size_t initial_capacity) {
    Collection* coll = allocate_aligned(sizeof(Collection), ALIGNMENT_BOUNDARY);
    if (!coll) return NULL;

    coll->records = allocate_aligned(initial_capacity * sizeof(Record), ALIGNMENT_BOUNDARY);
    if (!coll->records) {
        free(coll);
        return NULL;
    }

    coll->ref_counts = allocate_aligned(initial_capacity * sizeof(unsigned int), ALIGNMENT_BOUNDARY);
    if (!coll->ref_counts) {
        free(coll->records);
        free(coll);
        return NULL;
    }

    coll->count = 0;
    coll->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        coll->ref_counts[i] = 1;
    }

    return coll;
}

// Add a record to the collection
int add_record(Collection* coll, const long offsets[], int key, const char* str) {
    if (!coll || !str || strlen(str) >= MAX_STRING_LENGTH)
        return -1;

    if (coll->count == coll->capacity) { // Resize needed
        size_t new_capacity = coll->capacity * 2;
        Record* new_records = allocate_aligned(new_capacity * sizeof(Record), ALIGNMENT_BOUNDARY);
        unsigned int* new_ref_counts = allocate_aligned(new_capacity * sizeof(unsigned int), ALIGNMENT_BOUNDARY);

        if (!new_records || !new_ref_counts) {
            fprintf(stderr, "Failed to reallocate memory.\n");
            return -1;
        }

        memcpy(new_records, coll->records, coll->count * sizeof(Record));
        memcpy(new_ref_counts, coll->ref_counts, coll->capacity * sizeof(unsigned int));

        free(coll->records);
        free(coll->ref_counts);

        coll->records = new_records;
        coll->ref_counts = new_ref_counts;
        coll->capacity = new_capacity;
    }

    // Copy the data
    Record* record = &coll->records[coll->count];
    memcpy(record->offsets, offsets, OFFSET_ARRAY_SIZE * sizeof(long));
    record->key = key;

    size_t str_len = strlen(str) + 1; // Include null-terminator
    if (str_len > MAX_STRING_LENGTH) {
        fprintf(stderr, "String length exceeds maximum limit.\n");
        return -1;
    }

    record->str = allocate_aligned(str_len, ALIGNMENT_BOUNDARY);
    if (!record->str) {
        fprintf(stderr, "Failed to allocate memory for string.\n");
        return -1;
    }

    memcpy(record->str, str, str_len);

    coll->ref_counts[coll->count] = 1; // Initialize reference count
    coll->count++;

    return 0;
}

// Increment the reference count for a record at a given index
int increment_ref(Collection* coll, size_t index) {
    if (!coll || index >= coll->count)
        return -1;

    coll->ref_counts[index]++;
    return 0;
}

// Decrement the reference count and potentially deallocate the record
void decrement_ref_and_cleanup(Collection* coll, size_t index) {
    if (index < coll->count && (--coll->ref_counts[index] == 0)) {
        free(coll->records[index].str);

        // Shift remaining records to fill the gap
        memmove(&coll->records[index], &coll->records[index + 1],
                (coll->count - index - 1) * sizeof(Record));
        memmove(&coll->ref_counts[index], &coll->ref_counts[index + 1],
                (coll->count - index - 1) * sizeof(unsigned int));

        coll->count--;
    }
}

// Cleanup the entire collection
void destroy_collection(Collection* coll) {
    if (!coll) return;

    for (size_t i = 0; i < coll->count; ++i) {
        free(coll->records[i].str);
    }

    free(coll->records);
    free(coll->ref_counts);
    free(coll);
}

// Testing function
void test_collection() {
    Collection* collection = init_collection(10);

    if (!collection) {
        fprintf(stderr, "Failed to initialize the collection.\n");
        return;
    }

    long offsets[] = {1, 2, 3, 4, 5};
    add_record(collection, offsets, 100, "Test string");
    increment_ref(collection, 0);
    decrement_ref_and_cleanup(collection, 0);
    decrement_ref_and_cleanup(collection, 0); // Cleanup

    destroy_collection(collection);
}

int main() {
    test_collection();
    return 0;
}
```

### Key Points:

1. **Memory Management**: Uses `posix_memalign` for aligned memory allocations.
2. **Reference Counting**: Manages shared ownership of records without duplicating data.
3. **Performance Considerations**: Optimizes cache locality by aligning and efficiently managing memory access patterns.
4. **Scalability**: Supports dynamic resizing to handle large numbers of records.
5. **Error Handling**: Logs errors when allocations fail, without crashing the application.
6. **Integration**: Designed for robust handling with external data sources in mind.
7. **Testing**: Includes a basic test function `test_collection`.
8. **Documentation**: Inline comments explain each step.

This code provides an efficient way to manage records with performance optimizations and error handling.']

