    size_t record_size = num_entries * sizeof(record);

    size_t total_size = offset_size + key_size + record_size;

    void* block = malloc(total_size);
    if (!block) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Pointers to sections of the block
    long* offsets = (long*)block;
    int* keys = (int*)(offsets + num_entries);
    record* records = (record*)(keys + num_entries);

    // Initialize with sequential integers and random values
    for (size_t i = 0; i < num_entries; ++i) {
        offsets[i] = i;
        keys[i] = i;
        records[i].value = range_min + rand() % (range_max - range_min);
