#define MAX_SNR 0.0f
#define MIN_NF 0.0f
#define MAX_NF 70.0f
#define MIN_QOS 1
#define MAX_QOS 5

// Validation counters
typedef struct {
    int snr_failures;
    int nf_failures;
    int qos_failures;
} ValidationErrorCount;

// Logging verbosity levels
typedef enum { LOG_NONE, LOG_ERROR, LOG_WARNING, LOG_INFO } LogLevel;

// External logging function (stub)
void log_message(LogLevel level, const char* message) {
    // Stub implementation - replace with actual logging mechanism
    printf("Log [%d]: %s\n", level, message);
