// Memory pool structure
typedef struct {
    size_t element_size;
    size_t capacity;
    NFAPI_RX_FRAME_T* pool;
    NFAPI_RX_FRAME_T* free_list;
} MemoryPool;

MemoryPool frame_pool = { sizeof(NFAPI_RX_FRAME_T), 0, NULL, NULL };

// Initialize the memory pool
void init_memory_pool(size_t element_size, size_t capacity) {
    frame_pool.element_size = element_size;
    frame_pool.capacity = capacity;
    frame_pool.pool = (NFAPI_RX_FRAME_T*)malloc(element_size * capacity);
    frame_pool.free_list = frame_pool.pool;

    for (size_t i = 0; i < capacity - 1; ++i) {
        ((NFAPI_RX_FRAME_T*)frame_pool.pool)[i].next = &((NFAPI_RX_FRAME_T*)frame_pool.pool)[i + 1];
    }
    ((NFAPI_RX_FRAME_T*)frame_pool.pool)[capacity - 1].next = NULL;
}

// Function to allocate a frame from the pool
NFAPI_RX_FRAME_T* alloc_frame() {
    if (frame_pool.free_list == NULL) {
        log_message(LOG_ERROR, "Memory pool exhausted");
        return NULL;
    }
    NFAPI_RX_FRAME_T* frame = frame_pool.free_list;
    frame_pool.free_list = frame->next;
    return frame;
}

// Function to free a frame back to the pool
void free_frame(NFAPI_RX_FRAME_T* frame) {
    frame->next = frame_pool.free_list;
    frame_pool.free_list = frame;
}

// Function to validate input values and populate frames
NFAPI_RX_FRAME_T* initialize_nfar_frames(int M, ValidationErrorCount* errors) {
    if (M > M_MAX_FRAMES) M = M_MAX_FRAMES;

    NFAPI_RX_FRAME_T* head = NULL, *tail = NULL;
    for (int i = 0; i < M; ++i) {
        NFAPI_RX_FRAME_T* frame = alloc_frame();
        if (!frame) break;

        // Example values - replace with actual input
        int ue_id = rand() % 10000;
        float snr = ((float)(rand() % (int)(MAX_SNR - MIN_SNR + 1)) / RAND_MAX * (MAX_SNR - MIN_SNR)) + MIN_SNR;
        float nf = ((float)(rand() % (int)(MAX_NF - MIN_NF + 1)) / RAND_MAX * (MAX_NF - MIN_NF)) + MIN_NF;
        int qos = rand() % (MAX_QOS - MIN_QOS + 1) + MIN_QOS;

        // Validation and assignment
        if (snr < MIN_SNR || snr > MAX_SNR) {
            errors->snr_failures++;
            log_message(LOG_WARNING, "SNR out of range");
        } else {
            frame->SNR = snr;
        }

        if (nf < MIN_NF || nf > MAX_NF) {
            errors->nf_failures++;
            log_message(LOG_WARNING, "NF out of range");
        } else {
            frame->NF = nf;
        }

        if (qos < MIN_QOS || qos > MAX_QOS) {
            errors->qos_failures++;
            log_message(LOG_WARNING, "QoS out of range");
        } else {
            frame->QoS = qos;
        }

        // Assign valid UE ID
        frame->UE_ID = ue_id;

        // Add to the list
        if (!head) head = tail = frame;
        else {
            tail->next = frame;
            tail = frame;
        }
    }
    return head;
}

// Main function for demonstration purposes
int main() {
    ValidationErrorCount errors = {0, 0, 0};
    init_memory_pool(sizeof(NFAPI_RX_FRAME_T), M_MAX_FRAMES);
    NFAPI_RX_FRAME_T* frames = initialize_nfar_frames(10, &errors);

    // Print validation error counts
    printf("SNR Failures: %d\n", errors.snr_failures);
    printf("NF Failures: %d\n", errors.nf_failures);
    printf("QoS Failures: %d\n", errors.qos_failures);

    // Cleanup
    while (frames) {
        NFAPI_RX_FRAME_T* temp = frames;
        frames = frames->next;
        free_frame(temp);
    }

    return 0;
}
