    dynamic_array->capacity = INITIAL_CAPACITY;
    dynamic_array->array = malloc(dynamic_array->capacity * sizeof(LTE_RRC_Message));
    pthread_mutex_init(&dynamic_array->lock, NULL);
}

void resize_dynamic_array(DynamicArray *dynamic_array) {
    size_t new_capacity = dynamic_array->capacity * 2;
    LTE_RRC_Message *new_array = realloc(dynamic_array->array, new_capacity * sizeof(LTE_RRC_Message));

    if (new_array != NULL) {
        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;
    } else {
        perror("Failed to resize array");
        exit(EXIT_FAILURE);
    }
}

void add_message(DynamicArray *dynamic_array, LTE_RRC_Message message) {
    pthread_mutex_lock(&dynamic_array->lock);

    if (dynamic_array->size == dynamic_array->capacity) {
        resize_dynamic_array(dynamic_array);
    }

    dynamic_array->array[dynamic_array->size++] = message;

    pthread_mutex_unlock(&dynamic_array->lock);
}

void update_measurement_reports(DynamicArray *dynamic_array, size_t index) {
    pthread_mutex_lock(&dynamic_array->lock);

    if (index < dynamic_array->size) {
        LTE_RRC_Message *message = &dynamic_array->array[index];

        // Generate random reports
        for (size_t i = 0; i < message->message_body.count; ++i) {
            message->message_body.reports[i] = rand() % 100;
        }
    }

    pthread_mutex_unlock(&dynamic_array->lock);
}

void free_dynamic_array(DynamicArray *dynamic_array) {
    for (size_t i = 0; i < dynamic_array->size; ++i) {
        free(dynamic_array->array[i].message_body.reports);
    }
    free(dynamic_array->array);
    pthread_mutex_destroy(&dynamic_array->lock);
}

void create_and_configure_message(DynamicArray *dynamic_array, int pdu_id, size_t report_count) {
    if (report_count > MAX_REPORTS) {
        fprintf(stderr, "Exceeded maximum number of reports\n");
        return;
    }

    LTE_RRC_Message message = { .pdu_id = pdu_id };
    message.message_body.reports = malloc(report_count * sizeof(int));
    message.message_body.count = report_count;

    if (message.message_body.reports == NULL) {
        perror("Failed to allocate memory for reports");
        exit(EXIT_FAILURE);
    }

    add_message(dynamic_array, message);
}

int main() {
    srand(time(NULL));

    DynamicArray dynamic_array;
    init_dynamic_array(&dynamic_array);

    create_and_configure_message(&dynamic_array, 1, 50);
    create_and_configure_message(&dynamic_array, 2, 75);

    // Example of updating measurement reports in thread-safe manner
    update_measurement_reports(&dynamic_array, 0); 
    update_measurement_reports(&dynamic_array, 1);

    free_dynamic_array(&dynamic_array);

    return 0;
}
