### Java Code

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class ConnectionManager {

    private static final int INITIAL_RETRY_DELAY = 100; // milliseconds
    private static final int MAX_RETRIES = 5;

    public void connectWithRetry(String host, int port) {
        int retryCount = 0;
        int delay = INITIAL_RETRY_DELAY;

        while (retryCount < MAX_RETRIES) {
            try (SocketChannel channel = SocketChannel.open()) {
                if (channel.connect(new InetSocketAddress(host, port))) {
                    System.out.println("Connection successful");
                    onConnectSuccess();
                    return;
                }
            } catch (IOException e) {
                System.err.println("Connection attempt failed: " + e.getMessage());
                retryCount++;
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                delay *= 2; // Exponential backoff
            }
        }

        onConnectFailure();
    }

    private void onConnectSuccess() {
        // Handle successful connection logic
    }

    private void onConnectFailure() {
        System.err.println("All connection attempts failed.");
    }

    public static void main(String[] args) {
        ConnectionManager manager = new ConnectionManager();
        manager.connectWithRetry("localhost", 8080);
    }
}
```

