#define MAX_DOC_LENGTH 4096
#define ALIGNMENT 64
#define NUM_CATEGORIES 3

typedef enum {
    CATEGORY_A,
    CATEGORY_B,
    CATEGORY_C
} Category;

typedef struct ActionFunction {
    void (*process)(void*);
} ActionFunction;

typedef struct Tag {
    Category category;
    ActionFunction* action;
} Tag;

typedef struct Document {
    char *content;
    size_t tag_count;
    Tag tags[10]; // Assume a max of 10 tags per document
    time_t timestamp;
    int ref_count;
    pthread_mutex_t lock;
} Document;

Document** documents = NULL;
size_t doc_count = 0;
pthread_rwlock_t collection_lock = PTHREAD_RWLOCK_INITIALIZER;

void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

void free_aligned(void *ptr) {
    free(ptr);
}

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t n = 0; n < length - 1; ++n) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[n] = charset[key];
    }
    str[length - 1] = '\0';
}

void action_a(void *doc) {
    // Define processing for CATEGORY_A
}

void action_b(void *doc) {
    // Define processing for CATEGORY_B
}

void action_c(void *doc) {
    // Define processing for CATEGORY_C
}

ActionFunction* get_action_function(Category category) {
    switch (category) {
        case CATEGORY_A: return &(ActionFunction){.process = action_a};
        case CATEGORY_B: return &(ActionFunction){.process = action_b};
        case CATEGORY_C: return &(ActionFunction){.process = action_c};
        default: return NULL;
    }
}

Document* create_document() {
    Document *doc = aligned_alloc(sizeof(Document), ALIGNMENT);
    if (!doc) return NULL;

    doc->content = aligned_alloc(MAX_DOC_LENGTH, ALIGNMENT);
    if (!doc->content) {
        free_aligned(doc);
        return NULL;
    }

    generate_random_string(doc->content, rand() % MAX_DOC_LENGTH + 1);

    doc->tag_count = rand() % 10; // Random number of tags
    for (size_t i = 0; i < doc->tag_count; ++i) {
        Category category = rand() % NUM_CATEGORIES;
        Tag *tag = &doc->tags[i];
        tag->category = category;
        tag->action = get_action_function(category);
    }

    doc->timestamp = time(NULL);
    doc->ref_count = 1;
    pthread_mutex_init(&doc->lock, NULL);

    return doc;
}

void add_document(Document **docs, size_t *count) {
    pthread_rwlock_wrlock(&collection_lock);

    Document *new_doc = create_document();
    if (!new_doc) {
        fprintf(stderr, "Failed to create document.\n");
        pthread_rwlock_unlock(&collection_lock);
        return;
    }

    *docs = realloc(*docs, (*count + 1) * sizeof(Document*));
    (*docs)[*count] = new_doc;
    (*count)++;

    pthread_rwlock_unlock(&collection_lock);
}

void iterate_and_process() {
    pthread_rwlock_rdlock(&collection_lock);

    for (size_t i = 0; i < doc_count; ++i) {
        Document *doc = documents[i];
        pthread_mutex_lock(&doc->lock);

        for (size_t j = 0; j < doc->tag_count; ++j) {
            Tag *tag = &doc->tags[j];
            if (tag->action) {
                tag->action(doc);
            }
        }

        pthread_mutex_unlock(&doc->lock);
    }

    pthread_rwlock_unlock(&collection_lock);
}

void validate_documents() {
    for (size_t i = 0; i < doc_count; ++i) {
        Document *doc = documents[i];

        if (!doc || !doc->content || !doc->tags[0].action) continue;

        // Check alignment
        size_t offset = (size_t)doc % ALIGNMENT;
        if (offset != 0) {
            fprintf(stderr, "Document at index %zu is not aligned.\n", i);
        }

        // Check null-termination of content
        for (int n = 0; n < MAX_DOC_LENGTH && doc->content[n]; ++n) {}
        if (doc->content[MAX_DOC_LENGTH - 1] != '\0') {
            fprintf(stderr, "Document at index %zu is not properly null-terminated.\n", i);
        }
    }
}

void free_document(Document *doc) {
    pthread_mutex_lock(&doc->lock);

    doc->ref_count--;
    if (doc->ref_count == 0) {
        pthread_mutex_unlock(&doc->lock);
        free_aligned(doc->content);
        pthread_mutex_destroy(&doc->lock);
        free_aligned(doc);
    } else {
        pthread_mutex_unlock(&doc->lock);
    }
}

int main() {
    srand(time(NULL));

    for (size_t i = 0; i < 100; ++i) { // Create 100 documents
        add_document(&documents, &doc_count);
    }

    iterate_and_process();
    validate_documents();

    for (size_t i = 0; i < doc_count; ++i) {
        free_document(documents[i]);
    }

    free(documents);
    pthread_rwlock_destroy(&collection_lock);

    return 0;
}
