#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_RNTI 0x0FFF

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t rnti_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static uint16_t available_rntis[MAX_RNTI + 1];
static int available_rntis_count = MAX_RNTI;
static int crc_flag_toggle = 0;

void initialize_rnti_pool() {
    for (uint16_t i = 1; i <= MAX_RNTI; ++i) {
        available_rntis[available_rntis_count--] = i;
    }
}

uint16_t get_next_rnti() {
    pthread_mutex_lock(&rnti_pool_lock);
    if (available_rntis_count < 0) {
        pthread_mutex_unlock(&rnti_pool_lock);
        return 0; // No available RNTI
    }
    uint16_t rnti = available_rntis[available_rntis_count--];
    pthread_mutex_unlock(&rnti_pool_lock);
    return rnti;
}

void release_rnti(uint16_t rnti) {
    pthread_mutex_lock(&rnti_pool_lock);
    if (rnti > 0 && rnti <= MAX_RNTI) {
        available_rntis[++available_rntis_count] = rnti;
    }
    pthread_mutex_unlock(&rnti_pool_lock);
}

int validate_ue_tag(uint32_t tag) {
    // Placeholder for actual validation logic
    return (tag != 0); // Assume non-zero is valid
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(int N, FILE *log_fd) {
    if (N <= 0 || log_fd == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(log_fd, "Memory allocation failed\n");
        return NULL;
    }

    initialize_rnti_pool();

    for (int i = 0; i < N; ++i) {
        uint32_t ue_tag = rand(); // Example generation
        if (!validate_ue_tag(ue_tag)) {
            fprintf(log_fd, "Invalid UE tag: %u\n", ue_tag);
            continue;
        }

        uint16_t rnti = get_next_rnti();
        if (rnti == 0) {
            fprintf(log_fd, "No available RNTI\n");
            break; // Exit loop if no RNTI is available
        }

        array[i].RX_UE_INFORMATION_TAG = ue_tag;
        array[i].RNTI = rnti;
        array[i].CRCFLAG = crc_flag_toggle;
        crc_flag_toggle = !crc_flag_toggle; // Toggle between 0 and 1
    }

    return array;
}

void print_array(NFAPI_CRC_INDICATION_PDU_T *array, int N, FILE *fd) {
    if (!array || fd == NULL) return;

    for (int i = 0; i < N; ++i) {
        fprintf(fd, "UE Tag: %u, RNTI: %d, CRCFLAG: %d\n",
                array[i].RX_UE_INFORMATION_TAG,
                array[i].RNTI,
                array[i].CRCFLAG);
    }
}

void cleanup_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (!array) return;

    for (int i = 0; i < N; ++i) {
        release_rnti(array[i].RNTI);
    }

    free(array);
}
