#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>

#define MAX_DCC 10000
#define LOG_BUFFER_SIZE 1024

typedef struct {
    int lun;
    size_t block_size;
    unsigned int checksum;
} DiskControllerConfig;

typedef enum { INTERFACE_TYPE_A, INTERFACE_TYPE_B, UNKNOWN } InterfaceType;

typedef struct {
    int (*validate_lun)(int lun);
    void (*log_failure)(const char *message);
} StorageManagementSystemCallbacks;

// Function prototypes
DiskControllerConfig* initialize_dcc_array(size_t count, StorageManagementSystemCallbacks sms_callbacks, const int* backup_luns, size_t backup_size, InterfaceType interface_type);
static void* dcc_init_thread(void* arg);
void log_message(const char* message);

// Global variables for logging and control
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t valid_dcc_count = 0;

DiskControllerConfig* initialize_dcc_array(size_t count, StorageManagementSystemCallbacks sms_callbacks, const int* backup_luns, size_t backup_size, InterfaceType interface_type) {
    if (interface_type == UNKNOWN || (interface_type != INTERFACE_TYPE_A && interface_type != INTERFACE_TYPE_B)) {
        log_message("Unsupported disk controller interface type.");
        return NULL;
    }

    DiskControllerConfig *dcc_array = (DiskControllerConfig*)malloc(count * sizeof(DiskControllerConfig));
    if (!dcc_array) {
        log_message("Memory allocation failed for DCC array.");
        return NULL;
    }

    size_t thread_count = count > 0 ? count : 1; // At least one thread
    pthread_t threads[thread_count];
    int luns[count];

    for (size_t i = 0; i < count; ++i) {
        if (sms_callbacks.validate_lun(i) != 0) { // Assuming non-zero means invalid
            log_message("Invalid LUN detected.");

            size_t backup_index = i % backup_size;
            luns[i] = backup_luns[backup_index];
            sms_callbacks.log_failure("Using backup LUN.");
        } else {
            luns[i] = i;
        }
    }

    for (size_t i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, dcc_init_thread, &luns[i * (count / thread_count)]) != 0) {
            log_message("Failed to create pthread.");
        }
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return dcc_array;
}

static void* dcc_init_thread(void* arg) {
    int lun = *(int*)arg;

    DiskControllerConfig config;
    config.lun = lun;
    config.block_size = 4096; // Example block size
    config.checksum = (lun * 42) % 256; // Simplistic checksum calculation

    pthread_mutex_lock(&log_mutex);
    valid_dcc_count++;
    pthread_mutex_unlock(&log_mutex);

    return NULL;
}

void log_message(const char* message) {
    pthread_mutex_lock(&log_mutex);
    printf("Log: %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}
```

### Explanation:

- **Memory Management**: The code dynamically allocates memory for the DCC array and supports multi-threaded initialization using POSIX threads.

- **Error Checking**: Checks are in place to ensure valid interface types, handle memory allocation failures, and manage invalid LUNs.

- **Multi-Threading**: Each thread initializes a segment of the DCC array. The number of threads is set equal to the count for parallel processing.

- **Integration with SMS**: Uses callbacks to validate LUNs and log failures. If an LUN is invalid, it uses a backup LUN from a provided list.

- **Logging**: A simple logging mechanism using mutexes ensures thread-safe logging of messages.

This code provides a robust starting point, but you may need to adapt the `StorageManagementSystemCallbacks` definitions and logic based on your specific SMS implementation. Additionally, consider enhancing the error handling and logging mechanisms as needed for production environments.']

