### Java Method to Establish a Channel-Based Connection

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class NetworkConnector {

    public static void main(String[] args) {
        try {
            establishConnection("localhost", 8080, 5000); // Example parameters
        } catch (IOException e) {
            System.err.println("Failed to establish connection: " + e.getMessage());
        }
    }

    public static void establishConnection(String host, int port, int timeoutMillis) throws IOException {
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);

        try {
            InetSocketAddress address = new InetSocketAddress(host, port);

            long startTime = System.currentTimeMillis();
            while (!socketChannel.finishConnect()) {
                if (System.currentTimeMillis() - startTime > timeoutMillis) {
                    throw new IOException("Connection timed out");
                }
                Thread.sleep(50); // Sleep briefly before retrying
            }

            System.out.println("Successfully connected to " + host + ":" + port);
        } finally {
            socketChannel.close();
        }
    }
}
```

