['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    time_t timestamp;
    uint32_t id;
    int ref_count;
} data_packet;

typedef struct {
    data_packet *packets;
    char **strings;
    double *doubles;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    uint32_t next_id;
} MemoryManager;

void init_manager(MemoryManager *manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    manager->next_id = 1;

    manager->packets = malloc(manager->capacity * sizeof(data_packet));
    manager->strings = malloc(manager->capacity * sizeof(char *));
    manager->doubles = malloc(manager->capacity * sizeof(double));

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
}

void resize_manager(MemoryManager *manager) {
    size_t new_capacity = manager->capacity * 2;

    data_packet *new_packets = realloc(manager->packets, new_capacity * sizeof(data_packet));
    char **new_strings = realloc(manager->strings, new_capacity * sizeof(char *));
    double *new_doubles = realloc(manager->doubles, new_capacity * sizeof(double));

    if (new_packets && new_strings && new_doubles) {
        manager->packets = new_packets;
        manager->strings = new_strings;
        manager->doubles = new_doubles;
        manager->capacity = new_capacity;
    } else {
        // Handle allocation failure
        perror("Failed to resize memory");
        exit(EXIT_FAILURE);
    }
}

void insert_data_packet(MemoryManager *manager, const char *string, double value) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity) {
        resize_manager(manager);
    }

    time_t now = time(NULL);
    int random_offset_ms = rand() % 2001 - 1000;
    struct timespec ts = { .tv_sec = now + random_offset_ms / 1000, .tv_nsec = (random_offset_ms % 1000) * 1000000 };
    clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);

    uint32_t id = manager->next_id++;

    manager->packets[manager->size].timestamp = now + random_offset_ms / 1000;
    manager->packets[manager->size].id = id;
    manager->packets[manager->size].ref_count = 1;

    manager->strings[manager->size] = strdup(string);
    manager->doubles[manager->size] = value;

    manager->size++;

    pthread_mutex_unlock(&manager->mutex);
}

void increment_ref(MemoryManager *manager, uint32_t id) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].id == id) {
            manager->packets[i].ref_count++;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void decrement_ref(MemoryManager *manager, uint32_t id) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].id == id) {
            if (--manager->packets[i].ref_count <= 0) {
                free(manager->strings[i]);
                // Shift remaining elements
                memmove(&manager->packets[i], &manager->packets[i + 1], 
                        (manager->size - i - 1) * sizeof(data_packet));
                memmove(&manager->strings[i], &manager->strings[i + 1],
                        (manager->size - i - 1) * sizeof(char *));
                memmove(&manager->doubles[i], &manager->doubles[i + 1],
                        (manager->size - i - 1) * sizeof(double));
                manager->size--;
            }
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void archive_data(MemoryManager *manager, const char *archive_path) {
    FILE *file = fopen(archive_path, "w");
    if (!file) {
        perror("Failed to open archive file");
        return;
    }

    for (size_t i = 0; i < manager->size; ++i) {
        fprintf(file, "%lu %u %s %f\n", manager->packets[i].timestamp,
                manager->packets[i].id, manager->strings[i], manager->doubles[i]);
    }

    fclose(file);
}

void cleanup_manager(MemoryManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->strings[i]);
    }

    free(manager->packets);
    free(manager->strings);
    free(manager->doubles);

    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond_var);
}

int main() {
    srand(time(NULL));
    MemoryManager manager;
    init_manager(&manager);

    insert_data_packet(&manager, "Hello", 3.14);
    increment_ref(&manager, 1);
    decrement_ref(&manager, 1);

    archive_data(&manager, "archive.txt");

    cleanup_manager(&manager);
    return 0;
}
```']

