```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 1000
#define MAX_CRCFLAG_VALUE 1

typedef struct {
    uint16_t valid_RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

static void resize_list_if_needed(DynamicList *list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            perror("Failed to resize the list");
            exit(EXIT_FAILURE);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void insert_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (pdu.CRC_INDICATION_REL8_TAG > MAX_CRCFLAG_VALUE) {
        fprintf(stderr, "Invalid CRCFLAG value detected. Skipping insertion.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    resize_list_if_needed(list);
    list->data[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_pdu(DynamicList *list, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T pdu = {0};
    if (index < list->size) {
        pthread_mutex_lock(&list->lock);
        pdu = list->data[index];
        pthread_mutex_unlock(&list->lock);
    }
    return pdu;
}

// Unit Tests
#include <assert.h>

void test_dynamic_list() {
    DynamicList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .valid_RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = 0 };
    insert_pdu(&list, pdu1);

    assert(list.size == 1);
    assert(get_pdu(&list, 0).valid_RX_UE_INFORMATION_TAG == 1);

    NFAPI_CRC_INDICATION_PDU_T invalid_pdu = { .valid_RX_UE_INFORMATION_TAG = 3, .RNTI = 4, .CRC_INDICATION_REL8_TAG = 2 };
    insert_pdu(&list, invalid_pdu);
    assert(list.size == 1); // Invalid insertion should not increase size

    free_list(&list);
}

int main() {
    test_dynamic_list();
    printf("All tests passed.\n");
    return 0;
}
```

### Key Points:

