#include <time.h>

typedef struct {
    int value;
} record;

void initialize_arrays(long *offsets, int *keys, record *records, size_t num_elements, 
                       long offset_size, int key_size, size_t record_size, 
                       size_t max_memory_size) {

    size_t total_mem_required = num_elements * (sizeof(*offsets) + sizeof(*keys) + record_size);
    if (total_mem_required > max_memory_size) {
        printf("Adjusting number of elements due to memory constraint...\n");
        double ratio = (double)max_memory_size / total_mem_required;
        size_t adjusted_num_elements = (size_t)(num_elements * ratio);

        total_mem_required = adjusted_num_elements * (sizeof(*offsets) + sizeof(*keys) + record_size);

        printf("Adjusted number of elements: %zu\n", adjusted_num_elements);
    }

    offsets = malloc(adjusted_num_elements * offset_size);
    if (!offsets) {
        fprintf(stderr, "Memory allocation for offsets failed.\n");
        exit(EXIT_FAILURE);
    }

    keys = malloc(adjusted_num_elements * key_size);
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation for keys failed.\n");
        exit(EXIT_FAILURE);
    }

    records = malloc(adjusted_num_elements * record_size);
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    long min_value = 0; // Define range
    long max_value = 100;

    for (size_t i = 0; i < adjusted_num_elements; ++i) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Memory usage logging
    printf("Memory allocated: %zu bytes for offsets, %zu bytes for keys, %zu bytes for records.\n",
           adjusted_num_elements * offset_size,
           adjusted_num_elements * key_size,
           adjusted_num_elements * record_size);
}

// Function to free allocated memory
void free_resources(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
