#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    float score;
    size_t index;
    atomic_size_t ref_count; // Reference count using atomic operations for thread safety
} item;

// Mutex for synchronizing access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *allocate_arrays(size_t num_items, double **weights, char **categories, item ***items) {
    if (num_items <= 0) return NULL;

    // Allocate memory for arrays
    *weights = malloc(num_items * sizeof(double));
    *categories = malloc(num_items * sizeof(char));
    *items = malloc(num_items * sizeof(item*));

    if (!(*weights) || !(*categories) || !(*items)) {
        free(*weights); 
        free(*categories); 
        free(*items);
        return NULL;
    }

    // Initialize each item
    for (size_t i = 0; i < num_items; ++i) {
        (*items)[i] = malloc(sizeof(item));
        if (!(*items)[i]) {
            for (size_t j = 0; j <= i; ++j) free((*items)[j]);
            free(*weights);
            free(*categories);
            free(*items);
            return NULL;
        }
        atomic_store(&(*items)[i]->ref_count, 1); // Initialize reference count to 1
        (*items)[i]->index = i;
    }

    return *items; // Return pointer to allocated items array
}

void set_item_score(item* item, float score) {
    pthread_mutex_lock(&mutex);
    item->score = score;
    pthread_mutex_unlock(&mutex);
}

float get_item_score(const item* item) {
    pthread_mutex_lock(&mutex);
    float score = item->score;
    pthread_mutex_unlock(&mutex);
    return score;
}

size_t active_items_count(item **items, size_t num_items) {
    size_t count = 0;
    for (size_t i = 0; i < num_items; ++i) {
        if (atomic_load(&items[i]->ref_count) > 0) {
            count++;
        }
    }
    return count;
}

void update_scores(item **items, double *weights, size_t num_items) {
    for (size_t i = 0; i < num_items; ++i) {
        float weighted_sum = 0.0;
        double weight_total = 0.0;

        // Calculate the weighted sum
        pthread_mutex_lock(&mutex);
        for (size_t j = 0; j < num_items; ++j) {
            if (atomic_load(&items[j]->ref_count) > 0) { // Only consider active items
                weighted_sum += get_item_score(items[j]) * weights[j];
                weight_total += weights[j];
            }
        }
        pthread_mutex_unlock(&mutex);

        // Avoid division by zero, set to current score if no valid weights found
        float new_score = (weight_total > 0) ? (weighted_sum / weight_total) : get_item_score(items[i]);

        // Update item's score atomically
        atomic_store(&items[i]->score, new_score);
    }
}

void increment_ref_count(item* item) {
    atomic_fetch_add(&item->ref_count, 1);
}

void decrement_ref_count(item* item) {
    if (atomic_fetch_sub(&item->ref_count, 1) == 1) { // Check if this was the last reference
        pthread_mutex_lock(&mutex);
        free(item); // Free memory only if ref_count reached zero
        pthread_mutex_unlock(&mutex);
    }
}

// Example usage and error handling can be expanded as needed

int main() {
    size_t num_items = 1000;
    double *weights = NULL, *categories = NULL;
    item **items = NULL;

    // User-provided weights for the example
    double user_weights[1000]; 
    for (size_t i = 0; i < num_items; ++i) {
        user_weights[i] = 1.0 / num_items;
    }

    if (!allocate_arrays(num_items, &weights, &categories, &items)) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Example of setting a score
    set_item_score(items[0], 10.0);

    // Update all scores based on weights
    update_scores(items, user_weights, num_items);

    // Retrieve and print active item count
    size_t active_count = active_items_count(items, num_items);
    printf("Active items: %zu\n", active_count);

    // Cleanup
    for (size_t i = 0; i < num_items; ++i) {
        decrement_ref_count(items[i]);
    }
    free(weights); 
    free(categories); 
    free(items);

    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}
