#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT (1024 * 1024 * 512) // Example: 512 MB limit
#define MAX_FILE_DESCRIPTORS 1024            // Example: system-specific limit

typedef struct {
    char *buffer;
    int offset;
    volatile int ref_count;
} Document;

Document* documents = NULL;
pthread_mutex_t doc_mutex = PTHREAD_MUTEX_INITIALIZER;

int validate_parameters(size_t n, size_t doc_size) {
    if (n == 0 || doc_size == 0) return -1;
    if ((n * doc_size) > MAX_MEMORY_LIMIT) return -2;
    if (n > MAX_FILE_DESCRIPTORS) return -3;
    return 0;
}

Document* allocate_documents(size_t n, size_t doc_size) {
    Document *docs = malloc(n * sizeof(Document));
    if (!docs) return NULL;

    for (size_t i = 0; i < n; ++i) {
        docs[i].buffer = calloc(1, doc_size);
        if (!docs[i].buffer) {
            for (size_t j = 0; j < i; ++j) free(docs[j].buffer);
            free(docs);
            return NULL;
        }
        docs[i].offset = -1;
        docs[i].ref_count = 1;
    }

    return docs;
}

void initialize_documents(size_t n, size_t doc_size) {
    char template[] = "Document %zu: Content goes here.";

    pthread_mutex_lock(&doc_mutex);
    for (size_t i = 0; i < n; ++i) {
        snprintf(documents[i].buffer, doc_size, template, i + 1);
    }
    pthread_mutex_unlock(&doc_mutex);
}

void increment_ref_count(Document *doc) {
    __sync_fetch_and_add(&(doc->ref_count), 1);
}

void decrement_ref_count(Document *doc) {
    if (__sync_sub_and_fetch(&(doc->ref_count), 1) == 0) {
        free(doc->buffer);
        // Optionally handle document deallocation logic here
    }
}

void cleanup_documents(size_t n) {
    pthread_mutex_lock(&doc_mutex);
    for (size_t i = 0; i < n; ++i) {
        decrement_ref_count(&documents[i]);
    }
    free(documents);
    pthread_mutex_unlock(&doc_mutex);
}

int main(int argc, char *argv[]) {
    size_t n = 100;
    size_t doc_size = 256;

    int validation_status = validate_parameters(n, doc_size);
    if (validation_status != 0) {
        fprintf(stderr, "Invalid parameters: %d\n", validation_status);
        return EXIT_FAILURE;
    }

    documents = allocate_documents(n, doc_size);
    if (!documents) {
        fprintf(stderr, "Failed to allocate memory for documents.\n");
        return EXIT_FAILURE;
    }

    initialize_documents(n, doc_size);

    // Simulate document usage
    increment_ref_count(&documents[0]);
    decrement_ref_count(&documents[0]);

    cleanup_documents(n);
    pthread_mutex_destroy(&doc_mutex);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Validation**: Checks for valid input sizes and system limits.
- **Memory Allocation**: Allocates memory for documents with error handling to free allocated resources if any allocation fails.
- **Thread Safety**: Uses mutex locks to protect shared data during initialization.
- **Reference Counting**: Implements atomic operations for incrementing and decrementing reference counts, ensuring thread safety without explicit locks.
- **Error Handling**: Gracefully handles memory allocation failures.
- **Extensibility**: Designed with modular functions for easy integration of additional features or document formats.']

