void* allocate_memory(size_t size, size_t alignment) {
    void *ptr = aligned_alloc(alignment, size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_mmu(MemoryManager *manager, size_t block_size, int page_size, int protection_flags, size_t entry_count) {
    pthread_mutex_lock(&manager->lock);

    if (!validate_memory_policy(block_size, page_size)) {
        fprintf(stderr, "Invalid memory policy configuration\n");
        exit(EXIT_FAILURE);
    }

    manager->config.block_size = block_size;
    manager->config.page_size = page_size ? page_size : DEFAULT_PAGE_SIZE;
    manager->config.protection_flags = protection_flags ? protection_flags : DEFAULT_PROTECTION_FLAGS;
    manager->config.entry_count = entry_count;

    size_t total_memory = block_size * entry_count;
    manager->config.entries = (MMUEntry *)allocate_memory(total_memory, manager->config.page_size);

    for (size_t i = 0; i < entry_count; ++i) {
        MMUEntry *entry = &manager->config.entries[i];
        entry->pte = ((unsigned long)(manager->config.block_size * i)) | manager->config.protection_flags;
        entry->virtual_address = (void *)(((unsigned long)entry->pte) + sizeof(MMUEntry));
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_memory_manager(MemoryManager *manager) {
    if (manager->config.entries) {
        free(manager->config.entries);
        manager->config.entries = NULL;
    }
}

