fn validate_key_uniqueness(keys: &[i32]) -> bool {
    let mut seen = HashSet::new();
    for &key in keys {
        if !seen.insert(key) || key < KEY_RANGE.0 || key > KEY_RANGE.1 {
            return false;
        }
    }
    true
}

fn allocate_and_initialize() -> Result<(), &'static str> {
    // Measure start time and memory usage
    let start_time = Instant::now();
    let start_memory = get_resident_set_size();

    // Allocate arrays
    let offsets: Vec<i64> = (0..RECORD_COUNT)
        .map(|_| thread_rng().gen_range(0, MAX_OFFSET))
        .collect();

    let keys: Vec<i32> = (0..RECORD_COUNT)
        .map(|_| thread_rng().gen_range(KEY_RANGE.0, KEY_RANGE.1 + 1))
        .collect();

    if !validate_key_uniqueness(&keys) {
        return Err("Invalid or duplicate keys found.");
    }

    let values: Vec<f64> = (0..RECORD_COUNT).map(|_| thread_rng().gen()).collect();
    let mut unique_strings: HashMap<i32, CString> = HashMap::new();

    for i in 0..RECORD_COUNT {
        let string = format!("ID-{}", i);
        unique_strings.insert(keys[i], CString::new(string).unwrap());
    }

    // Allocate records
    let mut records: Vec<*mut Record> = vec![ptr::null_mut(); RECORD_COUNT];
    let mut free_indices = (0..RECORD_COUNT).collect::<Vec<_>>();

    thread_rng().shuffle(&mut free_indices);

    for &index in &free_indices {
        if records[index] != ptr::null_mut() {
            continue;
        }

        unsafe {
            records[index] = libc::malloc(std::mem::size_of::<Record>()) as *mut Record;

            if records[index].is_null() {
                // Free allocated memory on failure
                for &record in &records {
                    if !record.is_null() {
                        libc::free(record as *mut c_void);
                    }
                }
                return Err("Failed to allocate memory for records.");
            }

            let record = records[index];
            (*record).value = keys[index];

            // Fetch initial data from external source
            match fetch_initial_values() {
                Some((init_value, init_data)) => {
                    (*record).data = init_data;
                    (*record).next = ptr::null_mut();
                }
                None => {
                    (*record).data = values[index];
                    (*record).next = ptr::null_mut();
                },
            }

            // Allocate additional data
            let additional_data_str = unique_strings.get(&keys[index]).unwrap().as_ptr();
            (*record).additional_data = libc::malloc((STRING_LENGTH + 1) * std::mem::size_of::<c_char>()) as *mut c_char;

            if (*record).additional_data.is_null() {
                // Free allocated memory on failure
                for &rec in &records {
                    if !rec.is_null() {
                        libc::free(rec as *mut c_void);
                    }
                }
                return Err("Failed to allocate additional data.");
            }

            unsafe { std::ptr::copy(additional_data_str, (*record).additional_data, STRING_LENGTH + 1) };
        }
    }

    // Shuffle records if needed
    shuffle_records(&mut records);

    // Verify linked list integrity
    verify_linked_list_integrity(records);

    // Measure end time and memory usage
    let duration = start_time.elapsed();
    let end_memory = get_resident_set_size();

    println!("Time taken: {:?}", duration);
    println!("Memory used: {} -> {}", start_memory, end_memory);

    Ok(())
}

fn shuffle_records(records: &mut Vec<*mut Record>) {
    // Shuffle the order of records
    records.shuffle(&mut thread_rng());
    for i in 0..records.len() - 1 {
        unsafe {
            (*records[i]).next = records[i + 1];
        }
    }
    unsafe { (*records.last().unwrap()).next = ptr::null_mut(); }
}

fn verify_linked_list_integrity(records: &[*mut Record]) -> bool {
    let mut visited = HashSet::new();
    let mut current = records[0];

    while !current.is_null() {
        if visited.contains(current) {
            return false; // Cycle detected
        }
        visited.insert(current);

        current = unsafe { (*current).next };
    }

    true
}

fn get_resident_set_size() -> usize {
