#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <unistd.h>
#include <sys/mman.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define ALIGNMENT 16
#define AES_KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    int value;
    int key;
    int ref_count;
} Record;

typedef struct {
    Record *records;
    long *offsets;
    int *keys;
    size_t num_elements;
    sem_t semaphore;
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char iv[AES_KEY_LENGTH];
} DynamicResourceManager;

void* align_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

int derive_key(const char *password, unsigned char **key_out) {
    unsigned char sha1[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*) password, strlen(password), sha1);
    if ((*key_out = (unsigned char *) malloc(AES_KEY_LENGTH)) == NULL) {
        return 0;
    }
    memcpy(*key_out, sha1, AES_KEY_LENGTH);
    return 1;
}

void DynamicResourceManagerInit(size_t num_records, const char *password) {
    DynamicResourceManager *manager = (DynamicResourceManager*)align_alloc(ALIGNMENT, sizeof(DynamicResourceManager));

    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for manager\n");
        return;
    }

    sem_init(&manager->semaphore, 0, 1);

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    size_t total_elements = num_records;
    while (total_elements > MAX_ELEMENTS) {
        if (!align_alloc(ALIGNMENT, CHUNK_SIZE * sizeof(Record))) {
            fprintf(stderr, "Failed to allocate additional records\n");
            return;
        }
        total_elements -= CHUNK_SIZE;
    }

    manager->records = (Record*) align_alloc(ALIGNMENT, num_records * sizeof(Record));
    manager->offsets = (long*) align_alloc(ALIGNMENT, num_records * sizeof(long));
    manager->keys = (int*) align_alloc(ALIGNMENT, num_records * sizeof(int));

    if (!manager->records || !manager->offsets || !manager->keys) {
        fprintf(stderr, "Failed to allocate arrays\n");
        return;
    }

    unsigned char key[AES_KEY_LENGTH];
    if (!derive_key(password, &key)) {
        fprintf(stderr, "Failed to derive AES key\n");
        return;
    }

    manager->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!manager->cipher_ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != EVP_EncryptInit_ex(manager->cipher_ctx, EVP_aes_256_cbc(), NULL, key, manager->iv)) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int value = rand() % 10000; // Example range
        int key_value;

        do {
            key_value = rand() % 10000; // Ensure unique keys
        } while (manager->keys[i] == key_value);

        manager->records[i].value = value;
        manager->records[i].key = key_value;
        manager->records[i].ref_count = 0;
        manager->offsets[i] = i * sizeof(Record); // Example offset calculation
        manager->keys[i] = key_value;
    }

    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);

    sem_post(&manager->semaphore);

    // Returning the initialized structure as a void pointer.
    return (void*) manager;
}

// Cleanup function example
void DynamicResourceManagerCleanup(void *manager_ptr) {
    DynamicResourceManager *manager = (DynamicResourceManager*) manager_ptr;

    EVP_CIPHER_CTX_free(manager->cipher_ctx);
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);

    sem_destroy(&manager->semaphore);
    free(manager);
}
