#define DEFAULT_VALUE 0
#define LOG_FILE "system_log.txt"
#define LONG_COUNT 100
#define KEY_COUNT 50
#define RECORD_COUNT 200
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 100

typedef uint64_t offset_t;
typedef uint32_t key_t;
typedef struct {
    int value_t; // Assuming 'value_t' is an integer for simplicity
} record_t;

// Global configuration variables (for dynamic updates)
size_t g_long_count = LONG_COUNT;
size_t g_key_count = KEY_COUNT;
size_t g_record_count = RECORD_COUNT;
int g_min_random_value = MIN_RANDOM_VALUE;
int g_max_random_value = MAX_RANDOM_VALUE;

void log_warning(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

bool validate_checksum(const uint8_t *data, size_t length, uint32_t expected_checksum) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum == expected_checksum;
}

offset_t* initialize_offsets(const char *filename, uint32_t checksum) {
    offset_t *offsets = malloc(g_long_count * sizeof(offset_t));
    if (!offsets) {
        log_warning("Memory allocation for offsets failed");
        return NULL;
    }

    int fd = open(filename, O_RDONLY);
    if (fd == -1 || !validate_checksum((const uint8_t *)filename, strlen(filename), checksum)) {
        for (size_t i = 0; i < g_long_count; ++i) {
            offsets[i] = DEFAULT_VALUE;
        }
        log_warning("File not found or corrupted. Using default values.");
    } else {
        if (read(fd, offsets, g_long_count * sizeof(offset_t)) != g_long_count * sizeof(offset_t)) {
            free(offsets);
            log_warning("Failed to read file data");
            return NULL;
        }
        close(fd);
    }

    return offsets;
}

key_t* initialize_keys() {
    key_t *keys = malloc(g_key_count * sizeof(key_t));
    if (!keys) {
        log_warning("Memory allocation for keys failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < g_key_count; ++i) {
        keys[i] = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
    }

    return keys;
}

record_t* initialize_records() {
    record_t *records = malloc(g_record_count * sizeof(record_t));
    if (!records) {
        log_warning("Memory allocation for records failed");
        return NULL;
    }

    int assigned_values[g_key_count] = {0};
    for (size_t i = 0; i < g_key_count; ++i) {
        assigned_values[i] = -1;
    }

    for (size_t i = 0; i < g_record_count; ++i) {
        int value;
        bool is_duplicate;
        do {
            is_duplicate = false;
            value = rand() % (g_max_random_value - g_min_random_value + 1) + g_min_random_value;
            for (size_t j = 0; j < g_key_count; ++j) {
                if (assigned_values[j] == value) {
                    is_duplicate = true;
                    break;
                }
            }
        } while (is_duplicate);

        records[i].value_t = value;
    }

    return records;
}

void* connectToRemote(void *arg) {
    const char *remote_address = (const char *)arg;

    struct addrinfo hints, *res, *p;
    int sockfd, rv;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((rv = getaddrinfo(remote_address, "8080", &hints, &res)) != 0) {
        log_warning("getaddrinfo: %s\n", gai_strerror(rv));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if ((sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            continue;
        }

        int retries = 5;
        while (retries--) {
            if (::connect(sockfd, p->ai_addr, p->ai_addrlen) == -1) {
                close(sockfd);
                sleep(2 << (4 - retries)); // Exponential backoff
                continue;
            }
            break;
        }

        if (retries < 0) {
            log_warning("Failed to connect after retries");
            freeaddrinfo(res);
            return NULL;
        }
        break;
    }

    if (p == NULL) {
        log_warning("Failed to connect to any address");
        freeaddrinfo(res);
        return NULL;
    }

    freeaddrinfo(res);
    // Socket is connected; perform necessary operations
    close(sockfd);

    return NULL;
}

void initializeSystem() {
    offset_t *offsets = initialize_offsets("data.bin", 12345); // Example checksum
    if (!offsets) {
        offsets = malloc(g_long_count * sizeof(offset_t));
        memset(offsets, DEFAULT_VALUE, g_long_count * sizeof(offset_t));
    }

    key_t *keys = initialize_keys();
    if (!keys) return;

    record_t *records = initialize_records();
    if (!records) return;

    pthread_t connection_thread;
    const char *remote_address = "example.com";
    pthread_create(&connection_thread, NULL, connectToRemote, (void *)remote_address);
    pthread_join(connection_thread, NULL);

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    initializeSystem();
    return 0;
}
