### Java Connection Handling

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class NetworkConnector {

    private static final int TIMEOUT = 5000; // in milliseconds

    public void connectToRemote(String host, int port) throws IOException {
        try (SocketChannel socketChannel = SocketChannel.open()) {
            socketChannel.configureBlocking(false);
            InetSocketAddress remoteAddress = new InetSocketAddress(host, port);

            if (socketChannel.connect(remoteAddress)) {
                System.out.println("Connection established.");
            } else {
                if (!waitForConnect(socketChannel, remoteAddress)) {
                    throw new IOException("Connection timed out.");
                }
            }

            handleStateChange(socketChannel);
        }
    }

    private boolean waitForConnect(SocketChannel socketChannel, InetSocketAddress remoteAddress) throws IOException {
        long start = System.currentTimeMillis();
        while (!socketChannel.finishConnect()) {
            if (System.currentTimeMillis() - start > TIMEOUT) return false;
            try {
                Thread.sleep(100); // Polling interval
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException("Interrupted during connection wait.", e);
            }
        }
        return true;
    }

    private void handleStateChange(SocketChannel socketChannel) throws IOException {
        if (socketChannel.isConnected()) {
            System.out.println("Socket is connected.");
        } else if (socketChannel.isConnectionPending()) {
            System.out.println("Connection pending...");
        } else {
            System.out.println("Disconnected or failed to connect.");
        }
    }

    public static void main(String[] args) {
        NetworkConnector connector = new NetworkConnector();
        try {
            connector.connectToRemote("example.com", 80);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
