#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <unistd.h>

#define ALIGNMENT 32
#define MAX_NODES 100
#define ITEM_KEY_RANGE 1000
#define STRING_LENGTH 10
#define MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct Item {
    int key;
    char str[STRING_LENGTH + 1];
} Item;

typedef struct Node {
    double value;
    struct Item* items;
    size_t itemCount;
} Node;

void* aligned_alloc(size_t alignment, size_t size);
void free_aligned(void* ptr);

Node** initializeNodes(int numNodes) {
    Node** nodes = (Node**)aligned_alloc(ALIGNMENT, numNodes * sizeof(Node*));
    if (!nodes) return NULL;

    srand(time(NULL));

    size_t totalMemoryUsage = 0;
    for (int i = 0; i < numNodes; ++i) {
        int randomInt = rand() % 100;
        double sqrtValue = sqrt(randomInt);
        Node* node = (Node*)aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!node) break;

        node->value = sqrtValue;
        node->items = NULL;
        node->itemCount = 0;

        int itemCount = rand() % 10 + 1; // Random item count between 1 and 10
        size_t memoryUsage = sizeof(Item) * itemCount;

        if (totalMemoryUsage + sizeof(Node*) + memoryUsage > MEMORY_LIMIT) {
            free_aligned(node);
            break;
        }

        node->items = (Item*)aligned_alloc(ALIGNMENT, memoryUsage);
        if (!node->items) {
            free_aligned(node);
            break;
        }

        for (int j = 0; j < itemCount; ++j) {
            Item* item = &node->items[j];
            item->key = rand() % ITEM_KEY_RANGE;
            for (int k = 0; k < STRING_LENGTH; ++k) {
                item->str[k] = 'a' + rand() % 26;
            }
            item->str[STRING_LENGTH] = '\0';
        }

        node->itemCount = itemCount;
        nodes[i] = node;

        totalMemoryUsage += sizeof(Node*) + memoryUsage;
    }

    return nodes;
}

void freeNodes(Node** nodes, int numNodes) {
    for (int i = 0; i < numNodes; ++i) {
        if (nodes[i]) {
            free_aligned(nodes[i]->items);
            free_aligned(nodes[i]);
        }
    }
    free_aligned(nodes);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

void free_aligned(void* ptr) {
    free(ptr);
}
