import threading
from collections import deque
from random import randint
import string

# Constants for memory alignment and block size
BLOCK_SIZE = 64  # Align blocks to 64 bytes for optimal cache performance
MAX_ITEMS_PER_NODE = 10
ITEM_STRUCT_SIZE = 24  # Assuming each Item takes up 24 bytes

class Item:
    def __init__(self, key):
        self.key = key
        self.value = ''.join(random.choices(string.ascii_letters + string.digits, k=16))
        self.next = None

class Node:
    def __init__(self):
        self.head = None

class DistributedMemoryManager:
    def __init__(self):
        self.nodes = deque()
        self.lock = threading.Lock()

    def allocate_node(self):
        node = Node()
        with self.lock:
            self.nodes.append(node)
        return node

    def deallocate_node(self, node):
        with self.lock:
            self.nodes.remove(node)

    def allocate_items_for_node(self, node, num_items):
        current = node.head
        for _ in range(num_items):
            new_item = Item(randint(0, 100000))
            if not current:
                node.head = new_item
                current = new_item
            else:
                while current.next:
                    current = current.next
                current.next = new_item

    def handle_memory_allocation_failure(self, node):
        # Retry logic or reduce items as a fallback strategy
        try:
            self.allocate_items_for_node(node, randint(1, MAX_ITEMS_PER_NODE))
        except MemoryError:
            print("Memory allocation failed; attempting with fewer items.")
            self.allocate_items_for_node(node, 1)

    def add_nodes(self, node_count):
        for _ in range(node_count):
            node = self.allocate_node()
            num_items = randint(1, MAX_ITEMS_PER_NODE)
            try:
                self.allocate_items_for_node(node, num_items)
            except MemoryError:
                self.handle_memory_allocation_failure(node)

def worker(manager, nodes_to_create):
    manager.add_nodes(nodes_to_create)

def main():
    node_manager = DistributedMemoryManager()

    # Test scalability and concurrency
    threads = []
    for _ in range(10):  # Simulating multiple threads creating nodes concurrently
        t = threading.Thread(target=worker, args=(node_manager, 100))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

if __name__ == "__main__":
    main()
