function copyDataFromChunks(chunks, totalBytesToCopy) {
    if (!Array.isArray(chunks) || chunks.length === 0 || totalBytesToCopy <= 0) {
        throw new Error('Invalid input');
    }

    let copiedBytes = 0;
    const outputBuffer = Buffer.allocUnsafe(totalBytesToCopy);

    for (let i = 0; i < chunks.length && copiedBytes < totalBytesToCopy; i++) {
        const chunk = chunks[i];
        if (!Buffer.isBuffer(chunk)) continue;

        const bytesRemaining = totalBytesToCopy - copiedBytes;
        const copyLength = Math.min(chunk.length, bytesRemaining);

        chunk.copy(outputBuffer, copiedBytes, 0, copyLength);
        copiedBytes += copyLength;
    }

    return outputBuffer.slice(0, copiedBytes);
}

// Example usage:
// const chunks = [Buffer.from([1, 2, 3]), Buffer.from([4, 5, 6])];
// const result = copyDataFromChunks(chunks, 4);
