```javascript
function copyBufferData(bufferList, byteCount) {
    const totalLength = bufferList.reduce((acc, buf) => acc + buf.length, 0);

    // Handle case where requested bytes exceed available data
    if (byteCount > totalLength) {
        byteCount = totalLength;
    }

    const resultBuffer = Buffer.alloc(byteCount);

    let copiedBytes = 0;

    for (const buffer of bufferList) {
        const bytesToCopy = Math.min(buffer.length, byteCount - copiedBytes);

        // Copy data from the current buffer to the result buffer
        buffer.copy(resultBuffer, copiedBytes, 0, bytesToCopy);

        copiedBytes += bytesToCopy;

        if (copiedBytes >= byteCount) {
            break;
        }
    }

    return resultBuffer;
}
