#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double value;
    char identifier;
} data_point;

data_point* create_data_points(double* values, char* identifiers, size_t count) {
    if (values == NULL || identifiers == NULL) return NULL;

    // Allocate memory for data points
    data_point* points = (data_point*)malloc(count * sizeof(data_point));
    if (!points) {
        perror("Failed to allocate memory for data points");
        return NULL;
    }

    // Initialize data points with provided values and identifiers
    for (size_t i = 0; i < count; ++i) {
        points[i].value = values[i];
        points[i].identifier = identifiers[i];
    }

    return points;
}

void free_data_points(data_point* points) {
    if (points) {
        free(points);
    }
}

// Thread-safe function to process data
data_point* safe_create_data_points(double* values, char* identifiers, size_t count) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&lock);

    data_point* result = create_data_points(values, identifiers, count);

    pthread_mutex_unlock(&lock);
    return result;
}

// Example usage
int main() {
    double values[] = {1.0, 2.5, 3.7};
    char identifiers[] = {'a', 'b', 'c'};
    size_t count = sizeof(values) / sizeof(values[0]);

    data_point* points = safe_create_data_points(values, identifiers, count);

    if (points) {
        for (size_t i = 0; i < count; ++i) {
            printf("Value: %f, Identifier: %c\n", points[i].value, points[i].identifier);
        }

        free_data_points(points);
    }

    return 0;
}
