```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define MEMORY_THRESHOLD 1024 * 1024 // 1 MB
#define BLOCK_SIZE 64

typedef struct record {
    int value;
    char *str;
} Record;

typedef struct memory_pool {
    size_t block_size;
    size_t total_memory;
    void *free_list_head;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {BLOCK_SIZE, 0, NULL, PTHREAD_MUTEX_INITIALIZER};

void init_random() {
    srand(time(NULL));
}

int rand_in_range(int min, int max) {
    return min + rand() % (max - min + 1);
}

void *allocate_block(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    void *block = malloc(pool->block_size);
    if (!block) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pool->total_memory += pool->block_size;
    if (pool->total_memory > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded\n");
        free(block);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    ((Record *)block)->str = malloc(MAX_STRING_LENGTH);
    if (!((Record *)block)->str) {
        fprintf(stderr, "String allocation failed\n");
        free(block);
        pool->total_memory -= pool->block_size;
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pthread_mutex_unlock(&pool->lock);
    return block;
}

void deallocate_block(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);

    free(((Record *)block)->str);
    free(block);
    pool->total_memory -= pool->block_size;

    pthread_mutex_unlock(&pool->lock);
}

Record *create_record() {
    Record *record = (Record *)allocate_block(&pool);
    if (!record) return NULL;

    record->value = rand_in_range(1, 1000);
    snprintf(record->str, MAX_STRING_LENGTH, "String %d", record->value);

    return record;
}

void delete_record(MemoryPool *pool, Record *record) {
    deallocate_block(pool, (void *)record);
}

Record **traverse_records(size_t count, Record **records) {
    for (size_t i = 0; i < count; ++i) {
        records[i] = create_record();
    }
    return records;
}

void free_records(MemoryPool *pool, size_t count, Record **records) {
    for (size_t i = 0; i < count; ++i) {
        delete_record(pool, records[i]);
        records[i] = NULL;
    }
}

void test_module(size_t node_count, size_t item_count) {
    Record **records = malloc(node_count * sizeof(Record *));
    if (!records) return;

    traverse_records(item_count, records);

    for (size_t i = 0; i < item_count; ++i) {
        printf("Record %zu: Value=%d, String=%s\n", i, records[i]->value, records[i]->str);
    }

    free_records(&pool, item_count, records);
    free(records);
}

void verify_integrity(size_t count, Record **records) {
    for (size_t i = 0; i < count; ++i) {
        if (!records[i]) {
            fprintf(stderr, "Integrity check failed at index %zu\n", i);
        }
    }
}

// Database component
#include <mysql/mysql.h>

void query_database(const char *username, const char *password, int supervisor_id) {
    MYSQL *conn;
    MYSQL_STMT *stmt;
    MYSQL_BIND bind[1];
    unsigned long lengths[1] = {0};
    int param_type[1] = {1}; // Input parameter
    int result;

    conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", username, password, "database_name", 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        exit(EXIT_FAILURE);
    }

    const char *query = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";
    stmt = mysql_stmt_init(conn);
    if (!stmt) {
        fprintf(stderr, "mysql_stmt_init() failed\n");
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    if (mysql_stmt_prepare(stmt, query, strlen(query))) {
        fprintf(stderr, "mysql_stmt_prepare(), %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    memset(bind, 0, sizeof(bind));

    bind[0].buffer_type = MYSQL_TYPE_LONG;
    bind[0].buffer = (char *)&supervisor_id;
    bind[0].is_null = 0;

    if (mysql_stmt_bind_param(stmt, bind)) {
        fprintf(stderr, "mysql_stmt_bind_param() failed\n");
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    if (mysql_stmt_execute(stmt)) {
        fprintf(stderr, "mysql_stmt_execute(), %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    MYSQL_BIND result_bind[3];
    char name[100], city[100], address[255];
    memset(result_bind, 0, sizeof(result_bind));

    result_bind[0].buffer_type = MYSQL_TYPE_STRING;
    result_bind[0].buffer = (char *)&name;
    result_bind[0].buffer_length = sizeof(name);

    result_bind[1].buffer_type = MYSQL_TYPE_STRING;
    result_bind[1].buffer = (char *)&city;
    result_bind[1].buffer_length = sizeof(city);

    result_bind[2].buffer_type = MYSQL_TYPE_STRING;
    result_bind[2].buffer = (char *)&address;
    result_bind[2].buffer_length = sizeof(address);

    if (mysql_stmt_bind_result(stmt, result_bind)) {
        fprintf(stderr, "mysql_stmt_bind_result(), %s\n", mysql_stmt_error(stmt));
        mysql_close(conn);
        exit(EXIT_FAILURE);
    }

    while ((result = mysql_stmt_fetch(stmt)) == 0) {
        printf("Name: %s, City: %s, Address: %s\n", name, city, address);
    }

    if (result != MYSQL_DATA_TRUNCATED && result != MYSQL_NO_DATA) {
        fprintf(stderr, "mysql_stmt_fetch(), %s\n", mysql_stmt_error(stmt));
    }

    mysql_stmt_close(stmt);
    mysql_close(conn);
}

int main() {
    init_random();

    // Test module
    size_t node_count = 10;
    size_t item_count = 5;
    test_module(node_count, item_count);

    // Database query
    const char *username = "your_username";
    const char *password = "your_password";
    int supervisor_id = 1; // Example supervisor ID
    query_database(username, password, supervisor_id);

    return 0;
}
```

