#include "imagelib.h" // Assume this is the external image processing library

typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
    uint8_t transparency; // alpha channel
} pixel_data;

typedef struct {
    int exposure_time;
    time_t capture_time;
    char additional_info[256];
} metadata;

typedef struct {
    pixel_data **grid;
    metadata *metadata_grid;
    size_t width;
    size_t height;
} image_grid;

#define CACHE_SIZE 1024

pixel_data *cache[CACHE_SIZE];
size_t cache_index = 0;

// Function to allocate memory aligned to a specific boundary
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

// Simple cache mechanism for pixel_data
pixel_data* get_cached_pixel() {
    if (cache_index < CACHE_SIZE && cache[cache_index] != NULL) {
        pixel_data* result = cache[cache_index];
        cache[cache_index] = NULL;
        cache_index++;
        return result;
    }
    return aligned_alloc(64, sizeof(pixel_data));
}

void release_cached_pixel(pixel_data *pixel) {
    if (cache_index < CACHE_SIZE) {
        cache[cache_index++] = pixel;
    } else {
        free_aligned(pixel);
    }
}

// Function to handle dynamic resizing of the image grid
image_grid* resize_image_grid(image_grid *grid, size_t new_width, size_t new_height) {
    // Allocate new grids with aligned memory
    pixel_data **new_pixel_grid = (pixel_data **)aligned_alloc(64, new_width * sizeof(pixel_data *));
    metadata *new_metadata_grid = (metadata *)aligned_alloc(64, new_width * new_height * sizeof(metadata));

    if (!new_pixel_grid || !new_metadata_grid) {
        fprintf(stderr, "Memory allocation failed during resizing.\n");
        return NULL;
    }

    // Initialize new grids
    for (size_t i = 0; i < new_width; ++i) {
        new_pixel_grid[i] = (pixel_data *)aligned_alloc(64, new_height * sizeof(pixel_data));
        if (!new_pixel_grid[i]) {
            fprintf(stderr, "Memory allocation failed during resizing.\n");
            // Free already allocated memory
            for (size_t j = 0; j < i; ++j) free_aligned(new_pixel_grid[j]);
            free_aligned(new_pixel_grid);
            free_aligned(new_metadata_grid);
            return NULL;
        }
    }

    // Copy old data to new grids with proportional scaling if necessary
    size_t min_width = grid->width < new_width ? grid->width : new_width;
    size_t min_height = grid->height < new_height ? grid->height : new_height;

    for (size_t y = 0; y < min_height; ++y) {
        for (size_t x = 0; x < min_width; ++x) {
            new_pixel_grid[x][y] = grid->grid[x][y]; // Simple copy, adjust scaling as needed
            new_metadata_grid[y * new_width + x] = grid->metadata_grid[y * grid->width + x];
        }
    }

    // Free old grids
    for (size_t i = 0; i < grid->width; ++i) {
        free_aligned(grid->grid[i]);
    }
    free_aligned(grid->grid);
    free_aligned(grid->metadata_grid);

    // Update grid structure
    grid->grid = new_pixel_grid;
    grid->metadata_grid = new_metadata_grid;
    grid->width = new_width;
    grid->height = new_height;

    return grid;
}

// Parallel processing function
void process_pixel_data(image_grid *grid, size_t start_row, size_t end_row) {
    for (size_t y = start_row; y < end_row; ++y) {
        for (size_t x = 0; x < grid->width; ++x) {
            pixel_data* pixel = &grid->grid[x][y];
            // Apply some image processing using `imagelib`
            imagelib_process_pixel(pixel);

            // Handle transparency
            if (pixel->transparency == 0) {
                pixel->red = pixel->green = pixel->blue = 0;
            }
        }
    }
}

void* thread_function(void *arg) {
    image_grid *grid = (image_grid *)arg;
    size_t num_threads = pthread_self();
    size_t rows_per_thread = grid->height / num_threads;
    size_t start_row = rows_per_thread * num_threads;
    size_t end_row = (num_threads == pthread_self()) ? grid->height : start_row + rows_per_thread;

    process_pixel_data(grid, start_row, end_row);
    return NULL;
}

void process_image_grid(image_grid *grid) {
    int num_threads = 4; // Or determine dynamically based on hardware
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, grid)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Function to handle errors and logging
void log_message(const char *message, int level) {
    const char *levels[] = {"INFO", "WARNING", "ERROR"};
    if (level >= 0 && level < 3) {
        printf("[%s] %s\n", levels[level], message);
    }
}

// Main function to demonstrate usage
int main() {
    size_t width = 1920;
    size_t height = 1080;

    // Allocate image grid with aligned memory
    image_grid *grid = (image_grid *)aligned_alloc(64, sizeof(image_grid));
    if (!grid) {
        fprintf(stderr, "Failed to allocate memory for image grid.\n");
