    grid->metadata_grid = (metadata *)aligned_alloc(64, width * height * sizeof(metadata));

    if (!grid->grid || !grid->metadata_grid) {
        fprintf(stderr, "Failed to allocate memory for pixel or metadata grid.\n");
        free_aligned(grid);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < width; ++i) {
        grid->grid[i] = (pixel_data *)aligned_alloc(64, height * sizeof(pixel_data));
        if (!grid->grid[i]) {
            fprintf(stderr, "Failed to allocate memory for pixel row.\n");
            // Free previously allocated rows
            for (size_t j = 0; j < i; ++j) free_aligned(grid->grid[j]);
            free_aligned(grid->grid);
            free_aligned(grid->metadata_grid);
            free_aligned(grid);
            return EXIT_FAILURE;
        }
    }

    log_message("Image grid initialized successfully", 0);

    // Process the image grid
    process_image_grid(grid);

    // Resize example (demonstrating dynamic resizing)
