typedef struct {
    int value;
} record;

record* allocateAndInitializeRecords(int num_records, int key_range_min, int key_range_max,
                                     long offset_range_min, long offset_range_max) {
    if (num_records <= 0) return NULL;

    // Define the alignment boundary
    const size_t ALIGNMENT = 16;

    // Calculate sizes needed for allocation
    size_t record_size = sizeof(record);
    size_t aligned_record_size = ((record_size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    size_t total_record_memory = num_records * aligned_record_size;

    // Allocate memory for records with alignment
    void* raw_ptr = NULL;
#if defined(_WIN32)
    if (_aligned_malloc(total_record_memory, ALIGNMENT)) {
#else
    if (posix_memalign(&raw_ptr, ALIGNMENT, total_record_memory) == 0) {
#endif
        record* records = (record*)raw_ptr;

        // Allocate memory for keys and offsets
        int* keys = malloc(num_records * sizeof(int));
        long* offsets = malloc(num_records * sizeof(long));

        if (!keys || !offsets) {
            free(keys);
            free(offsets);

#if defined(_WIN32)
            _aligned_free(raw_ptr);
#else
            free(raw_ptr);
#endif

            return NULL;
        }

        // Seed random number generator
        srand(time(NULL));

        for (int i = 0; i < num_records; ++i) {
            records[i].value = key_range_min + rand() % (key_range_max - key_range_min + 1);
            keys[i] = records[i].value;
            offsets[i] = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);

            // Verify integrity: Check if values are within the specified range
            if ((records[i].value < key_range_min || records[i].value > key_range_max) ||
                (offsets[i] < offset_range_min || offsets[i] > offset_range_max)) {
#if defined(_WIN32)
                _aligned_free(raw_ptr);
#else
                free(raw_ptr);
#endif

                free(keys);
                free(offsets);

                return NULL;
            }
        }

        // Cleanup and return the records array
        free(keys);
        free(offsets);

    } else {
        return NULL;  // Memory allocation failed
    }

#if defined(_WIN32)
    _aligned_free(raw_ptr); // Ensure cleanup if not returning raw_ptr.
#else
    free(raw_ptr);
#endif

    return (record*)raw_ptr;
}
