```javascript
function copyBufferData(chunks, numBytesToCopy) {
    const outputBuffer = Buffer.alloc(numBytesToCopy);

    let totalCopiedBytes = 0;

    for (let i = 0; i < chunks.length && totalCopiedBytes < numBytesToCopy; ++i) {
        const chunk = chunks[i];
        const bytesAvailableInChunk = chunk.length - totalCopiedBytes;
        const bytesToCopyFromThisChunk = Math.min(numBytesToCopy - totalCopiedBytes, bytesAvailableInChunk);

        chunk.copy(outputBuffer, totalCopiedBytes, 0, bytesToCopyFromThisChunk);
        totalCopiedBytes += bytesToCopyFromThisChunk;

        if (totalCopiedBytes === numBytesToCopy) {
            break;
        }
    }

    return outputBuffer.slice(0, totalCopiedBytes); // Ensure only the copied data is returned
}
