    const char *output_dir;
    int target_bitrate;
} Task;

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <list of audio files> <output directory> <target bitrate>\n", argv[0]);
        return EXIT_FAILURE;
    }

#ifdef _WIN32
    sem_t semaphore = CreateSemaphore(NULL, MAX_THREADS, MAX_THREADS, NULL);
#else
    sem_init(&semaphore, 0, MAX_THREADS);
#endif

    // List of audio file paths and other parameters
    const char *output_dir = argv[2];
    int target_bitrate = atoi(argv[3]);

    // Process each file in parallel
    pthread_t threads[MAX_THREADS];
    Task tasks[MAX_THREADS];
    size_t num_files = argc - 3;
    if (num_files > MAX_THREADS) num_files = MAX_THREADS;

    for (size_t i = 0; i < num_files; ++i) {
        tasks[i] = (Task){argv[i + 3], output_dir, target_bitrate};
        sem_wait(&semaphore);
        pthread_create(&threads[i], NULL, thread_task, &tasks[i]);
    }

    for (size_t i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
        sem_post(&semaphore);
    }

#ifdef _WIN32
    CloseHandle(semaphore);
#else
    // No need to destroy semaphore on non-Windows platforms with custom implementation
#endif

    return EXIT_SUCCESS;
}

void *thread_task(void *arg) {
    Task *task = (Task *)arg;

    sem_post(&semaphore);  // Release the semaphore after task start

