#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define ALIGNMENT 16
#define CACHE_SIZE 10

typedef struct {
    int value;
    struct tm timestamp;
} record;

typedef struct CacheEntry {
    void* ptr;
    size_t size;
    pthread_mutex_t lock;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void log_allocation(size_t requested_size, size_t actual_size) {
    // Simulate logging to an external service
    printf("Allocated %zu bytes (requested: %zu)\n", actual_size, requested_size);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        log_allocation(size, 0); // Log failure
        return NULL;
    }
    log_allocation(size, size); // Log success
    return ptr;
}

void free_aligned(void* ptr, size_t size) {
    free(ptr);
    printf("Freed %zu bytes\n", size);
}

void cache_lookup(size_t size, void** result) {
    pthread_mutex_lock(&global_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].ptr && cache[i].size == size) {
            *result = cache[i].ptr;
            pthread_mutex_lock(&cache[i].lock);
            break;
        }
    }
    pthread_mutex_unlock(&global_lock);
}

void cache_store(size_t size, void* ptr) {
    pthread_mutex_lock(&global_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (!cache[i].ptr || !pthread_mutex_trylock(&cache[i].lock)) {
            cache[i].ptr = ptr;
            cache[i].size = size;
            pthread_mutex_unlock(&cache[i].lock);
            break;
        }
    }
    pthread_mutex_unlock(&global_lock);
}

int initialize_data(long* offset_array, int* key_array, record** records_array, size_t num_elements) {
    if (!offset_array || !key_array || !records_array) return -1;

    // Allocate and align memory for arrays
    *offset_array = (long*)aligned_alloc(ALIGNMENT, num_elements * sizeof(long));
    if (*offset_array == NULL) return -1;

    *key_array = (int*)aligned_alloc(ALIGNMENT, num_elements * sizeof(int));
    if (*key_array == NULL) {
        free_aligned(*offset_array, num_elements * sizeof(long));
        return -1;
    }

    // Allocate and align memory for records
    size_t record_size = sizeof(record);
    void* cached_ptr = NULL;
    cache_lookup(record_size, &cached_ptr);

    if (!cached_ptr) {
        *records_array = (record*)aligned_alloc(ALIGNMENT, num_elements * record_size);
        if (*records_array == NULL) {
            free_aligned(*offset_array, num_elements * sizeof(long));
            free_aligned(*key_array, num_elements * sizeof(int));
            return -1;
        }
        cache_store(record_size, *records_array);
    } else {
        *records_array = (record*)cached_ptr;
    }

    // Initialize data
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        (*offset_array)[i] = rand() % 100000;
        (*key_array)[i] = rand() % 1000;

        (*records_array)[i].value = rand() % 500;
        time_t rawtime = time(NULL);
        localtime_r(&rawtime, &((*records_array)[i].timestamp));
    }

    return 0;
}

void cleanup_data(long* offset_array, int* key_array, record* records_array) {
    if (offset_array) free_aligned(offset_array, sizeof(long) * num_elements);
    if (key_array) free_aligned(key_array, sizeof(int) * num_elements);
    if (records_array) free_aligned(records_array, sizeof(record) * num_elements);

    for (int i = 0; i < CACHE_SIZE; ++i) {
        pthread_mutex_lock(&cache[i].lock);
        if (cache[i].ptr) {
            free_aligned(cache[i].ptr, cache[i].size);
            cache[i].ptr = NULL;
        }
        pthread_mutex_unlock(&cache[i].lock);
    }
}
