import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.io.RandomAccessFile;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;

public class FileTransferManager {

    public void transferFile(String filePath) {
        try (RandomAccessFile file = new RandomAccessFile(filePath, "r");
             SocketChannel socketChannel = SocketChannel.open(new InetSocketAddress("localhost", 8080));
             FileChannel fileChannel = file.getChannel()) {

            ByteBuffer buffer = ByteBuffer.allocate(1024);

            while (fileChannel.read(buffer) > 0) {
                buffer.flip();
                socketChannel.write(buffer);
                buffer.clear();

                // Implement retry logic if necessary
            }
        } catch (Exception e) {
            System.err.println("File transfer failed: " + e.getMessage());
            notifyMonitoringService(false, filePath);
        }

        notifyMonitoringService(true, filePath);
    }

    private void notifyMonitoringService(boolean success, String filePath) {
        // Notify monitoring service with the status
        System.out.println((success ? "Successfully transferred" : "Failed to transfer") + ": " + filePath);
    }
}
```

