    double decimal;
    char character;
} data;

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || defined(__APPLE__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void aligned_free(void *ptr) {
#if defined(_WIN32)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

data* read_data_from_file(const char *filename, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    data *array = NULL;
    *count = 0;

    while (1) {
        data temp;
        int result = fscanf(file, "%d %lf %c", &temp.number, &temp.decimal, &temp.character);

        if (result != 3) {
            break;
        }

        array = realloc(array, sizeof(data) * (*count + 1));
        if (!array) {
            perror("Failed to allocate memory for data");
            fclose(file);
            return NULL;
        }
        array[*count] = temp;
        (*count)++;
    }

    fclose(file);
    return array;
}

node* initialize_node_array(const char *filename, int node_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file for nodes");
        return NULL;
    }

    node *nodes = aligned_alloc(ALIGNMENT, sizeof(node) * node_count);
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < node_count; ++i) {
        fscanf(file, "%lf", &nodes[i].value);

        // Assuming items are initialized with a fixed size for simplicity
        int item_count = 5; 
        nodes[i].items = aligned_alloc(ALIGNMENT, sizeof(item) * item_count);
        if (!nodes[i].items) {
            perror("Failed to allocate memory for items");
            fclose(file);
            return NULL;
        }

        for (int j = 0; j < item_count; ++j) {
            fscanf(file, "%d %s", &nodes[i].items[j].key, nodes[i].items[j].string);
            nodes[i].items[j].string = strdup(nodes[i].items[j].string);
            if (!nodes[i].items[j].string) {
                perror("Failed to duplicate string");
                fclose(file);
                return NULL;
            }
        }

        nodes[i].items_count = item_count;
        nodes[i].next = (i < node_count - 1) ? &nodes[i + 1] : NULL;
    }

    fclose(file);
    return nodes;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <data_file> <node_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int data_count = 0;
    data *data_array = read_data_from_file(argv[1], &data_count);
    if (!data_array) {
        fprintf(stderr, "Error reading data from file\n");
        return EXIT_FAILURE;
    }

    int node_count = 3; // Example fixed size for demonstration
    node *nodes = initialize_node_array(argv[2], node_count);
    if (!nodes) {
        fprintf(stderr, "Error initializing nodes\n");
        free(data_array);
        return EXIT_FAILURE;
    }

    // Use data_array and nodes as needed...

    // Cleanup
    for (int i = 0; i < node_count; ++i) {
        for (int j = 0; j < nodes[i].items_count; ++j) {
            free(nodes[i].items[j].string);
        }
        aligned_free(nodes[i].items);
    }
    aligned_free(nodes);
    free(data_array);

    return EXIT_SUCCESS;
}
