record* allocateAndInitializeRecords(int num_records, int key_range_min, int key_range_max,
                                    long offset_range_min, long offset_range_max,
                                    size_t alignment) {
    if (num_records <= 0 || alignment == 0) return NULL;

    // Allocate and align memory for offsets, keys, and records
    long* offsets = aligned_alloc(alignment, num_records * sizeof(long));
    int* keys = aligned_alloc(alignment, num_records * sizeof(int));
    record* records = aligned_alloc(alignment, num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free_aligned(offsets);
        free_aligned(keys);
        free_aligned(records);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Populate offsets and keys with random values within specified ranges
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = offset_range_min + rand() % (offset_range_max - offset_range_min + 1);
        keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);

        // Initialize records with random integers
        records[i].value = key_range_min + rand() % (key_range_max - key_range_min + 1);
    }

    // Integrity check: Ensure all offsets and keys are within the specified range
    for (int i = 0; i < num_records; ++i) {
        if (offsets[i] < offset_range_min || offsets[i] > offset_range_max ||
            keys[i] < key_range_min || keys[i] > key_range_max) {
            free_aligned(offsets);
            free_aligned(keys);
            free_aligned(records);
            fprintf(stderr, "Data integrity check failed\n");
            return NULL;
        }
    }

    // Free the offsets and keys as they are no longer needed
    free_aligned(offsets);
    free_aligned(keys);

    return records;  // Return only the record array
}
