function copyBufferData(sourceBuffer, targetBufferSize) {
    if (!sourceBuffer || !Number.isInteger(targetBufferSize)) {
        throw new Error("Invalid input: sourceBuffer must be a Buffer and targetBufferSize an integer.");
    }

    const targetBuffer = Buffer.allocUnsafe(targetBufferSize);

    // Determine the number of bytes to copy (either full source length or target capacity)
    const copyLength = Math.min(sourceBuffer.length, targetBufferSize);

    // Copy data from sourceBuffer to targetBuffer
    sourceBuffer.copy(targetBuffer, 0, 0, copyLength);

    return targetBuffer;
}
