['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>

// Constants for memory alignment and size limits
#define ALIGNMENT 32
#define MAX_STRING_LENGTH 16
#define INITIAL_ARRAY_SIZE 10
#define MEMORY_LIMIT (1024 * 1024 * 256) // Example limit: 256 MB

typedef struct Item {
    int key;
    char string[MAX_STRING_LENGTH + 1];
} Item;

typedef struct ListNode {
    Item* data;
    struct ListNode* next;
} ListNode;

typedef struct Node {
    double value;
    ListNode* head;
} Node;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Error handling
    }
#else
    if ((ptr = memalign(alignment, size))) {
        return ptr;
    }
#endif
    return NULL;
}

// Function to generate a random alphanumeric string
void generate_random_string(char* str, int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < length; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
}

// Function to initialize a node
void init_node(Node* node, double value) {
    pthread_mutex_lock(&lock);
    node->value = value;
    node->head = NULL;
    pthread_mutex_unlock(&lock);
}

// Function to add an item to the linked list in a node
void add_item_to_node(Node* node, int key, const char* string) {
    pthread_mutex_lock(&lock);
    ListNode* new_item = (ListNode*)aligned_alloc(ALIGNMENT, sizeof(ListNode));
    if (!new_item) {
        fprintf(stderr, "Memory allocation failed for item\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_item->data = (Item*)aligned_alloc(ALIGNMENT, sizeof(Item));
    if (!new_item->data) {
        free(new_item);
        fprintf(stderr, "Memory allocation failed for item data\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_item->data->key = key;
    strncpy(new_item->data->string, string, MAX_STRING_LENGTH);

    new_item->next = node->head;
    node->head = new_item;

    pthread_mutex_unlock(&lock);
}

// Function to manage nodes
Node** manage_nodes(int range_min, int range_max, size_t* num_nodes) {
    srand(time(NULL));
    Node** nodes = (Node**)aligned_alloc(ALIGNMENT, INITIAL_ARRAY_SIZE * sizeof(Node*));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for node array\n");
        return NULL;
    }

    *num_nodes = 0;
    size_t total_memory_used = 0;

    while (*num_nodes < INITIAL_ARRAY_SIZE && total_memory_used < MEMORY_LIMIT) {
        Node* new_node = (Node*)aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!new_node || total_memory_used + sizeof(Node) > MEMORY_LIMIT) {
            fprintf(stderr, "Memory allocation failed for node or limit exceeded\n");
            break;
        }

        int random_int = rand() % (range_max - range_min + 1) + range_min;
        double value = sqrt((double)random_int);

        init_node(new_node, value);
        nodes[*num_nodes] = new_node;
        (*num_nodes)++;
        total_memory_used += sizeof(Node);

        for (int i = 0; i < 5 && total_memory_used < MEMORY_LIMIT; ++i) { // Add 5 items per node
            char string[MAX_STRING_LENGTH + 1];
            generate_random_string(string, MAX_STRING_LENGTH);
            add_item_to_node(new_node, rand(), string);

            if (total_memory_used > MEMORY_LIMIT) {
                fprintf(stderr, "Memory usage exceeded limit\n");
                break;
            }
        }
    }

    return nodes;
}

// Function to verify integrity of the allocated data
int verify_nodes(Node** nodes, size_t num_nodes) {
    for (size_t i = 0; i < num_nodes; ++i) {
        if (!nodes[i]) continue;

        Node* node = nodes[i];
        if (node->value < 0 || node->head == NULL) return 0;

        ListNode* current = node->head;
        while (current) {
            if (current->data->key < 0 || strlen(current->data->string) > MAX_STRING_LENGTH) return 0;
            current = current->next;
        }
    }
    return 1;
}

// Main function for testing
int main() {
    size_t num_nodes = 0;
    Node** nodes = manage_nodes(1, 100, &num_nodes);

    if (nodes && verify_nodes(nodes, num_nodes)) {
        printf("Nodes initialized successfully\n");
    } else {
        fprintf(stderr, "Node initialization failed\n");
    }

    // Free allocated memory
    for (size_t i = 0; i < num_nodes; ++i) {
        ListNode* current = nodes[i]->head;
        while (current) {
            ListNode* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }
        free(nodes[i]);
    }
    free(nodes);

    return 0;
}
```

