// c_memory_manager.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE (0.8 * 1024 * 1024) // 80% of 1 MB
#define STRING_INIT_VALUE "INIT"
#define UINT_RANGE_MAX 100

typedef struct {
    size_t size;
    union {
        double d_val;
        char *c_ptr;
    } data;
} item;

typedef struct {
    int value;
    char id[64];
    struct item *item_ptr;
} record;

// Global lock for thread safety
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_record(record *rec, int index) {
    snprintf(rec->id, sizeof(rec->id), "REC-%d-%ld", index, time(NULL));
    rec->value = rand() % 100;
    rec->item_ptr = malloc(sizeof(item));
    if (rec->item_ptr != NULL) {
        rec->item_ptr->size = rand() % 100;
        // Randomly choose to store a double or char pointer
        if (rand() % 2 == 0) {
            rec->item_ptr->data.d_val = (double)rand();
        } else {
            rec->item_ptr->data.c_ptr = strdup(STRING_INIT_VALUE);
        }
    }
}

void free_record(record *rec) {
    if (rec && rec->item_ptr) {
        if (rec->item_ptr->data.c_ptr) {
            free(rec->item_ptr->data.c_ptr);
        }
        free(rec->item_ptr);
    }
}

int calculate_memory_usage(size_t num_records, size_t long_size, size_t double_size, size_t struct_size, size_t int_size) {
    size_t total = num_records * (sizeof(long *) + sizeof(double) + sizeof(struct {
        char str[128];
        unsigned int ui;
    }) + int_size + struct_size);
    return total;
}

void manage_memory(int num_records, long **long_array, double *double_array,
                   struct { char str[128]; unsigned int ui; } *struct_array, 
                   int *int_keys, record *records) {
    pthread_mutex_lock(&memory_lock);

    size_t long_size = sizeof(long *);
    size_t double_size = sizeof(double);
    size_t struct_size = sizeof(struct { char str[128]; unsigned int ui; });
    size_t int_size = sizeof(int);
    size_t record_size = sizeof(record);

    if (calculate_memory_usage(num_records, long_size, double_size, struct_size, int_size) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeds limit\n");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    // Allocate memory
    *long_array = malloc(num_records * long_size);
    *double_array = malloc(num_records * double_size);
    *struct_array = malloc(num_records * struct_size);
    *int_keys = malloc(num_records * int_size);
    records = malloc(num_records * record_size);

    if (!*long_array || !*double_array || !*struct_array || !*int_keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*long_array); free(*double_array); free(*struct_array); free(*int_keys); free(records);
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; ++i) {
        (*long_array)[i] = malloc(sizeof(long));
        if (!(*long_array)[i]) {
            fprintf(stderr, "Failed to allocate long\n");
            break;
        }

        (*double_array)[i] = (double)i;

        snprintf((*struct_array)[i].str, sizeof((*struct_array)[i].str), STRING_INIT_VALUE);
        (*struct_array)[i].ui = rand() % UINT_RANGE_MAX;

        (*int_keys)[i] = i;

        initialize_record(&records[i], i);
    }

    pthread_mutex_unlock(&memory_lock);
}

void free_resources(long **long_array, double *double_array,
                    struct { char str[128]; unsigned int ui; } *struct_array, 
                    int *int_keys, record *records, int num_records) {
    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < num_records; ++i) {
        free((*long_array)[i]);
        free_record(&records[i]);
    }

    free(*long_array);
    free(double_array);
    free(struct_array);
    free(int_keys);
    free(records);

    pthread_mutex_unlock(&memory_lock);
}

// c_memory_manager.h
#ifndef C_MEMORY_MANAGER_H
#define C_MEMORY_MANAGER_H

void manage_memory(int num_records, long **long_array, double *double_array,
                   struct { char str[128]; unsigned int ui; } *struct_array, 
                   int *int_keys, record *records);

void free_resources(long **long_array, double *double_array,
                    struct { char str[128]; unsigned int ui; } *struct_array, 
                    int *int_keys, record *records, int num_records);

#endif
