```java
// JavaRemoteConnection.java

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousSocketChannel;
import java.nio.channels.CompletionHandler;
import java.util.concurrent.ExecutionException;

public class JavaRemoteConnection {
    private AsynchronousSocketChannel channel;

    public void connect(String host, int port) throws IOException {
        try {
            channel = AsynchronousSocketChannel.open();
            InetSocketAddress address = new InetSocketAddress(host, port);
            boolean connected = channel.connect(address).get();

            if (!connected) {
                throw new IOException("Failed to connect");
            }

            // Handle connection state changes and messaging
            System.out.println("Connected to " + host + ":" + port);

        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Connection attempt failed: " + e.getMessage());
            reconnect(host, port);
        }
    }

    public void disconnect() throws IOException {
        if (channel != null) {
            channel.close();
            System.out.println("Disconnected");
        }
    }

    private void reconnect(String host, int port) {
        try {
            Thread.sleep(5000); // Wait before retrying
            connect(host, port);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        JavaRemoteConnection connection = new JavaRemoteConnection();

        while (true) {
            try {
                connection.connect("localhost", 8080);

                // Simulate service work
                Thread.sleep((long) (Math.random() * 5000));

                connection.disconnect();
                Thread.sleep((long) (Math.random() * 2000)); // Random delay

            } catch (IOException | InterruptedException e) {
                System.err.println("Service error: " + e.getMessage());
            }
        }
    }
}
