    float frequency;
} Signal;

typedef struct {
    int value;
} Record;

#define ALIGNMENT 32

// Custom memory allocation function
void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void* memory;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool*) aligned_alloc(sizeof(MemoryPool), ALIGNMENT);
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);

    pool->memory = aligned_alloc(block_size * num_blocks, ALIGNMENT);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    memset(pool->memory, 0, block_size * num_blocks);
    return pool;
}

void* memory_pool_allocate(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    static void** free_list = NULL;
    static size_t next_free_index = 0;

    if (!free_list) {
        free_list = (void**) aligned_alloc(pool->num_blocks * sizeof(void*), ALIGNMENT);
        for (size_t i = 0; i < pool->num_blocks; ++i) {
            void* block = (char*)pool->memory + i * pool->block_size;
            free_list[i] = block;
        }
    }

    if (next_free_index < pool->num_blocks) {
        void* allocated_block = free_list[next_free_index++];
        pthread_mutex_unlock(&pool->lock);
        return allocated_block;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // No available blocks
    }
}

void memory_pool_deallocate(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);

    size_t index = ((char*)block - (char*)pool->memory) / pool->block_size;
    if (index < pool->num_blocks) {
        free_list[index] = block;
        next_free_index--;
    }

    pthread_mutex_unlock(&pool->lock);
}

