// Define data structures
typedef struct {
    float measurement;
    double timestamp;
} data_point;

typedef struct {
    float intensity;
} event;

#define ALIGNMENT 64

// Memory pool structure to manage memory allocation and reuse
typedef struct {
    void *start;
    size_t total_size;
    size_t offset;
    pthread_mutex_t lock;
} mem_pool;

// Global variables for allocation statistics
int successful_allocations = 0;
int failed_allocations = 0;
pthread_mutex_t stats_lock;

void log_event(const char *message) {
    // Example logging function
    printf("%s\n", message);
}

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

mem_pool* create_memory_pool(size_t size) {
    mem_pool *pool = (mem_pool*)aligned_malloc(sizeof(mem_pool), ALIGNMENT);
    pool->start = aligned_malloc(size, ALIGNMENT);
    pool->total_size = size;
    pool->offset = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(mem_pool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->offset + size > pool->total_size) {
        pthread_mutex_unlock(&pool->lock);
        failed_allocations++;
        log_event("Allocation failed due to insufficient resources");
        return NULL;
    }
    void *ptr = (char*)pool->start + pool->offset;
    pool->offset += size;
    successful_allocations++;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void* safe_realloc(void *ptr, size_t old_size, size_t new_size) {
    if (!ptr) {
        return malloc(new_size);
    }
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr && new_size > 0) {
        failed_allocations++;
        log_event("Reallocation failed due to insufficient resources");
        return NULL;
    }
    return new_ptr;
}

