    size_t category_size = num_samples * sizeof(char);
    size_t data_point_size = num_samples * sizeof(data_point);
    size_t index_size = num_samples * sizeof(unsigned long);
    size_t status_code_size = num_samples * sizeof(short);
    size_t event_size = num_samples * sizeof(event);

    mem_pool *pool = create_memory_pool(sample_size + category_size + data_point_size +
                                        index_size + status_code_size + event_size);

    double *samples = (double*)allocate_from_pool(pool, sample_size);
    char *categories = (char*)allocate_from_pool(pool, category_size);
    data_point *data_points = (data_point*)allocate_from_pool(pool, data_point_size);
    unsigned long *indices = (unsigned long*)allocate_from_pool(pool, index_size);
    short *status_codes = (short*)allocate_from_pool(pool, status_code_size);
    event *events = (event*)allocate_from_pool(pool, event_size);

    if (!samples || !categories || !data_points || !indices || !status_codes || !events) {
        free(pool->start);
        free(pool);
        return NULL;
    }

    initialize_data(samples, categories, data_points, indices, status_codes, events,
                    num_samples, seed);

    // Log allocation statistics
    pthread_mutex_lock(&stats_lock);
    log_event("Total successful allocations: ");
    printf("%d\n", successful_allocations);
    log_event("Total failed allocations: ");
    printf("%d\n", failed_allocations);
    pthread_mutex_unlock(&stats_lock);

    return pool;
}

void free_memory_pool(mem_pool *pool) {
    if (pool) {
        free(pool->start);
        free(pool);
    }
}

int main() {
    size_t num_samples = 1000;
    int seed = 42;

    mem_pool *data_pool = allocate_and_initialize_data(num_samples, seed);

    if (!data_pool) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Use the data...

    free_memory_pool(data_pool);
    return EXIT_SUCCESS;
}
