// Structure definitions
typedef struct {
    double amplitude;
    float frequency;
} Signal;

typedef struct {
    int value;
} Record;

#define ALIGNMENT 32

// Global configuration for logging and allocation management
static int successful_allocations = 0;
static int failed_allocations = 0;
pthread_mutex_t alloc_lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool structure to manage free blocks
typedef struct Block {
    size_t size;
    struct Block* next;
} Block;

Block* freelist = NULL;

void* aligned_malloc(size_t size, size_t alignment) {
    void* ptr;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

void free_aligned(void* ptr) {
    free(ptr);
}

// Thread-safe logging function
void log_allocation(const char* message) {
    pthread_mutex_lock(&alloc_lock);
    printf("[%ld] %s\n", time(NULL), message); // Timestamp in seconds since epoch
    pthread_mutex_unlock(&alloc_lock);
}

// Memory allocation and initialization function
Signal* allocate_signal_array(size_t num_signals, double (*amplitude_func)(int), float (*frequency_func)(int)) {
    Signal* signals = (Signal*)aligned_malloc(num_signals * sizeof(Signal), ALIGNMENT);
    if (!signals) {
        failed_allocations++;
        log_allocation("Failed to allocate signal array");
        return NULL;
    }

    for (size_t i = 0; i < num_signals; ++i) {
        signals[i].amplitude = amplitude_func(i);
        signals[i].frequency = frequency_func(i);
    }
    successful_allocations++;

    // Log allocation success
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated signal array of size %zu", num_signals);
    log_allocation(log_message);

    return signals;
}

char* allocate_label_array(size_t num_labels) {
    char* labels = (char*)aligned_malloc(num_labels * sizeof(char), ALIGNMENT);
    if (!labels) {
        failed_allocations++;
        log_allocation("Failed to allocate label array");
        return NULL;
    }

    for (size_t i = 0; i < num_labels; ++i) {
        labels[i] = 'A' + (i % 26); // Example labeling
    }

    successful_allocations++;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated label array of size %zu", num_labels);
    log_allocation(log_message);

    return labels;
}

long* allocate_long_array(size_t num_elements) {
    long* offset_values = (long*)aligned_malloc(num_elements * sizeof(long), ALIGNMENT);
    if (!offset_values) {
        failed_allocations++;
        log_allocation("Failed to allocate long array");
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        offset_values[i] = i * 10L; // Example initialization
    }

    successful_allocations++;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated long array of size %zu", num_elements);
    log_allocation(log_message);

    return offset_values;
}

int* allocate_int_array(size_t num_keys) {
    int* keys = (int*)aligned_malloc(num_keys * sizeof(int), ALIGNMENT);
    if (!keys) {
        failed_allocations++;
        log_allocation("Failed to allocate integer array");
        return NULL;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i; // Example initialization
    }

    successful_allocations++;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated integer array of size %zu", num_keys);
    log_allocation(log_message);

    return keys;
}

Record* allocate_record_array(size_t num_records) {
    Record* records = (Record*)aligned_malloc(num_records * sizeof(Record), ALIGNMENT);
    if (!records) {
        failed_allocations++;
        log_allocation("Failed to allocate record array");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = i; // Example initialization
    }

    successful_allocations++;

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Allocated record array of size %zu", num_records);
    log_allocation(log_message);

    return records;
}

// Thread-safe memory pool management functions
void init_memory_pool(size_t initial_size) {
    freelist = (Block*)aligned_malloc(initial_size * sizeof(Block), ALIGNMENT);
    if (!freelist) {
        log_allocation("Failed to initialize memory pool");
        return;
    }

    for (size_t i = 0; i < initial_size - 1; ++i) {
        freelist[i].next = &freelist[i + 1];
        freelist[i].size = sizeof(Block);
    }

    freelist[initial_size - 1].next = NULL;
    freelist[initial_size - 1].size = sizeof(Block);
}

void* pool_allocate(size_t size) {
    pthread_mutex_lock(&alloc_lock);

    Block** current = &freelist;
    while (*current) {
        if ((*current)->size >= size) {
            void* block = *current;
            *current = (*current)->next;
            successful_allocations++;
            return block;
        }
        current = &((*current)->next);
    }

    pthread_mutex_unlock(&alloc_lock);

    failed_allocations++;
    log_allocation("Failed to allocate from memory pool");
    return NULL;
}

void pool_free(void* ptr, size_t size) {
    if (!ptr) return;

    Block* block = (Block*)ptr;
    block->size = size;

    pthread_mutex_lock(&alloc_lock);

    block->next = freelist;
    freelist = block;

    pthread_mutex_unlock(&alloc_lock);
}

// Example usage
int main() {
    init_memory_pool(1024);

    double amplitude_func(int index) { return 1.0 + (double)index / 100.0; }
    float frequency_func(int index) { return 440.0f * (float)(index % 10 + 1); }

    size_t num_signals = 100;
    Signal* signals = allocate_signal_array(num_signals, amplitude_func, frequency_func);

    if (!signals) {
        fprintf(stderr, "Signal allocation failed.\n");
        return EXIT_FAILURE;
    }

    size_t num_labels = 50;
    char* labels = allocate_label_array(num_labels);

    size_t num_offsets = 200;
    long* offsets = allocate_long_array(num_offsets);

    size_t num_keys = 100;
    int* keys = allocate_int_array(num_keys);

    size_t num_records = 150;
    Record* records = allocate_record_array(num_records);

    if (!labels || !offsets || !keys || !records) {
        fprintf(stderr, "Some allocations failed.\n");
    } else {
        printf("All allocations successful!\n");
    }

    // Clean up
    free_aligned(signals);
    free_aligned(labels);
    free_aligned(offsets);
    free_aligned(keys);
    free_aligned(records);

    return EXIT_SUCCESS;
}
