#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 1000
#define MAX_STRING_LENGTH 256
#define MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct node {
    char* string;
    int key;
    struct node* next;
} node_t;

// External dependency library stubs (replace with actual implementation)
void external_string_manipulate(char* str);
int external_integer_arithmetic(int a, int b);

// Logging mechanism
#define LOG_SIZE 0.1 * MEMORY_BUDGET
static char log_buffer[LOG_SIZE];
static size_t log_pos = 0;

void log_message(const char* message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    int len = snprintf(log_buffer + log_pos, LOG_SIZE - log_pos, "[%s] %s\n", timestamp, message);
    if (len > 0) {
        log_pos += len;
    }
}

// Memory tracking
size_t current_memory_usage = 0;

void update_memory_usage(size_t size_diff) {
    current_memory_usage += size_diff;
    printf("Current memory usage: %zu bytes\n", current_memory_usage);
    printf("Remaining budget: %zu bytes\n", MEMORY_BUDGET - current_memory_usage);
}

// Serialization and deserialization
void serialize_list(const char* filename, node_t* head) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return;
    }

    node_t* current = head;
    while (current) {
        fprintf(file, "%s %d\n", current->string, current->key);
        current = current->next;
    }

    fclose(file);
    log_message("List serialized successfully.");
}

node_t* deserialize_list(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        return NULL;
    }

    node_t* head = NULL, * tail = NULL;
    char buffer[MAX_STRING_LENGTH];
    int key;

    while (fscanf(file, "%255s %d", buffer, &key) == 2) {
        node_t* new_node = malloc(sizeof(node_t));
        if (!new_node) {
            log_message("Memory allocation failed during deserialization.");
            fclose(file);
            return NULL;
        }

        new_node->string = strdup(buffer);
        new_node->key = key;
        new_node->next = NULL;

        update_memory_usage(sizeof(node_t) + strlen(new_node->string) + 1);

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    fclose(file);
    log_message("List deserialized successfully.");
    return head;
}

// Insert a node into the list
void insert_node(node_t** head, const char* str, int key) {
    if (strlen(str) >= MAX_STRING_LENGTH || key < 0) {
        log_message("Invalid input for node insertion.");
        return;
    }

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
        log_message("Memory allocation failed during node insertion.");
        return;
    }

    new_node->string = strdup(str);
    new_node->key = key;
    new_node->next = *head;

    update_memory_usage(sizeof(node_t) + strlen(new_node->string) + 1);

    *head = new_node;
    log_message("Node inserted successfully.");
}

// Traverse and modify the list
void traverse_and_modify(node_t* head, void (*operation)(node_t*)) {
    node_t* current = head;
    while (current) {
        operation(current);
        current = current->next;
    }
}

// Example operation function
void example_operation(node_t* n) {
    external_string_manipulate(n->string);
    n->key = external_integer_arithmetic(n->key, 1);
}

// Initialize the linked list
node_t* initialize_list(int num_nodes) {
    if (num_nodes > MAX_NODES || num_nodes <= 0) {
        log_message("Invalid number of nodes requested.");
        return NULL;
    }

    node_t* head = NULL;
    char buffer[MAX_STRING_LENGTH];
    int key;

    for (int i = 0; i < num_nodes; ++i) {
        printf("Enter string (%d/%d): ", i + 1, num_nodes);
        scanf("%255s", buffer);

        printf("Enter key: ");
        scanf("%d", &key);

        insert_node(&head, buffer, key);
    }

    return head;
}

// Free the linked list
void free_list(node_t* head) {
    node_t* current = head;
    while (current) {
        node_t* next = current->next;
        free(current->string);
        free(current);
        update_memory_usage(-sizeof(node_t) - strlen(current->string) - 1);
        current = next;
    }
}

int main() {
    int num_nodes;
    printf("Enter the number of nodes: ");
    scanf("%d", &num_nodes);

    node_t* head = initialize_list(num_nodes);
    if (!head) {
        log_message("Failed to initialize list.");
        return EXIT_FAILURE;
    }

    traverse_and_modify(head, example_operation);

    serialize_list("list.txt", head);
    node_t* deserialized_head = deserialize_list("list.txt");

    free_list(head);
    free_list(deserialized_head);

    printf("Program completed successfully.\n");
    return EXIT_SUCCESS;
}
