#define LOG_MEMORY_BUDGET (10 * 1024) // 10 KB for logging
#define SYSTEM_MEMORY_BUDGET (50 * 1024 * 1024) // 50 MB total memory budget

typedef struct {
    int value;
} record;

// Logging function prototype
void log_error(const char* message);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int get_validated_input(const char* prompt, int max_value) {
    int input;
    do {
        printf("%s", prompt);
        if (scanf("%d", &input) != 1 || input <= 0 || input > max_value) {
            while(getchar() != '\n'); // Clear the buffer
            log_error("Invalid input. Please enter a number within the allowed range.");
            continue;
        }
    } while(input < 1 || input > max_value);
    return input;
}

void* initialize_memory(void* args) {
    int *offsets, *keys, num_records;
    long memory_used = 0;

    num_records = get_validated_input("Enter number of records (max %d): ", MAX_RECORDS);

    offsets = malloc(sizeof(long) * num_records);
    keys = malloc(sizeof(int) * num_records);

    if (!offsets || !keys) {
        log_error("Memory allocation failed.");
        free(offsets); // Ensure to free allocated memory
        free(keys);
        pthread_exit(NULL);
    }

    memory_used += sizeof(long) * num_records;
    memory_used += sizeof(int) * num_records;

    record* records = malloc(sizeof(record) * num_records);
    if (!records) {
        log_error("Memory allocation failed.");
        free(offsets);
        free(keys);
        pthread_exit(NULL);
    }
    memory_used += sizeof(record) * num_records;

    // Simulate external dependency for random number generation
