    int min_value = 0;
    int max_value = get_validated_input("Enter max value for records (max %d): ", MAX_INT_RANGE);

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_unlock(&lock);
    }

    if (memory_used > SYSTEM_MEMORY_BUDGET) {
        log_error("Memory usage exceeded the system budget.");
    } else {
        printf("Memory allocation and initialization completed successfully.\n");
    }

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

void log_error(const char* message) {
    // Implement a non-blocking logging mechanism
    static long log_memory_used = 0;
    const int LOG_MESSAGE_SIZE = 256;

    if (log_memory_used + LOG_MESSAGE_SIZE < LOG_MEMORY_BUDGET) {
        pthread_mutex_lock(&lock);
        printf("Error: %s\n", message);
        log_memory_used += LOG_MESSAGE_SIZE;
        pthread_mutex_unlock(&lock);
    } else {
        printf("Memory budget exceeded for logging. Error not logged.\n");
    }
}

int main() {
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, initialize_memory, NULL) != 0) {
        log_error("Failed to create a thread.");
        return 1;
    }

    pthread_join(thread_id, NULL);

    pthread_mutex_destroy(&lock);
    return 0;
}
