#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Error handling macro
#define CHECK_NULL(ptr, msg) if (!(ptr)) { fprintf(stderr, "%s\n", (msg)); exit(EXIT_FAILURE); }

void* allocate_memory(size_t size);
record* initialize_records(int count, int min_val, int max_val);

void manage_resources(int num_long_ints, int num_keys, int record_count, int range_min, int range_max, char mode) {
    long *long_array = NULL;
    int *key_array = NULL;
    record *records = NULL;

    if (mode == 'A') {
        // Single-pass allocation for Mode A
        size_t total_size = sizeof(long) * num_long_ints + sizeof(int) * num_keys + sizeof(record) * record_count;
        void *block = allocate_memory(total_size);

        long_array = (long *)block;
        key_array = (int *)(block + sizeof(long) * num_long_ints);
        records = (record *)(key_array + num_keys);

    } else if (mode == 'B') {
        // Separate allocations for Mode B
        long_array = (long *)allocate_memory(sizeof(long) * num_long_ints);
        key_array = (int *)allocate_memory(sizeof(int) * num_keys);
        records = initialize_records(record_count, range_min, range_max);
    }

    // Initialize arrays with zeros
    for (int i = 0; i < num_long_ints; ++i) {
        long_array[i] = 0;
    }
    for (int j = 0; j < num_keys; ++j) {
        key_array[j] = 0;
    }

    // Use the arrays as needed...

    // Free allocated memory
    if (mode == 'A') {
        free(long_array);  // `key_array` and `records` pointers are offsets in this block
    } else {
        free(long_array);
        free(key_array);
        free(records);
    }
}

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    CHECK_NULL(ptr, "Memory allocation failed");
    return ptr;
}

record* initialize_records(int count, int min_val, int max_val) {
    record *records = (record *)allocate_memory(sizeof(record) * count);

    // Simulate external service delay/failure handling
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    return records;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int num_long_ints = 10, num_keys = 5, record_count = 8;
    int range_min = 0, range_max = 100;

    printf("Mode A:\n");
    manage_resources(num_long_ints, num_keys, record_count, range_min, range_max, 'A');

    printf("\nMode B:\n");
    manage_resources(num_long_ints, num_keys, record_count, range_min, range_max, 'B');

    return 0;
}
```

### Explanation of the Implementation

- **Memory Allocation**: The function `allocate_memory` is used to allocate memory and check for failures.

- **Mode A**:
  - Allocates a single block of memory to hold all structures (`long_array`, `key_array`, and `records`) in contiguous memory. This minimizes allocation overhead, which is critical for performance-sensitive applications.

- **Mode B**:
  - Allocates each data structure separately using multiple calls to `malloc`. This mode enhances manageability and debuggability at the cost of additional overhead due to separate allocations.

- **Record Initialization**: The function `initialize_records` populates an array of `record` structures with random values. It simulates potential delays or failures when interfacing with external services by directly using the standard library's random number generation, wrapped in error handling for robustness.

- **Main Function**:
  - Demonstrates usage of both modes by invoking `manage_resources` with sample data.
  - Includes seeding the random number generator to ensure varied output on different runs. 

This implementation balances performance and maintainability, providing clear pathways for resource management under constrained conditions.']

