### C Code

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <jni.h>

#define MAX_ARRAY_SIZE 1024
#define VLAN_TAG_RANGE (4096)
#define DEFAULT_MEMORY_LIMIT 10485760 // 10 MB

typedef struct {
    uint8_t mac_address[6];
    int vlan_tag;
    int vlan_priority;
    int ip_checksum_calculated;
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    char *data; // Placeholder for packet data
    size_t length;
} NICB;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// LRU Cache structures and functions (simplified)
typedef struct Node {
    void *key;
    void *value;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    size_t capacity;
    Node* head;
    Node* tail;
    int size;
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    LRUCache* cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = NULL;
    cache->tail = NULL;
    return cache;
}

void remove_node(Node* node) {
    if (node->prev)
        node->prev->next = node->next;
    if (node->next)
        node->next->prev = node->prev;

    if (node == head)
        cache->head = node->next;
    if (node == tail)
        cache->tail = node->prev;

    free(node);
}

void put_cache(LRUCache* cache, void *key, void *value) {
    pthread_mutex_lock(&mutex);

    // Simplified LRU logic for brevity
    Node* new_node = malloc(sizeof(Node));
    new_node->key = key;
    new_node->value = value;

    if (cache->size >= cache->capacity) {
        remove_node(cache->head);
        cache->size--;
    }

    new_node->next = cache->head;
    new_node->prev = NULL;

    if (cache->head)
        cache->head->prev = new_node;

    cache->head = new_node;
    if (!cache->tail)
        cache->tail = new_node;

    cache->size++;
    pthread_mutex_unlock(&mutex);
}

// Function to initialize and populate NICB array
void initialize_nicb_array(NICB *nicbs, size_t count) {
    if (count == 0 || nicbs == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Initialize LRU Cache
    LRUCache* cache = create_cache(DEFAULT_MEMORY_LIMIT / sizeof(NICB));

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&mutex);

        nicbs[i].header.mac_address[0] = rand() % 256;
        nicbs[i].header.mac_address[1] = rand() % 256;
        nicbs[i].header.mac_address[2] = rand() % 256;
        nicbs[i].header.mac_address[3] = rand() % 256;
        nicbs[i].header.mac_address[4] = rand() % 256;
        nicbs[i].header.mac_address[5] = rand() % 256;

        nicbs[i].header.vlan_tag = rand() % VLAN_TAG_RANGE;
        nicbs[i].header.vlan_priority = (rand() & 0x07);
        nicbs[i].header.ip_checksum_calculated = (rand() & 1);

        nicbs[i].data = malloc(1500); // Example buffer size
        if (!nicbs[i].data) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }

        memset(nicbs[i].data, 0, 1500);
        nicbs[i].length = 1500;

        put_cache(cache, &nicbs[i], nicbs[i].data);

        pthread_mutex_unlock(&mutex);
    }
}
