["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double precision_value;
    char *variable_length_string;
} Data;

typedef struct {
    Data *data_array;
    size_t capacity;
    size_t count;
    size_t max_string_length;
    pthread_mutex_t mutex; // For thread safety
} DynamicArray;

// Initialize the dynamic array with a specified initial capacity and maximum string length
DynamicArray* init_dynamic_array(size_t initial_capacity, size_t max_string_length) {
    if (initial_capacity == 0 || max_string_length == 0) return NULL;

    DynamicArray *array = (DynamicArray*) malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data_array = (Data*) malloc(initial_capacity * sizeof(Data));
    if (!array->data_array) {
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        array->data_array[i].variable_length_string = (char*) malloc(max_string_length + 1); // +1 for null-terminator
        if (!array->data_array[i].variable_length_string) {
            while (--i >= 0) free(array->data_array[i].variable_length_string);
            free(array->data_array);
            free(array);
            return NULL;
        }
    }

    array->capacity = initial_capacity;
    array->count = 0;
    array->max_string_length = max_string_length;

    if (pthread_mutex_init(&array->mutex, NULL) != 0) {
        for (size_t i = 0; i < array->capacity; ++i)
            free(array->data_array[i].variable_length_string);
        free(array->data_array);
        free(array);
        return NULL;
    }

    return array;
}

// Add a new data element to the dynamic array
int add_data_element(DynamicArray *array, double precision_value, const char *string) {
    if (!array || !string) return -1;

    pthread_mutex_lock(&array->mutex);

    size_t str_len = strlen(string);
    if (str_len >= array->max_string_length) {
        pthread_mutex_unlock(&array->mutex);
        return -2; // String too long
    }

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Data *new_data_array = (Data*) realloc(array->data_array, new_capacity * sizeof(Data));
        if (!new_data_array) {
            pthread_mutex_unlock(&array->mutex);
            return -3; // Reallocation failed
        }

        for (size_t i = array->capacity; i < new_capacity; ++i) {
            new_data_array[i].variable_length_string = (char*) malloc(array->max_string_length + 1); 
            if (!new_data_array[i].variable_length_string) {
                while (i > array->capacity) free(new_data_array[--i].variable_length_string);
                pthread_mutex_unlock(&array->mutex);
                return -3;
            }
        }

        array->data_array = new_data_array;
        array->capacity = new_capacity;
    }

    Data *new_element = &array->data_array[array->count++];
    new_element->precision_value = precision_value;
    strncpy(new_element->variable_length_string, string, array->max_string_length);
    new_element->variable_length_string[array->max_string_length] = '\0';

    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
}

// Free the allocated dynamic array resources
void free_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i)
        free(array->data_array[i].variable_length_string);

    free(array->data_array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
```

### Explanation
- **Data Structure**: `DynamicArray` holds an array of `Data`, its current capacity, element count, maximum string length, and a mutex for synchronization.
- **Initialization**: Memory is allocated for the initial data array, ensuring strings can fit within specified limits. Error handling ensures safe cleanup if allocation fails.
- **Adding Elements**: Locks are used to ensure thread safety when adding elements or resizing. Strings exceeding max length are rejected, and reallocation doubles capacity if needed.
- **Freeing Resources**: Properly frees memory allocated for strings and the data array itself, ensuring no leaks."]

