// Function to check uniqueness of keys in an array
int are_keys_unique(int *keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) {
                return 0;
            }
        }
