// Memory management function with alignment and integrity checks
void* manage_memory(size_t offsetCount, size_t keyCount, size_t recordCount,
                    int minValue, int maxValue, size_t alignment) {

    // Determine total required memory size for each data structure
    size_t longSize = sizeof(long) * offsetCount;
    size_t intSize = sizeof(int) * keyCount;
    size_t recordStructSize = sizeof(record) * recordCount;

    // Calculate aligned sizes
    longSize = align_size(longSize, alignment);
    intSize = align_size(intSize, alignment);
    recordStructSize = align_size(recordStructSize, alignment);

    // Calculate total memory needed and allocate with aligned boundary
    size_t totalMemorySize = longSize + intSize + recordStructSize;

    void *memoryBlock = malloc(totalMemorySize);
    if (!memoryBlock) {
        log_error("Failed to allocate memory");
        return NULL;
    }

    // Align the start of each data structure within the block
    char *alignedLong = (char *)(((uintptr_t)memoryBlock + alignment - 1) & ~(alignment - 1));
    size_t usedMemorySize = align_size((size_t)(alignedLong - memoryBlock), alignment);

    char *alignedInt = alignedLong + longSize;
    usedMemorySize += align_size((size_t)(alignedInt - alignedLong), alignment);

    char *alignedRecord = alignedInt + intSize;

    // Initialize the data structures
    long *offsets = (long *)alignedLong;
    for (size_t i = 0; i < offsetCount; ++i) {
        offsets[i] = rand() % 1000;  // Example values, replace with actual logic
