void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
    return ptr;
}

TreeNode* create_node(const char *data, size_t metadata1, size_t metadata2, size_t num_children) {
    TreeNode *node = aligned_alloc(16, sizeof(TreeNode));
    node->data = strdup(data);
    node->metadata1 = metadata1;
    node->metadata2 = metadata2;
    node->ref_count = 0;
    node->children = aligned_alloc(16, sizeof(TreeNode*) * num_children);
    node->num_children = num_children;

    return node;
}

TreeManager* init_tree_manager() {
    TreeManager *manager = (TreeManager *)aligned_alloc(16, sizeof(TreeManager));
