    pthread_rwlock_wrlock(&manager->lock);

    if (manager->total_memory_allocated + sizeof(TreeNode) + strlen(data) + 1 > MAX_MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded\n");
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    TreeNode *new_node = create_node(data, metadata1, metadata2, 0);

    atomic_fetch_add_explicit(&(parent->ref_count), 1, memory_order_relaxed);

    size_t new_num_children = parent->num_children + 1;
    TreeNode **new_children = aligned_alloc(16, sizeof(TreeNode*) * new_num_children);

    memcpy(new_children, parent->children, sizeof(TreeNode*) * parent->num_children);
    new_children[parent->num_children] = new_node;

    free(parent->children);
    parent->children = new_children;
    parent->num_children = new_num_children;

    manager->total_memory_allocated += (sizeof(TreeNode) + strlen(data) + 1);

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

void verify_tree_integrity(TreeManager *manager, TreeNode *node) {
