#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define ALIGNMENT 64

typedef struct TreeNode {
    char *label;
    size_t depth;
    struct TreeNode *left, *right;
} TreeNode;

// Align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#ifdef _WIN32
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
#else
    ptr = aligned_alloc(alignment, size);
#endif
    return ptr;
}

// Free memory with specific alignment
void aligned_free(void *ptr) {
#ifdef _WIN32
    free(ptr);
#else
    free(ptr);
#endif
}

// Log insertion attempts and outcomes
void log_insertion(const char *message) {
    printf("LOG: %s\n", message);
}

// Verify tree integrity
int verify_tree_integrity(TreeNode *node, size_t depth_constraint) {
    if (node == NULL) return 1;

    // Check balance conditions here if required

    // Recursively check the left and right subtrees
    int left_valid = verify_tree_integrity(node->left, depth_constraint);
    int right_valid = verify_tree_integrity(node->right, depth_constraint);

    if (!left_valid || !right_valid) return 0;

    // Ensure no label is NULL or duplicates in this simplified check
    if (node->label == NULL) {
        log_insertion("Node has a missing label.");
        return 0;
    }

    return 1;
}

// Insert node into the tree, handles missing labels and depth constraints
TreeNode* insert_node(TreeNode *root, char *label, size_t current_depth, size_t max_depth) {
    if (max_depth == 0) return root;

    // Create a new tree node with aligned memory allocation
    TreeNode *new_node = (TreeNode*)aligned_alloc(ALIGNMENT, sizeof(TreeNode));
    if (!new_node) {
        log_insertion("Memory allocation failed for new node.");
        return NULL;
    }

    if (label != NULL) {
        new_node->label = strdup(label); // Duplicate label string
        if (!new_node->label) {
            aligned_free(new_node);
            log_insertion("Failed to duplicate label for new node.");
            return NULL;
        }
    } else {
        new_node->label = NULL;
    }

    new_node->depth = current_depth;
    new_node->left = new_node->right = NULL;

    if (root == NULL) {
        root = new_node;
    } else {
        // Simple insertion logic for demonstration purposes
        if (current_depth % 2 == 0) { // Example condition to insert left/right
            log_insertion("Inserting node on the left.");
            root->left = insert_node(root->left, label, current_depth + 1, max_depth - 1);
        } else {
            log_insertion("Inserting node on the right.");
            root->right = insert_node(root->right, label, current_depth + 1, max_depth - 1);
        }
    }

    return root;
}

// In-order traversal of the tree
void inorder_traversal(TreeNode *node) {
    if (node == NULL) return;

    inorder_traversal(node->left);

    // Print node's label
    if (node->label != NULL)
        printf("Node Label: %s, Depth: %zu\n", node->label, node->depth);
    else
        printf("Node is missing a label.\n");

    inorder_traversal(node->right);
}

// Free the entire tree with aligned memory deallocation
void free_tree(TreeNode *node) {
    if (node == NULL) return;

    free_tree(node->left);
    free_tree(node->right);

    if (node->label != NULL)
        free(node->label);

    aligned_free(node);
}

int main() {
    TreeNode *root = NULL;
    size_t max_depth = 3; // Example depth constraint

    // Insert nodes with some potentially missing labels
    root = insert_node(root, "Root", 0, max_depth);
    root = insert_node(root, "LeftChild", 1, max_depth - 1);
    root = insert_node(NULL, NULL, 2, max_depth - 2); // Missing label example

    inorder_traversal(root);

    if (!verify_tree_integrity(root, max_depth)) {
        log_insertion("Tree integrity verification failed.");
    }

    free_tree(root);
    return 0;
