#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 5 * 1024 * 1024 // 5 MB

typedef struct {
    size_t size;
    union {
        double dbl;
        char *str;
    } data;
} Item;

typedef struct {
    int value;
    char identifier[256];
    Item *item;
} Record;

typedef struct Node {
    int key;
    Record record;
    struct Node* next;
} HashNode;

#define HASH_TABLE_SIZE 1024

HashNode* hashTable[HASH_TABLE_SIZE];

unsigned long hashFunction(int key) {
    return key % HASH_TABLE_SIZE;
}

void insertToHashTable(int key, Record record) {
    unsigned long index = hashFunction(key);
    HashNode *newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->key = key;
    newNode->record = record;
    newNode->next = hashTable[index];
    hashTable[index] = newNode;
}

Record* lookupInHashTable(int key) {
    unsigned long index = hashFunction(key);
    HashNode *node = hashTable[index];
    while (node != NULL) {
        if (node->key == key) return &node->record;
        node = node->next;
    }
    return NULL;
}

void freeMemory(Record *records, size_t recordCount) {
    for (size_t i = 0; i < recordCount; ++i) {
        if (records[i].item != NULL) {
            free(records[i].item);
        }
    }
    free(records);
}

int main() {
    // Example usage
    size_t longPtrCount = 100;
    size_t doubleCount = 100;
    size_t structCount = 100;

    long *longPointers = (long*)malloc(longPtrCount * sizeof(long));
    double *doubles = (double*)malloc(doubleCount * sizeof(double));
    char **strings = (char**)malloc(structCount * sizeof(char*));

    Record *records = (Record*)malloc(structCount * sizeof(Record));
    int *keys = (int*)malloc(structCount * sizeof(int));

    for (size_t i = 0; i < structCount; ++i) {
        strings[i] = (char*)malloc(256);
        snprintf(strings[i], 256, "Record_%zu", i);

        records[i].item = (Item*)malloc(sizeof(Item));
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID_%zu_Time_%ld", i, time(NULL));
    }

    // Insert into hash table
    for (size_t i = 0; i < structCount; ++i) {
        insertToHashTable(keys[i], records[i]);
    }

    // Free memory
    freeMemory(records, structCount);
    free(longPointers);
    free(doubles);
    for (size_t i = 0; i < structCount; ++i) {
        free(strings[i]);
    }
    free(strings);
    free(keys);

    return 0;
}
