void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_WIN32)
    if (alignment <= sizeof(void*)) {
        ptr = _aligned_malloc(size, alignment);
    } else {
        ptr = _aligned_offset_malloc(size, alignment - sizeof(void*));
    }
#else
