// Thread-safe random number generator initialization
void init_thread_safe_random() {
    srand(time(NULL));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_once(&mutex, NULL);
}

// Generate a unique alphanumeric identifier
char* generate_alphanumeric_identifier(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t charset_size = sizeof(charset) - 1;
    char *identifier = malloc(length + 1); // +1 for null terminator

    if (identifier == NULL) {
        perror("Failed to allocate memory for identifier");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < length; i++) {
        size_t index = rand() % charset_size;
        identifier[i] = charset[index];
    }
    identifier[length] = '\0';
    pthread_mutex_unlock(&mutex);

    return identifier;
}

// Function to initialize and populate arrays
void initialize_and_populate_arrays(size_t count, int range_min, int range_max) {
