#define LOG_ERROR(msg) fprintf(stderr, "ERROR: %s\n", msg)

typedef struct {
    int key;
    char *name;
    int value;
} Record;

int init_records(int num_records, int min_value, int max_value, unsigned int seed, const size_t* name_lengths) {
    if (num_records <= 0 || min_value > max_value || seed == 0) return -1;

    srand(seed);

    // Allocate memory for the array of records
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        LOG_ERROR("Failed to allocate memory for records.");
        return -2;
    }
    LOG_SUCCESS("Allocated memory for records.");

    for (int i = 0; i < num_records; ++i) {
        // Calculate random value
        int range = max_value - min_value + 1;
        if (range <= 0 || INT_MAX / range < min_value) {
            free(records);
            LOG_ERROR("Integer overflow detected in calculating random values.");
            return -3;
        }

        int value = rand() % range + min_value;

        // Allocate memory for the name
        size_t length = (i < num_records && name_lengths[i] > 0) ? name_lengths[i] : 10; // Default length if not provided
        char *name = malloc((length + 1) * sizeof(char));
        if (!name) {
            LOG_ERROR("Failed to allocate memory for record name.");
            while (i-- > 0) free(records[i].name); // Free previously allocated names
            free(records);
            return -4;
        }
        snprintf(name, length + 1, "Name_%d", i); // Initialize with a sample string

        // Assign values to the record
        records[i] = (Record){i, name, value};
    }

    LOG_SUCCESS("All records initialized successfully.");

    // For demonstration purposes: Print all records
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Key=%d, Name='%s', Value=%d\n", i, records[i].key, records[i].name, records[i].value);
    }

    // Free allocated memory
    for (int i = 0; i < num_records; ++i) {
        free(records[i].name);
    }
    free(records);

    LOG_SUCCESS("Freed all allocated memory.");

    return 0;
}

int main() {
    size_t name_lengths[] = {8, 12, 15}; // Example lengths
    int result = init_records(3, 10, 100, 42, name_lengths);
    if (result != 0) {
        LOG_ERROR("Failed to initialize records.");
    }
    return result;
}
