#include <string.h>
#include <time.h>

#define ID_LENGTH 8

typedef struct entry {
    int value;
    char *id;
    struct entry *next;
    unsigned int ref_count;
} entry_t;

char* generate_random_id() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char id[ID_LENGTH + 1];
    for (int i = 0; i < ID_LENGTH; i++) {
        id[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    id[ID_LENGTH] = '\0';
    return strdup(id);
}

void free_entry(entry_t *entry) {
    if (--entry->ref_count == 0) {
        free(entry->id);
        free(entry);
    }
}

int main() {
    int num_entries, range_min, range_max;
    printf("Enter number of entries: ");
    scanf("%d", &num_entries);
    printf("Enter min and max range for random values: ");
    scanf("%d %d", &range_min, &range_max);

    srand(time(NULL));

    entry_t **entries = malloc(num_entries * sizeof(entry_t*));
    if (!entries) {
        fprintf(stderr, "Failed to allocate memory for entries array.\n");
        return 1;
    }

    int self_pointing_count = 0;

    for (int i = 0; i < num_entries; ++i) {
        entry_t *new_entry = malloc(sizeof(entry_t));
        if (!new_entry) {
            fprintf(stderr, "Failed to allocate memory for an entry.\n");
            // Free already allocated entries
            while (--i >= 0) {
                free_entry(entries[i]);
            }
            free(entries);
            return 1;
        }

        new_entry->value = rand() % (range_max - range_min + 1) + range_min;
        new_entry->id = generate_random_id();
        if (!new_entry->id) {
            fprintf(stderr, "Failed to allocate memory for an ID.\n");
            free(new_entry);
            // Free already allocated entries
            while (--i >= 0) {
                free_entry(entries[i]);
            }
            free(entries);
            return 1;
        }

        new_entry->ref_count = 1;

        int next_index = rand() % num_entries;
        if (next_index == i) { 
            self_pointing_count++;
        }

        entry_t *next_entry = entries[next_index];
        while (!next_entry) {
            // Wait for the dependent struct to be allocated
            continue;
        }

        new_entry->next = next_entry;
        next_entry->ref_count++;

        entries[i] = new_entry;
    }

    printf("Number of self-pointing entries: %d\n", self_pointing_count);

    // Free all entries after use
    for (int i = 0; i < num_entries; ++i) {
        free_entry(entries[i]);
    }
    free(entries);

    return 0;
}
