#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define ALIGNMENT 32
#define DEFAULT_MAX_NODES 100
#define DEFAULT_STRING_LENGTH 8

typedef enum {
    ACTIVE,
    INACTIVE,
    PENDING
} status_t;

typedef struct node {
    int value;
    char *identifier;
    status_t state;
} node_t;

static void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__)
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void free_aligned_alloc(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__unix__)
    free(ptr);
#endif
}

int is_unique(const int *array, int value, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i] == value) {
            return 0;
        }
    }
    return 1;
}

char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t charset_length = sizeof(charset) - 1;
    char *string = malloc(length + 1);

    if (!string) {
        return NULL;
    }

    for (size_t i = 0; i < length; ++i) {
        string[i] = charset[rand() % charset_length];
    }
    string[length] = '\0';

    return string;
}

int* generate_unique_random_numbers(size_t count, int min, int max) {
    int *numbers = malloc(count * sizeof(int));
    if (!numbers) {
        return NULL;
    }

    for (size_t i = 0; i < count;) {
        int num = rand() % (max - min + 1) + min;

        if (is_unique(numbers, num, i)) {
            numbers[i++] = num;
        }
    }

    return numbers;
}

node_t** create_nodes(size_t max_nodes, size_t string_length, int value_min, int value_max) {
    node_t **nodes = aligned_alloc(ALIGNMENT, max_nodes * sizeof(node_t*));

    if (!nodes) {
        return NULL;
    }

    srand((unsigned int)time(NULL));

    int *unique_values = generate_unique_random_numbers(max_nodes, value_min, value_max);

    if (!unique_values) {
        free_aligned_alloc(nodes);
        return NULL;
    }

    for (size_t i = 0; i < max_nodes; ++i) {
        nodes[i] = malloc(sizeof(node_t));

        if (!nodes[i]) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(nodes[j]->identifier);
                free(nodes[j]);
            }
            free_aligned_alloc(nodes);
            free(unique_values);
            return NULL;
        }

        nodes[i]->value = unique_values[i];
        nodes[i]->identifier = generate_random_string(string_length);

        if (!nodes[i]->identifier) {
            // Handle string allocation failure
            for (size_t j = 0; j <= i; ++j) {
                free(nodes[j]->identifier);
                free(nodes[j]);
            }
            free_aligned_alloc(nodes);
            free(unique_values);
            return NULL;
        }

        nodes[i]->state = ACTIVE;  // Or any default state
    }

    free(unique_values);

    return nodes;
}

void verify_nodes(node_t **nodes, size_t count, int value_min, int value_max) {
    if (!nodes) {
        printf("Node array is NULL.\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        node_t *node = nodes[i];

        if (!node->identifier || node->value < value_min || node->value > value_max) {
            printf("Verification failed at index %zu.\n", i);
            return;
        }
    }

    int *unique_check = malloc(count * sizeof(int));

    for (size_t i = 0; i < count; ++i) {
        unique_check[i] = nodes[i]->value;
    }

    for (size_t i = 0; i < count; ++i) {
        for (size_t j = 0; j < count; ++j) {
            if (i != j && unique_check[i] == unique_check[j]) {
                printf("Duplicate value found: %d at index %zu and %zu.\n", unique_check[i], i, j);
                free(unique_check);
                return;
            }
        }
    }

    printf("All nodes are verified successfully.\n");
    free(unique_check);
}

int main() {
    size_t max_nodes = DEFAULT_MAX_NODES;
    size_t string_length = DEFAULT_STRING_LENGTH;
    int value_min = 1, value_max = 1000;

    node_t **nodes = create_nodes(max_nodes, string_length, value_min, value_max);

    if (nodes) {
        verify_nodes(nodes, max_nodes, value_min, value_max);

        for (size_t i = 0; i < max_nodes; ++i) {
            free(nodes[i]->identifier);
            free(nodes[i]);
        }
        free_aligned_alloc(nodes);
    } else {
        printf("Failed to create nodes.\n");
    }

    return 0;
}
