void seed_rng(unsigned long long user_key) {
    pthread_mutex_lock(&rng_lock);
    rng_state[0] = 123456789;
    rng_state[1] = hash_user_key(user_key);
    pthread_mutex_unlock(&rng_lock);
}

unsigned int xorshift128() {
    unsigned long long s1 = rng_state[0];
    unsigned long long s0 = rng_state[1];
    const unsigned long long s1_prime = s1 * 2862933555777941757ULL;
    rng_state[0] = s0;
    s1 ^= (s1 << 23);
    rng_state[1] = s1 ^ s1_prime ^ (s1 >> 18) ^ (s0 >> 5);
    return (unsigned int)(rng_state[1] + s0);
}

