    int index = *(int *)arg + 1;

    // Initialize MAC header and MAC addresses
    memset(nicbs[index].dest_mac_address, 0xFF, MAX_MAC_ADDRESS_LENGTH);
    for (int i = 0; i < 6; ++i) {
        nicbs[index].src_mac[i] = xorshift128() & 0xFF;
    }

    // Assign VLAN tag
    nicbs[index].vlan_tag = xorshift128() % (VLAN_TAG_MAX + 1);

    // Set status flag based on dummy temperature and index
    float dummy_temperature = 20.0f + (xorshift128() % 100) / 10.0f;
    nicbs[index].status_flag = (dummy_temperature > 25) ? 'H' : 'N';

    return NULL;
}

void initialize_environmental_nicb_array(int array_size, const char *user_key) {
    pthread_t threads[array_size];
    int indices[array_size];

    // Seed the random number generator
    seed_rng(hash_user_key(user_key));

    // Allocate and initialize NICB structures with alignment
    NICB *nicbs = (NICB *)aligned_alloc(ALIGNMENT_BOUNDARY, array_size * sizeof(NICB));
    if (!nicbs) {
        fprintf(stderr, "Failed to allocate memory for NICBs\n");
        return;
    }

    int failed_validations = 0;

    // Initialize NICBs in parallel
    for (int i = 0; i < array_size; ++i) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, init_nicb, &indices[i]);
    }

    for (int i = 0; i < array_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Sensor data allocation and initialization
    size_t sensor_data_size = array_size * sizeof(SensorData);
    SensorData *sensor_data = aligned_alloc(ALIGNMENT_BOUNDARY, sensor_data_size);
    if (!sensor_data) {
