        free(nicbs);
        return;
    }

    float wind_speed_sum = 0.0f;

    // Initialize sensor data
    for (int i = 0; i < array_size; ++i) {
        sensor_data[i].temperature = 10.0f + ((float)xorshift128() / UINT_MAX * 30.0f);
        sensor_data[i].humidity = 20.0f + ((float)xorshift128() / UINT_MAX * 60.0f);
        float wind_speed = (float)xorshift128() / UINT_MAX * 100.0f;
        wind_speed_sum += wind_speed;
        sensor_data[i].wind_speed = wind_speed_sum / (i + 1);
        sensor_data[i].record_index = i;

        // Log detailed diagnostics
        printf("Sensor Data - Index: %d, Temperature: %.2f, Humidity: %.2f, Wind Speed: %.2f\n",
               i, sensor_data[i].temperature, sensor_data[i].humidity, sensor_data[i].wind_speed);
    }

    // Periodic cleanup mechanism placeholder

    // Cleanup and release resources
    free(nicbs);
    free(sensor_data);

    printf("Initialization completed with %d failed MAC validations.\n", failed_validations);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <array_size> <user_key>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int array_size = atoi(argv[1]);
    initialize_environmental_nicb_array(array_size, argv[2]);

    return EXIT_SUCCESS;
}
