#define MEMORY_LIMIT (1024 * 1024) // Example system-defined limit, 1MB

// Helper function to align the size
size_t align_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

int manage_dynamic_allocation(
    long **long_array, double *double_values, char ***char_2d_array,
    size_t *num_long_elements, size_t *num_double_elements,
    size_t num_rows, size_t num_cols,
    size_t long_alignment, size_t double_alignment,
    size_t char_alignment
) {
    // Check for invalid inputs
    if (long_array == NULL || double_values == NULL ||
        char_2d_array == NULL || num_long_elements == NULL ||
        num_double_elements == NULL || num_rows <= 0 || num_cols <= 0) {
        return -1; // Error: Invalid input parameters
    }

    size_t long_size = *num_long_elements * sizeof(long*);
    size_t double_size = *num_double_elements * sizeof(double);
    size_t char_2d_size = num_rows * align_size(num_cols, char_alignment) * sizeof(char);

    // Calculate aligned sizes
    long_size = align_size(long_size, long_alignment);
    double_size = align_size(double_size, double_alignment);
    char_2d_size = align_size(char_2d_size, char_alignment);

    size_t total_size = long_size + double_size + char_2d_size;

    // Check if the total allocation exceeds memory limits
    if (total_size > MEMORY_LIMIT) {
        return -1; // Error: Memory limit exceeded
    }

    // Allocate memory for each structure with alignment
    void *block = malloc(total_size);
    if (!block) {
        return -2; // Error: Allocation failed
    }

    long *aligned_long_array = (long*)align_size((size_t)((char*)block + sizeof(long)), long_alignment);
    double *aligned_double_values = (double*)align_size(
        (size_t)((char*)aligned_long_array + long_size), double_alignment);

    char **aligned_char_2d_array = (char**)(align_size(
        (size_t)((char*)aligned_double_values + double_size), char_alignment));

    // Calculate the start of the actual 2D array
    *char_2d_array = (char**)aligned_char_2d_array;
    for (size_t i = 0; i < num_rows; ++i) {
        (*char_2d_array)[i] = (char*)((size_t)((char*)aligned_char_2d_array + i * align_size(num_cols, char_alignment)));
    }

    // Assign pointers
    *long_array = aligned_long_array;
    *double_values = aligned_double_values;

    // Initialize the allocated data for verification
    for (size_t i = 0; i < *num_long_elements; ++i) {
        (*long_array)[i] = (long)i;
    }
    for (size_t i = 0; i < *num_double_elements; ++i) {
        (*double_values)[i] = (double)i + 0.5;
    }
    for (size_t i = 0; i < num_rows; ++i) {
        memset((*char_2d_array)[i], 'A' + i % 26, num_cols);
    }

    // Verify data integrity
    for (size_t i = 0; i < *num_long_elements; ++i) {
        if ((*long_array)[i] != (long)i) return -3; // Error: Data corruption in long array
    }
    for (size_t i = 0; i < *num_double_elements; ++i) {
