#include <time.h>

typedef struct {
    long offset;
    int key;
    void *data_block;
} Record;

// Utility function to align size to the nearest multiple of alignment
size_t align_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

// Function to initialize and allocate memory for records
Record* create_records(int num_records, int key_range_min, int key_range_max,
                       size_t alignment_boundary, int enable_logging) {

    if (num_records <= 0 || key_range_min > key_range_max)
        return NULL;

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        if (enable_logging) printf("Memory allocation failed for records array.\n");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand(); // Random offset as an example

        records[i].key = key_range_min + rand() % (key_range_max - key_range_min + 1);

        size_t data_block_size = align_size(records[i].key, alignment_boundary);
        records[i].data_block = malloc(data_block_size);

        if (!records[i].data_block) {
            if (enable_logging)
                printf("Memory allocation failed for data block of record %d.\n", i);

            // Clean up previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(records[j].data_block);
            }
            free(records);
            return NULL;
        }

        if (enable_logging)
            printf("Allocated data block of size %zu for record %d.\n", data_block_size, i);

        // Initialize the memory with some pattern or zeroing out
        memset(records[i].data_block, 0, data_block_size);
    }

    return records;
}

// Function to free allocated records
void destroy_records(Record *records, int num_records) {
    if (!records)
        return;

    for (int i = 0; i < num_records; ++i) {
        free(records[i].data_block);
    }
    free(records);
}
