#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_NODES 100
#define ITEMS_PER_NODE 50
#define ALIGNMENT 64
#define ITEM_STRING_LENGTH 10

typedef struct Node {
    double value;
} Node;

typedef union Metadata {
    struct Item* item_ptr;
    short value;
} Metadata;

typedef struct Item {
    int key;
    char str[ITEM_STRING_LENGTH];
    Metadata metadata;
    struct Item* next; // For linked list
} Item;

typedef struct {
    Node** nodes;
    Item* head;
    int* int_array;
    size_t int_array_size;
} DataStructures;

void *aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

void aligned_free(void* ptr) {
    free(ptr);
}

bool is_prime(int number) {
    if (number <= 1) return false;
    for (int i = 2; i * i <= number; ++i)
        if (number % i == 0)
            return false;
    return true;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

DataStructures* initialize_data_structures() {
    DataStructures* ds = aligned_malloc(sizeof(DataStructures), ALIGNMENT);
    if (!ds) {
        log_error("Failed to allocate memory for DataStructures");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate nodes
    ds->nodes = aligned_malloc(MAX_NODES * sizeof(Node*), ALIGNMENT);
    if (!ds->nodes) {
        log_error("Failed to allocate memory for nodes array");
        aligned_free(ds);
        return NULL;
    }

    // Initialize linked list head and integer array
    ds->head = NULL;
    ds->int_array_size = 0;
    ds->int_array = NULL;

    srand(time(NULL));

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < MAX_NODES; ++i) {
        Node* node = aligned_malloc(sizeof(Node), ALIGNMENT);
        if (!node) {
            log_error("Failed to allocate memory for a node");
            // Cleanup
            while (--i >= 0)
                aligned_free(ds->nodes[i]);
            aligned_free(ds->nodes);
            aligned_free(ds);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        int random_value = rand() % 1000 + 1; // Random integer in range [1, 1000]
        node->value = round(sqrt(random_value) * 1000.0) / 1000.0;

        ds->nodes[i] = node;

        for (int j = 0; j < ITEMS_PER_NODE; ++j) {
            Item* item = aligned_malloc(sizeof(Item), ALIGNMENT);
            if (!item) {
                log_error("Failed to allocate memory for an item");
                // Cleanup
                while (--i >= 0)
                    aligned_free(ds->nodes[i]);
                aligned_free(ds->nodes);
                aligned_free(ds);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            item->key = rand() % 10000; // Unique key (ensure uniqueness in real use-case)
            for (int k = 0; k < ITEM_STRING_LENGTH - 1; ++k) {
                item->str[k] = (rand() % 2) ? 'a' + (rand() % 26) : '0' + (rand() % 10);
            }
            item->str[ITEM_STRING_LENGTH - 1] = '\0';

            if ((double)rand() / RAND_MAX < 0.5) {
                item->metadata.item_ptr = NULL; // Simulating a pointer to another Item
            } else {
                item->metadata.value = rand() % 100;
            }

            item->next = ds->head;
            ds->head = item;

            int* int_array_new = aligned_malloc((ds->int_array_size + 1) * sizeof(int), ALIGNMENT);
            if (!int_array_new) {
                log_error("Failed to reallocate integer array");
                while (--i >= 0)
                    free(ds->nodes[i]);
                free(ds->nodes);
                // Free linked list
                Item* current = ds->head;
                while (current) {
                    Item* next = current->next;
                    free(current);
                    current = next;
                }
                aligned_free(ds);
                pthread_mutex_unlock(&lock);
                return NULL;
            }

            int_array_new[ds->int_array_size++] = item->key; // Add key to integer array
            if (ds->int_array)
                memcpy(int_array_new, ds->int_array, ds->int_array_size * sizeof(int));

            free(ds->int_array);
            ds->int_array = int_array_new;
        }
    }

    pthread_mutex_unlock(&lock);

    return ds;
}

void destroy_data_structures(DataStructures* ds) {
    if (!ds)
        return;

    for (size_t i = 0; i < MAX_NODES; ++i) {
        free(ds->nodes[i]);
    }

    free(ds->nodes);

    Item* current = ds->head;
    while (current) {
        Item* next = current->next;
        free(current);
        current = next;
    }

    if (ds->int_array)
        free(ds->int_array);

    free(ds);
}

bool verify_integrity(DataStructures* ds) {
    for (size_t i = 0; i < MAX_NODES; ++i) {
        Item* seen_keys[MAX_NODES];
        memset(seen_keys, 0, sizeof(seen_keys));

        for (Item* current = ds->head; current != NULL; current = current->next) {
            if (current->key >= MAX_NODES || seen_keys[current->key])
                return false;
            seen_keys[current->key] = true;
        }
    }

    return true;
}

void serialize_data_structures(DataStructures* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization");
        return;
    }

    fwrite(&MAX_NODES, sizeof(size_t), 1, file);
    fwrite(ds->nodes, MAX_NODES * sizeof(Node*), 1, file);

    Item* current = ds->head;
    while (current != NULL) {
        fwrite(current, sizeof(Item), 1, file);
        current = current->next;
    }

    size_t int_array_size = ds->int_array_size;
    fwrite(&int_array_size, sizeof(size_t), 1, file);
    if (int_array_size > 0)
        fwrite(ds->int_array, int_array_size * sizeof(int), 1, file);

    fclose(file);
}

void deserialize_data_structures(DataStructures** ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization");
        return;
    }

    size_t num_nodes;
    fread(&num_nodes, sizeof(size_t), 1, file);

    *ds = aligned_malloc(sizeof(DataStructures), ALIGNMENT);
    (*ds)->nodes = aligned_malloc(num_nodes * sizeof(Node*), ALIGNMENT);

    fread((*ds)->nodes, num_nodes * sizeof(Node*), 1, file);

    Item* head = NULL;
    while (true) {
        Item* item = malloc(sizeof(Item));
        if (!item)
            break;

        size_t read_result = fread(item, sizeof(Item), 1, file);
        if (read_result == 0) {
            free(item);
            break; // End of file
        }

        item->next = head;
        head = item;
    }

    (*ds)->head = head;

    size_t int_array_size;
    fread(&int_array_size, sizeof(size_t), 1, file);

    if (int_array_size > 0) {
        (*ds)->int_array_size = int_array_size;
        (*ds)->int_array = aligned_malloc(int_array_size * sizeof(int), ALIGNMENT);
        fread((*ds)->int_array, int_array_size * sizeof(int), 1, file);
    } else {
        (*ds)->int_array_size = 0;
        (*ds)->int_array = NULL;
    }

    fclose(file);
}

// Example usage
int main() {
    DataStructures* ds = initialize_data_structures();
    if (!ds) {
        return EXIT_FAILURE;
    }

    if (verify_integrity(ds)) {
        printf("Data integrity verified.\n");
    } else {
        printf("Data integrity verification failed.\n");
    }

    serialize_data_structures(ds, "data.bin");

    DataStructures* ds2 = NULL;
    deserialize_data_structures(&ds2, "data.bin");

    destroy_data_structures(ds);
    destroy_data_structures(ds2);

    return EXIT_SUCCESS;
}
```

This code demonstrates how to manage memory allocation and initialization for an array of `Node` pointers, a linked list of `Item` structures, and a dynamically sized integer array. It handles alignment requirements, potential memory limit issues, error checking, data integrity verification, serialization/deserialization, and concurrent access protection using mutex locks. The function also logs errors and organizes data to optimize cache usage for better performance.']

