#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_BLOCK_SIZE 256

typedef struct Dependency {
    int task_id;
    float weight;
    struct Dependency *next;
} Dependency;

typedef struct Task {
    int priority;
    char status[20];
    int completion_time;
    struct Task *next;
    Dependency *dependencies;
} Task;

typedef struct Project {
    Task *tasks;
} Project;

void *aligned_malloc(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, MEMORY_BLOCK_SIZE, size)) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void aligned_free(void *ptr) {
    free(ptr);
}

Dependency* create_dependency(int task_id, float weight) {
    Dependency *dep = (Dependency*)aligned_malloc(sizeof(Dependency));
    dep->task_id = task_id;
    dep->weight = weight;
    dep->next = NULL;
    return dep;
}

Task* create_task(int priority, int completion_time) {
    Task *task = (Task*)aligned_malloc(sizeof(Task));
    sprintf(task->status, "INIT");
    task->priority = priority;
    task->completion_time = completion_time;
    task->dependencies = NULL;
    task->next = NULL;

    // Initialize dependencies with random weights
    for (int i = 0; i < rand() % 5 + 1; ++i) {
        Dependency *dep = create_dependency(rand() % 100, ((float)rand() / RAND_MAX) * 10.0);
        dep->next = task->dependencies;
        task->dependencies = dep;
    }

    // State machine for status
    if (task->priority > 5 && task->completion_time < 50) {
        sprintf(task->status, "URGENT");
    } else if (task->completion_time >= 50) {
        sprintf(task->status, "COMPLETED");
    } else {
        sprintf(task->status, "IN_PROGRESS");
    }

    return task;
}

Project* create_project() {
    Project *project = (Project*)aligned_malloc(sizeof(Project));
    project->tasks = NULL;
    return project;
}

void add_task(Project *project, Task *task) {
    task->next = project->tasks;
    project->tasks = task;
}

void free_dependencies(Dependency *dep) {
    while (dep) {
        Dependency *temp = dep;
        dep = dep->next;
        aligned_free(temp);
    }
}

void free_tasks(Task *task) {
    while (task) {
        Task *temp = task;
        free_dependencies(task->dependencies);
        task = task->next;
        aligned_free(temp);
    }
}

void free_project(Project *project) {
    if (project) {
        free_tasks(project->tasks);
        aligned_free(project);
    }
}

void log_memory_usage() {
#ifdef _WIN32
    MEMORYSTATUSEX memInfo;
    memInfo.dwLength = sizeof(MEMORYSTATUSEX);
    GlobalMemoryStatusEx(&memInfo);
    printf("Available Physical Memory: %lu KB\n", memInfo.ullAvailPhys / 1024);
#else
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    printf("Max Resident Set Size: %ld KB\n", usage.ru_maxrss);
#endif
}

void test_function(const char *label, void (*f)(Project*), pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);
    Project *project = create_project();

    clock_t start_time = clock();
    f(project);
    clock_t end_time = clock();

    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Test: %s, Time Taken: %.4f seconds\n", label, time_taken);

    free_project(project);

    log_memory_usage();
    pthread_mutex_unlock(mutex);
}

void run_tests() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    test_function("Test 1", [](Project *project) {
        Task *task1 = create_task(3, 20);
        add_task(project, task1);

        Task *task2 = create_task(8, 40);
        add_task(project, task2);
    }, &mutex);

    test_function("Test 2", [](Project *project) {
        for (int i = 0; i < 10; ++i) {
            Task *task = create_task(i % 10, rand() % 100);
            add_task(project, task);
        }
    }, &mutex);

    pthread_mutex_destroy(&mutex);
}

int main() {
    srand(time(NULL));
    run_tests();
    return 0;
}
