import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.Future;

public class AsyncDataStreamer {
    public void streamFromServer(String host, int port) {
        AsynchronousSocketChannel channel = null;

        try {
            channel = AsynchronousSocketChannel.open();
            Future<Void> future = channel.connect(new InetSocketAddress(host, port));
            if (!future.get()) {
                System.out.println("Connection failed.");
                return;
            }

            ByteBuffer buffer = ByteBuffer.allocate(1024); // Adjust size as needed
            future = channel.read(buffer);
            while (!future.isDone());
            buffer.flip();

            // Process data here
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            System.out.println(new String(data));

        } catch (IOException | InterruptedException e) {
            System.err.println("I/O error: " + e.getMessage());
        } finally {
            if (channel != null) {
                try {
                    channel.close();
                } catch (IOException e) {
                    System.err.println("Error closing the socket: " + e.getMessage());
                }
            }
        }
    }

    // Main method for testing
    public static void main(String[] args) {
        AsyncDataStreamer streamer = new AsyncDataStreamer();
        streamer.streamFromServer("example.com", 80); // Replace with actual host and port
    }
}
