        fclose(input_file);
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void process_image_files(const char **file_names, int file_count, const char *output_path, pthread_mutex_t *mutex) {
    pthread_t threads[MAX_THREADS];
    int files_per_thread = (file_count + MAX_THREADS - 1) / MAX_THREADS;

    for (int i = 0; i < MAX_THREADS && i * files_per_thread < file_count; ++i) {
        const char **subset = file_names + i * files_per_thread;
        pthread_create(&threads[i], NULL, image_processing_worker, subset);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}
