#include <string.h>

#define NODE_ALIGNMENT 64
#define NODES_PER_NODE 16
#define DEFAULT_MAX_NODES 1024
#define DEFAULT_MAX_EDGES 8192

typedef struct Node {
    int (*comparator)(const void*, const void*);
    uint32_t weight;
    uint32_t distance;
    uint8_t status;
