} Node;

typedef struct Graph {
    Node* nodes;
    size_t num_nodes;
    size_t max_nodes;
    size_t max_edges;
    size_t edge_count;
} Graph;

void* aligned_malloc(size_t size) {
    void* ptr = malloc(size + NODE_ALIGNMENT - 1);
    if (ptr == NULL) return NULL;
    char* aligned_ptr = (char*)(((uintptr_t)ptr + NODE_ALIGNMENT - 1) & ~(NODE_ALIGNMENT - 1));
    if ((uintptr_t)aligned_ptr < (uintptr_t)ptr + size) {
        free(ptr);
        return NULL;
    }
    return aligned_ptr;
}

void* aligned_realloc(void* ptr, size_t new_size) {
    void* reallocated = aligned_malloc(new_size);
    if (reallocated == NULL) return NULL;

    // Copy data from old memory to new memory
    memcpy(reallocated, ptr, new_size > sizeof(Node) ? sizeof(Node) : new_size);

    free(ptr);
    return reallocated;
}

void verify_node_integrity(Node* node) {
    // Simple integrity check (can be extended as needed)
    if (!node) return;

    for (int i = 0; i < NODES_PER_NODE; ++i) {
        if (node->adj_list[i]) {
            // Check that the adjacent nodes are within valid range
            Node* adj_node = node->adj_list[i];
            if (adj_node == NULL || adj_node->status > 1) {  // Assuming status is a flag, e.g., [0, 1]
                fprintf(stderr, "Integrity check failed for adjacency list\n");
                exit(EXIT_FAILURE);
            }
        }
    }
}

Graph* initialize_graph(size_t max_nodes, size_t max_edges) {
    Graph* graph = (Graph*)aligned_malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->nodes = (Node*)aligned_malloc(max_nodes * sizeof(Node));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    memset(graph->nodes, 0, max_nodes * sizeof(Node)); // Initialize all nodes to zero

    graph->max_nodes = max_nodes;
    graph->max_edges = max_edges;
    graph->num_nodes = 0;
    graph->edge_count = 0;

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < max_nodes; ++i) {
        Node* node = &graph->nodes[i];
        node->weight = rand() % UINT_MAX;
        node->distance = UINT32_MAX;
        node->status = 0;
    }

    return graph;
}

void free_graph(Graph* graph) {
    if (!graph) return;

    aligned_free(graph->nodes);
    aligned_free(graph);
}
