#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALIGNMENT 16

typedef struct Node {
    char operation[5]; // "add", "sub", "mul", "div"
    double operand1;
    double operand2;
    struct Node *left;
    struct Node *right;
} Node;

// Helper function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__GNUC__) || defined(__clang__)
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Function to initialize a node with given operation and operands
Node* create_node(const char *op, double op1, double op2) {
    Node *node = aligned_alloc(ALIGNMENT, sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strncpy(node->operation, op, 4);
    node->operation[4] = '\0';
    node->operand1 = op1;
    node->operand2 = op2;
    node->left = NULL;
    node->right = NULL;

    return node;
}

// Function to free the tree
void free_tree(Node *root) {
    if (root) {
        free_tree(root->left);
        free_tree(root->right);
#if defined(_MSC_VER)
        _aligned_free(root);
#elif defined(__GNUC__) || defined(__clang__)
        free(root);
#endif
    }
}

// Function to verify the integrity of the tree
int verify_tree(Node *node) {
    if (!node) return 1;
    int left_valid = node->left ? verify_tree(node->left) : 1;
    int right_valid = node->right ? verify_tree(node->right) : 1;

    // Check for cycles (naive approach)
    Node *current = node;
    while (current) {
        if (current == node->left || current == node->right) return 0;
        current = current->left ? current->left : current->right;
    }

    return left_valid && right_valid;
}

// Main function to create a tree of nodes
Node* initialize_node_tree(const char *op, double op1, double op2,
                           const char *left_op, double left_op1, double left_op2,
                           const char *right_op, double right_op1, double right_op2) {
    Node *root = create_node(op, op1, op2);
    if (!verify_tree(root)) {
        free_tree(root);
        fprintf(stderr, "Tree integrity check failed\n");
        exit(EXIT_FAILURE);
    }

    root->left = create_node(left_op, left_op1, left_op2);
    root->right = create_node(right_op, right_op1, right_op2);

    if (!verify_tree(root)) {
        free_tree(root);
        fprintf(stderr, "Tree integrity check failed\n");
        exit(EXIT_FAILURE);
    }

    return root;
}

int main() {
    Node *root = initialize_node_tree("add", 10.0, 20.0,
                                      "mul", 2.0, 3.0,
                                      "div", 8.0, 4.0);

    // Example usage
    printf("Root operation: %s\n", root->operation);
    printf("Left operand of root: %.1f\n", root->operand1);
    printf("Right operand of root: %.1f\n", root->operand2);

    free_tree(root);
    return 0;
}
