#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 100 // Example limit: 100 MB
#define ALIGNMENT 32

typedef struct item {
    int key;
    char string[256];
} Item;

typedef union value {
    double num;
    char* str;
} Value;

typedef struct record {
    int data;
    char name[128];
    struct item* dynamic_item;
} Record;

typedef struct node {
    double value;
    struct item* head_item;
} Node;

typedef struct linked_list_node {
    Item item;
    struct linked_list_node* next;
} LinkedListNode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

size_t calculate_aligned_size(size_t size, size_t alignment) {
    return ((size + alignment - 1) / alignment) * alignment;
}

void free_resources(Node* nodes[], int node_count, long* offsets, int keys[], Record* records, int record_count);

int manage_data_allocation(int node_count, Node** nodes_out, long* offsets_out, int* keys_out, Record** records_out, int record_count) {
    pthread_mutex_lock(&lock);

    size_t total_memory = 0;
    const size_t node_size = sizeof(Node*);
    const size_t item_size = sizeof(LinkedListNode);
    const size_t linked_list_node_size = calculate_aligned_size(sizeof(LinkedListNode), ALIGNMENT);

    Node** nodes = aligned_alloc(node_count * node_size, ALIGNMENT);
    if (!nodes) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    long* offsets = aligned_alloc(record_count * sizeof(long), ALIGNMENT);
    if (!offsets) {
        free(nodes);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    int* keys = aligned_alloc(record_count * sizeof(int), ALIGNMENT);
    if (!keys) {
        free(nodes);
        free(offsets);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    Record* records = aligned_alloc(record_count * sizeof(Record), ALIGNMENT);
    if (!records) {
        free(nodes);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    total_memory += node_count * node_size + record_count * (sizeof(long) + sizeof(int) + sizeof(Record));

    for (int i = 0; i < node_count; ++i) {
        nodes[i] = aligned_alloc(sizeof(Node), ALIGNMENT);
        if (!nodes[i]) {
            free_resources(nodes, node_count, offsets, keys, records, record_count);
            pthread_mutex_unlock(&lock);
            return -1;
        }
        total_memory += sizeof(Node);

        LinkedListNode* current_item = NULL;
        for (int j = 0; j < 5; ++j) { // Example: Each Node has a linked list of 5 items
            LinkedListNode* new_item = aligned_alloc(linked_list_node_size, ALIGNMENT);
            if (!new_item) {
                free_resources(nodes, node_count, offsets, keys, records, record_count);
                pthread_mutex_unlock(&lock);
                return -1;
            }

            total_memory += linked_list_node_size;

            new_item->item.key = j;
            snprintf(new_item->item.string, sizeof(new_item->item.string), "Item_%d", j);

            if (current_item) {
                current_item->next = new_item;
            } else {
                nodes[i]->head_item = &new_item->item;
            }

            current_item = new_item;
        }

        // Terminate the linked list
        if (current_item) {
            current_item->next = NULL;
        }
    }

    for (int i = 0; i < record_count; ++i) {
        records[i].dynamic_item = aligned_alloc(sizeof(struct item), ALIGNMENT);
        if (!records[i].dynamic_item) {
            free_resources(nodes, node_count, offsets, keys, records, record_count);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        total_memory += sizeof(struct item);

        records[i].dynamic_item->key = i;
        snprintf(records[i].name, sizeof(records[i].name), "Record_%d", i);
    }

    if (total_memory > MAX_MEMORY_LIMIT) {
        // Free resources from the least recently used items
        for (int i = record_count - 1; i >= 0 && total_memory > MAX_MEMORY_LIMIT; --i) {
            free(records[i].dynamic_item);
            total_memory -= sizeof(struct item);
        }
    }

    *nodes_out = nodes;
    *offsets_out = offsets;
    *keys_out = keys;
    *records_out = records;

    pthread_mutex_unlock(&lock);
    return 0;
}

void free_resources(Node* nodes[], int node_count, long* offsets, int keys[], Record* records, int record_count) {
    for (int i = 0; i < node_count; ++i) {
        LinkedListNode* current = nodes[i]->head_item;
        while (current) {
            LinkedListNode* next = ((LinkedListNode*)current)->next;
            free(current);
            current = next;
        }
        free(nodes[i]);
    }

    free(nodes);
    free(offsets);
    free(keys);
    for (int i = 0; i < record_count; ++i) {
        free(records[i].dynamic_item);
    }
    free(records);
}

// Example of a remote service interaction placeholder
