    printf("[%s] %s\n", ctime(&now), event_description);
}

int initialize_file_metadata(FileManager *manager, int file_id, const void *content_data, size_t content_size) {
    pthread_rwlock_wrlock(&manager->rwlock);

    if (content_size > MAX_CONTENT_SIZE) {
        log_event("Content size exceeds maximum limit.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        FileMetadata **new_files = (FileMetadata **)realloc(manager->files, new_capacity * sizeof(FileMetadata *));
        if (!new_files) {
            log_event("Failed to resize file array.");
            pthread_rwlock_unlock(&manager->rwlock);
            return -1;
        }
        manager->files = new_files;
        manager->capacity = new_capacity;
    }

    FileMetadata *metadata = (FileMetadata *)malloc(sizeof(FileMetadata));
    if (!metadata) {
        log_event("Failed to allocate memory for file metadata.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    metadata->file_id = file_id;
    metadata->content_size = content_size;
    metadata->content = (char *)malloc(content_size);
    if (!metadata->content) {
        free(metadata);
        log_event("Failed to allocate memory for file content.");
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }
    memcpy(metadata->content, content_data, content_size);

    metadata->creation_time = time(NULL);
    metadata->modification_time = metadata->creation_time;
    metadata->access_time = metadata->creation_time;
    metadata->reference_count = 0;

    manager->files[manager->count++] = metadata;

    pthread_mutex_lock(&manager->lock);
    size_t current_memory_usage = (manager->capacity * sizeof(FileMetadata *)) + 
                                  (sizeof(FileMetadata) + content_size) * manager->count;
    if (current_memory_usage > manager->peak_memory_usage) {
        manager->peak_memory_usage = current_memory_usage;
    }
    manager->memory_window[manager->window_index++] = (double)current_memory_usage;
    if (manager->window_index >= 10) manager->window_index = 0;
    pthread_mutex_unlock(&manager->lock);

    log_event("File metadata initialized.");

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

void access_file(FileManager *manager, int file_id) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->files[i]->file_id == file_id) {
            FileMetadata *metadata = manager->files[i];
            metadata->access_time = time(NULL);
            metadata->reference_count++;
            pthread_rwlock_unlock(&manager->rwlock);
            log_event("File accessed.");
            return;
        }
    }

    log_event("File not found during access.");
    pthread_rwlock_unlock(&manager->rwlock);
}

void release_file(FileManager *manager, int file_id) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->files[i]->file_id == file_id) {
            FileMetadata *metadata = manager->files[i];
            metadata->reference_count--;
            if (metadata->reference_count == 0) {
                free(metadata->content);
                free(metadata);
                for (size_t j = i; j < manager->count - 1; ++j) {
                    manager->files[j] = manager->files[j + 1];
                }
                manager->count--;
            }

            pthread_mutex_lock(&manager->lock);
            size_t current_memory_usage = (manager->capacity * sizeof(FileMetadata *)) + 
                                          (sizeof(FileMetadata) + metadata->content_size) * manager->count;
            if (current_memory_usage < manager->peak_memory_usage) {
                manager->peak_memory_usage = current_memory_usage;
            }
            pthread_mutex_unlock(&manager->lock);

            log_event("File released and possibly deallocated.");
            pthread_rwlock_unlock(&manager->rwlock);
            return;
        }
    }

    log_event("File not found during release.");
    pthread_rwlock_unlock(&manager->rwlock);
}

void iterate_files(FileManager *manager) {
    pthread_rwlock_rdlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        FileMetadata *metadata = manager->files[i];
        printf("File ID: %d, Content Size: %zu\n", metadata->file_id, metadata->content_size);
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void free_file_manager(FileManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        release_file(manager, manager->files[i]->file_id);
    }

    free(manager->files);
    pthread_mutex_destroy(&manager->lock);
    pthread_rwlock_destroy(&manager->rwlock);
    free(manager);

    log_event("File manager freed.");
}

int main() {
    FileManager *manager = create_file_manager();
    if (!manager) return 1;

    const char *content = "Sample file content";
    initialize_file_metadata(manager, 1, content, strlen(content));

    access_file(manager, 1);
    release_file(manager, 1);

    iterate_files(manager);
    free_file_manager(manager);

    return 0;
}
```

