#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdalign.h>
#include <pthread.h>

typedef enum { NOT_STARTED, IN_PROGRESS, COMPLETED } TaskStatus;

typedef struct Task {
    TaskStatus status;
    char description[256];
    struct Task* next;
} Task;

typedef struct Module {
    int identifier;
    double value;
    Task* tasks;
} Module;

#define ALIGNMENT 64

void align_malloc(size_t size, void** ptr) {
    void* raw = NULL;
    if (posix_memalign(&raw, ALIGNMENT, size)) {
        perror("Failed to allocate aligned memory");
        exit(EXIT_FAILURE);
    }
    *ptr = raw;
}

Module* create_module(int identifier, double value) {
    Module* module;
    align_malloc(sizeof(Module), (void**)&module);
    module->identifier = identifier;
    module->value = value;
    module->tasks = NULL;
    return module;
}

void add_task_to_module(Module* module, TaskStatus status, const char* description) {
    Task* task;
    align_malloc(sizeof(Task), (void**)&task);
    task->status = status;
    strncpy(task->description, description, sizeof(task->description));
    task->next = module->tasks;
    module->tasks = task;
}

typedef struct ModuleArray {
    Module** modules;
    size_t count;
} ModuleArray;

ModuleArray* create_module_array(size_t initial_size) {
    ModuleArray* array;
    align_malloc(sizeof(ModuleArray), (void**)&array);
    array->count = 0;
    align_malloc(initial_size * sizeof(Module*), (void**)&array->modules);
    return array;
}

void add_module_to_array(ModuleArray* array, Module* module) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 4;
        align_malloc(new_capacity * sizeof(Module*), (void**)&array->modules);
        memcpy(array->modules, array->modules, array->count * sizeof(Module*));
    }
    array->modules[array->count++] = module;
}

void free_module_array(ModuleArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        Task* task = array->modules[i]->tasks;
        while (task) {
            Task* next = task->next;
            align_free(task);
            task = next;
        }
        align_free(array->modules[i]);
    }
    align_free(array->modules);
    align_free(array);
}

void load_and_test_module(const char* label, void (*f)(Module*)) {
    pthread_t threads[10];
    ModuleArray* module_array = create_module_array(4);

    for (int i = 0; i < 5; ++i) {
        Module* module = create_module(i, i * 1.1);
        add_task_to_module(module, NOT_STARTED, "Test Task");
        add_module_to_array(module_array, module);
    }

    printf("Testing module: %s\n", label);

    for (size_t j = 0; j < module_array->count; ++j) {
        Module* module = module_array->modules[j];
        printf("Running test on module ID: %d\n", module->identifier);
        f(module);
        // Reset mocking library
        // blueslip_reset();
    }

    free_module_array(module_array);
}

void sample_test(Module* module) {
    printf("Executing task for module ID: %d\n", module->identifier);
    Task* task = module->tasks;
    while (task) {
        printf("Task status: %d, description: %s\n", task->status, task->description);
        task->status = IN_PROGRESS; // Simulate task progress
        task = task->next;
    }
}

int main() {
    load_and_test_module("Sample Module", sample_test);
    return 0;
}
