```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#define INITIAL_LONG_ARRAY_SIZE 10
#define INITIAL_INT_KEYS_SIZE 10
#define RECORD_INITIAL_CAPACITY 5
#define RESIZE_FACTOR 2

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    size_t offset_count;
    size_t capacity_offsets;
    int *keys;
    size_t key_count;
    size_t capacity_keys;
    record *records;
    size_t record_capacity;
    pthread_mutex_t lock;
} data_manager;

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

data_manager* create_data_manager(size_t offset_size, size_t key_size) {
    data_manager *dm = malloc(sizeof(data_manager));
    if (!dm) handle_error("Failed to allocate data manager");

    dm->offsets = malloc(offset_size * sizeof(long));
    if (!dm->offsets) handle_error("Failed to allocate offsets array");
    dm->offset_count = offset_size;
    dm->capacity_offsets = offset_size;

    dm->keys = malloc(key_size * sizeof(int));
    if (!dm->keys) handle_error("Failed to allocate keys array");
    dm->key_count = key_size;
    dm->capacity_keys = key_size;

    dm->records = malloc(RECORD_INITIAL_CAPACITY * sizeof(record));
    if (!dm->records) handle_error("Failed to allocate records array");
    dm->record_capacity = RECORD_INITIAL_CAPACITY;

    pthread_mutex_init(&dm->lock, NULL);

    return dm;
}

void resize_records_array(data_manager *dm) {
    size_t new_capacity = dm->record_capacity * RESIZE_FACTOR;
    record *new_records = realloc(dm->records, new_capacity * sizeof(record));
    if (!new_records) handle_error("Failed to reallocate records array");
    dm->records = new_records;
    dm->record_capacity = new_capacity;
}

void set_random_values(data_manager *dm, int min_val, int max_val) {
    pthread_mutex_lock(&dm->lock);
    for (size_t i = 0; i < dm->offset_count; ++i) {
        if (i >= dm->record_capacity) resize_records_array(dm);

        int new_value;
        do {
            srand(time(NULL) + i); // Seed with a combination of time and index
            new_value = rand() % (max_val - min_val + 1) + min_val;
        } while ((dm->keys != NULL && memchr(dm->keys, new_value, dm->key_count * sizeof(int))) ||
                 (dm->records != NULL && memcmp(&dm->records[i].value, &new_value, sizeof(int)) == 0));

        dm->records[i].value = new_value;
    }
    pthread_mutex_unlock(&dm->lock);
}

void free_data_manager(data_manager *dm) {
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

void* worker_thread(void *arg) {
    data_manager *dm = (data_manager *)arg;
    set_random_values(dm, 1, 100);
    return NULL;
}

int main(int argc, char **argv) {
    size_t offset_size = INITIAL_LONG_ARRAY_SIZE;
    size_t key_size = INITIAL_INT_KEYS_SIZE;

    if (argc > 1) {
        offset_size = strtoul(argv[1], NULL, 10);
        key_size = (argc > 2) ? strtoul(argv[2], NULL, 10) : key_size;
    }

    data_manager *dm = create_data_manager(offset_size, key_size);

    const int thread_count = 4;
    pthread_t threads[thread_count];

    for (int i = 0; i < thread_count; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, dm)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_data_manager(dm);

    return 0;
}
```

### Key Points:

- **Dynamic Allocation and Resizing**: The code dynamically allocates memory for arrays of `long`, `int`, and a custom `record` structure, with resizing logic to handle capacity overflow.

- **Concurrency Management**: Uses mutexes for thread-safe operations. This is critical when multiple threads modify shared data structures.

- **Random Value Generation**: Ensures unique random values using simple collision avoidance by checking against existing keys and record values.

- **Error Handling**: Handles memory allocation failures with a standardized error handling function, which logs errors and exits the program gracefully.

- **Cleanup**: Properly deallocates all dynamically allocated resources to prevent memory leaks.

This code provides a base for further optimization and adaptation based on specific requirements or performance profiling results.']

