#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int key;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;  // Mutex for thread safety
} LinkedList;

// Function to dynamically allocate and initialize a linked list with specified number of nodes
LinkedList* create_linked_list(int num_nodes, int min_key, int max_key) {
    if (num_nodes <= 0 || min_key >= max_key) return NULL;

    LinkedList *list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    for (int i = 0; i < num_nodes; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            // Clean up previously allocated nodes
            while (list->head != NULL) {
                Node *temp = list->head;
                list->head = list->head->next;
                free(temp);
            }
            pthread_mutex_destroy(&list->lock);
            free(list);
            return NULL;
        }

        new_node->key = min_key + i;  // Initialize with unique key
        new_node->next = list->head;
        list->head = new_node;
    }

    return list;
}

// Function to print the keys in reverse order without modifying the list structure
void print_keys_in_reverse(LinkedList *list) {
    if (!list || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    // Use a stack (array for simplicity)
    int max_nodes = 0;
    while (current) { 
        ++max_nodes;
        current = current->next;
    }

    Node **stack = malloc(max_nodes * sizeof(Node*));
    if (!stack) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle error appropriately in production code
    }

    int top = -1;
    current = list->head;
    while (current) {
        stack[++top] = current;
        current = current->next;
    }

    for (int i = top; i >= 0; --i) {
        printf("%d\n", stack[i]->key);
    }

    free(stack);
    pthread_mutex_unlock(&list->lock);
}

// Function to safely destroy the linked list
void destroy_linked_list(LinkedList *list) {
    if (!list) return;

    Node *current = list->head;
    while (current != NULL) {
        Node *next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    int num_nodes = 10;
    int min_key = 1;
    int max_key = 20;

    LinkedList *list = create_linked_list(num_nodes, min_key, max_key);

    if (list) {
        print_keys_in_reverse(list);
        destroy_linked_list(list);
    } else {
        printf("Failed to initialize the linked list.\n");
    }

    return 0;
}
```

