['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t record_count;
    pthread_mutex_t mutex;
} MemoryManager;

// Function to dynamically allocate and initialize arrays
void initialize_arrays(MemoryManager *manager, size_t offset_size, size_t key_size) {
    pthread_mutex_lock(&manager->mutex);

    // Allocate memory for offsets array
    manager->offsets = (long*)malloc(offset_size * sizeof(long));
    if (!manager->offsets) {
        perror("Failed to allocate offsets");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets array with example values or zeros
    for(size_t i = 0; i < offset_size; ++i)
        manager->offsets[i] = i;

    // Allocate memory for keys array
    manager->keys = (int*)malloc(key_size * sizeof(int));
    if (!manager->keys) {
        perror("Failed to allocate keys");
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize keys array with example values or zeros
    for(size_t i = 0; i < key_size; ++i)
        manager->keys[i] = i;

    pthread_mutex_unlock(&manager->mutex);
}

// Function to initialize record structures
void initialize_records(MemoryManager *manager, size_t initial_count) {
    pthread_mutex_lock(&manager->mutex);

    // Allocate memory for records array
    manager->records = (Record**)malloc(initial_count * sizeof(Record*));
    if (!manager->records) {
        perror("Failed to allocate records");
        free(manager->offsets);
        free(manager->keys);
        exit(EXIT_FAILURE);
    }

    manager->record_count = initial_count;
    for(size_t i = 0; i < initial_count; ++i) {
        manager->records[i] = (Record*)malloc(sizeof(Record));
        if (!manager->records[i]) {
            perror("Failed to allocate record");
            for (size_t j = 0; j < i; ++j)
                free(manager->records[j]);
            free(manager->records);
            free(manager->offsets);
            free(manager->keys);
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to set random values for records
void set_random_values(MemoryManager *manager, int min_value, int max_value) {
    srand(time(NULL));

    pthread_mutex_lock(&manager->mutex);

    for(size_t i = 0; i < manager->record_count; ++i) {
        manager->records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to resize records array
void resize_records(MemoryManager *manager, size_t new_size) {
    pthread_mutex_lock(&manager->mutex);

    Record** temp = realloc(manager->records, new_size * sizeof(Record*));
    if (!temp) {
        perror("Failed to resize records");
        // Handle error by freeing existing resources
        for (size_t i = 0; i < manager->record_count; ++i)
            free(manager->records[i]);
        free(manager->records);
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    for(size_t i = manager->record_count; i < new_size; ++i) {
        temp[i] = (Record*)malloc(sizeof(Record));
        if (!temp[i]) {
            perror("Failed to allocate record during resize");
            // Free newly allocated records
            for (size_t j = manager->record_count; j < i; ++j)
                free(temp[j]);
            break;
        }
    }

    manager->records = temp;
    manager->record_count = new_size;

    pthread_mutex_unlock(&manager->mutex);
}

// Function to cleanup memory and resources
void clean_up(MemoryManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    free(manager->offsets);
    free(manager->keys);

    for(size_t i = 0; i < manager->record_count; ++i)
        free(manager->records[i]);

    free(manager->records);
    pthread_mutex_unlock(&manager->mutex);
}

// Main function to demonstrate the MemoryManager
int main() {
    const size_t offset_size = 10;
    const size_t key_size = 5;
    const size_t initial_record_count = 3;

    MemoryManager manager;
    pthread_mutex_init(&manager.mutex, NULL);

    initialize_arrays(&manager, offset_size, key_size);
    initialize_records(&manager, initial_record_count);

    // Simulate setting random values
    set_random_values(&manager, 0, 100);

    // Resize the records array
    resize_records(&manager, 10);

    // Clean up memory
    clean_up(&manager);
    pthread_mutex_destroy(&manager.mutex);

    return 0;
}
