#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define DEFAULT_LONG_ARRAY_SIZE 1000
#define DEFAULT_INT_ARRAY_SIZE 500
#define DEFAULT_DOUBLE_ARRAY_SIZE 200

typedef struct {
    int key;
    long offset;
    double data;
} Record;

// Global mutex for thread safety
static pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to get environment variable or default value
int get_env_or_default(const char *env_var, int default_value) {
    const char *value_str = getenv(env_var);
    if (value_str) {
        return atoi(value_str);
    }
    return default_value;
}

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

Record* create_record_array(size_t initial_size, int *capacity) {
    Record *array = malloc(initial_size * sizeof(Record));
    if (!array) {
        handle_error("Failed to allocate record array");
    }
    *capacity = (int)initial_size;
    return array;
}

void resize_record_array(Record **array, int *capacity) {
    pthread_mutex_lock(&global_mutex);
    size_t new_capacity = (*capacity) * 2;
    Record *new_array = realloc(*array, new_capacity * sizeof(Record));
    if (!new_array) {
        free(*array);
        handle_error("Failed to resize record array");
    }
    *array = new_array;
    *capacity = (int)new_capacity;
    pthread_mutex_unlock(&global_mutex);
}

void set_random_values(Record *records, int size, int min_key, int max_key, long min_offset, long max_offset, double min_data, double max_data) {
    for (int i = 0; i < size; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].data = ((double)rand() / RAND_MAX) * (max_data - min_data) + min_data;
    }
}

void free_record_array(Record *array) {
    free(array);
}

// Configuration parser
typedef struct {
    int long_array_size;
    int int_array_size;
    int double_array_size;
} Config;

Config parse_config() {
    Config config;
    config.long_array_size = get_env_or_default("LONG_ARRAY_SIZE", DEFAULT_LONG_ARRAY_SIZE);
    config.int_array_size = get_env_or_default("INT_ARRAY_SIZE", DEFAULT_INT_ARRAY_SIZE);
    config.double_array_size = get_env_or_default("DOUBLE_ARRAY_SIZE", DEFAULT_DOUBLE_ARRAY_SIZE);
    return config;
}

// Logging mechanism
void log_message(const char *message) {
    FILE *log_file = fopen("memory_manager.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void stress_test(Record *records, int capacity) {
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))set_random_values, records);
    }
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }
