typedef struct {
    short value;
    char identifier;
    float *dynamic_float;
} record;

typedef struct {
    double a, b, c;  // Coefficients for the polynomial
} PolynomialCoefficients;

// Function prototypes
void log_allocation(const char* operation, size_t size);
PolynomialCoefficients parse_coefficients(const char* filename);
float calculate_polynomial(float index, float key, PolynomialCoefficients coeffs);

// Thread-safe logging mechanism
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void log_allocation(const char* operation, size_t size) {
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    fprintf(log_file, "%s: %zu bytes at %s", operation, size, ctime(&now));
    fflush(log_file);  // Ensure the entry is written immediately
    pthread_mutex_unlock(&log_mutex);
}

PolynomialCoefficients parse_coefficients(const char* filename) {
    PolynomialCoefficients coeffs = {0};
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open coefficients file\n");
        exit(EXIT_FAILURE);
    }

    if (fscanf(file, "%lf %lf %lf", &coeffs.a, &coeffs.b, &coeffs.c) != 3) {
        fprintf(stderr, "Error reading polynomial coefficients\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
    return coeffs;
}

float calculate_polynomial(float index, float key, PolynomialCoefficients coeffs) {
    return (coeffs.a * index * index + coeffs.b * key + coeffs.c);
}

long* allocate_memory(int num_records, int* keys, record** records, long* offsets) {
    if (num_records <= 0 || num_records > 10000) {
        fprintf(stderr, "Invalid number of records\n");
        return NULL;
    }

    log_file = fopen("memory_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        fclose(log_file);
        return NULL;
    }

    log_allocation("Allocation", num_records * sizeof(long));

    *records = (record*)malloc(num_records * sizeof(record));
    if (!(*records)) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        log_allocation("Deallocation", num_records * sizeof(long));
        fclose(log_file);
        return NULL;
    }

    log_allocation("Allocation", num_records * sizeof(record));

    PolynomialCoefficients coeffs = parse_coefficients("coefficients.txt");

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i; // Dummy offset value, could be more complex

        (*records)[i].value = (short)i;
        (*records)[i].identifier = 'A' + (i % 26);

        float *poly_float = malloc(sizeof(float));
        if (!poly_float) {
            fprintf(stderr, "Memory allocation failed for dynamic float in record %d\n", i);
            // Cleanup previously allocated memory
            while (--i >= 0) free((*records)[i].dynamic_float);
            free(*records);
            log_allocation("Deallocation", num_records * sizeof(record));
            free(offsets);
            fclose(log_file);
            return NULL;
        }

        (*records)[i].dynamic_float = poly_float;
        *poly_float = calculate_polynomial((float)i, keys[i], coeffs);

        log_allocation("Allocation", sizeof(float));
    }

    pthread_mutex_unlock(&log_mutex);
    fclose(log_file);

    return offsets;
}

// Example of freeing memory
void free_memory(long* offsets, record* records, int num_records) {
    if (!offsets || !records || num_records <= 0) {
        fprintf(stderr, "Invalid arguments for memory deallocation\n");
        return;
    }

    log_file = fopen("memory_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].dynamic_float);
        log_allocation("Deallocation", sizeof(float));
    }

    free(records);
    log_allocation("Deallocation", num_records * sizeof(record));

    free(offsets);
    log_allocation("Deallocation", num_records * sizeof(long));

    fclose(log_file);
}

// Dummy implementations for serialization/deserialization
void serialize(const char* filename, record* records, int num_records) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(records, sizeof(record), num_records, file);
    fclose(file);
}

void deserialize(const char* filename, record** records, int* num_records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    *num_records = size / sizeof(record);
    *records = (record*)malloc(size);
    fread(*records, sizeof(record), *num_records, file);
    fclose(file);
}

// Example usage
int main() {
    int num_records = 5;
    int keys[] = {1, 2, 3, 4, 5};
    long* offsets = NULL;
    record* records = NULL;

    offsets = allocate_memory(num_records, keys, &records, offsets);
    if (!offsets) return EXIT_FAILURE;

    serialize("backup.bin", records, num_records);

    free_memory(offsets, records, num_records);

    return 0;
}
