#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <errno.h>

#define ALIGNMENT 16
#define MAX_RETRIES 3

// Struct definitions
typedef struct {
    size_t size;
    union {
        double dbl_value;
        char *str_ptr;
    } data;
} Item;

typedef struct {
    int value;
    char identifier[32];
    Item *item;
} Record;

// Function prototypes
void *aligned_alloc(size_t alignment, size_t size);
void free_aligned(void *ptr);
int is_aligned(void *ptr, size_t alignment);
size_t calculate_size(size_t num_elements, size_t element_size);
void log_allocation(const char *message, const void *addr, size_t size, size_t alignment);
void handle_allocation_failure(int retry_count);

// Main function to manage memory allocation and initialization
void manage_memory_and_initialize(int max_records, unsigned int range_min, unsigned int range_max) {
    srand(time(NULL));

    long **long_pointers = aligned_alloc(ALIGNMENT, calculate_size(max_records, sizeof(long*)));
    double *doubles = aligned_alloc(ALIGNMENT, calculate_size(max_records, sizeof(double)));
    struct { char str[64]; unsigned int num; } *struct_objects = aligned_alloc(
        ALIGNMENT, calculate_size(max_records, sizeof(struct { char str[64]; unsigned int num; }))
    );
    int *keys = aligned_alloc(ALIGNMENT, calculate_size(max_records, sizeof(int)));
    Record *records = aligned_alloc(ALIGNMENT, calculate_size(max_records, sizeof(Record)));

    if (!is_aligned(long_pointers, ALIGNMENT) || !is_aligned(doubles, ALIGNMENT) ||
        !is_aligned(struct_objects, ALIGNMENT) || !is_aligned(keys, ALIGNMENT) ||
        !is_aligned(records, ALIGNMENT)) {
        fprintf(stderr, "Memory alignment error.\n");
        return;
    }

    for (int i = 0; i < max_records; ++i) {
        long_pointers[i] = aligned_alloc(ALIGNMENT, sizeof(long));
        if (!long_pointers[i]) handle_allocation_failure(MAX_RETRIES);

        doubles[i] = (double)(rand() % 100);
        strncpy(struct_objects[i].str, "Initialized", sizeof(struct_objects[i].str));
        struct_objects[i].num = rand() % (range_max - range_min + 1) + range_min;

        keys[i] = i;

        records[i].value = rand() % 1000;
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID_%d_%ld", i, time(NULL));
        records[i].item = aligned_alloc(ALIGNMENT, sizeof(Item));

        if (!records[i].item) handle_allocation_failure(MAX_RETRIES);

        records[i].item->size = rand() % 100;
        records[i].item->data.dbl_value = (double)(rand() % 100.0);
    }

    // Log the allocation
    log_allocation("Allocations successful.", long_pointers, calculate_size(max_records, sizeof(long*)), ALIGNMENT);

    // Simulate high-latency environment
    usleep(500000); // 500ms delay

    // Validate data integrity
    for (int i = 0; i < max_records; ++i) {
        if (!is_aligned(records[i].item, ALIGNMENT)) {
            fprintf(stderr, "Data alignment error at record %d.\n", i);
        }
        if (records[i].value < 0 || records[i].value > 1000) {
            fprintf(stderr, "Record value out of range at index %d.\n", i);
        }
    }

    // Cleanup
    for (int i = 0; i < max_records; ++i) {
        free_aligned(long_pointers[i]);
        free_aligned(records[i].item);
    }
    free_aligned(long_pointers);
    free_aligned(doubles);
    free_aligned(struct_objects);
    free_aligned(keys);
    free_aligned(records);
}

// Implementations of helper functions
void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        ptr = NULL;
    }
    return ptr;
}

void free_aligned(void *ptr) {
    free(ptr);
}

int is_aligned(void *ptr, size_t alignment) {
    return ((uintptr_t)ptr % alignment) == 0;
}

size_t calculate_size(size_t num_elements, size_t element_size) {
    return num_elements * element_size;
}

void log_allocation(const char *message, const void *addr, size_t size, size_t alignment) {
    printf("%s: Address=%p, Size=%zu bytes, Alignment=%zu\n", message, addr, size, alignment);
}

void handle_allocation_failure(int retry_count) {
    if (retry_count > 0) {
        fprintf(stderr, "Allocation failed. Retrying...\n");
        usleep(100000); // Retry after 100ms
        handle_allocation_failure(retry_count - 1);
    } else {
        fprintf(stderr, "Critical allocation failure.\n");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <max_records> <range_min> <range_max>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int max_records = atoi(argv[1]);
    unsigned int range_min = atoi(argv[2]);
    unsigned int range_max = atoi(argv[3]);

    manage_memory_and_initialize(max_records, range_min, range_max);
    return 0;
}
