typedef struct item {
    int key;
    char string[11]; // Fixed length alphanumeric string with null terminator
} item;

typedef struct node {
    double value;
    item *items;  // Linked list of items
    int itemCount;
} node;

int log_memory_failure(const char* message) {
    fprintf(stderr, "Memory allocation failed: %s\n", message);
    return -1;
}

void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

void verify_integrity(node *nodes, size_t nodeCount) {
    for (size_t i = 0; i < nodeCount; ++i) {
        if (!nodes[i].value || !nodes[i].items) {
            fprintf(stderr, "Integrity check failed at node %zu\n", i);
            exit(EXIT_FAILURE);
        }
        for (int j = 0; j < nodes[i].itemCount; ++j) {
            if (!nodes[i].items[j].key || !*nodes[i].items[j].string) {
                fprintf(stderr, "Integrity check failed at node %zu item %d\n", i, j);
                exit(EXIT_FAILURE);
            }
        }
    }
}

node* allocate_and_initialize_nodes(size_t nodeCount, int valueRangeMin, int valueRangeMax, size_t alignmentBoundary, FILE *logFile) {
    if (nodeCount > 10000) {
        log_memory_failure("Node count exceeds system limit.");
        return NULL;
    }

    void *mem = aligned_alloc(alignmentBoundary, nodeCount * sizeof(node));
    if (!mem) {
        log_memory_failure("Failed to allocate memory for nodes");
        return NULL;
    }

    node *nodes = (node *)mem;
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < nodeCount; ++i) {
        int randomInt = rand() % (valueRangeMax - valueRangeMin + 1) + valueRangeMin;
        nodes[i].value = sqrt(randomInt);

        size_t itemCount = rand() % 10 + 1; // Random number of items between 1 and 10
        item *items = malloc(itemCount * sizeof(item));
        if (!items) {
            log_memory_failure("Failed to allocate memory for node items");
            free(mem);
            return NULL;
        }

        nodes[i].itemCount = itemCount;
        nodes[i].items = items;

        for (size_t j = 0; j < itemCount; ++j) {
            items[j].key = rand() % 1000000; // Unique integer key
            generate_random_string(items[j].string, sizeof(items[j].string));

            if (logFile) {
                fprintf(logFile, "Node %zu: Double value %.2f, Item %d: Key %d, String %s\n", i, nodes[i].value, j, items[j].key, items[j].string);
            }
        }
    }

    verify_integrity(nodes, nodeCount);

    return nodes;
}

void free_nodes(node *nodes, size_t nodeCount) {
    for (size_t i = 0; i < nodeCount; ++i) {
        if (nodes[i].items) {
            free(nodes[i].items);
        }
    }
    aligned_free(nodes);
}
