    float nf;      // Noise Figure in dB
} UESessionInfo;

// Error codes
typedef enum {
    SUCCESS = 0,
    ERROR_INVALID_SNR_NF_COUNT,
    ERROR_MEMORY_ALLOCATION_FAILURE,
    ERROR_THREAD_SYNC_FAILURE,
    // Add more error codes as needed
} ErrorCode;

// Global variables for logging invalid values
int invalid_snr_count = 0;
int invalid_nf_count = 0;

// Mutex for thread-safe operations
pthread_mutex_t lock;

// Memory pool for efficient allocation
#define POOL_SIZE 1024 * 64 // Example size, adjust as needed
char memory_pool[POOL_SIZE];
size_t next_free_ptr = 0;

void* allocate_from_pool(size_t size) {
    if (next_free_ptr + size > POOL_SIZE) return NULL;
    void* ptr = &memory_pool[next_free_ptr];
    next_free_ptr += size;
    return ptr;
}

ErrorCode initializeUesessionList(UESessionInfo** list, int M) {
    // Initialize mutex
    if (pthread_mutex_init(&lock, NULL) != 0) {
        return ERROR_THREAD_SYNC_FAILURE;
    }

    // Reset invalid counts
    pthread_mutex_lock(&lock);
    invalid_snr_count = 0;
    invalid_nf_count = 0;
    pthread_mutex_unlock(&lock);

    size_t element_size = sizeof(UESessionInfo);
    *list = (UESessionInfo*)allocate_from_pool(M * element_size);
    if (*list == NULL) {
        return ERROR_MEMORY_ALLOCATION_FAILURE;
    }

    for (int i = 0; i < M; ++i) {
        // Simulate or fetch valid ue_id, snr, nf values
        int ue_id = rand(); // Example UE ID generation
        float snr = (float)(rand() % (MIN_SNR - MAX_SNR + 1)) + MAX_SNR;
        float nf = (float)(rand() % (MAX_NF + 1));

        pthread_mutex_lock(&lock);
        if (snr < MAX_SNR || snr > MIN_SNR) {
            invalid_snr_count++;
            snr = MIN_SNR; // Default to minimum valid value
        }
        if (nf < 0 || nf > MAX_NF) {
            invalid_nf_count++;
            nf = 0; // Default to minimum valid value
        }
        pthread_mutex_unlock(&lock);

        (*list)[i].ue_id = ue_id;
        (*list)[i].snr = snr;
        (*list)[i].nf = nf;
    }

    return SUCCESS;
}

void freeUesessionList(UESessionInfo* list) {
    if (list != NULL) {
        // Reset the pool pointer for future allocations
        next_free_ptr = 0;
    }
}

// Example usage and testing functions can be added here

