    UESessionInfo* session_list = NULL;
    ErrorCode result = initializeUesessionList(&session_list, 100);

    if (result != SUCCESS) {
        fprintf(stderr, "Initialization failed with error code: %d\n", result);
        return EXIT_FAILURE;
    }

    // Simulate dynamic adjustment and other operations

    freeUesessionList(session_list);

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
