        nicb->vlan_tag = htons(ETH_P_8021Q | (rand() % 4096));
        nicb->vlan_priority = rand() % 8; // Priority between 0 and 7
        nicb->ip_checksum_calculation_enabled = rand() % 2;

        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        if (pthread_create(&thread_id, NULL, init_nicb, &nicbs[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
