        EVP_PKEY_keygen(pkey_ctx, &pkey_ctx) <= 0) {
        fprintf(stderr, "RSA key generation failed\n");
    }

    EVP_PKEY_assign_RSA(pkey_ctx, RSA_new());
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
    if (EVP_DigestSignInit(md_ctx, NULL, EVP_sha1(), NULL, pkey_ctx) <= 0 ||
        EVP_DigestSignUpdate(md_ctx, "data", strlen("data")) <= 0 ||
        EVP_DigestSignFinal(md_ctx, NULL, &md_ctx) <= 0) {
        fprintf(stderr, "RSA with SHA1 failed\n");
    }

    if (EVP_MD_CTX_init(md_ctx) != 1 ||
        EVP_DigestSignInit(md_ctx, NULL, EVP_sha256(), NULL, pkey_ctx) <= 0 ||
        EVP_DigestSignUpdate(md_ctx, "data", strlen("data")) <= 0 ||
        EVP_DigestSignFinal(md_ctx, NULL, &md_ctx) <= 0) {
        fprintf(stderr, "RSA with SHA256 failed\n");
    }

    pthread_mutex_destroy(&lock);
