#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000
#define IDENTIFIER_RANGE_MIN 1
#define IDENTIFIER_RANGE_MAX 100

typedef struct {
    long timestamp;
    int identifier;
    char status[20];
} Event;

typedef struct {
    Event *events;
    size_t count;
    pthread_mutex_t lock;
} EventCollection;

// Function to initialize the event collection
void init_event_collection(EventCollection *collection, size_t initial_capacity) {
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    // Allocate memory for events
    collection->events = (Event *)malloc(initial_capacity * sizeof(Event));
    if (!collection->events) {
        fprintf(stderr, "Failed to allocate memory for event collection\n");
        exit(EXIT_FAILURE);
    }
}

// Function to add an event to the collection
void add_event(EventCollection *collection, long timestamp, char *status) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_EVENTS) {
        fprintf(stderr, "Event collection is full\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    Event new_event;
    new_event.timestamp = timestamp;
    new_event.identifier = rand() % (IDENTIFIER_RANGE_MAX - IDENTIFIER_RANGE_MIN + 1) + IDENTIFIER_RANGE_MIN;
    snprintf(new_event.status, sizeof(new_event.status), "%s", status);

    collection->events[collection->count++] = new_event;

    pthread_mutex_unlock(&collection->lock);
}

// Function to free the event collection
void free_event_collection(EventCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->events);
    collection->events = NULL;
    collection->count = 0;

    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

// Function to simulate event processing
void process_events(EventCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        // Simulate processing each event
        printf("Processing Event ID: %d, Timestamp: %ld, Status: %s\n",
               collection->events[i].identifier,
               collection->events[i].timestamp,
               collection->events[i].status);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    EventCollection collection;
    init_event_collection(&collection, MAX_EVENTS);

    // Simulate adding events
    for (long i = 0; i < 100; ++i) {
        add_event(&collection, time(NULL), "Active");
    }

    process_events(&collection);

    free_event_collection(&collection);
    return 0;
}
```

