#include <pthread.h>
#include "jni.h"

#define MAX_MEMORY_USAGE 1048576 // Example limit in bytes
#define RECORD_COUNT 100

typedef struct {
    double value;
} Item;

typedef union {
    double dValue;
    char* cValue;
} UnionItem;

struct item {
    UnionItem u;
};

typedef struct {
    int intValue;
    char* identifier;
    struct item* ptrItem;
    void* metadataPtr;
    time_t timestamp;
} Record;

// Function declarations
void initializeRecords(Record** records, size_t count);
int calculateMetadataHash(const Record* record);
void freeMemory(Record** records, size_t count);
void processRecords(Record** records, size_t count);
int compareRecords(const void* a, const void* b);
int filterCriteria(const Record* record);
double aggregateRecords(Record** records, size_t count);

// JNI function to call Java method
JavaVM *jvm;
JNIEnv *env;

JNIEXPORT jint JNICALL Java_ConnectionHandler_connect(JNIEnv *env_, jobject obj) {
    // Implement retry logic and connection handling here...
    return 0; // Placeholder
}

void initializeJNI() {
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    options[0].optionString = "-Djava.class.path=."; // Path to class files

    vm_args.version = JNI_VERSION_1_6;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = 0;

    jint rc = JNI_CreateJavaVM(&jvm, (void**)&env, &vm_args);
    if (rc != JNI_OK) {
        fprintf(stderr, "Failed to create JVM\n");
        exit(1);
    }
}

void initializeRecords(Record** records, size_t count) {
    srand((unsigned int)time(NULL));
    *records = malloc(sizeof(Record) * count);

    for (size_t i = 0; i < count; ++i) {
        (*records)[i].intValue = rand() % 100 + 1;
        asprintf(&(*records)[i].identifier, "rec%d_%ld_%d", i, time(NULL), calculateMetadataHash(&((*records)[i])));

        struct item* newItem = malloc(sizeof(struct item));
        newItem->u.dValue = ((*records)[i].intValue + (double)time(NULL)) / 2.0;
        (*records)[i].ptrItem = newItem;

        // Memory management logic to ensure max memory usage
        size_t usedMemory = sizeof(Record) * (i + 1);
        if (usedMemory > MAX_MEMORY_USAGE) {
            free((*records)[0].identifier);
            free((*records)[0].ptrItem);
            memmove(*records, &((*records)[1]), sizeof(Record) * (count - 1));
            --count;
            --i; // Reevaluate this index
        }
    }

    initializeJNI();
    jclass cls = (*env)->FindClass(env, "ConnectionHandler");
    jmethodID methodId = (*env)->GetStaticMethodID(env, cls, "connect", "()I");

    if (methodId == NULL) {
        fprintf(stderr, "Could not find Java method\n");
        exit(1);
    }

    (*env)->CallStaticIntMethod(env, cls, methodId);

    // Process records: Sorting
    qsort(*records, count, sizeof(Record), compareRecords);

    // Filter and Aggregate based on criteria
    double aggregatedValue = aggregateRecords(records, count);

    printf("Aggregated Value: %f\n", aggregatedValue);
}

int calculateMetadataHash(const Record* record) {
    return (record->intValue ^ ((unsigned long)(record->ptrItem->u.dValue))) & 0xFF;
}

void freeMemory(Record** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free((*records)[i].identifier);
        free((*records)[i].ptrItem);
    }
    free(*records);
}

int compareRecords(const void* a, const void* b) {
    Record* recA = (Record*)a;
    Record* recB = (Record*)b;
    return (recA->intValue - recB->intValue);
}

int filterCriteria(const Record* record) {
    return record->intValue % 2 == 0; // Example: filter even integers
}

double aggregateRecords(Record** records, size_t count) {
    double sum = 0.0;
    int filteredCount = 0;

    for (size_t i = 0; i < count; ++i) {
        if (filterCriteria(&((*records)[i]))) {
            sum += (*records)[i].ptrItem->u.dValue;
            ++filteredCount;
        }
    }

    return filteredCount > 0 ? sum / filteredCount : 0.0;
}

int main() {
    Record* records = NULL;
    initializeRecords(&records, RECORD_COUNT);
    freeMemory(&records, RECORD_COUNT);

    // Shutdown JVM
    if (jvm != NULL) {
        jvm->DestroyJavaVM();
    }

    return 0;
}
```

### Key Points:
- **JNI Integration**: Connects to a Java method for handling network operations.
- **Dynamic Memory Management**: Ensures total memory usage does not exceed the predefined limit by releasing the least recently used records if necessary.
- **Data Processing**: Includes sorting, filtering, and aggregation of records with efficient handling of large datasets.
- **Scalability & Future Extensions**: The design allows easy integration of new record types or processing steps.

Ensure you have Java's `ConnectionHandler` class defined to match the JNI call for network connection management.']

