['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 512
#define CHUNK_SIZE 256
#define ALIGNMENT 32

typedef struct {
    char ip[16]; // IPv4 Address as string
    int port;
    unsigned int connection_timeout; // in milliseconds
    unsigned int reference_count;
    enum { ACTIVE, INACTIVE } status_flag;
} Node;

typedef struct {
    size_t capacity;
    size_t count;
    Node *nodes;
    pthread_mutex_t mutex;
    char **node_group_ids;
    int *node_weights;
} NetworkConfigurator;

// Utility function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

int validate_ip(const char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

int validate_port(int port) {
    return port > 0 && port <= 65535;
}

void free_resources(NetworkConfigurator *config) {
    if (config->nodes) {
        free(config->nodes);
    }
    if (config->node_group_ids) {
        for (size_t i = 0; i < config->count; ++i) {
            free(config->node_group_ids[i]);
        }
        free(config->node_group_ids);
    }
    if (config->node_weights) {
        free(config->node_weights);
    }
    pthread_mutex_destroy(&(config->mutex));
}

int expand_capacity(NetworkConfigurator *config, size_t additional_capacity) {
    size_t new_capacity = config->capacity + additional_capacity;
    Node *new_nodes = aligned_alloc(ALIGNMENT, new_capacity * sizeof(Node));
    if (!new_nodes) return -1;

    memcpy(new_nodes, config->nodes, config->count * sizeof(Node));
    free(config->nodes);
    config->nodes = new_nodes;
    config->capacity = new_capacity;

    char **new_node_group_ids = realloc(config->node_group_ids, new_capacity * sizeof(char*));
    if (!new_node_group_ids) return -1;
    memset(new_node_group_ids + config->count, 0, additional_capacity * sizeof(char*));

    int *new_node_weights = realloc(config->node_weights, new_capacity * sizeof(int));
    if (!new_node_weights) {
        free(new_node_group_ids);
        return -1;
    }
    memset(new_node_weights + config->count, 0, additional_capacity * sizeof(int));

    config->node_group_ids = new_node_group_ids;
    config->node_weights = new_node_weights;

    return 0;
}

int add_node(NetworkConfigurator *config, const char *ip, int port, unsigned int timeout) {
    pthread_mutex_lock(&(config->mutex));

    if (validate_ip(ip) && validate_port(port)) {
        if (config->count >= config->capacity) {
            if (expand_capacity(config, CHUNK_SIZE) != 0) {
                pthread_mutex_unlock(&(config->mutex));
                return -1;
            }
        }

        Node *node = &config->nodes[config->count++];
        strncpy(node->ip, ip, sizeof(node->ip) - 1);
        node->port = port;
        node->connection_timeout = timeout;
        node->reference_count = 0;
        node->status_flag = ACTIVE;

        // Assume unique IDs and weights are generated/assigned here
        config->node_group_ids[config->count - 1] = strdup("group_id");
        config->node_weights[config->count - 1] = rand() % 10 + 1; // Random weight for demo

        pthread_mutex_unlock(&(config->mutex));
        return 0;
    }

    pthread_mutex_unlock(&(config->mutex));
    return -1;
}

void retry_with_backoff(int (*operation)(void*), void *arg, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        if (operation(arg) == 0) {
            return;
        }
        sleep(1 << retries); // Exponential backoff
        ++retries;
    }
}

void initialize_configurator(NetworkConfigurator *config) {
    config->capacity = CHUNK_SIZE;
    config->count = 0;

    config->nodes = aligned_alloc(ALIGNMENT, CHUNK_SIZE * sizeof(Node));
    if (!config->nodes) exit(EXIT_FAILURE);

    config->node_group_ids = malloc(CHUNK_SIZE * sizeof(char*));
    if (!config->node_group_ids) {
        free(config->nodes);
        exit(EXIT_FAILURE);
    }

    config->node_weights = malloc(CHUNK_SIZE * sizeof(int));
    if (!config->node_weights) {
        free(config->nodes);
        free(config->node_group_ids);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&(config->mutex), NULL);
}

void cleanup_configurator(NetworkConfigurator *config) {
    free_resources(config);
}

int main() {
    NetworkConfigurator config;
    initialize_configurator(&config);

    // Example: Add a node
    retry_with_backoff((int (*)(void*)) add_node, (void*) &config, 3);

    cleanup_configurator(&config);
    return 0;
}
```']

