#define ALIGNMENT 64
#define MAX_TEMP 100.0f
#define MIN_TEMP -50.0f

typedef struct {
    uint64_t timestamp;
    float temperature;
    int status; // 1 for OK, 0 for ERROR
} SensorData;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int is_aligned(void* ptr, size_t alignment) {
    return ((uintptr_t)ptr % alignment == 0);
}

SensorData* allocate_sensors(size_t max_sensors) {
    SensorData *sensors = NULL;
    size_t alloc_size = (max_sensors + ALIGNMENT - 1) & ~(ALIGNMENT - 1); // Round up to the nearest multiple of ALIGNMENT
    void *aligned_mem;

    if ((aligned_mem = _aligned_malloc(alloc_size * sizeof(SensorData), ALIGNMENT)) == NULL) {
        log_error("Initial memory allocation failed");
        return NULL;
    }

    sensors = (SensorData *)aligned_mem;
    for (size_t i = 0; i < max_sensors; ++i) {
        if (!is_aligned(&sensors[i], ALIGNMENT)) {
            log_error("Memory misalignment detected");
            free(sensors);
            return NULL;
        }

        sensors[i].timestamp = time(NULL); // Simulated timestamp
        sensors[i].temperature = (float)(rand() % ((int)(MAX_TEMP - MIN_TEMP) + 1) + (int)MIN_TEMP);

        // Simulate sensor reliability check
        sensors[i].status = (rand() % 100 < 95) ? 1 : 0; // 95% chance of status OK

        if (!sensors[i].temperature || !sensors[i].timestamp) { // Handle missing/corrupted data
            log_error("Corrupted or missing sensor data, using defaults");
            sensors[i].temperature = 25.0f;
            sensors[i].status = 1; // Default to OK status
        }
    }

    return sensors;
}

void free_sensors(SensorData *sensors) {
    if (sensors) {
        _aligned_free(sensors);
    }
}
