        pthread_create(&threads[i], NULL, configure_and_process, (void*)&instances[i * total_instances / 4]);
    }

    for (int i = 0; i < 4 && i * total_instances / 4 < total_instances; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&lock);

    for (int i = 0; i < total_instances; ++i) {
        free(instances[i].config.server_config);
    }
    free(instances);

    return 0;
}
