#define ALIGNMENT 1024

typedef enum { ACTIVE, INACTIVE, PENDING } Status;
typedef struct Metric {
    char *type;
    float value;
    struct Metric *next;
} Metric;

typedef struct Connection {
    Status status;
    int bandwidth;
    struct Connection *prev;
    struct Connection *next;
    Metric *metrics_head;
} Connection;

typedef struct NetworkNode {
    Connection *connections_head;
} NetworkNode;

// Utility function to align memory allocation
void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        return NULL;
    }
    return ptr;
}

// Function to create and initialize a network node with connections and metrics
NetworkNode* init_network_node(int num_connections, int num_metrics_per_connection) {
    NetworkNode *node = aligned_alloc(sizeof(NetworkNode), ALIGNMENT);
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for NetworkNode\n");
        return NULL;
    }
    node->connections_head = NULL;

    srand(time(NULL));

    Connection **prev_conn = &node->connections_head;
    for (int i = 0; i < num_connections; ++i) {
        Connection *conn = aligned_alloc(sizeof(Connection), ALIGNMENT);
        if (!conn) {
            fprintf(stderr, "Failed to allocate memory for Connection\n");
            return NULL; // Handle cleanup in real scenario
        }
        conn->status = rand() % 3;
        conn->bandwidth = (rand() % 1000) + 1;
        conn->prev = *prev_conn ? (*prev_conn)->prev : NULL;
        conn->next = NULL;
        conn->metrics_head = NULL;

        Metric **prev_metric = &conn->metrics_head;
        for (int j = 0; j < num_metrics_per_connection; ++j) {
            const char *types[] = {"latency", "throughput", "packet loss"};
            Metric *metric = aligned_alloc(sizeof(Metric), ALIGNMENT);
            if (!metric) {
                fprintf(stderr, "Failed to allocate memory for Metric\n");
                return NULL; // Handle cleanup in real scenario
            }
            metric->type = strdup(types[rand() % 3]);
            metric->value = ((float)rand() / RAND_MAX) * 100.0f;
            metric->next = NULL;

            if (*prev_metric) {
                (*prev_metric)->next = metric;
            }
            *prev_metric = metric;
        }

        if (*prev_conn) {
            (*prev_conn)->next = conn;
        }
        prev_conn = &conn->next;
    }

    return node;
}

