// External libraries
#include "random_lib.h"  // Placeholder for a library providing random number generation
#include "string_lib.h"  // Placeholder for string handling

#define MAX_TASKS 100
#define MAX_OPERATIONS_PER_TASK 50
#define ALIGNMENT 128
#define FLOAT_RANGE_MIN 0.0f
#define FLOAT_RANGE_MAX 1.0f
#define PRIORITY_PRECISION 5

typedef struct Operation {
    int id;
    char *name;
    union {
        struct Operation* next_op;
        long duration;
    } resource_metrics;
} Operation;

typedef struct Task {
    float priority;
    Operation *operations[MAX_OPERATIONS_PER_TASK];
    size_t num_operations;
} Task;

// Binary search tree node for operations
struct BSTNode {
    int id;
    Operation *operation;
    struct BSTNode *left, *right;
};

Task* allocate_tasks(size_t num_tasks);
void free_tasks(Task *tasks[], size_t num_tasks);
Operation* create_operation(int id, char *name, long duration_or_op_ptr);
void initialize_task(Task *task);
int insert_bst(struct BSTNode **root, int id, Operation *operation);
int bst_verify_unique_ids(struct BSTNode *root, int current_id);
void serialize_data(const Task *tasks[], size_t num_tasks);
Task** deserialize_data(const char *data, size_t *num_tasks);
void log_error(const char *message);

// Helper functions
static void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

static double generate_random_float(double min, double max) {
    return min + (rand() / (double)RAND_MAX) * (max - min);
}

Task* allocate_tasks(size_t num_tasks) {
    if (num_tasks > MAX_TASKS) {
        log_error("Number of tasks exceeds maximum limit.");
        return NULL;
    }

    Task **tasks = aligned_alloc(ALIGNMENT, num_tasks * sizeof(Task *));
    if (!tasks) {
        log_error("Failed to allocate memory for task pointers.");
        return NULL;
    }

    for (size_t i = 0; i < num_tasks; ++i) {
        tasks[i] = aligned_alloc(ALIGNMENT, sizeof(Task));
        if (!tasks[i]) {
            free_tasks(tasks, i);
            log_error("Failed to allocate memory for a task.");
            return NULL;
        }
    }

    for (size_t i = 0; i < num_tasks; ++i) {
        initialize_task(tasks[i]);
    }

    return tasks;
}

void free_tasks(Task *tasks[], size_t num_tasks) {
    for (size_t i = 0; i < num_tasks; ++i) {
        for (size_t j = 0; j < tasks[i]->num_operations; ++j) {
            free(tasks[i]->operations[j]->name);
            free(tasks[i]->operations[j]);
        }
        free(tasks[i]);
    }
    free(tasks);
}

Operation* create_operation(int id, char *name, long duration_or_op_ptr) {
    Operation *op = aligned_alloc(ALIGNMENT, sizeof(Operation));
    if (!op) {
        log_error("Failed to allocate memory for an operation.");
        return NULL;
    }

    op->id = id;
    op->name = strdup(name); // Assume string_lib.h provides strndup
    op->resource_metrics.duration = duration_or_op_ptr; // Simplified

    return op;
}

void initialize_task(Task *task) {
    struct BSTNode *root = NULL;

    task->num_operations = rand() % MAX_OPERATIONS_PER_TASK + 1;
    double sum = 0.0;
    for (size_t i = 0; i < task->num_operations; ++i) {
        char name[32];
        snprintf(name, sizeof(name), "Op_%d", i); // Placeholder for dynamic string generation

        int id = rand(); // Unique ID generation
        long resource_metric = rand() % 100; // Simplified metric
        Operation *op = create_operation(id, name, resource_metric);

        if (!op) {
            log_error("Failed to create operation.");
            free_tasks(&task->operations, task->num_operations);
            return;
        }

        sum += generate_random_float(FLOAT_RANGE_MIN, FLOAT_RANGE_MAX);
        if (!insert_bst(&root, id, op)) {
            log_error("Operation ID conflict detected.");
            free(op);
            return;
        }

        task->operations[i] = op;
    }

    task->priority = round(sum / task->num_operations * pow(10, PRIORITY_PRECISION)) / pow(10, PRIORITY_PRECISION);

    if (!bst_verify_unique_ids(root, -1)) {
        log_error("BST verification failed.");
    }
}

int insert_bst(struct BSTNode **root, int id, Operation *operation) {
    if (!*root) {
        *root = aligned_alloc(ALIGNMENT, sizeof(struct BSTNode));
        if (!(*root)) {
            return 0;
        }

        (*root)->id = id;
        (*root)->operation = operation;
        (*root)->left = (*root)->right = NULL;
    } else if (id < (*root)->id) {
        if (!insert_bst(&((*root)->left), id, operation)) {
            return 0;
        }
    } else if (id > (*root)->id) {
        if (!insert_bst(&((*root)->right), id, operation)) {
            return 0;
        }
    } else {
        return 0; // ID conflict
    }

    return 1;
}

int bst_verify_unique_ids(struct BSTNode *root, int current_id) {
    if (!root) return 1;

    if (current_id == root->id || !bst_verify_unique_ids(root->left, current_id) || !bst_verify_unique_ids(root->right, current_id)) {
        log_error("Duplicate operation ID found in BST.");
        return 0;
    }

    return 1;
}

void serialize_data(const Task *tasks[], size_t num_tasks) {
    // Placeholder for serialization logic
}

Task** deserialize_data(const char *data, size_t *num_tasks) {
    // Placeholder for deserialization logic
    return NULL;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
