    for (int i = 0; i < length - 1; ++i) {
        size_t index = rand() % (sizeof(charset) - 1);
        str[i] = charset[index];
    }
    str[length - 1] = '\0';
}

// Function to initialize a node with seed-controlled randomness.
Node* init_node(double initial_value, unsigned int seed) {
