            return node; // Return partially initialized node.
        }

        new_item->key = rand() % 1000;
        size_t identifier_length = 10; // Example length for the unique identifier string.
        new_item->identifier = aligned_alloc(32, identifier_length);

        if (!new_item->identifier) {
            fprintf(stderr, "Memory allocation failed for item identifier.\n");
            free(new_item); // Clean up the allocated item before returning.
            return node;
        }

        init_identifier((char *)new_item->identifier, identifier_length, seed);

        new_item->next = node->items_head; // Insert at head to manage high update frequency efficiently.
        node->items_head = new_item;
    }

    // Verify pointer integrity: Ensure all pointers are set correctly and no uninitialized memory is used.
    Item *current_item = node->items_head;
    while (current_item) {
        if (!current_item->identifier) {
            fprintf(stderr, "Integrity check failed for item identifier.\n");
            break; // Log error and exit loop as the structure integrity is compromised.
        }
        current_item = current_item->next;
    }

    return node;
}

// Function to free a node and all its items.
void free_node(Node *node) {
    if (!node) return;

    Item *current = node->items_head;
    while (current) {
        Item *temp = current;
        current = current->next;
        free(temp->identifier); // Free the dynamically allocated identifier string.
        free(temp);             // Free the item itself.
    }

    free(node); // Finally, free the node itself.
}

