    char *p = (char *)ptr + (alignment - 1);
    p = (char *)((uintptr_t)p & ~(alignment - 1));
    return p;
}

void aligned_free(void *ptr) {
    free(ptr);
}

void initialize_field(FieldNode *field, const char *name, const char *type) {
    strncpy(field->name, name, sizeof(field->name));
    strncpy(field->type, type, sizeof(field->type));
}

void populate_record(Table *table, int key, int field_count) {
    pthread_rwlock_wrlock(&table->lock);
    RecordNode *new_record = (RecordNode *)aligned_malloc(sizeof(RecordNode), 64);
    new_record->key = key;
    new_record->value = hash_value(key);
    new_record->fields = NULL;

    FieldNode *last_field = NULL;
    for (int i = 0; i < field_count; ++i) {
        FieldNode *new_field = (FieldNode *)aligned_malloc(sizeof(FieldNode), 64);
        initialize_field(new_field, "field", "unknown");
        new_field->next = NULL;

        if (last_field == NULL) {
            new_record->fields = new_field;
        } else {
            last_field->next = new_field;
        }
        last_field = new_field;
    }

    new_record->next = table->head;
    table->head = new_record;
    pthread_rwlock_unlock(&table->lock);
}

char *hash_value(int key) {
    static char value[64];
    snprintf(value, sizeof(value), "%d", key);
    return strdup(value);
}

bool validate_table(Table *table) {
    pthread_rwlock_rdlock(&table->lock);
    RecordNode *current = table->head;
    while (current != NULL) {
        if (!current->value || strlen(current->value) == 0) {
            pthread_rwlock_unlock(&table->lock);
            return false;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&table->lock);
    return true;
}

void free_table(Table *table) {
    pthread_rwlock_wrlock(&table->lock);
    RecordNode *current = table->head;
    while (current != NULL) {
        RecordNode *to_free = current;
        current = current->next;

        FieldNode *field_current = to_free->fields;
        while (field_current != NULL) {
            FieldNode *field_to_free = field_current;
            field_current = field_current->next;
            aligned_free(field_to_free);
        }

