#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_NODES 1000
#define MAX_ITEMS_PER_NODE 50
#define ALIGNMENT 64
#define KEY_LENGTH 8
#define STRING_SIZE 32

typedef struct Item {
    int key;
    char string[STRING_SIZE];
    union {
        struct Item* next_item;
        short metadata_short;
    } metadata;
} Item;

typedef struct Node {
    double value;
    Item* items[MAX_ITEMS_PER_NODE];
    size_t item_count;
} Node;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Handle allocation failure
    }
    return ptr;
}

int hash(int key) {
    return key % MAX_NODES;
}

Node* create_node(double value) {
    Node* node = aligned_alloc(ALIGNMENT, sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->item_count = 0;
    memset(node->items, 0, sizeof(Item*) * MAX_ITEMS_PER_NODE);

    return node;
}

Item* create_item(int key, const char* str, short metadata_short) {
    Item* item = aligned_alloc(ALIGNMENT, sizeof(Item));
    if (!item) return NULL;

    item->key = key;
    strncpy(item->string, str, STRING_SIZE);
    item->metadata.metadata_short = metadata_short;

    return item;
}

void insert_item(Node* node, int key, const char* str, short metadata_short) {
    pthread_mutex_lock(&mutex);

    if (node->item_count >= MAX_ITEMS_PER_NODE) {
        fprintf(stderr, "Node is full.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (size_t i = 0; i < node->item_count; ++i) {
        if (node->items[i]->key == key) {
            fprintf(stderr, "Duplicate key found: %d\n", key);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    Item* item = create_item(key, str, metadata_short);
    node->items[node->item_count++] = item;

    pthread_mutex_unlock(&mutex);
}

void serialize(Node* nodes[], size_t node_count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&node_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < node_count; ++i) {
        fwrite(&nodes[i]->value, sizeof(double), 1, file);
        fwrite(&nodes[i]->item_count, sizeof(size_t), 1, file);

        for (size_t j = 0; j < nodes[i]->item_count; ++j) {
            Item* item = nodes[i]->items[j];
            fwrite(&item->key, sizeof(int), 1, file);
            fwrite(item->string, STRING_SIZE, 1, file);
            fwrite(&item->metadata.metadata_short, sizeof(short), 1, file);
        }
    }

    fclose(file);
}

void deserialize(Node* nodes[], size_t node_count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count && i < MAX_NODES; ++i) {
        double value;
        fread(&value, sizeof(double), 1, file);

        nodes[i] = create_node(value);

        size_t item_count;
        fread(&item_count, sizeof(size_t), 1, file);

        for (size_t j = 0; j < item_count && j < MAX_ITEMS_PER_NODE; ++j) {
            int key;
            char str[STRING_SIZE];
            short metadata_short;

            fread(&key, sizeof(int), 1, file);
            fread(str, STRING_SIZE, 1, file);
            fread(&metadata_short, sizeof(short), 1, file);

            insert_item(nodes[i], key, str, metadata_short);
        }
    }

    fclose(file);
}

void free_node(Node* node) {
    for (size_t i = 0; i < node->item_count; ++i) {
        free(node->items[i]);
    }
    free(node);
}

int main() {
    Node* nodes[MAX_NODES] = {NULL};

    // Example usage
    nodes[0] = create_node(1.23);
    insert_item(nodes[0], 123, "example", 456);

    serialize(nodes, 1, "data.bin");
    deserialize(nodes, 1, "data.bin");

    for (size_t i = 0; i < 1; ++i) {
        free_node(nodes[i]);
    }

    return 0;
}
```

