typedef enum {
    INT_TYPE,
    DOUBLE_TYPE,
    CHAR_PTR_TYPE
} DataType;

typedef struct {
    DataType type;
    union {
        int intValue;
        double doubleValue;
        char* charPtrValue;
    } data;
    unsigned long id; // Unique identifier for each object
} Object;

typedef struct {
    Object *objects;
    size_t capacity;
    size_t count;
    double growthFactor;
    size_t memoryUsageLimit;
    size_t currentMemoryUsage;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* initialize_list(size_t initialCapacity, double growthFactor, size_t memoryUsageLimit) {
    if (initialCapacity == 0 || growthFactor <= 1.0 || memoryUsageLimit == 0) {
        return NULL;
    }

    DynamicList *list = (DynamicList *)malloc(sizeof(DynamicList));
    if (!list) {
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    list->growthFactor = growthFactor;
    list->memoryUsageLimit = memoryUsageLimit;
    list->currentMemoryUsage = 0;

    pthread_mutex_init(&list->lock, NULL);
    list->objects = (Object *)malloc(initialCapacity * sizeof(Object));
    if (!list->objects) {
        free(list);
        return NULL;
    }

    return list;
}

size_t calculate_memory_usage(const Object *obj) {
    switch (obj->type) {
        case INT_TYPE: return sizeof(int);
        case DOUBLE_TYPE: return sizeof(double);
        case CHAR_PTR_TYPE: 
            if (obj->data.charPtrValue) {
                return strlen(obj->data.charPtrValue) + 1;
            }
            break;
    }
    return sizeof(unsigned long); // ID size
}

int add_object(DynamicList *list, const Object *newObj) {
    pthread_mutex_lock(&list->lock);

    if (list->currentMemoryUsage + calculate_memory_usage(newObj) > list->memoryUsageLimit) {
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    if (list->count == list->capacity) {
        size_t newCapacity = (size_t)(list->capacity * list->growthFactor);
        Object *newObjects = (Object *)realloc(list->objects, newCapacity * sizeof(Object));
        if (!newObjects) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        list->objects = newObjects;
        list->capacity = newCapacity;
    }

    memcpy(&list->objects[list->count], newObj, sizeof(Object));
    list->objects[list->count].id = ++((unsigned long)rand()); // Assign unique ID
    list->currentMemoryUsage += calculate_memory_usage(&list->objects[list->count]);
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

Object* search_object(DynamicList *list, unsigned long id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->objects[i].id == id) {
            return &list->objects[i];
        }
    }
    return NULL;
}

typedef void (*ProcessObjectFunc)(const Object *);

void iterate_list(DynamicList *list, ProcessObjectFunc processFunc, int forward) {
    pthread_mutex_lock(&list->lock);

    if (forward) {
        for (size_t i = 0; i < list->count; ++i) {
            processFunc(&list->objects[i]);
        }
    } else {
        for (int i = list->count - 1; i >= 0; --i) {
            processFunc(&list->objects[i]);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(DynamicList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->objects[i].type == CHAR_PTR_TYPE && list->objects[i].data.charPtrValue) {
            free(list->objects[i].data.charPtrValue);
        }
    }

    free(list->objects);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
