typedef struct {
    time_t timestamp;
    char status_flag;
    unsigned short version_number;
} Record;

// Function to allocate and initialize arrays
void* allocate_arrays(size_t num_elements, long** offsets, int** keys, float** timestamps) {
    *offsets = (long*)aligned_alloc(64, num_elements * sizeof(long));
    *keys = (int*)aligned_alloc(64, num_elements * sizeof(int));
    *timestamps = (float*)aligned_alloc(64, num_elements * sizeof(float));

    if (!*offsets || !*keys || !*timestamps) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_elements; ++i) {
        (*offsets)[i] = rand() % 10000;
        (*keys)[i] = rand();
        (*timestamps)[i] = (float)(rand() % 1000000) / 100.0f;
    }
}

// Function to generate random numbers within a specified range
int generate_random_number(int min, int max) {
    return min + rand() % (max - min + 1);
}

// Function to allocate and initialize an array of records with unique keys
Record* allocate_records(size_t num_elements, size_t* record_size) {
    Record* records = (Record*)aligned_alloc(64, num_elements * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records with unique keys and offsets
    for (size_t i = 0; i < num_elements; ++i) {
        records[i].timestamp = time(NULL);
        records[i].status_flag = 'A'; // Example status flag
        records[i].version_number = rand() % 100;
    }

    *record_size = sizeof(Record) * num_elements;
    return records;
}

// Function to ensure sum of integers does not exceed a specified limit
void adjust_record_integers(int* keys, size_t num_elements, int max_sum) {
    int current_sum = 0;

    // Calculate initial sum
    for (size_t i = 0; i < num_elements; ++i) {
        current_sum += keys[i];
    }

    if (current_sum > max_sum) {
        int excess = current_sum - max_sum;
        while (excess > 0) {
            for (size_t i = 0; i < num_elements && excess > 0; ++i) {
                if (keys[i] > 1) { // Ensure we don't reduce below minimum
                    keys[i]--;
                    excess--;
                }
            }
        }
    }
}

int main() {
    size_t num_elements;
    printf("Enter the number of elements: ");
    scanf("%zu", &num_elements);

    long* offsets = NULL;
    int* keys = NULL;
    float* timestamps = NULL;

    allocate_arrays(num_elements, &offsets, &keys, &timestamps);

    size_t record_size;
    Record* records = allocate_records(num_elements, &record_size);

    printf("Enter the maximum sum limit for integers: ");
    int max_sum;
    scanf("%d", &max_sum);

    adjust_record_integers(keys, num_elements, max_sum);

    // Example of generating random numbers within a range
    for (size_t i = 0; i < num_elements; ++i) {
        keys[i] = generate_random_number(1, 100); // Adjusted to fit in the sum limit
    }

    // Clean up
    free(offsets);
    free(keys);
    free(timestamps);
    free(records);

    return 0;
}
