    int qos_enabled;
    int encryption_enabled;
    // Additional fields for network settings and performance metrics
} NICB;

// Global variables
NICB *nicb_pool = NULL;
size_t nicb_count = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

// Initialize NICB pool
void initialize_nicb_pool(size_t count) {
    pthread_mutex_lock(&pool_mutex);

    if (nicb_count > 0) {
        free(nicb_pool);
        nicb_count = 0;
    }

    nicb_pool = (NICB *)malloc(count * sizeof(NICB));
    if (!nicb_pool) handle_error("Failed to allocate NICB pool");

    for (size_t i = 0; i < count; ++i) {
        nicb_pool[i].id = i;
        snprintf(nicb_pool[i].name, sizeof(nicb_pool[i].name), "Interface %zu", i);
        nicb_pool[i].link_aggregation_enabled = 0;
        nicb_pool[i].qos_enabled = 0;
        nicb_pool[i].encryption_enabled = 0;
    }

    nicb_count = count;

    pthread_mutex_unlock(&pool_mutex);
}

// Configure NICB settings
void configure_nicb(int id, int link_aggregation, int qos, int encryption) {
    pthread_mutex_lock(&pool_mutex);

    if (id < 0 || id >= nicb_count) {
        handle_error("Invalid NICB ID");
    }

    NICB *nicb = &nicb_pool[id];
    nicb->link_aggregation_enabled = link_aggregation;
    nicb->qos_enabled = qos;
    nicb->encryption_enabled = encryption;

    pthread_mutex_unlock(&pool_mutex);
}

// Monitor and report performance
void monitor_performance() {
    pthread_mutex_lock(&pool_mutex);

    for (size_t i = 0; i < nicb_count; ++i) {
        printf("NICB %zu - Link Aggregation: %d, QoS: %d, Encryption: %d\n",
               i, nicb_pool[i].link_aggregation_enabled,
               nicb_pool[i].qos_enabled, nicb_pool[i].encryption_enabled);
    }

    pthread_mutex_unlock(&pool_mutex);
}

// Example function to simulate hardware-accelerated encryption
void enable_hardware_encryption(int id) {
    pthread_mutex_lock(&pool_mutex);

    if (id < 0 || id >= nicb_count) {
        handle_error("Invalid NICB ID for encryption");
    }

    // Simulate enabling hardware acceleration
    printf("Enabling hardware-accelerated encryption on NICB %d\n", id);

    pthread_mutex_unlock(&pool_mutex);
}

// Logging mechanism (simplified)
void log_operation(const char *operation) {
