#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MEMORY_LIMIT 1024 * 1024 * 100 // 100 MB limit
#define STRING_INIT_VALUE "CONSTANT"
#define MAX_BATCHES 1000

typedef struct {
    size_t size;
    union {
        double dbl_value;
        char *str_value;
        struct item *item_value;
    };
} Payload;

typedef struct {
    size_t batch_id;
    char identifier[32];
    int transaction_ids[10]; // Example fixed size for simplicity
    unsigned long timestamp;
    struct payload *payload_ptr;
} BatchRecord;

typedef struct {
    pthread_mutex_t lock;
    void **int_pointers;
    struct heterogeneous_data_types *data_types;
    BatchRecord *batch_records;
    size_t allocated_memory;
    size_t total_batches;
} DataPipeline;

struct heterogeneous_data_types {
    char *char_str;
    double dbl_num;
    unsigned long timestamp;
};

// Initialize the data pipeline
DataPipeline* initialize_pipeline(size_t num_ints, size_t num_structs) {
    if (num_ints == 0 || num_structs == 0) return NULL;

    DataPipeline *pipeline = malloc(sizeof(DataPipeline));
    if (!pipeline) return NULL;

    pthread_mutex_init(&pipeline->lock, NULL);

    pipeline->int_pointers = calloc(num_ints, sizeof(void*));
    if (!pipeline->int_pointers) {
        free(pipeline);
        return NULL;
    }

    pipeline->data_types = malloc(num_structs * sizeof(struct heterogeneous_data_types));
    if (!pipeline->data_types) {
        free(pipeline->int_pointers);
        free(pipeline);
        return NULL;
    }

    for (size_t i = 0; i < num_structs; ++i) {
        pipeline->data_types[i].char_str = strdup(STRING_INIT_VALUE);
        pipeline->data_types[i].dbl_num = 0.0;
        pipeline->data_types[i].timestamp = time(NULL);

        if (!pipeline->data_types[i].char_str) {
            for (size_t j = 0; j < i; ++j)
                free(pipeline->data_types[j].char_str);
            free(pipeline->int_pointers);
            free(pipeline->data_types);
            free(pipeline);
            return NULL;
        }
    }

    pipeline->batch_records = calloc(MAX_BATCHES, sizeof(BatchRecord));
    if (!pipeline->batch_records) {
        for (size_t i = 0; i < num_structs; ++i)
            free(pipeline->data_types[i].char_str);
        free(pipeline->int_pointers);
        free(pipeline->data_types);
        free(pipeline);
        return NULL;
    }

    pipeline->allocated_memory = sizeof(void*) * num_ints +
                                 sizeof(struct heterogeneous_data_types) * num_structs +
                                 sizeof(BatchRecord) * MAX_BATCHES;

    if (pipeline->allocated_memory > MEMORY_LIMIT) {
        free_batch_records(pipeline, &pipeline->batch_records);
        for (size_t i = 0; i < num_structs; ++i)
            free(pipeline->data_types[i].char_str);
        free(pipeline->int_pointers);
        free(pipeline->data_types);
        free(pipeline);
        return NULL;
    }

    pipeline->total_batches = 0;
    return pipeline;
}

void free_batch_records(DataPipeline *pipeline, BatchRecord **batch_records) {
    for (size_t i = 0; i < MAX_BATCHES && pipeline->total_batches > 0; ++i) {
        if ((*batch_records)[i].payload_ptr) {
            free((*batch_records)[i].payload_ptr);
        }
        (*batch_records)[i].batch_id = 0;
        memset((*batch_records)[i].identifier, 0, sizeof((*batch_records)[i].identifier));
        pipeline->allocated_memory -= sizeof(BatchRecord);
        --pipeline->total_batches;
    }
}

void free_pipeline(DataPipeline *pipeline) {
    if (!pipeline) return;

    pthread_mutex_lock(&pipeline->lock);

    for (size_t i = 0; i < MAX_BATCHES && pipeline->batch_records[i].batch_id != 0; ++i) {
        if (pipeline->batch_records[i].payload_ptr) {
            free(pipeline->batch_records[i].payload_ptr);
        }
    }

    free(pipeline->int_pointers);
    for (size_t i = 0; i < pipeline->total_batches; ++i) {
        free(pipeline->data_types[i].char_str);
    }
    free(pipeline->data_types);
    free(pipeline->batch_records);

    pthread_mutex_unlock(&pipeline->lock);
    pthread_mutex_destroy(&pipeline->lock);

    free(pipeline);
}

