#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define INITIAL_POOL_SIZE 16
#define MAX_POOL_SIZE 512
#define INCREMENT_STEP 16

typedef struct {
    int handle;
    bool in_use;
    time_t last_accessed;
    unsigned int ref_count;
} Resource;

typedef struct {
    Resource *resources;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    size_t head; // For managing lock-free queue
    size_t tail; // For managing lock-free queue
} ResourcePoolManager;

ResourcePoolManager* initialize_resource_pool() {
    ResourcePoolManager *manager = malloc(sizeof(ResourcePoolManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_POOL_SIZE;
    manager->count = 0;
    manager->resources = calloc(manager->capacity, sizeof(Resource));
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond_var, NULL);
    manager->head = 0;
    manager->tail = 0;

    return manager;
}

bool validate_resource(const Resource *resource) {
    // Lightweight validation logic
    return resource->handle != -1; // Example condition for a valid handle
}

void* allocate_resource(ResourcePoolManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    while (true) {
        size_t next_tail = (manager->tail + 1) % manager->capacity;
        if (next_tail == manager->head && manager->count < manager->capacity) {
            // Resize pool
            if (manager->capacity < MAX_POOL_SIZE) {
                size_t new_capacity = manager->capacity + INCREMENT_STEP;
                if (new_capacity > MAX_POOL_SIZE) new_capacity = MAX_POOL_SIZE;

                Resource *new_resources = realloc(manager->resources, new_capacity * sizeof(Resource));
                if (!new_resources) {
                    pthread_mutex_unlock(&manager->mutex);
                    return NULL; // Failed to resize
                }

                manager->capacity = new_capacity;
                manager->resources = new_resources;
            } else {
                pthread_cond_wait(&manager->cond_var, &manager->mutex); // Wait for resource release
                continue;
            }
        }

        size_t index = manager->tail;
        Resource *resource = &manager->resources[index];

        if (!resource->in_use && validate_resource(resource)) {
            resource->in_use = true;
            resource->last_accessed = time(NULL);
            resource->ref_count = 1;
            manager->tail = next_tail;
            manager->count++;
            pthread_mutex_unlock(&manager->mutex);
            return (void*)(resource + 1); // Return pointer past the structure
        }

        if (next_tail != manager->head) {
            manager->tail = next_tail; // Move to next resource in case of invalid
        } else {
            break; // Pool is exhausted or all resources are busy and valid
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL; // No available resource
}

void release_resource(ResourcePoolManager *manager, Resource* resource) {
    if (!resource || !validate_resource(resource)) return;

    pthread_mutex_lock(&manager->mutex);

    resource->in_use = false;
    resource->ref_count--;
    if (resource->ref_count == 0) {
        manager->count--;
        pthread_cond_signal(&manager->cond_var); // Notify waiting threads
    }

    pthread_mutex_unlock(&manager->mutex);
}

void cleanup_resource_pool(ResourcePoolManager *manager) {
    if (!manager) return;
    free(manager->resources);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond_var);
    free(manager);
}
```

This code snippet provides a basic framework for managing a resource pool with dynamic resizing, thread-safe allocation and release of resources using mutexes and condition variables. It incorporates lightweight validation checks and manages concurrent access to the resource pool. The design aims to minimize contention by allowing efficient allocation and expansion, while ensuring that only valid resources are allocated.']

