#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define ALIGNMENT 32
#define NODES_COUNT 10000
#define ITEMS_PER_NODE 1000
#define RANDOM_RANGE_MAX 100000
#define ITEM_STRING_LENGTH 10

typedef struct item {
    int key;
    char string[ITEM_STRING_LENGTH + 1];
    time_t timestamp;
    struct item *next;
} Item;

typedef struct node {
    double value;
    Item *head;
} Node;

pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long long seed = (unsigned long long)time(NULL);

void* aligned_alloc(size_t alignment, size_t size);
size_t total_reallocations = 0;
double total_time_spent = 0.0;

// Function to ensure memory allocation is aligned
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

// Function to generate a thread-safe random integer
int thread_safe_rand_int() {
    pthread_mutex_lock(&rand_lock);
    seed = seed * 6364136223846793005ULL + 1;
    int result = (int)(seed >> 33) % RANDOM_RANGE_MAX;
    pthread_mutex_unlock(&rand_lock);
    return result;
}

// Function to generate a random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for the null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    }
}

// Main function to allocate and initialize nodes
Node** manage_nodes_and_items(size_t *allocated_count, double *average_time_per_allocation) {
    Node **nodes = aligned_alloc(ALIGNMENT, NODES_COUNT * sizeof(Node*));
    if (!nodes) return NULL;

    for (size_t i = 0; i < NODES_COUNT; ++i) {
        Node *node = aligned_alloc(ALIGNMENT, sizeof(Node));
        if (!node) break;

        double start_time = clock() / (double)CLOCKS_PER_SEC;
        node->value = sqrt(thread_safe_rand_int());
        node->head = NULL;
        Item *current_item = NULL;

        for (size_t j = 0; j < ITEMS_PER_NODE; ++j) {
            Item *item = aligned_alloc(ALIGNMENT, sizeof(Item));
            if (!item) break;

            item->key = j + 1;
            generate_random_string(item->string, ITEM_STRING_LENGTH);
            item->timestamp = time(NULL);

            // Before writing to the node's linked list
            if (current_item == NULL) {
                node->head = item;
                current_item = item;
            } else {
                current_item->next = item;
                current_item = item;
            }
        }

        double end_time = clock() / (double)CLOCKS_PER_SEC;
        total_reallocations++;
        total_time_spent += (end_time - start_time);

        nodes[i] = node;
    }

    *allocated_count = NODES_COUNT;
    if (*allocated_count > 0) {
        *average_time_per_allocation = total_time_spent / *allocated_count;
    } else {
        *average_time_per_allocation = 0.0;
    }

    // Return nodes for verification
    return nodes;
}

// Function to free allocated memory
void free_nodes(Node **nodes, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (!nodes[i]) continue;

        Item *current_item = nodes[i]->head;
        while (current_item) {
            Item *temp = current_item;
            current_item = current_item->next;
            free(temp);
        }
        free(nodes[i]);
    }
    free(nodes);
}
