typedef struct {
    long* long_ptr;
    int value;
} record;

void initialize_random() {
    srand(time(NULL));
}

int safe_malloc(void **ptr, size_t size) {
    *ptr = malloc(size);
    return (*ptr != NULL);
}

void free_memory(long** offsets, int** keys, record** records) {
    if (offsets && *offsets) free(*offsets);
    if (keys && *keys) free(*keys);
    if (records && *records) free(*records);
}

int manage_memory(int size_offsets, int size_keys, int max_mem_bytes, int rand_min, int rand_max, record*** records_out) {
    initialize_random();

    if (size_offsets < 0 || size_keys < 0 || max_mem_bytes <= 0 ||
        rand_min >= rand_max || *records_out == NULL) return -1;

    long* offsets;
    int* keys;

    // Calculate memory usage
    size_t mem_used = sizeof(long) * size_offsets + sizeof(int) * size_keys + sizeof(record) * size_offsets;

    if (mem_used > max_mem_bytes) {
        fprintf(stderr, "Exceeded maximum memory limit\n");
        return -1;
    }

    if (!safe_malloc((void**)&offsets, mem_used)) goto cleanup;

    for (int i = 0; i < size_offsets; ++i) {
        offsets[i] = i * 100 + rand() % 100;
    }

    int* keys_start_ptr = (int*)((char*)offsets + sizeof(long) * size_offsets);

    if (!safe_malloc((void**)&keys, mem_used - sizeof(long) * size_offsets)) goto cleanup;

    for (int i = 0; i < size_keys; ++i) {
        keys[i] = i * 5 + rand() % 5;
    }

    record* records_start_ptr = (record*)((char*)keys + sizeof(int) * size_keys);

    if (!safe_malloc((void**)&records_start_ptr, mem_used - sizeof(long) * size_offsets - sizeof(int) * size_keys)) goto cleanup;

    for (int i = 0; i < size_offsets; ++i) {
        records_start_ptr[i].long_ptr = &offsets[i];
        records_start_ptr[i].value = keys[i] + rand() % (rand_max - rand_min + 1);
    }

    // Update int values with new random values ensuring no two consecutive are the same
    int last_value = -2;
    for (int i = 0; i < size_offsets; ++i) {
        int value;
        do {
            value = rand() % (rand_max - rand_min + 1) + rand_min;
        } while (value == last_value);
        records_start_ptr[i].value = value;
        last_value = value;
    }

    *records_out = &records_start_ptr;

    return 0;

cleanup:
    free_memory(&offsets, &keys, (record***)&records_start_ptr);
    return -1;
}

int main() {
    int size_offsets = 100;
    int size_keys = 100;
    int max_mem_bytes = 1024 * 1024; // 1MB
    int rand_min = 10;
    int rand_max = 50;

    record** records = NULL;
    if (manage_memory(size_offsets, size_keys, max_mem_bytes, rand_min, rand_max, &records) == 0) {
        printf("Memory management successful\n");

        // Process the records if needed

        free_memory(NULL, NULL, records);
    } else {
        printf("Failed to manage memory\n");
    }

    return 0;
}
