#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_KEY_LENGTH 16
#define MAX_OFFSETS 10
#define OFFSET_THRESHOLD 5000

typedef struct {
    long offsets[MAX_OFFSETS];
    int valid_offsets;
} ResourceRecord;

typedef struct {
    ResourceRecord *records;
    size_t record_count;
    long cumulative_sum_of_offsets;
} RecordCollection;

int validate_key(const char *key) {
    if (strlen(key) > MAX_KEY_LENGTH)
        return 0; // Key too long
    for (size_t i = 0; key[i] != '\0'; ++i) {
        if (!((key[i] >= 'a' && key[i] <= 'z') ||
              (key[i] >= 'A' && key[i] <= 'Z') ||
              (key[i] >= '0' && key[i] <= '9') ||
              strchr("!@#$%^&*()-_=+", key[i]))) {
            return 0; // Invalid character
        }
    }
    return 1;
}

void initialize_offsets(ResourceRecord *record) {
    long sum = 0;
    for (int i = 0; i < MAX_OFFSETS && sum <= OFFSET_THRESHOLD;) {
        long random_value = rand() % 1001;
        if (sum + random_value > OFFSET_THRESHOLD)
            break;
        record->offsets[i] = random_value;
        sum += random_value;
        ++i;
    }
    record->valid_offsets = i;
}

RecordCollection *create_record_collection(int max_records, int *keys, const char **key_strings) {
    if (!keys || !key_strings)
        return NULL;

    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    collection->records = (ResourceRecord *)calloc(max_records, sizeof(ResourceRecord));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        free(collection);
        return NULL;
    }

    size_t record_count = 0;
    long cumulative_sum_of_offsets = 0;

    for (int i = 0; i < max_records && keys[i] != -1; ++i) {
        if (!validate_key(key_strings[i])) {
            fprintf(stderr, "Invalid key: %s\n", key_strings[i]);
            continue;
        }

        strncpy(collection->records[record_count].key, key_strings[i], MAX_KEY_LENGTH);
        collection->records[record_count].key[MAX_KEY_LENGTH] = '\0';
        initialize_offsets(&collection->records[record_count]);

        cumulative_sum_of_offsets += 0;
        for (int j = 0; j < collection->records[record_count].valid_offsets; ++j) {
            cumulative_sum_of_offsets += collection->records[record_count].offsets[j];
        }

        record_count++;
    }

    collection->record_count = record_count;
    collection->cumulative_sum_of_offsets = cumulative_sum_of_offsets;

    return collection;
}

void free_record_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}

// Example of garbage collection mechanism, simplistic approach
void garbage_collect(RecordCollection *collection) {
    // In practice, this would involve more sophisticated memory management.
    // Here it's just a placeholder to illustrate where such logic might go.

    // This could include freeing unused records if they are no longer needed,
    // or reorganizing memory to reduce fragmentation.
}

// Unit tests and further implementation details would be added here

int main() {
    int keys[] = {1, 2, -1}; // Last entry as sentinel
    const char *key_strings[] = {"validKey1", "invalid@Key!", NULL};

    RecordCollection *collection = create_record_collection(3, keys, key_strings);

    if (collection) {
        printf("Number of records: %zu\n", collection->record_count);
        printf("Cumulative sum of offsets: %ld\n", collection->cumulative_sum_of_offsets);

