#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_USAGE 500 * 1024 // 500 KB

typedef struct {
    unsigned int seed;
    int value_range_min;
    int value_range_max;
} InitConfig;

typedef struct {
    size_t max_memory_usage;
    double performance_threshold; // Example metric, could be time or other
} Config;

typedef struct {
    int key;
    int value;
} Record;

// Function to initialize random number generator
void init_random(unsigned int seed) {
    srand(seed);
}

// Function to generate a random integer within a range
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Logging function for resource usage and performance metrics
void log_usage(size_t allocated_memory, double performance_metric) {
    printf("Allocated Memory: %zu bytes\n", allocated_memory);
    printf("Performance Metric: %.2f\n", performance_metric);
}

// Function to manage dynamic memory allocation for an array of records
Record* allocate_and_initialize_records(unsigned int n, InitConfig* init_config, Config* config) {
    if (n == 0 || init_config == NULL) return NULL;

    // Calculate the size of each record and total required memory
    size_t record_size = sizeof(Record);
    size_t total_memory_needed = n * record_size;

    // Check against maximum allowed memory usage
    size_t max_allowed_memory = config ? config->max_memory_usage : MAX_MEMORY_USAGE;
    if (total_memory_needed > max_allowed_memory) {
        fprintf(stderr, "Error: Memory requirement exceeds limit\n");
        return NULL;
    }

    // Allocate memory for the records array
    Record* records = (Record*)malloc(total_memory_needed);
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize random number generator with provided seed
    init_random(init_config->seed);

    clock_t start_time = clock();

    // Populate the records array with random keys and values
    for (unsigned int i = 0; i < n; ++i) {
        records[i].key = random_int(1, 100); // Example key range
        records[i].value = random_int(init_config->value_range_min, init_config->value_range_max);
    }

    clock_t end_time = clock();
    double performance_metric = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    if (config && performance_metric > config->performance_threshold) {
        fprintf(stderr, "Warning: Performance threshold exceeded\n");
    }

    // Log usage and performance metrics
    log_usage(total_memory_needed, performance_metric);

    return records;
}

// Function to free allocated memory for the records array
void free_records(Record* records) {
    if (records) {
        free(records);
    }
}
```

### Rationale:
- **Memory Management**: The function checks the required memory against a maximum limit and logs errors when allocation fails.
- **Random Initialization**: Uses `srand` for reproducible random number generation, ensuring values fall within specified ranges.
- **Performance Logging**: Tracks time taken to initialize records and logs it alongside memory usage.
- **Error Handling**: Ensures that if any allocation or initialization step fails, appropriate error messages are logged.
- **Configurable Limits**: Allows optional configuration struct to specify custom limits for memory and performance thresholds.']

