#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB

typedef struct {
    int value;
} record;

typedef struct {
    long rand_seed;
    int range_min, range_max;
} RandomContext;

void* allocateAndInitializeRecords(int num_records, int key_range_min, int key_range_max,
                                   long offset_range_min, long offset_range_max,
                                   RandomContext *rand_ctx) {
    // Calculate total required memory
    size_t record_size = sizeof(record);
    size_t total_memory = 3 * num_records * sizeof(long) + num_records * (record_size + sizeof(int));

    if (total_memory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory allocation exceeds limit\n");
        return NULL;
    }

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * record_size);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(rand_ctx->rand_seed);

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (offset_range_max - offset_range_min + 1) + offset_range_min;
        keys[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;

        records[i].value = rand() % (rand_ctx->range_max - rand_ctx->range_min + 1) + rand_ctx->range_min;
    }

    free(offsets);
    free(keys);

    return records;
}
