```javascript
function copyBufferData(chunks, numBytesToCopy) {
    const copiedData = Buffer.alloc(numBytesToCopy);

    let totalCopied = 0;

    for (let chunk of chunks) {
        if (!chunk || !Buffer.isBuffer(chunk)) continue;

        const bytesAvailableInChunk = chunk.length - totalCopied;
        const bytesToCopyFromThisChunk = Math.min(bytesAvailableInChunk, numBytesToCopy - totalCopied);

        if (bytesToCopyFromThisChunk > 0) {
            chunk.copy(copiedData, totalCopied, totalCopied, totalCopied + bytesToCopyFromThisChunk);
            totalCopied += bytesToCopyFromThisChunk;
        }

        if (totalCopied >= numBytesToCopy) break;
    }

    return copiedData.slice(0, totalCopied);
}
