```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FSCBS 1000

typedef enum { DISABLED, ENABLED } Bool;
typedef enum { ALGO_MD5, ALGO_SHA1, ALGO_SHA256 } HashAlgorithm;

typedef struct {
    char filename[256];
    size_t block_size;
    size_t hash_size;
    HashAlgorithm algo;
} IntegrityPolicy;

typedef struct {
    char name[256];
    Bool is_directory;
    Bool is_symlink;
    IntegrityPolicy policy;
    unsigned char *data; // Example data field
    size_t data_length;
} FSCB;

FSCB fscb_array[MAX_FSCBS];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_fscbs() {
    for (int i = 0; i < MAX_FSCBS; ++i) {
        snprintf(fscb_array[i].name, sizeof(fscb_array[i].name), "file_%d", i);
        fscb_array[i].is_directory = (i % 10 == 0);
        fscb_array[i].is_symlink = (i % 15 == 0);

        if (fscb_array[i].is_directory) {
            fscb_array[i].policy.algo = DISABLED;
        } else {
            fscb_array[i].policy.algo = ALGO_SHA256; // Default algorithm
            fscb_array[i].policy.block_size = 4096;
            fscb_array[i].policy.hash_size = 32; // SHA-256 hash size in bytes
        }

        fscb_array[i].data_length = fscb_array[i].policy.block_size * ((i % 5) + 1);
        fscb_array[i].data = (unsigned char *)malloc(fscb_array[i].data_length);

        if (!fscb_array[i].data) {
            fprintf(stderr, "Memory allocation failed for FSCB %d\n", i);
            exit(EXIT_FAILURE);
        }

        memset(fscb_array[i].data, i, fscb_array[i].data_length); // Example data initialization
    }
}

void perform_integrity_checks() {
    for (int i = 0; i < MAX_FSCBS; ++i) {
        if (!fscb_array[i].is_directory && !fscb_array[i].policy.algo == DISABLED) {
            pthread_mutex_lock(&lock);

            // Simulate integrity check
            printf("Checking integrity for %s using algorithm %d\n", fscb_array[i].name, fscb_array[i].policy.algo);

            pthread_mutex_unlock(&lock);
        }
    }
}

void log_event(const char *message) {
    static int event_count = 0;

    pthread_mutex_lock(&lock);
    printf("Event %d: %s\n", ++event_count, message);
    pthread_mutex_unlock(&lock);
}

int main() {
    initialize_fscbs();
    perform_integrity_checks();
    log_event("Integrity check completed successfully");

    for (int i = 0; i < MAX_FSCBS; ++i) {
        free(fscb_array[i].data);
    }

    return 0;
}
```

### Key Points:

1. **FSCB Initialization**: Each FSCB is initialized with a name, type flags (`is_directory`, `is_symlink`), and an integrity policy including algorithm selection, block size, and hash size.

2. **Integrity Checks**: Simulated integrity checks are performed using mutex locks to ensure thread safety, demonstrating how operations can be synchronized in a multi-threaded context.

3. **Logging Mechanism**: A simple logging function records events with a counter protected by a mutex for thread safety.

4. **Memory Management**: Memory is allocated dynamically for each FSCB data field and freed at the end of the program to prevent memory leaks.

This code provides a foundational structure that fulfills the given requirements, including handling large arrays, supporting dynamic integrity policies, and ensuring efficient performance with multi-threading capabilities.']

