typedef struct {
    double value;
} DoubleValue;

typedef struct {
    int id;
    char name[64];
    DoubleValue *double_ptr;
    long **long_ptr_array;
    double *double_values;
    char **char_arrays;
    size_t num_records;
} Record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0)
        return NULL;
    return ptr;
}

bool check_memory_limit(size_t required_size) {
    // Assume a predefined memory limit for demonstration purposes
    const size_t MEMORY_LIMIT = 1024 * 1024 * 512; // 512 MB
    static size_t current_usage = 0;

    if (current_usage + required_size > MEMORY_LIMIT)
        return false;

    current_usage += required_size;
    return true;
}

void release_memory(Record *record) {
    free(record->double_ptr);
    for(size_t i = 0; i < record->num_records; ++i) {
        free(record->long_ptr_array[i]);
        free(record->char_arrays[i]);
    }
    free(record->long_ptr_array);
    free(record->double_values);
    free(record->char_arrays);
}

bool serialize_record(const Record *record, FILE *file) {
    if (!fwrite(&record->num_records, sizeof(size_t), 1, file)) {
        log_error("Failed to write record count");
        return false;
    }

    for (size_t i = 0; i < record->num_records; ++i) {
        if (!fwrite(record->long_ptr_array[i], sizeof(long*), 1, file) ||
            !fwrite(record->double_values + i, sizeof(double), 1, file)) {
            log_error("Failed to write record data");
            return false;
        }
    }

    for (size_t i = 0; i < record->num_records; ++i) {
        if (!fputs(record->char_arrays[i], file)) {
            log_error("Failed to write char array");
            return false;
        }
    }

    return true;
}

bool deserialize_record(Record *record, FILE *file) {
    size_t num_records;
    if (fread(&num_records, sizeof(size_t), 1, file) != 1 ||
        !check_memory_limit(num_records * (sizeof(long*) + sizeof(double) + 64))) {
        log_error("Failed to read record count or exceeded memory limit");
        return false;
    }

    record->num_records = num_records;
    record->long_ptr_array = aligned_alloc(32, num_records * sizeof(long*));
    record->double_values = aligned_alloc(64, num_records * sizeof(double));
    record->char_arrays = aligned_alloc(64, num_records * sizeof(char*));

    for (size_t i = 0; i < num_records; ++i) {
        long **temp_long_ptr = malloc(sizeof(long*)); // Temporary allocation
        if (!temp_long_ptr) return false;

        double temp_double;
        char buffer[65]; // Extra space for null terminator

        if (!fread(temp_long_ptr, sizeof(long*), 1, file) ||
            !fread(&temp_double, sizeof(double), 1, file) ||
            !fgets(buffer, 65, file)) {
            log_error("Failed to read record data");
            release_memory(record);
            return false;
        }

        *temp_long_ptr = NULL; // Placeholder for demonstration
        *(record->long_ptr_array + i) = temp_long_ptr;
        *(record->double_values + i) = temp_double;
        buffer[64] = '\0'; // Ensure null termination
        *(record->char_arrays + i) = strdup(buffer);
    }

    return true;
}

void manage_record_lifecycle(Record *record, const char* file_path) {
    FILE *file = fopen(file_path, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        release_memory(record);
        return;
    }

    if (serialize_record(record, file)) {
        fclose(file);
        file = fopen(file_path, "rb");
        if (file && deserialize_record(record, file)) {
            printf("Record successfully serialized and deserialized\n");
        } else {
            log_error("Deserialization failed after serialization succeeded");
        }
    } else {
        log_error("Serialization failed");
    }

    fclose(file);
    release_memory(record);
}

void* async_data_fetch(void *arg) {
    // Simulate fetching data asynchronously
    sleep(1); // Placeholder for actual API call
    printf("Data fetched\n");

    return NULL;
}

int main() {
    Record record = {0};

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, async_data_fetch, &record);
    pthread_join(thread_id, NULL);

    manage_record_lifecycle(&record, "data.bin");

    return 0;
}
