}

TablePointer* initialize_database(int num_records, int num_fields_per_record, int compress) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    TablePointer* table = aligned_alloc(sizeof(TablePointer));
    if (!table) return NULL;

    RecordNode* prev_record = NULL;
    for (int i = 0; i < num_records; ++i) {
        RecordNode* record = aligned_alloc(sizeof(RecordNode));
        if (!record) continue;

        record->key = i;
        char value_buffer[128];
        snprintf(value_buffer, sizeof(value_buffer), "Value_%u", simple_hash(i));

        record->value = compress ? compress_string(value_buffer) : strdup(value_buffer);
        if (!record->value) {
            free(record);
            continue; // Skip this record due to allocation failure
        }

        FieldNode* prev_field = NULL;
        for (int j = 0; j < num_fields_per_record; ++j) {
            FieldNode* field = aligned_alloc(sizeof(FieldNode));
            if (!field) continue;

            char* name = aligned_alloc(16 * sizeof(char));
            snprintf(name, 16, "Field_%d", j);
            field->name = name;

            field->type = (DataType)rand() % 3; // Random type
            field->description = aligned_alloc(32 * sizeof(char));
            snprintf(field->description, 32, "Description for Field_%d", j);

            field->next = NULL;
            if (!prev_field) {
                record->fields = field;
            } else {
                prev_field->next = field;
            }
            prev_field = field;
        }

        if (prev_record) {
            prev_record->next = record;
        } else {
            table->head = record;
        }
        prev_record = record;
    }

    pthread_mutex_destroy(&lock);
    return table;
}

void verify_database_integrity(TablePointer* table) {
    RecordNode* current = table->head;
    while (current) {
        if (!current->key || !current->value || !current->fields) {
            fprintf(stderr, "Data integrity issue in record with key %d\n", current->key);
        }
        FieldNode* field = current->fields;
        while (field) {
            if (!field->name || !field->description) {
                fprintf(stderr, "Data integrity issue in field of record with key %d\n", current->key);
            }
            field = field->next;
        }
        current = current->next;
    }
}

void* test_wrapper(void* args) {
    struct TestArgs {
        char* label;
        void (*test_func)(TablePointer*);
        int compress;
    };

    struct TestArgs* ta = (struct TestArgs*)args;

    TablePointer* db = initialize_database(10, 5, ta->compress);
    if (!db) {
        fprintf(stderr, "Test %s failed: Database initialization error\n", ta->label);
        return NULL;
    }

    verify_database_integrity(db);

    pthread_mutex_t blueslip_lock;
    pthread_mutex_init(&blueslip_lock, NULL);
    pthread_mutex_lock(&blueslip_lock);

    printf("Running test: %s\n", ta->label);
    ta->test_func(db);

    pthread_mutex_unlock(&blueslip_lock);
    pthread_mutex_destroy(&blueslip_lock);

    // Free allocated memory here
    return NULL;
}

void run_test(char* label, void (*f)(TablePointer*), int compress) {
    struct TestArgs args = {label, f, compress};

    pthread_t thread;
    if (pthread_create(&thread, NULL, test_wrapper, &args)) {
        fprintf(stderr, "Error creating test thread\n");
    }
    pthread_join(thread, NULL);
}

void example_test(TablePointer* db) {
    // Example test function
    RecordNode* current = db->head;
    while (current) {
        printf("Record key: %d, value: %s\n", current->key, current->value);
        FieldNode* field = current->fields;
        while (field) {
            printf("\tField name: %s, type: %d, description: %s\n",
                field->name, field->type, field->description);
            field = field->next;
        }
        current = current->next;
    }
}

int main() {
    run_test("Test 1", example_test, 0);
    run_test("Test 2 with compression", example_test, 1);

    return 0;
}
