void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Memory allocation with alignment
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr;
    if ((intptr_t)posix_memalign(&ptr, alignment, size)) {
        log_error("Memory allocation failed.");
        return NULL;
    }
    return ptr;
}

// Thread-safe initialization function
int initialize_data(long num_elements, long min_offset, long max_offset,
                    int min_key, int max_key, int min_record_value, int max_record_value,
                    const int* external_keys) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory with alignment
    long *offsets = aligned_alloc(16, num_elements * sizeof(long));
    int *keys = aligned_alloc(16, num_elements * sizeof(int));
    Record *records = aligned_alloc(16, num_elements * sizeof(Record));

    if (!offsets || !keys || !records) {
        log_error("Failed to allocate memory.");
        return -1;
    }

    // Initialize data
    pthread_mutex_lock(&mutex);

    for (long i = 0; i < num_elements; ++i) {
        offsets[i] = min_offset + rand() % (max_offset - min_offset + 1);

        if (external_keys && external_keys[i] >= min_key && external_keys[i] <= max_key) {
            keys[i] = external_keys[i];
        } else {
            keys[i] = min_key + rand() % (max_key - min_key + 1);
        }

        records[i].value = min_record_value + rand() % (max_record_value - min_record_value + 1);
    }

    pthread_mutex_unlock(&mutex);

    // Verify data integrity
    for (long i = 0; i < num_elements; ++i) {
        if (!(min_offset <= offsets[i] && offsets[i] <= max_offset)) {
            log_error("Offset value out of range.");
        }

        if (!(min_key <= keys[i] && keys[i] <= max_key)) {
            log_error("Key value out of range.");
        }

        if (!(min_record_value <= records[i].value && records[i].value <= max_record_value)) {
            log_error("Record value out of range.");
        }
    }

    // Clean up mutex
    pthread_mutex_destroy(&mutex);

    return 0;
}

// Example usage
int main() {
    long num_elements = 100;
    long min_offset = 10, max_offset = 50;
    int min_key = 1, max_key = 20;
    int min_record_value = 5, max_record_value = 15;

    // Simulate external data source for keys
    int *external_keys = malloc(num_elements * sizeof(int));
    if (external_keys) {
        for (int i = 0; i < num_elements; ++i) {
            external_keys[i] = rand() % (max_key - min_key + 1) + min_key;
        }
    }

    // Initialize data
    initialize_data(num_elements, min_offset, max_offset, min_key, max_key,
                    min_record_value, max_record_value, external_keys);

    free(external_keys);
    return 0;
}
