#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_BUFFER_LENGTH 50

typedef struct {
    double value;
    char buffer[MAX_BUFFER_LENGTH];
    int key;
} item;

typedef struct {
    item *items;
    size_t size;
    size_t capacity;
    int *external_offsets; // Array for offsets linked to external data sources
} ItemCollection;

void initialize_random() {
    srand((unsigned int)time(NULL));
}

double random_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

char* generate_unique_string(const char *seed, size_t max_length) {
    static size_t index = 0;
    char *result = malloc(max_length + 1);
    if (!result) {
        fprintf(stderr, "Memory allocation failed for string buffer\n");
        exit(EXIT_FAILURE);
    }

    strncpy(result, seed, max_length);
    snprintf(result + strlen(seed), max_length - strlen(seed), "_%zu", index++);
    result[max_length] = '\0';

    return result;
}

void init_item_collection(ItemCollection *collection, const char *seed) {
    collection->items = malloc(INITIAL_CAPACITY * sizeof(item));
    if (!collection->items) {
        fprintf(stderr, "Memory allocation failed for items\n");
        exit(EXIT_FAILURE);
    }
    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;

    collection->external_offsets = malloc(collection->capacity * sizeof(int));
    if (!collection->external_offsets) {
        free(collection->items);
        fprintf(stderr, "Memory allocation failed for external offsets\n");
        exit(EXIT_FAILURE);
    }
}

void resize_item_collection(ItemCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    item *new_items = realloc(collection->items, new_capacity * sizeof(item));
    if (!new_items) {
        fprintf(stderr, "Memory allocation failed during resizing\n");
        exit(EXIT_FAILURE);
    }
    int *new_offsets = realloc(collection->external_offsets, new_capacity * sizeof(int));
    if (!new_offsets) {
        free(new_items);
        fprintf(stderr, "Memory allocation failed for external offsets during resizing\n");
        exit(EXIT_FAILURE);
    }

    collection->items = new_items;
    collection->external_offsets = new_offsets;
    collection->capacity = new_capacity;
}

void add_item(ItemCollection *collection, double min_value, double max_value, const char *seed) {
    if (collection->size >= collection->capacity) {
        resize_item_collection(collection);
    }

    item *new_item = &collection->items[collection->size];
    new_item->value = random_double(min_value, max_value);

    char *buffer_content = generate_unique_string(seed, MAX_BUFFER_LENGTH - 1);
    strncpy(new_item->buffer, buffer_content, MAX_BUFFER_LENGTH);
    free(buffer_content); // Free the temporary string memory

    new_item->key = (int)collection->size; // Assign key based on index

    collection->external_offsets[collection->size] = rand() % 1000; // Simulating external offset
    collection->size++;
}

void handle_external_data(ItemCollection *collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        int offset = collection->external_offsets[i];

        if (offset < 0 || offset >= 1000) { // Simulated bounds check
            fprintf(stderr, "Warning: Inconsistent data at index %zu\n", i);
            collection->external_offsets[i] = -1; // Mark as invalid
        }
    }
}

void free_item_collection(ItemCollection *collection) {
    free(collection->items);
    free(collection->external_offsets);
}

// Test function for stress testing under failure conditions and large datasets
void test_stress_conditions() {
    ItemCollection collection;
    initialize_random();
    init_item_collection(&collection, "Seed");

    // Add items to simulate stress
    const size_t num_items = 100000; // Large number of items
    for (size_t i = 0; i < num_items; ++i) {
        add_item(&collection, -50.0, 50.0, "Test");
    }

    handle_external_data(&collection);
    free_item_collection(&collection);

    printf("Stress test completed successfully.\n");
}

int main() {
    test_stress_conditions();
    return 0;
}
