int lcg(int seed) {
    const unsigned long a = 1664525;
    const unsigned long c = 1013904223;
    static unsigned long last_state = seed;
    last_state = (a * last_state + c);
    return (int)(last_state % ((unsigned long)LONG_MAX));
}

// Function to manage memory for arrays and records
void* initialize_data(size_t num_offsets, size_t num_keys, int random_seed, void (*random_gen_func)(int), FILE* log_file) {
    // Validate input sizes
    if (num_offsets == 0 || num_keys == 0) {
        log_message("Invalid array sizes.");
        return NULL;
    }

    // Log start time
    clock_t start_time = clock();
    double init_start_time = ((double)start_time) / CLOCKS_PER_SEC;

    // Set random seed for reproducibility
    srand(random_seed);

    // Allocate memory for arrays and records
    long* offsets = (long*)calloc(num_offsets, sizeof(long));
    int* keys = (int*)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        log_message("Memory allocation failed.");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays using custom random number generator
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = random_gen_func(rand());
    }
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = random_gen_func(rand());
    }

    // Allocate and initialize records
    Record* records = (Record*)calloc(num_offsets, sizeof(Record));
    if (!records) {
        log_message("Memory allocation for records failed.");
        free(offsets);
        free(keys);
        return NULL;
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        records[i].value = random_gen_func(rand());
    }

    // Log end time and duration
    clock_t end_time = clock();
    double init_end_time = ((double)end_time) / CLOCKS_PER_SEC;
    log_message("Initialization completed.");

    if (log_file) {
        fprintf(log_file, "Initialization Start: %f\n", init_start_time);
        fprintf(log_file, "Initialization End: %f\n", init_end_time);
    }

    // Verify that memory is properly initialized
    for (size_t i = 0; i < num_offsets; ++i) {
        if (offsets[i] == 0 || records[i].value == 0) {
            log_message("Memory initialization verification failed.");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    // Return the allocated memory in a struct-like manner
    typedef struct {
        long* offsets;
        int* keys;
        Record* records;
    } Data;

    Data* data = (Data*)malloc(sizeof(Data));
    if (!data) {
        log_message("Memory allocation for data structure failed.");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    data->offsets = offsets;
    data->keys = keys;
    data->records = records;

    return (void*)data;
}

// Usage documentation
/*
