#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 10000
#define MEMORY_LIMIT (5 * 1024 * 1024) // 5 MB

typedef struct {
    double timestamp;
    int event_id;
    double metric_value;
} EventLogEntry;

typedef struct {
    EventLogEntry* entries;
    size_t count;
    double memory_usage;
    pthread_mutex_t lock;
} EventLogSystem;

double generate_random_metric(double min, double max, unsigned int seed) {
    srand(seed);
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

void init_event_log(EventLogSystem* log_system, size_t initial_count, double min_metric, double max_metric, unsigned int seed) {
    pthread_mutex_init(&log_system->lock, NULL);

    log_system->entries = (EventLogEntry*)malloc(initial_count * sizeof(EventLogEntry));
    if (!log_system->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    log_system->count = initial_count;
    log_system->memory_usage = initial_count * sizeof(EventLogEntry);

    for (size_t i = 0; i < initial_count; ++i) {
        log_system->entries[i].timestamp = (double)i; // Simplified timestamp
        log_system->entries[i].event_id = i;
        log_system->entries[i].metric_value = generate_random_metric(min_metric, max_metric, seed);
    }
}

int add_event(EventLogSystem* log_system, double timestamp, int event_id, double metric_value) {
    pthread_mutex_lock(&log_system->lock);

    if (log_system->count >= MAX_EVENTS || 
        (log_system->memory_usage + sizeof(EventLogEntry)) > MEMORY_LIMIT) {
        pthread_mutex_unlock(&log_system->lock);
        return -1; // Memory limit or entry limit exceeded
    }

    log_system->entries[log_system->count].timestamp = timestamp;
    log_system->entries[log_system->count].event_id = event_id;
    log_system->entries[log_system->count].metric_value = metric_value;

    log_system->count++;
    log_system->memory_usage += sizeof(EventLogEntry);

    pthread_mutex_unlock(&log_system->lock);
    return 0; // Success
}

EventLogEntry* get_event(EventLogSystem* log_system, int event_id) {
    pthread_mutex_lock(&log_system->lock);

    for (size_t i = 0; i < log_system->count; ++i) {
        if (log_system->entries[i].event_id == event_id) {
            pthread_mutex_unlock(&log_system->lock);
            return &log_system->entries[i];
        }
    }

    pthread_mutex_unlock(&log_system->lock);
    return NULL;
}

void cleanup_event_log(EventLogSystem* log_system) {
    pthread_mutex_lock(&log_system->lock);

    free(log_system->entries);
    log_system->entries = NULL;
    log_system->count = 0;
    log_system->memory_usage = 0;

    pthread_mutex_unlock(&log_system->lock);
    pthread_mutex_destroy(&log_system->lock);
}

int main() {
    EventLogSystem event_log;
    init_event_log(&event_log, 1000, 0.0, 100.0, 42);

    if (add_event(&event_log, 162030, 2001, 75.5) == 0) {
        printf("Event added successfully.\n");
    } else {
        printf("Failed to add event due to memory limit.\n");
    }

    EventLogEntry* entry = get_event(&event_log, 2001);
    if (entry != NULL) {
        printf("Retrieved Event: ID=%d, Metric=%.2f\n", entry->event_id, entry->metric_value);
    } else {
        printf("Event not found.\n");
    }

    cleanup_event_log(&event_log);
    return 0;
}
