#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>

#define MAX_STRUCTS 1000

typedef struct {
    unsigned char mac_header[14];
    unsigned char mac_address_1[6];
    unsigned char mac_address_2[6];
    unsigned short vlan_tag;
    unsigned char vlan_priority : 3;
    unsigned char ip_checksum_enabled : 1;
} NICB;

typedef struct {
    NICB nicb;
    char *data; // variable-length data
} NetworkDataStruct;

typedef struct Node {
    NetworkDataStruct *struct_data;
    struct Node *next;
} Node;

Node *head = NULL, *tail = NULL;

void initialize_aes_cipher(AES_KEY *aes_key) {
    unsigned char key[32] = "0123456789abcdef0123456789abcdef"; // 256-bit key
    AES_set_encrypt_key(key, 256, aes_key);
}

void encrypt_data(unsigned char *data, size_t data_len, AES_KEY *aes_key) {
    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0, AES_BLOCK_SIZE); // simple IV for demonstration purposes

    int num_blocks = (data_len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE;
    unsigned char *encrypted_data = malloc(num_blocks * AES_BLOCK_SIZE);

    if (!encrypted_data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    AES_cbc_encrypt(data, encrypted_data, data_len, aes_key, iv, AES_ENCRYPT);

    // Replace original data with encrypted data
    memcpy(data, encrypted_data, num_blocks * AES_BLOCK_SIZE);
    free(encrypted_data);
}

void add_data_structure(NICB nicb, const char *data) {
    NetworkDataStruct *new_struct = malloc(sizeof(NetworkDataStruct));
    if (!new_struct) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    new_struct->nicb = nicb;
    size_t data_len = strlen(data) + 1;
    new_struct->data = malloc(data_len);
    if (!new_struct->data) {
        free(new_struct);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    memcpy(new_struct->data, data, data_len);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        free(new_struct->data);
        free(new_struct);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    new_node->struct_data = new_struct;
    new_node->next = NULL;

    if (tail) {
        tail->next = new_node;
    } else {
        head = new_node;
    }
    tail = new_node;
}

void remove_data_structure(const char *data) {
    Node **indirect = &head;
    while (*indirect) {
        Node *entry = *indirect;
        if (strcmp(entry->struct_data->data, data) == 0) {
            *indirect = entry->next;
            free(entry->struct_data->data);
            free(entry->struct_data);
            free(entry);

            if (*indirect == NULL) {
                tail = NULL; // If the list is now empty
            }

            return;
        }
        indirect = &entry->next;
    }
}

void iterate_and_transform() {
    for (Node *current = head; current != NULL; current = current->next) {
        NetworkDataStruct *data_struct = current->struct_data;

        // Example transformation: Encrypt the data
        AES_KEY aes_key;
        initialize_aes_cipher(&aes_key);
        encrypt_data((unsigned char *)data_struct->data, strlen(data_struct->data), &aes_key);

        // Additional operations (e.g., filtering, sorting) can be done here
    }
}

void perform_md5(const char *input) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, strlen(input), hash);

    printf("MD5: ");
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++)
        printf("%02x", hash[i]);
    printf("\n");
}

void perform_sha1(const char *input) {
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)input, strlen(input), hash);

    printf("SHA1: ");
    for(int i = 0; i < SHA_DIGEST_LENGTH; i++)
        printf("%02x", hash[i]);
    printf("\n");
}

void manage_network_data_structures() {
    // Example Usage
    NICB nicb_example = { .mac_header = "header" };
    add_data_structure(nicb_example, "Sample Data 1");

    iterate_and_transform();

    perform_md5("example data for MD5");
    perform_sha1("example data for SHA1");

    remove_data_structure("Sample Data 1");

    // Free remaining nodes
    while (head) {
        Node *temp = head;
        head = head->next;

        free(temp->struct_data->data);
        free(temp->struct_data);
        free(temp);
    }
}

int main() {
    manage_network_data_structures();
    return 0;
}
