#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define ALIGNMENT 1024

typedef struct Constraint {
    int dependency_id;
    int limit;
    time_t deadline;
    struct Constraint* next;
} Constraint;

typedef struct Activity {
    int priority;
    char type[50];
    Constraint* constraints;
    double resource_demand;
    int criticality;
    struct Activity* next;
} Activity;

typedef struct Item {
    double value;
    char buffer[256];
} Item;

void* aligned_malloc(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Activity* create_activity(int priority, const char* type, double resource_demand, int criticality, Constraint** constraints) {
    Activity* activity = aligned_malloc(sizeof(Activity));
    if (!activity) return NULL;

    activity->priority = priority;
    strncpy(activity->type, type, sizeof(activity->type) - 1);
    activity->resource_demand = resource_demand;
    activity->criticality = criticality;
    activity->constraints = *constraints;
    activity->next = NULL;

    return activity;
}

Constraint* create_constraint(int dependency_id, int limit, time_t deadline) {
    Constraint* constraint = aligned_malloc(sizeof(Constraint));
    if (!constraint) return NULL;

    constraint->dependency_id = dependency_id;
    constraint->limit = limit;
    constraint->deadline = deadline;
    constraint->next = NULL;

    return constraint;
}

Item* create_items(size_t count, const char* seed, double min_val, double max_val, size_t buffer_length) {
    Item* items = aligned_malloc(sizeof(Item) * count);
    if (!items) return NULL;

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        items[i].value = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);

        snprintf(items[i].buffer, buffer_length, "%s_%zu", seed, i);
        items[i].buffer[buffer_length - 1] = '\0';
    }

    return items;
}

void run_tests(Activity* activities, Item* items, size_t item_count) {
    // Example test framework structure
    printf("Running tests...\n");

    for (size_t i = 0; i < item_count; ++i) {
        printf("Test %zu: Value = %.2f, Buffer = %s\n", i + 1, items[i].value, items[i].buffer);
    }

    Activity* current_activity = activities;
    while (current_activity != NULL) {
        printf("Activity Priority: %d, Type: %s, Resource Demand: %.2f, Criticality: %d\n",
               current_activity->priority,
               current_activity->type,
               current_activity->resource_demand,
               current_activity->criticality);

        Constraint* constraint = current_activity->constraints;
        while (constraint != NULL) {
            printf("  Constraint Dependency ID: %d, Limit: %d, Deadline: %ld\n",
                   constraint->dependency_id,
                   constraint->limit,
                   constraint->deadline);
            constraint = constraint->next;
        }

        current_activity = current_activity->next;
    }
}

void cleanup(Activity* activities, Item* items) {
    Activity* activity = activities;
    while (activity != NULL) {
        Constraint* constraint = activity->constraints;
        while (constraint != NULL) {
            Constraint* to_free = constraint;
            constraint = constraint->next;
            free(to_free);
        }
        Activity* to_free = activity;
        activity = activity->next;
        free(to_free);
    }

    free(items);
}

int main() {
    srand(time(NULL));

    // Create activities
    Constraint* constraints1 = create_constraint(101, 50, time(NULL) + 3600);
    Constraint* constraints2 = create_constraint(102, 30, time(NULL) + 7200);

    Activity* activity1 = create_activity(1, "TypeA", 75.5, 10, &constraints1);
    Activity* activity2 = create_activity(2, "TypeB", 60.3, 20, &constraints2);

    activity1->next = activity2;

    // Create items
    Item* items = create_items(5, "SeedString", 0.0, 100.0, sizeof(items[0].buffer));

    run_tests(activity1, items, 5);
    cleanup(activity1, items);

    return 0;
}
