#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1048576 // 1 MB in bytes
#define NUM_RECORDS 100

typedef struct {
    size_t size;
    union {
        double dValue;
        char *strPtr;
    } uData;
} Item;

typedef struct {
    int value;
    char uniqueID[64];
    Item *itemPtr;
} Record;

pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;
size_t totalMemoryUsage = 0;
Record* recordsArray[NUM_RECORDS];

void initializeRecords() {
    srand(time(NULL));
    for (int i = 0; i < NUM_RECORDS; ++i) {
        recordsArray[i] = (Record*)malloc(sizeof(Record));
        if (!recordsArray[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&memoryMutex);
        totalMemoryUsage += sizeof(Record);

        // Ensure we don't exceed memory usage
        while (totalMemoryUsage > MAX_MEMORY_USAGE) {
            free(recordsArray[0]);
            recordsArray[0] = NULL;
            totalMemoryUsage -= sizeof(Record);
        }

        pthread_mutex_unlock(&memoryMutex);

        // Initialize the record
        recordsArray[i]->value = rand() % 1000;
        snprintf(recordsArray[i]->uniqueID, sizeof(recordsArray[i]->uniqueID),
                 "record_%d_time_%ld", i, time(NULL));

        // Allocate and initialize item
        recordsArray[i]->itemPtr = (Item*)malloc(sizeof(Item));
        if (!recordsArray[i]->itemPtr) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        totalMemoryUsage += sizeof(Item);

        pthread_mutex_lock(&memoryMutex);

        // Ensure we don't exceed memory usage
        while (totalMemoryUsage > MAX_MEMORY_USAGE) {
            free(recordsArray[0]->itemPtr);
            recordsArray[0]->itemPtr = NULL;
            totalMemoryUsage -= sizeof(Item);
        }

        pthread_mutex_unlock(&memoryMutex);

        recordsArray[i]->itemPtr->size = rand() % 100 + 1; // random size
        if (rand() % 2 == 0) {
            recordsArray[i]->itemPtr->uData.dValue = (double)(rand() % 100);
        } else {
            char *str = (char*)malloc(recordsArray[i]->itemPtr->size + 1);
            if (!str) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            snprintf(str, recordsArray[i]->itemPtr->size + 1, "String of length %zu", recordsArray[i]->itemPtr->size);
            recordsArray[i]->itemPtr->uData.strPtr = str;
            totalMemoryUsage += (strlen(str) + 1);
        }
    }
}

void freeRecords() {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (recordsArray[i]) {
            Item *item = recordsArray[i]->itemPtr;
            if (item && item->uData.strPtr) {
                free(item->uData.strPtr);
                totalMemoryUsage -= (strlen(item->uData.strPtr) + 1);
            }
            free(item);
            totalMemoryUsage -= sizeof(Item);
            free(recordsArray[i]);
            totalMemoryUsage -= sizeof(Record);
        }
    }
}

int main() {
    initializeRecords();

    // Simulate high load scenario
    for (int i = 0; i < NUM_RECORDS; ++i) {
        printf("Record %d: Value=%d, UniqueID=%s\n", 
               i, recordsArray[i]->value, recordsArray[i]->uniqueID);
    }

    freeRecords();
    return 0;
}
