['Below is an example implementation of the described C function. This code uses pthreads for thread safety and ensures alignment using `posix_memalign`. It incorporates dynamic resizing, error handling, and logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 1000
#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

typedef struct {
    int *frequencies;
    size_t max_key;
    pthread_rwlock_t rwlock;
} FrequencyTracker;

// Function prototypes
void init_record_array(RecordArray *array, size_t alignment);
void free_record_array(RecordArray *array);
int resize_record_array(RecordArray *array, size_t new_capacity);
void populate_records_randomly(RecordArray *array, long min_offset, long max_offset, int min_key, int max_key);
void update_frequency(FrequencyTracker *tracker, int key, int delta);

// Initialize record array with aligned memory
void init_record_array(RecordArray *array, size_t alignment) {
    pthread_mutex_init(&array->lock, NULL);
    array->records = NULL;
    array->capacity = 0;
    array->count = 0;

    if (posix_memalign((void**)&array->records, alignment, INITIAL_CAPACITY * sizeof(Record)) != 0) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
}

// Free record array
void free_record_array(RecordArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->records);
    array->records = NULL;
    array->capacity = 0;
    array->count = 0;
}

// Resize the record array dynamically
int resize_record_array(RecordArray *array, size_t new_capacity) {
    Record *new_records;
    if (posix_memalign((void**)&new_records, sizeof(Record), new_capacity * sizeof(Record)) != 0) {
        fprintf(stderr, "Failed to allocate memory for resizing\n");
        return -1;
    }

    pthread_mutex_lock(&array->lock);
    memcpy(new_records, array->records, array->count * sizeof(Record));
    free(array->records);
    array->records = new_records;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);

    return 0;
}

// Populate records with random values
void populate_records_randomly(RecordArray *array, long min_offset, long max_offset, int min_key, int max_key) {
    srand(time(NULL));

    pthread_mutex_lock(&array->lock);
    if (resize_record_array(array, array->capacity + 1000) != 0) {
        fprintf(stderr, "Unable to resize record array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array->count; ++i) {
        array->records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        array->records[i].key = min_key + rand() % (max_key - min_key + 1);
    }

    array->count += 1000;
    pthread_mutex_unlock(&array->lock);
}

// Initialize frequency tracker
void init_frequency_tracker(FrequencyTracker *tracker, size_t max_key) {
    pthread_rwlock_init(&tracker->rwlock, NULL);
    if (posix_memalign((void**)&tracker->frequencies, sizeof(int), max_key * sizeof(int)) != 0) {
        fprintf(stderr, "Failed to allocate memory for frequencies\n");
        exit(EXIT_FAILURE);
    }
    memset(tracker->frequencies, 0, max_key * sizeof(int));
    tracker->max_key = max_key;
}

// Free frequency tracker
void free_frequency_tracker(FrequencyTracker *tracker) {
    pthread_rwlock_destroy(&tracker->rwlock);
    free(tracker->frequencies);
    tracker->frequencies = NULL;
    tracker->max_key = 0;
}

// Update the frequency of a key
void update_frequency(FrequencyTracker *tracker, int key, int delta) {
    if (key < 0 || key >= (int)tracker->max_key) return;

    pthread_rwlock_wrlock(&tracker->rwlock);
    tracker->frequencies[key] += delta;
    pthread_rwlock_unlock(&tracker->rwlock);
}

// Main function to manage memory and populate records
void manage_memory_and_populate(int max_records, long min_offset, long max_offset, int min_key, int max_key, size_t alignment) {
    RecordArray record_array;
    FrequencyTracker freq_tracker;

    init_record_array(&record_array, alignment);
    init_frequency_tracker(&freq_tracker, max_key);

    for (size_t i = 0; i < max_records && record_array.count < MAX_RECORDS; i += 1000) {
        populate_records_randomly(&record_array, min_offset, max_offset, min_key, max_key);

        // Example update of frequency tracker
        for (size_t j = 0; j < record_array.count && j >= record_array.count - 1000; ++j) {
            update_frequency(&freq_tracker, record_array.records[j].key, 1);
        }
    }

    free_record_array(&record_array);
    free_frequency_tracker(&freq_tracker);
}

int main(int argc, char *argv[]) {
    // Example usage
    manage_memory_and_populate(1000000, 0, 10000, 0, 100, 16);

    return 0;
}
```

