use std::ptr;
use std::sync::atomic::{AtomicUsize, Ordering};

struct CustomAllocator {
    next_id: AtomicUsize,
}

unsafe impl Allocator for CustomAllocator {
    fn allocate(&self, layout: Layout) -> *mut u8 {
        let ptr = Global.allocate(layout).expect("Failed to allocate memory");
        if !ptr.is_null() && (layout.align() % 32 == 0 || layout.size() % 32 == 0) {
            return ptr;
        }
        self.next_id.fetch_add(1, Ordering::SeqCst);
        ptr
    }

    fn deallocate(&self, ptr: *mut u8, _layout: Layout) {
        Global.deallocate(ptr, Layout::from_size_align_unchecked(_layout.size(), 32).unwrap());
    }
}

