#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define ALIGNMENT 32

typedef struct Item {
    int key;
    char str[16]; // Fixed length string
    unsigned long timestamp; 
} Item;

typedef struct Node {
    double value;
    Item *items;
} Node;

// Function to allocate aligned memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // posix_memalign returns 0 on success
    }
#else
#error "Platform not supported"
#endif
    return ptr;
}

// Function to free aligned memory
void aligned_free(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#elif defined(__unix__) || (defined(__APPLE__) && defined(__MACH__))
    free(ptr);
#else
#error "Platform not supported"
#endif
}

// Configuration structure for RNG
typedef struct RNGConfig {
    const char* rng_type; // e.g., "default", "fast"
    int parameter1;
} RNGConfig;

// Function to load configuration from a file (simplified)
RNGConfig load_rng_config(const char *filename) {
    RNGConfig config = {"default", 0};
    FILE *file = fopen(filename, "r");
    if (file) {
        fscanf(file, "%s %d", config.rng_type, &config.parameter1);
        fclose(file);
    }
    return config;
}

// Function to generate random numbers based on configuration
double generate_random_number(const RNGConfig *config) {
    // Simplified example: use different generators or parameters
    if (strcmp(config->rng_type, "fast") == 0) {
        return rand() / (double)RAND_MAX; // Example of a fast RNG
    }
    return drand48(); // Default C library RNG
}

// Function to verify data integrity
int verify_data_integrity(Node *nodes, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (!nodes[i].value || !nodes[i].items) {
            return 0;
        }
    }
    return 1;
}

// Main function to allocate and initialize nodes
Node* manage_nodes(size_t node_count, const char *config_file) {
    Node *nodes = aligned_alloc(ALIGNMENT, sizeof(Node) * node_count);
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for nodes\n");
        return NULL;
    }

    RNGConfig rng_config = load_rng_config(config_file);

    for (size_t i = 0; i < node_count; ++i) {
        Node *node = &nodes[i];

        // Initialize node value with random number
        node->value = generate_random_number(&rng_config);

        size_t item_count = rand() % 10 + 1; // Random number of items

        // Allocate aligned memory for items
        Item *items = aligned_alloc(ALIGNMENT, sizeof(Item) * item_count);
        if (!items) {
            fprintf(stderr, "Failed to allocate memory for items\n");
            while (i-- > 0) { // Cleanup previously allocated nodes
                aligned_free(nodes[i].items);
            }
            aligned_free(nodes);
            return NULL;
        }

        node->items = items;

        // Initialize each item
        for (size_t j = 0; j < item_count; ++j) {
            Item *item = &items[j];
            item->key = rand() % 1000;
            snprintf(item->str, sizeof(item->str), "Item_%zu", j);
            item->timestamp = time(NULL); // Use current time for timestamp
        }
    }

    if (!verify_data_integrity(nodes, node_count)) {
        fprintf(stderr, "Data integrity verification failed\n");
        while (node_count-- > 0) {
            aligned_free(nodes[node_count].items);
        }
        aligned_free(nodes);
        return NULL;
    }

    return nodes;
}

// Example usage
int main() {
    const size_t node_count = 5;
    Node *nodes = manage_nodes(node_count, "rng_config.txt");

    if (nodes) {
        // Use the allocated and initialized nodes
        for (size_t i = 0; i < node_count; ++i) {
            printf("Node %zu: Value = %.2f\n", i, nodes[i].value);
        }

        // Cleanup
        for (size_t i = 0; i < node_count; ++i) {
            aligned_free(nodes[i].items);
        }
        aligned_free(nodes);
    }

    return 0;
