#define ALIGNMENT 16
#define RECORD_COUNT 1000
#define OFFSET_COUNT 500
#define KEY_COUNT 300
#define NICB_COUNT 10

typedef struct {
    int value;
} Record;

typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
    uint16_t vlan_tag;
    uint8_t priority;
    // Additional MAC_HEADER fields as required by the network stack.
} NetworkInterfaceControlBlock;

void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
#endif
    return ptr;
}

void free_aligned(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int initialize_resources(Record records[], long offsets[], int keys[], NetworkInterfaceControlBlock nicbs[]) {
    sem_t semaphores[NICB_COUNT];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (posix_memalign((void**)&records, ALIGNMENT, RECORD_COUNT * sizeof(Record))) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return -1;
    }
    if (posix_memalign((void**)&offsets, ALIGNMENT, OFFSET_COUNT * sizeof(long))) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free_aligned(records);
        return -1;
    }
    if (posix_memalign((void**)&keys, ALIGNMENT, KEY_COUNT * sizeof(int))) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free_aligned(records);
        free_aligned(offsets);
        return -1;
    }

    for (int i = 0; i < NICB_COUNT; ++i) {
        if (sem_init(&semaphores[i], 0, 1)) {
            fprintf(stderr, "Semaphore initialization failed\n");
            free_aligned(records);
            free_aligned(offsets);
            free_aligned(keys);
            return -1;
        }
    }

    // Initialize records with random values
    for (int i = 0; i < RECORD_COUNT; ++i) {
        records[i].value = rand() % 100; // Random value in range [0, 99]
    }

    // Populate NICBs
    for (int i = 0; i < NICB_COUNT; ++i) {
        // Example MAC addresses and VLAN configuration
        memset(nicbs[i].dest_mac, 0xAA, sizeof(nicbs[i].dest_mac));
        memset(nicbs[i].src_mac, 0xBB, sizeof(nicbs[i].src_mac));
        nicbs[i].vlan_tag = htons(100 + i); // Example VLAN tag
        nicbs[i].priority = i % 8;          // Example priority

        pthread_mutex_lock(&mutex);
        sem_post(&semaphores[i]); // Ensure semaphore is available
        pthread_mutex_unlock(&mutex);
    }

    // Example of dynamic reconfiguration function (not fully implemented)
    void reconfigure_nicb(NetworkInterfaceControlBlock* nicb, const uint8_t* new_src_mac) {
        if (new_src_mac) {
            memcpy(nicb->src_mac, new_src_mac, sizeof(nicb->src_mac));
        }
    }

    // Cleanup
    for (int i = 0; i < NICB_COUNT; ++i) {
        sem_destroy(&semaphores[i]);
    }
    pthread_mutex_destroy(&mutex);
    free_aligned(records);
    free_aligned(offsets);
    free_aligned(keys);

    return 0;
}

int main() {
    Record records[RECORD_COUNT];
    long offsets[OFFSET_COUNT];
    int keys[KEY_COUNT];
    NetworkInterfaceControlBlock nicbs[NICB_COUNT];

    if (initialize_resources(records, offsets, keys, nicbs) != 0) {
        fprintf(stderr, "Failed to initialize resources\n");
        return EXIT_FAILURE;
    }

    printf("Resources initialized successfully\n");
    return EXIT_SUCCESS;
}
