#define MEMORY_LIMIT (1ULL << 30) // 1 GB

typedef struct {
    time_t last_accessed;
    size_t file_size;
} struct meta;

void free_least_recently_used(int* fds, struct meta** metadata, char** paths, int* sizes, int current_count);

// C function to handle memory and synchronization
void manage_file_processing(char** input_paths, int num_files) {
    if (num_files == 0) return;

    int* file_descriptors = malloc(num_files * sizeof(int));
    struct meta** metadata_array = malloc(num_files * sizeof(struct meta*));
    char** path_array = malloc(num_files * MAX_PATH_LENGTH * sizeof(char));
    size_t* binary_sizes = malloc(num_files * sizeof(size_t));

    size_t total_memory_usage = 0;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_files; ++i) {
        metadata_array[i] = malloc(METADATA_SIZE);
        path_array[i] = input_paths[i];

        // Initialize metadata
        metadata_array[i]->last_accessed = time(NULL); // Random access time
        metadata_array[i]->file_size = BINARY_OBJECT_SIZE;

        binary_sizes[i] = BINARY_OBJECT_SIZE; // Fixed size for binary object

        total_memory_usage += METADATA_SIZE + strlen(path_array[i]) * sizeof(char) + BINARY_OBJECT_SIZE;
    }

    if (total_memory_usage > MEMORY_LIMIT) {
        pthread_mutex_lock(&lock);
        free_least_recently_used(file_descriptors, metadata_array, path_array, binary_sizes, num_files);
        total_memory_usage = 0; // Recalculate after freeing
        for (int i = 0; i < num_files && total_memory_usage <= MEMORY_LIMIT; ++i) {
            total_memory_usage += METADATA_SIZE + strlen(path_array[i]) * sizeof(char) + BINARY_OBJECT_SIZE;
        }
        pthread_mutex_unlock(&lock);
    }

    // Clean up
    for (int i = 0; i < num_files; ++i) {
        free(metadata_array[i]);
    }

    free(file_descriptors);
    free(metadata_array);
    free(path_array);
    free(binary_sizes);

    pthread_mutex_destroy(&lock);
}

