    tags[1] = (Tag){CATEGORY_B, process_document_b};
    tags[2] = (Tag){CATEGORY_C, process_document_c};

    return tags;
}

Document* create_document() {
    Document *doc = aligned_alloc(ALIGNMENT, sizeof(Document));
    if (!doc) return NULL;

    doc->content = generate_random_string(rand() % MAX_CHAR_LENGTH);
    if (!doc->content) {
        free_aligned(doc);
        return NULL;
    }

    doc->tags = initialize_tags();
    if (!doc->tags) {
        free_aligned(doc->content);
        free_aligned(doc);
        return NULL;
    }
    doc->tag_count = TAG_COUNT;

    doc->timestamp = time(NULL);
    doc->ref_count = 1; // Initial reference count

    return doc;
}

void release_document(Document *doc) {
    if (--doc->ref_count == 0) {
        free_aligned(doc->content);
        free_aligned(doc->tags);
        free_aligned(doc);
    }
}

typedef struct ThreadArgs {
    Document **documents;
    size_t start_idx;
    size_t end_idx;
} ThreadArgs;

void* process_documents(void *args_void_ptr) {
    ThreadArgs *args = (ThreadArgs*)args_void_ptr;

    for (size_t i = args->start_idx; i < args->end_idx; ++i) {
        Document *doc = args->documents[i];
        // Simulate processing
        doc->tags[0].action(doc);
    }
    return NULL;
}

void process_documents_parallel(Document **documents, size_t count) {
    pthread_t threads[THREAD_POOL_SIZE];
    ThreadArgs thread_args[THREAD_POOL_SIZE];

    size_t chunk_size = count / THREAD_POOL_SIZE;

    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        thread_args[i].documents = documents;
        thread_args[i].start_idx = i * chunk_size;
        thread_args[i].end_idx = (i == THREAD_POOL_SIZE - 1) ? count : (i + 1) * chunk_size;

        if (pthread_create(&threads[i], NULL, process_documents, &thread_args[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Simulated main function
int main() {
    srand(time(NULL));

    const size_t document_count = 100;
    Document **documents = aligned_alloc(ALIGNMENT, document_count * sizeof(Document*));
    if (!documents) return EXIT_FAILURE;

    for (size_t i = 0; i < document_count; ++i) {
        documents[i] = create_document();
        if (!documents[i]) {
            fprintf(stderr, "Failed to create document\n");
            // Handle cleanup
            break;
        }
    }

    process_documents_parallel(documents, document_count);

    for (size_t i = 0; i < document_count; ++i) {
        release_document(documents[i]);
    }

    free_aligned(documents);
    return EXIT_SUCCESS;
}
