// Cache management structures and functions (simplified)
#define CACHE_MAX_SIZE 100

struct MemoryBlock {
    void *ptr;
    size_t size;
    UT_hash_handle hh; // Makes this structure hashable
};

static struct MemoryBlock *cache = NULL;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_to_cache(void *ptr, size_t size) {
    pthread_mutex_lock(&cache_mutex);
    struct MemoryBlock *block = malloc(sizeof(struct MemoryBlock));
    if (!block) return; // Handle allocation failure
    block->ptr = ptr;
    block->size = size;
    HASH_ADD_PTR(cache, ptr, block); // Add to cache hash table

    // Implement a simple eviction policy for the sake of example
    if (HASH_COUNT(cache) > CACHE_MAX_SIZE) {
        struct MemoryBlock *old_block;
        HASH_ITER(hh, cache, old_block, block) {
            free(old_block->ptr);
            HASH_DEL(cache, old_block);
            free(old_block);
            break;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
}

void* get_from_cache(size_t size) {
    pthread_mutex_lock(&cache_mutex);
    struct MemoryBlock *block, *tmp;
    for (block = cache; block != NULL; block = tmp) {
        tmp = (struct MemoryBlock*)HASH_NEXT(cache, block);
        if (block->size >= size) {
            HASH_DEL(cache, block);
            void *ptr = block->ptr;
            free(block); // Free the metadata
            pthread_mutex_unlock(&cache_mutex);
            return ptr; // Return the memory pointer
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL; // No suitable block found in cache
}

// Random number generation pool (simplified for example)
#define POOL_SIZE 1000
static float rand_pool[POOL_SIZE];
static int pool_index = 0;
pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;

float get_random_float() {
    pthread_mutex_lock(&rand_lock);
    if (pool_index >= POOL_SIZE) {
        // Refill the pool with random numbers
        for (int i = 0; i < POOL_SIZE; ++i) {
            rand_pool[i] = ((float) rand()) / RAND_MAX;
        }
        pool_index = 0;
    }
    float result = rand_pool[pool_index++];
    pthread_mutex_unlock(&rand_lock);
    return result;
}

// Function to initialize records
int init_records(Record **records, long *offsets, int *keys, size_t n) {
    if (n <= 0) return -1; // Error: Invalid input

    // Allocate memory for the arrays
    offsets = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return -2; // Error: Memory allocation failure
    }

    *records = (Record *)malloc(n * sizeof(Record));
    if (!*records) {
        free(offsets);
        free(keys);
        return -3; // Error: Memory allocation failure for records
    }

    // Initialize the arrays and records
    time_t rawtime;
    struct timespec spec;

    clock_gettime(CLOCK_REALTIME, &spec);
    long start_time = spec.tv_sec;

    int unique_keys[HASH_MAX_BUCKETS];  // Example max buckets size
    HASH_CREATE(unique_keys);

    for (size_t i = 0; i < n; ++i) {
        offsets[i] = start_time + i;

        int key;
        do {
            key = rand() % n;  // Simplified unique key generation example
        } while (HASH_FIND_INT(unique_keys, &key, NULL));

        HASH_ADD_INT(unique_keys, key, key);  // Store to hash table

        keys[i] = key;

        (*records)[i].timestamp = offsets[i];
        (*records)[i].key = keys[i];
        (*records)[i].value = get_random_float();
    }

    return 0; // Success
}

// Function to cleanup memory and manage deallocation
void cleanup(Record *records, long *offsets, int *keys) {
    free(records);
    free(offsets);
    free(keys);

    pthread_mutex_lock(&cache_mutex);
    struct MemoryBlock *block, *tmp;
    HASH_ITER(hh, cache, block, tmp) {
        HASH_DEL(cache, block);  // Delete it (users advances to next)
        free(block->ptr);        // Free the memory block
        free(block);             // Free the metadata
    }
    pthread_mutex_unlock(&cache_mutex);
}
