// User-provided backup states and configuration settings
typedef struct {
    CPUState **backup_states;
    size_t num_backup_states;
} BackupStates;

// Log utility function
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Thread worker function for VMCB initialization
void* initialize_vmcb_thread(void *arg) {
    InitializationContext *ctx = (InitializationContext *)arg;
    int thread_id = *(int *)pthread_getspecific(pthread_self());

    size_t start_index = thread_id * (ctx->vmcb_count / pthread_self()->detachstate);
    size_t end_index = (thread_id + 1) * (ctx->vmcb_count / pthread_self()->detachstate);

    for (size_t i = start_index; i < end_index && i < ctx->vmcb_count; ++i) {
        VMCB *vmcb = ctx->vmcb_array[i];

        // Validate CPU state
        if (!HMS_CpuStateIsValid(vmcb->cpu_state)) {
            for (size_t j = 0; j < ctx->num_backup_states; ++j) {
                if (HMS_CpuStateIsValid(ctx->backup_states.backup_states[j])) {
                    vmcb->cpu_state = ctx->backup_states.backup_states[j];
                    break;
                }
            }

            // If still invalid, log failure
            if (!HMS_CpuStateIsValid(vmcb->cpu_state)) {
                HMS_LogFailure(vmcb->id, "Invalid CPU state");
                ++ctx->failed_initializations;
                continue;
            }
        }

        // Initialize virtual memory space and I/O port mappings (mocked)
        vmcb->virtual_memory_space = malloc(1024);  // Example allocation
        if (!vmcb->virtual_memory_space) {
            log_error("Memory allocation failed for VMCB");
            ++ctx->failed_initializations;
            continue;
        }

        vmcb->io_port_mapping = malloc(256);
        if (!vmcb->io_port_mapping) {
            free(vmcb->virtual_memory_space);
            log_error("Memory allocation failed for I/O port mapping");
            ++ctx->failed_initializations;
            continue;
        }

        // Initialize CPU features and interrupt control (mocked)
        memset(vmcb->cpu_features, 0, sizeof(vmcb->cpu_features));
        vmcb->interrupt_control = 1;

        // Log initialization success
    }

    return NULL;
}

// Main function to initialize VMCBs
void initialize_vmcs(int count, CpuStateValidator validator, BackupStates *backup_states) {
    if (count <= 0 || count > MAX_VMCBS) {
        log_error("Invalid number of VMCBs");
        return;
    }

    pthread_t threads[MAX_VMCBS];
    int thread_count = pthread_self()->detachstate; // Assume some system-dependent way to get optimal thread count
    if (thread_count < 1) thread_count = 1;

    InitializationContext context = {0};
    context.vmcb_count = count;

    context.vmcb_array = malloc(count * sizeof(VMCB *));
    if (!context.vmcb_array) {
        log_error("Failed to allocate memory for VMCB array");
        return;
    }

    context.num_backup_states = backup_states->num_backup_states;

    // Populate the VMCBs with initial data
    for (int i = 0; i < count; ++i) {
        VMCB *vmcb = malloc(sizeof(VMCB));
        if (!vmcb) {
            log_error("Failed to allocate memory for VMCB");
            context.failed_initializations++;
            continue;
        }

        vmcb->id = i;
        // Initialize with default CPU state, will be validated
        vmcb->cpu_state = NULL;  // Assume some function fills this

        // Validate initial CPU state using external callback
        if (!validator(vmcb->cpu_state)) {
            log_error("Invalid initial CPU state");
            context.failed_initializations++;
            free(vmcb);
            continue;
        }

        context.vmcb_array[i] = vmcb;
    }

    // Create threads to initialize VMCBs in parallel
    for (int i = 0; i < thread_count; ++i) {
        pthread_create(&threads[i], NULL, initialize_vmcb_thread, &context);
    }

    // Join threads
    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (context.failed_initializations > 0) {
        printf("Failed to initialize %d VMCBs\n", context.failed_initializations);
    } else {
        printf("All VMCBs initialized successfully\n");
    }

    // Clean up resources
    for (int i = 0; i < count; ++i) {
        if (context.vmcb_array[i]) {
            free(context.vmcb_array[i]->virtual_memory_space);
            free(context.vmcb_array[i]->io_port_mapping);
            free(context.vmcb_array[i]);
        }
    }
    free(context.vmcb_array);

    // Periodically send health reports to HMS
    while (1) {
        sleep(10);  // Example interval
        printf("Sending health report: %d VMCBs initialized, %d failures\n", 
               count - context.failed_initializations, context.failed_initializations);

        if (context.failed_initializations == context.vmcb_count) break;
    }
}
