RecordCollection* create_record_collection(size_t n) {
    if (n == 0) return NULL;

    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = malloc(n * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = n;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    // Initialize random seed
    srand((unsigned int)time(NULL));

    return collection;
}

int insert_record(RecordCollection *collection, int key, const char *metadata) {
    if (!collection || collection->count >= collection->capacity) return -1;

    pthread_mutex_lock(&collection->mutex);

    Record *record = &collection->records[collection->count++];

    // Timestamp
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        record->timestamp = ts.tv_sec + ts.tv_nsec / 1000000000.0;
    } else {
        time_t now = time(NULL);
        record->timestamp = now;
    }

    // Key
    record->key = key;

    // Value
    record->value = (float)rand() / RAND_MAX;

    // Metadata
    strncpy(record->metadata, metadata, MAX_METADATA_LENGTH - 1);
    record->metadata[MAX_METADATA_LENGTH - 1] = '\0';

    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

void cleanup_record_collection(RecordCollection *collection) {
    if (!collection) return;

    pthread_mutex_destroy(&collection->mutex);
    free(collection->records);
    free(collection);
}
