#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    char sensor_id[10];
    float value;
} SensorData;

typedef struct {
    long *timestamps;
    double *measurements;
    SensorData **sensor_data;
    size_t count;
} DataStore;

typedef struct {
    FILE *file;
    int index;
    pthread_mutex_t mutex;
} FileThreadArg;

void *process_file(void *arg) {
    FileThreadArg *fta = (FileThreadArg *)arg;
    char line[256];
    SensorData *sd = NULL;

    while (fgets(line, sizeof(line), fta->file)) {
        sd = realloc(fta->sensor_data[fta->index], sizeof(SensorData) * (fta->count + 1));
        if (!sd) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&fta->mutex);

        sscanf(line, "%s %f", fta->sensor_data[fta->index][fta->count].sensor_id, &fta->sensor_data[fta->index][fta->count].value);
        fta->sensor_data[fta->index][fta->count].index = fta->index;

        pthread_mutex_unlock(&fta->mutex);

        fta->count++;
    }

    free(fta);
    return NULL;
}

DataStore *initialize_data_store(size_t file_count) {
    DataStore *ds = malloc(sizeof(DataStore));
    if (!ds) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    ds->timestamps = calloc(file_count, sizeof(long));
    ds->measurements = calloc(file_count, sizeof(double));
    ds->sensor_data = calloc(file_count, sizeof(SensorData *));
    ds->count = 0;

    return ds;
}

void free_data_store(DataStore *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->sensor_data[i]);
    }
    free(ds->timestamps);
    free(ds->measurements);
    free(ds->sensor_data);
    free(ds);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t file_count = argc - 1;
    DataStore *ds = initialize_data_store(file_count);
    pthread_t threads[file_count];

    for (size_t i = 0; i < file_count; ++i) {
        FILE *file = fopen(argv[i + 1], "r");
        if (!file) {
            perror("Failed to open file");
            return EXIT_FAILURE;
        }

        FileThreadArg *fta = malloc(sizeof(FileThreadArg));
        if (!fta) {
            perror("Failed to allocate memory");
            fclose(file);
            return EXIT_FAILURE;
        }

        fta->file = file;
        fta->index = i;
        pthread_mutex_init(&fta->mutex, NULL);

        ds->sensor_data[i] = malloc(sizeof(SensorData));
        if (!ds->sensor_data[i]) {
            perror("Failed to allocate memory");
            fclose(file);
            free(fta);
            return EXIT_FAILURE;
        }

        pthread_create(&threads[i], NULL, process_file, fta);
    }

    for (size_t i = 0; i < file_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_data_store(ds);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Memory Allocation**: The code dynamically allocates memory for timestamps, measurements, and sensor data.
- **Multi-threading**: Each file is processed in a separate thread to handle concurrent I/O operations efficiently.
- **Thread Safety**: Mutexes are used to protect shared resources during updates.
- **Memory Management**: The `free_data_store` function ensures all allocated memory is properly freed, preventing leaks.
- **Error Handling**: Basic error handling is included for file operations and memory allocation failures.']

