int initialize_records(record **records, size_t *capacity, long start_time, long end_time, long interval) {
    if (start_time > end_time || interval <= 0) {
        fprintf(stderr, "Invalid date range or interval.\n");
        return -1;
    }

    size_t estimated_size = ((end_time - start_time) / interval) + 1;

    // Allocate or reallocate memory
    *records = realloc(*records, estimated_size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    size_t count = 0;
    for (long time = start_time; time <= end_time && count < estimated_size; time += interval) {
        // Handle potential overflow
        if ((time + interval > time || time - interval < time) &&
            (time + interval < time || time - interval > time)) {
            fprintf(stderr, "Overflow detected.\n");
            break;
        }

        (*records)[count].timestamp = time;
        (*records)[count].status_code = 0; // Default status code
        count++;
    }

    *capacity = count;

    return 0;
}

void resize_records(record **records, size_t current_capacity, size_t new_capacity) {
    record *temp = realloc(*records, new_capacity * sizeof(record));
    if (temp == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
    } else {
        *records = temp;
    }
}

