    long end_time = 10000000000L; // Large end time for testing.
    long interval = 1000;

    size_t initial_capacity = 10;
    record *records = malloc(initial_capacity * sizeof(record));
    if (initialize_records(&records, &initial_capacity, start_time, end_time, interval) != 0) {
        free(records);
        return -1;
    }

