#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    long timestamp;
    float floatValue;
} Record;

#define ERROR_CODE -1

int initialize_data(long *offsets, int *keys, Record *records, size_t num_elements,
                    int min_value, int max_value, pthread_mutex_t *mutex) {
    if (!offsets || !keys || !records || !mutex) return ERROR_CODE;

    srand((unsigned int)time(NULL));

    // Allocate memory for data structures
    offsets = (long *)malloc(num_elements * sizeof(long));
    keys = (int *)malloc(num_elements * sizeof(int));
    records = (Record *)malloc(num_elements * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return ERROR_CODE;
    }

    // Initialize data structures
    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(mutex);

        offsets[i] = rand() % 1000; // Example initialization

        keys[i] = min_value + (rand() % (max_value - min_value + 1));

        struct timespec ts;
#if defined(_POSIX_TIMERS) && (_POSIX_TIMERS > 0)
        clock_gettime(CLOCK_REALTIME, &ts);
#else
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0; // Fallback if high-resolution timer is unavailable
#endif

        records[i].value = keys[i];
        records[i].timestamp = (long)(ts.tv_sec * 1000000000 + ts.tv_nsec); // Convert to nanoseconds
        records[i].floatValue = ((float)rand() / RAND_MAX) * 100.0f; // Example range

        pthread_mutex_unlock(mutex);
    }

    return 0;
}

void cleanup_data(long *offsets, int *keys, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

int main() {
    size_t num_elements = 1000;
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int result = initialize_data(offsets, keys, records, num_elements, 10, 50, &mutex);
    if (result == ERROR_CODE) {
        fprintf(stderr, "Error initializing data.\n");
        cleanup_data(offsets, keys, records);
        pthread_mutex_destroy(&mutex);
        return EXIT_FAILURE;
    }

    // Simulate use of the data structures...

    cleanup_data(offsets, keys, records);
    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}
```

### Key Points:
