```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Include necessary headers for JSON, compression, and logging
#include "json-c/json.h"
#include "zlib.h" // Example compression library

#define MEMORY_ALIGNMENT 64 // Memory alignment boundary
#define MAX_CONFIG_SIZE (1024 * 1024) // Max size of the configuration in bytes

typedef struct event {
    char type[32];
    uint64_t timestamp;
    int severity;
    uint32_t unique_id;
    struct event* next;
} event;

typedef struct device {
    char status[16];
    float performance_metric;
    time_t last_online_time;
    struct timespec maintenance_window_start;
    struct timespec maintenance_window_end;
    event* events_head;
} device;

typedef struct network_node {
    int server_port;
    char protocol_type[8];
    char auth_credentials[64];
    device* devices_head;
    struct network_node* next;
} network_node;

// Mutex for thread safety
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

void align_malloc(size_t size, void** ptr) {
    *ptr = aligned_alloc(MEMORY_ALIGNMENT, size);
    if (!(*ptr)) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function prototypes
int serialize_config(network_node* head, char** output, size_t* length);
int deserialize_config(const char* input, size_t length, network_node** head);
void compress_data(const void* data, size_t data_len, void** compressed_data, size_t* compressed_length);
void decompress_data(const void* compressed_data, size_t compressed_len, void** decompressed_data, size_t* decompressed_length);

// Serialization function
int serialize_config(network_node* head, char** output, size_t* length) {
    pthread_mutex_lock(&config_mutex);

    // Serialize to JSON first
    json_object* jobj = json_object_new_object();
    while (head != NULL) {
        json_object* server_obj = json_object_new_object();

        json_object_object_add(server_obj, "port", json_object_new_int(head->server_port));
        json_object_object_add(server_obj, "protocol", json_object_new_string(head->protocol_type));
        json_object_object_add(server_obj, "auth_credentials", json_object_new_string(head->auth_credentials));

        device* dev = head->devices_head;
        while (dev != NULL) {
            json_object* dev_obj = json_object_new_object();

            json_object_object_add(dev_obj, "status", json_object_new_string(dev->status));
            json_object_object_add(dev_obj, "performance_metric", json_object_new_double(dev->performance_metric));

            event* evt = dev->events_head;
            while (evt != NULL) {
                json_object* evt_obj = json_object_new_object();

                json_object_object_add(evt_obj, "type", json_object_new_string(evt->type));
                json_object_object_add(evt_obj, "timestamp", json_object_new_int64(evt->timestamp));
                json_object_object_add(evt_obj, "severity", json_object_new_int(evt->severity));

                char unique_id_str[16];
                snprintf(unique_id_str, sizeof(unique_id_str), "%u", evt->unique_id);
                json_object_object_add(evt_obj, "unique_id", json_object_new_string(unique_id_str));

                json_object_object_add(dev_obj, "event", evt_obj);

                evt = evt->next;
            }

            json_object_array_append_new(server_obj, dev_obj);
            dev = dev->next;
        }

        json_object_array_append_new(jobj, server_obj);
        head = head->next;
    }

    // Convert JSON to string
    const char* json_str = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PRETTY | JSON_C_TO_STRING_NOZEROES);
    size_t json_len = strlen(json_str);

    if (json_len > MAX_CONFIG_SIZE) {
        fprintf(stderr, "Configuration exceeds maximum allowed size\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    // Compress the JSON data
    void* compressed_data;
    size_t compressed_length;
    compress_data((const void*)json_str, json_len, &compressed_data, &compressed_length);

    if (compressed_length > MAX_CONFIG_SIZE) {
        fprintf(stderr, "Compressed configuration exceeds maximum allowed size\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    *output = malloc(compressed_length);
    if (!*output) {
        fprintf(stderr, "Memory allocation failed for output buffer\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    memcpy(*output, compressed_data, compressed_length);
    free(compressed_data);

    *length = compressed_length;

    json_object_put(jobj); // Free JSON object

    pthread_mutex_unlock(&config_mutex);
    return 0;
}

// Deserialization function
int deserialize_config(const char* input, size_t length, network_node** head) {
    pthread_mutex_lock(&config_mutex);

    if (length > MAX_CONFIG_SIZE) {
        fprintf(stderr, "Input configuration exceeds maximum allowed size\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    // Decompress the data
    void* decompressed_data;
    size_t decompressed_length;
    decompress_data(input, length, &decompressed_data, &decompressed_length);

    if (decompressed_length > MAX_CONFIG_SIZE) {
        fprintf(stderr, "Decompressed configuration exceeds maximum allowed size\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    // Parse JSON
    json_object* jobj = json_tokener_parse((const char*)decompressed_data);

    if (!jobj) {
        fprintf(stderr, "Failed to parse JSON\n");
        pthread_mutex_unlock(&config_mutex);
        return -1;
    }

    network_node* new_head = NULL;
    network_node** last_node_ptr = &new_head;

    json_object_array_foreach(jobj, i, val) {
        *last_node_ptr = malloc(sizeof(network_node));
        if (!(*last_node_ptr)) {
            fprintf(stderr, "Memory allocation failed for network node\n");
            pthread_mutex_unlock(&config_mutex);
            json_object_put(jobj); // Free JSON object
            return -1;
        }

        (*last_node_ptr)->devices_head = NULL;

        json_object_object_foreach(val, key, val_obj) {
            if (strcmp(key, "port") == 0)
                (*last_node_ptr)->server_port = json_object_get_int(val_obj);
            else if (strcmp(key, "protocol") == 0)
                strncpy((*last_node_ptr)->protocol_type, json_object_get_string(val_obj), sizeof((*last_node_ptr)->protocol_type) - 1);
            else if (strcmp(key, "auth_credentials") == 0)
                strncpy((*last_node_ptr)->auth_credentials, json_object_get_string(val_obj), sizeof((*last_node_ptr)->auth_credentials) - 1);

            if (strcmp(key, "device") == 0) {
                device* new_dev = NULL;
                device** last_dev_ptr = &new_dev;

                json_object_array_foreach(val_obj, j, dev_val_obj) {
                    *last_dev_ptr = malloc(sizeof(device));
                    if (!(*last_dev_ptr)) {
                        fprintf(stderr, "Memory allocation failed for device\n");
                        pthread_mutex_unlock(&config_mutex);
                        json_object_put(jobj); // Free JSON object
                        return -1;
                    }

                    memset((*last_dev_ptr), 0, sizeof(device)); // Initialize to zero

                    (*last_dev_ptr)->events_head = NULL;

                    json_object_object_foreach(dev_val_obj, dev_key, dev_val) {
                        if (strcmp(dev_key, "status") == 0)
                            strncpy((*last_dev_ptr)->status, json_object_get_string(dev_val), sizeof((*last_dev_ptr)->status) - 1);
                        else if (strcmp(dev_key, "performance_metric") == 0)
                            (*last_dev_ptr)->performance_metric = json_object_get_double(dev_val);

                        if (strcmp(dev_key, "event") == 0) {
                            event* new_evt = NULL;
                            event** last_evt_ptr = &new_evt;

                            json_object_object_foreach(dev_val, evt_key, evt_val) {
                                *last_evt_ptr = malloc(sizeof(event));
                                if (!(*last_evt_ptr)) {
                                    fprintf(stderr, "Memory allocation failed for event\n");
                                    pthread_mutex_unlock(&config_mutex);
                                    json_object_put(jobj); // Free JSON object
                                    return -1;
                                }

                                memset((*last_evt_ptr), 0, sizeof(event)); // Initialize to zero

                                if (strcmp(evt_key, "type") == 0)
                                    strncpy((*last_evt_ptr)->type, json_object_get_string(evt_val), sizeof((*last_evt_ptr)->type) - 1);
                                else if (strcmp(evt_key, "timestamp") == 0)
                                    (*last_evt_ptr)->timestamp = json_object_get_int64(evt_val);
                                else if (strcmp(evt_key, "severity") == 0)
                                    (*last_evt_ptr)->severity = json_object_get_int(evt_val);
                                else if (strcmp(evt_key, "unique_id") == 0) {
                                    char* unique_id_str = strdup(json_object_get_string(evt_val));
                                    sscanf(unique_id_str, "%u", &(*last_evt_ptr)->unique_id);
                                    free(unique_id_str);
                                }

                                *last_evt_ptr = (*last_evt_ptr)->next;
                            }
                        }

                        *last_dev_ptr = (*last_dev_ptr)->next;
                    }

                    (*last_node_ptr)->devices_head = new_dev; // Link device to network node
                }
            }
        }

        *last_node_ptr = (*last_node_ptr)->next;
    }

    *head = new_head;

    json_object_put(jobj); // Free JSON object

    pthread_mutex_unlock(&config_mutex);
    return 0;
}

// Compression function using zlib
void compress_data(const void* data, size_t data_len, void** compressed_data, size_t* compressed_length) {
    uLongf dest_len = compressBound(data_len);
    *compressed_data = malloc(dest_len);

    if (compress((Bytef*)*compressed_data, &dest_len, (const Bytef*)data, data_len) != Z_OK) {
        fprintf(stderr, "Compression failed\n");
        free(*compressed_data);
        *compressed_data = NULL;
    }

    *compressed_length = dest_len;
}

// Decompression function using zlib
void decompress_data(const void* compressed_data, size_t compressed_len, void** decompressed_data, size_t* decompressed_length) {
    uLongf dest_len = compressed_len * 10; // Initial guess for decompressed length

    *decompressed_data = malloc(dest_len);

    if (uncompress((Bytef*)*decompressed_data, &dest_len, (const Bytef*)compressed_data, compressed_len) != Z_OK) {
        fprintf(stderr, "Decompression failed\n");
        free(*decompressed_data);
        *decompressed_data = NULL;
    }

    *decompressed_length = dest_len;
}

// Implement additional functions for initialization and handling configuration versioning
