['```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define MAX_STRING_LEN 16

typedef struct Item {
    int key;
    char string[MAX_STRING_LEN];
    struct Item* next;
} Item;

typedef struct Node {
    double value;
    Item* items_head;
} Node;

void free_items(Item* head) {
    while (head != NULL) {
        Item* temp = head;
        head = head->next;
        free(temp);
    }
}

void free_nodes(Node** nodes, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free_items(nodes[i]->items_head);
        free(nodes[i]);
    }
    free(nodes);
}

Node* allocate_and_initialize_node(size_t item_count) {
    Node* node = aligned_alloc(64, sizeof(Node)); // Align to cache line size
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for Node\n");
        return NULL;
    }

    int random_int = rand() % 100 + 1; // Random integer in range [1, 100]
    node->value = sqrt((double)random_int);

    Item* prev_item = NULL;
    for (size_t i = 0; i < item_count; ++i) {
        Item* new_item = aligned_alloc(64, sizeof(Item)); // Align to cache line size
        if (!new_item) {
            fprintf(stderr, "Failed to allocate memory for Item\n");
            free_items(node->items_head);
            free(node);
            return NULL;
        }

        new_item->key = i; // Unique integer key
        for (size_t j = 0; j < MAX_STRING_LEN - 1; ++j) {
            if ((rand() % 2)) {
                new_item->string[j] = 'A' + rand() % 26;
            } else {
                new_item->string[j] = 'a' + rand() % 26;
            }
        }
        new_item->string[MAX_STRING_LEN - 1] = '\0';
        new_item->next = NULL;

        if (prev_item == NULL) {
            node->items_head = new_item;
        } else {
            prev_item->next = new_item;
        }

        prev_item = new_item;
    }
    return node;
}

void run_test(const char* label, void (*test_func)(void)) {
    printf("Running test: %s\n", label);
    test_func();
    // Reset blueslip or other mocking libraries here
    printf("Test completed: %s\n", label);
}

void example_test() {
    size_t node_count = 10;
    Node** nodes = aligned_alloc(64, sizeof(Node*) * node_count); // Align to cache line size
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for Nodes array\n");
        return;
    }

    for (size_t i = 0; i < node_count; ++i) {
        nodes[i] = allocate_and_initialize_node(5);
        if (!nodes[i]) {
            free_nodes(nodes, i); // Free previously allocated nodes
            break;
        }
    }

    // Simulate network communication
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Socket creation failed\n");
        return;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported\n");
        close(sockfd);
        return;
    }

    while (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        printf("Retrying connection...\n");
        sleep(1); // Brief pause before retrying
    }

    printf("Connected to server at 127.0.0.1:8080\n");

    close(sockfd);
    free_nodes(nodes, node_count);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    run_test("Example Test", example_test);

    return 0;
}
```

### Key Points:
- **Memory Alignment**: Use `aligned_alloc` for cache line alignment.
- **Error Handling**: Check allocation results and handle errors gracefully.
- **Node and Item Initialization**: Populate nodes with a double derived from the square root of a random integer, and items with unique keys and random strings.
- **Network Communication**: Establish a connection to a server using sockets, retrying on failure.
- **Resource Management**: Free allocated memory properly to prevent leaks.']

['Creating a complete scalable, distributed document indexing system in C++ involves many components. Below is an outline of key classes and methods to get you started on such a complex project:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <fstream>
#include <shared_mutex> // For shared_lock and unique_lock

// Document structure
struct Document {
    int id;
    std::string timestamp;
    std::string author;
    std::vector<std::string> tags;
    std::string content; // Textual data, could be JSON/BSON for mixed types
};

// Node class representing a node in the distributed system
class Node {
public:
    Node() : load(0) {}

    void insertDocument(const Document& doc);
    void deleteDocument(int id);
    std::vector<Document> queryDocuments(const std::string& field, const std::string& value);

private:
    std::unordered_map<int, Document> inMemoryIndex; // In-memory hash table
    std::mutex indexMutex;
    int load; // Current system load

    void syncToDisk();
};

// DistributedSystem class managing multiple nodes
class DistributedSystem {
public:
    DistributedSystem(int nodeCount);

    void insertDocument(const Document& doc);
    void deleteDocument(int id);
    std::vector<Document> queryDocuments(const std::string& field, const std::string& value);

private:
    std::vector<Node> nodes;
    std::mutex systemMutex;

    int getNodeIndexForDocument(const Document& doc); // Hash or load balancing logic
};

// Example implementation of Node methods

void Node::insertDocument(const Document& doc) {
    std::unique_lock<std::mutex> lock(indexMutex);

    if (inMemoryIndex.find(doc.id) != inMemoryIndex.end()) return; // Prevent duplicate primary keys

    inMemoryIndex[doc.id] = doc;

