These functions are optimized for performance and resource management, considering large-scale data handling.']

['Below is a C implementation that fulfills the described requirements. This code uses POSIX threads and includes necessary synchronization mechanisms such as mutexes to ensure thread-safe operations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    char *id;
    long offset;
    double value;
    struct Record *next; // for handling collisions in the hash table
} Record;

#define TABLE_SIZE 1024

Record **hashTable[TABLE_SIZE];
pthread_mutex_t lock[TABLE_SIZE];

unsigned int hashFunction(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % TABLE_SIZE;
}

void initializeTable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hashTable[i] = NULL;
        pthread_mutex_init(&lock[i], NULL);
    }
}

Record* createRecord(const char *id, long offset, double value) {
    Record *newRecord = malloc(sizeof(Record));
    if (!newRecord) return NULL;

    newRecord->id = strdup(id);
    newRecord->offset = offset;
    newRecord->value = value;
    newRecord->next = NULL;

    return newRecord;
}

void insertRecord(const char *id, long offset, double value) {
    unsigned int index = hashFunction(id);

    pthread_mutex_lock(&lock[index]);

    Record **ptr = &hashTable[index];
    while (*ptr) {
        if (strcmp((*ptr)->id, id) == 0) break;
        ptr = &(*ptr)->next;
    }

    if (!*ptr) { // not found
        *ptr = createRecord(id, offset, value);
    } else { // update existing record
        (*ptr)->offset = offset;
        (*ptr)->value = value;
    }

    pthread_mutex_unlock(&lock[index]);
}

void freeTable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *entry = hashTable[i];

        while (entry) {
            Record *temp = entry;
            entry = entry->next;

            free(temp->id);
            free(temp);
        }

        pthread_mutex_destroy(&lock[i]);
    }
}

void initializeFromCSV(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char id[64], valueStr[64];
        long offset;

        if (sscanf(line, "%63[^,],%ld,%63s", id, &offset, valueStr) == 3) {
            double value = atof(valueStr);

            insertRecord(id, offset, value);
        }
    }

    fclose(file);
}

void* threadSafeRead(void *arg) {
    const char *id = (const char *)arg;

    unsigned int index = hashFunction(id);

    pthread_mutex_lock(&lock[index]);

    Record *entry = hashTable[index];
    while (entry) {
        if (strcmp(entry->id, id) == 0) break;
        entry = entry->next;
    }

    pthread_mutex_unlock(&lock[index]);

    if (entry) {
        printf("ID: %s, Offset: %ld, Value: %.2f\n", entry->id, entry->offset, entry->value);
    } else {
        printf("Record not found for ID: %s\n", id);
    }

    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv-file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initializeTable();
    initializeFromCSV(argv[1]);

    // Simulating concurrent access
    pthread_t threads[5];
    char *ids[] = {"id1", "id2", "id3", "id4", "id5"};

    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, threadSafeRead, ids[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    freeTable();

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Hash Table**: Used for efficient lookup. It combines with linked lists to handle collisions.
- **Mutexes**: Each bucket in the hash table has its own mutex to ensure thread-safe access during reads and writes.
- **CSV Parsing**: Parses input file, handling errors gracefully if the format is incorrect or a line can't be read properly.
- **Concurrency**: Uses POSIX threads (`pthread`) for simulating concurrent operations. The design ensures that reading and writing do not cause data races.
- **Memory Management**: Includes proper allocation and deallocation to prevent leaks.

This solution provides a balance between efficiency, memory usage, and concurrency safety while handling large datasets. Adjust `TABLE_SIZE` based on expected load or available resources for optimal performance.']

