['Below is a C code implementation that addresses your requirements for initializing and populating an array of Network Interface Control Block (NICB) structures.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_NICBS 10000

typedef struct {
    unsigned char mac[6];
} MAC_HEADER;

typedef struct {
    MAC_HEADER header;
    unsigned int vlan_tag;
    unsigned char priority;
    unsigned char eth_mac[6][2]; // Two addresses for each NICB
    unsigned short ip_checksum; // Assume function to calculate checksum is available
} NICB;

typedef enum {
    INTERFACE_GIGABIT,
    INTERFACE_FAST,
    INTERFACE_WLAN
} InterfaceType;

typedef struct {
    int size;
    InterfaceType type;
    void (*mac_valid_callback)(unsigned char *mac, int index);
    unsigned char backup_mac_list[MAX_NICBS][6];
    int backup_count;
    int seed;
    FILE *log_file;
} NICBConfig;

void log_message(NICBConfig *config, const char *message) {
    if (config->log_file) {
        fprintf(config->log_file, "%s\n", message);
        fflush(config->log_file);
    }
}

int is_mac_valid(unsigned char *mac, int index, void (*callback)(unsigned char *, int)) {
    return callback(mac, index);
}

unsigned short calculate_checksum(unsigned char *data, size_t length) {
    unsigned long sum = 0;
    for (size_t i = 0; i < length; i += 2) {
        sum += (data[i] << 8) + data[i + 1];
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum;
}

void *initialize_nicb(void *arg) {
    NICBConfig *config = (NICBConfig *)arg;
    int start_index, end_index, i, mac_failures = 0;
    pthread_t thread_id = pthread_self();

    // Determine the range of indices this thread will handle
    int threads_per_nicb = config->size / MAX_NICBS; 
    int my_thread_id = (int)(thread_id % (size_t)pthread_self()); // Simplified, normally derived from a more reliable method
    start_index = my_thread_id * threads_per_nicb;
    end_index = ((my_thread_id + 1) * threads_per_nicb < config->size) ? (my_thread_id + 1) * threads_per_nicb : config->size;

    for (i = start_index; i < end_index; ++i) {
        NICB *nicb = &config->nicbs[i];

        // Generate VLAN tag with seed
        srand(config->seed + i);
        nicb->vlan_tag = rand() % 4096;
        nicb->priority = (rand() % 8);

        unsigned char mac1[6] = {0x00, 0x16, 0x3e, 0x00, 0x00, 0x01}; // Example MAC
        int valid_mac_index = -1;

        if (!is_mac_valid(mac1, i, config->mac_valid_callback)) {
            for (int j = 0; j < config->backup_count; ++j) {
                if (is_mac_valid(config->backup_mac_list[j], i, config->mac_valid_callback)) {
                    memcpy(nicb->header.mac, config->backup_mac_list[j], 6);
                    valid_mac_index = j;
                    break;
                }
            }
        } else {
            memcpy(nicb->header.mac, mac1, 6);
        }

        if (valid_mac_index == -1) {
            log_message(config, "Failed to validate MAC address for NICB index: %d", i);
            ++mac_failures;
            continue; // Skip this NICB
        } else if (!is_mac_valid(nicb->header.mac, i, config->mac_valid_callback)) {
            log_message(config, "Invalid MAC address after backup check for NICB index: %d", i);
            ++mac_failures;
            continue;
        }

        memcpy(nicb->eth_mac[0], mac1, 6); // First Ethernet MAC
        nicb->eth_mac[1][5] = (nicb->vlan_tag >> 8) & 0xFF; // VLAN Tag part
        nicb->eth_mac[1][4] = nicb->vlan_tag & 0xFF;

        // Dummy data for checksum calculation
        unsigned char ip_data[20];
        memset(ip_data, 'A', sizeof(ip_data));
        nicb->ip_checksum = calculate_checksum(ip_data, sizeof(ip_data));

    }
    log_message(config, "Thread %ld handled NICBs from %d to %d with %d MAC validation failures", thread_id, start_index, end_index, mac_failures);
    pthread_exit(NULL);
}

int initialize_nicbs(NICBConfig *config) {
    if (!config || config->size <= 0 || !config->mac_valid_callback || config->log_file == NULL) {
        log_message(config, "Invalid configuration parameters");
        return -1;
    }

    // Validate interface type
    switch (config->type) {
        case INTERFACE_GIGABIT:
        case INTERFACE_FAST:
        case INTERFACE_WLAN:
            break; 
        default:
            log_message(config, "Unsupported interface type: %d", config->type);
            return -2;
    }

    int num_threads = (config->size > MAX_NICBS) ? MAX_NICBS : 1;
    pthread_t threads[num_threads];

    // Memory allocation for NICBs
    config->nicbs = malloc(config->size * sizeof(NICB));
    if (!config->nicbs) {
        log_message(config, "Memory allocation failed");
        return -3;
    }

    // Create threads for parallel initialization
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_nicb, config)) {
            log_message(config, "Failed to create thread %d", i);
            free(config->nicbs);
            return -4;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_message(config, "Initialization completed successfully");
    return 0;
}
```

### Explanation

- **NICB and MAC_HEADER structures**: Define the necessary data structures.
- **NICBConfig struct**: Holds configuration parameters for initialization, including logging and validation functions.
- **Logging mechanism**: Uses a file pointer in `NICBConfig` to log messages.
