use std::env;
use std::process::{Command, ExitStatus};
use std::time::Instant;
use sysinfo::{ProcessExt, System, SystemExt};

fn get_resident_set_size(pid: u32) -> Option<u64> {
    let mut system = System::new_all();
    system.refresh_all();

    for (pid2, proc) in system.get_processes() {
        if pid == *pid2 {
            return proc.get_memory();
        }
    }

    None
}

fn compile_rust_source(source_file: &str) -> Result<(), String> {
    let start_time = Instant::now();
    let output = Command::new("rustc")
        .arg(source_file)
        .output();

    match output {
        Ok(output) => {
            if !output.status.success() {
                return Err(String::from_utf8_lossy(&output.stderr).to_string());
            }
        }
        Err(e) => return Err(format!("Failed to execute command: {}", e)),
    }

    let duration = start_time.elapsed();
    println!("Compilation completed in {:?}", duration);

    // Get resident set size before and after compilation
    let pid = env::current_pid();
    if let (Some(before), Some(after)) = (get_resident_set_size(pid as u32), get_resident_set_size(pid as u32)) {
        println!("Resident Set Size: Before = {} KB, After = {} KB", before / 1024, after / 1024);
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <source_file>", args[0]);
        std::process::exit(1);
    }

    match compile_rust_source(&args[1]) {
        Ok(_) => println!("Compilation successful"),
        Err(e) => eprintln!("Error during compilation: {}", e),
    }
}
