use std::process::{Command, Stdio};
use std::time::Instant;
use sysinfo::{ProcessExt, System, ProcessorExt};

fn compile_and_profile_rust(source_file: &str) {
    let system = System::new_all();
    system.refresh_all();

    let mut command = Command::new("rustc")
        .arg(source_file)
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    match command.output() {
        Ok(output) => {
            if output.status.success() {
                println!("Compilation successful.");
            } else {
                eprintln!("Compilation failed with error:");
                eprintln!("{}", String::from_utf8_lossy(&output.stderr));
            }
        },
        Err(e) => {
            eprintln!("Failed to start compilation process: {}", e);
        }
    }

    let elapsed_time = Instant::now();
    let current_process = system.get_process(command.id()).unwrap_or_else(|| {
        eprintln!("Could not get the current process info.");
        std::process::exit(1);
    });

    if let Some(cpu_usage) = current_process.cpu_usage() {
        println!("CPU usage: {}%", cpu_usage);
    }

    if let Some(memory_info) = current_process.memory() {
        println!(
            "Memory Usage (RSS): {} KB",
            memory_info.rss as f64 / 1024.0
        );
    }

    let duration = elapsed_time.elapsed();
    println!("Compilation time: {:?}", duration);
}
