#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long *ptr;
    int key;
} Record;

void initialize_structures(int offset_size, unsigned int mask_value, long range_min, long range_max) {
    if (offset_size <= 0) return; // Handle zero-length arrays

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    long **offset_array = (long **)malloc(offset_size * sizeof(long *));
    int *key_array = (int *)malloc(offset_size * sizeof(int));
    Record *record_array = (Record *)malloc(offset_size * sizeof(Record));

    if (!offset_array || !key_array || !record_array) {
        // Free any allocated memory before returning
        free(offset_array);
        free(key_array);
        free(record_array);
        return;
    }

    for (int i = 0; i < offset_size; ++i) {
        offset_array[i] = malloc(sizeof(long));
        if (!offset_array[i]) {
            // Free previously allocated memory before exiting
            while (--i >= 0) free(offset_array[i]);
            free(offset_array);
            free(key_array);
            free(record_array);
            return;
        }
        *offset_array[i] = i; // Initialize with unique sequential values

        key_array[i] = i & mask_value; // Derive keys using bitwise AND
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < offset_size; ++i) {
        pthread_mutex_lock(&mutex);

        record_array[i].ptr = offset_array[i % offset_size]; // Circular reference
        record_array[i].key = key_array[i];

        long random_value = range_min + rand() % ((range_max - range_min) + 1);
        *record_array[i].ptr = random_value;

        pthread_mutex_unlock(&mutex);
    }

    // Clean up allocated memory
    for (int i = 0; i < offset_size; ++i) {
        free(offset_array[i]);
    }
    free(offset_array);
    free(key_array);
    free(record_array);

    pthread_mutex_destroy(&mutex);
}
```

