['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_SIZE 1000
#define RANGE_LOW 0
#define RANGE_HIGH 1000000

typedef struct Record {
    long offset;
    double value;
    struct Record* next;
} Record;

typedef struct DataSet {
    long* offsets;
    int* keys;
    Record* records;
    Record* head; // For linked list
    size_t size;
    pthread_mutex_t lock; // To ensure thread safety for concurrent access
} DataSet;

void free_memory(DataSet* dataset) {
    if (dataset->offsets) free(dataset->offsets);
    if (dataset->keys) free(dataset->keys);
    Record* current = dataset->head;
    while (current) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
}

void generate_random_numbers(DataSet* dataset, long range_low, long range_high) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < dataset->size; ++i) {
        dataset->offsets[i] = rand() % (range_high - range_low + 1) + range_low;
        dataset->keys[i] = (int)i;
    }
}

void* populate_records(void* arg) {
    DataSet* dataset = (DataSet*)arg;
    pthread_mutex_lock(&dataset->lock);
    for (size_t i = 0; i < dataset->size; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        record->offset = dataset->offsets[i];
        record->value = (double)i;
        record->next = dataset->head;
        dataset->head = record;
    }
    pthread_mutex_unlock(&dataset->lock);
    return NULL;
}

int initialize_dataset(DataSet* dataset, size_t size) {
    if (size > MAX_SIZE) {
        fprintf(stderr, "Size exceeds maximum limit\n");
        return -1;
    }

    dataset->offsets = malloc(size * sizeof(long));
    dataset->keys = malloc(size * sizeof(int));
    pthread_mutex_init(&dataset->lock, NULL);
    dataset->head = NULL;

    if (!dataset->offsets || !dataset->keys) {
        perror("Failed to allocate memory");
        free_memory(dataset);
        return -1;
    }

    dataset->size = size;

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, populate_records, dataset)) {
        perror("Thread creation failed");
        free_memory(dataset);
        return -1;
    }

    pthread_join(thread_id, NULL);

    // Initialize records
    for (size_t i = 0; i < size; ++i) {
        Record* current = dataset->head;
        int pos = 0;
        while (current) {
            current->value += pos++;
            current = current->next;
        }
    }

    return 0;
}

void serialize_dataset(DataSet* dataset, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(&dataset->size, sizeof(size_t), 1, file);
    Record* current = dataset->head;
    while (current) {
        fwrite(&(current->offset), sizeof(long), 1, file);
        fwrite(&(current->value), sizeof(double), 1, file);
        current = current->next;
    }

    fclose(file);
}

int deserialize_dataset(DataSet** dataset_ptr, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    DataSet* dataset = malloc(sizeof(DataSet));
    if (!dataset) {
        perror("Failed to allocate memory for dataset");
        fclose(file);
        return -1;
    }

    fread(&dataset->size, sizeof(size_t), 1, file);
    dataset->offsets = malloc(dataset->size * sizeof(long));
    dataset->keys = malloc(dataset->size * sizeof(int));

    if (!dataset->offsets || !dataset->keys) {
        perror("Failed to allocate memory");
        free_memory(dataset);
        fclose(file);
        return -1;
    }

    pthread_mutex_init(&dataset->lock, NULL);
    dataset->head = NULL;

    for (size_t i = 0; i < dataset->size; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory");
            free_memory(dataset);
            fclose(file);
            return -1;
        }
        fread(&(record->offset), sizeof(long), 1, file);
        fread(&(record->value), sizeof(double), 1, file);
        record->next = dataset->head;
        dataset->head = record;
    }

    *dataset_ptr = dataset;
    fclose(file);

    return 0;
}

int main() {
    DataSet dataset;
    if (initialize_dataset(&dataset, 500) == 0) {
        serialize_dataset(&dataset, "dataset.bin");

        DataSet* loaded_dataset;
        if (deserialize_dataset(&loaded_dataset, "dataset.bin") == 0) {
            free_memory(loaded_dataset);
        }

        free_memory(&dataset);
    }
    return 0;
}
