#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2
#define ALIGNMENT 32

typedef struct {
    unsigned int device_id;
    char mac_address[18]; // For "XX:XX:XX:XX:XX:XX"
} MAC_HEADER;

typedef struct {
    unsigned short vlan_tag;
    unsigned char priority;
} VLAN_TAG;

typedef struct {
    time_t timestamp;
    MAC_HEADER header;
    VLAN_TAG vlan;
    // Add other fields as necessary
} SensorReading;

typedef struct {
    SensorReading *readings;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SensorDataStore;

static void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
#if defined(_POSIX_C_SOURCE)
    posix_memalign(&ptr, alignment, size);
#elif defined(_MSC_VER)
    ptr = _aligned_malloc(size, alignment);
#else
    ptr = malloc(size + alignment);
    if (ptr) {
        void* aligned_ptr = (void*)(((size_t)(ptr) + alignment - 1) & ~(alignment - 1));
        ((char*)aligned_ptr)[-((char*)aligned_ptr - (char*)(ptr))] = (char)(ptrdiff_t)((char*)(ptr) - (char*)aligned_ptr);
        ptr = aligned_ptr;
    }
#endif
    return ptr;
}

static void aligned_free(void* ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free((void*)((char*)ptr - ((size_t)(ptr) & (ALIGNMENT - 1))));
#endif
}

SensorDataStore* create_sensor_data_store() {
    SensorDataStore* store = malloc(sizeof(SensorDataStore));
    if (!store) return NULL;

    store->capacity = INITIAL_SIZE;
    store->count = 0;
    store->readings = aligned_alloc(ALIGNMENT, sizeof(SensorReading) * store->capacity);
    if (!store->readings) {
        free(store);
        return NULL;
    }

    pthread_mutex_init(&store->lock, NULL);

    return store;
}

int add_sensor_reading(SensorDataStore* store, SensorReading reading) {
    if (!store || !store->readings) return -1;

    pthread_mutex_lock(&store->lock);

    if (store->count == store->capacity) {
        size_t new_capacity = store->capacity * GROWTH_FACTOR;
        SensorReading* new_readings = aligned_alloc(ALIGNMENT, sizeof(SensorReading) * new_capacity);
        if (!new_readings) {
            pthread_mutex_unlock(&store->lock);
            return -1; // Memory allocation failure
        }

        memcpy(new_readings, store->readings, sizeof(SensorReading) * store->count);
        aligned_free(store->readings);
        store->readings = new_readings;
        store->capacity = new_capacity;
    }

    store->readings[store->count++] = reading;

    pthread_mutex_unlock(&store->lock);

    return 0; // Success
}

void release_sensor_data_store(SensorDataStore* store) {
    if (store) {
        if (store->readings) aligned_free(store->readings);
        pthread_mutex_destroy(&store->lock);
        free(store);
    }
}

// Performance monitoring functions and logging could be added here

int main() {
    SensorDataStore* store = create_sensor_data_store();
    if (!store) {
        fprintf(stderr, "Failed to create sensor data store\n");
        return 1;
    }

    // Example usage
    SensorReading reading = { .timestamp = time(NULL), .header = {.device_id = 1, .mac_address = "00:11:22:33:44:55"} };
    if (add_sensor_reading(store, reading) != 0) {
        fprintf(stderr, "Failed to add sensor reading\n");
    }

    // Clean up
    release_sensor_data_store(store);

    return 0;
}
