#define RANDOM_RANGE_MAX 100

typedef struct {
    int value;
    long offset;
    int key;
    int ref_count;
} record;

static pthread_mutex_t resource_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to align memory allocation.
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

// Exponential backoff delay for retries
static int exponential_backoff(int attempt) {
    const int base_delay_ms = 100; // Base delay in milliseconds
    int delay_ms = base_delay_ms * (1 << attempt);
    if (delay_ms > 5000) {
        delay_ms = 5000;
    }
    return delay_ms / 1000; // convert to seconds for sleep function
}

// Simulated API call to fetch theme configuration.
