int allocate_and_initialize(int offset_count, int min_value, int max_value, int value_limit) {
    if (pthread_mutex_lock(&lock) != 0) {
        fprintf(stderr, "Failed to acquire mutex\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    long *offsets = malloc(offset_count * sizeof(long));
    int *keys = malloc(offset_count * sizeof(int));
    record *records = malloc(offset_count * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failure\n");
        pthread_mutex_unlock(&lock);
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Initialize offsets
    for (int i = 0; i < offset_count; ++i) {
        offsets[i] = i * 1000L; // Example initialization
    }

    // Initialize keys with unique values
    int key_set[256] = {0}; // Assuming max value fits in a byte, adjust as needed
    for (int i = 0; i < offset_count;) {
        int new_key = rand() % (max_value - min_value + 1) + min_value;
        if (!key_set[new_key]) {
            keys[i] = new_key;
            key_set[new_key] = 1;
            ++i;
        }
    }

    // Initialize records with random values within limit
    int current_sum = 0;
    for (int i = 0; i < offset_count;) {
        int rand_value = rand() % (max_value - min_value + 1) + min_value;
        if (current_sum + rand_value <= value_limit) {
            records[i].value = rand_value;
            current_sum += rand_value;
            ++i;
        }
    }

    // Check if allocation and initialization were successful
    if (i < offset_count) {
        fprintf(stderr, "Failed to initialize all records within the limit\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return UNIQUE_KEY_FAILURE;
    }

    printf("Initialization successful\n");

    // Release mutex lock
    pthread_mutex_unlock(&lock);

    // Normally, you'd return pointers or references to these structures.
    // For the purpose of this example, just returning success code.
    free(offsets); // In a real application, manage lifetime appropriately
    free(keys);
    free(records);

    return 0;
}

