#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <time.h>

#define MAX_ELEMENTS 1024
#define CHUNK_SIZE 512
#define ALIGNMENT 16
#define DEFAULT_THEME_DIR "/default/theme/dir"
#define SHA256_DIGEST_LENGTH 32

typedef struct {
    int value;
    long offset;
    int key;
    int ref_count;
} record_t;

typedef struct {
    record_t *records;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicResourceManager;

void align_alloc(size_t *ptr, size_t alignment) {
    void *mem = malloc(*ptr);
    if (mem == NULL) return;
    size_t addr = (size_t)mem;
    size_t offset = alignment - (addr % alignment);
    *ptr = offset ? (*ptr + offset) : *ptr;
    mem = (void *)((uintptr_t)mem + offset);
    *(void **)ptr = mem;
}

