void log_message(int level, const char *message) {
    if (level >= LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}

int is_power_of_two(size_t x) {
    return (x != 0) && ((x & (x - 1)) == 0);
}

size_t align_size(size_t size, size_t alignment) {
    if (!is_power_of_two(alignment)) {
        fprintf(stderr, "Alignment must be a power of two.\n");
        exit(EXIT_FAILURE);
    }
    return (size + alignment - 1) & ~(alignment - 1);
}

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate aligned memory.");
        return NULL;
    }
    return ptr;
}

int init_records(ResourceManager *rm, int num_records, int value_range) {
    pthread_mutex_lock(&rm->lock);
    rm->count = 0;

    while (rm->count < num_records && rm->count < MAX_RECORDS) {
        size_t chunk_size = CHUNK_SIZE;
        if ((num_records - rm->count) < CHUNK_SIZE) {
            chunk_size = num_records - rm->count;
        }

        for (size_t i = 0; i < chunk_size; ++i) {
            if (rm->count >= MAX_RECORDS) break;

            Record *record = aligned_alloc(ALIGNMENT, sizeof(Record));
            if (!record) {
                log_message(LOG_LEVEL_ERROR, "Memory allocation failed.");
                pthread_mutex_unlock(&rm->lock);
                return -1;
            }

            record->value = rand() % value_range;
            record->offset = (long)(rand() * 1000.0);
            record->key = rm->count; // Ensure unique keys
            record->ref_count = 0;

            rm->records[rm->count] = record;
            ++rm->count;
        }
    }

    pthread_mutex_unlock(&rm->lock);
    return 0;
}

void verify_integrity(ResourceManager *rm) {
    pthread_mutex_lock(&rm->lock);

    for (size_t i = 0; i < rm->count; ++i) {
        Record *record = rm->records[i];
        if (!record || record->key != i) {
            log_message(LOG_LEVEL_ERROR, "Data integrity check failed.");
        }
    }

    pthread_mutex_unlock(&rm->lock);
}

void DynamicResourceManagerInit(int num_records, int value_range) {
    ResourceManager rm;
    memset(&rm, 0, sizeof(ResourceManager));
    pthread_mutex_init(&rm.lock, NULL);

    srand(time(NULL)); // Seed random number generator

    if (init_records(&rm, num_records, value_range) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to initialize records.");
        return;
    }

    verify_integrity(&rm);
    log_message(LOG_LEVEL_INFO, "Resource manager initialized successfully.");

    // Simulate theme management and API integration
    char *theme_dir = getenv("THEME_DIR");
    if (!theme_dir) {
        theme_dir = DEFAULT_THEME_DIR;
    }
    log_message(LOG_LEVEL_DEBUG, ("Using theme directory: %s", theme_dir));

    // Simulated external API call with exponential backoff retry logic
    int retries = 0;
    while (retries < 5) {
        int success = rand() % 2; // Randomize for simulation
        if (success) break;

        sleep((1 << retries)); // Exponential backoff
        ++retries;
    }

    log_message(LOG_LEVEL_INFO, "External API call completed.");

    // Clean up
    pthread_mutex_destroy(&rm.lock);
}

int main() {
    DynamicResourceManagerInit(1000, 100);
    return 0;
}
