    for (int i = 0; i < *offset_array_size; ++i) {
        (*records)[i] = (Record *)malloc(sizeof(Record));
        if (!(*records)[i]) {
            log_warning("Failed to allocate memory for a record");
            // Free previously allocated records
            while (--i >= 0) {
                free((*records)[i]);
