// Generates random integer between min and max (inclusive)
int get_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Checks if two ranges overlap
bool are_ranges_overlapping(const Range *a, const Range *b) {
    bool a_max_cond = (a->inclusive_max ? a->max >= b->min : a->max > b->min);
    bool b_max_cond = (b->inclusive_max ? b->max >= a->min : b->max > a->min);

    return ((a->min < b->max || (a->inclusive_min && a->min == b->max)) &&
            (b->min < a->max || (b->inclusive_min && b->min == a->max)) &&
            a_max_cond && b_max_cond);
}

// Merges overlapping ranges into contiguous blocks
void merge_ranges(RangeManager *manager) {
    // Example implementation: Sort and merge overlapping or adjacent ranges
    if (manager->range_count <= 1) return;

    qsort(manager->ranges, manager->range_count, sizeof(Range), 
          [](const void* a, const void* b) -> int {
              Range *ra = (Range *)a;
              Range *rb = (Range *)b;
              if (ra->min != rb->min)
                  return ra->min - rb->min;
              if (ra->inclusive_min && !rb->inclusive_min)
                  return -1;
              if (!ra->inclusive_min && rb->inclusive_min)
                  return 1;
              if (ra->max != rb->max)
                  return ra->max - rb->max;
              if (ra->inclusive_max && !rb->inclusive_max)
                  return 1;
              if (!ra->inclusive_max && rb->inclusive_max)
                  return -1;
              return 0;
          });

    size_t i = 0;
    for (size_t j = 1; j < manager->range_count;) {
        if (are_ranges_overlapping(&manager->ranges[i], &manager->ranges[j])) {
            // Merge logic: update min and max appropriately
            long new_min = manager->ranges[i].min;
            bool new_inclusive_min = manager->ranges[i].inclusive_min;

            long new_max = manager->ranges[j].max;
            bool new_inclusive_max = manager->ranges[j].inclusive_max;

            if (manager->ranges[j].min < new_min ||
                (manager->ranges[j].min == new_min && !new_inclusive_min &&
                 manager->ranges[j].inclusive_min)) {
                new_min = manager->ranges[j].min;
                new_inclusive_min = manager->ranges[j].inclusive_min;
            }

            if (manager->ranges[i].max > new_max ||
                (manager->ranges[i].max == new_max && !new_inclusive_max &&
                 manager->ranges[i].inclusive_max)) {
                new_max = manager->ranges[i].max;
                new_inclusive_max = manager->ranges[i].inclusive_max;
            }

            manager->ranges[i] = (Range){new_min, new_inclusive_min, new_max, new_inclusive_max};
        } else {
            i++;
            manager->ranges[i] = manager->ranges[j];
        }
        j++;
    }

    manager->range_count = i + 1;
}

// Splits a range into non-overlapping sub-ranges based on custom criteria
void split_range(const Range *range, Range **subranges, size_t *count) {
    // Example logic to split the range in half (adjust as needed)
