long generateRandomLong(Range range);
double generateRandomDouble(Range range);
void updateDataStorage();
void allocateAndInitializeDataStorage(size_t recordCount);
void freeDataStorage();
void handleExternalDataFeed(char* dataStream);
void integrateBigDataFramework();
void detectAnomalies();
void cacheResults();
void selfHealMechanism();
void priorityScheduling();

// Initialize Range Manager
void initRangeManager() {
    rangeManager.ranges = malloc(MAX_RANGES * sizeof(Range));
}

// Free resources used by Range Manager
void freeRangeManager() {
    if (rangeManager.ranges) {
        free(rangeManager.ranges);
        pthread_mutex_destroy(&rangeManager.lock);
    }
}

// Add or update a range definition
int addOrUpdateRange(long min, long max, BoundaryType minBoundary, BoundaryType maxBoundary) {
    pthread_mutex_lock(&rangeManager.lock);

    for (size_t i = 0; i < rangeManager.count; ++i) {
        if (min == rangeManager.ranges[i].min && max == rangeManager.ranges[i].max &&
            minBoundary == rangeManager.ranges[i].minBoundary && maxBoundary == rangeManager.ranges[i].maxBoundary) {
            // Update existing
            pthread_mutex_unlock(&rangeManager.lock);
            return 0; // Success
        }
    }

    if (rangeManager.count >= MAX_RANGES) {
        pthread_mutex_unlock(&rangeManager.lock);
        return -1; // Failure: too many ranges
    }

    rangeManager.ranges[rangeManager.count++] = (Range){min, max, minBoundary, maxBoundary};

    mergeRanges();  // Merge overlapping ranges

    pthread_mutex_unlock(&rangeManager.lock);
    return 0; // Success
}

// Merge overlapping ranges
void mergeRanges() {
    // Simplified merging logic for demonstration
    if (rangeManager.count <= 1) return;

    Range* temp = malloc(rangeManager.count * sizeof(Range));
    size_t j = 0;

    for (size_t i = 0; i < rangeManager.count - 1; ++i) {
        if ((temp[j-1].max >= rangeManager.ranges[i+1].min &&
             (!((temp[j-1].maxBoundary == EXCLUSIVE && temp[j-1].max == rangeManager.ranges[i+1].min) ||
                (temp[j-1].maxBoundary == INCLUSIVE && temp[j-1].max + 1 == rangeManager.ranges[i+1].min)))) ||
            temp[j-1].max < rangeManager.ranges[i+1].min) {
            memcpy(&temp[j], &rangeManager.ranges[i], sizeof(Range));
            ++j;
        } else {
            if (temp[j-1].maxBoundary == INCLUSIVE)
                temp[j-1].max = rangeManager.ranges[i+1].max;
            else
                temp[j-1].max = rangeManager.ranges[i+1].max - 1;

            temp[j-1].maxBoundary = (rangeManager.ranges[i+1].maxBoundary == INCLUSIVE) ? INCLUSIVE : EXCLUSIVE;
        }
    }

    memcpy(&temp[j], &rangeManager.ranges[rangeManager.count - 1], sizeof(Range));
    ++j;

    free(rangeManager.ranges);
    rangeManager.ranges = temp;
    rangeManager.count = j;
}

// Split a range into non-overlapping sub-ranges
void splitRange(size_t index) {
    // Simplified splitting logic for demonstration
    if (index >= rangeManager.count) return;

    Range currentRange = rangeManager.ranges[index];

    pthread_mutex_lock(&rangeManager.lock);

    if (currentRange.min != currentRange.max) {  // If there's something to split

        size_t newSize = rangeManager.count + 1;

        if (newSize > MAX_RANGES) {
            pthread_mutex_unlock(&rangeManager.lock);
            return; // Failure: too many ranges
        }

        Range* newRanges = realloc(rangeManager.ranges, newSize * sizeof(Range));
        if (!newRanges) {
            pthread_mutex_unlock(&rangeManager.lock);
            return; // Allocation failure
        }

        rangeManager.ranges = newRanges;

        // Copy the current range, split into two sub-ranges
        memcpy(&rangeManager.ranges[index], &currentRange, sizeof(Range));
        rangeManager.ranges[newSize - 1] = (Range){currentRange.max + 1, MAX_RANGES, EXCLUSIVE, EXCLUSIVE};

        rangeManager.count = newSize;
    }

    pthread_mutex_unlock(&rangeManager.lock);
}

// Generate a random long within a given range
long generateRandomLong(Range range) {
    srand(time(NULL));
    return rand() % (range.max - range.min + 1) + range.min;
}

// Generate a random double within a given range
double generateRandomDouble(Range range) {
    srand(time(NULL) * time(NULL));
    double fraction = ((double)rand() / RAND_MAX);
    long rangeSize = (range.max - range.min);
    return range.min + fraction * rangeSize;
}

// Update Data Storage with random values
void updateDataStorage() {
    pthread_mutex_lock(&dataStorage.lock);

    allocateAndInitializeDataStorage(rangeManager.count);

    for (size_t i = 0; i < dataStorage.recordCount; ++i) {
        long randomValue = generateRandomLong(rangeManager.ranges[i % rangeManager.count]);
        dataStorage.records[i].value = (int)randomValue;
    }

    pthread_mutex_unlock(&dataStorage.lock);
}

// Allocate and initialize data storage
void allocateAndInitializeDataStorage(size_t recordCount) {
    if (dataStorage.recordCount != 0) {
        free(dataStorage.offsets);
        free(dataStorage.keys);
        free(dataStorage.records);
    }

    dataStorage.recordCount = recordCount;
    dataStorage.offsets = malloc(recordCount * sizeof(long));
    dataStorage.keys = malloc(recordCount * sizeof(int));
    dataStorage.records = malloc(recordCount * sizeof(Record));

    for (size_t i = 0; i < recordCount; ++i) {
        dataStorage.offsets[i] = 0;
        dataStorage.keys[i] = i;
        dataStorage.records[i].value = 0;
    }
}

// Free resources used by Data Storage
void freeDataStorage() {
    pthread_mutex_lock(&dataStorage.lock);

    if (dataStorage.offsets) free(dataStorage.offsets);
    if (dataStorage.keys) free(dataStorage.keys);
    if (dataStorage.records) free(dataStorage.records);

    dataStorage.recordCount = 0;

    pthread_mutex_unlock(&dataStorage.lock);
}

