#define ATTRIBUTE_MAX_LEN 128
#define ALIGNMENT 64

typedef struct Attribute {
    int identifier;
    char string[ATTRIBUTE_MAX_LEN];
    struct Attribute* next;
} Attribute;

typedef struct TreeNode {
    double value;
    Attribute* attributes;
    struct TreeNode* children;
    int num_children;
} TreeNode;

// Helper function to align memory allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Function to generate a random alphanumeric string of specified length
void generate_random_string(char *str, int len) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (len) {
        --len; // Leave space for the null terminator
        for (size_t n = 0; n < len; ++n) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[len] = '\0';
    } else {
        *str = '\0';
    }
}

// Function to create and initialize a new tree node
TreeNode* create_tree_node(double value, int num_attributes) {
    TreeNode* node = aligned_alloc(ALIGNMENT, sizeof(TreeNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for TreeNode\n");
        exit(EXIT_FAILURE);
    }

    node->value = value;
    node->attributes = NULL;

    Attribute* last_attr = NULL;
    for (int i = 0; i < num_attributes; ++i) {
        Attribute* attr = aligned_alloc(ALIGNMENT, sizeof(Attribute));
        if (!attr) {
            fprintf(stderr, "Memory allocation failed for Attribute\n");
            exit(EXIT_FAILURE);
        }

        attr->identifier = rand();
        generate_random_string(attr->string, ATTRIBUTE_MAX_LEN);

        if (last_attr) {
            last_attr->next = attr;
        } else {
            node->attributes = attr;
        }
        last_attr = attr;
    }

    node->children = NULL;
    node->num_children = 0;

    return node;
}

// Function to recursively populate the tree
TreeNode* populate_tree(int current_depth, int max_depth) {
    if (current_depth > max_depth) return NULL;

    double value = exp((double)rand() / RAND_MAX * log(10.0));
    int num_attributes = rand() % 5 + 1; // Random number of attributes between 1 and 5

    TreeNode* node = create_tree_node(value, num_attributes);

    int num_children = rand() % 3 + 1; // Random number of children between 1 and 3
    node->children = aligned_alloc(ALIGNMENT, sizeof(TreeNode*) * num_children);
    if (!node->children) {
        fprintf(stderr, "Memory allocation failed for TreeNode pointers\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_children; ++i) {
        node->children[i] = populate_tree(current_depth + 1, max_depth);
    }
    node->num_children = num_children;

    return node;
}

// Main function to manage tree allocation and initialization
void manage_tree_allocation_and_initialization(const char* label, void (*f)(int), int max_depth) {
