        memset(&config->nicbs[i].mac_header.dest_mac, rand() % 256, sizeof(config->nicbs[i].mac_header.dest_mac));
        memset(&config->nicbs[i].mac_header.src_mac, rand() % 256, sizeof(config->nicbs[i].mac_header.src_mac));
        config->nicbs[i].mac_header.vlan_tag = (uint16_t)(rand() % 4096); // Random VLAN tag
        config->nicbs[i].mac_header.vlan_priority = rand() % 8; // Random priority
        config->nicbs[i].ip_checksum_enabled = true; // Example setting
