typedef void* aligned_alloc(size_t size, size_t alignment);

aligned_alloc(size_t size, size_t alignment) {
    if (alignment & (alignment - 1)) {
        return NULL; // Alignment must be a power of two
    }
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size) != 0) {
