error_cleanup:
    fprintf(stderr, "Memory allocation failed\n");
}

long* allocate_offsets(int size) {
    long *offsets = (long*)aligned_alloc(size * sizeof(long), ALIGNMENT);
    if (!offsets && size > 0) {
        // Retry with smaller chunks
        return allocate_offsets(size / 2);
    }
    return offsets;
}

int* allocate_keys(int size) {
    int *keys = (int*)aligned_alloc(size * sizeof(int), ALIGNMENT);
    if (!keys && size > 0) {
        return allocate_keys(size / 2);
    }
    return keys;
}

Record* allocate_records(int size) {
    Record *records = (Record*)aligned_free(size * sizeof(Record), ALIGNMENT);
    if (!records && size > 0) {
        return allocate_records(size / 2);
    }
    return records;
}

