    time_t last_timestamp = 0;
    for (int i = 0; i < num_keys; ++i) {
        if (records[i].timestamp < last_timestamp) return 0;
        last_timestamp = records[i].timestamp;
    }

    // Check for unique keys
    for (int i = 0; i < num_keys; ++i) {
        for (int j = i + 1; j < num_keys; ++j) {
            if (keys[i] == keys[j]) return 0;
        }
    }

    return 1;
}

void free_resources(long* offsets, int* keys, Record* records) {
    aligned_free(offsets);
    aligned_free(keys);
    aligned_free(records);
}

int retry_with_backoff(void (*func)(void*), void* arg, int max_attempts, int initial_delay) {
    int attempt = 0;
    int delay = initial_delay;

    while (attempt < max_attempts) {
        if ((*func)(arg)) return 1;

        usleep(delay * 1000);
        delay *= 2; // Exponential backoff
        ++attempt;
    }

    return 0;
}

void aligned_free(void* ptr) {
    free(ptr);
}
