        pthread_mutex_lock(&global_lock);

        Node* node = aligned_malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for node\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_unlock(&global_lock);

        double random_value = sqrt(secure_random_number(rand_range_min, rand_range_max));
        node->value = random_value;
        node->items_head = NULL;

        // Allocate a list of items
        Item* head = NULL;
        for (int j = 0; j < num_nodes; ++j) {
            pthread_mutex_lock(&global_lock);

            Item* item = aligned_malloc(sizeof(Item));
            if (!item) {
                fprintf(stderr, "Failed to allocate memory for item\n");
                exit(EXIT_FAILURE);
            }

            pthread_mutex_unlock(&global_lock);

            item->key = j;
            random_string(item->string, ITEM_STRING_LENGTH);
            item->next = head;
            head = item;
        }

        node->items_head = head;
        nodes[i] = node;
    }

    return nodes;
}

