    // Cleanup
    for (int i = 0; i < num_nodes; ++i) {
        Item* item = nodes[i]->items_head;
        while (item) {
            Item* next = item->next;
            free(item);
            item = next;
        }
        free(nodes[i]);
    }
    free(nodes);

    pthread_mutex_destroy(&global_lock);
    pthread_mutex_destroy(&mem_pool.lock);
    free(mem_pool.start);

    return 0;
}
```

