    if (!pool) return NULL;

    pool->head = NULL;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
