float calculate_priority(float *metrics, size_t count) {
    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += metrics[i];
    }
    return round(sum / count * 100000.0f) / 100000.0f;
}

int check_unique_keys(Operation *operation, int num_operations) {
    for (int i = 0; i < num_operations; ++i) {
        for (int j = i + 1; j < num_operations; ++j) {
            if (operation->keys[i] == operation->keys[j]) {
                return 0;
            }
        }
    }
    return 1;
}

