    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

int init_tasks(Task **tasks, int max_tasks, float *metrics, size_t metrics_count) {
    if (max_tasks <= 0 || !metrics || metrics_count == 0) return -1;

    pthread_mutex_lock(&task_lock);

    *tasks = aligned_alloc(sizeof(Task) * max_tasks, MEMORY_ALIGNMENT);
    if (!*tasks) {
        log_error("Failed to allocate memory for tasks");
        pthread_mutex_unlock(&task_lock);
        return -1;
    }

    float priority = calculate_priority(metrics, metrics_count);

    for (int i = 0; i < max_tasks; ++i) {
        (*tasks)[i].operations = aligned_alloc(sizeof(Operation) * MAX_OPERATIONS, MEMORY_ALIGNMENT);
        if (!(*tasks)[i].operations) {
            log_error("Failed to allocate memory for operations");
            free_aligned_alloc(*tasks);
            pthread_mutex_unlock(&task_lock);
            return -1;
        }

        (*tasks)[i].priority = priority;
        for (int j = 0; j < MAX_OPERATIONS; ++j) {
            Operation *op = &((*tasks)[i].operations[j]);
            op->offsets = aligned_alloc(sizeof(long), MEMORY_ALIGNMENT);
            if (!op->offsets) {
