        (*tasks)[i].num_operations = MAX_OPERATIONS;

        if (!check_unique_keys((*tasks)[i].operations, MAX_OPERATIONS)) {
            log_error("Duplicate keys found in task operations");
            free_aligned_alloc(*tasks);
            pthread_mutex_unlock(&task_lock);
            return -1;
        }
    }

    pthread_mutex_unlock(&task_lock);

    return 0;
}

int init_records(Record **records, int max_records) {
    if (max_records <= 0) return -1;

    *records = aligned_alloc(sizeof(Record) * max_records, MEMORY_ALIGNMENT);
