    for (int i = 0; i < max_tasks; ++i) {
        fwrite(&tasks[i].priority, sizeof(float), 1, file);
        fwrite(&tasks[i].num_operations, sizeof(int), 1, file);
        for (int j = 0; j < tasks[i].num_operations; ++j) {
            Operation *op = &tasks[i].operations[j];
            fwrite(op->keys, sizeof(int), MAX_OPERATIONS, file);
            long dummy_offset = 0;
            fwrite(&dummy_offset, sizeof(long), MAX_OPERATIONS, file); // Assuming offsets are not needed
        }
    }

    fclose(file);
}

void deserialize_tasks(Task **tasks, int *max_tasks, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization");
        return;
    }

    fread(max_tasks, sizeof(int), 1, file);
    *tasks = aligned_alloc(sizeof(Task) * (*max_tasks), MEMORY_ALIGNMENT);

    for (int i = 0; i < *max_tasks; ++i) {
