        fread(&(*tasks)[i].num_operations, sizeof(int), 1, file);
        (*tasks)[i].operations = aligned_alloc(sizeof(Operation) * MAX_OPERATIONS, MEMORY_ALIGNMENT);

        for (int j = 0; j < (*tasks)[i].num_operations; ++j) {
            Operation *op = &(*tasks)[i].operations[j];
            fread(op->keys, sizeof(int), MAX_OPERATIONS, file);
            long dummy_offset;
            for (int k = 0; k < MAX_OPERATIONS; ++k) {
                fread(&dummy_offset, sizeof(long), 1, file); // Assuming offsets are not needed
            }
        }
    }

    fclose(file);
}

void free_tasks(Task *tasks, int max_tasks) {
    if (!tasks) return;

    for (int i = 0; i < max_tasks; ++i) {
        for (int j = 0; j < tasks[i].num_operations; ++j) {
            Operation *op = &tasks[i].operations[j];
            free_aligned_alloc(op->offsets);
        }
        free_aligned_alloc(tasks[i].operations);
    }

    free_aligned_alloc(tasks);
}

void free_records(Record *records, int max_records) {
    if (!records) return;

    free_aligned_alloc(records);
}
