#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>

#define MAX_WORKLOADS 10
#define MAX_OPERATIONS 100
#define MEMORY_ALIGNMENT 128
#define VALUE_RANGE_LOW 0.0f
#define VALUE_RANGE_HIGH 1.0f

typedef struct {
    float value;
} Operation;

typedef struct {
    Operation* operations[MAX_OPERATIONS];
    int priority;
    char key[256];
    uint64_t identifier;
} Workload;

typedef struct Node {
    uint64_t identifier;
    struct Node* left;
    struct Node* right;
} Node;

typedef struct {
    Node* root;
    pthread_mutex_t lock;
} IdentifierTree;

// Utility functions
static inline void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

float generate_random_float(float low, float high) {
    float range = high - low;
    float random = ((double)rand() / RAND_MAX);
    return low + random * range;
}

uint64_t generate_unique_identifier(IdentifierTree* tree) {
    // Simple unique identifier generation for demonstration
    static uint64_t id_counter = 1;
    Node* new_node = (Node*)aligned_alloc(MEMORY_ALIGNMENT, sizeof(Node));
    if (!new_node) return 0;

    new_node->identifier = id_counter++;
    pthread_mutex_lock(&tree->lock);

    // Insert into the tree
    Node** current = &tree->root;
    while (*current) {
        int cmp = (int)(*current)->identifier - (int)new_node->identifier;
        if (cmp > 0)
            current = &(*current)->left;
        else if (cmp < 0)
            current = &(*current)->right;
        else {
            pthread_mutex_unlock(&tree->lock);
            free(new_node);
            return 0; // Duplicate identifier
        }
    }

    *current = new_node;
    pthread_mutex_unlock(&tree->lock);

    return new_node->identifier;
}

void serialize_workload(const Workload* workload, FILE* file) {
    fwrite(workload, sizeof(Workload), 1, file);
    for (int i = 0; workload->operations[i]; ++i)
        fwrite(workload->operations[i], sizeof(Operation), 1, file);
}

void deserialize_workload(Workload* workload, FILE* file) {
    fread(workload, sizeof(Workload), 1, file);
    for (int i = 0; i < MAX_OPERATIONS && workload->operations[i]; ++i)
        fread(workload->operations[i], sizeof(Operation), 1, file);
}

void initialize_workload(Workload* workload) {
    srand(time(NULL));
    workload->priority = round((generate_random_float(VALUE_RANGE_LOW, VALUE_RANGE_HIGH) +
                                generate_random_float(VALUE_RANGE_LOW, VALUE_RANGE_HIGH)) / 2.0f * 100000) / 100000;

    for (int i = 0; i < MAX_OPERATIONS; ++i) {
        Operation* op = (Operation*)aligned_alloc(MEMORY_ALIGNMENT, sizeof(Operation));
        if (!op) continue;
        op->value = generate_random_float(VALUE_RANGE_LOW, VALUE_RANGE_HIGH);
        workload->operations[i] = op;
    }

    snprintf(workload->key, sizeof(workload->key), "Workload_%lu", (unsigned long)workload - (unsigned long)&workload[0]);
}

void free_workload(Workload* workload) {
    for (int i = 0; i < MAX_OPERATIONS; ++i)
        if (workload->operations[i])
            free(workload->operations[i]);

    memset(workload, 0, sizeof(Workload));
}

void manage_workloads(int num_workloads) {
    Workload workloads[MAX_WORKLOADS] = {0};
    IdentifierTree tree = {.root = NULL};
    pthread_mutex_init(&tree.lock, NULL);

    for (int i = 0; i < num_workloads && i < MAX_WORKLOADS; ++i) {
        initialize_workload(&workloads[i]);
        workloads[i].identifier = generate_unique_identifier(&tree);
        if (!workloads[i].identifier) {
            fprintf(stderr, "Failed to generate unique identifier for workload %d\n", i);
            break;
        }
    }

    // Example serialization
    FILE* file = fopen("workloads.dat", "wb");
    if (file) {
        for (int i = 0; i < num_workloads && i < MAX_WORKLOADS; ++i)
            serialize_workload(&workloads[i], file);
        fclose(file);
    }

    // Example deserialization
    file = fopen("workloads.dat", "rb");
    if (file) {
        for (int i = 0; i < num_workloads && i < MAX_WORKLOADS; ++i)
            deserialize_workload(&workloads[i], file);
        fclose(file);
    }

    // Cleanup
    for (int i = 0; i < num_workloads && i < MAX_WORKLOADS; ++i)
        free_workload(&workloads[i]);

    pthread_mutex_destroy(&tree.lock);
}

int main() {
    manage_workloads(5); // Example usage with 5 workloads
    return 0;
}
```

