['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_TIMEOUT_MS 30000 // Define maximum timeout value

typedef struct {
    int session_id;
    char *remote_address;
    int timeout_ms;
} NetworkSession;

typedef struct {
    NetworkSession **sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// Function prototypes
int init_session_manager(SessionManager *manager, size_t initial_capacity);
void free_session_manager(SessionManager *manager);
int add_session(SessionManager *manager, int session_id, const char *remote_address, int timeout_ms);
void remove_session(SessionManager *manager, int session_id);
void* session_timeout_checker(void *arg);

// Initialize the SessionManager
int init_session_manager(SessionManager *manager, size_t initial_capacity) {
    manager->sessions = (NetworkSession **)malloc(initial_capacity * sizeof(NetworkSession *));
    if (!manager->sessions) return -1;
    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);

    // Create a thread to handle session timeouts
    pthread_t timeout_thread;
    if (pthread_create(&timeout_thread, NULL, session_timeout_checker, manager) != 0) {
        free(manager->sessions);
        pthread_mutex_destroy(&manager->lock);
        return -1;
    }
    pthread_detach(timeout_thread);

    return 0;
}

// Free resources used by SessionManager
void free_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]) {
            free(manager->sessions[i]->remote_address);
            free(manager->sessions[i]);
        }
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

// Add a new session to the manager
int add_session(SessionManager *manager, int session_id, const char *remote_address, int timeout_ms) {
    if (timeout_ms > MAX_TIMEOUT_MS) return -1; // Validate timeout

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NetworkSession **new_sessions = realloc(manager->sessions, new_capacity * sizeof(NetworkSession *));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Allocation failed
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    NetworkSession *session = (NetworkSession *)malloc(sizeof(NetworkSession));
    if (!session) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failed
    }

    session->session_id = session_id;
    size_t address_len = strlen(remote_address) + 1;
    session->remote_address = malloc(address_len);
    if (!session->remote_address) {
        free(session);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failed
    }

    strcpy(session->remote_address, remote_address);
    session->timeout_ms = timeout_ms;

    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Remove a session by session_id
void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i] && manager->sessions[i]->session_id == session_id) {
            free(manager->sessions[i]->remote_address);
            free(manager->sessions[i]);

            // Shift remaining elements
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(NetworkSession *));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Thread function to check for session timeouts
void* session_timeout_checker(void *arg) {
    SessionManager *manager = (SessionManager *)arg;

    while (1) {
        sleep(1); // Check every second

        time_t current_time = time(NULL);

        pthread_mutex_lock(&manager->lock);

        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->sessions[i] &&
                current_time - manager->sessions[i]->timeout_ms >= manager->sessions[i]->timeout_ms / 1000) {

                remove_session(manager, manager->sessions[i]->session_id);
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}
