    pthread_mutex_t lock;
} OffsetsManager;

// Function declarations
MemoryManagementUnit* initializeMemorySystem(size_t num_units, size_t page_size, int protection_flags);
void freeMemorySystem(MemoryManagementUnit* units, size_t num_units);
size_t* loadOffsetsFromFile(const char* filename, size_t *count);
int validateChecksum(size_t *offsets, size_t count);

// Global mutex for thread-safe operations
pthread_mutex_t memory_system_lock = PTHREAD_MUTEX_INITIALIZER;

MemoryManagementUnit* initializeMemorySystem(size_t num_units, size_t page_size, int protection_flags) {
    if (num_units == 0 || page_size == 0) return NULL;

    MemoryManagementUnit *units = malloc(num_units * sizeof(MemoryManagementUnit));
    if (!units) return NULL;

    for (size_t i = 0; i < num_units; ++i) {
        units[i].page_table_entry.valid = 1;
        units[i].physical_memory_size = page_size;
        units[i].protection_flags = protection_flags;

        // Align memory address based on alignment requirements
        size_t alignment = 4096; // Example: 4KB page alignment
        void *aligned_addr = NULL;
        if (posix_memalign(&aligned_addr, alignment, page_size) != 0) {
            free(units);
            return NULL;
        }

        units[i].virtual_memory_address = aligned_addr;
    }

    pthread_mutex_lock(&memory_system_lock);
    // Log initialization
    printf("Memory system initialized with %zu units.\n", num_units);
    pthread_mutex_unlock(&memory_system_lock);

    return units;
}

void freeMemorySystem(MemoryManagementUnit* units, size_t num_units) {
    if (!units) return;

    for (size_t i = 0; i < num_units; ++i) {
        free(units[i].virtual_memory_address);
    }

    free(units);

    pthread_mutex_lock(&memory_system_lock);
    // Log deallocation
    printf("Memory system deallocated.\n");
    pthread_mutex_unlock(&memory_system_lock);
}

size_t* loadOffsetsFromFile(const char* filename, size_t *count) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0L, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    size_t num_elements = file_size / sizeof(size_t);
    size_t *offsets = malloc(num_elements * sizeof(size_t));

    if (fread(offsets, sizeof(size_t), num_elements, file) != num_elements) {
        free(offsets);
        fclose(file);
        return NULL;
    }

    fclose(file);

    if (!validateChecksum(offsets, num_elements)) {
        free(offsets);
        return NULL;
    }

    *count = num_elements;

    pthread_mutex_lock(&memory_system_lock);
    // Log file loading
    printf("Offsets loaded from %s with %zu elements.\n", filename, num_elements);
    pthread_mutex_unlock(&memory_system_lock);

    return offsets;
}

int validateChecksum(size_t *offsets, size_t count) {
    if (!offsets || count == 0) return 0;

    // Simple checksum validation
    size_t checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += offsets[i];
    }

    pthread_mutex_lock(&memory_system_lock);
    printf("Checksum: %zu\n", checksum); // Log checksum value
    pthread_mutex_unlock(&memory_system_lock);

    return checksum % 2 == 0; // Example condition for a valid checksum
}
