CustomData* allocate_custom_data_array(size_t count, const char **pool_of_identifiers,
                                       size_t pool_size, int min_int, int max_int) {
    if (count == 0 || pool_of_identifiers == NULL || pool_size == 0) return NULL;

    srand((unsigned int)time(NULL)); // Seed for random number generation

    CustomData *array = malloc(count * sizeof(CustomData));
    if (!array) return NULL;

    char *used_identifiers = calloc(pool_size, sizeof(char));
    if (!used_identifiers) {
        free(array);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        array[i].identifier = get_random_identifier(pool_of_identifiers, pool_size,
                                                    used_identifiers, i);
        if (!array[i].identifier) {
            // Cleanup on failure
            for (size_t j = 0; j < i; ++j) free(array[j].identifier);
            free(used_identifiers);
            free(array);
            return NULL;
        }

        array[i].number = generate_random_int(min_int, max_int);

        array[i].value = calculate_double_value(array[i].number);
    }

    free(used_identifiers);
    return array;
}

