                            char *used_identifiers, size_t used_count) {
    size_t attempts = 0;
    while (attempts < pool_size) {
        size_t index = rand() % pool_size;
        if (!used_identifiers[index]) {
            used_identifiers[index] = 1; // Mark as used
            return strdup(pool_of_identifiers[index]);
        }
        ++attempts;
    }

    return NULL; // Should not reach here if 'count' <= 'pool_size'
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

double calculate_double_value(int number) {
    // Example formula: double the integer value and add a constant
    return (double)number * 2.0 + 3.14;
}

