#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BANDWIDTH 20 // in MHz
#define MIN_BANDWIDTH 1  // in MHz
#define MAX_SUBCARRIER_SPACING 120
#define MIN_SUBCARRIER_SPACING 30
#define MAX_REF_SIGNAL_POWER 23 // in dBm
#define MIN_REF_SIGNAL_POWER -3  // in dBm

typedef struct {
    int bandwidth;
    int subcarrier_spacing;
    float ref_signal_power;
} LTE_PHY_Config;

typedef struct {
    LTE_PHY_Config *configs;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

// Function to validate configuration settings
int validate_config(int bandwidth, int subcarrier_spacing, float ref_signal_power) {
    if (bandwidth < MIN_BANDWIDTH || bandwidth > MAX_BANDWIDTH) return 0;
    if (subcarrier_spacing < MIN_SUBCARRIER_SPACING || subcarrier_spacing > MAX_SUBCARRIER_SPACING) return 0;
    if (ref_signal_power < MIN_REF_SIGNAL_POWER || ref_signal_power > MAX_REF_SIGNAL_POWER) return 0;
    return 1;
}

// Function to add a configuration
int add_config(ConfigManager *manager, int bandwidth, int subcarrier_spacing, float ref_signal_power) {
    pthread_mutex_lock(&manager->lock);

    if (!validate_config(bandwidth, subcarrier_spacing, ref_signal_power)) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    LTE_PHY_Config *new_configs = realloc(manager->configs, (manager->count + 1) * sizeof(LTE_PHY_Config));
    if (!new_configs) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    manager->configs = new_configs;
    manager->configs[manager->count].bandwidth = bandwidth;
    manager->configs[manager->count].subcarrier_spacing = subcarrier_spacing;
    manager->configs[manager->count].ref_signal_power = ref_signal_power;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

// Function to serialize configurations
int serialize_configurations(const ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return 0;

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->configs, sizeof(LTE_PHY_Config), manager->count, file);

    fclose(file);
    return 1;
}

// Function to deserialize configurations
int deserialize_configurations(ConfigManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return 0;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    LTE_PHY_Config *configs = malloc(count * sizeof(LTE_PHY_Config));
    if (!configs) {
        fclose(file);
        return 0;
    }

    fread(configs, sizeof(LTE_PHY_Config), count, file);
    fclose(file);

    pthread_mutex_lock(&manager->lock);
    free(manager->configs);
    manager->configs = configs;
    manager->count = count;
    pthread_mutex_unlock(&manager->lock);

    return 1;
}

// Function to initialize ConfigManager
ConfigManager *init_config_manager() {
    ConfigManager *manager = malloc(sizeof(ConfigManager));
