#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    short key;
    int value;
    float data;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
size_t max_size = 0; // Maximum memory size for records and nodes

int insert_record(short key, int value, float data) {
    if (head != NULL) { 
        Node *current = head;
        while (current != NULL) {
            if (current->record.key == key) return -1; // Key already exists
            current = current->next;
        }
    }

    size_t record_size = sizeof(Record);
    size_t node_size = sizeof(Node);

    Node *new_node = (Node*)malloc(node_size + record_size);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1; 
    }

    new_node->record.key = key;
    new_node->record.value = value;
    new_node->record.data = data;
    new_node->next = head;
    head = new_node;

    max_size += node_size + record_size;
    if (max_size > max_allowed_memory) {
        // Handle memory overflow
        return -1; 
    }

    return 0;
}

int delete_record(short key) {
    Node **indirect = &head;

    while (*indirect != NULL) {
        Node *entry = *indirect;

        if (entry->record.key == key) {
            *indirect = entry->next;
            free(entry);
            max_size -= sizeof(Node) + sizeof(Record);
            return 0; 
        }

        indirect = &(*indirect)->next;
    }

    return -1; // Record not found
}

int serialize_records(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    Node *current = head;
    while (current != NULL) {
        size_t written = fwrite(&current->record, sizeof(Record), 1, file);
        if (written < 1) break; // Error writing
        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserialize_records(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    Record temp_record;
    size_t read_bytes;

    while ((read_bytes = fread(&temp_record, sizeof(Record), 1, file)) > 0) {
        insert_record(temp_record.key, temp_record.value, temp_record.data);
    }

    fclose(file);
    return 0;
}

void cleanup() {
    Node *current = head;
    while (current != NULL) {
        Node *next_node = current->next;
        free(current);
        current = next_node;
    }
    head = NULL;
    max_size = 0; // Reset the memory usage
}

// Usage example
int main(int argc, char **argv) {
    if (argc < 2) return -1;

    sscanf(argv[1], "%zu", &max_allowed_memory);

    insert_record(1, 10, 3.14f);
    insert_record(2, 20, 6.28f);

    serialize_records("records.dat");

    cleanup(); // Clean up before deserialization

    deserialize_records("records.dat");
    cleanup();

    return 0;
}
