#include <stdalign.h>

#define MAX_NODES 1000
#define MAX_ITEMS 10000
#define KEY_LENGTH 10
#define STRING_LENGTH 50
#define MEMORY_ALIGNMENT 64

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    double data;
    struct Node* next;
} Node;

typedef union MetadataUnion {
    struct Item* item_ptr;
    short metadata_short;
} MetadataUnion;

typedef struct Item {
    int key;
    char string[STRING_LENGTH];
    MetadataUnion metadata;
    struct Item* next;
} Item;

typedef struct LinkedListNode {
    Record* record_array;
    size_t record_count;
    Node** node_pointers;
    size_t node_count;
    Item* head_item;
} LinkedListNode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* initialize_data_structure(size_t max_nodes, size_t max_items, int min_val, int max_val) {
    pthread_t threads[MAX_NODES];
    int thread_count = MAX_NODES;

    // Function to create nodes and items
    void* process_subset(void* arg) {
        int index = *(int*)arg;

        // Allocate aligned memory for records
        Record* record_array = aligned_alloc(MEMORY_ALIGNMENT, max_items * sizeof(Record));

        // Initialize records with random values within specified range
        srand(time(NULL) + index);
        for (size_t i = 0; i < max_items; ++i) {
            record_array[i].value = rand() % (max_val - min_val + 1) + min_val;
        }

        // Allocate aligned memory for node pointers
        Node** node_pointers = aligned_alloc(MEMORY_ALIGNMENT, max_nodes * sizeof(Node*));

        // Initialize node pointers to NULL or create nodes as required
        for (size_t i = 0; i < max_nodes; ++i) {
            node_pointers[i] = malloc(sizeof(Node)); // Allocate each Node separately to manage fragmentation
            if (node_pointers[i]) {
                node_pointers[i]->data = (double)(rand() % 100);
                node_pointers[i]->next = NULL;
            }
        }

        // Create and initialize linked list of items
        Item* head_item = malloc(sizeof(Item));
        if (!head_item) return NULL;

        Item* current = head_item;
        for (size_t i = 0; i < max_items; ++i) {
            current->key = rand() % MAX_ITEMS;
            snprintf(current->string, STRING_LENGTH, "String_%d", current->key);

            // Randomly assign metadata
            if (rand() % 2 == 0) {
                MetadataUnion* union_ptr = &current->metadata;
                union_ptr->item_ptr = NULL; // or point to another item as needed
            } else {
                current->metadata.metadata_short = rand() % 100;
            }

            Item* new_item = malloc(sizeof(Item));
            if (!new_item) break;

            current->next = new_item;
            current = new_item;
        }

        // Join nodes in a circular fashion for demonstration
        current->next = head_item;

        LinkedListNode* result = malloc(sizeof(LinkedListNode));
        result->record_array = record_array;
        result->record_count = max_items;
        result->node_pointers = node_pointers;
        result->node_count = max_nodes;
        result->head_item = head_item;

        return (void*)result;
    }

    for (int i = 0; i < thread_count; ++i) {
        int* index_ptr = malloc(sizeof(int));
        *index_ptr = i;
        pthread_create(&threads[i], NULL, process_subset, (void*)index_ptr);
    }

    LinkedListNode** data_structures = calloc(thread_count, sizeof(LinkedListNode*));
    for (int i = 0; i < thread_count; ++i) {
        void* result;
        pthread_join(threads[i], &result);
        if (result) {
            data_structures[i] = (LinkedListNode*)result;
        }
    }

    return (void*)data_structures;
}

// Example usage
int main() {
    size_t max_nodes = 1000;
    size_t max_items = 10000;
    int min_val = 1, max_val = 100;

    void* data_structures = initialize_data_structure(max_nodes, max_items, min_val, max_val);
    // Handle or process the returned data structures as needed

    return 0;
}
```

This code snippet demonstrates how to create interconnected data structures with dynamic allocation and alignment for performance. It employs multi-threading to manage large-scale data processing efficiently and ensures each thread manages a subset of nodes and items. Memory fragmentation is minimized by separately allocating node pointers, while initialization and management of linked lists are handled within the threads.']

