    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Mockup external checksum function
int calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Placeholder for actual checksum calculation
    return (int)pdu->RNTI % 2; // Example logic: even RNTIs get CRCFLAG set to 1, odd to 0.
}

// Custom pool allocator for performance optimization
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} PoolAllocator;

PoolAllocator* create_pool_allocator(size_t element_size, size_t initial_capacity) {
    PoolAllocator *allocator = (PoolAllocator *)malloc(sizeof(PoolAllocator));
    if (!allocator) {
        log_error("Failed to allocate memory for PoolAllocator");
        return NULL;
    }

    allocator->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!allocator->pool) {
        free(allocator);
        log_error("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T pool");
        return NULL;
    }

    allocator->pool_size = initial_capacity;
    pthread_mutex_init(&allocator->lock, NULL);

    return allocator;
}

void* pool_alloc(PoolAllocator *allocator) {
    pthread_mutex_lock(&allocator->lock);
    if (allocator->pool_size == 0) {
        pthread_mutex_unlock(&allocator->lock);
        log_error("Pool is exhausted");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &allocator->pool[--allocator->pool_size];
    pthread_mutex_unlock(&allocator->lock);

    return pdu;
}

void pool_free(PoolAllocator *allocator, void *ptr) {
    pthread_mutex_lock(&allocator->lock);
    if (allocator->pool_size == allocator->pool_size) { // Assuming max size is a defined constant
        pthread_mutex_unlock(&allocator->lock);
        log_error("Pool overflow");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = ptr;
    pdu->ue_info_tag.RNTI = 0; // Reset RNTI to zero for reuse safety.
    pdu->RNTI = 0; // Reset RNTI to zero for reuse safety.
    allocator->pool[allocator->pool_size++] = *pdu;

    pthread_mutex_unlock(&allocator->lock);
}

void free_pool_allocator(PoolAllocator *allocator) {
    if (allocator) {
        free(allocator->pool);
        pthread_mutex_destroy(&allocator->lock);
        free(allocator);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_list(size_t N, size_t initial_capacity) {
    PoolAllocator *allocator = create_pool_allocator(sizeof(NFAPI_CRC_INDICATION_PDU_T), initial_capacity);
    if (!allocator) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_error("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T list");
        free_pool_allocator(allocator);
        return NULL;
    }

    unsigned int last_RNTI = 0;
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = pool_alloc(allocator);
        if (!pdu) {
            log_error("Failed to allocate a structure from the pool");
            // Clean up partially filled list
            for (size_t j = 0; j < i; ++j) {
                pool_free(allocator, &list[j]);
            }
            free(list);
            free_pool_allocator(allocator);
            return NULL;
        }

        pdu->ue_info_tag.RNTI = rand(); // Mocked UE information
        do {
            pdu->RNTI = rand();
        } while (pdu->RNTI == last_RNTI);
        last_RNTI = pdu->RNTI;

        pdu->crc_indication_rel8.CRCFLAG = calculate_checksum(pdu);

        list[i] = *pdu;
    }

    free_pool_allocator(allocator);
    return list;
}

int main() {
    size_t N = 1000; // Example: create a list of 1000 structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_nfa_pi_crc_list(N, 500); // Initial pool capacity is 500

    if (pdu_list) {
        printf("List created successfully.\n");
        free(pdu_list);
    } else {
        printf("Failed to create list.\n");
    }

    return 0;
}
