#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    short key;
    int value;
    float data;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t max_memory_usage;
    pthread_mutex_t lock;
    size_t current_memory_usage;
} LinkedList;

LinkedList* create_list(size_t max_memory_usage) {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->max_memory_usage = max_memory_usage;
    list->current_memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(Node* node) {
    while (node) {
        Node* temp = node;
        node = node->next;
        free(temp);
    }
}

void destroy_list(LinkedList* list) {
    if (!list) return;
    pthread_mutex_lock(&list->lock);
    free_list(list->head);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_record(LinkedList* list, Record new_record) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->record.key == new_record.key)
            goto end;  // Key already exists
        current = &(*current)->next;
    }

    size_t record_size = sizeof(Record);
    size_t node_size = sizeof(Node);

    if (list->current_memory_usage + record_size + node_size > list->max_memory_usage) {
        pthread_mutex_unlock(&list->lock);
        return -2;  // Out of memory
    }

    Node* new_node = malloc(node_size);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3;  // Memory allocation failed
    }

    *current = new_node;
    list->current_memory_usage += node_size;
    new_node->record = new_record;
    new_node->next = NULL;

end:
    pthread_mutex_unlock(&list->lock);
    return 0;  // Success or duplicate key
}

int delete_record(LinkedList* list, short key) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->record.key == key) {
            Node* temp = *current;
            *current = (*current)->next;
            list->current_memory_usage -= sizeof(Node);
            free(temp);
            pthread_mutex_unlock(&list->lock);
            return 0;  // Success
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;  // Record not found
}

int serialize_list(LinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -2;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        fwrite(&(current->record), sizeof(Record), 1, file);
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

int deserialize_list(LinkedList* list, const char* filename) {
    if (!list || !filename) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -2;

    pthread_mutex_lock(&list->lock);

    Record record;
    while (fread(&record, sizeof(Record), 1, file)) {
        insert_record(list, record);  // Handle duplicates and memory limits
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}
