#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
    void *pointer;  // Can point to either long or int
} record;

// Function prototypes
void* safe_malloc(size_t size);
void free_all(void **offsets, size_t offsets_count, void **keys, size_t keys_count, record *records, size_t records_count);
bool is_unique_key(int key, int *key_array, size_t count);
bool populate_records(record *records, long *offsets, int *keys, size_t records_count, int value_range_min, int value_range_max, size_t offset_count, size_t key_count);
void iterate_records(record *records, size_t count);
int random_between(int min, int max);

// Memory allocation with error handling
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Free all allocated memory safely
void free_all(void **offsets, size_t offsets_count, void **keys, size_t keys_count, record *records, size_t records_count) {
    for (size_t i = 0; i < offsets_count; ++i) free(offsets[i]);
    for (size_t i = 0; i < keys_count; ++i) free(keys[i]);
    free(records);
}

// Check if a key is unique in the array
bool is_unique_key(int key, int *key_array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (key == key_array[i]) return false;
    }
    return true;
}

// Populate records with random values ensuring uniqueness and proper pointer assignment
bool populate_records(record *records, long *offsets, int *keys, size_t records_count, int value_range_min, int value_range_max, size_t offset_count, size_t key_count) {
    bool used_values[records_count];
    for (size_t i = 0; i < records_count; ++i) used_values[i] = false;

    srand(time(NULL));

    for (size_t i = 0; i < records_count; ++i) {
        int value;
        do {
            value = random_between(value_range_min, value_range_max);
        } while (used_values[value - value_range_min]);

        used_values[value - value_range_min] = true;

        records[i].value = value;
        if ((rand() % 2) == 0 && i < offset_count) { // Randomly choose to point to offset
            records[i].pointer = &offsets[rand() % offset_count];
        } else if (i < key_count) {
            int key;
            do {
                key = random_between(value_range_min, value_range_max);
            } while (!is_unique_key(key, keys, key_count));
            keys[key_count++] = key;
            records[i].pointer = &keys[key_count - 1];
        }
    }

    return true;
}

// Random number generator
int random_between(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Iterate through the record array safely using pointer arithmetic
void iterate_records(record *records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("Record %zu: Value = %d\n", i, records[i].value);
        if ((int*)records[i].pointer > (int*)records + count)
            printf("Pointer points to offset\n");
        else
            printf("Pointer points to key\n");
    }
}

// Main function demonstrating the memory management system
int main() {
    const size_t max_records = 100;
    const size_t max_keys = 50;
    const int value_range_min = 1;
    const int value_range_max = 200;

    long *offsets = safe_malloc(max_records * sizeof(long));
    int *keys = safe_malloc(max_keys * sizeof(int));

    record *records = (record *)safe_malloc(max_records * sizeof(record));

    if (!populate_records(records, offsets, keys, max_records, value_range_min, value_range_max, max_records, max_keys)) {
        fprintf(stderr, "Failed to populate records\n");
        free_all((void**)&offsets, 1, (void**)&keys, 1, records, max_records);
        return EXIT_FAILURE;
    }

    iterate_records(records, max_records);

    free_all((void**)&offsets, 1, (void**)&keys, 1, records, max_records);
    return EXIT_SUCCESS;
}
```

This code implements a memory management system for multiple dynamic data structures, adhering to the specified constraints and performance requirements. It includes error handling, unique key generation, random value assignment, and safe iteration through records using pointer arithmetic.']

['Below is a C implementation for managing memory dynamically with concurrent operations using pthreads for synchronization. The code utilizes mutexes and condition variables to ensure thread safety during insertions and retrievals.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    int payload;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} RecordList;

RecordList* create_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void destroy_record_list(RecordList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}

void log_event(const char* event, int thread_id) {
    time_t now = time(NULL);
    printf("[%ld] Thread %d: %s\n", now, thread_id, event);
}

int insert_record(RecordList* list, Record record) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;  // Memory allocation failure
    }

    new_node->record = record;
    new_node->next = list->head;
    list->head = new_node;

    log_event("Inserted Record", pthread_self());

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int retrieve_record(RecordList* list, int key, Record* out_record) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->record.key == key) {
            *out_record = current->record;
            log_event("Retrieved Record", pthread_self());
            pthread_mutex_unlock(&list->lock);
            return 0;  // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;  // Key not found
}

void* concurrent_insert_thread(void* arg) {
    RecordList* list = (RecordList*)arg;
    for (int i = 0; i < 100; ++i) {
        Record record = { .key = i, .offset = i * 10, .payload = i };
        insert_record(list, record);
    }
    return NULL;
}

void* concurrent_retrieve_thread(void* arg) {
    RecordList* list = (RecordList*)arg;
    for (int i = 0; i < 100; ++i) {
        Record record;
        retrieve_record(list, i, &record);
    }
    return NULL;
}

void test_concurrent_operations() {
    RecordList* list = create_record_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize record list\n");
        return;
    }

    pthread_t threads[4];
    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, concurrent_insert_thread, list);
    }
    for (int i = 2; i < 4; ++i) {
        pthread_create(&threads[i], NULL, concurrent_retrieve_thread, list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_record_list(list);
}

int main() {
    test_concurrent_operations();
    return 0;
}
```

This code provides a thread-safe mechanism for inserting and retrieving records using mutex locks. It includes basic logging to an external console output, which can be extended or replaced with a more sophisticated logging service as needed. The implementation prioritizes simplicity while ensuring concurrency safety, memory management, and providing room for further performance optimization and scalability enhancements.']

