void destroy_thread_pool(ThreadPool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
}

Item generate_item(const char *seed, size_t max_length) {
    Item item;
    srand((unsigned int)time(NULL));
    item.value = (double)(rand() % 100);

    strncpy(item.buffer, seed, BUFFER_SIZE);
    for(size_t i = strlen(seed); i < max_length && i < BUFFER_SIZE; ++i) {
        char c = 'a' + rand() % 26;
        item.buffer[i] = c;
    }
    item.buffer[min(BUFFER_SIZE - 1, max_length)] = '\0';

    return item;
}

PacketMetadata* allocate_metadata(size_t count) {
    PacketMetadata *metadata_array = aligned_alloc(STRUCT_ALIGNMENT,
                                                   sizeof(PacketMetadata) * count);
    if (!metadata_array) {
        fprintf(stderr, "Failed to allocate memory for packet metadata.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&metadata_array->lock, &attr);

    return metadata_array;
}

void free_metadata(PacketMetadata *metadata_array) {
    if (metadata_array) {
        aligned_free(metadata_array);
    }
}

size_t adjust_payload_range(size_t current_load, size_t resource_availability) {
    // Adjust the range dynamically based on load and resources
    if(current_load > 0.8) { // High load scenario
        return PAYLOAD_MIN;
    } else if(resource_availability < 20) { // Low resource availability
        return PAYLOAD_MAX / 2;
    }
    return (PAYLOAD_MAX + PAYLOAD_MIN) / 2;
}

void* process_file(void *arg) {
    // Process a single file with the necessary logic
    ThreadPool *pool = (ThreadPool *)arg;

    pthread_mutex_lock(&pool->mutex);
    pool->active_threads++;
    while(pool->active_threads >= NUM_THREADS) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    pthread_mutex_unlock(&pool->mutex);

    // Simulate file processing
    sleep(rand() % 3); // Random sleep to simulate work

    Item item = generate_item(SEED_STRING, MAX_BUFFER_LENGTH);
    printf("Processed an item with value: %.2f and buffer: %s\n", item.value, item.buffer);

    pthread_mutex_lock(&pool->mutex);
    pool->active_threads--;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2 ...]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ThreadPool pool;
    initialize_thread_pool(&pool);

    for (int i = 1; i < argc; ++i) {
        pthread_create(&pool.threads[i - 1], NULL, process_file, &pool);
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(pool.threads[i], NULL);
    }

    destroy_thread_pool(&pool);

    MetadataManager manager;
    size_t initial_capacity = MAX_ITEMS;

    PacketMetadata *metadata_array = allocate_metadata(initial_capacity);
    manager.metadata_array = metadata_array;
    manager.capacity = initial_capacity;
    manager.count = 0;

    // Simulate dynamic adjustment
    size_t current_load = 70; // Example load percentage
    size_t resource_availability = 50; // Example available resources in percentage

    for (int i = 0; i < 10; ++i) { // Simulating addition of packets
        if (manager.count >= manager.capacity) {
            initial_capacity *= 2;
            metadata_array = realloc(metadata_array, sizeof(PacketMetadata) * initial_capacity);
            if (!metadata_array) {
                fprintf(stderr, "Failed to resize packet metadata array.\n");
                exit(EXIT_FAILURE);
            }
            manager.metadata_array = metadata_array;
            manager.capacity = initial_capacity;
        }

        PacketMetadata pkt_meta;
        pkt_meta.timestamp = (uint64_t)(time(NULL));
        pkt_meta.src_ip[0] = rand() % 256;
        pkt_meta.dst_ip[0] = rand() % 256;
        pkt_meta.payload_length = adjust_payload_range(current_load, resource_availability);

        pthread_mutex_lock(&manager.lock);
        manager.metadata_array[manager.count++] = pkt_meta;
        pthread_mutex_unlock(&manager.lock);
    }

    free_metadata(metadata_array);

    // Generate and print summary report
    printf("Summary Report:\n");
    double total_size = 0;
    for (size_t i = 0; i < manager.count; ++i) {
        total_size += manager.metadata_array[i].payload_length;
    }
    double avg_packet_size = total_size / manager.count;

    printf("Average Packet Size: %.2f\n", avg_packet_size);
    printf("Throughput: %zu packets processed.\n", manager.count);

    return 0;
}
