int initialize_records(record_t **records, size_t num_records, long offset_range_min, long offset_range_max) {
    pthread_mutex_lock(&mutex);

    if (num_records > MAX_RECORDS || num_records == 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    const size_t record_size = sizeof(record_t);
    const size_t max_memory = SYSTEM_LIMIT_MB * 1024 * 1024; // Convert MB to bytes
    size_t total_memory_needed = num_records * record_size;

    if (total_memory_needed > max_memory || total_memory_needed / 1024 > MAX_KB_SIZE) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    *records = malloc(total_memory_needed);
    if (*records == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1; // Allocation failure
    }

    long* offsets = malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        free(*records);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
