        (*records)[i].value = rand() % (INTEGER_RANGE_MAX - INTEGER_RANGE_MIN + 1) + INTEGER_RANGE_MIN;

        offsets[i] = (*records)[i].offset_index;
    }

    // Optional: Implement a garbage collector trigger if system memory is near threshold
    pthread_mutex_unlock(&mutex);

    free(offsets);
    return 0; // Success
}

void cleanup_records(record_t *records) {
    if (records != NULL) {
        free(records);
    }
}
