void process_batch(FSACB **fsacbs, size_t start_index, size_t batch_size, const char *file_paths[], Logger *logger, const ConfigSettings config, int *pause_flag);
void export_fsacbs(const FSACB *fsacbs, size_t count, const char *output_file);

// Helper functions
