### Java Class

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MyClass {

    private static final Logger logger = Logger.getLogger(MyClass.class.getName());

    public static void connectToRemote() {
        Selector selector = null;
        SocketChannel socketChannel = null;

        int attempt = 0;
        boolean connected = false;

        while (!connected && attempt < 5) { // Retry up to 5 times
            try {
                selector = Selector.open();
                socketChannel = SocketChannel.open();

                socketChannel.configureBlocking(false);
                socketChannel.connect(new InetSocketAddress("localhost", 8080));

                int ops = socketChannel.validOps();
                if (ops == SelectionKey.OP_CONNECT) { // Connect operation pending
                    selector.select(5000); // Wait for connection with timeout
                    for (SelectionKey key : selector.selectedKeys()) {
                        if (key.isConnectable() && key.channel().isConnected()) {
                            connected = true;
                            logger.log(Level.INFO, "Connection Successful");
                            break;
                        } else {
                            socketChannel.finishConnect();
                        }
                    }
                }

                if (!connected) throw new IOException("Failed to connect");

            } catch (IOException e) {
                attempt++;
                try {
                    Thread.sleep((long) Math.pow(2, attempt) * 1000); // Exponential backoff
                } catch (InterruptedException ex) {
                    Logger.getLogger(MyClass.class.getName()).log(Level.SEVERE, null, ex);
                }
                logger.log(Level.WARNING, "Retrying connection - Attempt " + attempt);
            } finally {
                try {
                    if (socketChannel != null) socketChannel.close();
                    if (selector != null) selector.close();
                } catch (IOException e) {
                    logger.log(Level.SEVERE, "Failed to close resources", e);
                }
            }
        }

        if (!connected) {
            Logger.getLogger(MyClass.class.getName()).log(Level.SEVERE, "Connection Failed after retries");
        }
    }
}
