                               unsigned char** output, size_t* output_len) {
    // Compress using zlib
    uLongf compressed_size = compressBound(input_len);
    *output = malloc(compressed_size);
    if (!(*output)) return;

    if (compress(*output, &compressed_size, input, input_len) != Z_OK) {
        free(*output);
        *output = NULL;
        return;
