        free(*output);
        free(encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        *output = NULL;
        return;
    }
    *output_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len)) {
        free(*output);
        free(encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        *output = NULL;
        return;
    }
    *output_len += len;

    free(*output);
    *output = encrypted_data;
    EVP_CIPHER_CTX_free(ctx);
}

