#include <time.h>

typedef enum {
    TYPE_INT,
    TYPE_FLOAT,
    TYPE_STRING,
    // Add additional types as needed
} DataType;

typedef struct {
    DataType type;
    size_t size;
    time_t timestamp;
} ElementHeader;

typedef union {
    int intValue;
    float floatValue;
    char* stringValue;
} ElementData;

typedef struct ListElement {
    ElementHeader header;
    ElementData data;
    struct ListElement* next;
} ListElement;

#define MAX_ELEMENTS 1000000

typedef struct {
    ListElement* head;
    size_t count;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int insert_element(DynamicList* list, DataType type, const void* data, size_t size) {
    if (list == NULL || data == NULL || list->count >= MAX_ELEMENTS) return -1;

    ListElement* newElem = (ListElement*)malloc(sizeof(ListElement));
    if (!newElem) return -2;

    pthread_mutex_lock(&list->lock);

    // Set header
    newElem->header.type = type;
    newElem->header.size = size;
    newElem->header.timestamp = time(NULL);

    // Set data
    switch (type) {
        case TYPE_INT:
            newElem->data.intValue = *(int*)data;
            break;
        case TYPE_FLOAT:
            newElem->data.floatValue = *(float*)data;
            break;
        case TYPE_STRING:
            newElem->data.stringValue = strdup((char*)data);
            break;
        // Handle additional types as needed
    }

    // Insert at head for simplicity; other strategies can be applied
    newElem->next = list->head;
    list->head = newElem;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int delete_element(DynamicList* list, size_t index) {
    if (list == NULL || index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);

    ListElement *current = list->head, *prev = NULL;
    for (size_t i = 0; current != NULL && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    // Handle data cleanup
    if (current->header.type == TYPE_STRING) {
        free(current->data.stringValue);
    }

    if (prev) prev->next = current->next;
    else list->head = current->next;

    free(current);
    list->count--;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int get_element(DynamicList* list, size_t index, void* buffer, size_t bufferSize) {
    if (list == NULL || index >= list->count || buffer == NULL) return -1;

    pthread_mutex_lock(&list->lock);

    ListElement *current = list->head;
    for (size_t i = 0; current != NULL && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    // Copy data to buffer
    switch (current->header.type) {
        case TYPE_INT:
            if (bufferSize >= sizeof(int)) *(int*)buffer = current->data.intValue;
            else break;
            break;
        case TYPE_FLOAT:
            if (bufferSize >= sizeof(float)) *(float*)buffer = current->data.floatValue;
            else break;
            break;
        case TYPE_STRING:
            if (current->header.size < bufferSize) strncpy(buffer, current->data.stringValue, current->header.size);
            else break;
            break;
        // Handle additional types as needed
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int serialize_list(DynamicList* list, const char* filename) {
    if (list == NULL || filename == NULL) return -1;

    FILE* file = fopen(filename, "wb");
    if (!file) return -2;

    pthread_mutex_lock(&list->lock);

    fwrite(&list->count, sizeof(size_t), 1, file);
    ListElement* current = list->head;
    while (current != NULL) {
        fwrite(&(current->header), sizeof(ElementHeader), 1, file);
        switch (current->header.type) {
            case TYPE_INT:
                fwrite(&(current->data.intValue), sizeof(int), 1, file);
                break;
            case TYPE_FLOAT:
                fwrite(&(current->data.floatValue), sizeof(float), 1, file);
                break;
            case TYPE_STRING:
                fwrite(&(current->header.size), sizeof(size_t), 1, file);
                fwrite(current->data.stringValue, current->header.size, 1, file);
                break;
        }
        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int deserialize_list(DynamicList* list, const char* filename) {
    if (list == NULL || filename == NULL) return -1;

    FILE* file = fopen(filename, "rb");
    if (!file) return -2;

    pthread_mutex_lock(&list->lock);

    ListElement *prev = NULL;
    while (fread(&(list->count), sizeof(size_t), 1, file)) {
        ElementHeader header;
        fread(&header, sizeof(ElementHeader), 1, file);

        ListElement* newElem = (ListElement*)malloc(sizeof(ListElement));
        if (!newElem) return -3;

        newElem->header = header;

        switch (header.type) {
            case TYPE_INT:
                fread(&(newElem->data.intValue), sizeof(int), 1, file);
                break;
            case TYPE_FLOAT:
                fread(&(newElem->data.floatValue), sizeof(float), 1, file);
                break;
            case TYPE_STRING:
                fread(&newElem->header.size, sizeof(size_t), 1, file);
                newElem->data.stringValue = (char*)malloc(header.size + 1);
                if (!newElem->data.stringValue) {
                    free(newElem);
                    return -4;
                }
                fread(newElem->data.stringValue, header.size, 1, file);
                newElem->data.stringValue[header.size] = '\0';
                break;
        }

        newElem->next = list->head;
        if (prev) prev->next = newElem;
        else list->head = newElem;

        prev = newElem;
    }

    fclose(file);

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void destroy_list(DynamicList* list) {
    if (list == NULL) return;

    pthread_mutex_lock(&list->lock);

    ListElement *current = list->head, *next;
    while (current != NULL) {
        next = current->next;
        if (current->header.type == TYPE_STRING) {
            free(current->data.stringValue);
        }
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
