public class MessagingService {

    private static final String BROKER_URL = "tcp://localhost:61616";
    private Connection connection;
    private Session session;

    public void initializeConnection() {
        try {
            Properties props = new Properties();
            props.put("ConnectionFactory", "org.apache.activemq.artemis.jms.client.ActiveMQJmsClientProperties.ConnectionFactory");
            props.put("URL", BROKER_URL);

            ConnectionFactory factory = new ActiveMQConnectionFactory(props);
            connection = factory.createConnection();
            session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);

            System.out.println("Connected to the message broker successfully.");
        } catch (JMSException e) {
            e.printStackTrace();
            handleConnectionError(e);
        }
    }

    private void handleConnectionError(JMSException e) {
        // Implement retry logic and logging
        System.err.println("Failed to connect: " + e.getMessage());
    }

    public void sendCustomMessage(String destinationName, String messageBody, Map<String, Object> headers) {
        try {
            Destination destination = session.createTopic(destinationName);
            MessageProducer producer = session.createProducer(destination);

            TextMessage message = session.createTextMessage(messageBody);
            for (Map.Entry<String, Object> header : headers.entrySet()) {
                message.setObjectProperty(header.getKey(), header.getValue());
            }

            producer.send(message);
            System.out.println("Message sent to " + destinationName);
        } catch (JMSException e) {
            e.printStackTrace();
        }
    }

    public void monitorMessages() {
        // Implement monitoring logic with alerting
        // Track delivery success, failure rates, and queue depth
        System.out.println("Monitoring messages...");
    }

