#define MAX_NICB_COUNT 1024
#define MAC_ADDRESS_LENGTH 6

typedef struct {
    unsigned char mac_address[MAC_ADDRESS_LENGTH];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    unsigned char src_mac[MAC_ADDRESS_LENGTH];
    unsigned char dest_mac[MAC_ADDRESS_LENGTH];
    unsigned short vlan_tag;
    int vlan_priority;
    int ip_checksum_enabled;
} NICB;

void initialize_and_populate_nicbs() {
    // Initialize OpenSSL
    OpenSSL_add_all_algorithms();
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest_alias("SHA1", "sha1");
    EVP_add_cipher(EVP_camellia_128_ecb());

    // Allocate and initialize NICB array
    NICB *nicbs = (NICB *)malloc(MAX_NICB_COUNT * sizeof(NICB));
    if (!nicbs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_NICB_COUNT; ++i) {
        // Random MAC addresses
        if (!RAND_bytes(nicbs[i].mac_header.mac_address, MAC_ADDRESS_LENGTH)) {
            fprintf(stderr, "Random generation failed\n");
            free(nicbs);
            exit(EXIT_FAILURE);
        }

        if (!RAND_bytes(nicbs[i].src_mac, MAC_ADDRESS_LENGTH) ||
            !RAND_bytes(nicbs[i].dest_mac, MAC_ADDRESS_LENGTH)) {
            fprintf(stderr, "Random generation failed\n");
            free(nicbs);
            exit(EXIT_FAILURE);
        }

        // Random VLAN tag
        unsigned short vlan_tag;
        if (!RAND_bytes((unsigned char *)&vlan_tag, sizeof(vlan_tag))) {
            fprintf(stderr, "Random generation failed\n");
            free(nicbs);
            exit(EXIT_FAILURE);
        }

        nicbs[i].vlan_tag = ntohs(vlan_tag);

        // Optional configuration
        nicbs[i].vlan_priority = rand() % 256; // Random VLAN priority
        nicbs[i].ip_checksum_enabled = rand() % 2; // Randomly enable/disable IP checksum

        printf("NICB[%d]: Src MAC: ", i);
        for (int j = 0; j < MAC_ADDRESS_LENGTH; ++j) {
            printf("%02x", nicbs[i].src_mac[j]);
        }
        printf(", Dest MAC: ");
        for (int j = 0; j < MAC_ADDRESS_LENGTH; ++j) {
            printf("%02x", nicbs[i].dest_mac[j]);
        }
        printf(", VLAN Tag: %u, Priority: %d, IP Checksum Enabled: %d\n",
               ntohs(nicbs[i].vlan_tag), nicbs[i].vlan_priority, nicbs[i].ip_checksum_enabled);
    }

    // Free allocated memory
    free(nicbs);

    // Clean up OpenSSL
    EVP_cleanup();
}

int main() {
    initialize_and_populate_nicbs();
    return 0;
}
