```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordManager;

// Function to initialize the record manager
RecordManager* init_record_manager(size_t initial_capacity) {
    RecordManager *rm = malloc(sizeof(RecordManager));
    rm->data = malloc(initial_capacity * sizeof(int));
    rm->capacity = initial_capacity;
    rm->count = 0;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

// Function to resize the array
void resize_record_manager(RecordManager *rm, size_t new_capacity) {
    int *new_data = realloc(rm->data, new_capacity * sizeof(int));
    if (new_data) {
        rm->data = new_data;
        rm->capacity = new_capacity;
    }
}

// Function to add a record
void add_record(RecordManager *rm, int value) {
    pthread_mutex_lock(&rm->lock);
    if (rm->count == rm->capacity) {
        resize_record_manager(rm, rm->capacity * 2);
    }
    rm->data[rm->count++] = value;
    pthread_mutex_unlock(&rm->lock);
}

// Function to get a record by index
int get_record(RecordManager *rm, size_t index) {
    pthread_mutex_lock(&rm->lock);
    int value = (index < rm->count) ? rm->data[index] : -1; // Return -1 if out of bounds
    pthread_mutex_unlock(&rm->lock);
    return value;
}

// Function to free the record manager
void destroy_record_manager(RecordManager *rm) {
    pthread_mutex_destroy(&rm->lock);
    free(rm->data);
    free(rm);
}

// Unit tests
#include <assert.h>

void test_record_manager() {
    RecordManager *rm = init_record_manager(10);

    // Test adding records
    for (int i = 0; i < 500000; ++i) {
        add_record(rm, i);
    }

    // Test retrieving records
    for (size_t i = 0; i < rm->count; ++i) {
        assert(get_record(rm, i) == (int)i);
    }

    // Test out of bounds access
    assert(get_record(rm, 500000) == -1);

    destroy_record_manager(rm);
}

void stress_test() {
    RecordManager *rm = init_record_manager(1000);

    for (int i = 0; i < 50000; ++i) {
        add_record(rm, rand());
    }

    // Random access test
    for (int i = 0; i < 100000; ++i) {
        int index = rand() % rm->count;
        assert(get_record(rm, index) == get_record(rm, index));
    }

    destroy_record_manager(rm);
}

int main() {
    test_record_manager();
    stress_test();
    printf("All tests passed.\n");
    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure that concurrent access is managed safely.
- **Dynamic Resizing**: The array resizes itself when necessary, doubling its capacity to minimize reallocations.
- **Efficiency Considerations**: The design balances between memory usage and performance, aiming for cache locality by using contiguous memory allocation.
- **Unit Tests**: Simple assertions are used to validate the correctness of operations under normal and stress conditions.']

