void initialize_data_structures(long offset_count, int key_count, int range_min, int range_max, long **offsets, int **keys, record ***records) {
    // Seed the random number generator
    srand(time(NULL));

    // Allocate memory for offsets and keys
    *offsets = (long*)malloc(offset_count * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int*)malloc(key_count * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records
    *records = (record**)malloc(key_count * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Failed to allocate memory for records pointers\n");
        exit(EXIT_FAILURE);
    }

    int *unique_values = (int*)malloc(key_count * sizeof(int));
    if (unique_values == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        fprintf(stderr, "Failed to allocate memory for unique values\n");
        exit(EXIT_FAILURE);
    }

