use std::env;
use std::fs;
use std::sync::{Mutex, Once};
use lazy_static::lazy_static;

// A global mutex to ensure thread safety for directory creation and env variable setting.
lazy_static! {
    static ref DIR_MUTEX: Mutex<()> = Mutex::new(());
}

fn create_directory_with_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Lock the mutex globally to prevent race conditions
    let _guard = DIR_MUTEX.lock().unwrap();

    let dir_path = format!("./{}", dir_name);

    if !dir_path.exists() {
        fs::create_dir(&dir_path)?;

        let existing_var = env::var_os("MY_DIR_ENV_VAR").is_some();
        if !existing_var {
            env::set_var("MY_DIR_ENV_VAR", &dir_path);
        }
    }

    Ok(())
}

// Example usage:
fn main() -> Result<(), Box<dyn std::error::Error>> {
    create_directory_with_env_var("new_directory")?;
    // Handle any subsequent logic here
    Ok(())
}
