                               [&content](const auto& pair) { return pair.second.content == content; });
        if (it != collection.end()) {
            collection.erase(it);
            return true;
        }
        return false;
    }

    StringData* retrieveString(const std::string& content) {
        std::shared_lock lock(mutex);
        auto it = std::find_if(collection.begin(), collection.end(),
