#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define MAX_RANGES 10000

typedef struct {
    uint8_t dest_mac[6];
    uint8_t src_mac[6];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    uint16_t vlan_tag; // Combined with priority
} NICB;

typedef struct {
    unsigned int min_value;
    unsigned int max_value;
    int inclusive_min;
    int inclusive_max;
} RangeDefinition;

typedef struct {
    int value;
} Record;

void initialize_random() {
    srand(time(NULL));
}

uint16_t generate_vlan_tag(int priority) {
    uint16_t tag = (priority & 0x0F) << 13; // Priority bits
    tag |= rand() % 4096;                  // VLAN ID
    return tag;
}

int is_overlapping(RangeDefinition a, RangeDefinition b) {
    if (a.inclusive_min && a.inclusive_max)
        return !(b.min_value > a.max_value || b.max_value < a.min_value);
    else if (a.inclusive_min)
        return !(b.min_value >= a.max_value || b.max_value <= a.min_value);
    else if (a.inclusive_max)
        return !(b.min_value > a.max_value || b.max_value >= a.min_value);
    else
        return !(b.min_value >= a.max_value || b.max_value <= a.min_value);
}

void merge_ranges(RangeDefinition *ranges, int count) {
    // Example logic for merging overlapping ranges; this is a basic approach.
    qsort(ranges, count, sizeof(RangeDefinition), (int(*)(const void*, const void*))strcmp);

    for (int i = 0; i < count - 1;) {
        if (is_overlapping(ranges[i], ranges[i + 1])) {
            ranges[i].max_value = ranges[i].max_value > ranges[i + 1].max_value ? 
                                  ranges[i].max_value : ranges[i + 1].max_value;
            memmove(&ranges[i + 1], &ranges[i + 2], (count - i - 1) * sizeof(RangeDefinition));
            count--;
        } else {
            i++;
        }
    }
}

int generate_random_within_range(unsigned int min, unsigned int max) {
    return rand() % (max - min + 1) + min;
}

void populate_records(Record *records, RangeDefinition range_def, size_t record_count) {
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = generate_random_within_range(range_def.min_value, range_def.max_value);
    }
}

void initialize_nicb_array(NICB *nicbs, size_t nicb_count, int priority) {
    for (size_t i = 0; i < nicb_count; ++i) {
        // Randomly generating MAC addresses
        for (int j = 0; j < 6; ++j) {
            nicbs[i].mac_header.dest_mac[j] = rand() % 256;
            nicbs[i].mac_header.src_mac[j] = rand() % 256;
        }

        nicbs[i].vlan_tag = generate_vlan_tag(priority);
    }
}

void initialize_and_manage_ranges(RangeDefinition *range_defs, int count) {
    // Initialize and sort the range definitions
    merge_ranges(range_defs, count);

    for (int i = 0; i < count; ++i) {
        printf("Range %d: [%u, %u] - Inclusive Min: %d, Inclusive Max: %d\n",
               i + 1,
               range_defs[i].min_value,
               range_defs[i].max_value,
               range_defs[i].inclusive_min,
               range_defs[i].inclusive_max);
    }
}

int main() {
    // Example usage
    initialize_random();

    NICB nicbs[100];
    initialize_nicb_array(nicbs, 100, 5); // Priority set to 5 for VLAN

    RangeDefinition ranges[MAX_RANGES] = {{10, 50, 1, 0}, {45, 60, 0, 1}};
    int range_count = 2;

    initialize_and_manage_ranges(ranges, range_count);

    Record records[100];
    populate_records(records, ranges[0], 100); // Using the first merged range

    for (int i = 0; i < 10; ++i) {
        printf("Record %d value: %d\n", i + 1, records[i].value);
    }

    return 0;
}
