void* semaphore_init(int initial_value) {
    sem_t* sem = malloc(sizeof(sem_t));
    if (!sem || sem_init(sem, 1 /* Pshared */ , initial_value)) {  // Allow sharing across processes
        free(sem);
        return NULL;
    }
    return sem;
}

int process_records(Record** records, size_t count) {
    *records = aligned_alloc(ALIGNMENT, count * sizeof(Record));
    if (!*records) return -1;

    long offsets_size = count * 10; // Example offset size
    for (size_t i = 0; i < count; ++i) {
