        if (!validate_record(&(*records)[i])) goto cleanup;
    }

    return 0;

cleanup:
    for (size_t i = 0; i < count; ++i) {
        free((*records)[i].offsets);
    }
    free(*records);
    *records = NULL;
    return -1;
}

void manage_resources(size_t record_count, sem_t** semaphore) {
    Record* records = NULL;

    if (process_records(&records, record_count)) {
        fprintf(stderr, "Failed to allocate and initialize resources\n");
        return;
    }

    *semaphore = semaphore_init(1);
    if (!*semaphore) {
        free(records->offsets); // Free offsets in each record
        free(records);
        records = NULL;
        fprintf(stderr, "Failed to initialize semaphore\n");
        return;
    }

    // Resource management logic here...

    // Cleanup at the end of resource usage
    for (size_t i = 0; i < record_count; ++i) {
        free(records[i].offsets);
    }
    free(records);

    sem_destroy(*semaphore);
    free(*semaphore);
}

