#define MAX_RECORDS 1000
#define MEMORY_LIMIT (1024 * 1024) // 1 MB for example
#define RETRY_COUNT 3

typedef struct {
    double value;
} Item;

typedef struct {
    int key;
    char identifier[64];
    Item* item;
    time_t last_accessed;
} Record;

Record records[MAX_RECORDS];
size_t current_memory_usage = 0;
int record_count = 0;

// Function to fetch temperature from the server
double fetch_temperature() {
    CURL *curl;
    CURLcode res;
    double temp = -1.0;
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080/temperature");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL); // Assume simple GET
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            double *data;
            curl_easy_getinfo(curl, CURLINFO_DATA_PTR, &data);
            temp = *data; // Assuming the server returns a plain double
        }
        curl_easy_cleanup(curl);
    }
    return temp;
}

// Function to generate unique identifier
void generate_identifier(int index) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    snprintf(records[index].identifier, sizeof(records[index].identifier),
             "ID-%d-Time:%ld-Day:%s", index, now,
             (t->tm_wday == 0 ? "Sun" : (t->tm_wday == 1 ? "Mon" : 
             (t->tm_wday == 2 ? "Tue" : (t->tm_wday == 3 ? "Wed" :
             (t->tm_wday == 4 ? "Thu" : (t->tm_wday == 5 ? "Fri" : "Sat")))))));
}

// Function to initialize records
void init_records(int key_min, int key_max) {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS && current_memory_usage <= MEMORY_LIMIT; ++i) {
        if (record_count >= MAX_RECORDS) break;

        Record *rec = &records[record_count];
        rec->key = rand() % (key_max - key_min + 1) + key_min;
        generate_identifier(record_count);
        double temp = fetch_temperature();
        time_t now = time(NULL);

        // Calculate item value and allocate memory
        rec->item = malloc(sizeof(Item));
        if (!rec->item) {
            perror("Failed to allocate memory for item");
            continue; // Skip this record on allocation failure
        }
        rec->item->value = (double)rec->key * temp / now;
        current_memory_usage += sizeof(Record) + sizeof(Item);

        rec->last_accessed = now;
        ++record_count;

        printf("Initialized Record %d: Key=%d, Identifier=%s\n", record_count - 1,
               rec->key, rec->identifier);
    }
}

// Function to release memory from least recently used records
void manage_memory() {
    if (current_memory_usage <= MEMORY_LIMIT) return;

    // Sort by last accessed time (simple bubble sort for example)
    for (int i = 0; i < record_count - 1; ++i) {
        for (int j = 0; j < record_count - i - 1; ++j) {
            if (records[j].last_accessed > records[j + 1].last_accessed) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }

    // Free memory from the least recently used
    while (current_memory_usage > MEMORY_LIMIT && record_count > 0) {
        Record *rec = &records[record_count - 1];
        free(rec->item);
        current_memory_usage -= sizeof(Record) + sizeof(Item);
        --record_count;
    }
}

// Logging function
void log_event(const char *level, const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", level, message); // Simple console logging for example
}

int main() {
    init_records(1, 1000);
    manage_memory();

    // Assuming you have a Java function to call here after initializing records

    return 0;
}
