import java.io.*;
import java.net.SocketTimeoutException;
import java.nio.channels.SocketChannel;
import java.util.logging.FileHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

public class PersistentConnection {
    private static final Logger logger = Logger.getLogger(PersistentConnection.class.getName());
    private static final String SERVER_ADDRESS = "remote.server.com";
    private static final int SERVER_PORT = 12345;
    private static final int TIMEOUT_MS = 5000; // Timeout in milliseconds
    private static final int RETRY_LIMIT = 3;

    public static void establishConnection() {
        FileHandler fh;
        try {
            fh = new FileHandler("persistent_connection.log");
            logger.addHandler(fh);
            SimpleFormatter formatter = new SimpleFormatter();
            fh.setFormatter(formatter);

            for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
                try (SocketChannel socketChannel = SocketChannel.open()) {
                    socketChannel.configureBlocking(true);
                    socketChannel.connect(new java.net.InetSocketAddress(SERVER_ADDRESS, SERVER_PORT));
                    socketChannel.socket().setSoTimeout(TIMEOUT_MS);

                    logger.log(Level.INFO, "Connection established on attempt {0}", attempt + 1);

                    // Handle data transfer here
                    handleData(socketChannel);

                } catch (IOException e) {
                    logger.log(Level.WARNING, "Failed to connect: " + e.getMessage());
                    if (e instanceof SocketTimeoutException) {
                        logger.log(Level.SEVERE, "Connection timed out. Retrying...");
                    }
                    try {
                        Thread.sleep(1000); // Wait before retrying
                    } catch (InterruptedException ie) {
                        logger.log(Level.WARNING, "Retry sleep interrupted: " + ie.getMessage());
                    }
                }
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to setup logging handler", e);
        }
    }

    private static void handleData(SocketChannel socketChannel) throws IOException {
        // Implement data handling logic
        byte[] buffer = new byte[1024];
        while (socketChannel.read(ByteBuffer.wrap(buffer)) > 0) {
            String received = new String(buffer).trim();
            logger.log(Level.INFO, "Received: {0}", received);

            // Process the data here

            // Example of sending a response
            socketChannel.write(ByteBuffer.wrap("Response".getBytes()));
        }
    }

    public static void main(String[] args) {
        establishConnection();
    }
}
