// Pseudo-random number generator initialization and reset function
typedef struct {
    unsigned int state;
} PRNG;

void prng_init(PRNG *prng, unsigned int seed) {
    prng->state = seed ? seed : rand();
}

unsigned int prng_next(PRNG *prng) {
    // Linear congruential generator (LCG)
    prng->state = 1103515245U * prng->state + 12345;
    return (unsigned int)(prng->state >> 16) & 0x7FFF; // Return a pseudo-random number
}

// Thread-safe dynamic array management for NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *dynamic_array, size_t initial_capacity) {
    pthread_mutex_init(&dynamic_array->lock, NULL);
    dynamic_array->capacity = initial_capacity;
    dynamic_array->array = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(64, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_dynamic_array(DynamicArray *dynamic_array) {
    pthread_mutex_lock(&dynamic_array->lock);
    free(dynamic_array->array);
    dynamic_array->array = NULL;
    dynamic_array->capacity = 0;
    pthread_mutex_unlock(&dynamic_array->lock);
    pthread_mutex_destroy(&dynamic_array->lock);
}

int add_pdu_to_dynamic_array(DynamicArray *dynamic_array, NFAPI_CRC_INDICATION_PDU_T pdu, unsigned int seed) {
    if (!validate_NFAPI_CRC_INDICATION_PDU_T(&pdu)) return 0;

    pthread_mutex_lock(&dynamic_array->lock);

    // Resize the array if necessary
    if (dynamic_array->capacity == 0) {
        dynamic_array->array = realloc(dynamic_array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        dynamic_array->capacity = 1;
    } else if ((size_t)(dynamic_array->capacity - 1) >= SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&dynamic_array->lock);
        return 0; // Prevent overflow
    } else if (dynamic_array->capacity == dynamic_array->used_capacity) {
        size_t new_capacity = dynamic_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dynamic_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dynamic_array->lock);
            return 0; // Memory allocation failure
        }
        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;
    }

    PRNG prng;
    prng_init(&prng, seed);
    pdu.CRCFLAG = (prng_next(&prng) % 2); // Set CRCFLAG based on pseudo-random value

    memcpy(dynamic_array->array + dynamic_array->used_capacity, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynamic_array->used_capacity++;

    pthread_mutex_unlock(&dynamic_array->lock);
    return 1;
}

// Unit test for the implementation
void run_unit_tests() {
    DynamicArray dynamic_array;
    init_dynamic_array(&dynamic_array, 2);

    // Test case: Add valid PDU
    NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 2, .CRC_INDICATION_REL8_TAG = 3 };
    assert(add_pdu_to_dynamic_array(&dynamic_array, pdu, 12345) == 1);

    // Test case: Add invalid PDU (invalid values)
    NFAPI_CRC_INDICATION_PDU_T invalid_pdu = { .RX_UE_INFORMATION_TAG = -1, .RNTI = 0, .CRC_INDICATION_REL8_TAG = -3 };
    assert(add_pdu_to_dynamic_array(&dynamic_array, invalid_pdu, 12345) == 0);

