int calculate_memory_usage(size_t num_elements) {
    size_t offset_size = num_elements * sizeof(long);
    size_t key_size = num_elements * sizeof(int);
    size_t record_size = num_elements * sizeof(record);
    return offset_size + key_size + record_size;
}

void* data_structure_manager(void* args) {
    int num_elements, min_val, max_val;
    sscanf(args, "%d %d %d", &num_elements, &min_val, &max_val);

