    free(keys);
    free(records);

    return NULL;
}

int main() {
    const char *args = "1000 10 50";
    pthread_t thread1, thread2;

    log_message("Starting data structure manager in thread 1.");
    if (pthread_create(&thread1, NULL, data_structure_manager, args)) {
        log_message("Failed to create thread 1.");
    }

    log_message("Starting data structure manager in thread 2.");
    if (pthread_create(&thread2, NULL, data_structure_manager, args)) {
        log_message("Failed to create thread 2.");
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

