// Thread-safe function to log messages
void safe_log(const char *message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_lock);
}

// Function to allocate and initialize arrays with performance monitoring
int allocate_and_initialize(long num_elements, int min_value, int max_value) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    clock_t start_time, end_time;

    pthread_mutex_lock(&monitor.lock);
    start_time = clock();
    offsets = (long *)malloc(num_elements * sizeof(long));
    keys = (int *)malloc(num_elements * sizeof(int));
    records = (record *)malloc(num_elements * sizeof(record));

    if (!offsets || !keys || !records) {
        safe_log("Memory allocation failed");
        pthread_mutex_unlock(&monitor.lock);
        free(offsets);
        free(keys);
        free(records);
        return FAILURE;
    }

    end_time = clock();
    monitor.total_allocation_time += (double)(end_time - start_time) / CLOCKS_PER_SEC;
    monitor.allocation_count++;

    for (long i = 0; i < num_elements; ++i) {
        offsets[i] = rand() % 10000; // Random offset
        keys[i] = rand_range(1, 100); // Random key within range

        int value = rand_range(min_value, max_value);
        if (value >= min_value && value <= max_value) {
            records[i].value = value;
        } else {
            safe_log("Validation failed for record");
            return FAILURE;
        }
    }

    safe_log("Memory allocation and initialization successful");

    pthread_mutex_unlock(&monitor.lock);
    return SUCCESS;
}

