['```c
#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_RECORDS 1024
#define MEMORY_CHUNK 512
#define ALIGNMENT 16

typedef struct {
    int value;
    long *offsets;
    int *keys;
    unsigned int ref_count;
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    size_t capacity;
    pthread_mutex_t lock;
    sem_t semaphore;
} ResourceManager;

void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_WIN32)
    ptr = _aligned_malloc(size, alignment);
#else
    if (posix_memalign(&ptr, alignment, size)) ptr = NULL;
#endif
    return ptr;
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void ResourceManagerInit(ResourceManager *manager, unsigned int initial_semaphore_value) {
    pthread_mutex_init(&manager->lock, NULL);
    sem_init(&manager->semaphore, 0, initial_semaphore_value);
    manager->capacity = MEMORY_CHUNK;

    for (size_t i = 0; i < MAX_RECORDS; ++i)
        manager->records[i] = NULL;

    while (1) {
        size_t total_size = sizeof(Record*) * MAX_RECORDS + sizeof(Record) * manager->capacity;
        void *ptr = aligned_alloc(ALIGNMENT, total_size);

        if (!ptr) break;

        Record *new_records = ptr + sizeof(Record*) * MAX_RECORDS;

        for (size_t i = 0; i < manager->capacity; ++i) {
            new_records[i].value = random_int(1, 100);
            new_records[i].offsets = aligned_alloc(ALIGNMENT, MEMORY_CHUNK * sizeof(long));
            new_records[i].keys = malloc(MEMORY_CHUNK * sizeof(int));

            if (!new_records[i].offsets || !new_records[i].keys) {
                free(new_records[i].offsets);
                free(new_records[i].keys);
                break;
            }

            for (size_t j = 0; j < MEMORY_CHUNK; ++j) {
                new_records[i].keys[j] = random_int(1, 10000); // Ensure unique keys
            }
            new_records[i].ref_count = 0;

            manager->records[i] = &new_records[i];
        }

        if (i == manager->capacity)
            break; 

        free(new_records);
    }
}

void ResourceManagerMonitor(ResourceManager *manager) {
    while (1) {
        sem_wait(&manager->semaphore);

        pthread_mutex_lock(&manager->lock);
        printf("Current Usage: %zu records\n", manager->capacity);
        // Add more detailed statistics here
        pthread_mutex_unlock(&manager->lock);
        sem_post(&manager->semaphore);

        sleep(60);
    }
}

void ResourceManagerCleanup(ResourceManager *manager) {
    for (size_t i = 0; i < MAX_RECORDS && manager->records[i]; ++i) {
        free(manager->records[i]->offsets);
        free(manager->records[i]->keys);
    }
    pthread_mutex_destroy(&manager->lock);
    sem_destroy(&manager->semaphore);
}

void* ResourceManagerGet(void *data) {
    ResourceManager *manager = (ResourceManager*)data;
    return manager;
}
