int generate_random_value(Range range, int type) {
    if (type == 0) { // integer
        return rand() % (range.max - range.min + 1) + range.min;
    } else if (type == 1) { // floating-point
        double scale = RAND_MAX / (double)(range.max - range.min);
        return (int)((rand() / (double)RAND_MAX) * scale) + range.min;
    }
    return 0; // default case
}

void manage_records(Record records[], int size, Range range) {
    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&records[i].lock);

        if ((range.inclusive_min && records[i].id >= range.min) ||
            (!range.inclusive_min && records[i].id > range.min)) {

            if ((range.inclusive_max && records[i].id <= range.max) ||
                (!range.inclusive_max && records[i].id < range.max)) {

                int type = 0; // Assuming integer for simplicity
                records[i].value = generate_random_value(range, type);
            }
        }

        pthread_mutex_unlock(&records[i].lock);
    }
}

void dynamic_range_update(Range new_range) {
    pthread_mutex_lock(&resource_manager.range_lock);

    resource_manager.ranges[resource_manager.count++] = new_range;

    if (resource_manager.count >= MAX_RANGES) {
        // Handle max range limit
    }

    pthread_cond_signal(&resource_manager.cond_var);
    pthread_mutex_unlock(&resource_manager.range_lock);
}

void remove_range(int index) {
    pthread_mutex_lock(&resource_manager.range_lock);

    if (index < 0 || index >= resource_manager.count) {
        pthread_mutex_unlock(&resource_manager.range_lock);
        return;
    }

    for (int i = index; i < resource_manager.count - 1; ++i) {
        resource_manager.ranges[i] = resource_manager.ranges[i + 1];
    }
    resource_manager.count--;

    pthread_mutex_unlock(&resource_manager.range_lock);
}

void garbage_collect() {
    // Implement a simple garbage collection strategy
    for (int i = 0; i < MAX_RANGES; ++i) {
        if (pthread_mutex_trylock(&resource_manager.ranges[i].lock) == 0) {
            pthread_mutex_unlock(&resource_manager.ranges[i].lock);
        }
    }
}

void DynamicResourceManager() {
