    std::size_t totalMemoryUsage = 0;
    std::mutex freqMutex;

    void manageMemoryFragmentation() {
        if (totalMemoryUsage > MEMORY_LIMIT_MB * KB_TO_BYTES * KB_TO_BYTES) {
            std::lock_guard<std::mutex> lock(freqMutex);

            // Find the least frequently used sensor to release
            auto it = std::min_element(accessFrequency.begin(), accessFrequency.end(),
                                       [](const auto& a, const auto& b) { return a.second < b.second; });

            if (it != accessFrequency.end()) {
                sensors[it->first].reset();
                totalMemoryUsage -= sizeof(SensorData) + sizeof(Event) * 10; // Assume average event queue size
                accessFrequency.erase(it);
