            posix_memalign(&alignedPtr, CACHE_ALIGNMENT_BYTES, sizeof(Sensor));
            Sensor* newSensor = new(alignedPtr) Sensor(newSensorData);
            sensors.push_back(std::unique_ptr<Sensor>(newSensor));

            newSensor->addEvent(newEvent);

            // Update access frequency and total memory usage
            {
                std::lock_guard<std::mutex> lock(freqMutex);
                int sensorIndex = sensors.size() - 1;
                accessFrequency[sensorIndex]++;
                totalMemoryUsage += sizeof(SensorData) + sizeof(Event) * newSensor->events.size();

                manageMemoryFragmentation();
            }

            // Verify data integrity
            if (!verifySensorDataIntegrity(*newSensor)) {
                std::cerr << "Data corruption detected, initiating self-healing mechanism." << std::endl;
                sensors[sensorIndex].reset(); // Reset corrupted sensor
