#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define MEMORY_THRESHOLD 1024 * 1024 // 1 MB for example
#define CACHE_SIZE 10

typedef struct {
    int value;
    char *str;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t allocated_memory;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t cache[MAX_STRING_LENGTH];
    int cache_index;
} DynamicCollection;

DynamicCollection collection = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, {}, 0};

int is_valid_virtual_address(void* address) {
    // Placeholder for actual validation logic
    return 1; // Assume all addresses are valid for this example
}

void log_invalid_address_failure(void* address) {
    printf("Invalid virtual address: %p\n", address);
}

Node* create_node(int value, const char *str) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->record.value = value;
    new_node->record.str = strndup(str, MAX_STRING_LENGTH);
    if (!new_node->record.str) {
        free(new_node);
        return NULL;
    }

    size_t node_size = sizeof(Node) + strlen(new_node->record.str) + 1;
    pthread_mutex_lock(&collection.lock);
    while (collection.allocated_memory + node_size > MEMORY_THRESHOLD) {
        pthread_cond_wait(&collection.cond, &collection.lock);
    }
    collection.allocated_memory += node_size;
    pthread_mutex_unlock(&collection.lock);

    return new_node;
}

void insert_record(int value, const char *str) {
    Node* new_node = create_node(value, str);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return;
    }

    pthread_mutex_lock(&collection.lock);
    new_node->next = collection.head;
    collection.head = new_node;
    pthread_mutex_unlock(&collection.lock);

    // Caching logic
    if (collection.cache_index < CACHE_SIZE) {
        collection.cache[collection.cache_index++] = value;
    }
}

void delete_record(int value) {
    pthread_mutex_lock(&collection.lock);
    Node *current = collection.head, *prev = NULL;

    while (current && current->record.value != value) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&collection.lock);
        return;
    }

    size_t node_size = sizeof(Node) + strlen(current->record.str) + 1;
    collection.allocated_memory -= node_size;

    if (prev) {
        prev->next = current->next;
    } else {
        collection.head = current->next;
    }

    free(current->record.str);
    free(current);

    pthread_cond_signal(&collection.lock);
    pthread_mutex_unlock(&collection.lock);
}

void traverse_records() {
    pthread_mutex_lock(&collection.lock);
    Node* current = collection.head;

    while (current) {
        printf("Value: %d, String: %s\n", current->record.value, current->record.str);
        current = current->next;
    }

    pthread_mutex_unlock(&collection.lock);
}

void initialize_collection(size_t num_records) {
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        int random_value = rand() % 100;
        char str[MAX_STRING_LENGTH];
        snprintf(str, MAX_STRING_LENGTH, "Record_%zu", i);
        insert_record(random_value, str);
    }
}

int main() {
    initialize_collection(50);

    traverse_records();

    delete_record(42); // Example deletion
    traverse_records();

    return 0;
}
