```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define ALIGNMENT 32
#define MAX_STRING_LENGTH 16

typedef struct item {
    int key;
    char *data; // Alphanumeric string
    struct item *next;
} Item;

typedef struct node {
    double value;
    Item *items_head;
    pthread_mutex_t mutex; // For thread safety
} Node;

typedef struct record {
    long offset;
    int key;
    Node *node;
    struct record *next;
} Record;

// Utility function for aligned memory allocation
void* aligned_alloc(size_t size, size_t alignment) {
    void *ptr = NULL;
#if defined(_POSIX_) && _POSIX >= 200112L
    ptr = memalign(alignment, size);
#else
    int ret;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

// Function to generate a random alphanumeric string
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *string = (char*)aligned_alloc(length + 1, ALIGNMENT);
    if (!string) return NULL;

    for (size_t i = 0; i < length; ++i) {
        size_t index = rand() % (sizeof(charset) - 1);
        string[i] = charset[index];
    }
    string[length] = '\0';

    return string;
}

// Function to initialize a node
Node* create_node(double value) {
    Node *node = (Node*)aligned_alloc(sizeof(Node), ALIGNMENT);
    if (!node) return NULL;

    node->value = value;
    node->items_head = NULL;
    pthread_mutex_init(&node->mutex, NULL);

    return node;
}

// Function to add an item to a node
int add_item_to_node(Node *node, int key, size_t string_length) {
    if (!node) return -1;

    pthread_mutex_lock(&node->mutex);

    Item *item = (Item*)aligned_alloc(sizeof(Item), ALIGNMENT);
    if (!item) {
        pthread_mutex_unlock(&node->mutex);
        return -1;
    }

    item->key = key;
    item->data = generate_random_string(string_length);
    if (!item->data) {
        free(item);
        pthread_mutex_unlock(&node->mutex);
        return -1;
    }
    item->next = node->items_head;
    node->items_head = item;

    pthread_mutex_unlock(&node->mutex);

    return 0;
}

// Function to create a record
Record* create_record(long offset, int key, double node_value) {
    Record *record = (Record*)aligned_alloc(sizeof(Record), ALIGNMENT);
    if (!record) return NULL;

    record->offset = offset;
    record->key = key;
    record->node = create_node(node_value);
    if (!record->node) {
        free(record);
        return NULL;
    }
    record->next = NULL;

    return record;
}

// Function to add a record to the collection
Record* add_record(Record **head, long offset, int key, double node_value) {
    Record *new_record = create_record(offset, key, node_value);
    if (!new_record) return NULL;

    pthread_mutex_t head_lock;
    pthread_mutex_init(&head_lock, NULL);

    pthread_mutex_lock(&head_lock);
    new_record->next = *head;
    *head = new_record;
    pthread_mutex_unlock(&head_lock);

    return new_record;
}

// Function to periodically update records from an external source
void* periodic_update(void *arg) {
    Record **records_head = (Record**)arg;

    while (1) {
        // Simulate fetching data from external source
        sleep(5); // Wait for 5 seconds

        pthread_mutex_t head_lock;
        pthread_mutex_init(&head_lock, NULL);

        pthread_mutex_lock(&head_lock);
        Record *current = *records_head;
        while (current) {
            // Update logic here: simulate fetching and updating
            current->node->value += 1.0; // Example update
            current = current->next;
        }
        pthread_mutex_unlock(&head_lock);
    }

    return NULL;
}

// Logging function for monitoring
void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int main() {
    srand(time(NULL));

    Record *records_head = NULL;

    // Add initial records
    add_record(&records_head, 0, 1, 10.5);
    add_record(&records_head, 1, 2, 20.5);

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, periodic_update, (void*)&records_head);

    // Run for a while to see updates
    sleep(15);

    pthread_cancel(update_thread);
    pthread_join(update_thread, NULL);

    return 0;
}
```

### Key Points:
