#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <jansson.h> // JSON library

// Structure alignment to 8-byte boundary
typedef struct {
    char key[64];
    char value_type; // 's' for string, 'i' for integer, 'c' for custom structure
    union {
        char *string_value;
        int integer_value;
        void *custom_value; // Custom structure pointer
    } data;
} ConfigEntry;

// Configuration management system structure
typedef struct {
    pthread_rwlock_t lock;
    ConfigEntry *entries;
    size_t entry_count;
    size_t capacity;
} ConfigManager;

// Initialize the configuration manager
ConfigManager* init_config_manager(size_t initial_capacity) {
    ConfigManager *manager = (ConfigManager *)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    pthread_rwlock_init(&manager->lock, NULL);
    manager->entries = (ConfigEntry *)aligned_alloc(8, initial_capacity * sizeof(ConfigEntry));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }
    manager->entry_count = 0;
    manager->capacity = initial_capacity;

    return manager;
}

// Add or update a configuration entry
int set_config_entry(ConfigManager *manager, const char *key, const char *value_type, void *value) {
    pthread_rwlock_wrlock(&manager->lock);

    // Check if key exists and update
    for (size_t i = 0; i < manager->entry_count; ++i) {
        if (strcmp(manager->entries[i].key, key) == 0) {
            strcpy(manager->entries[i].data.string_value, value_type[0] == 's' ? (char *)value : "");
            manager->entries[i].value_type = *value_type;
            pthread_rwlock_unlock(&manager->lock);
            return 0;
        }
    }

    // Add new entry
    if (manager->entry_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        ConfigEntry *new_entries = (ConfigEntry *)aligned_realloc(manager->entries, 8, new_capacity * sizeof(ConfigEntry));
        if (!new_entries) {
            pthread_rwlock_unlock(&manager->lock);
            return -1;
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    ConfigEntry *entry = &manager->entries[manager->entry_count++];
    strncpy(entry->key, key, sizeof(entry->key));
    entry->value_type = *value_type;

    if (*value_type == 's') {
        entry->data.string_value = strdup((char *)value);
    } else if (*value_type == 'i') {
        entry->data.integer_value = *(int *)value;
    } else {
        entry->data.custom_value = value; // Assume custom memory management
    }

    pthread_rwlock_unlock(&manager->lock);
    return 0;
}

// Serialize configuration to JSON
char* serialize_config(ConfigManager *manager) {
    pthread_rwlock_rdlock(&manager->lock);

    json_t *root = json_object();
    for (size_t i = 0; i < manager->entry_count; ++i) {
        json_t *value = NULL;
        if (manager->entries[i].value_type == 's') {
            value = json_string(manager->entries[i].data.string_value);
        } else if (manager->entries[i].value_type == 'i') {
            value = json_integer(manager->entries[i].data.integer_value);
        } else {
            // Handle custom structure serialization
        }
        json_object_set_new(root, manager->entries[i].key, value);
    }

    char *json_str = json_dumps(root, JSON_COMPACT);
    pthread_rwlock_unlock(&manager->lock);

    json_decref(root);
    return json_str;
}

// Deserialize configuration from JSON
int deserialize_config(ConfigManager *manager, const char *json_str) {
    pthread_rwlock_wrlock(&manager->lock);

    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) {
        pthread_rwlock_unlock(&manager->lock);
        return -1;
    }

    size_t entry_count = json_object_size(root);
    if (entry_count > manager->capacity) {
        size_t new_capacity = entry_count;
        ConfigEntry *new_entries = (ConfigEntry *)aligned_realloc(manager->entries, 8, new_capacity * sizeof(ConfigEntry));
        if (!new_entries) {
            pthread_rwlock_unlock(&manager->lock);
            json_decref(root);
            return -1;
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    manager->entry_count = entry_count;

    for (size_t i = 0; i < entry_count; ++i) {
        const char *key;
        json_t *value;
        json_object_iterate(root, &key, &value);

        ConfigEntry *entry = &manager->entries[i];
        strncpy(entry->key, key, sizeof(entry->key));

        if (json_is_string(value)) {
            entry->value_type = 's';
            entry->data.string_value = strdup(json_string_value(value));
        } else if (json_is_integer(value)) {
            entry->value_type = 'i';
            entry->data.integer_value = json_integer_value(value);
        } else {
            // Handle custom structure deserialization
        }
    }

    pthread_rwlock_unlock(&manager->lock);

    json_decref(root);
    return 0;
}

// Web API interface (pseudo-code)
void handle_get_request(ConfigManager *manager, const char *key) {
    pthread_rwlock_rdlock(&manager->lock);

    for (size_t i = 0; i < manager->entry_count; ++i) {
        if (strcmp(manager->entries[i].key, key) == 0) {
            // Respond with JSON
            char *json_str = serialize_config(manager);
            printf("GET Response: %s\n", json_str);
            free(json_str);
            break;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

void handle_put_request(ConfigManager *manager, const char *key, const char *value_type, void *value) {
    pthread_rwlock_wrlock(&manager->lock);

    // Validate and update
    if (set_config_entry(manager, key, value_type, value) == 0) {
        printf("PUT Request Successful\n");
    } else {
        printf("PUT Request Failed\n");
    }

    pthread_rwlock_unlock(&manager->lock);
}

void handle_delete_request(ConfigManager *manager, const char *key) {
    pthread_rwlock_wrlock(&manager->lock);

    for (size_t i = 0; i < manager->entry_count; ++i) {
        if (strcmp(manager->entries[i].key, key) == 0) {
            // Provide details before deletion
            printf("DELETE Request: Key to delete: %s\n", manager->entries[i].key);

            // Perform deletion logic
            break;
        }
    }

    pthread_rwlock_unlock(&manager->lock);
}

// Testing framework
void run_test(const char *label, void (*test_func)(void)) {
    printf("Running test: %s\n", label);

