        last_call_time = current_time;
        call_count = 0;
    }

    pthread_mutex_lock(&mutex);
    if (call_count >= RATE_LIMIT_CALLS_PER_SECOND) {
        pthread_mutex_unlock(&mutex);
        return true;
    }
    call_count++;
    pthread_mutex_unlock(&mutex);

    return false;
}

