            op->mode = OPERATION_MODE_A;

            return NULL;  // Success

        }, &op_pool[i])) {
            failed_allocations++;
            safeLogError("Failed to create a thread for operation initialization.");
        }
    }

    // Wait for all threads to finish.
    for (size_t i = 0; i < num_operations; ++i) {
        if (pthread_join(threads[i], NULL)) {
            failed_allocations++;
            safeLogError("Thread join failed during operation initialization.");
        }
    }

    *operations = &op_pool;
    *keys = key_array;

    // Check for allocation failures
    if (failed_allocations > 0) {
        free(counters);
        free(key_array);
        free(op_pool);
        return -5;  // Return error code indicating failed allocations.
    }

    return 0;  // Success
}
