MemoryPool* init_memory_pool(int initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        log_error("Failed to allocate memory for MemoryPool");
        return NULL;
    }

    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->capacity = initial_capacity;
    pool->size = 0;

    // Pre-allocate nodes
    for (int i = 0; i < initial_capacity; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            log_error("Failed to allocate memory for a node");
            // Free previously allocated nodes before exiting
            while (pool->head != NULL) {
                Node* temp = pool->head;
                pool->head = pool->head->next;
                free(temp);
            }
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }

        new_node->next = pool->head;
        pool->head = new_node;
    }
    pool->size = initial_capacity;
    return pool;
}

