    pthread_mutex_lock(&pool_mutex);
    allocated_memory += size;
    if (allocated_memory > POOL_SIZE) {
        // Handle over-allocation
        free(ptr);
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void aligned_free(void* ptr, size_t size) {
    pthread_mutex_lock(&pool_mutex);
    allocated_memory -= size;
    free(ptr);
    pthread_mutex_unlock(&pool_mutex);
}

// Function prototypes
Record* create_record(int index);
void cleanup_records(Record** records, int count);

// Main function to manage dynamic memory allocation and initialization
void initialize_data_structures(size_t long_count, size_t double_count,
                                size_t struct_count, size_t key_count,
                                size_t record_count) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate arrays with aligned memory
    long* long_array = (long*)aligned_alloc(16, sizeof(long) * long_count);
    if (!long_array) goto cleanup;

    double* double_array = (double*)aligned_alloc(16, sizeof(double) * double_count);
    if (!double_array) goto cleanup_long_array;

    struct {
        char str[50];
        unsigned int num;
    } *struct_array = (typeof(struct_array))aligned_alloc(16, sizeof(*struct_array) * struct_count);
    if (!struct_array) goto cleanup_double_array;

    int* key_array = (int*)aligned_alloc(16, sizeof(int) * key_count);
    if (!key_array) goto cleanup_struct_array;

    Record** record_array = (Record**)aligned_alloc(16, sizeof(*record_array) * record_count);
    if (!record_array) goto cleanup_key_array;

    // Initialize records
    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&lock);
        record_array[i] = create_record(i);
        if (!record_array[i]) goto cleanup_record_allocation;
        pthread_mutex_unlock(&lock);

        // Ensure total memory usage does not exceed 1 MB
        pthread_mutex_lock(&pool_mutex);
        while (allocated_memory > POOL_SIZE) {
            aligned_free(record_array[0], sizeof(*record_array[0]));
            record_array[0] = NULL;
            allocated_memory -= sizeof(*record_array[0]);
        }
        pthread_mutex_unlock(&pool_mutex);
    }

    // Memory usage validation and cleanup in case of failure
    if (allocated_memory > POOL_SIZE) {
        cleanup_records(record_array, record_count);
    }

    return; // Success

cleanup_record_allocation:
    for (size_t i = 0; i < i; ++i) {
        aligned_free(record_array[i], sizeof(*record_array[i]));
    }
cleanup_key_array:
    aligned_free(key_array, sizeof(*key_array) * key_count);
cleanup_struct_array:
    aligned_free(struct_array, sizeof(*struct_array) * struct_count);
cleanup_double_array:
    aligned_free(double_array, sizeof(*double_array) * double_count);
cleanup_long_array:
    aligned_free(long_array, sizeof(*long_array) * long_count);

cleanup:
    pthread_mutex_destroy(&lock);
}

// Create a record with dynamic memory allocation
Record* create_record(int index) {
    Record* record = (Record*)aligned_alloc(16, sizeof(Record));
    if (!record) return NULL;

    time_t now = time(NULL);
    snprintf(record->identifier, sizeof(record->identifier), "ID-%d-%ld", index, now);

    record->item = (Item*)aligned_alloc(16, sizeof(Item));
    if (!record->item) {
        aligned_free(record, sizeof(Record));
        return NULL;
    }

    // Initialize item with example data
    record->item->size = 64; // Example size
    record->item->u.d_val = 3.14159; // Example double value

    return record;
}

// Cleanup records and free allocated memory
void cleanup_records(Record** records, int count) {
    for (int i = 0; i < count; ++i) {
        if (records[i]) {
            aligned_free(records[i]->item, sizeof(*records[i]->item));
            aligned_free(records[i], sizeof(Record));
        }
    }
}

