#define MAX_HEADER_LEN 256
#define SYSTEM_MEMORY_LIMIT (1024 * 1024) // 1MB for example

typedef struct {
    int packet_id;
    unsigned char* payload;
    int header_len;
} DataPacket;

typedef struct {
    int value;
    long* offset_ptr;
} Record;

void initialize_data_packets(DataPacket* packets, size_t count) {
    if (!packets || count == 0) return;

    for (size_t i = 0; i < count; ++i) {
        packets[i].packet_id = i;

        // Ensure header_len does not exceed maximum
        packets[i].header_len = MAX_HEADER_LEN; 
        packets[i].payload = malloc(packets[i].header_len);

        if (!packets[i].payload) {
            perror("Failed to allocate memory for payload");

            // Cleanup already allocated packets in case of failure
            while (i > 0) {
                free(packets[--i].payload);
            }
            return;
        }
    }
}

long total_memory_allocated = 0;

int allocate_and_initialize_arrays(long** offsets, int* keys, size_t offset_count, int* key_count, 
                                   Record** records, size_t record_count) {

    long offset_size = sizeof(long) * offset_count;
    int key_size = sizeof(int) * (*key_count);

    // Check if the total memory usage exceeds system limit
    if (total_memory_allocated + offset_size + key_size > SYSTEM_MEMORY_LIMIT) {
        fprintf(stderr, "Insufficient system resources.\n");
        return -1;
    }

    *offsets = malloc(offset_size);
    if (!*offsets) {
        perror("Failed to allocate memory for offsets");
        return -1;
    }

    for (size_t i = 0; i < offset_count; ++i) {
        (*offsets)[i] = 0;
    }

    *keys = malloc(key_size);
    if (!*keys) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        return -1;
    }

    for (int i = 0; i < *key_count; ++i) {
        (*keys)[i] = i + 1;
    }

    total_memory_allocated += offset_size + key_size;

    // Allocate memory for records
    *records = malloc(sizeof(Record) * record_count);
    if (!*records) {
        perror("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % 100 + 1;
        if (i < offset_count) {
            (*records)[i].offset_ptr = &((*offsets)[i]);
        } else {
            fprintf(stderr, "Record index exceeds available offsets\n");
            free(*records);
            *records = NULL;
            return -1;
        }
    }

    total_memory_allocated += sizeof(Record) * record_count;

    // Seed the random number generator
    srand(time(NULL));

    return 0; 
}

void cleanup(DataPacket* packets, size_t packet_count,
             long* offsets, int* keys, Record* records) {

    if (packets) {
        for (size_t i = 0; i < packet_count; ++i) {
            free(packets[i].payload);
        }
    }

    if (offsets) {
        free(offsets);
    }

    if (keys) {
        free(keys);
    }

    if (records) {
        free(records);
    }

    total_memory_allocated = 0;
}

int main() {
    size_t data_packet_count = 10; 
    DataPacket* packets = malloc(sizeof(DataPacket) * data_packet_count);

    initialize_data_packets(packets, data_packet_count);

    long* offsets = NULL;
    int keys[100]; // Assume max key count is 100
    Record* records = NULL;

    if (allocate_and_initialize_arrays(&offsets, keys, sizeof(keys)/sizeof(int), &data_packet_count,
                                       &records, data_packet_count) != 0) {
        cleanup(packets, data_packet_count, offsets, keys, records);
        return -1;
    }

    // Verify integrity
    for (size_t i = 0; i < data_packet_count && records[i].offset_ptr; ++i) {
        if (*records[i].offset_ptr != 0) {
            fprintf(stderr, "Record %zu has invalid offset value\n", i);
        }
    }

    cleanup(packets, data_packet_count, offsets, keys, records);

    return 0;
}
