#define MAX_NICB 10000

typedef struct {
    unsigned char dest_mac[6];
    unsigned char src_mac[6];
    unsigned short vlan_tag;
    unsigned char priority;
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    unsigned char *vlan_tags;
    int num_vlans;
    int interface_type; // 1: Gigabit Ethernet, 2: Fast Ethernet, 3: Wireless LAN
    unsigned int ip_checksum_enabled;
    pthread_mutex_t lock;
} NICB;

typedef struct {
    int size;
    NICB **nicbs;
    void (*log)(const char *message);
    int (*validate_mac)(unsigned char mac[6]);
    unsigned char backup_macs[][6];
    int num_backup_macs;
    unsigned int seed;
} InitializationConfig;

void log_message(const char *message) {
    printf("%s\n", message);
}

int validate_mac_address(unsigned char mac[6]) {
    // Placeholder for external NMS validation logic
    return 1; // Assume all MACs are valid for this example
}

unsigned short calculate_checksum(unsigned short *buf, int nwords) {
    unsigned long sum = 0;
    while (nwords > 1) {
        sum += *buf++;
        if (sum & 0x80000000)
            sum = (sum & 0xFFFF) + (sum >> 16);
        nwords -= 2;
    }
    if (nwords == 1)
        sum += *(unsigned char *)buf;
    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);
    return ~sum;
}

void initialize_nicb(NICB *nicb, unsigned int seed, void (*log)(const char *message), 
                     int (*validate_mac)(unsigned char mac[6]), unsigned char backup_macs[][6], int num_backup_macs) {
    srand(seed);

    if (!nicb || !validate_mac) return;

    // Initialize MAC addresses
    for (int i = 0; i < 6; ++i) {
        nicb->mac_header.dest_mac[i] = rand() % 256;
        nicb->mac_header.src_mac[i] = rand() % 256;

        int valid = validate_mac(nicb->mac_header.src_mac);
        if (!valid) {
            for (int j = 0; j < num_backup_macs && !valid; ++j) {
                memcpy(nicb->mac_header.src_mac, backup_macs[j], 6);
                valid = validate_mac(nicb->mac_header.src_mac);
            }
            if (!valid) {
                log("Failed to initialize NICB due to invalid MAC address.");
                return;
            }
        }
    }

    // Set VLAN tag
    nicb->mac_header.vlan_tag = (rand() % 4096) | ((seed & 0x000F) << 13); // Use seed for deterministic priority bits

    log("NICB initialized successfully.");
}

void *initialize_nicb_thread(void *arg) {
    InitializationConfig *config = (InitializationConfig *)arg;
    NICB *nicb_array = *(config->nicbs);
    pthread_mutex_lock(&config->lock);

    for (int i = 0; i < config->size; ++i) {
        initialize_nicb(nicb_array[i], config->seed, config->log, config->validate_mac,
                        config->backup_macs, config->num_backup_macs);
    }

    pthread_mutex_unlock(&config->lock);
    return NULL;
}

NICB *initialize_nicbs(int size, InitializationConfig config) {
    if (size <= 0 || size > MAX_NICB) {
        config.log("Invalid NICB array size.");
        return NULL;
    }

    NICB **nicb_array = malloc(size * sizeof(NICB *));
    if (!nicb_array) {
        config.log("Memory allocation failed for NICB array.");
        return NULL;
    }

    pthread_mutex_init(&config.lock, NULL);

    // Create threads
    int num_threads = 4; // Example thread count
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_nicb_thread, &config)) {
            config.log("Failed to create thread.");
            free(nicb_array);
            return NULL;
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&config.lock);

    config.nicbs = &nicb_array;
    return *nicb_array;
}
