    record_t *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    sem_t *sem = create_semaphore(1);
    if (!sem) {
        printf("Failed to initialize semaphore\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    set_random_seed(seed);

    size_t record_size = sizeof(record_t);
    size_t aligned_record_size = (record_size + ALIGNMENT - 1) & ~(ALIGNMENT - 1);

    size_t current_capacity = total_records > MAX_ELEMENTS ? MAX_ELEMENTS : total_records;
    while (1) {
        records = aligned_alloc(ALIGNMENT, current_capacity * aligned_record_size);
        offsets = aligned_alloc(ALIGNMENT, current_capacity * sizeof(long));
        keys = aligned_alloc(ALIGNMENT, current_capacity * sizeof(int));

        if (!records || !offsets || !keys) {
            printf("Memory allocation failed. Attempting with more capacity...\n");
            free_aligned_alloc(records);
            free_aligned_alloc(offsets);
            free_aligned_alloc(keys);

            if (current_capacity + CHUNK_SIZE > total_records) {
                current_capacity = total_records;
            } else {
                current_capacity += CHUNK_SIZE;
            }

            continue; // Retry allocation
        }

        break; // Successful allocation
    }

    if (!records || !offsets || !keys) {
        printf("Failed to allocate memory after multiple attempts\n");
        destroy_semaphore(sem);
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < total_records; ++i) {
        int value, key;
        do {
            value = range_min + rand() % (range_max - range_min + 1);
            key = rand();
        } while ((i > 0 && keys[i-1] == key)); // Ensure unique keys

        records[i].value = value;
        records[i].offset = i * sizeof(record_t); // Simple example offset
        records[i].key = key;
        records[i].ref_count = 1; // Initial reference count
    }

    pthread_mutex_unlock(&mutex);

    destroy_semaphore(sem);

    return malloc(3 * sizeof(void*)); // Return pointer to an array of pointers
}
