typedef struct {
    int field;
} record;

#define ALIGNMENT 16

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
} MemoryManager;

// Utility function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL; // Allocation failed
    }
    return ptr;
}

// Simulate configuration retrieval with potential delays/failures
size_t fetch_configuration(size_t *num_offsets, size_t *num_keys, size_t *num_records) {
    srand(time(NULL));

    const int max_retries = 3;
    const int delay_range = 1000; // milliseconds

    for (int i = 0; i < max_retries; ++i) {
        if ((rand() % 10) < 2) { // Simulate a failure with a 20% chance
            printf("Warning: Configuration fetch failed, retrying...\n");
            sleep((rand() % delay_range) / 1000);
            continue;
        }

        *num_offsets = rand() % 1000 + 1;
        *num_keys = rand() % 500 + 1;
        *num_records = rand() % 300 + 1;

        printf("Configuration fetched: offsets=%zu, keys=%zu, records=%zu\n", 
               *num_offsets, *num_keys, *num_records);
        return 0; // Success
    }

    printf("Error: Configuration fetch failed after retries.\n");
    return -1; // Failure
}

// Function to manage memory for data structures
int initialize_memory_manager(MemoryManager *mm) {
    size_t num_offsets, num_keys, num_records;

    if (fetch_configuration(&num_offsets, &num_keys, &num_records)) {
        return -1; // Error in fetching configuration
    }

    mm->offsets = aligned_alloc(ALIGNMENT, num_offsets * sizeof(long));
    if (!mm->offsets) {
        goto cleanup;
    }

    mm->keys = aligned_alloc(ALIGNMENT, num_keys * sizeof(int));
    if (!mm->keys) {
        free(mm->offsets);
        goto cleanup;
    }

    mm->records = aligned_alloc(ALIGNMENT, num_records * sizeof(record));
    if (!mm->records) {
        free(mm->offsets);
        free(mm->keys);
        goto cleanup;
    }

    // Initialize records with random values
    for (size_t i = 0; i < num_records; ++i) {
        mm->records[i].field = rand() % 100 + 1;
    }

    mm->num_offsets = num_offsets;
    mm->num_keys = num_keys;
    mm->num_records = num_records;

    return 0; // Success

cleanup:
    if (mm->offsets) free(mm->offsets);
    if (mm->keys) free(mm->keys);
    if (mm->records) free(mm->records);

    return -1; // Error
}

// Function to periodically check for updates in configuration
void check_for_updates(MemoryManager *mm) {
    size_t new_num_offsets, new_num_keys, new_num_records;

    while (true) {
        sleep(5); // Check every 5 seconds

        if (!fetch_configuration(&new_num_offsets, &new_num_keys, &new_num_records)) {
            if ((new_num_offsets != mm->num_offsets) || 
                (new_num_keys != mm->num_keys) || 
                (new_num_records != mm->num_records)) {

                printf("Updating configuration...\n");

                // Free existing resources
                free(mm->offsets);
                free(mm->keys);
                free(mm->records);

                // Allocate new resources
                mm->offsets = aligned_alloc(ALIGNMENT, new_num_offsets * sizeof(long));
                if (!mm->offsets) {
                    printf("Error: Failed to allocate memory for offsets.\n");
                    continue;
                }

                mm->keys = aligned_alloc(ALIGNMENT, new_num_keys * sizeof(int));
                if (!mm->keys) {
                    free(mm->offsets);
                    printf("Error: Failed to allocate memory for keys.\n");
                    continue;
                }

                mm->records = aligned_alloc(ALIGNMENT, new_num_records * sizeof(record));
                if (!mm->records) {
                    free(mm->offsets);
                    free(mm->keys);
                    printf("Error: Failed to allocate memory for records.\n");
                    continue;
                }

                // Initialize records with random values
                for (size_t i = 0; i < new_num_records; ++i) {
                    mm->records[i].field = rand() % 100 + 1;
                }

                mm->num_offsets = new_num_offsets;
                mm->num_keys = new_num_keys;
                mm->num_records = new_num_records;

            } else {
                printf("Configuration unchanged.\n");
            }
        }
    }
}

int main() {
    MemoryManager mm = {0};

    if (initialize_memory_manager(&mm)) {
        fprintf(stderr, "Failed to initialize memory manager.\n");
        return EXIT_FAILURE;
    }

    // Simulate periodic configuration checking in a separate thread
    #ifdef _WIN32
        HANDLE hThread = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)check_for_updates, &mm, 0, NULL);
        WaitForSingleObject(hThread, INFINITE);
        CloseHandle(hThread);
    #else
        pthread_t thread;
        if (pthread_create(&thread, NULL, (void *(*)(void *))check_for_updates, &mm)) {
            fprintf(stderr, "Error creating thread.\n");
            return EXIT_FAILURE;
        }
        pthread_join(thread, NULL);
    #endif

    // Cleanup
    free(mm.offsets);
    free(mm.keys);
    free(mm.records);

    return EXIT_SUCCESS;
}
