#define INITIAL_SIZE 1000
#define MAX_SIZE 10000

typedef struct {
    long *offset;
    int key;
} Record;

// Function declarations
void initialize_data(long **offsets, int **keys, size_t *size);
long* allocate_memory(size_t *current_size, size_t max_size, size_t increment, long **array);
int* allocate_memory_int(size_t *current_size, size_t max_size, size_t increment, int **array);
void add_unique_long(long **offsets, long value, size_t current_size, size_t max_size);
void add_unique_int(int **keys, int value, size_t current_size, size_t max_size);
int check_for_duplicates(long *offsets, long value, size_t size);
int check_for_key_duplicates(int *keys, int value, size_t size);

// Main function to manage offsets and keys
void manage_data_structures(Record **records) {
    long *offsets = NULL;
    int *keys = NULL;
    size_t offsets_size = 0, keys_size = 0;

    // Initialize memory for offsets and keys
    initialize_data(&offsets, &keys, &offsets_size);

    // Allocate initial records array
    *records = (Record *)malloc(INITIAL_SIZE * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    size_t records_count = 0;
    srand(time(NULL));

    while (records_count < INITIAL_SIZE) {
        long offset_value = rand() % MAX_SIZE; // Adjust range as needed
        int key_value = rand() % MAX_SIZE;

        if (!check_for_duplicates(offsets, offset_value, offsets_size)) {
            add_unique_long(&offsets, offset_value, offsets_size, MAX_SIZE);
        }

        if (!check_for_key_duplicates(keys, key_value, keys_size)) {
            add_unique_int(&keys, key_value, keys_size, MAX_SIZE);
        }

        // Assign to records
        (*records)[records_count].offset = &offsets[offsets_size - 1];
        (*records)[records_count].key = key_value;

        records_count++;
    }
}

// Function implementations

void initialize_data(long **offsets, int **keys, size_t *size) {
    *offsets = (long *)malloc(INITIAL_SIZE * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    *keys = (int *)malloc(INITIAL_SIZE * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    *size = INITIAL_SIZE;
}

long* allocate_memory(size_t *current_size, size_t max_size, size_t increment, long **array) {
    if (*current_size >= max_size)
        return NULL;

    size_t new_size = (*current_size < max_size - increment) ? *current_size + increment : max_size;
    long *new_array = (long *)realloc(*array, new_size * sizeof(long));

    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = *current_size; i < new_size; ++i)
        new_array[i] = 0; // Initialize new space

    *current_size = new_size;
    return new_array;
}

int* allocate_memory_int(size_t *current_size, size_t max_size, size_t increment, int **array) {
    if (*current_size >= max_size)
        return NULL;

    size_t new_size = (*current_size < max_size - increment) ? *current_size + increment : max_size;
    int *new_array = (int *)realloc(*array, new_size * sizeof(int));

    if (!new_array) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = *current_size; i < new_size; ++i)
        new_array[i] = 0; // Initialize new space

    *current_size = new_size;
    return new_array;
}

void add_unique_long(long **offsets, long value, size_t current_size, size_t max_size) {
    if (check_for_duplicates(*offsets, value, current_size)) 
        return;

    if (allocate_memory(&current_size, max_size, 1000, offsets) == NULL) { // Increment by 1000
        perror("Failed to allocate more memory for offsets");
        exit(EXIT_FAILURE);
    }

    (*offsets)[current_size - 1] = value;
}

void add_unique_int(int **keys, int value, size_t current_size, size_t max_size) {
    if (check_for_key_duplicates(*keys, value, current_size)) 
        return;

    if (allocate_memory_int(&current_size, max_size, 1000, keys) == NULL) { // Increment by 1000
        perror("Failed to allocate more memory for keys");
        exit(EXIT_FAILURE);
    }

    (*keys)[current_size - 1] = value;
}

int check_for_duplicates(long *offsets, long value, size_t size) {
    for (size_t i = 0; i < size; ++i)
        if (offsets[i] == value)
            return 1;
    return 0;
}

int check_for_key_duplicates(int *keys, int value, size_t size) {
    for (size_t i = 0; i < size; ++i)
        if (keys[i] == value)
            return 1;
    return 0;
}
