} DataManager;

#define GROWTH_FACTOR 2
#define INITIAL_CAPACITY 10

DataManager* create_data_manager() {
    DataManager *manager = malloc(sizeof(DataManager));
    manager->data_array = calloc(INITIAL_CAPACITY, sizeof(Data));
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void log_message(const char *message) {
    // Integrate with your logging framework here
    printf("%s\n", message);
}

void resize_data_array(DataManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->mutex);

    Data *new_data_array = realloc(manager->data_array, new_capacity * sizeof(Data));
    if (new_data_array == NULL) {
        log_message("Failed to allocate memory for data array resizing.");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->data_array = new_data_array;
    manager->capacity = new_capacity;

    log_message("Data array resized successfully.");

    pthread_mutex_unlock(&manager->mutex);
}

void add_data(DataManager *manager, long number, const char *str) {
    pthread_mutex_lock(&manager->mutex);

    if (number_of_elements(manager) >= manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        resize_data_array(manager, new_capacity);
    }

    Data *data_entry = &manager->data_array[number_of_elements(manager)];
    data_entry->number = number;

    size_t str_length = strlen(str) + 1; // Include null terminator
    data_entry->str = malloc(str_length);
    if (data_entry->str == NULL) {
        log_message("Failed to allocate memory for string.");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    memcpy(data_entry->str, str, str_length);

    log_message("Data added successfully.");

    pthread_mutex_unlock(&manager->mutex);
}

size_t number_of_elements(const DataManager *manager) {
    // Implement logic to determine the current number of elements
