['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 500
#define MAX_RECORDS 200

typedef struct {
    long *offset;
    int key;
} Record;

Record *records;
long offsets[MAX_OFFSETS];
int keys[MAX_KEYS];

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

void initialize_arrays() {
    srand(time(NULL));

    // Initialize offsets with random unique values
    for (int i = 0; i < MAX_OFFSETS; ++i) {
        offsets[i] = rand() % (LONG_MAX / 2); // Ensure no overflow
    }

    // Initialize keys with random unique values
    int used_keys[MAX_KEYS] = {0};
    for (int i = 0; i < MAX_KEYS; ++i) {
        do {
            keys[i] = rand() % INT_MAX;
        } while (used_keys[keys[i]]);
        used_keys[keys[i]] = 1;
    }
}

void initialize_records(int num_records) {
    records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_message("Memory allocation for records failed");
        exit(EXIT_FAILURE);
    }

    int used_offsets[MAX_OFFSETS] = {0};
    int used_keys[MAX_KEYS] = {0};

    for (int i = 0; i < num_records; ++i) {
        // Assign unique offset
        do {
            int idx = rand() % MAX_OFFSETS;
        } while (used_offsets[idx]);
        long *offset_ptr = &offsets[idx];
        records[i].offset = offset_ptr;
        used_offsets[idx] = 1;

        // Assign unique key
        do {
            int key_idx = rand() % MAX_KEYS;
        } while (used_keys[key_idx]);
        records[i].key = keys[key_idx];
        used_keys[key_idx] = 1;
    }
}

void compact_arrays(int *new_offsets, long **new_offset_ptrs) {
    pthread_mutex_lock(&mutex);

    int new_size = 0;
    for (int i = 0; i < MAX_OFFSETS; ++i) {
        if (!used_offsets[i]) continue;

        new_offsets[new_size] = offsets[i];
        (*new_offset_ptrs)[new_size] = &new_offsets[new_size];
        used_offsets[new_size] = 1;
        new_size++;
    }

    pthread_mutex_unlock(&mutex);
}

void serialize_data(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization");
        return;
    }

    fwrite(offsets, sizeof(long), MAX_OFFSETS, file);
    fwrite(keys, sizeof(int), MAX_KEYS, file);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        fwrite(records[i].offset, sizeof(long*), 1, file);
        fwrite(&records[i].key, sizeof(int), 1, file);
    }

    fclose(file);
    log_message("Data serialized successfully");
}

void deserialize_data(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization");
        return;
    }

    fread(offsets, sizeof(long), MAX_OFFSETS, file);
    fread(keys, sizeof(int), MAX_KEYS, file);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        long *offset_ptr;
        fread(&offset_ptr, sizeof(long*), 1, file);
        records[i].offset = offset_ptr;

        fread(&records[i].key, sizeof(int), 1, file);
    }

    fclose(file);
    log_message("Data deserialized successfully");
}

void cleanup() {
    free(records);
    pthread_mutex_destroy(&mutex);
    log_message("Resources deallocated and mutex destroyed");
}

int main() {
    initialize_arrays();
    initialize_records(MAX_RECORDS);

    int new_offsets[MAX_OFFSETS];
    long *new_offset_ptrs = malloc(MAX_OFFSETS * sizeof(long*));
    compact_arrays(new_offsets, &new_offset_ptrs);

    serialize_data("data.dat");
    deserialize_data("data.dat");

    cleanup();
    return 0;
}
```']

