ErrorCode allocate_distributed_file_system(long *offsets, int *ids, record **records, size_t num_records, u_char *hash_value) {
    if (num_records > MAX_RECORDS || !offsets || !ids || !records || !hash_value) {
        return INVALID_INPUT;
    }

    srand(time(NULL));
    pthread_mutex_t lock;

    // Allocate and initialize offsets
    offsets = (long *)calloc(num_records, sizeof(long));
    if (!offsets) {
        return ALLOC_FAILURE;
    }
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;
    }

    // Allocate and initialize ids
    ids = (int *)malloc(num_records * sizeof(int));
    if (!ids) {
        free(offsets);
        return ALLOC_FAILURE;
    }
    for (size_t i = 0; i < num_records; ++i) {
        ids[i] = i + 1;
    }

    // Allocate and initialize records
    *records = (record *)malloc(num_records * sizeof(record));
    if (!(*records)) {
        free(offsets);
        free(ids);
        return ALLOC_FAILURE;
    }
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].inode = rand() % 10000 + 1;
        (*records)[i].file_size = rand() % 100000 + 1;
        (*records)[i].timestamp = time(NULL);
