    for (size_t i = 0; i < num_records; ++i) {
        temp_hash[i % sizeof(temp_hash)] ^= ((u_char *)offsets)[i % sizeof(long)];
        temp_hash[(i + 1) % sizeof(temp_hash)] ^= ids[i];
        temp_hash[(i + 2) % sizeof(temp_hash)] ^= (u_char)((*records)[i].inode >> i);
    }
    memcpy(hash_value, temp_hash, sizeof(temp_hash));

    // Example logging
    printf("Initialized file system structures with %zu records.\n", num_records);

    pthread_mutex_init(&lock, NULL);

    // Placeholder for additional features like encryption key rotation, etc.

    return SUCCESS;
}

// Cleanup function to be called on failure or at the end of use
void cleanup(long *offsets, int *ids, record *records) {
