#include <pthread.h>

// Define operation_type enum
typedef enum {
    OPERATION_TYPE_A,
    OPERATION_TYPE_B,
    OPERATION_TYPE_C
} operation_type;

// Define the operation structure
typedef struct Operation {
    operation_type op_type;
    char *details_buffer;
    size_t buffer_length;
} Operation;

// Define the task structure
typedef struct Task {
    long start_time;
    int priority_level;
    Operation *operation;
    pthread_mutex_t ref_count_lock; // Mutex for thread-safe reference counting
    unsigned int ref_count;        // Reference count for shared operations
    int unique_id;                 // Unique identifier for each task
} Task;

// Thread-safe memory allocation function
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE); // Or handle error as needed
    }
    return ptr;
}

// Thread-safe memory deallocation function
void safe_free(void *ptr) {
    free(ptr);
}

// Function to initialize operation details buffer
void init_operation_details(Operation *operation, const char *details, size_t max_length) {
    strncpy(operation->details_buffer, details, max_length - 1);
    operation->details_buffer[max_length - 1] = '\0';
}

// Function to generate a random integer between min and max (inclusive)
int rand_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to allocate an array of tasks
Task* create_tasks(size_t num_tasks) {
    Task *tasks = safe_malloc(num_tasks * sizeof(Task));

    // Initialize random number generator
    srand(time(NULL));

    for (size_t i = 0; i < num_tasks; ++i) {
        pthread_mutex_init(&tasks[i].ref_count_lock, NULL);
        tasks[i].start_time = time(NULL) + i;
        tasks[i].priority_level = rand_int(1, 10);

        // Allocate and initialize operation structure
        Operation *operation = safe_malloc(sizeof(Operation));
        operation->op_type = (operation_type)rand_int(0, 2);

        const size_t buffer_length = 256;
        operation->details_buffer = safe_malloc(buffer_length);
        init_operation_details(operation, "Example Operation Details", buffer_length);
        operation->buffer_length = buffer_length;

        tasks[i].operation = operation;
        tasks[i].ref_count = 1; // Initial reference count
        tasks[i].unique_id = (int)i; // Simple unique identifier based on index

        pthread_mutex_lock(&tasks[i].ref_count_lock);
        // If another task references the same operation, increase ref_count
        for (size_t j = 0; j < i; ++j) {
            if (tasks[j].operation == operation) {
                tasks[i].ref_count++;
                break;
            }
        }
        pthread_mutex_unlock(&tasks[i].ref_count_lock);
    }

    return tasks;
}

// Function to free tasks and their resources
void destroy_tasks(Task *tasks, size_t num_tasks) {
    for (size_t i = 0; i < num_tasks; ++i) {
        if (tasks[i].ref_count > 1 || i == 0) { // Only deallocate shared operation if no other references exist
            pthread_mutex_lock(&tasks[i].ref_count_lock);
            tasks[i].ref_count--;
            if (tasks[i].ref_count == 0) {
                safe_free(tasks[i].operation->details_buffer);
                safe_free(tasks[i].operation);
            }
            pthread_mutex_unlock(&tasks[i].ref_count_lock);
        }
        pthread_mutex_destroy(&tasks[i].ref_count_lock);
    }

    safe_free(tasks);
}

// Main function for demonstration purposes
int main() {
    size_t num_tasks = 10;
    Task *tasks = create_tasks(num_tasks);

    // Do something with tasks...

    destroy_tasks(tasks, num_tasks);

    return 0;
}
