        free_aligned(records[i].keys);
        // Free task list and dependencies
        Task *task = records[i].tasks;
        while (task != NULL) {
            Task *next_task = task->next;
            Dependency *dep = task->dependencies;
            while (dep != NULL) {
                Dependency *next_dep = dep->next;
                free_aligned(dep);
                dep = next_dep;
            }
            free_aligned(task);
            task = next_task;
