typedef struct {
    long *offset_ptr;
    int key_index;
    char data[20];
} record;

record* allocate_memory(size_t offsets_size) {
    if (offsets_size <= 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        exit(EXIT_FAILURE);
    }

    size_t keys_size = offsets_size / 2;
    if (keys_size == 0) {
        fprintf(stderr, "Error: Calculated keys size is zero. Invalid input.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for arrays
    long *offsets = (long *)malloc(offsets_size * sizeof(long));
    int *keys = (int *)malloc(keys_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records
    record *records = (record *)malloc(offsets_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize and set pointers in records
    srand((unsigned int)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < offsets_size; ++i) {
        records[i].offset_ptr = &offsets[i];

        if (i < keys_size) {
            records[i].key_index = i;
            records[i].keys = &keys[records[i].key_index]; // Set the pointer to keys
            records[i].keys[0] = rand() % 1000 + 1; // Initialize with random value between 1 and 1000
        } else {
            records[i].key_index = -1; // Indicate no corresponding key for excess offsets
        }

        // Initialize char array to zeros
        for (int j = 0; j < 20; ++j) {
            records[i].data[j] = '\0';
        }
    }

    // Validation check
    for (size_t i = 0; i < offsets_size; ++i) {
        if (!records[i].offset_ptr || 
            (i < keys_size && !records[i].keys)) {
            fprintf(stderr, "Error: Pointer validation failed.\n");
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }
    }

    return records;
}

void cleanup(record *records, size_t offsets_size) {
    if (records) {
        free(records);  // Free the contiguous block of record structures
    }
}

int main() {
    size_t offsets_size;

    printf("Enter the size for the offsets array: ");
    if (scanf("%zu", &offsets_size) != 1 || getchar() != '\n') {
        fprintf(stderr, "Error: Invalid input.\n");
        return EXIT_FAILURE;
    }

    record *records = allocate_memory(offsets_size);

    // Use records...

    cleanup(records, offsets_size);
    return 0;
}
