#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long *array;
    size_t size;
} Offset;

typedef struct {
    int *array;
    size_t size;
} Keys;

typedef struct {
    Record *records;
    size_t size;
} Records;

#define ERROR_CODE -1

int initialize_structures(Offset *offset, Keys *keys, Records *records, size_t n, size_t m) {
    if (n < 0 || m < 0) {
        return ERROR_CODE; // Invalid input parameters
    }

    // Allocate and initialize the offset array
    offset->size = n;
    offset->array = (long *)malloc(n * sizeof(long));
    if (!offset->array) {
        return ERROR_CODE; // Memory allocation failed
    }
    for (size_t i = 0; i < n; ++i) {
        offset->array[i] = (long)i;
    }

    // Allocate and initialize the keys array
    keys->size = n + m;
    keys->array = (int *)malloc((n + m) * sizeof(int));
    if (!keys->array) {
        free(offset->array); // Clean up previously allocated memory
        return ERROR_CODE; // Memory allocation failed
    }
    for (size_t i = 0; i < n + m; ++i) {
        keys->array[i] = (int)i;
    }

    // Initialize random number generator
    unsigned int seed;
    if (time(NULL) == ((unsigned long)-1)) {
        fprintf(stderr, "Failed to get current time for seeding\n");
        free(offset->array);
        free(keys->array);
        return ERROR_CODE;
    }
    srand(seed = (unsigned int)time(NULL));

    // Allocate and initialize the records array
    records->size = n;
    records->records = (Record *)malloc(n * sizeof(Record));
    if (!records->records) {
        free(offset->array); // Clean up previously allocated memory
        free(keys->array);
        return ERROR_CODE; // Memory allocation failed
    }
    for (size_t i = 0; i < n; ++i) {
        records->records[i].value = rand() % 1001;
    }

    return 0; // Success
}

void cleanup_structures(Offset *offset, Keys *keys, Records *records) {
    free(offset->array);
    free(keys->array);
    free(records->records);
}
