Resource* allocate_resources(int num_resources) {
    if (num_resources <= 0) return NULL;

    Resource *resources = (Resource *)malloc(num_resources * sizeof(Resource));
    if (!resources) {
        log_debug_info("Memory allocation for resources failed.");
        return NULL;
    }

    for (int i = 0; i < num_resources; ++i) {
        resources[i].resource_level = (double)i + 1.0; // Initialize based on index.

        // Probabilistic model: Example using a simple random choice.
        bool status = rand() % 2 == 0;
        resources[i].status_flag = status;

        resources[i].usage_pattern = (UsagePattern *)malloc(sizeof(UsagePattern));
        if (!resources[i].usage_pattern) {
            log_debug_info("Memory allocation for usage pattern failed.");
            free(resources); // Cleanup previously allocated memory.
            return NULL;
        }

        // Select a pattern type from the predefined list.
        resources[i].usage_pattern->type = (pattern_type)(rand() % 3);

        // Example timeline initialization.
        for (int j = 0; j < 10; ++j) {  // Adjust as needed.
            resources[i].usage_pattern->usage_intervals[j].start_time = rand() % 100;
            resources[i].usage_pattern->usage_intervals[j].end_time = rand() % 100 + 50;
        }
    }

    log_debug_info("Resources allocated successfully.");
    return resources;
}

void free_resources(Resource *resources, int num_resources) {
    if (!resources) return;

    for (int i = 0; i < num_resources; ++i) {
        if (resources[i].usage_pattern) {
            free(resources[i].usage_pattern);
        }
    }

    free(resources);
}
