#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long *offsets;
    int keys_count;
    char data[20];
} record;

static size_t total_allocations = 0; // Counter for resource tracking

void* log_and_allocate(size_t size, const char* message) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "%s: Memory allocation failed\n", message);
        exit(EXIT_FAILURE);
    }
    total_allocations++;
    return ptr;
}

size_t get_total_allocations() {
    return total_allocations;
}

record* allocateRecords(int offsets_size, int keys_size) {
    if (offsets_size <= 0 || keys_size <= 0 || keys_size > offsets_size / 2) {
        fprintf(stderr, "Invalid input: Sizes must be positive and keys size should not exceed half of offsets size.\n");
        exit(EXIT_FAILURE);
    }

    // Calculate total memory needed
    size_t record_count = offsets_size;
    size_t total_memory_size = sizeof(record) * record_count;

    // Allocate a single block of memory for all records
    record* records = (record*)log_and_allocate(total_memory_size, "allocateRecords");

    // Initialize each record's data and allocate additional memory as needed
    for (int i = 0; i < offsets_size; ++i) {
        records[i].offsets = (long*)log_and_allocate(sizeof(long), "Allocate long pointer");
        memset(records[i].data, 0, sizeof(records[i].data));
    }
    records[record_count - 1].keys_count = keys_size;

    return records;
}

void freeRecords(record* records, int offsets_size) {
    if (records == NULL) return;

    for (int i = 0; i < offsets_size; ++i) {
        if (records[i].offsets != NULL) {
            free(records[i].offsets);
        }
    }
    free(records);
}

