#define MAX_MEMORY_PERCENTAGE 0.8

typedef struct {
    int value;
} record;

// Mutex for thread-safe access to records
pthread_mutex_t record_mutex = PTHREAD_MUTEX_INITIALIZER;

void* memory_pool; // Custom memory pool
size_t total_memory_size;

void allocate_and_initialize(int offset_array_size, unsigned int seed, int min_random, int max_random) {
    size_t system_memory = getTotalSystemMemory();  // Implement this function to get available system memory
    if (offset_array_size * sizeof(long) > 0.5 * system_memory) {
        fprintf(stderr, "Offset array size exceeds 50% of total available memory.\n");
        return;
    }

    int keys_array_size = offset_array_size / 2;

    // Calculate the maximum allowable memory usage
    size_t max_allowable_memory = MAX_MEMORY_PERCENTAGE * system_memory;

    size_t required_memory = 
        (offset_array_size * sizeof(long)) + 
        (keys_array_size * sizeof(int)) +
        (offset_array_size * sizeof(record));

    if (required_memory > max_allowable_memory) {
        fprintf(stderr, "Required memory exceeds 80% of total available system memory.\n");
        return;
    }

    // Allocate custom memory pool
    memory_pool = malloc(required_memory);
    if (!memory_pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    total_memory_size = required_memory;

    long *offset_array = (long *)memory_pool;
    int *keys_array = (int *)(offset_array + offset_array_size);
    record *records_array = (record *)(keys_array + keys_array_size);

    // Initialize random number generator
    srand(seed);

    for (size_t i = 0; i < offset_array_size; ++i) {
        offset_array[i] = i * 10; // Example initialization
        records_array[i].value = min_random + rand() % (max_random - min_random + 1);
    }

    for (size_t i = 0; i < keys_array_size; ++i) {
        keys_array[i] = i;
    }
}

void free_resources() {
    if (memory_pool) {
        free(memory_pool);
        memory_pool = NULL;
    }
}

// Thread-safe access to records
record* get_record(size_t index, size_t offset_array_size) {
    pthread_mutex_lock(&record_mutex);

    record *records_array = (record *)((long *)memory_pool + offset_array_size / 2 + offset_array_size);

    if (index < offset_array_size) {
        return &records_array[index];
    }

    pthread_mutex_unlock(&record_mutex);
    return NULL;
}

size_t getTotalSystemMemory() {
    // Implement this function to get the total available system memory
    // This is platform-specific; on Unix-like systems, you might use sysinfo or similar.
    return 1024 * 1024 * 1024; // Example: 1GB for demonstration purposes
}

int main(int argc, char **argv) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <offset_array_size> <seed> <min_random_value> <max_random_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int offset_array_size = atoi(argv[1]);
    unsigned int seed = (unsigned int)atoi(argv[2]);
    int min_random = atoi(argv[3]);
    int max_random = atoi(argv[4]);

    allocate_and_initialize(offset_array_size, seed, min_random, max_random);

    // Example of accessing a record in a thread-safe manner
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        size_t index = i;
        pthread_create(&threads[i], NULL, (void *(*)(void *))get_record, &index);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_resources();
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management**: The function calculates the memory requirements and ensures they do not exceed specified limits.
- **Error Handling**: Checks for allocation failures and invalid inputs.
- **Thread Safety**: Uses a mutex to protect access to shared resources.
- **Random Initialization**: Allows users to specify seed and range for reproducibility.
- **Custom Memory Pool**: Reduces fragmentation by using a single block of memory.']

