typedef struct {
    int value;
} Record;

typedef struct {
    long *data;
    size_t size;
} Offset;

typedef struct {
    int *keys;
    size_t size;
} Keys;

typedef struct {
    Record *records;
    size_t size;
} Records;

#define TIMEOUT_MS 5000

// Function to log errors
void log_error(const char *message) {
    FILE *log_file = fopen(ERROR_LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

int allocate_and_initialize(int n, int m, Offset *offset_out, Keys *keys_out, Records *records_out) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Timeout mechanism
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    long timeout_nsec = TIMEOUT_MS * 1000000L;

    if (n < 0 || m < 0) {
        log_error("Invalid input parameters: n and m must be non-negative.");
        return -1; // Error code for invalid input
    }

    size_t offset_size = sizeof(long) * n;
    size_t keys_size = sizeof(int) * (n + m);
    size_t records_size = sizeof(Record) * n;

    if ((offset_size + keys_size + records_size) > MAX_MEMORY_LIMIT) {
        log_error("Memory allocation exceeds the predefined limit.");
        return -2; // Error code for memory limit exceeded
    }

    pthread_mutex_lock(&lock);

    offset_out->data = (long *)malloc(offset_size);
    keys_out->keys = (int *)malloc(keys_size);
    records_out->records = (Record *)malloc(records_size);

    if (!offset_out->data || !keys_out->keys || !records_out->records) {
        log_error("Memory allocation failed.");
        free(offset_out->data);
        free(keys_out->keys);
        free(records_out->records);
        pthread_mutex_unlock(&lock);
        return -3; // Error code for memory allocation failure
    }

    offset_out->size = n;
    keys_out->size = n + m;
    records_out->size = n;

    // Initialize the arrays
    for (int i = 0; i < n; ++i) {
        if (pthread_mutex_lock(&lock)) {
            break;
        }
        clock_gettime(CLOCK_REALTIME, &current_time);
        long elapsed_nsec = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + 
                            (current_time.tv_nsec - start_time.tv_nsec);

        if (elapsed_nsec > timeout_nsec) {
            log_error("Function execution exceeded the time limit.");
            pthread_mutex_unlock(&lock);
            return -4; // Error code for timeout
        }

        offset_out->data[i] = i;
    }

    for (int i = 0; i < n + m; ++i) {
        if (pthread_mutex_lock(&lock)) {
            break;
        }
        clock_gettime(CLOCK_REALTIME, &current_time);
        long elapsed_nsec = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + 
                            (current_time.tv_nsec - start_time.tv_nsec);

        if (elapsed_nsec > timeout_nsec) {
            log_error("Function execution exceeded the time limit.");
            pthread_mutex_unlock(&lock);
            return -4; // Error code for timeout
        }

        keys_out->keys[i] = i;
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        if (pthread_mutex_lock(&lock)) {
            break;
        }
        clock_gettime(CLOCK_REALTIME, &current_time);
        long elapsed_nsec = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + 
                            (current_time.tv_nsec - start_time.tv_nsec);

        if (elapsed_nsec > timeout_nsec) {
            log_error("Function execution exceeded the time limit.");
            pthread_mutex_unlock(&lock);
            return -4; // Error code for timeout
        }

        records_out->records[i].value = rand() % 1001;
    }

    pthread_mutex_unlock(&lock);

    return 0; // Success
}

void free_resources(Offset *offset, Keys *keys, Records *records) {
    if (offset->data != NULL) {
        free(offset->data);
        offset->data = NULL;
    }
    if (keys->keys != NULL) {
        free(keys->keys);
        keys->keys = NULL;
    }
    if (records->records != NULL) {
        free(records->records);
        records->records = NULL;
    }
}
