// Function to generate random numbers with fallback
int safe_rand(void) {
    static unsigned int seed_initialized = 0;
    if (!seed_initialized) {
        // Attempt to initialize the seed using an external source or fallback
        srand((unsigned int)time(NULL));
        seed_initialized = 1; // Ensure we only initialize once
    }
    return rand() % 1001; // Return a random number between 0 and 1000
}

// Function to manage memory allocation for offset, keys, and records
int manage_memory_allocation(size_t n, size_t m) {
    if (n < 0 || m < 0) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        return -1; // Error code for invalid input
    }

    Offset offset;
    Keys keys;
    Records records;

    // Allocate memory for structures
    offset.data = malloc(n * sizeof(long));
    if (!offset.data) {
        perror("Failed to allocate memory for offset");
        return -2;
    }

    keys.data = malloc((n + m) * sizeof(int));
    if (!keys.data) {
        free(offset.data);
        perror("Failed to allocate memory for keys");
        return -3;
    }

    records.data = malloc(n * sizeof(Record));
    if (!records.data) {
        free(offset.data);
        free(keys.data);
        perror("Failed to allocate memory for records");
        return -4;
    }

    // Initialize offset array with sequential values
    for (size_t i = 0; i < n; ++i) {
        offset.data[i] = i;
    }

    // Initialize keys array with unique values from 0 to n + m - 1
    for (size_t i = 0; i < n + m; ++i) {
        keys.data[i] = i;
    }

    // Initialize records with random values between 0 and 1000
    for (size_t i = 0; i < n; ++i) {
        records.data[i].value = safe_rand();
    }

    printf("Memory allocation and initialization completed successfully.\n");

    // Free allocated memory
    free(offset.data);
    free(keys.data);
    free(records.data);

    return 0; // Success code
}

int main() {
    size_t n = 10; // Example value for n
    size_t m = 5;  // Example value for m

    int result = manage_memory_allocation(n, m);
    if (result != 0) {
        fprintf(stderr, "Memory allocation failed with error code: %d\n", result);
    }

    return result;
}
