#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Mock definitions for necessary structures, replace these with actual implementations
typedef struct {
    unsigned char dest_mac[6];
    unsigned char src_mac[6];
} MAC_HEADER;

typedef struct {
    MAC_HEADER mac_header;
    unsigned short vlan_tag; // VLAN tag in the network byte order
    int vlan_priority;
    int ip_checksum_enabled;
} NICB;

// Configuration for cryptographic operations
typedef struct {
    int enable_algorithm;
    size_t key_size;
    size_t hash_length;
} CryptoConfig;

#define MAX_NICBS 1000

pthread_mutex_t crypto_lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to generate a random MAC address (not globally unique)
void generate_mac_address(unsigned char mac[6]) {
    srand((unsigned int)time(NULL));
    for(int i = 0; i < 5; ++i) {
        mac[i] = rand() & 0xFF;
    }
    // Set the unicast/multicast bit
    mac[5] = (rand() % 2 == 0) ? 0x02 : 0x03;
}

// Initialize a NICB structure with random MAC addresses and VLAN tag
void initialize_nicb(NICB *nicbs, size_t count, CryptoConfig config) {
    if (!nicbs || count > MAX_NICBS || config.key_size < 128 || config.hash_length < 16) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        generate_mac_address(nicbs[i].mac_header.dest_mac);
        generate_mac_address(nicbs[i].mac_header.src_mac);
        nicbs[i].vlan_tag = htons(rand() % 4096); // Random VLAN ID
        nicbs[i].vlan_priority = rand() % 8;      // Priority value between 0 and 7
        nicbs[i].ip_checksum_enabled = rand() % 2;
    }

    // Validate cryptographic configuration against secure defaults
    if (config.key_size != 128 && config.key_size != 256) {
        fprintf(stderr, "Invalid key size. Supported sizes: 128 or 256 bits.\n");
        return;
    }
}

// Example function to simulate cryptographic operations
void perform_crypto_operations(NICB *nicb) {
    pthread_mutex_lock(&crypto_lock);

    // Simulate cryptographic processing
    printf("Processing NICB with VLAN tag: %hu\n", ntohs(nicb->vlan_tag));

    pthread_mutex_unlock(&crypto_lock);
}

// Main function to demonstrate initialization and processing
int main() {
    NICB nicbs[MAX_NICBS];
    CryptoConfig config = {1, 256, 32}; // Example configuration

    initialize_nicb(nicbs, 100, config);

    for (size_t i = 0; i < 100; ++i) {
        perform_crypto_operations(&nicbs[i]);
    }

    return 0;
}
```

### Explanation:

- **NICB Structure**: Contains MAC header with source and destination MAC addresses, a VLAN tag, priority settings, and an optional IP checksum flag.

