    size_t num_records;
    struct Entry *left, *right;
} Entry;

typedef struct TreeNode {
    Entry* entry;
    struct TreeNode *left, *right;
} TreeNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Utility function to align memory
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL; // Handle allocation failure
    }
    return ptr;
}

// Function to free aligned memory
void aligned_free(void *ptr) {
    free(ptr);
}

// Function to generate a unique alphanumeric identifier
char* generate_identifier() {
    static char id[64];
    srand(time(NULL));
    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (int i = 0; i < sizeof(id) - 1; ++i) {
        id[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    id[sizeof(id) - 1] = '\0';
    return id;
}

// Function to create a new value
Value* create_value(double numeric, const char *char_string, void *metadata) {
    Value *value = aligned_alloc(ALIGNMENT, sizeof(Value));
    if (!value) {
        fprintf(stderr, "Memory allocation failed for Value\n");
        return NULL;
    }

    value->numeric = numeric;
    size_t len = strlen(char_string) + 1;
    value->char_string = aligned_alloc(ALIGNMENT, len);
    if (!value->char_string) {
        fprintf(stderr, "Memory allocation failed for char string in Value\n");
        aligned_free(value);
        return NULL;
    }
    strncpy(value->char_string, char_string, len);

    // Assume metadata is either a long or another value pointer
    if (metadata == NULL) {
        value->metadata.metadata_long = rand(); // Example default
    } else if (sizeof(metadata) == sizeof(long)) {
        memcpy(&value->metadata.metadata_long, metadata, sizeof(long));
    } else {
        value->metadata.metadata_value_ptr = (Value*)metadata;
    }

    return value;
}

// Recursive function to populate an entry with values
void populate_entry(Entry *entry, double base_numeric) {
    for (size_t i = 0; i < MAX_VALUES; ++i) {
        // Example: Derive numeric from weighted average
        double weighted_avg = base_numeric + ((double)(rand() % 100)) / 100.0;
        entry->values[i] = create_value(weighted_avg, "example", NULL);
    }
}

// Function to initialize a record with unique identifier and timestamp
Record* create_record() {
    Record *record = aligned_alloc(ALIGNMENT, sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed for Record\n");
        return NULL;
    }

    record->timestamp = time(NULL);
    strcpy(record->identifier, generate_identifier());

    // Placeholder metadata
    record->metadata = NULL;

    return record;
}

// Function to create a new entry
Entry* create_entry(const char *key) {
    Entry *entry = aligned_alloc(ALIGNMENT, sizeof(Entry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed for Entry\n");
        return NULL;
    }

    size_t len = strlen(key) + 1;
    entry->key = aligned_alloc(ALIGNMENT, len);
    if (!entry->key) {
        fprintf(stderr, "Memory allocation failed for key in Entry\n");
        aligned_free(entry);
        return NULL;
    }
    strncpy(entry->key, key, len);

    entry->timestamp = time(NULL);
    entry->status = 0;
    entry->num_values = 0;
    entry->num_records = 0;

    // Initialize records array
    entry->records = aligned_alloc(ALIGNMENT, sizeof(Record*) * MAX_VALUES);
    if (!entry->records) {
        fprintf(stderr, "Memory allocation failed for records in Entry\n");
        aligned_free(entry->key);
        aligned_free(entry);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    // Populate values and records
    populate_entry(entry, 0.0); // Example base numeric
    for (size_t i = 0; i < MAX_VALUES / 2; ++i) { // Fewer records than values
        entry->records[i] = create_record();
    }
    pthread_mutex_unlock(&lock);

    entry->left = entry->right = NULL;
    return entry;
}

// Function to insert a new entry into the binary search tree
TreeNode* insert_tree_node(TreeNode *node, Entry *entry) {
    if (!node) {
        TreeNode *new_node = aligned_alloc(ALIGNMENT, sizeof(TreeNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for TreeNode\n");
            return NULL;
        }
        new_node->entry = entry;
        new_node->left = new_node->right = NULL;
        return new_node;
    }

    int cmp = strcmp(entry->key, node->entry->key);
    if (cmp < 0) {
        node->left = insert_tree_node(node->left, entry);
    } else if (cmp > 0) {
        node->right = insert_tree_node(node->right, entry);
    }
    return node;
}

// Function to serialize the tree
void serialize_tree(TreeNode *node, FILE *file) {
    if (!node) return;

    // Serialize entry
    fwrite(&node->entry->timestamp, sizeof(time_t), 1, file);
    size_t key_len = strlen(node->entry->key) + 1;
    fwrite(&key_len, sizeof(size_t), 1, file);
    fwrite(node->entry->key, sizeof(char), key_len, file);

    // Serialize values and records
    for (size_t i = 0; i < MAX_VALUES; ++i) {
        if (!node->entry->values[i]) continue;
        double numeric = node->entry->values[i]->numeric;
        fwrite(&numeric, sizeof(double), 1, file);
        size_t str_len = strlen(node->entry->values[i]->char_string) + 1;
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(node->entry->values[i]->char_string, sizeof(char), str_len, file);
    }

    // Recursively serialize left and right subtrees
    serialize_tree(node->left, file);
    serialize_tree(node->right, file);
}

// Function to deserialize the tree
TreeNode* deserialize_tree(FILE *file) {
    time_t timestamp;
    fread(&timestamp, sizeof(time_t), 1, file);

    size_t key_len;
    fread(&key_len, sizeof(size_t), 1, file);
    char *key = aligned_alloc(ALIGNMENT, key_len);
    fread(key, sizeof(char), key_len, file);

    Entry *entry = create_entry(key);
    if (!entry) return NULL;

    entry->timestamp = timestamp;

    // Deserialize values
    for (size_t i = 0; i < MAX_VALUES; ++i) {
        double numeric;
        fread(&numeric, sizeof(double), 1, file);

        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        char *char_string = aligned_alloc(ALIGNMENT, str_len);
        fread(char_string, sizeof(char), str_len, file);

        entry->values[i] = create_value(numeric, char_string, NULL);
        aligned_free(char_string);
    }

    // Recursively deserialize left and right subtrees
    TreeNode *left_child = deserialize_tree(file);
    TreeNode *right_child = deserialize_tree(file);

    TreeNode *node = aligned_alloc(ALIGNMENT, sizeof(TreeNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for TreeNode\n");
        return NULL;
    }
    node->entry = entry;
    node->left = left_child;
    node->right = right_child;

    return node;
}

int main() {
    // Example usage
    Entry *root_entry = create_entry("root");
    if (!root_entry) {
        fprintf(stderr, "Failed to create root entry\n");
        return 1;
    }

    TreeNode *root_node = insert_tree_node(NULL, root_entry);

    FILE *file = fopen("tree_data.bin", "wb");
    if (file) {
        serialize_tree(root_node, file);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for writing\n");
    }

    file = fopen("tree_data.bin", "rb");
    if (file) {
        TreeNode *loaded_tree = deserialize_tree(file);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open file for reading\n");
    }

    // Cleanup
    aligned_free(root_entry->key);
    aligned_free(root_entry);

    return 0;
}
