#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

// Define the record structure
typedef struct {
    int value;
} record;

// Function prototypes
void manageMemory(long *offsets, int *keys, record **records, size_t numKeys, int maxRecords, size_t maxSizeThreshold);
int readInitialKeysFromFile(const char *filename, int **keys, size_t *numKeys);
void processAndWriteResultsToFile(const char *outputFile, const int *keys, const record *records, size_t numRecords);

// Memory management function
void manageMemory(long *offsets, int *keys, record **records, size_t numKeys, int maxRecords, size_t maxSizeThreshold) {
    // Calculate total memory usage and validate against threshold
    size_t longSize = sizeof(long);
    size_t intSize = sizeof(int);
    size_t recordSize = sizeof(record);

    size_t requiredMemory = (longSize * numKeys) + (intSize * numKeys) + (recordSize * maxRecords);

    if (requiredMemory > maxSizeThreshold) {
        fprintf(stderr, "Error: Required memory exceeds the maximum threshold.\n");
        exit(EXIT_FAILURE);
    }

    // Dynamic allocation
    offsets = (long *)malloc(longSize * numKeys);
    keys = (int *)malloc(intSize * numKeys);

    if (!offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets); // Only free if non-NULL
        free(keys); // Only free if non-NULL
        exit(EXIT_FAILURE);
    }

    *records = (record *)malloc(recordSize * maxRecords);

    if (!(*records)) {
        fprintf(stderr, "Error: Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    // Populate records with random values within a specified range
    for (int i = 0; i < maxRecords; ++i) {
        (*records)[i].value = rand() % (INT_MAX - INT_MIN + 1) + INT_MIN;
    }
}

// Function to read initial key values from a configuration file
int readInitialKeysFromFile(const char *filename, int **keys, size_t *numKeys) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    // Assuming the number of keys is known and stored in numKeys
    fscanf(file, "%zu", numKeys);

    *keys = (int *)malloc(sizeof(int) * (*numKeys));
    for (size_t i = 0; i < *numKeys; ++i) {
        if (fscanf(file, "%d", &(*keys)[i]) != 1) {
            fprintf(stderr, "Error reading keys from file.\n");
            free(*keys);
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0; // Success
}

// Function to process and write results back to disk
void processAndWriteResultsToFile(const char *outputFile, const int *keys, const record *records, size_t numRecords) {
    FILE *file = fopen(outputFile, "w");
    if (!file) {
        perror("Error opening output file");
        return;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        fprintf(file, "Key: %d, Record Value: %d\n", keys[i], records[i].value);
    }

    fclose(file);
}

// Example usage of the function with command-line argument support
int main(int argc, char *argv[]) {
    const char *configFile = "config.txt";
    const char *outputFile = "output.txt";
    size_t numKeys;
    int *keys;

    // Read initial keys from file
    if (readInitialKeysFromFile(configFile, &keys, &numKeys) != 0) {
        return EXIT_FAILURE;
    }

    long *offsets = NULL;
    record *records = NULL;
    int maxRecords = argc > 1 ? atoi(argv[1]) : 100; // Default to 100 if no argument provided
    size_t maxSizeThreshold = 1024 * 1024; // Example maximum threshold of 1MB

    manageMemory(offsets, keys, &records, numKeys, maxRecords, maxSizeThreshold);

    processAndWriteResultsToFile(outputFile, keys, records, maxRecords);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
