#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include "external_logging_library.h" // Placeholder for external logging library

#define LOG_INTERVAL 5 // Example log interval in seconds

typedef struct metadata {
    int value;
} Metadata;

typedef struct node {
    int data;
    Metadata *metadata_ptr;
} Node;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t current_nodes_count = 0;
static size_t max_nodes;
static size_t max_metadata;
static Node **nodes_array;
static Metadata *metadata_array;
static time_t last_log_time = 0;

void log_memory_usage() {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("memory_usage.log", "a");
        if (!log_file) {
            external_log_error("Failed to open memory usage log file.");
            return;
        }
    }

    time_t now = time(NULL);
    if (difftime(now, last_log_time) >= LOG_INTERVAL) {
        fprintf(log_file, "Memory usage: %zu nodes allocated\n", current_nodes_count);
        fflush(log_file); // Ensure the logs are written immediately
        last_log_time = now;
    }
}

void initialize_metadata() {
    for (size_t i = 0; i < max_metadata; ++i) {
        metadata_array[i].value = (int)i;
    }
}

int generate_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void manage_memory(size_t new_nodes_count, size_t new_max_nodes, size_t new_max_metadata) {
    pthread_mutex_lock(&lock);

    if (new_nodes_count > new_max_nodes) {
        external_log_error("Node count exceeds maximum allowed nodes.");
        pthread_mutex_unlock(&lock);
        return;
    }

    if (!nodes_array) {
        max_nodes = new_max_nodes;
        metadata_array = malloc(new_max_metadata * sizeof(Metadata));
        if (!metadata_array) {
            external_log_error("Failed to allocate memory for metadata array.");
            pthread_mutex_unlock(&lock);
            return;
        }
        initialize_metadata();
        nodes_array = calloc(max_nodes, sizeof(Node*));
    } else if (new_max_nodes > max_nodes) {
        Node **temp = realloc(nodes_array, new_max_nodes * sizeof(Node*));
        if (!temp) {
            external_log_error("Failed to reallocate memory for node array.");
            pthread_mutex_unlock(&lock);
            return;
        }
        nodes_array = temp;
        memset((char *)nodes_array + current_nodes_count * sizeof(Node*), 0, (new_max_nodes - current_nodes_count) * sizeof(Node*));
        max_nodes = new_max_metadata;
    }

    if (!metadata_array || new_max_metadata != max_metadata) {
        free(metadata_array);
        metadata_array = malloc(new_max_metadata * sizeof(Metadata));
        if (!metadata_array) {
            external_log_error("Failed to allocate memory for metadata array.");
            pthread_mutex_unlock(&lock);
            return;
        }
        initialize_metadata();
    }

    for (size_t i = current_nodes_count; i < new_nodes_count && i < max_nodes; ++i) {
        nodes_array[i] = malloc(sizeof(Node));
        if (!nodes_array[i]) {
            external_log_error("Failed to allocate memory for a node.");
            pthread_mutex_unlock(&lock);
            return;
        }
        nodes_array[i]->data = generate_random_int(0, INT_MAX);
        nodes_array[i]->metadata_ptr = &metadata_array[rand() % max_metadata];
    }

    current_nodes_count = new_nodes_count;

    log_memory_usage();

    pthread_mutex_unlock(&lock);
}

void free_resources() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < current_nodes_count; ++i) {
        if (nodes_array[i]) {
            free(nodes_array[i]);
        }
    }

    free(nodes_array);
    nodes_array = NULL;

    free(metadata_array);
    metadata_array = NULL;

    pthread_mutex_unlock(&lock);
}

int main() {
    srand((unsigned int)time(NULL));
    manage_memory(10, 20, 5); // Example usage
    free_resources();
    return 0;
}
