['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000
#define MAX_MESSAGE_LENGTH 256

typedef struct {
    uint64_t timestamp;
    int priority;
    char message[MAX_MESSAGE_LENGTH + 1];
} EventLogEntry;

typedef struct {
    EventLogEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventLog;

uint64_t get_monotonic_timestamp() {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        return (uint64_t)(ts.tv_sec * 1000000ULL + ts.tv_nsec / 1000);
    }
    return 0;
}

int assign_priority(EventLog *log) {
    static int last_priority = -1;
    pthread_mutex_lock(&log->lock);
    do {
        last_priority++;
        if (last_priority >= MAX_EVENTS) {
            last_priority = 0;
        }
    } while (find_priority(log, last_priority));
    pthread_mutex_unlock(&log->lock);
    return last_priority;
}

int find_priority(EventLog *log, int priority) {
    for (size_t i = 0; i < log->count; ++i) {
        if (log->entries[i].priority == priority) {
            return 1;
        }
    }
    return 0;
}

void init_event_log(EventLog *log) {
    log->entries = malloc(MAX_EVENTS * sizeof(EventLogEntry));
    if (!log->entries) {
        perror("Failed to allocate memory for event log");
        exit(EXIT_FAILURE);
    }
    log->count = 0;
    log->capacity = MAX_EVENTS;
    pthread_mutex_init(&log->lock, NULL);
}

void add_event(EventLog *log, const char *message) {
    pthread_mutex_lock(&log->lock);

    if (log->count >= log->capacity) {
        fprintf(stderr, "Event log capacity exceeded\n");
        pthread_mutex_unlock(&log->lock);
        return;
    }

    EventLogEntry *entry = &log->entries[log->count++];
    entry->timestamp = get_monotonic_timestamp();
    entry->priority = assign_priority(log);

    strncpy(entry->message, message, MAX_MESSAGE_LENGTH);
    entry->message[MAX_MESSAGE_LENGTH] = '\0';

    pthread_mutex_unlock(&log->lock);
}

void destroy_event_log(EventLog *log) {
    free(log->entries);
    pthread_mutex_destroy(&log->lock);
}

int main() {
    EventLog log;
    init_event_log(&log);

    add_event(&log, "First event");
    add_event(&log, "Second event");

    for (size_t i = 0; i < log.count; ++i) {
        printf("Timestamp: %llu, Priority: %d, Message: %s\n",
               log.entries[i].timestamp,
               log.entries[i].priority,
               log.entries[i].message);
    }

    destroy_event_log(&log);
    return 0;
}
