#include <stdio.h>
#include <time.h>

#define MEMORY_LIMIT (1 * 1024 * 1024) // 1 MB limit
#define MAX_RECORDS 10000

pthread_mutex_t dm_lock = PTHREAD_MUTEX_INITIALIZER;

DataManager* create_data_manager(size_t record_count) {
    DataManager* dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->long_arr = calloc(record_count, sizeof(long *));
    dm->double_arr = calloc(record_count, sizeof(double));
    // Allocate memory for struct_array and record_array
    size_t struct_size = record_count * sizeof(struct { char string[128]; unsigned int num; });
    dm->struct_array = malloc(struct_size);
    size_t record_size = record_count * sizeof(Record);
    dm->record_array = malloc(record_size);

    return dm;
}

void destroy_data_manager(DataManager* dm) {
    if (!dm) return;

    free(dm->long_arr);
    free(dm->double_arr);
    free(dm->struct_array);
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (dm->record_array[i].item_ptr) free(dm->record_array[i].item_ptr);
    }
    free(dm->record_array);
    free(dm);
}

int initialize_data_manager(DataManager* dm) {
    pthread_mutex_lock(&dm_lock);

    srand(time(NULL));
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        dm->long_arr[i] = malloc(sizeof(long));
        *dm->long_arr[i] = i;

        dm->double_arr[i] = (double)i;

        snprintf(dm->struct_array[i].string, sizeof(dm->struct_array[i].string), "PredefinedString_%zu", i);
        dm->struct_array[i].num = rand() % 1000 + 1;

        dm->record_array[i].value = rand() % 100 + 1;
        snprintf(dm->record_array[i].id, sizeof(dm->record_array[i].id), "ID_%zu_Timestamp", i);

        dm->record_array[i].item_ptr = malloc(sizeof(Item));
        if (!dm->record_array[i].item_ptr) {
            pthread_mutex_unlock(&dm_lock);
            return -1;
        }
        dm->record_array[i].item_ptr->size = sizeof(double);
        dm->record_array[i].item_ptr->dval = (double)i;
    }

    pthread_mutex_unlock(&dm_lock);
    return 0;
}

void access_record(DataManager* dm, size_t index) {
    pthread_mutex_lock(&dm_lock);

    // Simulate accessing the record
    printf("Accessing Record %zu\n", index);

    pthread_mutex_unlock(&dm_lock);
}

void log_memory_usage(DataManager* dm) {
    pthread_mutex_lock(&dm_lock);

    printf("Logging Memory Usage...\n");

    pthread_mutex_unlock(&dm_lock);
}
