// File: DataConnection.java

import java.io.IOException;
import java.nio.channels.SocketChannel;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DataConnection {

    private SocketChannel channel;
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void connect(String address, int port) {
        try {
            channel = SocketChannel.open();
            channel.configureBlocking(false);
            channel.connect(java.net.InetSocketAddress.createUnresolved(address, port));

            scheduler.scheduleWithFixedDelay(this::checkConnection, 0, 5, TimeUnit.SECONDS);

        } catch (IOException e) {
            handleNetworkFailure(e);
        }
    }

    private void checkConnection() {
        try {
            if (!channel.finishConnect()) {
                reconnect();
            }
        } catch (IOException e) {
            handleNetworkFailure(e);
        }
    }

    private void reconnect() {
        try {
            channel.close();
            connect(channel.getLocalAddress().getHostName(), 12345); // Example port
        } catch (IOException e) {
            handleNetworkFailure(e);
        }
    }

    private void handleNetworkFailure(Exception e) {
        System.err.println("Network failure: " + e.getMessage());
        sendMessageToMessagingSystem("Connection closed");
        scheduleReconnect();
    }

    private void scheduleReconnect() {
        scheduler.schedule(this::reconnect, 10, TimeUnit.SECONDS); // Example grace period
    }

    private void sendMessageToMessagingSystem(String message) {
        // Implement messaging system integration here
    }
}
