#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <math.h>

#define ALIGNMENT 32
#define N 10

typedef struct {
    int key;
    char value[256];
} item;

typedef struct node {
    double value;
    int id;
    struct item *items;
    size_t items_count;
    struct node *next;
} node;

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

double generate_double_value(int min, int max) {
    return (double)(rand() % (max - min + 1) + min) / RAND_MAX * M_PI; // Example function
}

void* aligned_alloc(size_t size) {
    void* ptr = NULL;
#if defined(_POSIX_C_SOURCE)
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        return NULL;
    }
#elif defined(_MSC_VER)
    ptr = _aligned_malloc(size, ALIGNMENT);
#endif
    return ptr;
}

void free_aligned_alloc(void *ptr) {
#if defined(_MSC_VER)
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

node* create_node(int id, int min, int max, size_t item_count) {
    node* new_node = aligned_alloc(sizeof(node));
    if (!new_node) return NULL;

    new_node->value = generate_double_value(min, max);
    new_node->id = id;
    new_node->items = aligned_alloc(item_count * sizeof(struct item));
    if (!new_node->items) {
        free_aligned_alloc(new_node);
        return NULL;
    }
    new_node->items_count = item_count;
    new_node->next = NULL;

    for (size_t i = 0; i < item_count; ++i) {
        new_node->items[i].key = rand() % 100; // Example key
        snprintf(new_node->items[i].value, sizeof(new_node->items[i].value), "Item_%zu", i);
    }

    return new_node;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_array(size_t n) {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* array = aligned_alloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        uint16_t rnti = (uint16_t)(rand() % (0x0FFF - 0x0001 + 1) + 0x0001); // Unique RNTI
        array[i].RX_UE_INFORMATION_TAG = rand(); // Example tag generation
        array[i].RNTI = rnti;
        array[i].CRCFLAG = i % 2; // Balanced distribution of CRCFLAG

        // Validate RX_UE_INFORMATION_TAG and RNTI (example logic)
        if (array[i].RX_UE_INFORMATION_TAG == 0 || array[i].RNTI == 0) {
            fprintf(stderr, "Invalid entry at index %zu\n", i);
            free_aligned_alloc(array);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void print_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, int fd) {
    if (!array) return;

    for (size_t i = 0; i < n; ++i) {
        dprintf(fd, "RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
                array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRCFLAG);
    }
}

void free_node(node* head) {
    while (head) {
        node* temp = head;
        head = head->next;
        if (temp->items) {
            free_aligned_alloc(temp->items);
        }
        free_aligned_alloc(temp);
    }
}

void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (!array) return;
    free_aligned_alloc(array);
}
