#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/pem.h>
#include <openssl/rsa.h>

typedef struct {
    char name[256];
    unsigned int permissions;
    time_t last_access;
    time_t last_modification;
    time_t last_change;
} FSBC;

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
    char audit_log[512];
    char metadata_tag[128];
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t fsbc_count = 0;
FSBC *fsbcs = NULL;

void init_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_alias("md5", "md5");
    EVP_add_cipher(EVP_camellia_128_cbc());
    EVP_add_digest(EVP_sha256());
    EVP_add_digest_alias("sha256", "SHA256");
}

void resize_fsbc_array(size_t new_size) {
    pthread_mutex_lock(&mutex);
    FSBC *new_fsbcs = realloc(fsbcs, new_size * sizeof(FSBC));
    if (!new_fsbcs) {
        perror("Failed to resize FSBC array");
        exit(EXIT_FAILURE);
    }
    fsbcs = new_fsbcs;
    memset(fsbcs + fsbc_count, 0, (new_size - fsbc_count) * sizeof(FSBC));
    fsbc_count = new_size;
    pthread_mutex_unlock(&mutex);
}

void initialize_fsbc(size_t initial_size) {
    resize_fsbc_array(initial_size);
}

void add_fsbc(const char *name, unsigned int permissions) {
    pthread_mutex_lock(&mutex);
    if (fsbc_count >= INITIAL_SIZE) {
        resize_fsbc_array(fsbc_count * 2);
    }
    FSBC *new_fsbc = &fsbcs[fsbc_count++];
    strncpy(new_fsbc->name, name, sizeof(new_fsbc->name) - 1);
    new_fsbc->permissions = permissions;
    new_fsbc->last_access = time(NULL);
    new_fsbc->last_modification = time(NULL);
    new_fsbc->last_change = time(NULL);
    pthread_mutex_unlock(&mutex);
}

void log_memory_usage() {
    printf("Memory usage: %zu FSBC structures\n", fsbc_count);
}

int main() {
    init_crypto();
    initialize_fsbc(10);

    add_fsbc("file1.txt", 0755);
    add_fsbc("dir1", 0755);

    log_memory_usage();

    free(fsbcs);
    return 0;
}
```

