        thread_args[thread_index].input_filename = input_filenames[i];
        thread_args[thread_index].output_filename = output_filenames[i];

        if (pthread_create(&threads[thread_index], NULL, process_file, &thread_args[thread_index]) != 0) {
            perror("Failed to create thread");
            // Handle error
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Thread function to process each file
void* process_file(void* arg) {
    struct thread_arg* t_arg = (struct thread_arg*)arg;
    char* input_filename = t_arg->input_filename;
    char* output_filename = t_arg->output_filename;

    // Convert JPEG to PDF
    convert_jpeg_to_pdf(input_filename, output_filename);

    // Simulate system load metrics
