    size_t num_pdus = 10; // Example number of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    if (allocate_aligned_memory(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T), (void**)&pdus) != 0) {
        fprintf(stderr, "Memory allocation failed for PDUs\n");
        return NULL;
    }

    int validation_failures = 0;
    for (size_t i = 0; i < num_pdus && validation_failures < MAX_VALIDATION_FAILURES; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand(); // Example tag
        pdus[i].RNTI = rand(); // Example RNTI

        set_crc_flag(&pdus[i], crc_flag_min, crc_flag_max);
    }

    free(pdus);

    return NULL;
}

// Allocate memory with specific alignment
int allocate_aligned_memory(size_t size, void** ptr) {
    void* raw_ptr = malloc(size + ALIGNMENT - 1);
    if (!raw_ptr) return -1;

    // Align the pointer
    uintptr_t aligned_ptr = (uintptr_t(raw_ptr) + ALIGNMENT - 1) & ~(ALIGNMENT - 1);
    *ptr = (void*)aligned_ptr;
    memset(*ptr, 0, size);

    free((void*)((char*)aligned_ptr - ((uintptr_t(raw_ptr) + ALIGNMENT - 1) & ~(ALIGNMENT - 1))));

    return 0;
}

// Set CRC flag with validation
void set_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu, int min, int max) {
    do {
        pdu->CRC_INDICATION_REL8_TAG = rand() % (max - min + 1) + min;
    } while (pdu->CRC_INDICATION_REL8_TAG < min || pdu->CRC_INDICATION_REL8_TAG > max);
}

// Adjust CRC range based on system load
void adjust_crc_range(int* min, int* max, float cpu_load, float mem_usage, float io_wait) {
    // Example heuristic: reduce range if high CPU or memory usage
    if (cpu_load > 0.7 || mem_usage > 0.7) {
        *max = (*max / 2) + *min;
    } else {
        *max = DEFAULT_CRC_RANGE_MAX;
    }
}

