void initializeScheduler(struct ProcessHashTable* pht, struct UsageHashTable* uht) {
    pht->size = MAX_PROCESSES;
    pht->ids = malloc(sizeof(int) * pht->size);
    pht->limits = malloc(sizeof(struct ResourceLimits) * pht->size);

    uht->size = MAX_PROCESSES;
    uht->ids = malloc(sizeof(int) * uht->size);
    uht->usage = malloc(sizeof(struct ResourceUsage) * uht->size);

    // Initialize locks
    pthread_rwlock_init(&pht->rwlock, NULL);
}

// Dynamically adjust resources based on real-time monitoring
void adjustResourcesDynamically(struct ProcessHashTable* pht, struct UsageHashTable* uht) {
    struct timeval start, end;
    gettimeofday(&start, NULL);

    // Dummy adjustment logic for illustration purposes
