Record* create_record(int key, long offset) {
    Record* new_record = (Record*)custom_alloc(sizeof(Record));
    if (!new_record) return NULL;

    pthread_mutex_init(&new_record->lock, NULL);
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = NULL;

    return new_record;
}

void insert_record(int key, long offset) {
    Record* new_record = create_record(key, offset);
    if (!new_record) return;

    pthread_mutex_lock(&record_list.list_lock);
    new_record->next = record_list.head;
    record_list.head = new_record;
    record_list.size++;
    pthread_mutex_unlock(&record_list.list_lock);
}

Record* find_record(int key) {
    Record* current = record_list.head;
    while (current) {
        if (current->key == key) return current;
        current = current->next;
    }
    return NULL;
}

void delete_record(int key) {
    pthread_mutex_lock(&record_list.list_lock);

    Record *prev = NULL, *current = record_list.head;
    while (current && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (prev) prev->next = current->next;
        else record_list.head = current->next;

        pthread_mutex_destroy(&current->lock);
        custom_free(current);
        record_list.size--;
    }

    pthread_mutex_unlock(&record_list.list_lock);
}

