void initialize_memory(double *doubleArray, size_t doubleSize, char **charArray, size_t charSize, data ***dataArray, size_t dataSize) {
    // Allocate memory for arrays
    doubleArray = (double *)malloc(doubleSize * sizeof(double));
    if (!doubleArray) exit(EXIT_FAILURE);

    *charArray = (char *)malloc(charSize * sizeof(char));
    if (!*charArray) exit(EXIT_FAILURE);

    *dataArray = (data **)malloc(dataSize * sizeof(data *));
    if (!*dataArray) exit(EXIT_FAILURE);

    for (size_t i = 0; i < dataSize; ++i) {
        (*dataArray)[i] = (data *)malloc(sizeof(data));
        if (!(*dataArray)[i]) exit(EXIT_FAILURE);

        // Calculate float value within predefined range
        const float minValue = 1.0f, maxValue = 100.0f;
        float calculatedValue = i + 10; // Example constant
        (*dataArray)[i]->value = (calculatedValue < minValue) ? minValue : (calculatedValue > maxValue) ? maxValue : calculatedValue;

        (*dataArray)[i]->number = 0; // Initialize short field
        (*dataArray)[i]->flag = false; // Initialize bool field
    }
}

void free_memory(double *doubleArray, char *charArray, data **dataArray, size_t dataSize) {
    free(doubleArray);
    free(charArray);

    for (size_t i = 0; i < dataSize; ++i) {
        free(dataArray[i]);
    }
    free(dataArray);
}
