public class WebSocketClient {

    private static ExecutorService executor = Executors.newFixedThreadPool(10000);

    @OnOpen
    public void onOpen(Session session) {
        System.out.println("Connected: " + session.getId());
        // Handle connection opened event, e.g., sending a configuration request
    }

    @OnMessage
    public void onMessage(String message, Session session) throws IOException {
        executor.submit(() -> handleMessage(message, session));
    }

    private void handleMessage(String message, Session session) {
        try {
            System.out.println("Received: " + message);
            // Process received message and respond if needed
        } catch (Exception e) {
            System.err.println("Error handling message: " + e.getMessage());
        }
    }

    @OnClose
    public void onClose(Session session, CloseReason closeReason) {
        System.out.println("Closed: " + session.getId() + ", Reason: " + closeReason);
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        System.err.println("Error on Session " + session.getId() + ": " + throwable.getMessage());
    }

    public static void main(String[] args) throws Exception {
        WebSocketContainer container = ContainerProvider.getWebSocketContainer();
        URI uri = URI.create("ws://localhost:8080/websocket");
        Session session = container.connectToServer(WebSocketClient.class, uri);

        // Keep the client running
        Thread.sleep(Long.MAX_VALUE);
    }
}
