#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pthread.h>

// Define constants
#define ALIGNMENT 32
#define STRING_LENGTH 10

// Dummy logging function for demonstration purposes
void log_message(const char *message) {
    printf("%s\n", message);
}

// Item structure
typedef struct item {
    int key;
    char string[STRING_LENGTH + 1];
} item_t;

// Node structure
typedef struct node {
    double value;
    item_t *items_head;
    int ref_count;
    pthread_mutex_t lock;
} node_t;

// Custom allocator for memory pool management (simplified version)
void* custom_alloc(size_t size) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        log_message("Memory allocation failed.");
        return NULL;
    }
    return ptr;
}

// Function to generate a random alphanumeric string
char* generate_random_string() {
    const char charset[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";
    char *random_str = malloc(STRING_LENGTH + 1);
    if (random_str == NULL) {
        log_message("Failed to allocate memory for random string.");
        return NULL;
    }

    for (int i = 0; i < STRING_LENGTH; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        random_str[i] = charset[key];
    }

    random_str[STRING_LENGTH] = '\0';
    return random_str;
}

// Function to initialize a node
node_t* init_node(double value) {
    node_t *node = custom_alloc(sizeof(node_t));
    if (node == NULL) return NULL;

    node->value = value;
    node->items_head = NULL;
    node->ref_count = 1;
    pthread_mutex_init(&node->lock, NULL);

    log_message("Node initialized.");
    return node;
}

// Function to initialize an item
item_t* init_item(int key) {
    item_t *item = custom_alloc(sizeof(item_t));
    if (item == NULL) return NULL;

    item->key = key;
    char *random_string = generate_random_string();
    if (random_string != NULL) {
        strncpy(item->string, random_string, STRING_LENGTH);
        free(random_string);
    } else {
        free(item);
        return NULL;
    }

    log_message("Item initialized.");
    return item;
}

// Main function to manage nodes
node_t** manage_nodes(size_t num_nodes, int range_min, int range_max) {
    node_t **nodes = custom_alloc(num_nodes * sizeof(node_t*));
    if (nodes == NULL) return NULL;

    srand(time(NULL));

    for (size_t i = 0; i < num_nodes; ++i) {
        int random_int = rand() % (range_max - range_min + 1) + range_min;
        double value = sqrt(random_int);

        node_t *node = init_node(value);
        if (node == NULL) {
            log_message("Failed to initialize node.");
            return NULL; // Cleanup omitted for brevity
        }

        nodes[i] = node;

        pthread_mutex_lock(&node->lock);
        item_t *new_item = init_item(rand());
        if (new_item != NULL) {
            new_item->next = node->items_head;
            node->items_head = new_item;
        }
        pthread_mutex_unlock(&node->lock);

        log_message("Node and items initialized.");
    }

    return nodes;
}

// Function to release a node
void release_node(node_t **node_ptr) {
    if (node_ptr == NULL || *node_ptr == NULL) return;

    pthread_mutex_lock(&(*node_ptr)->lock);
    item_t *current = (*node_ptr)->items_head;
    while (current != NULL) {
        item_t *next_item = current->next;
        free(current);
        current = next_item;
    }

    pthread_mutex_unlock(&(*node_ptr)->lock);

    (*node_ptr)->ref_count--;
    if ((*node_ptr)->ref_count == 0) {
        pthread_mutex_destroy(&(*node_ptr)->lock);
        free(*node_ptr);
        *node_ptr = NULL;
    }
}

// Example usage
int main() {
    size_t num_nodes = 10;
    int range_min = 1, range_max = 100;

    node_t **nodes = manage_nodes(num_nodes, range_min, range_max);
    if (nodes == NULL) {
        log_message("Failed to allocate nodes.");
        return EXIT_FAILURE;
    }

    // Simulate usage
    for (size_t i = 0; i < num_nodes; ++i) {
        release_node(&nodes[i]);
    }

    free(nodes);
    return EXIT_SUCCESS;
}
