#include <pthread.h>

#define SUCCESS 0
#define ERROR_INVALID_SIZE -1
#define ERROR_MEMORY_EXHAUSTION -2

typedef struct {
    long *offset_ptr;
    int *key_ptr;
    int ref_count;
} Record;

typedef struct {
    Record **records;
    long *offsets;
