typedef struct {
    long *used_integers;
    size_t capacity;
    size_t count;
} UniqueIntegerManager;

// Utility functions declarations

long* allocate_array(size_t size, size_t element_size);
int resize_array(void **array, size_t current_capacity, size_t new_capacity, size_t element_size);

UniqueIntegerManager* create_unique_integer_manager(int range_start, int range_end) {
    int range = range_end - range_start + 1;
    UniqueIntegerManager *manager = malloc(sizeof(UniqueIntegerManager));
    if (!manager || range <= 0) return NULL;

    manager->used_integers = calloc(range, sizeof(long));
    if (!manager->used_integers) {
        free(manager);
        return NULL;
    }

    manager->capacity = range;
    manager->count = 0;
    return manager;
}

int get_unique_integer(UniqueIntegerManager *manager, int min, int max) {
    int attempt, num_attempts = (max - min + 1);

    for (attempt = 0; attempt < num_attempts; ++attempt) {
        int candidate = rand() % (max - min + 1) + min;

        if (!manager->used_integers[candidate - min]) { // If not used
            manager->used_integers[candidate - min] = 1;
            manager->count++;
            return candidate;
        }
    }

    return -1; // Failed to find a unique integer within the range
}

void free_unique_integer_manager(UniqueIntegerManager *manager) {
    if (manager) {
        free(manager->used_integers);
        free(manager);
    }
}

// RecordStorage functions declarations

RecordStorage* create_record_storage(size_t initial_capacity, size_t min_offset_size, 
                                     size_t max_offset_size, size_t min_key_size,
                                     size_t max_key_size, int unique_range_start,
                                     int unique_range_end) {

    if (min_offset_size > max_offset_size || min_key_size > max_key_size) return NULL;

    RecordStorage *storage = malloc(sizeof(RecordStorage));
    if (!storage) return NULL;

    storage->record_capacity = initial_capacity;
    storage->offset_size = min_offset_size;
    storage->key_size = min_key_size;
    storage->allocated_offsets = 0;
    storage->allocated_keys = 0;

    pthread_mutex_init(&storage->lock, NULL);

    // Allocate records array
    if (resize_array((void**)&(storage->records), 0, initial_capacity, sizeof(Record*)) != SUCCESS) {
        free(storage);
        return NULL;
    }

    // Allocate offsets and keys arrays
    storage->offsets = allocate_array(max_offset_size, sizeof(long));
    storage->keys = allocate_array(max_key_size, sizeof(int));

    if (!storage->offsets || !storage->keys) {
        free_unique_integer_manager(create_unique_integer_manager(unique_range_start, unique_range_end));
        pthread_mutex_destroy(&storage->lock);
        free(storage);
        return NULL;
    }

    // Initialize records
    for (size_t i = 0; i < initial_capacity; ++i) {
        storage->records[i] = malloc(sizeof(Record));

        if (!storage->records[i]) {
            // Cleanup on failure
            pthread_mutex_destroy(&storage->lock);
            free(storage->offsets);
            free(storage->keys);

            for (size_t j = 0; j < i; ++j) {
                free(storage->records[j]);
            }
            free(storage->records);
            free_unique_integer_manager(create_unique_integer_manager(unique_range_start, unique_range_end));
            free(storage);
            return NULL;
        }

        storage->records[i]->offset_ptr = &(storage->offsets[storage->allocated_offsets++]);
        storage->records[i]->key_ptr = &(storage->keys[storage->allocated_keys++]);
        storage->records[i]->ref_count = 0;

        // Assign unique random integers
        UniqueIntegerManager *unique_manager = create_unique_integer_manager(unique_range_start, unique_range_end);
        int unique_value = get_unique_integer(unique_manager, unique_range_start, unique_range_end);

        if (unique_value == -1) {
            free_unique_integer_manager(unique_manager);
            pthread_mutex_destroy(&storage->lock);
            free(storage->offsets);
            free(storage->keys);

            for (size_t j = 0; j <= i; ++j) {
                free(storage->records[j]);
            }
            free(storage->records);
            free_unique_integer_manager(create_unique_integer_manager(unique_range_start, unique_range_end));
            free(storage);
            return NULL;
        }

        *storage->records[i]->offset_ptr = (long)unique_value;

        // Free the unique manager now that it's no longer needed
        free_unique_integer_manager(unique_manager);
    }

    return storage;
}

void resize_record_storage(RecordStorage *storage, size_t new_capacity) {
    if (resize_array((void**)&(storage->records), storage->record_capacity, new_capacity, sizeof(Record*)) != SUCCESS)
        return;

    storage->record_capacity = new_capacity;
}

size_t add_record(RecordStorage *storage) {
    pthread_mutex_lock(&storage->lock);

    // Resize if necessary
    if (storage->allocated_offsets >= storage->offset_size || 
        storage->allocated_keys >= storage->key_size) {

        size_t new_offset_size = storage->offset_size == 0 ? storage->min_offset_size : storage->offset_size * 2;
        size_t new_key_size = storage->key_size == 0 ? storage->key_size_size : storage->key_size * 2;

        long* new_offsets = allocate_array(new_offset_size, sizeof(long));
        int* new_keys = allocate_array(new_key_size, sizeof(int));

        if (!new_offsets || !new_keys) {
            pthread_mutex_unlock(&storage->lock);
            return ERROR_MEMORY_EXHAUSTION;
        }

        // Copy over existing data
        memcpy(new_offsets, storage->offsets, storage->allocated_offsets * sizeof(long));
        memcpy(new_keys, storage->keys, storage->allocated_keys * sizeof(int));

        free(storage->offsets);
        free(storage->keys);

        storage->offsets = new_offsets;
        storage->keys = new_keys;

        storage->offset_size = new_offset_size;
        storage->key_size = new_key_size;
    }

    Record *new_record = malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&storage->lock);
        return ERROR_MEMORY_EXHAUSTION;
    }

    // Insert new record
    size_t index = storage->record_capacity; 
    resize_array((void**)&(storage->records), storage->record_capacity, storage->record_capacity + 1, sizeof(Record*));
    storage->records[index] = new_record;

    new_record->offset_ptr = &(storage->offsets[storage->allocated_offsets++]);
    new_record->key_ptr = &(storage->keys[storage->allocated_keys++]);
    new_record->ref_count = 0;

    // Assign unique random integers
    UniqueIntegerManager *unique_manager = create_unique_integer_manager(storage->min_unique_range_start, storage->max_unique_range_end);
    int unique_value = get_unique_integer(unique_manager, storage->min_unique_range_start, storage->max_unique_range_end);

    if (unique_value == -1) {
        free(new_record);
        pthread_mutex_unlock(&storage->lock);
        return ERROR_MEMORY_EXHAUSTION;
    }

    *new_record->offset_ptr = (long)unique_value;

    // Free the unique manager now that it's no longer needed
    free_unique_integer_manager(unique_manager);

    pthread_mutex_unlock(&storage->lock);

    return index + 1; // Return total number of records successfully allocated
}

void destroy_record_storage(RecordStorage *storage) {
    if (!storage) return;

    for (size_t i = 0; i < storage->record_capacity; ++i) {
        free(storage->records[i]);
    }

    free(storage->records);
    free(storage->offsets);
    free(storage->keys);

    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

long* allocate_array(size_t size, size_t element_size) {
    return (size == 0) ? NULL : calloc(size, element_size);
}

int resize_array(void **array, size_t current_capacity, size_t new_capacity, size_t element_size) {
    if (new_capacity <= current_capacity) return SUCCESS;

    void *new_array = realloc(*array, new_capacity * element_size);
    if (!new_array && new_capacity > 0) return ERROR_MEMORY_EXHAUSTION;

    *array = new_array;
    return (*array != NULL) ? SUCCESS : ERROR_MEMORY_EXHAUSTION;
}

// Example usage
int main() {
    RecordStorage* storage = create_record_storage(10, 5, 20, 5, 15, 0, 100);

    if (!storage) {
        printf("Failed to initialize record storage\n");
        return -1;
    }

    for (size_t i = 0; i < 12; ++i) { // Attempt to add more records than initial capacity
        size_t total_records = add_record(storage);
        if (total_records == ERROR_MEMORY_EXHAUSTION || total_records == ERROR_INVALID_SIZE) {
            printf("Failed to add record %zu\n", i + 1);
            destroy_record_storage(storage);
            return -1;
        }
    }

    printf("Successfully added %zu records.\n", storage->record_capacity);

    destroy_record_storage(storage);
    return 0;
}
