#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10

typedef struct {
    long *offset;
    int *key;
    int ref_count;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    bool initialized;
} RecordSystem;

void log_event(const char *event, size_t size) {
    clock_t start = clock();
    printf("%s: %zu bytes\n", event, size);
    double time_taken = (double)(clock() - start) / CLOCKS_PER_SEC;
    printf("Time taken: %.6f seconds\n", time_taken);
}

bool is_unique_key(int *keys, size_t count, int key) {
    for (size_t i = 0; i < count; ++i) {
        if (keys[i] == key) return false;
    }
    return true;
}

bool is_unique_value(long *values, size_t count, long value) {
    for (size_t i = 0; i < count; ++i) {
        if (values[i] == value) return false;
    }
    return true;
}

long generate_random_value(size_t min, size_t max, long *existing_values, size_t existing_count) {
    long value;
    do {
        value = rand() % (max - min + 1) + min;
    } while (!is_unique_value(existing_values, existing_count, value));
    return value;
}

void resize_array(void **array, size_t new_capacity) {
    void *new_array = realloc(array, new_capacity * sizeof(*array));
    if (new_array) {
        array = new_array;
    }
}

RecordSystem* initialize_record_system(size_t initial_capacity) {
    RecordSystem *system = malloc(sizeof(RecordSystem));
    system->offsets = NULL;
    system->keys = NULL;
    system->records = NULL;
    system->capacity = 0;
    system->count = 0;
    pthread_mutex_init(&system->lock, NULL);
    system->initialized = false;

    resize_array((void**)&system->offsets, initial_capacity * sizeof(long));
    resize_array((void**)&system->keys, initial_capacity * sizeof(int));
    resize_array((void**)&system->records, initial_capacity * sizeof(Record*));

    for (size_t i = 0; i < initial_capacity; ++i) {
        system->offsets[i] = -1;
        system->keys[i] = -1;
    }

    system->capacity = initial_capacity;
    log_event("Initialized RecordSystem", initial_capacity * sizeof(Record*));
    system->initialized = true;

    return system;
}

void destroy_record_system(RecordSystem *system) {
    if (!system || !system->initialized) return;

    for (size_t i = 0; i < system->count; ++i) {
        free(system->records[i]);
    }
    free(system->offsets);
    free(system->keys);
    free(system->records);

    pthread_mutex_destroy(&system->lock);
    log_event("Destroyed RecordSystem", 0);
}

bool insert_record(RecordSystem *system, long offset, int key, size_t data_range_min, size_t data_range_max) {
    if (!system || !system->initialized || data_range_min >= data_range_max) return false;

    pthread_mutex_lock(&system->lock);

    if (system->count == system->capacity) {
        size_t new_capacity = system->capacity * 2;
        resize_array((void**)&system->offsets, new_capacity * sizeof(long));
        resize_array((void**)&system->keys, new_capacity * sizeof(int));
        resize_array((void**)&system->records, new_capacity * sizeof(Record*));

        for (size_t i = system->capacity; i < new_capacity; ++i) {
            system->offsets[i] = -1;
            system->keys[i] = -1;
        }

        system->capacity = new_capacity;
    }

    if (!is_unique_key(system->keys, system->count, key)) {
        pthread_mutex_unlock(&system->lock);
        return false;
    }

    Record *record = malloc(sizeof(Record));
    record->offset = &system->offsets[system->count];
    record->key = &system->keys[system->count];
    record->ref_count = 0;

    *record->offset = offset;
    *record->key = key;

    long data_value = generate_random_value(data_range_min, data_range_max, system->offsets, system->count);
    *((long*)record + 1) = data_value; // Storing data after the record struct

    system->records[system->count] = record;
    system->count++;

    pthread_mutex_unlock(&system->lock);

    log_event("Inserted Record", sizeof(Record));
    return true;
}

void merge_record_systems(RecordSystem *dest, RecordSystem *src) {
    if (!dest || !src || !dest->initialized || !src->initialized) return;

    pthread_mutex_lock(&dest->lock);
    pthread_mutex_lock(&src->lock);

    for (size_t i = 0; i < src->count; ++i) {
        insert_record(dest, *(src->records[i]->offset), *(src->records[i]->key), 0, ULONG_MAX);
    }

    pthread_mutex_unlock(&src->lock);
    pthread_mutex_unlock(&dest->lock);

    log_event("Merged RecordSystems", dest->capacity * sizeof(Record*));
}

void compact_records(RecordSystem *system) {
    if (!system || !system->initialized) return;

    pthread_mutex_lock(&system->lock);

    size_t new_capacity = system->count;
    resize_array((void**)&system->offsets, new_capacity * sizeof(long));
    resize_array((void**)&system->keys, new_capacity * sizeof(int));
    resize_array((void**)&system->records, new_capacity * sizeof(Record*));

    for (size_t i = 0; i < system->count; ++i) {
        system->offsets[i] = *(system->records[i]->offset);
        system->keys[i] = *(system->records[i]->key);
    }

    pthread_mutex_unlock(&system->lock);

    log_event("Compacted Records", new_capacity * sizeof(Record*));
}

size_t get_record_count(const RecordSystem *system) {
    return system ? (system->initialized ? system->count : 0) : 0;
}

int main() {
    srand(time(NULL));

    size_t initial_capacity = INITIAL_CAPACITY;
    RecordSystem *system = initialize_record_system(initial_capacity);

    for (size_t i = 0; i < 20; ++i) {
        insert_record(system, rand(), rand(), 1, 100);
    }

    printf("Number of records: %zu\n", get_record_count(system));

    RecordSystem *new_system = initialize_record_system(initial_capacity);

    for (size_t i = 0; i < 10; ++i) {
        insert_record(new_system, rand(), rand(), 1, 100);
    }

    merge_record_systems(system, new_system);

    printf("Number of records after merge: %zu\n", get_record_count(system));

    compact_records(system);

    destroy_record_system(system);
    destroy_record_system(new_system);

    return 0;
}
