#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Function prototypes
int *generateRandomValues(int size, int minValue, int maxValue);
void calculateAverage(Record *records, int arraySize);
long *initializeOffsets(int size, long (*dataRetrieval)(int));
int *initializeKeys(int size, int (*dataRetrieval)(int));
void freeResources(long *offsets, int *keys, Record *records);

// External data retrieval functions (stubs)
long fetchOffsetData(int index) {
    // Simulate a network call or file read
    return (long)index * 1000;
}

int fetchKeyData(int index) {
    // Simulate a network call or file read
    return index * 10;
}

// Function to generate thread-safe random values
int *generateRandomValues(int size, int minValue, int maxValue) {
    if (size <= 0 || minValue > maxValue)
        return NULL;

    int *values = malloc(size * sizeof(int));
    if (!values)
        return NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        values[i] = minValue + rand() % (maxValue - minValue + 1);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return values;
}

// Function to calculate the average of record values
void calculateAverage(Record *records, int arraySize) {
    if (!records || arraySize <= 0)
        return;

    double sum = 0.0;
    for (int i = 0; i < arraySize; ++i) {
        sum += records[i].value;
    }

    double average = arraySize > 0 ? sum / arraySize : 0;
    printf("Average: %.2f\n", average);
}

// Function to initialize offsets with retry logic
long *initializeOffsets(int size, long (*dataRetrieval)(int)) {
    if (size <= 0 || !dataRetrieval)
        return NULL;

    long *offsets = malloc(size * sizeof(long));
    int retries;
    for (int i = 0; i < size; ++i) {
        retries = 3;
        while (retries-- > 0) {
            offsets[i] = dataRetrieval(i);
            if (offsets[i] >= 0)
                break;
            // Exponential backoff
            usleep((4 - retries) * 100000);
        }
    }

    return offsets;
}

// Function to initialize keys with retry logic
int *initializeKeys(int size, int (*dataRetrieval)(int)) {
    if (size <= 0 || !dataRetrieval)
        return NULL;

    int *keys = malloc(size * sizeof(int));
    int retries;
    for (int i = 0; i < size; ++i) {
        retries = 3;
        while (retries-- > 0) {
            keys[i] = dataRetrieval(i);
            if (keys[i] >= 0)
                break;
            // Exponential backoff
            usleep((4 - retries) * 100000);
        }
    }

    return keys;
}

// Function to free allocated resources
void freeResources(long *offsets, int *keys, Record *records) {
    if (offsets)
        free(offsets);

    if (keys)
        free(keys);

    if (records)
        free(records);
}

// Main function demonstrating the use of above functions
int main(int argc, char **argv) {
    int arraySize = 1000;
    int minValue = 1, maxValue = 100;
    long *offsets;
    int *keys;
    Record *records;

    // Initialize random values for records
    if (arraySize <= 0)
        return -1;

    // Allocate and initialize memory for records
    records = malloc(arraySize * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int *values = generateRandomValues(arraySize, minValue, maxValue);
    if (!values) {
        free(records);
        fprintf(stderr, "Memory allocation for random values failed\n");
        return -1;
    }

    // Assign the generated values to records
    for (int i = 0; i < arraySize; ++i)
        records[i].value = values[i];

    free(values);

    // Initialize offsets and keys with external data retrieval
    offsets = initializeOffsets(arraySize, fetchOffsetData);
    keys = initializeKeys(arraySize, fetchKeyData);

    if (!offsets || !keys) {
        fprintf(stderr, "Failed to initialize offsets or keys\n");
        freeResources(offsets, keys, records);
        return -1;
    }

    // Calculate and print the average
    calculateAverage(records, arraySize);

    // Free allocated resources
    freeResources(offsets, keys, records);

    return 0;
}
